window.__BOOK__['p02'].push([{"id":"b17-1","bab":"الجزء 3","sec":"ذكر طويس وأخباره","page":"ج3 ص28","text":"طويس لقب غلب عليه واسمه عيسى بن عبد الله وكنيته أبو عبد المنعم وغيرها المخنثون فجعلوها أبا عبد النعيم وهو مولى بني مخزوم وقد حدثني جحظة عن حماد بن إسحاق عن أبيه عن الواقدي عن ابن أبي الزناد قال سعد بن أبي وقاص كني طويس أبا عبد المنعم أخبرنا الحسين بن يحيى عن حماد عن أبيه عن المسيبي ومحمد بن سلام الجمحي وعن الواقدي عن ابن أبي الزناد وعن المدائني عن زيد بن أسلم عن أبيه وعن ابن الكلبي عن أبيه وعن أبي مسكين قالوا أول من غنى بالعربي بالمدينة طويس وهو أول من ألقى الخنث بها وكان طويلا أحول يكنى أبا عبد المنعم مولى بني مخزوم وكان لا يضرب بالعود إنما كان ينقر بالدف وكان ظريفا عالما بأمر المدينة وأنساب أهلها وكان يتقى للسانه قالوا وسئل عن مولده فذكر أنه ولد يوم قبض رسول الله وفطم يوم مات أبو بكر وختن يوم قتل عمر وزوج يوم قتل عثمان وولد له يوم قتل علي رضوان الله عليهم أجمعين قال وقيل إنه ولد له يوم مات الحسن بن علي عليهما\nالسلام قال وكانت أمي تمشي بين نساء الأنصار بالنميمة قالوا وأول غناء غناه وهزج به صوت\n(كيف يأتي من بعيد ... وهو يخفيه القريب)\n(نازح بالشأم عنا ... وهو مكسال هيوب)\n(قد براني الحب حتى ... كدت من وجدي أذوب)\nلغناء لطويس هزج بالبنصر","topic":"ذكر طويس وأخباره","topicNo":17,"sp":0,"spl":"ذكر طويس وأخباره — شؤم طويس"},
{"id":"b17-2","bab":"الجزء 3","sec":"شؤم طويس","page":"ج3 ص29","text":"قال إسحاق أخبرني الهيثم بن عدي قال قال صالح بن حسان الأنصاري أنبأني أبي قال اجتمع يوما جماعة بالمدينة يتذاكرون أمر المدينة إلى أن ذكروا طويسا فقالوا كان وكان فقال رجل منا أما لو شاهدتموه لرأيتم ما تسرون به علما وظرفا وحسن غناء وجودة نقر بالدف ويضحك كل ثكلى حرى فقال بعض القوم والله إنه على ذلك كان مشؤوما وذكر خبر ميلاده كما قال الواقدي إلا أنه قال ولد يوم مات نبينا وفطم يوم مات صديقنا وختن يوم قتل فاروقنا وزوج يوم قتل نورنا وولد له يوم قتل أخو نبينا وكان مع هذا مخنثا يكيدنا ويطلب عثراتنا وكان مفرطا في طوله مضطربا في خلقه أحول فقال رجل من جلة أهل المجلس لئن كان كما قلت لقد كان ممتعا فهما يحسن رعاية من حفظ له حق المجالسة ورعاية حرمة الخدمة وكان لا يحمل قول من لا يرعى له بعض ما يرعاه له ولقد كان معظما لمواليه بني مخزوم ومن والاهم من سائر قريش ومسالما لمن عاداهم\nدون التحكيك به وما يلام من قال بعلم وتكلم على فهم والظالم الملوم والبادئ أظلم فقال رجل آخر لئن كان ما قلت لقد رأيت قريشا يكتنفونه ويحدقون به ويحبون مجالسته وينصتون إلى حديثه ويتمنون غناءه وما وضعه شيء إلا خنثه ولولا ذلك ما بقي رجل من قريش والأنصار وغيرهم إلا أدناه أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال حدثني إسماعيل بن جامع عن سياط قال كان أول من تغنى بالمدينة غناء يدخل في الإيقاع طويس وكان مولده يوم مات رسول الله وفطامه في اليوم الذي توفي فيه أبو بكر وختانه في اليوم الذي قتل فيه عمر وبناءه بأهله في اليوم الذي قتل فيه عثمان وولد له يوم قتل علي رضوان الله عليهم أجمعين وولد وهو ذاهب العين اليمنى وكان يلقب بالذائب وإنما لقب بذلك لأنه غنى\n(قد براني الحب حتى ... كدت من وجدي أذوب)\nخبرني الحسين عن حماد عن أبيه قال أخبرني ابن الكلبي عن أبي مسكين قال كان بالمدينة مخنث يقال له النغاشي فقيل لمروان بن الحكم إنه لا\nيقرأ من كتاب الله شيئا فبعث إليه يومئذ وهو على المدينة فاستقرأه أم الكتاب فقال والله ما معي بناتها أو ما أقرأ البنات فكيف أقرأ أمهن فقال أتهزأ لا أم لك فأمر به فقتل في موضع يقال له بطحان وقال من جاءني بمخنث فله عشرة دنانير فأتي طويس وهو في بني الحارث بن الخزرج من المدينة وهو يغني بشعر حسان بن ثابث\n(لقد هاج نفسك أشجانها ... وعاودها اليوم أديانها)\n(تذكرت هندا وما ذكرها ... وقد قطعت منك أقرانها)\n(وقفت عليها فساءلتها ... وقد ظعن الحي ما شانها)\n(فصدت وجاوب من دونها ... بما أوجع القلب أعوانها)\nأخبر بمقالة مروان فيهم فقال أما فضلني الأمير عليهم بفضل حتى جعل في وفيهم أمرا واحدا ثم خرج حتى نزل السويداء على ليلتين من المدينة في طريق الشأم فلم يزل بها عمره وعمر حتى مات في ولاية الوليد بن عبد الملك","topic":"ذكر طويس وأخباره","topicNo":17,"sp":0,"spl":"ذكر طويس وأخباره — شؤم طويس"},
{"id":"b17-3","bab":"الجزء 3","sec":"خبر بادية بنت غيلان","page":"ج3 ص31","text":"قال إسحاق وأخبرني ابن الكلبي قال أخبرني خالد بن سعيد عن أبيه وعوانة قالا قال هيت المخنث لعبد الله بن أبي أمية إن فتح الله عليكم الطائف فسل النبي بادية بنت غيلان بن سلمة بن معتب فإنها هيفاء شموع نجلاء إن\nتكلمت تغنت وإن قامت تثنت تقبل بأربع وتدبر بثمان مع ثغر كأنه الأقحوان وبين رجليها كالإناء المكفوء كما قال قيس بن الخطيم\n(تغترق الطرف وهي لاهية ... كأنما شف وجهها نزف)\n(بين شكول النساء خلقتها ... قصد فلا جبلة ولا قضف)\nفقال النبي لقد غلغلت النظر يا عدو الله ثم جلاه عن المدينة إلى الحمى قال هشام وأول ما اتخذت النعوش من أجلها قال فلما فتحت الطائف تزوجها عبد الرحمن بن عوف فولدت له بريهة فلم يزل هيت بذلك المكان حتى قبض النبي فلما ولي أبو بكر رضي الله عنه كلم فيه فأبى أن يرده فلما ولي عمر رضي الله عنه كلم فيه فأبى أن يرده وقال إن رأيته لأضربن عنقه فلما ولي عثمان رضي الله عنه كلم فيه فأبى أن يرده فقيل له قد كبر وضعف واحتاج فأذن له أن يدخل كل جمعة فيسأل ويرجع إلى مكانه وكان هيت مولى لعبد الله بن أبي أمية بن المغيرة المخزومي وكان طويس له فمن ثم قيل الخنث وجلس يوما فغنى في مجلس فيه ولد لعبد الله بن أبي أمية\n(تغترق الطرف وهي لاهية ... )\nلى آخر البيتين فأشير إلى طويس أن اسكت فقال والله ما قيل هذان البيتان في\nابنة غيلان بن سلمة وإنما هذا مثل ضربه هيت في أم بريهة ثم التفت إلى ابن عبد الله فقال يابن الطاهر أوجدت علي في نفسك أقسم بالله قسما حقا لا أغني بهذا الشعر أبدا قال إسحاق وحدثنا أبو الحسن الباهلي الرواية عن بعض أهل المدينة وحدثنا الهيثم بن عدي والمدائني قالوا كان عبد الله بن جعفر معه إخوان له في عشية من عشايا الربيع فراحت عليهم السماء بمطر جود فأسال كل شيء فقال عبد الله هل لكم في العقيق وهو متنزه أهل المدينة في أيام الربيع والمطر فركبوا دوابهم ثم انتهوا إليه فوقفوا على شاطئه وهو يرمي بالزبد مثل مد الفرات فإنهم لينظرون إذ هاجت السماء فقال عبد الله لأصحابه ليس معنا جنة نستجن بها وهذه سماء خليقة أن تبل ثيابنا فهل لكم في منزل طويس فإنه قريب منا فنستكن فيه ويحدثنا ويضحكنا وطويس في النظارة يسمع كلام عبد الله بن جعفر فقال له عبد الرحمن بن حسان بن ثابت جعلت فداءك وما تريد من طويس عليه غضب الله مخنث شائن لمن عرفه فقال له عبد الله لا تقل ذلك فإنه مليح خفيف لنا فيه أنس فلما استوفى طويس كلامهم تعجل إلى منزله فقال لامرأته ويحك قد جاءنا عبد الله بن جعفر سيد الناس فما عندك قالت نذبح هذه العناق وكانت عندها عنيقة قد ربتها باللبن واختبز خبزا رقاقا فبادر فذبحها وعجنت هي ثم خرج فتلقاه مقبلا إليه فقال له طويس بأبي أنا وأمي هذا المطر فهل لك في المنزل فتستكن فيه إلى أن تكف السماء قال إياك أريد قال فامض يا سيدي على بركة الله وجاء\nيمشي بين يديه حتى نزلوا فتحدثوا حتى أدرك الطعام فقال بأبي أنت وأمي تكرمني إذ دخلت منزلي بأن تتعشى عندي قال هات ما عندك فجاءه بعناق سمينة ورقاق فأكل وأكل القوم حتى تملؤوا فأعجبه طيب طعامه فلما غسلوا أيديهم قال بأبي أنت وأمي أتمشى معك وأغنيك قال افعل يا طويس فأخذ ملحفة فأتزر بها وأرخى لها ذنبين ثم أخذ المربع فتمشى وأنشأ يغني\n(يا خليلي يا بني سهدي ... لم تنم عيني ولم تكد)\n(كيف تلحو بي على رجل ... آنس تلتذه كبدي)\n(مثل ضوء البدر طلعته ... ليس بالزميلة النكد)\nفطرب القوم وقالوا أحسنت والله يا طويس ثم قال يا سيدي أتدري لمن هذا الشعر قال لا والله ما أدري لمن هو إلا أني سمعت شعرا حسنا قال هو لفارعة بنت ثابت أخت حسان بن ثابت وهي تتعشق عبد الرحمن بن الحارث بن هشام المخزومي وتقول فيه هذا الشعر فنكس القوم رؤوسهم وضرب عبد الرحمن برأسه على صدره فلو شقت الأرض له لدخل فيها قال وحدثني ابن الكلبي والمدائني عن جعفر بن محرز قال خرج عمر بن عبد العزيز وهو على المدينة إلى السويداء وخرج الناس معه وقد أخذت المنازل فلحق بهم يزيد بن بكر بن دأب الليثي وسعيد بن عبد","topic":"ذكر طويس وأخباره","topicNo":17,"sp":1,"spl":"خبر بادية بنت غيلان","partialRef":{"sid":"b16-11","gi":1,"vi":5,"side":0},"partial":1},
{"id":"b17-4","bab":"الجزء 3","sec":"خبر بادية بنت غيلان","page":"ج3 ص31","text":"الرحمن بن حسان بن ثابت الأنصاري فلقيهما طويس فقال لهما بأبي أنتما وأمي عرجا إلى منزلي فقال يزيد لسعيد مل بنا مع أبي عبد النعيم فقال سعيد أين تذهب مع هذا المخنث فقال يزيد إنما هو منزل ساعة فمالا واحتمل طويس الكلام على سعيد فأتيا منزله فإذا هو قد نضحه ونصعه فأتاهما بفاكهة من فاكهة الماء ثم قال سعيد لو أسمعتنا يا أبا عبد النعيم فتناول خريطة فاستخرج منها دفا ثم نقره وقال\n(يا خليلي نابني سهدي ... لم تنم عيني ولم تكد)\n(فشرابي ما أسيغ وما ... أشتكي ما بي إلى أحد)\n(كيف تلحوني على رجل ... آنس تلتذه كبدي)\n(مثل ضوء البدر صورته ... ليس بالزميلة النكد)\n(من بني آل المغيرة لا ... خامل نكس ولا جحد)\n(نظرت يوما فلا نظرت ... بعده عيني إلى أحد)\nم ضرب بالدف الأرض فقال سعيد ما رأيت كاليوم قط شعرا أجود ولا غناء أحسن منه فقال له طويس يابن الحسام أتدري من يقوله قال لا قال قالته عمتك خولة بنت ثابت تشبب بعمارة بن الوليد بن المغيرة المخزومي فخرج سعيد وهو يقول ما رأيت كاليوم قط مثل ما استقبلني به هذا المخنث والله لا يفلتني فقال يزيد دع هذا وأمته ولا ترفع به رأسا قال أبو الفرج الأصبهاني هذه الأبيات فيما ذكر الحرمي بن أبي العلاء عن الزبير بن بكار لابن زهير المخنث","topic":"ذكر طويس وأخباره","topicNo":17,"sp":2,"spl":"خبر بادية بنت غيلان — ابن سريج يمدح غناء طويس"},
{"id":"b17-5","bab":"الجزء 3","sec":"ابن سريج يمدح غناء طويس","page":"ج3 ص36","text":"قال إسحاق وحدثني الهيثم بن عدي عن ابن عياش وابن الكلبي عن أبي مسكين قالا قدم ابن سريج المدينة فغناهم فاستظرف الناس غناءه وآثروه على كل من غنى وطلع عليهم طويس فسمعهم وهم يقولون ذلك فاستخرج دفا من حضنه ثم نقر به وغناهم بشعر عمارة بن الوليد المخزومي في خولة بنت ثابت عارضها بقصيدتها فيه\n(يا خليلي نابني سهدي ... لم تنم عيني ولم تكد)\nهو\n(تناهى فيكم وجدي ... وصدع حبكم كبدي)\n(فقلبي مسعر حزنا ... بذات الخال في الخد)\n(فما لاقى أخو عشق ... عشير العشر من جهدي)\nأقبل عليهم ابن سريح فقال والله هذا أحسن الناس غناء أخبرني وكيع محمد بن خلف قال حدثنا إسماعيل بن مجمع قال حدثني المدائني قال قدم ابن سريج المدينة فجلس يوما في جماعة وهم يقولون أنت والله أحسن الناس غناء إذ مر بهم طويس فسمعهم وما يقولون فاستل دفه من حضنه ونقره وتغنى\n(إن المجنبة التي ... مرت بنا قبل الصباح)\n(في حلة موشية ... مكية غرثى الوشاح)\n(زين لمشهد فطرهم ... وتزينهم يوم الأضاحي)\nلشعر لابن زهير المخنث والغناء لطويس هزج أخبرنا بذلك الحرمي بن أبي العلاء عن الزبير بن بكار فقال ابن سريج هذا والله أحسن الناس غناء لا أنا","topic":"ذكر طويس وأخباره","topicNo":17,"sp":2,"spl":"خبر بادية بنت غيلان — ابن سريج يمدح غناء طويس"},
{"id":"b17-6","bab":"الجزء 3","sec":"خبر طويس مع جارية","page":"ج3 ص37","text":"قال إسحاق حدثني المدائني قال حدثت أن طويسا تبع جارية فراوغته فلم ينقطع عنها فخبت في المشي فلم ينقطع عنها فلما جازت بمجلس وقفت ثم قالت يا هؤلاء لي صديق ولي زوج ومولى ينكحني فسلوا هذا ما يريد مني فقال أضيق ما قد وسعوه ثم جعل يتغنى\n(أفق يا قلب عن جمل ... وجمل قطعت حبلي)\n(أفق عنها فقد عنيت ... حولا في هوى جمل)\n(وكيف يفيق محزون ... بجمل هائم العقل)\n(براه الحب في جمل ... فحسبي الحب من ثقل)\n(وحسبي فيك ما ألقى ... من التفنيد والعذل)\n(وقدما لامني فيها ... فلم أحفل بهم أهلي)\nال إسحاق وقال المدائني قال مسلمة بن محارب حدثني رجل من أصحابنا قال\nخرجنا في سفرة ومعنا رجل فانتهينا إلى واد فدعونا بالغداء فمد الرجل يده إلى الطعام فلم يقدر عليه وهو قبل ذلك يأكل معنا في كل منزل فخرجنا نسأل عن حاله فلقينا رجلا طويلا أحول مضطرب الخلق في زي الأعراب فقال لنا ما لكم فأنكرنا سؤاله لنا فأخبرناه خبر الرجل فقال ما اسم صاحبكم فقلنا أسيد فقال هذا واد قد أخذت سباعه فارحلوا فلوقد جاوزتم الوادي استمر صاحبكم وأكل قلنا في أنفسنا هذا من الجن ودخلتنا فزعة ففهم ذلك وقال ليفرخ روعكم فأنا طويس قال له بعض من معنا من بني غفار أو من بني عبس مرحبا بك يا أبا عبد النعيم ما هذا الزي فقال دعاني بعض أودائي من الأعراب فخرجت إليهم وأحببت أن أتخطى الأحياء فلا ينكروني فسألت الرجل أن يغنينا فاندفع ونقر بدف كان معه مربع فلقد تخيل لي أن الوادي ينطق معه حسنا وتعجبنا من علمه وما أخبرنا به من أمر صاحبنا وكان الذي غنى به في شعر عروة بن الورد في سلمى امرأته الغفارية حيث رهنها على الشراب\n(سقوني الخمر ثم تكنفوني ... عداة الله من كذب وزور)\n(وقالوا لست بعد فداء سلمى ... بمفن ما لديك ولا فقير)\n(فلا والله لو ملكت أمري ... ومن لي بالتدبر في الأمور)\n(إذا لعصيتهم في حب سلمى ... على ما كان من حسك الصدور)\n(فيا للناس كيف غلبت أمري ... على شيء ويكرهه ضميري)\nال إسحاق وحدثني الواقدي قال حدثني عبد الرحمن بن أبي الزناد عن أبيه قال لما غزا النبي بني النضير وأجلاهم عن المدينة خرجوا يريدون خيبر يضربون بدفوف ويزمرون بالمزامير وعلى النساء المعصفرات وحلي الذهب مظهرين لذلك تجلدا ومرت في الظعن يومئذ سلمى امرأة عروة بن الورد العبسي وكان عروة حليفا في بني عمرو بن عوف وكانت سلمى من بني غفار فسباها عروة من قومها وكانت ذات جمال فولدت له أولادا وكان شديد الحب لها وكان ولده يعيرون بأمهم ويسمون بني الأخيذة أي السبية فقالت ألا ترى ولدك يعيرون قال فماذا ترين قالت أرى أن تردني إلى قومي حتى يكونوا هم الذين يزوجونك فأنعم لها فأرسلت إلى قومها أن القوه بالخمر ثم أتركوه حتى يسكر ويثمل فإنه لا يسأل حينئذ شيئا إلا أعطاه فلقوه وقد نزل في بني النضير فسقوه الخمر فلما سكر سألوه سلمى فردها عليهم ثم أنكحوه بعد ويقال إنما جاء بها إلى بني النضير وكان صعلوكا يغير فسقوه الخمر فلما انتشى منعوه ولا شيء معه إلا هي فرهنها ولم يزل يشرب حتى غلقت فلما قال لها انطلقي قالت لا سبيل إلى ذلك قد أغلقتني فبهذا صارت عند بني النضير فقال في ذلك\n(سقوني الخمر ثم تكنفوني ... عداة الله من كذب وزور)\nذه الأبيات مشهورة بأن لطويس فيها غناء وما وجدته في شيء من الكتب مجنسا فتذكر طريقته","topic":"ذكر طويس وأخباره","topicNo":17,"sp":3,"spl":"خبر طويس مع جارية"},
{"id":"b17-7","bab":"الجزء 3","sec":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم","page":"ج3 ص40","text":"وقال إسحاق وحدثني المدائني قال كان طويس ولعا بالشعر الذي قالته الأوس والحزرج في حروبهم وكان يريد بذلك الإغراء فقل مجلس اجتمع فيه هذان الحيان فغنى فيه طويس إلا وقع فيه شيء فنهي عن ذلك فقال والله لا تركت الغناء بشعر الأنصار حتى يوسدوني التراب وذلك لكثرة تولع القوم به فكان يبدي السرائر ويخرج الضغائن فكان القوم يتشاءمون به\nوكان يستحسن غناؤه ولا يصبر عن حديثه ويستشهد على معرفته فغنى يوما بشعر قيس بن الخطيم في حرب الأوس والخزرج وهو\n(رد الخليط الجمال فانصرفوا ... ماذا عليهم لو أنهم وقفوا)\n(لو وقفوا ساعة نسائلهم ... ريث يضحي جماله السلف)\n(فليت أهلي وأهل أثلة في الدار ... قريب من حيث نختلف)\nلما بلغ إلى آخر بيت غنى فيه طويس من هذه القصيدة وهو\n(أبلغ بني جحجبى وقومهم ... خطمة أنا وراءهم أنف)\nكلموا وانصرفوا وجرت بينهم دماء وانصرف طويس من عندهم سليما لم يكلم ولم يقل له شيء قال إسحاق فحدثني الواقدي وأبو البختري قالا قال قيس بن الخطيم هذه القصيدة لشغب أثاره القوم بعد دهر طويل ونذكر\nسبب أول ما جرى بين الأوس والخزرج من الحرب قال إسحاق قال أبو عبد الله اليزيدي وأبو البختري وحدثني مشايخ لنا قالوا كانت الأوس والخزرج أهل عز ومنعة وهما أخوان لأب وأم وهما ابنا حارثة بن ثعلبة بن عمرو بن عامر وأمهما قيلة بنت جفنة بن عتبة بن عمرو وقضاعة تذكر أنها قيلة بنت كاهل بن عذرة بن سعد بن زيد بن سود بن أسلم بن الحاف بن قضاعة وكانت أول حرب جرت بينهم في مولى كان لمالك بن العجلان قتله سمير بن يزيد بن مالك وسمير رجل من الأوس ثم أحد بني عمرو بن عوف وكان مالك سيد الحيين في زمانه وهو الذي ساق تبعا إلى المدينة وقتل الفطيون صاحب زهرة وأذل اليهود للحيين جميعا فكان له بذلك الذكر والشرف عليهم وكانت دية المولى فيهم وهو الحليف خمسا من الإبل ودية الصريح عشرا فبعث مالك إلى عمرو بن عوف ابعثوا إلي سميرا حتى أقتله بمولاي فإنا نكره أن تنشب بيننا وبينكم حرب فأرسلوا إليه إنا نعطيك الرضا من مولاك فخذ منا عقله فإنك قد عرفت أن الصريح لا يقتل بالمولى قال لا آخذ في مولاي دون دية الصريح فأبوا إلا دية المولى فلما رأى ذلك مالك بن العجلان جمع قومه من الخزرج وكان فيهم مطاعا وأمرهم بالتهيؤ للحرب فلما بلغ الأوس استعدوا لهم وتهيؤوا للحرب واختاروا الموت على الذل ثم خرج بعض القوم إلى بعض فالتقوا بالصفينة بين بئر سالم وبين قباء قرية لبني عمرو بن عوف فاقتتلوا قتالا شديدا حتى نال بعض القوم من بعض ثم إن رجلا من الأوس نادى يا مالك ننشدك الله والرحم وكانت أم مالك إحدى نساء بني","topic":"ذكر طويس وأخباره","topicNo":17,"sp":4,"spl":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم"},
{"id":"b17-8","bab":"الجزء 3","sec":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم","page":"ج3 ص40","text":"عمرو بن عوف فاجعل بيننا وبينك عدلا من قومك فما حكم علينا سلمنا لك فارعوى مالك عند ذلك وقال نعم فاختاروا عمرو بن امرئ القيس أحد بني الحارث بن الحزرج فرضي القوم به واستوثق منهم ثم قال فإني أقضي بينكم إن كان سمير قتل صريحا من القوم فهو به قود وإن قبلوا العقل فلهم دية الصريح وإن كان قتل مولى فلهم دية المولى بلا نقص ولا يعطى فوق نصف الدية وما أصبتم منا في هذه الحرب ففيه الدية مسلمة إلينا وما أصبنا منكم فيها علينا فيه دية مسلمة إليكم فلما قضى بذلك عمرو بن امرئ القيس غضب مالك بن العجلان ورأى أن يرد عليه رأيه وقال لا أقبل هذا القضاء وأمر قومه بالقتال فجمع القوم بعضهم لبعض ثم التقوا بالفضاء عند آطام بني قينقاع فاقتتلوا قتالا شديدا ثم تداعوا إلى الصلح فحكموا ثابت بن حرام بن المنذر أبا حسان بن ثابت النجاري فقضى بينهم أن يدوا مولى مالك بن العجلان بدية الصريح ثم تكون السنة فيهم بعده على مالك وعليهم كما كانت أول مرة المولى على ديته والصريح على ديته فرضي مالك وسلم الآخرون وكان ثابت إذ حكموه أراد إطفاء النائرة فيما بين القوم ولم شعثهم فأخرج خمسا من الإبل من قبيلته حين أبت عليه الأوس أن تؤدي إلى مالك أكثر من خمس وأبى مالك أن يأخذ دون عشر فلما أخرج ثابت الخمس أرضى مالكا بذلك ورضيت الأوس واصطلحوا بعهد وميثاق ألا يقتل رجل في داره ولا معقله والمعاقل النخل فإذا خرج رجل من داره أو معقله فلا دية له ولا عقل ثم انظروا في القتلى فأي الفريقين فضل على صاحبه ودى له صاحبه فأفضلت الأوس على الخزرج بثلاثة نفر فودتهم الأوس واصطلحوا ففي ذلك يقول حسان بن ثابت لما كان أبوه أصلح بينهم ورضاهم بقضائه في ذلك\n(وأبي في سميحة القائل الفاصل ... حين التفت عليه الخصوم)\nفي ذلك يقول قيس بن الخطيم قصيدته وهي طويلة\n(رد الخليط الجمال فانصرفوا ... ماذا عليهم لو أنهم وقفوا)","topic":"ذكر طويس وأخباره","topicNo":17,"sp":5,"spl":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم — ومما في المائة المختارة من أغاني طويس"},
{"id":"b17-9","bab":"الجزء 3","sec":"عمر بن عبد العزيز يقول قيس بن الخطيم هو أنسب الناس","page":"ج3 ص42","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الرحمن بن أبي الزناد عن أبيه قال\nكان عمر بن عبد العزيز ينشد قول قيس بن الخطيم\n(بين شكول النساء خلقتها ... قصد فلا جبلة ولا قضف)\n(تنام عن كبر شأنها فإذا ... قامت رويدا تكاد تنقصف)\n(تغترق الطرف وهي لاهية ... كأنما شف وجهها نزف)\nم يقول قائل هذا الشعر أنسب الناس","topic":"ذكر طويس وأخباره","topicNo":17,"sp":5,"spl":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم — ومما في المائة المختارة من أغاني طويس"},
{"id":"b17-10","bab":"الجزء 3","sec":"ومما في المائة المختارة من أغاني طويس","page":"ج3 ص43","text":"صوت\n(يا لقومي قد أرقتني الهموم ... ففؤادي مما يجن سقيم)\n(أندب الحب في فؤادي ففيه ... لو تراءى للناظرين كلوم)\nجن يخفي والجنة من ذلك والجن أيضا مأخوذ منه وأندب أبقى فيه ندبا وهو أثر الجرح قال ذو الزمة\n(تريك سنة وجه غير مقرفة ... ملساء ليس بها خال ولا ندب)\nلشعر لابن قيس الرقيات فيما قيل والغناء لطويس ولحنه المختار خفيف رمل مطلق في مجرى الوسطى قال إسحاق وهو أجود لحن غناه طويس ووجدته في كتاب الهشامي خفيف رمل بالوسطى منسوبا إلى ابن طنبورة قال وقال ابن المكي إنه لحكم وقال عمرو بن بانة إنه لابن عائشة أوله هذان البيتان وبعدهما\n(ما لذا الهم لا يريم فؤادي ... مثل ما يلزم الغريم الغريم)\n(إن من فرق الجماعة منا ... بعد خفص ونعمة لذميم)\nانقضت أخبار طويس","topic":"ذكر طويس وأخباره","topicNo":17,"sp":5,"spl":"ولع طويس بالشعر الذي قالته الأوس والخزرج في حروبهم — ومما في المائة المختارة من أغاني طويس"},
{"id":"b18-1","bab":"الجزء 3","sec":"صوت من المائة المختارة من صنعة قفا النجار","page":"ج3 ص44","text":"(حجب الألى كنا نسر بقربهم ... يا ليت أن حجابهم لم يقدر)\n(حجبوا ولم نقض اللبانة منهم ... ولنا إليهم صبوة لم تقصر)\n(ويحيط مئزرها بردف كامل ... رابي المجسة كالكثيب الأعفر)\n(وإذا مشت خلت الطريق لمشيها ... وحلا كمشي المرجحن الموقر)\nم يقع إلينا قائل هذا الشعر والغناء لقفا النجار ولحنه المختار من الثقيل\nالثاني بإطلاق الوتر في مجرى الوسطى ويقال إن فيه لحنا لابن سريج وذكر يحيى بن علي ابن يحيى في الاختيار الواثقي أن لحن قفا النجار المختار من الثقيل الأول","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":0,"spl":"صوت من المائة المختارة من صنعة قفا النجار — ذكر الدارمي وخبره ونسبه"},
{"id":"b18-2","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص45","text":"(أفق يا دارمي فقد بليتا ... وإنك سوف توشك أن تموتا)\n(أراك تزيد عشقا كل يوم ... إذا ما قلت إنك قد بريتا)\nلشعر والغناء جميعا لسعيد الدارمي ولحنه المختار من خفيف الثقيل الأول بإطلاق الوتر في مجرى الوسطى","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":0,"spl":"صوت من المائة المختارة من صنعة قفا النجار — ذكر الدارمي وخبره ونسبه"},
{"id":"b18-3","bab":"الجزء 3","sec":"ذكر الدارمي وخبره ونسبه","page":"ج3 ص45","text":"أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني أبو أيوب المديني قال حدثني عبد الرحمن ابن أخي الأصمعي عن عمه قال الدارمي من ولد سويد بن زيد الذي كان جده قتل أسعد بن عمرو بن هند ثم هربوا إلى مكة فحالفوا بني نوفل بن عبد مناف وكان الدارمي في أيام عمر بن عبد العزيز وكانت له أشعار ونوادر وكان من ظرفاء أهل مكة وله أصوات يسيرة وهو الذي يقول\n(ولما رأيتك أوليتني القبيح ... وأبعدت عني الجميلا)\n(تركت وصالك في جانب ... وصادفت في الناس خلا بديلا)","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":0,"spl":"صوت من المائة المختارة من صنعة قفا النجار — ذكر الدارمي وخبره ونسبه"},
{"id":"b18-4","bab":"الجزء 3","sec":"مناسبة قصيدته قل للمليحة","page":"ج3 ص46","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني إسحاق بن إبراهيم عن الأصمعي وأخبرني عمي قال حدثنا فضل اليزيدي عن إسحاق بن إبراهيم عن الأصمعي وأخبرني عمي قال حدثنا أبو الفضل الرياشي عن الأصمعي قال وحدثني به النوشجاني عن شيخ له البصريين عن الأصمعي عن\nابن أبي الزناد ولم يقل عن ابن أبي الزناد غيره أن تاجرا من أهل الكوفة قدم المدينة بخمر فباعها كلها وبقيت السود منها فلم تنفق وكان صديقا للدارمي فشكا ذاك إليه وقد كان نسك وترك الغناء وقول الشعر فقال له لا تهتم بذلك فإني سأنفقها لك حتى تبيعها أجمع ثم قال صوت\n(قل للمليحة في الخمار الأسود ... ماذا صنعت براهب متعبد)\n(قد كان شمر للصلاة ثيابه ... حتى وقفت له بباب المسجد)\nوغنى فيه وغنى فيه أيضا سنان الكاتب وشاع في الناس وقالوا قد فتك الدارمي ورجع عن نسكه فلم تبق في المدينة ظريفة إلا ابتاعت خمارا أسود حتى نفد ما كان مع العراقي منها فلما علم بذلك الدارمي رجع إلى نسكه ولزم المسجد فأما نسبة هذا الصوت فإن الشعر فيه للدارمي والغناء أيضا وهو خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لسنان الكاتب رمل بالوسطى عن حبش وذكر حبش أن فيه لان سريج هزجا بالبنصر أخبرني إسماعيل بن يونس قال حدثني أبو هفان قال حضرت يوما مجلس بعض قواد الأتراك وكانت له ستارة فنصبت فقال لها غني صوت الخمار السود المليح فلم ندر ما أراد حتى غنت\n(قل للمليحة في الخمار الأسود ... )\nثم أمسك ساعة ثم قال لها غني\n(إني خريت وجئت ... )\nضحكت ثم قالت هذا يشبهك فلم ندر أيضا ما أراد حتى غنت\n(إن الخليط أجد منتقله ... )\nخل الدارمي أخبرني الحسن بن علي قال حدثنا هارون بن محمد قال حدثني محمد ابن أخي سلم الخزاعي قال حدثني الحرمازي قال زعم لي ابن مودود قال كان الدارمي المكي شاعرا ظريفا وكانت متفتيات أهل مكة لا يطيب لهن متنزه إلا بالدارمي فاجتمع جماعة منهن في متنزه لهن وفيهن صديقة له وكل واحدة منهن قد واعدت هواها فخرجن حتى أتين الجحفة وهو معهن فقال بعضهن لبعض كيف لنا أن نخلو مع هؤلاء الرجال من الدارمي فإنا إن فعلنا قطعنا في الأرض قالت لهن صاحبته أنا أكفيكنه قلن إنا نريد ألا يلومنا قالت علي أن ينصرف حامدا وكان أبخل الناس فأتته فقالت يا دارمي إنا قد تفلنا فاجلب لنا طيبا قال نعم هوذا آتي سوق الجحفة آتيكن منها بطيب فأتى المكارين فاكترى حمارا فصار عليه إلى مكة وهو يقول\n(أنا بالله ذي العز ... وبالركن وبالصخره)\n(من اللائي يردن الطيب ... في اليسر وفي العسره)\n(وما أقوى على هذا ... ولو كنت على البصره)\nمكث النسوة ما شئن ثم قدم من مكة فلقيته صاحبته ليلة في الطواف فأخرجته إلى ناحية المسجد وجعلت تعاتبه على ذهابه ويعاتبها إلى أن قالت له يا دارمي بحق هذه البنية أتحبني فقال نعم فبربها أتحبيني قالت نعم قال فيالك الخير فأنت تحبيني وأنا أحبك فما مدخل الدراهم بيننا أخبرني حبيب بن نصر المهلبي قال حدثنا الزبير بن بكار قال حدثني عمي قال كان الدارمي عند عبد الصمد بن علي يحدثه فأغفى عبد الصمد فعطس الدارمي عطسة هائلة ففزع عبد الصمد فزعا شديدا وغضب غضبا شديدا ثم استوى جالسا وقال يا عاض كذا من أمه أتفزعني قال لا والله ولكن هكذا عطاسي قال والله لأنقعنك في دمك أو تأتيني ببينة على ذلك قال فخرج ومعه حرسي لا يدري أين يذهب به فلقيه ابن الريان المكي فسأله فقال أنا أشهد لك فمضى حتى دخل على عبد الصمد فقال له بم تشهد لهذا قال أشهد أني رأيته مرة عطس عطسة فسقط ضرسه فضحك عبد الصمد وخلى سبيله أخبرني الحسن بن علي قال حدثنا هارون بن محمد قال حدثنا الزبير قال قال محمد بن إبراهيم الإمام للدارمي لو صلحت عليك ثيابي لكسوتك قال فديتك إن لم تصلح علي ثيابك صلحت علي دنانيرك\nأخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن زهير قال حدثنا الزبير ونسخت من كتاب هارون بن محمد حدثنا الزبير قال حدثني يونس بن عبد الله الخياط قال خرج الدارمي مع السعاة فصادف جماعة منهم قد نزلوا على الماء فسألهم فأعطوه دراهم فأتى بها في ثوبه وأحاط به أعرابيات فجعلن يسألنه وألححن عليه وهو يردهن فعرفته صبية منهن فقالت يا أخواتي أتدرين من تسألن منذ اليوم هذا الدارمي السأل ثم أنشدت","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":1,"spl":"مناسبة قصيدته قل للمليحة","partial":1},
{"id":"b18-5","bab":"الجزء 3","sec":"مناسبة قصيدته قل للمليحة","page":"ج3 ص46","text":"(إذا كنت لا بد مستطعما ... فدع عنك من كان يستطعم)\nولى الدارمي هاربا منهن وهن يتضاحكن به","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":2,"spl":"مناسبة قصيدته قل للمليحة — مرضه"},
{"id":"b18-6","bab":"الجزء 3","sec":"خبر الدارمي مع الأوقص القاضي","page":"ج3 ص50","text":"أخبرني حبيب بن نصر المهلبي قال أخبرني أحمد بن أبي خيثمة قال حدثنا مصعب الزبيري قال أتى الدارمي الأوقص القاضي بمكة في شيء فأبطأ عليه فيه وحاكمه إليه خصم له في حق فحبسه به حتى أداه إليه فبينا الأوقص يوما في المسجد الحرام يصلي ويدعو ويقول يا رب أعتق رقبتي من النار إذ قال له الدارمي والناس يسمعون أولك رقبة تعتق لا والله ما جعل الله وله الحمد لك من عتق ولا رقبة فقال له الأوقص ويلك ومن أنت قال أنا الدارمي حبستني وقتلتني قال لا تقل ذلك وأتني فإني أعوضك فأتاه ففعل ذلك به","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":2,"spl":"مناسبة قصيدته قل للمليحة — مرضه"},
{"id":"b18-7","bab":"الجزء 3","sec":"خبر الدارمي مع عبد الصمد بن علي","page":"ج3 ص50","text":"أخبرني الحرمي أحمد بن محمد بن إسحاق قال حدثني الزبير بن بكار قال حدثني عمي قال مدح الدارمي عبد الصمد بن علي بقصيدة واستأذنه في الإنشاد فأذن له فلما فرغ أدخل إليه رجل من الشراة فقال لغلامه أعط هذا مائة دينار واضرب عنق هذا فوثب الدارمي فقال بأبي أنت وأمي برك وعقوبتك جميعا نقد فإن رأيت أن تبدأ بقتل هذا فإذا فرغ منه أمرته فأعطاني فإني لن أريم من حضرتك حتى يفعل ذلك قال ولم ويلك قال أخشى أن يغلط فيما بيننا والغلط في هذا لا يستقال فضحك وأجابه إلى ما سأل","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":2,"spl":"مناسبة قصيدته قل للمليحة — مرضه"},
{"id":"b18-8","bab":"الجزء 3","sec":"مرضه","page":"ج3 ص51","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي قال أصابت الدارمي قرحة في صدره فدخل إليه بعض أصدقائه يعوده فرآه قد نفث من فيه نفثا أخضر فقال له أبشر قد اخضرت القرحة وعوفيت فقال هيهات والله لو نفثت كل زمردة في الدنيا ما أفلت منها","topic":"ذكر الدارمي وخبره ونسبه","topicNo":18,"sp":2,"spl":"مناسبة قصيدته قل للمليحة — مرضه"},
{"id":"b19-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص52","text":"(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\n(ريع تبدل ممن كان يسكنه ... عفر الظباء وظلمانا به عصبا)\nلشعر لهلال بن الأسعر المازني أخبرني بذلك وكيع عن حماد بن إسحاق عن أبيه وهكذا هو في رواية عمرو بن أبي عمرو الشيباني ومن لا يعلم ينسبه إلى عمر بن أبي ربيعة وإلى الحارث بن خالد ونصيب وليس كذلك والغناء في اللحن المختار لعزور الكوفي ومن الناس من يقول عزون بالنون وتشديد الزاي وهو رجل من أهل الكوفة غير مشهور ولا كثير الصنعة ولا أعلم أني سمعت له بخبر ولا صنعة غير هذا الصوت ولحن هذا المختار ثقيل أول بالبنصر في مجراها عن إسحاق وهكذا نسبه في الاختيار الواثقي وذكر عمرو بن بانة أن فيه لابن عائشة لحنا من الثقيل الأول بالبنصر وفي أخبار الغريض عن حماد أن له فيه ثقيلا أول وقال الهشامي فيه لعبد الله بن العباس لحن من الثقيل الثاني وذكر حبش أن فيه لحسين بن محرز خفيف رمل بالبنصر","topic":"أخبار هلال ونسبه","topicNo":19,"sp":0,"spl":"صوت من المائة المختارة — أخبار هلال ونسبه"},
{"id":"b19-2","bab":"الجزء 3","sec":"أخبار هلال ونسبه","page":"ج3 ص53","text":"هو فيما ذكر خالد بن كلثوم هلال بن الأسعر بن خالد بن الأرقم بن قسيم بن ناشرة بن سيار بن رزام بن مازن بن مالك بن عمرو بن تميم شاعر إسلامي من شعراء الدولة الأموية وأظنه قد أدرك الدولة العباسية وكان رجلا شديدا عظيم الخلق أكولا معدودا من الأكلة قال أبو عمرو وكان هلال فارسا شجاعا شديد البأس والبطش أكثر الناس أكلا وأعظمهم في حرب غناء هذا لفظ أبي عمرو وقال أبو عمرو وعمر هلال بن أسعر عمرا طويلا ومات بعد بلايا عظام مرت على رأسه قال وكان رجل من قومه من بني رزام بن مالك يقال له المغيرة بن قنبر يعوله ويفضل عليه ويحتمل ثقله وثقل عياله فهلك فقال هلال يرثيه\n(ألا ليت المغيرة كان حيا ... وأفنى قبله الناس الفناء)\n(ليبك على المغيرة كل خيل ... إذا أفنى عرائكها اللقاء)\n(ويبك على المغيرة كل كل ... فقير كان ينعشه العطاء)\n(ويبك على المغيرة كل جيش ... تمور لدى معاركه الدماء)\n(فتى الفتيان فارس كل حرب ... إذا شالت وقد رفع اللواء)\n(لقد وارى جديد الأرض منه ... خصالا عقد عصمتها الوفاء)\n(فصبرا للنوائب إن ألمت ... إذا ما ضاق بالحدث الفضاء)\n(هزبر تنجلي الغمرات عنه ... نقي العرض همته العلاء)\n(إذا شهد الكريهة خاض منها ... بحورا لا تكدرها الدلاء)\n(جسور لا يروع عند روع ... ولا يثني عزيمته اتقاء)\n(حليم في مشاهده إذا ما ... حبا الحلماء أطلقها المراء)\n(حميد في عشيرته فقيد ... يطيب عليه في الملأ الثناء)\n(فإن تكن المنية أقصدته ... وحم عليه بالتلف القضاء)\n(فقد أودى به كرم وخير ... وعود بالفضائل وابتداء)\n(وجود لا يضم إليه جودا ... مراهنه إذا جد الجراء)","topic":"أخبار هلال ونسبه","topicNo":19,"sp":0,"spl":"صوت من المائة المختارة — أخبار هلال ونسبه"},
{"id":"b19-3","bab":"الجزء 3","sec":"أخبار عن قوته وصلابته","page":"ج3 ص54","text":"وقال خالد بن كلثوم كان هلال بن الأسعر فيما ذكروا يرد مع الإبل فيأكل ما وجد عند أهله ثم يرجع إليها ولا يتزود طعاما ولا شرابا حتى يرجع يوم ورودها لا\nيذوق فيما بين ذلك طعاما ولا شرابا وكان عادي الخلق لا توصف صفته قال خالد بن كلثوم فحدثنا عنه من أدركه أنه كان يوما في إبل له وذلك عند الظهيرة في يوم شديد وقع الشمس محتدم الهاجرة وقد عمد إلى عصاه فطرح عليها كساءه ثم أدخل رأسه تحت كسائه من الشمس فبينا هو كذلك إذ مر به رجلان أحدهما من بني نهشل والآخر من بني فقيم كانا أشد تميميين في ذلك الزمان بطشا يقال لأحدهما الهياج وقد أقبلا من البحرين ومعهما أنواط من تمر هجر وكان هلال بناحية الصعاب فلما انتهيا إلى الإبل ولا يعرفان هلالا بوجهه ولا يعرفان أن الإبل له ناديا يا راعي أعندك شراب تسقينا وهما يظنانه عبدا لبعضهم فناداهما هلال ورأسه تحت كسائه عليكما الناقة التي صفتها كذا في موضع كذا فأنيخاها فإن عليها وطبين من لبن فاشربا منهما ما بدا لكما قال فقال له أحدهما ويحك انهض يا غلام فأت بذلك اللبن فقال لهما إن تك لكما حاجة فستأتيانها فتجدان الوطبين فتشربان قال فقال أحدهما إنك يابن اللخناء لغليظ الكلام قم فاسقنا ثم دنا من هلال وهو على تلك الحال وقال لهما حيث قال له أحدهما إنك يابن اللخناء لغيظ الكلام أراكما والله ستلقيان هوانا وصغارا وسمعا ذلك منه فدنا أحدهما فأهوى له ضربا بالسوط على عجزه وهو مضطجع فتناول هلال يده فاجتذبه إليه ورماه تحت فخذه ثم ضغطه ضغطة فنادى صاحبه ويحك أغثني قد قتلني فدنا صاحبه منه فتناوله هلال أيضا فاجتذبه فرمى تحت فخذه الأخرى ثم أخذ برقابهما فجعل يصك برؤوسهما\nبعضا ببعض لا يستطيعان أن يمتنعا منه فقال أحدهما كن هلالا ولا نبالي ما صنعت فقال لهما أنا والله هلال ولا والله لا تفلتان مني حتى تعطياني عهدا وميثاقا لا تخيسان به لتأتيان المربد إذا قدمتا البصرة ثم لتناديان بأعلى أصواتكما بما كان مني ومنكما فعاهداه وأعطياه نوطا من التمر الذي معهما وقدما البصرة فأتيا المربد فناديا بما كان منه ومنهما وحدث خالد عن كنيف بن عبد الله المازني قال كنت يوما مع هلال ونحن نبغي إبلا لنا فدفعنا إلى قوم من بكر بن وائل وقد لغبنا وعطشنا وإذا نحن بفتية شباب عند ركية لهم وقد وردت إبلهم فلما رأوا هلالا استهولوا خلقه وقامته فقام رجلان منهم إليه فقال له أحدهما يا عبد الله هل لك في الصراع فقال له هلال أنا إلى غير ذلك أحوج قال وما هو قال إلى لبن وماء فإنني لغب ظمآن قال ما أنت بذائق من ذلك شيئا حتى تعطينا عهدا لتجيبننا إلى الصراع إذا أرحت ورويت فقال لهما هلال إنني لكم ضيف والضيف لا يصارع آهله رب منزله وأنتم مكتفون من ذلك بما أقول لكم اعمدوا إلى أشد فحل في إبلكم وأهيبه صولة وإلى أشد رجل منكم ذراعا فإن لم أقبض على هامة البعير وعلى يد صاحبكم فلا يمتنع الرجل ولا البعير حتى أدخل يد الرجل في فم البعير فإن لم أفعل ذلك فقد صرعتموني وإن فعلته علمتم أن صراع أحدكم أيسر من ذلك قال فعجبوا من مقالته تلك وأومؤوا إلى فحل في إبلهم هائج صائل قطم فأتاه هلال ومعه نفر من أولئك القوم وشيخ لهم فأخذ بهامة الفحل مما","topic":"أخبار هلال ونسبه","topicNo":19,"sp":1,"spl":"أخبار عن قوته وصلابته"},
{"id":"b19-4","bab":"الجزء 3","sec":"أخبار عن قوته وصلابته","page":"ج3 ص54","text":"فوق مشفره فضغطها ضغطة جرجر الفحل منها واستخذى ورغا وقال ليعطني من أحببتم يده أولجها في فم هذا الفحل قال فقال الشيخ يا قوم تنكبوا هذا الشيطان فوالله ما سمعت فلانا يعني الفحل جرجر منذ بزل قبل اليوم فلا تعرضوا لهذا الشيطان وجعلوا يتبعونه وينظرون إلى خطوه ويعجبون من طول أعضائه حتى جازهم قال وحدثنا من سمع هلالا يقول قدمت المدينة وعليها رجل من آل مروان فلم أزل أضع عن إبلي وعليها أحمال للتجار حتى أخذ بيدي وقيل لي أجب الأمير قال قلت لهم ويلكم إبلي وأحمالي فقيل لا بأس على إبلك وأحمالك قال فانطلق بي حتى أدخلت على الأمير فسلمت عليه ثم قلت جعلت فداك بلى وأمانتي قال فقال نحن ضامنون لإبلك وأمانتك حتى نؤديها إليك قال فقلت عند ذلك فما حاجة الأمير إلي جعلني الله فداه قال فقال لي وإلى جنبه رجل أصفر لا والله ما رأيت رجلا قط أشد خلقا منه ولا أغلظ عنقا وما أدري أطوله أكثر أم عرضه إن هذا العبد الذي تراه لا والله ما ترك بالمدينة عربيا يصارع إلا صرعه وبلغني عنك قوة فأردت أن يجري الله صرع هذا العبد على يديك فتدرك ما عنده من أوتار العرب قال فقلت جعلني الله فداء الأمير إني لغب نصب جائع فإن رأى الأمير أن يدعني اليوم حتى أضع عن إبلي وأؤدي أمانتي وأريح يومي هذا وأجيئه غدا فليفعل قال فقال لأعوانه انطلقوا معه فأعينوه على الوضع عن إبله وأداء أمانته وانطلقوا به إلى المطبخ فأشبعوه ففعلوا جميع ما أمرهم به قال فظللت بقية يومي ذلك وبت ليلتي تلك بأحسن حال شبعا وراحة\nوصلاح أمر فلما كان من الغد غدوت عليه وعلي جبة لي صوف وبت وليس علي إزار إلا أني قد شددت بعمامتي وسطي فسلمت عليه فرد علي السلام وقال للأصفر قم إليه فقد أرى أنه أتاك الله بما يجزيك فقال العبد اتزر يا أعرابي فأخذت بتي فاتزرت به على جبتي فقال هيهات هذا لا يثبت إذا قبضت عليه جاء في يدي قال فقلت والله ما لي من إزار قال فدعا الأمير بملحفة ما رأيت قبلها ولا علا جلدي مثلها فشددت بها على حقوي وخلعت الجبة قال وجعل العبد يدور حولي ويريد ختلي وأنا منه وجل ولا أدري كيف أصنع به ثم دنا مني دنوة فنقد جبهتي نقدة حتى ظننت أنه قد شجني وأوجعني فغاظني ذلك فجعلت أنظر في خلقه ثم أقبض منه فما وجدت في خلقه شيئا أصغر من رأسه فوضعت إبهامي في صدغيه وأصابعي الأخر في أصل أذنيه ثم غمزته غمزة صاح منها قتلني قتلني فقال الأمير اغمس رأس العبد في التراب قال فقلت له ذلك لك علي قال فغمست والله رأسه في التراب ووقع شبيها بالمغشي عليه فضحك الأمير حتى استلقى وأمر لي بجائزة وكسوة وانصرفت","topic":"أخبار هلال ونسبه","topicNo":19,"sp":2,"spl":"أخبار عن قوته وصلابته"},
{"id":"b19-5","bab":"الجزء 3","sec":"فرار هلال إلى اليمن","page":"ج3 ص58","text":"قال أبو الفرج ولهلال أحاديث كثيرة من أعاجيب شدته وقد ذكره حاجب بن ذبيان فقال قوم من بني رباب من بني حنيفة في شيء كان بينهم فيه أربع ضربات بالسيف فقال حاجب\n(وقائلة وباكية بشجو ... لبئس السيف سيف بني رباب)\n(ولو لاقى هلال بني رزام ... لعجله إلى يوم الحساب)\nوكان هلال بن الأسعر ضربه رجل من بني عنزة ثم من بني جلان يقال له عبيد ابن جري في شيء كان بينهما فشجه وخمشه خماشة فأتى هلال بني جلان فقال إن صاحبكم قد فعل بي ما ترون فخذوا لي بحقي فأوعدوه وزجروه فخرج من عندهم وهو يقول عسى أن يكون لهذا جزاء حتى أتى بلاد قومه فمضى لذلك زمن طويل حتى درس ذكره ثم إن عبيد بن جري قدم الوقبى وهو موضع من بلاد بني مالك فلما قدمها ذكر هلالا وما كان بينه وبينه فتخوفه فسأل من أعز أهل الماء فقيل له معاذ بن جعدة بن ثابت بن زرارة بن ربيعة بن سيار بن رزام بن مازن فأتاه فوجده غائبا عن الماء فعقد عبيد بن جري طرف ثيابه إلى جانب طنب بيت معاذ وكانت العرب إذا فعلت ذلك وجب على المعقود بطنب بيته للمستجير به أن يجيره وأن يطلب له بظلامته وكان يوم فعل ذلك غائبا عن الماء فقيل رجل استجار بآل معاذ بن جعدة ثم خرج عبيد بن جري ليستقي فوافق قدوم هلال بإبله يوم وروده وكان إنما يقدمها في الأيام فلما نظر هلال إلى ابن جري ذكر ما كان بينه وبينه ولم يعلم باستجارته بمعاذ بن جعدة فطلب شيئا يضربه به فلم يجده فانتزع المحور من السانية فعلاه به ضربة على رأسه فصرع وقيذا وقيل قتل هلال بن الأسعر جار معاذ بن جعدة فلما سمع ذلك هلال تخوف بني جعدة الرزاميين وهم بنو عمه فأتى راحلته ليركبها قال هلال فأتتني خولة بنت يزيد بن ثابت أخي بني جعدة بن ثابت وهي جدة أبي السفاح زهيد بن عبد الله بن مالك أم أبيه فتعلقت بثوب هلال ثم قالت أي عدو الله قتلت جارنا والله لا تفارقني حتى يأتيك رجالنا قال هلال والمحور في يدي لم أضعه قال فهممت أن أعلوا به رأس خولة ثم قلت في نفسي عجوز لها سن وقرابة قال فضربتها برجلي ضربة رميت بها من بعيد ثم أتيت\nناقتي فأركبها ثم أضربها هاربا وجاء معاذ بن جعدة وإخوته وهم يومئذ تسعة إخوة وعبد الله بن مالك زوج لبنت معاذ ويقال لها جبيلة وهو مع ذلك ابن عمتهم خولة بنت يزيد بن ثابت فهو معهم كأنه بعضهم فجاءوا من آخر النهار فسمعوا الواعية على الجلاني وهو دنف لم يمت فسألوا عن تلك الواعية فأخبروا بما كان من استجارة الجلاني بمعاذ بن جعدة وضرب هلال له من بعد ذلك فركب الأخوة التسعة وعبد الله بن مالك عاشرهم وكانوا أمثال الجبال في شدة خلقهم مع نجدتهم وركبوا معهم بعشرة غلمة لهم أشد منهم خلقا لا يقع لأحد منهم سهم في غير موضع يريده من رميته حتى تبعوا هلالا وقد نسل هلال من الهرب يومه ذلك كله وليلته فلما أصبح أمنهم وظن أن قد أبعد في الأرض ونجا منهم وتبعوه فلما أصبحوا من تلك الليلة قصوا أثره وكان لا يخفى أثره على أحد لعظم قدمه فلحقوه من بعد الغد فلما أدركوه وهم عشرون ومعهم النبل والقسي والسيوف والترسة ناداهم يا بني جعدة إني أنشدكم الله أن أكون قتلت رجلا غريبا طلبته بترة تقتلوني وأنا ابن عمكم وظن أن الجلاني قد مات ولم يكن مات إلى أن تبعوه وأخذوه فقال معاذ والله لو أيقنا أنه قد مات ما ناظرنا بك القتل من ساعتنا ولكنا تركناه ولم يمت ولسنا نحب قتلك إلا أن تمتنع منا ولا نقدم عليك حتى نعلم ما يصنع جارنا فقاتلهم وامتنع منهم فجعل معاذ يقول لأصحابه وغلمانه لا ترموه بالنبل ولا تضربوه بالسيوف ولكن ارموه بالحجارة واضربوه بالعصي حتى تأخذوه ففعلوا ذلك فما قدروا على أخذه حتى كسروا من إحدى يديه ثلاث أصابع ومن الأخرى إصبعين ودقوا ضلعين من أضلاعه وأكثروا الشجاج في رأسه ثم أخذوه وما كادوا يقدرون على أخذه فوضعوا في رجله","topic":"أخبار هلال ونسبه","topicNo":19,"sp":3,"spl":"فرار هلال إلى اليمن"},
{"id":"b19-6","bab":"الجزء 3","sec":"فرار هلال إلى اليمن","page":"ج3 ص58","text":"أدهم ثم جاءوا به وهو معروض على بعير حتى انتهوا به إلى الوقبى فدفعوه إلى الجلاني ولم يمت بعد فقالوا انطلقوا به معكم إلى بلادكم ولا تحدثوا في أمره شيئا حتى تنظروا ما يصنع بصاحبكم فإن مات فاقتلوه وإن حيي فأعلمونا حتى نحمل لكم أرش الجناية فقال الجلانيون وفت ذمتكم يا بني جعدة وجزاكم الله أفضل ما يجزي به خيار الجيران إنا نتخوف أن ينزعه منا قومكم إن خليتم عنا وعنهم وهو في أيدينا فقال لهم معاذ فإني أحمله معكم وأشيعكم حتى تردوا بلادكم ففعلوا ذلك فحمل معروضا على بعير وركبت أخته جماء بنت الأسعر معه وجعل يقول قتلتني بنو جعدة وتأتيه أخته بمغرة فيشربها فيقال يمشي بالدم لأن بني جعدة فرثوا كبده في جوفه فلما بلغوا أدنى بلاد بكر بن وائل قال الجلانيون لمعاذ وأصحابه أدام الله عزكم وقد وفيتم فانصرفوا وجعل هلال يريهم أنه يمشي في الليلة عشرين مرة فلما ثقل الجلاني وتخوف هلال أن يموت من ليلته أو يصبح ميتا تبرز هلال كما كان يصنع وفي رجله الأدهم كأنه يقضي حاجة ووضع كساءه على عصاه في ليلة ظلماء ثم اعتمد على الأدهم فحطمه ثم طار تحت ليلته على رجليه وكان أدل الناس فتنكب الطريق التي تعرف ويطلب فيها وجعل يسلك المسالك التي لا يطمع فيها حتى انتهى إلى رجل من بني أثاثة بن مازن يقال له السعر بن يزيد بن طلق بن جبيلة بن أثاثة بن مازن فحمله السعر على ناقة له يقال لها ملوة فركبها ثم تجنب بها الطريق فأخذ نحو بلاد قيس بن عيلان تخوفا من بني مازن أن يتبعوه أيضا فيأخذوه فسار ثلاث\nليال وأيامها حتى نزل اليوم الرابع فنحر الناقة فأكل لحمها كله إلا فضلة فضلت منها فاحتملها ثم أتى بلاد اليمن فوقع بها فلبث زمانا وذلك عند مقام الحجاج بالعراق فبلغ إفلاته من بالبصرة من بكر بن وائل فانطلقوا إلى الحجاج فاستعدوه وأخبروه بقتله صاحبهم فبعث الحجاج إلى عبد الله بن شعبة بن العلقم وهو يومئذ عريف بني مازن حاضرتهم وباديتهم فقال له لتأتيني بهلال أو لأفعلن بك ولأفعلن فقال له عبد الله بن شعبة إن أصحاب هلال وبني عمه قد صنعوا كذا وكذا فاقتص عليه ما صنعوا في طلبه وأخذه ودفعه إلى الجلانيين وتشييعهم إياه حتى وردوا بلاد بكر بن وائل فقال له الحجاج ويلك ما تقول قال فقال بعض البكريين صدق أصلح الله الأمير قال فقال الحجاج فلا يرغم الله إلا أنوفكم اشهدوا أني قد آمنت كل قريب لهلال وحميم وعريف ومنعت من أخذ أحد به ومن طلبه حتى يظفر به البكريون أو يموت قبل ذلك فلما وقع هلال إلى بلاد اليمن بعث إلى بني رزام بن مازن بشعر يعاتبهم فيه ويعظم عليهم حقه ويذكر قرابته وذلك أن سائر بني مازن قاموا ليحملوا ذلك الدم فقال معاذ لا أرضى والله أن يحمل لجاري دم واحد حتى يحمل له دم ولجواري دم آخر وإن أراد هلال الأمان وسطنا حمل له دم ثالث فقال هلال في ذلك\n(بني مازن لا تطردوني فإنني ... أخوكم وإن جرت جرائرها يدي)\n(ولا تثلجوا أكباد بكر بن وائل ... بترك أخيكم كالخليع المطرد)\n(ولا تجعلوا حفظي بظهر وتحفظوا ... بعيدا ببغضاء يروح ويغتدي)\n(فإن القريب حيث كان قريبكم ... وكيف بقطع الكف من سائر اليد)\n(وإن البعيد إن دنا فهو جاركم ... وإن شط عنكم فهو أبعد أبعد)\n(وإني وإن أوجدتموني لحافظ ... لكم حفظ راض عنكم غير موجد)\n(سيحمي حماكم بي وإن كنت غائبا ... أغر إذا ما ريع لم يتبلد)\n(وتعلم بكر أنكم حيث كنتم ... وكنت من الأرض الغريبة محتدي)\n(وأني ثقيل حيث كنت على العدا ... وأني وإن أوحدت لست بأوحد)\n(وأنهم لما أرادوا هضيمتي ... منوا بجميع القلب عضب مهند)\n(حسام متى يعزم على الأمر يأته ... ولم يتوقف للعواقب في غد)\n(وهم بدؤوا بالبغي حتى إذا جزوا ... بأفعالهم قالوا لجازيهم قد)\n(فلم يك منهم في البديهة منصف ... ولم يك فيهم في العواقب مهتدي)\n(ولم يفعلوا فعل الحليم فيجملوا ... ولم يفعلوا فعل العزيز المؤيد)\n(فإن يسر لي إيعاد بكر فربما ... منعت الكرى بالغيظ من متوعد)\n(ورب حمى قوم أبحت ومورد ... وردت بفتيان الصباح ومورد)\n(وسجف دجوجي من الليل حالك ... رفعت بعجلى الرجل موارة اليد)\n(سفينة خواض بحور همومه ... قليل التياث العزم عند التردد)\n(جسور على الأمر المهيب إذا ونى ... أخو الفتك ركاب قرى المتهدد)\nوقال وهو بأرض اليمن\n(أقول وقد جاوزت نعمى وناقتي ... تحن إلى جنبي فليج مع الفجر)","topic":"أخبار هلال ونسبه","topicNo":19,"sp":4,"spl":"فرار هلال إلى اليمن"},
{"id":"b19-7","bab":"الجزء 3","sec":"فرار هلال إلى اليمن","page":"ج3 ص58","text":"(سقى الله يا ناق البلاد التي بها ... هواك وإن عنا نأت سبل القطر)\n(فما عن قلى منا لها خفت النوى ... بنا عن مراعيها وكثبانها العفر)\n(ولكن صرف الدهر فرق بيننا ... وبين الأداني والفتى غرض الدهر)\n(فسقيا لصحراء الإهالة مربعا ... وللوقبى من منزل دمث مثري)\n(وسقيا ورعيا حيث حلت لمازن ... وأيامها الغر المجلة الزهر)\nال خالد بن كلثوم ولما دفع هلال إلى أولياء الجلاني ليقتلوه بصاحبهم جاء رجل يقال له حفيد كان هلال قد وتره فقال والله لأؤنبنه ولأصغرن إليه نفسه وهو في القيود مصبور للقتل فأتاه فلم يدع له شيئا مما يكره إلا عده عليه قال وإلى جنب هلال حجر يملأ الكف فأخذه هلال فأهوى به للرجل فأصاب جبينه فاجتلف جلفة من وجهه ورأسه ثم رمى بها وقال خذ القصاص مني الآن وأنشأ يقول\n(أنا ضربت كربا وزيدا ... وثابتا مشيتهم رويدا)\n(كما أفدت حينه عبيدا ... وقد ضربت بعده حفيدا)\nقال وهؤلاء كلهم من بني رزام بن مازن وكلهم كان هلال قد نكأ فيهم","topic":"أخبار هلال ونسبه","topicNo":19,"sp":5,"spl":"فرار هلال إلى اليمن — حبسه ثم الإفراج عنه بعد افتدائه"},
{"id":"b19-8","bab":"الجزء 3","sec":"هلال يمدح الديسم لأنه أدى عنه الدية","page":"ج3 ص65","text":"قال خالد بن كلثوم ولما طال مقام هلال باليمن نهضت بنو مازن بأجمعهم إلى بني رزام بن مازن رهط هلال ورهط معاذ بن جعدة جار الجلاني المقتول فقالوا إنكم قد أسأتم بابن عمكم وجزتم الحد في الطلب بدم جاركم فنحن نحمل لكم ما أردتم فحمل ديسم بن المنهال بن خزيمة بن شهاب بن أثاثة بن ضباب بن حجية بن كابية بن حرقوص بن مازن الذي طلب معاذ بن جعدة أن يحمل لجاره لفضل عزه وموضعه في عشيرته وكان الذي طلب ثلثمائة بعير فقال هلال في ذلك\n(إن ابن كابية المرزأ ديسما ... واري الزناد بعيد ضوء النار)\n(من كان يحمل ما تحمل ديسم ... من حائل فنق وأم حوار)\n(عيت بنو عمرو بحمل هنائد ... فيها العشار ملابيء الأبكار)\n(حتى تلافاها كريم سابق ... بالخير حل منازل الأخيار)\n(حتى إذا وردت جميعا أرزمت ... جلان بعد تشمس ونفار)\n(ترعى بصحراء الإهالة روبة ... والعنظوان منابت الجرجار)\nوقال خالد بن كثلوم كان قيمر بن سعد مصدقا على بكر بن وائل فوجد منهم رجلا قد سرق صدقته فأخذه قمير ليحبسه فوثب قومه وأرادوا أن يحولوا بين قمير وبينه وهلال حاضر فلما رأى ذلك هلال وثب على البكريين فجعل يأخذ الرجلين منهم فيكنفهما ويناطح بين رؤوسهما فانتهى إلى قمير أعوانه فقهروا البكريين فقال هلال في ذلك\n(دعاني قمير دعوة فأجبته ... فأي امريء في الحرب حين دعاني)\n(معي مخذم قد أخلص القين حده ... يخفض عند الروع روع جناني)\n(وما زلت مذ شدت يميني حجزتي ... أحارب أو في ظل حرب تراني)","topic":"أخبار هلال ونسبه","topicNo":19,"sp":5,"spl":"فرار هلال إلى اليمن — حبسه ثم الإفراج عنه بعد افتدائه"},
{"id":"b19-9","bab":"الجزء 3","sec":"حبسه ثم الإفراج عنه بعد افتدائه","page":"ج3 ص66","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا حكيم بن سعد عن زفر بن هبيرة قال تقاوم هلال بن أسعر المازني وهو أحد بني رزام بن مازن ونييس الجلاني من عنزة وهما يسقيان إبلهما فحذف هلال نهيسا بمحور في يده فأصابه فمات فاستعدى ولده بلال بن أبي بردة على هلال فحبسه فأسلمه قومه بنو رزام وعمل في أمره ديسم ابن المنهال أحد بني كابية بن حرقوص فافتكه بثلاث ديات فقال هلال يمدحه\n(تدارك ديسم حسبا ومجدا ... رزاما بعد ما انشقت عصاها)\n(همو حملوا المئين فألحقوها ... بأهليها فكان لهم سناها)\n(وما كانت لتحملها رزام ... بأستاه معقصة لحاها)\n(بكابية بن حرقوص وجد ... كريم لا فتى إلا فتاها)","topic":"أخبار هلال ونسبه","topicNo":19,"sp":5,"spl":"فرار هلال إلى اليمن — حبسه ثم الإفراج عنه بعد افتدائه"},
{"id":"b19-10","bab":"الجزء 3","sec":"نهم هلال وكثرة أكله","page":"ج3 ص67","text":"أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري قالا حدثنا إسماعيل بن إسحاق القاضي قال حدثني نصر بن علي الجهضمي قال حدثنا الأصمعي وأخبرني أبو عبيد محمد بن أحمد بن المؤمل الصيرفي قال حدثنا فضل بن الحسن قال حدثنا نصر بن علي عن الأصمعي قال حدثنا المعتمر بن سليمان قال قلت لهلال بن أسعر ما أكلة أكلتها بلغتني عنك قال جعت مرة ومعي بعيري فنحرته وأكلته إلا ما حملت منه على ظهري قال أبو عبيد في حديثه عن فضل ثم أردت امرأتي فلم أقدر على جماعها فقالت لي ويحك كيف تصل إلي وبيني وبينك بعير قال المعتمر فقلت له كم تكفيك هذه الأكلة قال أربعة أيام وحدثني به ابن عمار قال حدثني عبد الله بن أبي سعد قال حدثني أحمد بن معاوية عن الأصمعي عن معتمر بن سليمان عن أبيه قال قلت لهلال بن الأسعر هكذا قال ابن أبي سعد معتمر عن أبيه وقال في خبره فقلت له كم تكفيك هذه الأكلة فقال خمسا أخبرني أحمد بن عبد العزيز قال حدثنا إسماعيل بن إسحاق القاضي قال حدثنا نصر بن علي قال حدثني الأصمعي قال حدثني شيخ من بني مازن قال أتانا هلال بن أسعر المازني فأكل جميع ما في بيتنا فبعثنا إلى الجيران\nنقترض الخبز فلما رأى الخبز قد اختلف عليه قال كأنكم أرسلتم إلى الجيران أعندكم سويق قلنا نعم فجئته بجراب طويل فيه سويق وببرنية نبيذ فصب السويق كله وصب عليه النبيذ حتى أتى على السويق والنبيذ كله أخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثنا أحمد بن الحارث عن المدائني أن هلال بن أسعر مر على رجل من بني مازن بالبصرة وقد حمل من بستانه رطبا في زواريق فجلس على زورق صغير منها وقد كثب الرطب فيه وغطي بالبواري قال له يابن عم آكل من رطبك هذا قال نعم قال ما يكفيني قال ما يكفيك فجلس على صدر الزورق وجعل يأكل إلى أن اكتفى ثم قام فانصرف فكشف الزورق فإذا هو مملؤ نوى قد أكل رطبه وألقى النوى فيه قال المدائني وحدثني من سأله عن أعجب شيء أكله فقال مائتي رغيف مع مكوك ملح أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عبد الله بن أبي سعد قال حدثني الحسن بن علي بن منصور الأهوازي وكان كهلا سريا معدلا قال حدثني شبان النيلي عن صدقة بن عبيد المازني قال\nأولم علي أبي لما تزوجت فعملنا عشر جفان ثريدا من جزور فكان أول من جاءنا هلال بن أسعر المازني فقدمنا إليه جفنة فأكلها ثم أخرى ثم أخرى حتى أتى على العشر ثم استسقى فأتي بقربة من نبيذ فوضع طرفها في شدقه ففرغها في جوفه ثم قام فخرج فاستأنفنا عمل الطعام","topic":"أخبار هلال ونسبه","topicNo":19,"sp":6,"spl":"نهم هلال وكثرة أكله"},
{"id":"b19-11","bab":"الجزء 3","sec":"هلال أطول الناس قامة","page":"ج3 ص69","text":"أخبرني الجوهري قال حدثنا إسماعيل بن إسحاق قال حدثنا نصر بن علي عن الأصمعي قال حدثني أبو عمرو بن العلاء قال رأيت هلال بن أسعر ميتا ولم أره حيا فما رأيت أحدا على سرير أطول منه أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد قال حدثني بعض حاشية السلطان قال غنى إبراهيم الموصلي الرشيد يوما\n(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\nال والصنعة فيه لرجل من أهل الكوفة يقال له عزون فأعجب به الرشيد وطرب له واستعاده مرارا فقال له الموصلي يا أمير المؤمنين فكيف لو سمعته من عبدك مخارق فإنه أخذه عني وهو يفضل فيه الخلق جميعا ويفضلني فأمر بإحضار مخارق فأحضر فقال له غنني\n(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\nفغناه إياه فبكى وقال سل حاجتك قال مخارق فقلت تعتقني يا أمير المؤمنين من الرق وتشرفني بولائك أعتقك الله من النار قال أنت حر لوجه الله أعد الصوت قال فأعدته فبكى وقال سل حاجتك فقلت يا أمير المؤمنين ضيعة تقيمني غلتها فقال قد أمرت لك بها أعد الصوت فأعدته فبكى وقال سل حاجتك فقلت يأمر لي أمير المؤمنين بمنزل وفرشه وما يصلحه وخادم فيه قال ذلك لك أعده فأعدته فبكى وقال سل حاجتك قلت حاجتي يا أمير المؤمنين أن يطيل الله بقاءك ويديم عزك ويجعلني من كل سوء فداءك قال فكان إبراهيم الموصلي سبب عتقه بهذا الصوت أخبرني بهذا الخبر محمد بن خلف وكيع قال حدثني هارون بن مخارق وحدثني به الصولي أيضا عن وكيع عن هارون بن مخارق قال كان أبي إذا غنى هذا الصوت\n(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\nقول أنا مولى هذا الصوت فقلت له يوما يا أبت وكيف ذلك فقال غنيته مولاي الرشيد فبكى وقال أحسنت أعد فأعدت فبكى وقال أحسنت أنت حر لوجه الله وأمر لي بخمسة آلاف دينار فأنا مولى هذا الصوت بعد مولاي وذكر قريبا مما ذكره المبرد من باقي الخبر حدثني الحسن بن علي قال حدثنا ابن أبي الدنيا قال حدثني إسحاق النخعي عن حسين بن الضحاك عن مخارق\nأن الرشيد أقبل يوما على المغنين وهو مضطجع فقال من منكم يغني\n(يا ربع سلمى لقد هيجت لي طربا ... زدت الفؤاد على علاته وصبا)\nال فقمت فقلت أنا فقال هاته فغنيته فطرب وشرب ثم قال علي بهرثمة فقلت في نفسي ما تراه يريد منه فجاؤوا بهرثمة فأدخل إليه وهو يجر سيفه فقال يا هرثمة مخارق الشاري الذي قتلناه بناحية الموصل ما كانت كنيته فقال أبو المهنا فقال انصرف فانصرف ثم أقبل علي فقال قد كنيتك أبا المهنا لإحسانك وأمر لي بمائة ألف درهم فانصرفت بها وبالكنية","topic":"أخبار هلال ونسبه","topicNo":19,"sp":7,"spl":"هلال أطول الناس قامة"},
{"id":"b20-1","bab":"الجزء 3","sec":"صوت من المائة المختارة من رواية جحظة عن أصحابه","page":"ج3 ص71","text":"(وخل كنت عين الرشد منه ... إذا نظرت ومستمعا سميعا)\n(أطاف بغيه فعدلت عنه ... وقلت له أرى أمرا فظيعا)\nلشعر لعروة بن الورد والغناء في اللحن المختار لسياط ثاني ثقيل بالبنصر عن عمرو بن بانة وفيه لإبراهيم ماخوري بالوسطى عن عمرو أيضا","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة عن أصحابه — خبر عروة مع سبيته سلمى"},
{"id":"b20-2","bab":"الجزء 3","sec":"أخبار عروة بن الورد ونسبه","page":"ج3 ص72","text":"عروة بن الورد بن زيد وقيل ابن عمرو بن زيد بن عبد الله بن ناشب بن هريم بن لديم بن عوذ بن غالب بن قطيعة بن عبس بن بغيض بن الريث بن غطفان بن سعد بن قيس بن عيلان بن مضر بن نزار شاعر من شعراء الجاهلية وفارس من فرسانها وصعلوك من صعاليكها المعدودين المقدمين الأجواد وكان يلقب عروة الصعاليك لجمعه إياهم وقيامه بأمرهم إذا أخفقوا في غزواتهم ولم يكن لهم معاش ولا مغزى وقيل بل لقب عروة الصعاليك لقوله\n(لحى الله صعلوكا إذا جن ليله ... مصافي المشاش آلفا كل مجزر)\n(يعد الغنى من دهره كل ليلة ... أصاب قراها من صديق ميسر)\n(ولله صعلوك صفيحة وجهه ... كضوء شهاب القابس المتنور)\nخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال بلغني أن معاوية قال لو كان لعروة بن الورد ولد لأحببت أن أتزوج إليهم أخبرني محمد بن خلف قال حدثنا أحمد بن الهيثم بن فراس قال حدثني\nالعمري عن الهيثم بن عدي وحدثنا إبراهيم بن أيوب عن عبد الله بن مسلم قالا جميعا قال عبد الملك بن مروان ما يسرني أن أحدا من العرب ولدني ممن لم يلدني إلا عروة بن الورد لقوله\n(إني امرؤ عافي إنائي شركة ... وأنت امرؤ عافي إنائك واحد)\n(أتهزأ مني أن سمنت وأن ترى ... بجسمي مس الحق والحق جاهد)\n(أفرق جسمي في جسوم كثيرة ... وأحسو قراح الماء والماء بارد)\nخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة قال بلغني أن عمر بن الخطاب رضي الله عنه قال للحطيئة كيف كنتم في حربكم قال كنا ألف حازم قال وكيف قال كان فينا قيس بن زهير وكان حازما وكنا لا نعصيه وكنا نقدم إقدام عنترة ونأتم بشعر عروة بن الورد وننقاد لأمر الربيع بن زياد","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة عن أصحابه — خبر عروة مع سبيته سلمى"},
{"id":"b20-3","bab":"الجزء 3","sec":"عبد الملك يقول عروة أسمح الناس","page":"ج3 ص73","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال ويقال إن عبد الملك قال من زعم أن حاتما أسمح الناس فقد ظلم عروة ابن الورد أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال أخبرنا إبراهيم بن المنذر قال حدثنا معن بن عيسى قال\nسمعت أن عبد الله بن جعفر بن أبي طالب قال لمعلم ولده لا تروهم قصيدة عروة بن الورد التي يقول فيها\n(دعيني للغنى أسعى فإني ... رأيت الناس شرهم الفقير)\nيقول إن هذا يدعوهم إلى الاغتراب عن أوطانهم","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة عن أصحابه — خبر عروة مع سبيته سلمى"},
{"id":"b20-4","bab":"الجزء 3","sec":"خبر عروة مع سبيته سلمى","page":"ج3 ص73","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني محمد بن يحيى قال حدثني عبد العزيز بن عمران الزهري عن عامر بن جابر قال أغار عروة بن الورد على مزينة فأصاب منهم امرأة من كنانة ناكحا فاستاقها ورجع وهو يقول\n(تبغ عديا حيث حلت ديارها ... وأبناء عوف في القرون الأوائل)\n(فإلا أنل أوسا فإني حسبها ... بمنبطح الأدغال من ذي السلائل)\nم أقبل سائرا حتى نزل ببني النضير فلما رأوها أعجبتهم فسقوه الخمر ثم استوهبوها منه فوهبها لهم وكان لا يمس النساء فلما أصبح وصحا ندم فقال\n(سقوني الخمر ثم تكنفوني ... )\nلأبيات قال وجلاها النبي مع من جلا من بني النضير","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة عن أصحابه — خبر عروة مع سبيته سلمى","partialRef":{"sid":"b17-6","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b20-5","bab":"الجزء 3","sec":"سلمى تثني عليه بعد رفضها العودة معه","page":"ج3 ص74","text":"وذكر أبو عمرو الشيباني من خبر عروة بن الورد وسلمى هذه أنه أصاب امرأة\nمن بني كنانة بكرا يقال لها سلمى وتكنى أم وهب فأعتقها واتخذها لنفسه فمكثت عنده بضع عشرة سنة وولدت له أولادا وهو لا يشك في أنها أرغب الناس فيه وهي تقول له لو حججت بي فأمر على أهلي وأراهم فحج بها فأتى مكة ثم أتى المدينة وكان يخالط من أهل يثرب بني النضير فيقرضونه إن احتاج ويبايعهم إذا غنم وكان قومها يخالطون بني النضير فأتوهم وهو عندهم فقالت لهم سلمى إنه خارج بي قبل أن يخرج الشهر الحرام فتعالوا إليه وأخبروه أنكم تستحيون أن تكون امرأة منكم معروفة النسب صحيحته سبية وافتدوني منه فإنه لا يرى أني أفارقه ولا أختار عليه أحدا فأتوه فسقوه الشراب فلما ثمل قالوا له فادنا بصاحبتنا فإنها وسطة النسب فينا معروفة وإن علينا سبة أن تكون سبية فإذا صارت إلينا وأردت معاودتها فاخطبها إلينا فإننا ننكحك فقال لهم ذاك لكم ولكن لي الشرط فيها أن تخيروها فإن اختارتني انطلقت معي إلى ولدها وإن اختارتكم انطلقتم بها قالوا ذاك لك قال دعوني أله بها الليلة وأفادها غدا فلما كان الغد جاءوه فامتنع من فدائها فقالوا له قد فاديتنا به منذ البارحة وشهد عليه بذلك جماعة ممن حضر فلم يقدر على الامتناع وفاداها فلما فادوه بها خيروها فاختارت أهلها ثم أقبلت عليه فقالت يا عروة أما إني أقول فيك وإن فارقتك الحق والله ما أعلم امرأة من العرب ألقت سترها على بعل خير منك وأغض طرفا وأقل فحشا وأجود يدا وأحمى لحقيقة وما مر علي يوم منذ كنت عندك إلا والموت فيه أحب إلي من الحياة بين قومك لأني لم أكن أشاء أن أسمع امرأة من قومك تقول قالت أمة عروة كذا وكذا إلا سمعته ووالله لا أنظر في وجه\nغطفانية أبدا فارجع راشدا إلى ولدك وأحسن إليهم فقال عروة في ذلك\n(سقوني الخمر ثم تكنفوني ... )\nأولها\n(أرقت وصحبتي بمضيق عمق ... لبرق من تهامة مستطير)\n(سقى سلمى وأين ديار سلمى ... إذا كانت مجاورة السرير)\n(إذا حلت بأرض بني علي ... وأهلي بين إمرة وكير)\n(ذكرت منازلا من أم وهب ... محل الحي أسفل من نقير)\n(وأحدث معهد من أم وهب ... معرسنا بدار بني النضير)\n(وقالوا ما تشاء فقلت ألهو ... إلى الإصباح آثر ذي أثير)\n(بآنسة الحديث رضاب فيها ... بعيد النوم كالعنب العصير)\nأخبرني علي بن سليمان الأخفش عن ثعلب عن ابن الأعرابي بهذه الحكاية كما ذكر أبو عمرو وقال فيها إن قومها أغلوا بها الفداء وكان معه طلق وجبار أخوه وابن عمه فقالا له والله لئن قبلت ما أعطوك لا تفتقر أبدا وأنت على النساء قادر متى شئت وكان قد سكر فأجاب إلى فدائها فلما صحا ندم فشهدوا عليه بالفداء فلم يقدر على الامتناع وجاءت سلمى تثني عليه فقالت والله إنك ما علمت لضحوك مقبلا كسوب مدبرا خفيف على متن الفرس ثقيل على العدو طويل\nالعماد كثير الرماد راضي الأهل والجانب فاستوص ببنيك خيرا ثم فارقته فتزوجها رجل من بني عمها فقال لها يوما من الأيام يا سلمى أثني علي كما أثنيت على عروة وقد كان قولها فيه شهر فقالت له لا تكلفني ذلك فإني إن قلت الحق غضبت ولا واللات والعزى لا أكذب فقال عزمت عليك لتأتيني في مجلس قومي فلتثنين علي بما تعلمين وخرج فجلس في ندي القوم وأقبلت فرماها القوم بأبصارهم فوقفت عليهم وقالت أنعموا صباحا إن هذا عزم علي أن أثني عليه بما أعلم ثم أقبلت عليه فقالت والله إن شملتك لالتحاف وإن شربك لاشتفاف وإنك لتنام ليلة تخاف وتشبع ليلة تضاف وما ترضي الأهل ولا الجانب ثم انصرفت فلامه قومه وقالوا ما كان أغناك عن هذا القول منها","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":1,"spl":"سلمى تثني عليه بعد رفضها العودة معه","partialRef":{"sid":"b17-6","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b20-6","bab":"الجزء 3","sec":"عروة يخرج صعاليك","page":"ج3 ص77","text":"أخبرني الأخفش عن ثعلب عن ابن الأعرابي قال حدثني أبو فقعس قال كان عروة بن الورد إذا أصابت الناس سنة شديدة تركوا في دارهم المريض والكبير والضعيف وكان عروة بن الورد يجمع أشباه هؤلاء من دون الناس من عشيرته في الشدة ثم يحفر لهم الأسراب ويكنف عليهم الكنف ويكسبهم ومن قوي منهم إما مريض يبرأ من مرضه أو ضعيف تثوب قوته خرج به معه فأغار وجعل لأصحابه الباقين في ذلك نصيبا حتى إذا أخصب الناس وألبنوا\nوذهبت السنة الحق كل إنسان بأهله وقسم له نصيبه من غنيمة إن كانوا غنموها فربما أتى الإنسان منهم أهله وقد استغنى فلذلك سمي عروة الصعاليك فقال في ذلك بعض السنين وقد ضاقت حاله\n(لعل ارتيادي في البلاد وبغيتي ... وشدي حيازيم المطية بالرحل)\n(سيدفعني يوما إلى رب هجمة ... يدافع عنها بالعقوق وبالبخل)\nزعموا أن الله عز و جل قيض له وهو مع قوم من هلاك عشيرته في شتاء شديد ناقتين دهماوين فنحر لهم إحداهما وحمل متاعهم وضعفاءهم على الأخرى وجعل ينتقل بهم من مكان إلى مكان وكان بين النقرة والربذة فنزل بهم ما بينهما بموضع يقال له ماوان ثم إن الله عز و جل قيض له رجلا صاحب مائة من الإبل قد فر بها من حقوق قومه وذلك أول ما ألبن الناس فقتله وأخذ إبله وامرأته وكانت من أحسن النساء فأتى بالإبل أصحاب الكنيف فحلبها وحملهم عليها حتى إذا دنوا من عشيرتهم أقبل يقسمها بينهم وأخذ مثل نصيب أحدهم فقالوا لا واللات والعزى لا نرضى حتى تجعل المرأة نصيبا فمن شاء أخذها فجعل يهم بأن يحمل عليهم فيقتلهم وينتزع الإبل منهم ثم يذكر أنهم صنيعته وأنه إن فعل ذلك أفسد ما كان يصنع فأفكر طويلا ثم أجابهم إلى أن يرد عليهم الإبل إلا راحلة يحمل عليها المرأة حتى يلحق بأهله فأبوا ذلك عليه حتى انتدب رجل منهم فجعل له راحلة من نصيبه فقال عروة في ذلك قصيدته التي أولها\n(ألا إن أصحاب الكنيف وجدتهم ... كما الناس لما أمرعوا وتمولوا)\n(وإني لمدفوع إلي ولاؤهم ... بماوان إذ نمشي وإذ نتململ)\n(وإني وإياهم كذي الأم أرهنت ... له ماء عينيها تفدي وتحمل)\n(فباتت بحد المرفقين كليهما ... توحوح مما نالها وتولول)\n(تخير من أمرين ليسا بغبطة ... هو الثكل إلا أنها قد تجمل)","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":2,"spl":"عروة يخرج صعاليك"},
{"id":"b20-7","bab":"الجزء 3","sec":"قوله في ليلى","page":"ج3 ص79","text":"وقال ابن الأعرابي في هذه الرواية أيضا كان عروة قد سبى امرأة من بني هلال بن عامر بن صعصعة يقال لها ليلى بنت شعواء فمكثت عنده زمانا وهي معجبة له تريه أنها تحبه ثم استزارته أهلها فحملها حتى أتاهم بها فلما أراد الرجوع أبت أن ترجع معه وتوعده قومها بالقتل فانصرف عنهم وأقبل عليها فقال لها يا ليلى خبري صواحبك عني كيف أنا فقالت ما أرى لك عقلا أتراني قد اخترت عليك وتقول خبري عني فقال في ذلك\n(تحن إلى ليلى بجو بلادها ... وأنت عليها بالملا كنت أقدرا)\n(وكيف ترجيها وقد حيل دونها ... وقد جاوزت حيا بتيماء منكرا)\n(لعلك يوما أن تسري ندامة ... علي بما جشمتني يوم غضورا)\nهي طويلة قال ثم إن بني عامر أخذوا امرأة من بني عبس ثم من بني سكين يقال لها أسماء فما لبثت عندهم إلا يوما حتى استنقذها قومها فبلغ عروة أن عامر بن الطفيل فخر بذلك وذكر أخذه إياها فقال عروة يعيرهم بأخذه ليلى بنت شعواء الهلالية\n(إن تأخذوا أسماء موقف ساعة ... فمأخذ ليلى وهي عذراء أعجب)\n(لبسنا زمانا حسنها وشبابها ... وردت إلى شعواء والرأس أشيب)\n(كمأخذنا حسناء كرها ودمعها ... غداة اللوى معصوبة يتصبب)\nوقال ابن الأعرابي أجدب ناس من بني عبس في سنة أصابتهم فأهلكت أموالهم وأصابهم جوع شديد وبؤس فأتوا عروة بن الورد فجلسوا أمام بيته فلما بصروا به صرخوا وقالوا يا أبا الصعاليك أغثنا فرق لهم وخرج ليغزو بهم ويصيب معاشا فنهته امرأته عن ذلك لما تخوفت عليه من الهلاك فعصاها وخرج غازيا فمر بمالك بن حمار الفزاري ثم الشمخي فسأله أين يريد فأخبره فأمر له بجزور فنحرها فأكلوا منها وأشار عليه مالك أن يرجع فعصاه ومضى حتى انتهى إلى بلاد بني القين فأغار عليهم فأصاب هجمة عاد بها على نفسه وأصحابه وقال في ذلك\n(أرى أم حسان الغداة تلومني ... تخوفني الأعداء والنفس أخوف)\n(تقول سليمى لو أقمت لسرنا ... ولم تدر أني للمقام أطوف)\n(لعل الذي خوفتنا من أمامنا ... يصادفه في أهله المتخلف)\nهي طويلة وقال في ذلك أيضا\n(أليس ورائي أن أدب على العصا ... فيشمت أعدائي ويسأمني أهلي)\n(رهينة قعر البيت كل عشية ... يطيف بي الولدان أهدج كالرأل)\n(أقيموا بني لبنى صدور ركابكم ... فكل منايا النفس خير من الهزل)\n(فإنكم لن تبلغوا كل همتي ... ولا أربي حتى تروا منبت الأثل)\n(لعل ارتيادي في البلاد وحيلتي ... وشدي حيازيم المطية بالرحل)\n(سيدفعني يوما إلى رب هجمة ... يدافع عنها بالعقوق وبالبخل)","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":3,"spl":"قوله في ليلى"},
{"id":"b20-8","bab":"الجزء 3","sec":"حديث عروة مع الهذلي الذي أخذ فرسه","page":"ج3 ص81","text":"نسخت من كتاب أحمد بن القاسم بن يوسف قال حدثني حر بن قطن أن ثمامة بن الوليد دخل على المنصور فقال يا ثمامة أتحفظ حديث ابن عمك عروة الصعاليك بن الورد العبسي فقال أي حديثه يا أمير المؤمنين فقد كان كثير الحديث حسنه قال حديثه مع الهذلي الذي أخذ فرسه قال ما يحضرني ذلك فأرويه يا أمير المؤمنين فقال المنصور خرج عروة حتى دنا من منازل هذيل فكان منها على نحو ميلين وقد جاع فإذا هو بأرنب فرماها ثم أورى نارا فشواها وأكلها ودفن النار على مقدار ثلاث أذرع وقد ذهب الليل وغارت النجوم ثم أتى سرحة فصعدها وتخوف الطلب فلما تغيب فيها إذا الخيل قد جاءت وتخوفوا البيات قال فجاءت جماعة منهم ومعهم رجل على فرس فجاء حتى ركز رمحه في موضع النار وقال لقد رأيت النار ها هنا فنزل رجل فحفر قدر ذراع فلم يجد شيئا فأكب القوم على الرجل يعذلونه ويعيبون أمره ويقولون عنيتنا في مثل هذه الليلة القرة وزعمت لنا شيئا كذبت فيه فقال ما كذبت ولقد رأيت النار في موضع رمحي فقالوا ما رأيت شيئا ولكن تحذلقك وتدهيك هو الذي حملك على\nهذا وما نعجب إلا لأنفسنا حين أطعنا أمرك واتبعناك ولم يزالوا بالرجل حتى رجع عن قوله لهم واتبعهم عروة حتى إذا وردوا منازلهم جاء عروة فتمكن في كسر بيت وجاء الرجل إلى امرأته وقد خالفه إليها عبد أسود وعروة ينظر فأتاها العبد بعلبة فيها لبن فقال اشربي فقالت لا أوتبدأ فبدأ الأسود فشرب فقالت للرجل حين جاء لعن الله صلفك عنيت قومك منذ الليلة قال لقد رأيت نارا ثم دعا بالعلبة ليشرب فقال حين ذهب ليكرع ريح رجل وب الكعبة فقالت امرأته وهذه أخرى أي ريح رجل تجده في إنائك غير ريحك ثم صاحت فجاء قومها فأخبرتهم خبره فقالت يتهمني ويظن بي الظنون فأقبلوا عليه باللوم حتى رجع عن قوله فقال عروة هذه ثانية قال ثم أوى الرجل إلى فراشه فوثب عروة إلى الفرس وهو يريد أن يذهب به فضرب الفرس بيده وتحرك فرجع عروة إلى موضعه ووثب الرجل فقال ما كنت لتكذبني فمالك فأقبلت عليه امرأته لوما وعذلا قال فصنع عروة ذلك ثلاثا وصنعه الرجل ثم أوى الرجل إلى فراشه وضجر من كثرة ما يقوم فقال لا أقوم إليك الليلة وأتاه عروة فحال في متنه وخرج ركضا وركب الرجل فرسا عنده أنثى قال عروة فجعلت أسمعه خلفي يقول الحقي فإنك من نسله فلما انقطع عن البيوت قال له عروة بن الورد أيها الرجل قف فإنك لو عرفتني لم تقدم علي أنا عروة بن الورد وقد رأيت الليلة منك عجبا فأخبرني به وأرد إليك فرسك قال وما هو قال جئت مع قومك حتى ركزت رمحك في موضع نار قد كنت أوقدتها فثنوك عن ذلك فانثنيت وقد صدقت ثم اتبعتك حتى أتيت منزلك وبينك وبين النار ميلان فأبصرتها منهما ثم شممت رائحة رجل في إنائك وقد رأيت الرجل حين آثرته زوجتك بالإناء وهو عبدك الأسود وأظن أن بينهما ما لا تحب فقلت ريح\nرجل فلم تزل تثنيك عن ذلك حتى انثنيت ثم خرجت إلى فرسك فأردته فاضطرب وتحرك فخرجت إليه ثم خرجت وخرجت ثم أضربت عنه فرأيتك في هذه الخصال أكمل الناس ولكنك تنثني وترجع فضحك وقال ذلك لأخوال السوء والذي رأيت من صرامتي فمن قبل أعمامي وهم هذيل وما رأيت من كعاعتي فمن قبل أخوالي وهم بطن من خزاعة والمرأة التي رأيت عندي امرأة منهم وأنا نازل فيهم فذلك الذي يثنيني عن أشياء كثيرة وأنا لاحق بقومي وخارج عن أخوالي هؤلاء ومخل سبيل المرأة ولولا رأيت من كعاعتي لم يقو على مناوأة قومي أحد من العرب فقال عروة خذ فرسك راشدا قال ما كنت لآخذه منك وعندي من نسله جماعة مثله فخذه مباركا لك فيه قال ثمامة إن له عندنا أحاديث كثيرة ما سمعنا له بحديث هو أظرف من هذا","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":4,"spl":"حديث عروة مع الهذلي الذي أخذ فرسه"},
{"id":"b20-9","bab":"الجزء 3","sec":"عروة يتعرف على ابن له","page":"ج3 ص83","text":"قال المنصور أفلا أحدثك له بحديث هو أظرف من هذا قال بلى يا أمير المؤمنين فإن الحديث إذا جاء منك كان له فضل على غيره قال خرج عروة وأصحابه حتى أتى ماوان فنزل أصحابه وكنف عليهم كنيفا من الشجر وهم أصحاب الكنيف الذي سمعته قال فيهم\n(ألا إن أصحاب الكنيف وجدتهم ... كما الناس لما أمرعوا وتمولوا)\nفي هذه الغزاة يقول عروة\n(أقول لقوم في الكنيف تروحوا ... عشية قلنا حول ماوان رزح)\nوفي هذه القصيدة يقول\n(ليبلغ عذرا أو يصيب غنيمة ... ومبلغ نفس عذرها مثل منجح)\nم مضى يبتغي لهم شيئا وقد جهدوا فإذا بأبيات شعر وبامرأة قد خلا من سنها وشيخ كبير كالحقاء الملقى فكمن في كسر بيت منها وقد أجدب الناس وهلكت الماشية فإذا هو في البيت بسحور ثلاثة مشوية فقال ثمامة وما السحور قال الحلقوم بما فيه والبيت خال فأكلها وقد مكث قبل ذلك يومين لا يأكل شيئا فأشبعته وقوي فقال لا أبالي من لقيت بعد هذا ونظرت المرأة فظنت أن الكلب أكلها فقال للكلب أفعلتها يا خبيث وطردته فإنه لكذلك إذا هو عند المساء بإبل قد ملأت الأفق وإذا هي تلتفت فرقا فعلم أن راعيها جلد شديد الضرب لها فلما أتت المناخ بركت ومكث الراعي قليلا ثم أتى ناقة منها فمرى أخلافها ثم وضع العلبة على ركبتيه وحلب حتى ملأها ثم أتى الشيخ فسقاه ثم أتى ناقة أخرى ففعل بها ذلك وسقى العجوز ثم أتى أخرى ففعل بها كذلك فشرب هو ثم التفع بثوب واضطجع ناحية فقال الشيخ للمرأة وأعجبه ذلك كيف ترين ابني فقالت ليس بابنك قال فابن من ويلك قالت ابن عروة بن الورد قال ومن أين قالت أتذكر يوم مر بنا يريد سوق ذي المجاز فقلت هذه عروة بن الورد وصفته لي بجلد فإني استطرفته قال فسكت حتى إذا نوم وثب عروة وصاح بالإبل فاقتطع منها نحوا من النصف ومضى ورجا ألا يتبعه الغلام وهو غلام حين بدا شاربه فاتبعه قال فاتخذا وعالجه قال فضرب به الأرض فيقع قائما فتخوفه على نفسه ثم واثبه فضرب به وبادره فقال إني عروة بن الورد وهو يريد أن يعجزه عن نفسه قال فارتدع ثم قال مالك ويلك لست أشك\nأنك قد سمعت ما كان من أمي قال قلت نعم فاذهب معي أنت وأمك وهذه الإبل ودع هذا الرجل فإنه لا ينهاك عن شيء قال الذي بقي من عمر الشيخ قليل وأنا مقيم معه ما بقي فإن له حقا وذماما فإذا هلك فما أسرعني إليك وخذ من هذه الإبل بعيرا قلت لا يكفيني إن معي أصحابي قد خلفتهم قال فثانيا قلت لا قال فثالثا والله لا زدتك على ذلك فأخذها ومضى إلى أصحابه ثم إن الغلام لحق به بعد هلاك الشيخ قال والله يا أمير المؤمنين لقد زينته عندنا وعظمته في قلوبنا قال فهل أعقب عندكم قال لا ولقد كنا نتشاءم بأبيه لأنه هو الذي أوقع الحرب بين عبس وفزارة بمراهنته حذيفة ولقد بلغني أنه كان له ابن أسن من عروة فكان يؤثره على عروة فيما يعطيه ويقربه فقيل له أتؤثر الأكبر مع غناه عنك على الأصغر مع ضعفه قال أترون هذا الأصغر لئن بقي ما رأى من شدة نفسه ليصيرن الأكبر عيالا عليه","topic":"أخبار عروة بن الورد ونسبه","topicNo":20,"sp":5,"spl":"عروة يتعرف على ابن له"},
{"id":"b21-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص85","text":"(أزرى بنا أننا شالت نعامتنا ... فخالني دونه بل خلته دوني)\n(فإن تصبك من الأيام جائحة ... لم أبك منك على دنيا ولا دين)\nلشعر لذي الإصبع العدواني والغناء لفيل مولى العبلات هزج خفيف بإطلاق الوتر في مجرى البنصر معنى قوله أزرى بنا قصر بنا يقال زريت عليه إذا عبت عليه فعله وأزريت به إذا قصرت به في شيء وشالت نعامتهم إذا انتقلوا بكليتهم يقال شالت نعامتهم وزف رألهم إذا انتقلوا عن الموضع فلم يبق فيه منهم أحد ولم يبق لهم فيه شيء وخالني ظنني يقال خلت كذا وكذا فأنا أخاله إذا ظننته والجائحة النازلة التي تجتاح ولا تبقى على ما نزلت به","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":0,"spl":"صوت من المائة المختارة — خبر من قرعت له العصا"},
{"id":"b21-2","bab":"الجزء 3","sec":"ذكر ذي الإصبع العدواني ونسبه وخبره","page":"ج3 ص86","text":"هو حرثان بن الحارث بن محرث بن ثعلبة بن سيار بن ربيعة بن هبيرة بن ثعلبة بن ظرب بن عمرو بن عباد بن يشكر بن عدوان بن عمر بن سعد بن قيس بن عيلان بن مضر بن نزار أحد بني عدوان وهم بطن من جديلة شاعر فارس من قدماء الشعراء في الجاهلية وله غارات كثيرة في العرب ووقائع مشهورة أخبرنا محمد بن خلف وكيع وابن عمار والأسدي قالوا حدثنا الحسن بن عليل العنزي قال حدثنا أبو عثمان المازني عن الأصمعي قال نزلت عدوان على ماء فأحصوا فيهم سبعين ألف غلام أغرل سوى من كان مختونا لكثرة عددهم ثم وقع بأسهم بينهم فتفانوا فقال ذو الإصبع صوت\n(عذير الحي من عدوان ... كانوا حية الأرض)\n(بغى بعضهم بعضا ... فلم يبقوا على بعض)\n(فقد صاروا أحاديث ... برفع القول والخفض)\n(ومنهم كانت السادات ... والموفون بالقرض)\n(ومنهم من يجيز الناس ... بالسنة والفرض)\n(ومنهم حكم يقضي ... فلا ينقض ما يقضي)\nنى في هذه الأبيات مالك ثقيلا أول بالوسطى على مذهب إسحاق من رواية عمر وأما قول ذي الإصبع\n(ومنهم حكم يقضي ... )\nإنه يعني عامر بن الظرب العدواني كان حكما للعرب تحتكم إليه","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":0,"spl":"صوت من المائة المختارة — خبر من قرعت له العصا","partial":1},
{"id":"b21-3","bab":"الجزء 3","sec":"خبر من قرعت له العصا","page":"ج3 ص87","text":"حدثنا محمد بن العباس اليزيدي عن محمد بن حبيب قال قيس تدعي هذه الحكومة وتقول إن عامر بن الظرب العدواني هو الحكم وهو الذي كانت العصا تقرع له وكان قد كبر فقال له الثاني من ولده إنك ربما أخطأت في الحكم فيحمل عنك قال فاجعلوا لي أمارة أعرفها فإذا زغت فسمعتها رجعت إلى الحكم والصواب فكان يجلس قدام بيته ويقعد ابنه في البيت ومعه العصا فإذا زاغ أو هفا قرع له الجفنة فرجع إلى الصواب وفي ذلك يقول المتلمس\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\nال ابن حبيب وربيعة تدعيه لعبد الله بن عمرو بن الحارث بن همام واليمن تدعيه لربيعة بن مخاشن وهو ذو الأعواد وهو أول من جلس على منبر أو سرير وتكلم وفيه يقول الأسود بن يعفر\n(ولقد علمت لو أن علمي نافعي ... أن السبيل سبيل ذي الأعواد)\nخبرني هاشم بن محمد الخزاعي أو دلف قال أخبرنا الرياشي قال حدثنا الأصمعي قال زعم أبو عمرو بن العلاء أنه ارتحلت عدوان من منزل فعد فيهم أربعون ألف غلام أقلف قال الرياشي وأخبرني رجل عن هشام بن الكلبي قال وقع على إياد البق فأصاب كل رجل منهم بقتان","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":0,"spl":"صوت من المائة المختارة — خبر من قرعت له العصا"},
{"id":"b21-4","bab":"الجزء 3","sec":"عبد الملك بن مروان يسأل عن ذي الإصبع","page":"ج3 ص88","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني يعقوب بن نعيم قال حدثنا أحمد بن عبيد أبو عصيدة قال أخبرني محمد بن زياد الزيادي وأخبرني به أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة ولم يسنده إلى أحد وروايته أتم أن عبد الملك بن مروان لما قدم الكوفة بعد قتله مصعب بن الزبير جلس\nلعرض أحياء العرب وقال عمر بن شبة إن مصعب بن الزبير كان صاحب هذه القصة فقام إليه معبد بن خالد الجدلي وكان قصيرا دميما فتقدمه إليه رجل منا حسن الهيئة قال معبد فنظر عبد الملك إلى الرجل وقال ممن أنت فسكت ولم يقل شيئا وكان منا فقلت من خلفه نحن يا أمير المؤمنين من جديلة فأقبل على الرجل وتركني فقال من أيكم ذو الإصبع قال الرجل لا أدري قلت كان عدوانيا فأقبل على الرجل وتركني وقال لم سمي ذا الإصبع قال الرجل لا أدري فقلت نهشته حية في إصبعه فيبست فأقبل على الرجل وتركني فقال وبما كان يسمى قبل ذلك قال الرجل لا أدري قلت كان يسمى حدثان فأقبل على الرجل وتركني فقال من أي عدوان كان فقلت من خلفه من بني ناج الذين يقول فيهم الشاعر\n(وأما بنو ناج فلا تذكرنهم ... ولا تتبعن عينيك ما كان هالكا)\n(إذا قلت معروفا لأصلح بينهم ... يقول وهيب لا أسالم ذلكا)\nروى عمر بن شبة لا أسلم\n(فأضحى كظهر الفحل جب سنامه ... يدب إلى الأعداء أحدب باركا)\nأقبل على الرجل وتركني وقال أنشدني قوله\n(عذير الحي من عدوان ... )\nال الرجل لست أرويها قلت يا أمير المؤمنين إن شئت أنشدتك قال ادن مني فإني أراك بقومك عالما فأنشدته\n(وليس المرء في شيء ... من الإبرام والنقض)\n(إذا أبرم أمرا خاله ... يقضي وما يقضي)\n(يقول اليوم أمضيه ... ولا يملك ما يمضي)\n(عذير الحي من عدوان ... كانوا حية الأرض)\n(بغى بعضهم بعضا ... فلم يبقوا على بعض)\n(فقد صاروا أحاديث ... برفع القول والخفض)\n(ومنهم كانت السادات ... والموفون بالقرض)\n(ومنهم حكم يقضي ... فلا ينقض ما يقضي)\n(ومنهم من يجيز النا ... س بالسنة والفرض)\n(وهم من ولدوا أشبوا ... بسر الحسب المحض)\n(وممن ولدوا عامر ... ذو الطول وذو العرض)\n(وهم بووا ثقيفا دار ... لا ذل ولا خفض)\nأقبل على الرجل وتركني وقال كم عطاؤك فقال ألفان فأقبل علي فقال كم عطاؤك فقلت خمسمائة فأقبل على كاتبه وقال اجعل الألفين لهذا والخمسمائة لهذا فانصرفت بها وقوله ومنهم من يجيز الناس فإن إجازة الحج كانت لخزاعة فأخذتها منهم عدوان فصارت إلى رجل منهم يقال له أبو سيارة أحد بني وابش بن زيد بن عدوان وله يقول الراجز\n(خلوا السبيل عن أبي سياره ... وعن مواليه بني فزاره)\n(حتى يجيز سالما حماره ... مستقبل الكعبة يدعوا جاره)\nال وكان أبو سيارة يجيز الناس في الحج بأن يتقدمهم على حمار ثم يخطبهم فيقول اللهم أصلح بين نسائنا وعاد بين رعائنا واجعل المال في سمحائنا أوفوا بعهدكم وأكرموا جاركم وأقروا ضيفكم ثم يقول أشرق ثبيركيما نغير وكانت هذه إجازته ثم ينفر ويتبعه الناس ذكر ذلك أبو عمرو الشيباني والكلبي وغيرهما أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أبو بكر العليمي قال حدثنا محمد بن داود الهشامي قال كان لذي الإصبع أربع بنات وكن يخطبن إليه فيعرض ذلك عليهن فيستحين ولا يزوجهن وكانت أمهن تقول لو زوجتهن فلا يفعل قال فخرج ليلة إلى متحدث لهن فاستمع عليهن وهن لا يعلمن فقلن تعالين نتمنى ولنصدق فقالت الكبرى\n(ألا ليت زوجي من أناس ذوي غنى ... حديث الشباب طيب الريح والعطر)\n(طبيب بأدواء النساء كأنه ... خليفة جان لا ينام على وتر)\nقلن لها أنت تحبين رجلا ليس من قومك فقالت الثانية\n(ألا هل أراها ليلة وضجيعها ... أشم كنصل السيف غير مبلد)\n(لصوق بأكباد النساء وأصله ... إذا ما انتمى من سر أهلي ومحتدي)\nفقلن لها أنت تحبين رجلا من قومك فقالت الثالثة\n(ألا ليته يملا الجفان لضيفه ... له جفنة يسقى بها النيب والجزر)\n(له حكمات الدهر من غير كبرة ... تشين ولا الفاني ولا الضرع الغمر)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":1,"spl":"عبد الملك بن مروان يسأل عن ذي الإصبع","partialRef":{"sid":"b21-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b21-5","bab":"الجزء 3","sec":"عبد الملك بن مروان يسأل عن ذي الإصبع","page":"ج3 ص88","text":"قلن لها أنت تحبين رجلا شريفا وقلن للصغرى تمني فقالت ما أريد شيئا قلن والله لا تبرحين حتى نعلم ما في نفسك قالت زوج من عود خير من قعود فلما سمع ذلك أبوهن زوجهن أربعتهن فمكثن برهة ثم اجتمعن إليه فقال للكبرى يا بنية ما مالكم قالت الإبل قال فكيف تجدونها قالت خير مال نأكل لحومها مزعا ونشرب ألبانها جرعا وتحملنا وضعيفنا معا قال فكيف تجدين زوجك قالت خير زوج يكرم الحليلة ويعطي الوسيلة قال مال عميم وزوج كريم ثم قال للثانية يا بنية ما مالكم قالت البقر قال فكيف تجدونها قالت خير مال تألف الفناء وتودك السقاء وتملأ الإناء ونساء في نساء قال فكيف تجدين زوجك قالت خير زوج يكرم أهله وينسى فضله قال حظيت ورضيت ثم قال للثالثة ما مالكم قالت المعزى قال فكيف تجدونها قالت لا بأس بها نولدها فطما ونسلخها أدما قال فكيف تجدين زوجك قالت لا بأس به ليس بالبخيل الحكر ولا بالسمح البذر قال\nجدوى مغنية ثم قال للرابعة يا بنية ما مالكم قالت الضأن قال وكيف تجدونها قالت شر مال جوف لا يشبعن وهيم لا ينقعن وصم لا يسمعن وأمر مغويتهن يتبعن قال فكيف تجدين زوجك قالت شر زوج يكرم نفسه ويهين عرسه قال أشبه امرأ بعض بزه وذكر الحسن بن عليل العنزي في خبر عدوان الذي رواه عن أبي عمرو بن العلاء أنه لا يصح من أبيات ذي الإصبع الضادية إلا الأبيات التي أنشدها وأن سائرها منحول أخبرني عمي قال حدثني محمد بن عبد الله الحزنبل قال حدثني عمرو بن أبي عمرو الشيباني عن أبيه قال عمر ذو الإصبع العدواني عمرا طويلا حتى خرف وأهتر وكان يفرق ماله فعذله أصهاره ولاموه وأخذوا على يده فقال في ذلك\n(أهلكنا الليل والنهار معا ... والدهر يعدو مصمما جذعا)\n(فليس فيما أصابني عجب ... إن كنت شيبا أنكرت أو صلعا)\n(وكنت إذ رونق الشباب به ... ماء شبابي تخاله شرعا)\n(والحي فيه الفتاة ترمقني ... حتى مضى شأو ذاك فانقشعا)\nصوت\n(إنكما صاحبي لم تدعا ... لومي ومهما أضق فلن تسعا)\n(لم تعقلا جفوة علي ولم ... أشتم صديقا ولم أنل طبعا)\n(إلا بأن تكذبا علي وما ... أملك أن تكذبا وأن تلعا)\nابن سريج في هذه الأبيات لحنان أحدهما ثاني ثقيل بالسبابة والبنصر عن يحيى المكي والآخر ثقيل أول عن الهشامي\n(وإنني سوف أبتدي بندى ... يا صاحبي الغداة فاستمعا)\n(ثم سلا جارتي وكنتها ... هل كنت فيمن أراب أو خدعا)\n(أو دعتاني فلم أجب ولقد ... تأمن مني حليلتي الفجعا)\n(آبى فلا أقرب الخباء إذا ... ما ربه بعد هدأة هجعا)\n(ولا أروم الفتاة زورتها ... إن نام عنها الحليل أو شسعا)\n(وذاك في حقبة خلت ومضت ... والدهر يأتي على الفتى لمعا)\n(إن تزعما أنني كبرت فلم ... ألف ثقيلا نكسا ولا ورعا)\n(إما تري شكتي رميح أبي ... سعد فقد أحمل السلاح معا)\nبو سعد ابنه ورميح عصا كانت لابنه يلعب بها مع الصبيان يطاعنهم بها كالرمح فصار يتوكأ هو عليها ويقوده ابنه هذا بها\n(السيف والرمح والكنانة قد ... أكملت فيها معابلا صنعا)\n(والمهر صافي الأديم أصنعه ... يطير عنه عفاؤه قزعا)\n(أقصر من قيده وأردعه ... حتى إذا السرب ريع أو فزعا)\n(كان أمام الجياد يقدمها ... يهز لدنا وجؤجؤا تلعا)\n(فغامس الموت أو حمى ظعنا ... أو رد نهبا لأي ذاك سعى)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":2,"spl":"عبد الملك بن مروان يسأل عن ذي الإصبع"},
{"id":"b21-6","bab":"الجزء 3","sec":"وصيته لابنه أسيد عند موته","page":"ج3 ص95","text":"قال أبو عمرو ولما احتضر ذو الإصبع دعا ابنه أسيدا فقال له يا بني إن أباك قد فني وهو حي وعاش حتى سئم العيش وإني موصيك بما إن حفظته بلغت في قومك ما بلغته فاحفظ عني ألن جانبك لقومك يحبوك وتواضع لهم يرفعوك وابسط لهم وجهك يطيعوك ولا تستأثر عليهم بشيء يسودوك وأكرم صغارهم كما تكرم كبارهم يكرمك كبارهم ويكبر على مودتك صغارهم واسمح بمالك واحم حريمك وأعزز جارك وأعن من استعان بك وأكرم ضيفك وأسرع النهضة في الصريخ فإن أجلا لا يعدوك وصن وجهك عن مسئلة أحد شيئا فبذلك يتم سوددك ثم أنشأ يقول\n(أأسيد إن مالا ملكت ... فسر به سيرا جميلا)\n(آخ الكرام إن استطعت ... إلى إخائهم سبيلا)\n(واشرب بكأسهم وإن ... شربوا به السم الثميلا)\n(أهن اللئام ولا تكن ... لإخائهم جملا ذلولا)\n(إن الكرام إذا تواخيهم ... وجدت لهم فضولا)\n(ودع الذي يعد العشيرة ... أن يسيل ولن يسيلا)\n(أبني إن المال لا ... يبكي إذا فقد البخيلا)\nصوت\n(أأسيد إن أزمعت من ... بلد إلى بلد رحيلا)\n(فاحفظ وإن شحط المزار ... أخا أخيك أو الزميلا)\n(واركب بنفسك إن هممت ... بها الحزونة والسهولا)\n(وصل الكرام وكن لمن ... ترجو مودته وصولا)\nلغناء للهذلي خفيف ثقيل أول بالوسطى عن عمرو\n(ودع التواني في الأمور ... وكن لها سلسا ذلولا)\n(وابسط يمينك بالندى ... وامدد لها باعا طويلا)\n(وابسط يديك بما ملكت ... وشيد الحسب الأثيلا)\n(واعزم إذا حاولت أمرا ... يفرج الهم الدخيلا)\n(وابذل لضيفك ذات رحلك ... مكرما حتى يزولا)\n(واحلل على الأيفاع للعافين ... واجتنب المسيلا)\n(وإذا القروم تخاطرت ... يوما وأرعدت الخصيلا)\n(فاهصر كهصر الليث خضب من فريسته التليلا ... )\n(وأنزل إلى الهيجا إذا ... أبطالها كرهوا النزولا)\n(وإذا دعيت إلى المهم ... فكن لفادحه حمولا)\nخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن العتبي قال جرى بين عبد الله بن الزبير وعتبة بن أبي سفيان لحاء بين يدي معاوية فجعل ابن الزبير يعدل بكلامه عن عتبة ويعرض بمعاوية حتى أطال وأكثر من ذلك فالتفت إليه معاوية متمثلا وقال\n(ورام بعوران الكلام كأنها ... نوافر صبح نفرتها المراتع)\n(وقد يدحض المرء الموارب بالخنا ... وقد تدرك المرء الكريم المصانع)\nم قال لابن الزبير من يقول هذا فقال ذو الإصبع فقال أترويه قال لا فقال من هاهنا يروي هذه الأبيات فقام رجل من قيس فقال أنا أرويها يا أمير المؤمنين فقال أنشدني فأنشده حتى أتى على قومه\n(وساع برجليه لآخر قاعد ... ومعط كريم ذو يسار ومانع)\n(وبان لأحساب الكرام وهادم ... وخافض مولاه سفاها ورافع)\n(ومغض على بعض الخطوب وقد بدت ... له عورة من ذي القرابة ضاجع)\n(وطالب حوب باللسان وقلبه ... سوى الحق لا تخفى عليه الشرائع)\nقال له معاوية وكم عطاؤك قال سبعمائة قال اجعلوها ألفا وقطع الكلام بين عبد الله وعتبة قال أبو عمرو وكان لذي الإصبع ابن عم يعاديه فكان يتدسس إلى مكارهه ويمشي به إلى أعدائه ويؤلب عليه ويسعى بينه وبين بني عمه ويبغيه عندهم شرا فقال فيه وقد أنشدنا الأخفش هذه الأبيات أيضا عن ثعلب والأحول السكري\n(يا صاحبي قفا قليلا ... وتخبرا عني لميسا)\n(عمن أصابت قلبه ... في مرها فغدا نكيسا)\n(ولي ابن عم لا يزال ... إلي منكره دسيسا)\n(دبت له فأحس بعد ... البرء من سقم رسيسا)\n(إما علانية وإما ... مخمرا أكلا وهيسا)\n(إني رأيت بني أبيك ... يحمجون إلي شوسا)\n(حنقا علي ولن ترى ... لي فيهم أثرا بئيسا)\n(أنحوا على حر الوجوه ... بحد مئشار ضروسا)\n(لو كنت ماء لم تكن ... عذب المذاق ولا مسوسا)\n(ملحا بعيد القعر قد ... فلت حجارته الفؤوسا)\n(مناع ما ملكت يداك ... وسائل لهم نحوسا)\nأنشدنا الأخفش عن هؤلاء الرواة بعقب هذه الأبيات وليس من شعر ذي الإصبع ولكنه يشبه معناه\n(لو كنت ماء كنت غير عذب ... أو كنت سيفا كنت غير عضب)\n(أو كنت طرفا كنت غير ندب ... أو كنت لحما كنت لحم كلب)\nال وفي مثله أنشدنا\n(لو كنت مخا مخا ريرا ... أو كنت بردا كنت زمهريرا)\n(أو كنت ريحا كانت الدبورا ... )","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":3,"spl":"وصيته لابنه أسيد عند موته","partial":1},
{"id":"b21-7","bab":"الجزء 3","sec":"وصيته لابنه أسيد عند موته","page":"ج3 ص95","text":"ال أبو عمرو به وكان السبب في تفرق عدوان وقتال بعضهم بعضا حتى تفانوا أن بني ناج بن يشكر بن عدوان أغاروا على بني عوف بن سعد بن ظرب بن عمرو بن عباد بن يشكر بن عدوان ونذرت بهم بنو عوف فاقتتلوا فقتل بنو ناج ثمانية نفر فيهم عمير بن مالك سيد بني عوف وقتلت بنو عوف رجلا منهم يقال له سنان بن جابر وتفرقوا على حرب وكان الذي أصابوه من بني واثلة بن عمرو\nابن عباد وكان سيدا فاصطلح سائر الناس على الديات أن يتعاطوها ورضوا بذلك وأبى مرير بن جابر أن يقبل بسنان بن جابر دية واعتزل هو وبنو أبيه ومن أطاعهم ومن والاهم وتبعه على ذلك كرب بن خالد أحد بني عبس بن ناج فمشى إليهما ذو الإصبع وسألهما قبول الدية وقال قد قتل منا ثمانية نفر فقبلنا الدية وقتل منكم رجل فاقبلوا ديته فأبيا ذلك وأقاما على الحرب فكان ذلك مبدأ حرب بعضهم بعضا حتى تفانوا وتقطعوا فقال ذو الإصبع في ذلك\n(ويا بؤس للأيام والدهر هالكا ... وصرف الليالي يختلفن كذلكا)\n(أبعد بني ناج وسعيك فيهم ... فلا تتبعن عينيك ما كان هالكا)\n(إذا قلت معروفا لأصلح بينهم ... يقول مرير لا أحاول ذلكا)\n(فأضحوا كظهر العود جب سنامه ... تحوم عليه الطير أحدب باركا)\n(فإن تك عدوان بن عمرو تفرقت ... فقد غنيت دهرا ملوكا هنالكا)\nقال أبو عمرو وفي مرير بن جابر يقول ذو الإصبع وهذه القصيدة هي التي منها الغناء المذكور وأولها\n(يا من لقلب شديد الهم محزون ... أمسى تذكر ريا أم هارون)\n(أمسى تذكرها من بعد ما شحطت ... والدهرو ذو غلظ حينا وذو لين)\n(فإن يكن حبها أمسى لنا شجنا ... وأصبح الولي منها لا يواتيني)\n(فقد غنينا وشمل الدار يجمعنا ... أطيع ريا وريا لا تعاصيني)\n(نرمي الوشاة فلا نخطي مقاتلهم ... بخالص من صفاء الود مكنون)\n(ولي ابن عم على ما كان من خلق ... مختلفان فأقليه ويقليني)\n(أزرى بنا أننا شالت نعامتنا ... فخالني دونه بل خلته دوني)\n(لاه ابن عمك لا أفضلت في حسب ... شيئا ولا أنت دياني فتخزوني)\n(ولا تقوت عيالي يوم مسغبة ... ولا بنفسك في العزاء تكفيني)\n(فإن ترد عرض الدنيا بمنقصتي ... فإن ذلك مما ليس يشجيني)\n(ولا ترى في غير الصبر منقصة ... وما سواه فإن الله يكفيني)\n(لولا أواصر قربى لست تحفظها ... ورهبة الله في مولى يعاديني)\n(إذا بريتك بريا لا انجبار له ... إني رأيتك لا تنفك تبريني)\n(إن الذي يقبض الدنيا ويبسطها ... إن كان أغناك عني سوف يغنيني)\n(الله يعلمكم والله يعلمني ... والله يجزيكم عني ويجزيني)\n(ماذا علي وإن كنتم ذوي رحمي ... ألا أحبكم إن لم تحبوني)\n(لو تشربون دمي لم يرو شاربكم ... ولا دماؤكم جمعا ترويني)\n(ولي ابن عم لو ان الناس في كبدي ... لظل محتجزا بالنبل يرميني)\n(يا عمرو إن لا تدع شتمي ومنقصتي ... أضربك حتى تقول الهامة اسقوني)\n(كل امرىء صائر يوما لشيمته ... وإن تخلق أخلاقا إلى حين)\n(إني لعمرك ما بابي بذي غلق ... عن الصديق ولا خيري بممنون)\n(ولا لساني على الأدنى بمنطلق ... بالمنكرات ولا فتكي بمأمون)\n(لا يخرج القسر مني غير مغضبة ... ولا ألين لمن لا يبتغي ليني)\n(وأنتم معشر زيد على مائة ... فأجمعوا أمركم شتى فكيدوني)\n(فإن علمتم سبيل الرشد فانطلقوا ... وإن غبيتم طريق الرشد فأتوني)\n(يا رب ثوب حواشيه كأوسطه ... لا عيب في الثوب من حسن ومن لين)\n(يوما شددت على فرغاء فاهقة ... يوما من الدهر تارات تماريني)\n(ماذا علي إذا تدعونني فزعا ... ألا أجيبكم إذ لا تجيبوني)\n(وكنت أعطيكم مالي وأمنحكم ... ودي على مثبت في الصدر مكنون)\n(يارب حي شديد الشغب ذي لجب ... ذعرت من راهن منهم ومرهون)\n(رددت باطلهم في رأس قائلهم ... حتى يظلوا خصوما ذا أفانين)\n(يا عمرو لو كنت لي ألفيتني يسرا ... سمحا كريما أجازي من يجازيني)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":4,"spl":"وصيته لابنه أسيد عند موته"},
{"id":"b21-8","bab":"الجزء 3","sec":"رثاء ذي الإصبع لقومه","page":"ج3 ص102","text":"قال أبو عمرو وقال ذو الإصبع يرثي قومه\n(وليس المرء في شيء ... من الإبرام والنقض)\n(إذا يفعل شيئا خاله ... يقضي وما يقضي)\n(جديد العيش ملبوس ... وقد يوشك أن ينضى)\nقد مضى بعض هذه القصيدة متقدما في صدر هذه الأخبار وتمامها\n(وأمر اليوم أصلحه ... ولا تعرض لما يمضي)\n(فبينا المرء في عيش ... له من عيشة خفض)\n(أتاه طبق يوما ... على مزلقة دحض)\n(وهم كانوا فلا تكذب ... ذوي القوة والنهض)\n(وهم إن ولدوا أشبوا ... بسر الحسب المحض)\n(لهم كانت أعالي الأرض ... فالسران فالعرض)\n(إلى ما حازه الحزن ... فما أسهل للحمض)\n(إلى الكفرين من نحلة ... فالداءة فالمرض)\n(لهم كان جمام الماء ... لا المزجى ولا البرض)\n(فكان الناس إذا هموا ... بيسر خاشع مغضي)\n(تنادوا ثم ساروا برئيس ... لهم مرضي)\n(فمن ساجلهم حربا ... ففي الخيبة والخفض)\n(وهم نالوا على الشنا ... ن والشحناء والبغض)\n(معالي لم ينلها الناس ... في بسط ولا قبض)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":5,"spl":"رثاء ذي الإصبع لقومه — رثاء أمامة بنت ذي الإصبع لقومها"},
{"id":"b21-9","bab":"الجزء 3","sec":"رثاء أمامة بنت ذي الإصبع لقومها","page":"ج3 ص103","text":"قال أبو عمرو قالت أمامة بنت ذي الإصبع وكانت شاعرة ترثي قومها\n(كم من فتى كانت له ميعة ... أبلج مثل القمر الزاهر)\n(قد مرت الخيل بحافاته ... كمر غيث لجب ماطر)\n(قد لقيت فهم وعدوانها ... قتلا وهلكا آخرالغابر)\n(كانوا ملوكا سادة في الذرى ... دهرا لها الفخر على الفاخر)\n(حتى تساقوا كأسهم بينهم ... بغيا فيا للشارب الخاسر)\n(بادوا فمن يحلل بأوطانهم ... يحلل برسم مقفر داثر)\nقال أبو عمرو ولأمامة ابنته هذه يقول ذو الإصبع ورأته قد نهض فسقط وتوكأ على العصا فبكت فقال\n(جزعت أمامة أن مشيت على العصا ... وتذكرت إذ نحن م الفتيان)\n(فلقبل ما رام الاله بكيده ... إرما وهذا الحي من عدوان)\n(بعد الحكومة والفضيلة والنهى ... طاف الزمان عليهم بأوان)\n(وتفرقوا وتقطعت أشلاؤهم ... وتبددوا فرقا بكل مكان)\n(جدب البلاد فأعقمت أرحامهم ... والدهر غيرهم مع الحدثان)\n(حتى أبادهم على أخراهم ... صرعى بكل نقيرة ومكان)\n(لا تعجبن أمام من حدث عرا ... فالدهر غيرنا مع الأزمان)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":5,"spl":"رثاء ذي الإصبع لقومه — رثاء أمامة بنت ذي الإصبع لقومها"},
{"id":"b21-10","bab":"الجزء 3","sec":"ذكر قيل مولى العبلات","page":"ج3 ص105","text":"قال هارون بن محمد بن عبد الملك أخبرني حماد بن إسحاق عن أبيه قال كان يحيى قيل عبدا للثريا ورضيا وأخواتهما بنات علي بن عبد الله بن الحارث بن أمية الأصغر بن عبد شمس موليات الغريض قال وحدثني حماد قال حدثني أبي قال حدثني ابن أبي جناح قال حدثنا مقاحف بن ناصح مولى عبد الله بن عباس قال قال حدثني هشام بن المرية وهي أمه وهو مولى بني مخزوم قال كان يحيى قيل عبدا لامرأة من العبلات وله من الغناء صوت\n(وأخرجتها من بطن مكة بعدما ... أصات المنادي للصلاة وأعتما)\n(فمرت ببطن الليث تهوي كأنما ... تبادر بالإصباح نهبا مقسما)\nوالشعر لأبي دهبل الجمحي وأول هذه القصيدة\n(ألا علق القلب المتيم كلثما ... )\nأخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني يحيى بن المقداد الزمعي قال حدثني عمي موسى بن يعقوب الزمعي قال أنشدني أبو دهبل الجمحي لنفسه\n(ألا علق القلب المتيم كلثما ... لجوجا ولم يلزم من الحب ملزما)\n(خرجت بها من بطن مكة بعد ما ... أصات المنادي للصلاة وأعتما)\n(فما نام من راع ولا ارتد سامر ... من الحي حتى جاوزت بي يلملما)\n(ومرت ببطن الليث تهوي كأنها ... تبادر بالإدلاج نهبا مقسما)\n(أجازت على البزواء والليل كاسر ... جناحين بالبزواء وردا وأدهما)\n(فما ذر قرن الشمس حتى تبينت ... بعليب نخلا مشرفا ومخيما)\n(ومرت على أشطان دومة بالضحى ... فما خزرت للماء عينا ولا فما)\n(وما شربت حتى ثنيت زمامها ... وخفت عليها أن تحز وتكلما)\n(فقلت لها قد تعت غير ذميمة ... وأصبح وادي البرك غيثا مديما)\nقال فقلت له يا عم ما كنت إلا على الريح فقال يا ابن أخي إن عمك كان إذا هم فعل وهي العجاجة أما سمعت قول أخي بني مرة\n(إذا أقبلت قلت مشحونة ... أقلت لها الريح قلعا جفولا)\n(وإن أدبرت قلت مذعورة ... من الرمد تتبع هيقا ذمولا)\n(وإن أعرضت خال فيها البصير ... ما لا يكلفه أن يفيلا)\n(يدا سرحا مائرا ضبعها ... تسوم وتقدم رجلا زجولا)\n(فمرت على كشب غدوة ... ومرت فويق أريك أصيلا)\n(تخبط بالليل حزانه ... كخبط القوي العزيز الذليلا)\nأخبرنا الحرمي قال حدثنا الزبير بن بكار قال حدثني ابن اصبغ السلمي قال جاء إنسان يغني إلى عياش المنقري بالعقيق فجعل يغنيه قول أبي دهبل\n(ألا علق القلب المتيم كلثما ... )\nجعل يعيده فلما أكثر قال له عياش كم تنذر بالعجوز عافاك الله اسم أمي كلثم قال وتسمع العجوز فقالت لا والله ما كان بيني وبينه شيء قال ومن غنائه\n(أزرى بنا أننا شالت نعامتنا ... فخالني دونه بل خلته دوني)\n(فإن تصبك من الأيام جائحة ... لا نبك منك على دنيا ولا دين)\nأول هذه الأبيات فيما أنشدناه علي بن سلمان الأخفش عن ثعلب","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":6,"spl":"ذكر قيل مولى العبلات — صوت من المائة المختارة","partial":1},
{"id":"b21-11","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص108","text":"(لي ابن عم ما كان من خلق ... مختلفان فأقليه ويقليني)\n(لاه ابن عمك لا أفضلت في حسب ... عني ولا أنت دياني فتخزوني)\nنى في هذين البيتين الهذلي ثاني ثقيل بالوسطى\n(وقد عجبت وما في الدهر من عجب ... يد تشج وأخرى منك تأسوني)\nوت من المائة المختارة\n(إرفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\n(يجزيك أو يثني عليك وإن من ... أثنى عليك بما فعلت فقد جزى)\nروضه من الكامل الشعر لغريض اليهودي وهو السموأل بن عادياء وقيل إنه لابنه سعية بن غريض وقيل إنه لزيد بن عمرو بن نفيل وقيل إنه لورقة بن نوفل وقيل إنه لزهير بن جناب وقيل إنه لعامر بن المجنون الجرمي الذي يقال له مدرج الريح والصحيح أنه لغريض أو لابنه\n(وقد عجبت وما في الدهر من عجب ... يد تشج وأخرى منك تأسوني)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":6,"spl":"ذكر قيل مولى العبلات — صوت من المائة المختارة"},
{"id":"b21-12","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص109","text":"(إرفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\n(يجزيك أو يثني عليك وإن من ... أثنى عليك بما فعلت فقد جزى)\nروضه من الكامل الشعر لغريض اليهودي وهو السموأل بن عادياء وقيل إنه لابنه سعية بن غريض وقيل إنه لزيد بن عمرو بن نفيل وقيل إنه لورقة بن نوفل وقيل إنه لزهير بن جناب وقيل إنه لعامر بن المجنون الجرمي الذي يقال له مدرج الريح والصحيح أنه لغريض أو لابنه","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":6,"spl":"ذكر قيل مولى العبلات — صوت من المائة المختارة"},
{"id":"b21-13","bab":"الجزء 3","sec":"خبر غريض اليهودي","page":"ج3 ص110","text":"وغريض هذا من اليهود من ولد الكاهن بن هارون بن عمران وكان موسى عليه الصلاة و السلام وجه جيشا إلى العماليق وكانوا قد طغوا وبلغت غاراتهم إلى الشام وأمرهم إن ظفروا بهم أن يقتلوهم أجمعين فظفروا بهم فقتلوهم أجمعين سوى ابن لملكهم كان غلاما جميلا فرحموه واستبقوه وقدموا الشأم بعد وفاة موسى عليه السلام فأخبروا بني إسرائيل بما فعلوه فقالوا أنتم عصاة لا تدخلون الشأم علينا أبدا فأخرجوهم عنها فقال بعضهم لبعض ما لنا بلد غير البلد الذي ظفرنا به وقتلنا أهله فرجعوا إلى يثرب فأقاموا بها وذلك قبل ورود الأوس والخزرج إياها عند وقوع سيل العرم باليمن فمن هؤلاء اليهود قريظة والنضير وبنو قينقاع وغيرهم ولم أجد لهم نسبا فأذكره لأنهم ليسوا من العرب فتدون العرب أنسابهم إنما هم حلفاؤهم وقد شرحت أخبارهم وما يغني به من أشعارهم في موضع آخر من هذا الكتاب والغناء في اللحن المختار لابن صاحب الوضوء واسمه محمد وكنيته أبو عبد الله وكان أبوه على الميضاة بالمدينة فعرف بذلك وهو يسير الصناعة ليس ممن خدم الخلفاء ولا شهر عندهم شهرة غيره وهذا الغناء ماخوري بالبنصر وفيه ليونس ثاني ثقيل بالبنصر\nأخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي وعبد الرحمن بن أخي الأصمعي عن الأصمعي عن ابن أبي الزناد عن هشام بن عروة قال\n(ارفع ضعيفك لا يحر بك ضعفه ... )\nغريض اليهودي","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":7,"spl":"خبر غريض اليهودي — رسول الله يدخل على عائشة وهي تتمثل بشعر","partial":1},
{"id":"b21-14","bab":"الجزء 3","sec":"رسول الله يدخل على عائشة وهي تتمثل بشعر","page":"ج3 ص111","text":"وأخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أحمد بن عيسى قال حدثنا مؤمل بن عبد الرحمن الثقفي قال حدثني سهل بن المغيرة عن الزهري عن عروة عن عائشة قالت دخل علي رسول الله وأنا أتمثل بهذين البيتين\n(إرفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\n(يجزيك أو يثني عليك وإن من ... أثنى عليك بما فعلت فقد جزى)\nقال \" ردي علي قول اليهودي قاتله الله لقد أتاني جبريل برسالة من ربي أيما رجل صنع إلى أخيه صنيعة فلم يجد له جزاء إلا الثناء عليه والدعاء له فقد كافأه \" قال أبو زيد وقد حدثني أبو عثمان محمد بن يحيى أن هذا الشعر لورقة بن نوفل وقد ذكر الزبير بن بكار أيضا أن هذا الشعر لورقة بن نوفل وذكر هذين البيتين في قصيدة أولها\n(رحلت قتيلة عيرها قبل الضحى ... وأخال أن شحطت بجارتك النوى)\n(أو كلما رحلت قتيلة غدوة ... وغدت مفارقة لأرضهم بكى)\n(ولقد ركبت على السفين ملججا ... أذر الصديق وأنتحي دار العدا)\n(ولقد دخلت البيت يخشى أهله ... بعد الهدوء وبعد ما سقط الندى)\n(فوجدت فيه حرة قد زينت ... بالحلي تحسبه بها جمر الغضا)\n(فنعمت بالا إذ أتيت فراشها ... وسقطت منها حين جئت على هوى)\n(فلتلك لذات الشباب قضيتها ... عني فسائل بعضهم ماذا قضى)\n(فرج الرباب فليس يؤدى فرجه ... لا حاجة قضى ولا ماء بغى)\n(فارفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\n(يجزيك أو يثني عليك وإن من ... أثنى عليك بما فعلت فقد جزى)","topic":"ذكر ذي الإصبع العدواني ونسبه وخبره","topicNo":21,"sp":7,"spl":"خبر غريض اليهودي — رسول الله يدخل على عائشة وهي تتمثل بشعر"},
{"id":"b22-2","bab":"الجزء 3","sec":"ذكر ورقة بن نوفل ونسبه — نسبة ما في هذا الشعر من الغناء","page":"ج3 ص112 – ج3 ص113","text":"هو ورقة بن نوفل بن أسد بن عبد العزى بن قصي وأمه هند بنت أبي كثير بن عبد بن قصي وهو أحد من اعتزل عبادة الأوثان في الجاهلية وطلب الدين وقرأ الكتب وامتنع من أكل ذبائح الأوثان\n(غير ... ارفع ضعيفك)\nصوت\n(ولقد طرقت البيت يخشى أهله ... بعد الهدوء وبعد ما سقط الندى)\n(فوجدت فيه حرة قد زينت ... بالحلي تحسبه بها جمر الغضا)\nلشعر لورقة بن نوفل والغناء لابن محرز من القدر الأوسط من الثقيل الأول بالخنصر في مجرى الوسطى عن إسحاق أخبرنا الطوسي قال حدثنا الزبير بن بكار قال حدثنا عبد الله بن معاذ عن\nمعمر عن الزهري عن عروة بن الزبير قال سئل رسول الله عن ورقة بن نوفل كما بلغنا فقال \" قد رأيته في المنام كأن عليه ثيابا بيضا فقد أظن أن لو كان من أهل النار لم أر عليه البياض \" قال الزبير وحدثنا عبد الله بن معاذ عن معمر عن الزهري عن عائشة أن خديجة بنت خويلد انطلقت بالنبي حتى أتت به ورقة بن نوفل بن أسد بن عبد العزى وهو ابن عم خديجة أخي أبيها وكان امرأ تنصر في الجاهلية وكان يكتب الكتاب العبراني فيكتب بالعبرانية من الإنجيل ما شاء أن يكتب وكان شيخا كبيرا قد عمي فقالت خديجة أي ابن عم اسمع من ابن أخيك قال ورقة يابن أخي ماذا ترى فأخبره رسول الله خبر ما رأى فقال ورقة هذا الناموس الذي أنزله الله تبارك وتعالى على موسى يا ليتني فيها جذع ليتني أكون حيا إذ يخرجك قومك قال رسول الله أو مخرجي هم قال ورقة نعم لم يأت رجل قط بمثل ما جئت به إلا عودي وإن يدركني يومك لأنصرنك نصرا مؤزرا ثم لم ينشب ورقة أن توفي","topic":"ذكر ورقة بن نوفل ونسبه","topicNo":22,"sp":0,"spl":"ذكر ورقة بن نوفل ونسبه — نسبة ما في هذا الشعر من الغناء — النبي ينهى عن سبه"},
{"id":"b22-3","bab":"الجزء 3","sec":"خبره مع بلال","page":"ج3 ص114","text":"قال الزبير حدثني عثمان عن الضحاك بن عثمان عن عبد الرحمن بن أبي الزناد قال قال عروة كان بلال لجارية من بني جمح بن عمرو وكانوا يعذبونه برمضاء مكة يلصقون ظهره بالرمضاء ليشرك بالله فيقول أحد أحد فيمر\nعليه ورقة بن نوفل وهو على ذلك يقول أحد أحد فيقول ورقة بن نوفل أحد أحد والله يا بلال والله لئن قتلتموه لاتخدته حنانا كأنه يقول لأتمسحن به وقال ورقة بن نوفل في ذلك\n(لقد نصحت لأقوام وقلت لهم ... أنا النذير فلا يغرركم أحد)\n(لا تعبدن إلها غير خالقكم ... فإن دعوكم فقولوا بيننا حدد)\n(سبحان ذي العرش سبحانا نعوذ به ... وقبل قد سبح الجودي والجمد)\n(مسخر كل ما تحت السماء له ... لا ينبغي أن يناوي ملكه أحد)\n(لا شيء مما ترى تبقى بشاشته ... يبقى الإله ويودي المال والولد)\n(لم تغن عن هرمز يوما خزائنه ... والخلد قد حاولت عاد فما خلدوا)\n(ولا سليمان إذ دان الشعوب له ... والجن والإنس تجري بينها البرد)","topic":"ذكر ورقة بن نوفل ونسبه","topicNo":22,"sp":0,"spl":"ذكر ورقة بن نوفل ونسبه — نسبة ما في هذا الشعر من الغناء — النبي ينهى عن سبه"},
{"id":"b22-4","bab":"الجزء 3","sec":"النبي ينهى عن سبه","page":"ج3 ص115","text":"قال الزبير حدثني عمي قال حدثنا الضحاك بن عثمان عن عبد الرحمن بن أبي الزناد عن هشام بن عروة أن رسول الله قال لأخي ورقة بن نوفل أو لابن أخيه \" شعرت أني قد رأيت لورقة جنة أو جنتين \" يشك هشام قال عروة ونهى رسول الله عن سب ورقة\nوقال الزبير وحدثني عمي قال حدثني الضحاك عن عبد الرحمن بن أبي الزناد عن هشام بن عروة عن أبيه أن خديجة كانت تأتي ورقة بما يخبرها رسول الله أنه يأتيه فيقول ورقة لئن كان ما يقول حقا إنه ليأتيه الناموس الأكبر ناموس عيسى ابن مريم الذي لا يجيزه أهل الكتاب إلا بثمن ولئن نطق وأنا حي لأبلين فيه لله بلاء حسنا","topic":"ذكر ورقة بن نوفل ونسبه","topicNo":22,"sp":0,"spl":"ذكر ورقة بن نوفل ونسبه — نسبة ما في هذا الشعر من الغناء — النبي ينهى عن سبه"},
{"id":"b23-1","bab":"الجزء 3","sec":"خبر زيد بن عمرو ونسبه","page":"ج3 ص117","text":"هو زيد بن عمرو بن نفيل بن عبد العزى بن رياح بن عبد الله بن قرط بن رزاح بن عدي بن كعب بن لؤي بن غالب وأمه جيداء بنت خالد بن جابر بن أبي حبيب بن فهم وكانت جيداء عند نفيل بن عبد العزى فولدت له الخطاب أبا عمر بن الخطاب وعبدنهم ثم مات عنها نفيل فتزوجها ابنه عمر فولدت له زيدا وكان هذا نكاحا ينكحه أهل الجاهلية وكان زيد بن عمرو أحد من اعتزل عبادة الأوثان وامتنع من أكل ذبائحهم وكان يقول يا معشر قريش أيرسل الله قطر السماء وينبت بقل الأرض ويخلق السائمة فترعى فيه وتذبحوها لغيره والله ما أعلم على ظهر الأرض أحدا على دين إبراهيم غيري أخبرنا الطوسي قال حدثنا الزبير قال حدثني عمي مصعب بن عبد الله ومحمد بن الضحاك عن أبيه قالا كان الخطاب بن نفيل قد أخرج زيد بن عمرو من مكة وجماعة من قريش ومنعوه أن يدخلها حين فارق أهل الأوثان وكان أشدهم عليه الخطاب بن نفيل وكان زيد بن عمرو إذا خلص إلى البيت استقبله ثم قال لبيك حقا حقا تعبدا ورقا البر أرجو لا الخال وهل مهجر كمن قال ثم يقول\n(عذت بما عاذ به إبراهم ... مستقبل الكعبة وهو قائم)\n(يقول أنفي لك عان راغم ... مهما تجشمني فإني جاشم)\nم يسجد قال محمد بن الضحاك عن أبيه وهو الذي يقول\n(لا هم إني حرم لا حله ... وإن داري أوسط المحله)\n(عند الصفا ليست بها مضله ... )\nعر زيد في ترك عبادة الأوثان قال الزبير وحدثني مصعب بن عبد الله عن الضحاك بن عثمان عن عبد الرحمن ابن بي الزناد قال قال هشام بن عروة عن أبيه عن أسماء بنت أبي بكر أنها قالت قال زيد بن عمرو بن نفيل\n(عزلت الجن والجنان عني ... كذلك يفعل الجلد الصبور)\n(فلا العزى أدين ولا ابنتيها ... ولا صنمي بني غنم أزور)\n(ولا هبلا أدين وكان ربا ... لنا في الدهر إذا حلمي صغير)\n(أربا واحدا أم ألف رب ... أدين إذا تقسمت الأمور)\n(ألم تعلم بأن الله أفنى ... رجالا كان شأنهم الفجور)\n(وأبقى آخرين ببر قوم ... فيربو منهم الطفل الصغير)\n(وبينا المرء يعثر ثاب يوما ... كما يتروح الغصن النضير)\nفقال ورقة بن نوفل لزيد بن عمرو بن نفيل\n(رشدت وأنعمت ابن عمرو وإنما ... تجنبت تنورا من النار حاميا)\n(بدينك ربا ليس رب كمثله ... وتركك جنان الجبال كما هيا)\n(أقول إذا ما زرت أرضا مخوفة ... حنانيك لا تظهر علي الأعاديا)\n(حنانيك إن الجن كانت رجاءهم ... وأنت إلهي ربنا ورجائيا)\n(أدين لرب يستجيب ولا أرى ... أدين لمن لا يسمع الدهر داعيا)\n(أقول إذا صليت في كل بيعة ... تباركت قد أكثرت باسمك داعيا)\nقول خلقت خلقا يدعون باسمك قال الزبير وحدثني مصعب بن عبد الله قال حدثني الضحاك بن عثمان عن عبد الرحمن بن أبي الزناد عن موسى بن عقبة قال سمعت من أرضى يحدث أن زيد بن عمرو كان يعيب على قريش ذبائحهم ويقول الشاة خلقها الله وأنزل من السماء ماء وأثبت لها من الأرض نباتا ثم تذبحونها على غير اسم الله إنكارا لذلك وإعظاما له","topic":"خبر زيد بن عمرو ونسبه","topicNo":23,"sp":0,"spl":"خبر زيد بن عمرو ونسبه","partial":1},
{"id":"b23-2","bab":"الجزء 3","sec":"قصته مع النبي","page":"ج3 ص119","text":"قال الزبير وحدثني مصعب بن عبد الله عن الضحاك بن عثمان عن عبد الرحمن بن أبي الزناد عن موسى بن عقبة عن سالم بن عبد الله أنه سمع عبد الله بن عمر يحدث عن رسول الله أنه لقي زيد بن عمرو بن نفيل بأسفل بلدح\nوكان قبل أن ينزل على رسول الله الوحي فقدم إليه رسول الله سفرة فيها لحم فأبى أن يأكل وقال إني لا آكل إلا ما ذكر اسم الله عليه قال الزبير وحدثني مصعب بن عبد الله عن الضحاك بن عثمان عن عبد الله بن أبي الزناد عن موسى بن عقبة عن سالم بن عبد الرحمن قال قال موسى لا أراه إلا حدثه عن عبد الله بن عمر أن زيد بن عمرو خرج إلى الشأم يسأل عن الدين ويتبعه فلقي عالما من اليهود فسأله عن دينهم فقال لعلي أدين بدينكم فأخبرني بدينكم فقال اليهودي إنك لا تكون على ديننا حتى تأخذ بنصيبك من غضب الله فقال زيد بن عمرو لا أفر إلا من غضب الله وما أحمل من غضب الله شيئا أبدا وأنا أستطيع فهل تدلني على دين ليس فيه هذا قال ما أعلمه إلا أن يكون حنيفا قال وما الحنيف قال دين إبراهيم فخرج من عنده وتركه فأتى عالما من علماء النصارى فقال له نحوا مما قال لليهودي فقال له النصراني إنك لن تكون على دينك حتى تأخذ بنصيبك من لعنة الله فقال إني لا أحمل من لعنة ولا من غضبه شيئا أبدا وأنا أستطيع فهل تدلني على دين ليس فيه هذا فقال له نحوا ممن قال اليهودي لا أعلمه إلا أن يكون حنيفا فخرج من عندهما وقد رضي بما أخبراه واتفقا عليه من دين إبراهيم فلما برز رفع يديه وقال اللهم إني على دين إبراهيم قال الزبير وحدثني مصعب بن عبد الله عن الضحاك بن عثمان عن عبد الرحمن بن أبي الزناد قال قال هشام بن عروة بلغنا أن زيد بن عمرو كان بالشأم فلما بلغه خبر النبي أقبل يريده فقتله أهل ميفعة قال الزبير وحدثني مصعب بن عبد الله عن الضحاك بن عثمان عن عبد\nالرحمن بن أبي الزناد عن هشام بن عروة عن أبيه عن سعيد بن زيد بن عمرو قال سألت أنا وعمر بن الخطاب رسول الله عن زيد فقال \" يأتي يوم القيامة أمة وحده \" وأنشد محمد بن الضحاك عن الحزامي عن أبيه لزيد بن عمرو\n(أسلمت وجهي لمن أسملت ... له المزن تحمل عذبا زلالا)\n(وأسلمت وجهي لمن أسلمت ... له الأرض تحمل صخرا ثقالا)\n(دحاها فلما استوت شدها ... سواء وأرسى عليها الجبالا)","topic":"خبر زيد بن عمرو ونسبه","topicNo":23,"sp":1,"spl":"قصته مع النبي — شعر زهير بن جناب في الكبر"},
{"id":"b23-3","bab":"الجزء 3","sec":"شعر زهير بن جناب في الكبر","page":"ج3 ص121","text":"وأما زهير بن جناب الكلبي فإنه أحد المعمرين يقال إنه عمر مائة وخمسين سنة وهو فيما ذكر أحد الذين شربوا الخمر في الجاهلية حتى قتلتهم وكان قد بلغ من السن الغاية التي ذكرناها فقال ذات يوم إن الحي ظاعن فقال عبد الله بن عليم بن جناب إن الحي مقيم فقال زهير إن الحي مقيم فقال عبد الله إن الحي ظاعن فقال من هذا الذي يخالفني منذ اليوم قيل ابن أخيك عبد الله بن عليم فقال أو ما هاهنا أحد ينهاه عن ذلك قالوا لا فغضب وقال لا أراني قد خولفت ثم دعا بالخمر فشربها صرفا بغير مزاج وعلى غير طعام حتى قتلته وهو الذي يقول في ذم الكبر وطول الحياة\n(الموت خير للفتى ... فليهلكن وبه بقيه)\n(من أن يرى الشيخ البجال ... إذا تهادى بالعشيه)\n(أبني أن أهلك فقد ... أورثتكم مجدا بنيه)\n(وتركتكم أبناء سادات ... زنادكم وريه)\n(بل كل ما نال الفتى ... قد نلته إلا التحيه)\nأما مدرج الريح فاسمه عامر بن المجنون الجرمي وإنما سمي مدرج الريح بشعر قاله في امرأة كان يزعم أنه يهواها من الجن وأنها تسكن الهواء وتتراءى له وكان محمقا وشعره هذا\n(لابنة الجني في الجو طلل ... دارس الآيات عاف كالخلل)\n(درسته الريح من بين صبا ... وجنوب درجت حينا وطل)\nصوت الغناء فيه لحنين ثقيل أول بالوسطى عن الهشامي وابن المكي وذكر حبش أنه لمعبد وذكر عمرو بن بانة أن لحن حنين من خفيف الثقيل الأول بالبنصر وأخبار عامر بن المجنون تذكر في موضع آخر إن شاء الله تعالى وأما سعية بن غريض فقد كان ذكر خبر جده السموأل بن غريض بن عاديا في موضع غير هذا وكان سعية بن غريض شاعرا وهو الذي يقول لما حضرته الوفاة يرثي نفسه صوت\n(يا ليت شعري حين يذكر ... ماذا تؤبنني به أنواحي)\n(أيقلن لا تبعد فرب كريهة ... فرجتها ببشارة وسماح)\n(وإذا دعيت لصعبة سهلتها ... أدعى بأفلح تارة ونجاح)\nناه ابن سريج ثاني ثقيل بالبنصر على مذهب إسحاق من رواية عمرو وأسلم سعية وعمر عمرا طويلا ويقال إنه مات في آخر خلافة معاوية","topic":"خبر زيد بن عمرو ونسبه","topicNo":23,"sp":1,"spl":"قصته مع النبي — شعر زهير بن جناب في الكبر"},
{"id":"b23-4","bab":"الجزء 3","sec":"خبر سعية بن غريض مع معاوية بن أبي سفيان","page":"ج3 ص123","text":"فأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية عن الهيثم بن عدي قال حج معاوية حجتين في خلافته وكانت له ثلاثون بغلة يحج عليها نساؤه وجواريه قال فحج في إحداهما فرأى شيخا يصلي في المسجد الحرام عليه ثوبان أبيضان فقال من هذا قالوا سعية بن غريض وكان من اليهود فأرسل إليه يدعوه فأتاه رسوله فقال أجب أمير المؤمنين قال أو ليس قد مات أمير المؤمنين قيل فأجب معاوية فأتاه فلم يسلم عليه بالخلافة فقال له معاوية ما فعلت أرضك التي بتيماء قال يكسى منها العاري ويرد فضلها على الجار قال أفتبيعها قال نعم قال بكم قال بستين ألف دينار ولولا خلة أصابت الحي لم أبعها قال لقد أغليت قال أما لو كانت لبعض أصحابك لأخذتها بستمائة ألف دينار ثم لم تبل قال أجل وإذ بخلت بأرضك فأنشدني شعر أبيك يرثي به نفسه فقال قال أبي\n(يا ليت شعري حين أندب هالكا ... ماذا تؤبنني به أنواحي)\n(أيقلن لا تبعد فرب كريهة ... فرجتها بشجاعة وسماح)\n(ولقد ضربت بفضل مالي حقه ... عند الشتاء وهبة الأرواح)\n(ولقد أخذت الحق غير مخاصم ... ولقد رددت الحق غير ملاحي)\n(وإذا دعيت لصعبة سهلتها ... أدعى بأفلح مرة ونجاح)\nفقال أنا كنت بهذا الشعر أولى من أبيك قال كذبت ولؤمت قال أما كذبت فنعم وأما لؤمت فلم قال لأنك كنت ميت الحق في الجاهلية وميته في الإسلام أما في الجاهلية فقاتلت النبي والوحي حتى جعل الله عز و جل كيدك المردود وأما في الإسلام فمنعت ولد رسول الله الخلافة وما أنت وهي وأنت طليق ابن طليق فقال معاوية قد خرف الشيخ فأقيموه فأخذ بيده فأقيم وسعية هذا هو الذي يقول صوت\n(يا دار سعدى بأقصى تلعة النعم ... حييت دارا على الإقواء والقدم)\n(وما بجزعك إلا الوحش ساكنة ... وهامد من رماد القدر والحمم)\n(عجنا فما كلمتنا الدار إذ سئلت ... وما بها عن جواب خلت من صمم)\nلشعر لسعية بن غريض والغناء لابن محرز ثقيل أول بالسبابة في مجرى البنصر","topic":"خبر زيد بن عمرو ونسبه","topicNo":23,"sp":2,"spl":"خبر سعية بن غريض مع معاوية بن أبي سفيان"},
{"id":"b24-1","bab":"الجزء 3","sec":"أخبار ابن صاحب الوضوء ونسبه","page":"ج3 ص125","text":"اسمه محمد بن عبد الله ويكنى أبا عبد الله مولى بني أمية وهو من أهل المدينة وكان أبوه على ميضأة المدينة فسمي صاحب الوضوء وهو قليل الصنعة لم يذكر له إسحاق إلا صوتين كلاهما في خفيف الثقيل المعروف بالماخوري ولا ذكر له غير إسحاق سواهما إلا ما هو مرسوم في الكتاب الباطل المنسوب إلى إسحاق فإن له فيه شيئا كثيرا لا أصل له وفي كتاب حبش الصيني وهو رجل لا يحصل ما يقوله ويرويه أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن جده عن سياط عن يونس الكاتب قال غنى ابن صاحب الوضوء في شعر النابغة\n(خطاطيف حجن في حبال متينة ... تمد بها أيد إليك نوازع)\nفي شعر بعض اليهود\n(إرفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\nأجاد فيهما ما شاء وأحسن غاية الإحسان فقيل له ألا تزيد وتصنع شيئا آخر\nفقال لا والله حتى أرى غيري قد صنع مثل ما صنعت وأزيد وإلا فحسبي هذا","topic":"أخبار ابن صاحب الوضوء ونسبه","topicNo":24,"sp":0,"spl":"أخبار ابن صاحب الوضوء ونسبه — عبد الله بن عامر يغني صوتا في المحراب"},
{"id":"b24-2","bab":"الجزء 3","sec":"عبد الله بن عامر يغني صوتا في المحراب","page":"ج3 ص125","text":"أخبرني أحمد بن عبد الله بن عمار وأحمد بن عبد العزيز الجوهري وإسماعيل بن يونس الشيعي قالوا حدثنا عمر بن شبة قال حدثنا عيسى بن عبد الله بن محمد بن عمر بن علي قال ابن عمار في خبره وكان يسمى المبارك قد حدثنا أبو مسلمة المصبحي قال قدم علينا أسود من أهل الكوفة فغنى\n(ارفع ضعيفك لا يحر بك ضعفه ... يوما فتدركه العواقب قد نما)\nال فمررت بعبد الله بن عامر الأسلمي وكان يؤمنا وهو قائم يصلي الظهر فقلت له قدم علينا أسود من الكوفة يغني كذا وكذا فأجاده فأشار إلي بيده أن اجلس فلما قضى صلاته قال أخذته عنه قلت نعم قال فأمره علي ففعلت قال فلما كان بالليل صلى بنا فأداه في المحراب","topic":"أخبار ابن صاحب الوضوء ونسبه","topicNo":24,"sp":0,"spl":"أخبار ابن صاحب الوضوء ونسبه — عبد الله بن عامر يغني صوتا في المحراب"},
{"id":"b25-1","bab":"الجزء 3","sec":"صوت من المائة المختارة التي رواها علي بن يحيى","page":"ج3 ص126","text":"(يا ليلتي تزداد نكرا ... من حب من أحببت بكرا)\n(حوراء إن نظرت إليك ... سقتك بالعينين خمرا)\nلشعر لبشار والغناء في اللحن المختار ليزيد حوراء رمل بالبنصر عن عمرو ويحيى المكي وإسحاق وفيه لسياط خفيف رمل بالوسطى عن عمرو وإبراهيم الموصلي","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":0,"spl":"صوت من المائة المختارة التي رواها علي بن يحيى — أخبار بشار بن برد ونسبه"},
{"id":"b25-2","bab":"الجزء 3","sec":"أخبار بشار بن برد ونسبه","page":"ج3 ص127","text":"هو فيما ذكره الحسن بن علي عن محمد بن القاسم بن مهرويه عن غيلان الشعوبي بشار بن برد بن يرجوخ بن أزدكرد بن شروستان بن بهمهن بن دارا بن فيروز بن كرديه بن ماهفيدان بن دادان بن بهمن بن أزدكرد بن حسيس بن مهران ابن خسروان بن أخشين بن شهرداد بن نبوذ بن ما خرشيدا نماذ بن شهريار بن بنداد سيحان بن مكرر بن ادريوس بن يستاسب بن لهراسف قال وكان يرجوخ بن طخارستان من سبي المهلب بن أبي صفرة ويكنى بشار أبا معاذ ومحله في الشعر وتقدمه طبقات المحدثين فيه بإجماع الرواة ورياسته عليهم من غير اختلاف في ذلك يغني عن وصفه وإطالة ذكر محله وهو من مخضرمي شعراء الدولتين العباسية والأموية قد شهر فيهما ومدح وهجا وأخذ سني الجوائز مع الشعراء أخبرنا يحيى بن علي بن يحيى المنجم قال قال حميد بن سعيد كان بشار من شعب ادريوس بن يستاسب الملك بن لهراسف الملك قال وهو بشار بن برد بن بهمن بن أزدكرد بن شروستان بن بهمن بن دارا بن فيروز قال وكان يكنى أبا معاذ\nوأخبرني يحيى بن علي ومحمد بن عمران الصيرفي وغيرهما عن الحسن بن عليل العنزي عن خالد بن يزيد بن وهب بن جرير بن حازم عن أبيه قال كان بشار بن برد بن يرجوخ وأبوه برد من قن خيرة القشيرية امرأة المهلب بن أبي صفرة وكان مقيما لها في ضيعتها بالبصرة المعروفة بخيرتان مع عبيد لها وإماء فوهبت بردا بعد أن زوجته لامرأة من بني عقيل كانت متصلة بها فولدت له امرأته وهو في ملكها بشارا فأعتقته العقيلية وأخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال كان برد أبو بشار مولى أم الظباء العقيلية السدوسية فادعى بشار أنه مولى بني عقيل لنزوله فيهم وأخبرني أحمد بن العباس العسكري قال حدثنا العنزي قال حدثني رجل من ولد بشار يقال له حمدان كان قصارا بالبصرة قال ولاؤنا لبني عقيل فقلت لأيهم فقال لبني ربيعة بن عقيل وأخبرني وكيع قال حدثني سليمان المدني قال قال أحمد بن معاوية الباهلي كان بشار وأمه لرجل من الأزد فتزوج امرأة من بني عقيل فساق إليها بشارا وأمه في صداقها وكان بشار ولد مكفوفا فأعتقته العقيلية أخبرني محمد بن عمران الصيرفي قال حدثني الحسن بن عليل العنزي قال\nحدثنا قعنب بن المحرز الباهلي قال حدثني محمد بن الحجاج قال باعت أم بشار بشارا على أم الظباء السدوسية بدينارين فأعتقته وأم الظباء امرأة أوس بن ثعلبة أحد بني تيم اللات بن ثعلبة وهو صاحب قصر أوس بالبصرة وكان أوس أحد فرسان بكر بن وائل بخراسان","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":0,"spl":"صوت من المائة المختارة التي رواها علي بن يحيى — أخبار بشار بن برد ونسبه"},
{"id":"b25-3","bab":"الجزء 3","sec":"كان أبوه طيانا","page":"ج3 ص129","text":"أخبرني الحسن بن علي الخفاف قال حدثنا العنزي قال حدثنا محمد بن زيد العجلي قال أخبرني بدر بن مزاحم أن بردا أبا بشار كان طيانا يضرب اللبن وأراني أبي بيتين لنا فقال لي لبن هذين البيتين من ضرب برد أبي بشار فسمع هذه الحكاية حماد عجرد فهجاه فقال\n(يابن برد إخسأ إليك فمثل الكلب ... في الناس أنت لا الإنسان)\n(بل لعمري لأنت شر من الكلب ... وأولى منه بكل هوان)\n(ولريح الخنزير أهون من ريحك ... يابن الطيان ذي التبان)\nخبرني يحيى بن علي قال حدثنا أبو أيوب المديني عن أبي الصلت البصري عن أبي عدنان قال حدثني يحيى بن الجون العبدي راوية بشار قال قال لما دخلت على المهدي قال لي فيمن تعتد يا بشار فقلت أما\nاللسان والزي فعربيان وأما الأصل فعجمي كما قلت في شعري يا أمير المؤمنين\n(ونبئت قوما بهم جنة ... يقولون من ذا وكنت العلم)\n(ألا أيها السائلي جاهدا ... ليعرفني أنا أنف الكرم)\n(نمت في الكرام بني عامر ... فروعي وأصلي قريش العجم)\n(فإني لأغني مقام الفتى ... وأصبي الفتاة فما تعتصم)\nال وكان أبو دلامة حاضرا فقال كلا لوجهك أقبح من ذلك ووجهي مع وجهك فقلت كلا والله ما رأيت رجلا أصدق على نفسه وأكذب على جليسه منك والله إني لطويل القامة عظيم الهامة تام الألواح أسجح الخدين ولرب مسترخي المذروين للعين فيه مراد قد جلس من الفتاة حجرة وجلست منها حيث أريد فأنت مثلي يا مرضعان قال فسكت عني ثم قال لي المهدي فمن أي العجم أصلك فقلت من أكثرها في الفرسان وأشدها على الأقران أهل طخارستان فقال بعض القوم أولئك الصغد فقلت لا الصغد تجار فلم يردد ذلك المهدي\nوكان بشار كثير التلون في ولائه شديد الشغب والتعصب للعجم مرة يقول يفتخر بولائه في قيس\n(أمنت مضرة الفحشاء أني ... أرى قيسا تضر ولا تضار)\n(كأن الناس حين تغيب عنهم ... نبات الأرض أخطأه القطار)\n(وقد كانت بتدمر خيل قيس ... فكان لتدمر فيها دمار)\n(بحي من بني عيلان شوس ... يسير الموت حيث يقال ساروا)\n(وما نلقاهم إلا صدرنا ... بري منهم وهم حرار)\nمرة يتبرأ من ولاء العرب فيقول\n(أصبحت مولى ذي الجلال وبعضهم ... مولى العريب فخذ بفضلك فافخر)\n(مولاك أكرم من تميم كلها ... أهل الفعال ومن قريش المشعر)\n(فارجع إلى مولاك غير مدافع ... سبحان مولاك الأجل الأكبر)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":1,"spl":"كان أبوه طيانا — لقبه وسبب ذلك"},
{"id":"b25-4","bab":"الجزء 3","sec":"لقبه وسبب ذلك","page":"ج3 ص131","text":"وقال يفتخر بولاء بني عقيل\n(إنني من بني عقيل بن كعب ... موضع السيف من طلى الأعناق)\nويكنى بشار أبا معاذ ويلقب بالمرعث أخبرني عمي ويحيى بن علي قالا حدثنا أبو أيوب المديني قال حدثني محمد بن سلام قال بشار المرعث هو بشار بن برد وإنما سمي المرعث بقوله\n(قال ريم مرعث ... ساحر الطرف والنظر)\n(لست والله نائلي ... قلت أو يغلب القدر)\n(أنت إن رمت وصلنا ... فانج هل تدرك القمر)\nال أبو أيوب وقال لنا ابن سلام مرة أخرى إنما سمي بشار المرعث لأنه كان لقميصه جيبان جيب عن يمينه وجيب عن شماله فإذا أراد لبسه ضمه عليه من غير أن يدخل رأسه فيه وإذا أراد نزعه حل أزرار وخرج منه فشبهت تلك الجيوب بالرعاث لاسترسالها وتدليها وسمي من أجلها المرعث أخبرنا يحيى بن علي قال حدثنا علي بن مهدي قال حدثني أبو حاتم قال قال لي أبو عبيدة لقب بشار بالمرعث لأنه كان في أذنه وهو صغير رعاث والرعاث القرطة واحدتها رعثة وجمعها رعاث ورعثات ورعثات الديك اللحم المتدلي تحت حنكه قال الشاعر\n(سقيت أبا المصرع إذ أتاني ... وذو الرعثات منتصب يصيح)\n(شرابا يهرب الذبان منه ... ويلثغ حين يشربه الفصيح)\nال والرعث الاسترسال والتساقط فكأن اسم القرطة اشتق منه أخبرني محمد بن عمران قال حدثني العنزي قال حدثنا محمد بن بدر\nالعجلي قال سمعت الأصمعي يذكر أن بشارا كان من أشد الناس تبرما بالناس وكان يقول الحمد لله الذي ذهب ببصري فقيل له ولم يا أبا معاذ قال لئلا أرى من أبغض وكان يلبس قميصا له لبنتان فإذا أراد أن ينزعه نزعه من أسفله فبذلك سمي المرعث أخبرني هاشم بن محمد أبو دلف الخزاعي قال حدثنا قعنب بن محرز عن الأصمعي قال كان بشار ضخما عظيم الخلق والوجه مجدورا طويلا جاحظ المقلتين قد تغشاهما لحم أحمر فكان أقبح الناس عمى وأفظعه منظرا وكان إذا أراد أن ينشد صفق بيديه وتنحنح وبصق عن يمينه وشماله ثم ينشد فيأتي بالعجب","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":1,"spl":"كان أبوه طيانا — لقبه وسبب ذلك"},
{"id":"b25-5","bab":"الجزء 3","sec":"هجاء أبي هشام الباهلي في عمى بشار","page":"ج3 ص133","text":"أخبرنا يحيى بن علي عن أبي أيوب المديني عن محمد بن سلام قال ولد بشار أعمى وهو الأكمه وقال في تصداق ذلك أبو هشام الباهلي يهجوه\n(وعبدي فقا عينيك في الرحم أيره ... فجئت ولم تعلم لعينيك فاقيا)\n(أأمك يا بشار كانت عفيفة ... علي إذا مشيي إلى البيت حافيا)\nال ولم يزل بشار منذ قال فيه هذين البيتين منكسرا أخبرنا هاشم بن محمد قال حدثنا الرياشي عن الأصمعي قال ولد بشار أعمى فما نظر إلى الدنيا قط وكان يشبه الأشياء بعضها ببعض في\nشعره فيأتى بما لا يقدر البصراء أن يأتوا بمثله فقيل له يوما وقد أنشد قوله\n(كأن مثار النقع فوق رؤوسنا ... وأسيافنا ليل تهاوى كواكبه)\nما قال أحد أحسن من هذا التشبيه فمن أين لك هذا ولم تر الدنيا قط ولا شيئا فيها فقال إن عدم النظر يقوي ذكاء القلب ويقطع عنه الشغل بما ينظر إليه من الأشياء فيتوفر حسه وتذكو قريحته ثم أنشدهم قوله\n(عميت جنينا والذكاء من العمى ... فجئت عجيب الظن للعلم موئلا)\n(وغاض ضياء العين للعلم رافدا ... لقلب إذا ضيع الناس حصلا)\n(وشعر كنور الروض لاءمت بينه ... بقول إذا ما أحزن الشعر أسهلا)\nخبرنا هاشم قال حدثنا العنزي عن قعنب بن محرز عن أبي عبد الله الشرادني قال كان بشار أعمى طويلا ضخما آدم مجدورا وأخبرني يحيى بن علي عن أبي أيوب المديني قال قال الحمراني قالت لي عمتي زرت قرابة لي في بني عقيل فإذا أنا بشيخ أعمى ضخم ينشد\n(من المفتون بشار بن برد ... إلى شيبان كهلهم ومرد)\n(بأن فتاتكم سلبت فؤادي ... فنصف عندها والنصف عندي)\nسألت عنه فقيل لي هذا بشار أخبرني محمد بن يحيى الصيرفي قال حدثنا العنزي قال حدثنا أبو زيد قال سمعت أبا محمد التوزي يقول قال بشار أزرى بشعري الأذان يقول إنه إسلامي\nوأخبرني حبيب بن نصر المهلي قال حدثنا عمر بن شبة قال قال أبو عبيدة قال بشار الشعر ولم يبلغ عشر سنين ثم بلغ الحلم وهو مخشي معرة لسانه قال وكان بشار يقول هجوت جريرا فأعرض عني واستصغرني ولو أجابني لكنت أشعر الناس","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":2,"spl":"هجاء أبي هشام الباهلي في عمى بشار — قول الأصمعي عنه إنه خاتمة الشعراء"},
{"id":"b25-6","bab":"الجزء 3","sec":"قول الأصمعي عنه إنه خاتمة الشعراء","page":"ج3 ص135","text":"وأخبرنا يحيى بن علي بن يحيى وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال كان الأصمعي يقول بشار خاتمة الشعراء والله لولا أن أيامه تأخرت لفضلته على كثير منهم قال أبو زيد كان راجزا مقصدا أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال حدثني أبو عبيدة قال سمعت بشارا يقول وقد أنشد في شعر الأعشى\n(وأنكرتني وما كان الذي نكرت ... من الحوادث إلا الشيب والصلعا)\nأنكره وقال هذا بيت مصنوع ما يشبه كلام الأعشى فعجبت لذلك فلما كان بعد هذا بعشر سنين كنت جالسا عند يونس فقال حدثني أبو عمرو بن العلاء أنه صنع هذا البيت وأدخله في شعر الأعشى\n(وأنكرتني وما كان الذي نكرت ... من الحوادث إلا الشيب والصلعا)\nفجعلت حينئذ أزداد عجبا من فطنة بشار وصحة قريحته وجودة نقده للشعر","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":2,"spl":"هجاء أبي هشام الباهلي في عمى بشار — قول الأصمعي عنه إنه خاتمة الشعراء"},
{"id":"b25-7","bab":"الجزء 3","sec":"عدد قصائده","page":"ج3 ص136","text":"أخبرني عمي قال حدثني الكراني قال حدثني أبو حاتم عن أبي عبيدة قال قال بشار لي اثنا عشر ألف بيت عين فقيل له هذا ما لم يكن يدعيه أحد قط سواك فقال لي اثنتا عشرة ألف قصيدة لعنها الله ولعن قائلها إن لم يكن في كل واحدة منها بيت عين وأخبرنا يحيى بن علي قال حدثنا علي بن مهدي عن أبي حاتم قال قلت لأبي عبيدة أمروان عندك أشعر أم بشار فقال حكم بشار لنفسه بالاستظهار أنه قال ثلاثة عشر ألف بيت جيد ولا يكون عدد الجيد من شعر شعراء الجاهلية والإسلام هذا العدد وما أحسبهم برزوا في مثلها ومروان أمدح للملوك أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا الأصمعي قال قال بشار الشعر وله عشر سنين فلما بلغ الحلم إلا وهو مخشي معرة اللسان بالبصرة قال وكان يقول هجوت جريرا فاستصغرني وأعرض عني ولو أجابني لكنت أشعر أهل زماني أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو العواذل زكريا بن هارون قال\nقال بشار لي اثنا عشر ألف بيت جيدة فقيل له كيف قال لي اثنتا عشرة ألف قصيدة أما في كل قصيدة منها بيت جيد وقال الجاحظ في كتاب البيان والتبيين وقد ذكره كان بشار شاعرا خطيبا صاحب منثور ومزدوج وسجع ورسائل وهو من المطبوعين أصحاب الإبداع والاختراع المفتنين في الشعر القائلين في أكثر أجناسه وضروبه قال الشعر في حياة جرير وتعرض له وحكى عنه أنه قال هجوت جريرا فأعرض عني ولو هاجاني لكنت أشعر الناس قال الجاحظ وكان بشار يدين بالرجعة ويكفر جميع الأمة ويصوب رأي إبليس في تقديم النار على الطين وذكر ذلك في شعره فقال\n(الأرض مظلمة والنار مشرقة ... والنار معبودة مذ كانت النار)\nال وبلغه عن أبي حذيفة واصل بن عطاء إنكار لقوله وهتف به فقال يهجوه\n(ما لي أشايع غزالا له عنق ... كنقنق الدو إن ولى وإن مثلا)\n(عنق الزرافة ما بالي وبالكم ... تكفرون رجالا كفروا رجلا)\nال فلما تتابع على واصل منه ما يشهد على إلحاده خطب به واصل وكان\nألثغ على الراء فكان يجتنبها في كلامه فقال أما لهذا الأعمى الملحد أما لهذا المشنف المكني بأبي معاذ من يقتله أما والله لولا أن الغيلة سجية من سجايا الغالية لدسست إليه من يبعج بطنه في جوف منزله أو في حفله ثم كان لا يتولى ذلك إلا عقيلي أو سدوسي فقال أبا معاذ ولم يقل بشارا وقال المشنف ولم يقل المرعث وقال من سجايا الغالية ولم يقل الرافضة وقال في منزله ولم يقل في داره وقال يبعج بطنه ولم يقل يبقر للثغة التي كانت به في الراء قال وكان واصل قد بلغ من اقتداره على الكلام وتمكنه من العبارة أن حذف الراء من جميع كلامه وخطبه وجعل مكانها ما يقوم مقامها","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":3,"spl":"عدد قصائده"},
{"id":"b25-8","bab":"الجزء 3","sec":"هو أحد أصحاب الكلام الستة","page":"ج3 ص138","text":"أخبرني يحيى بن علي قال حدثني أبي عن عافية بن شبيب قال حدثني أبو سهيل قال حدثني سعيد بن سلام قال كان بالبصرة ستة من أصحاب الكلام عمرو بن عبيد وواصل بن\nعطاء وبشار الأعمى وصالح بن عبد القدوس وعبد الكريم بن أبي العوجاء ورجل من الأزدي وقال أبو أحمد يعني جرير بن حازم فكانوا يجتمعون في منزل الأسدي ويختصمون عنده فأما عمرو وواصل فصارا إلى الاعتزال وأما عبد الكريم وصالح فصححا التوبة وأما بشار فبقي متحيرا مخلطا وأما الأزدي فمال إلى قول السمنية وهو مذهب من مذاهب الهند وبقي ظاهره على ما كان عليه قال فكان عبد الكريم يفسد الأحداث فقال له عمرو بن عبيد قد بلغني أنك تخلوا بالحدث من أحادثنا فتفسده وتستزله وتدخله في دينك فإن خرجت من مصرنا وإلا قمت فيك مقاما آتي فيه على نفسك فلحق بالكوفة فدل عليه محمد بن سليمان فقتله وصلبه بها وله يقول بشار\n(قل لعبد الكريم يابن أبي العوجاء ... بعت الإسلام بالكفر موقا)\n(لا تصلي ولا تصوم فإن صمت ... فبعض النهار صوما رقيقا)\n(لا تبالي إذا أصبت من الخمر ... عتيقا ألا تكون عتيقا)\n(ليت شعري غداة حليت في الجيد ... حنيفا حليت أم زنديقا)\n(أنت ممن يدور في لعنة الله ... صديق لمن ينيك الصديقا)\nخبرني هاشم بن محمد قال حدثني الرياشي قال سئل الأصمعي عن بشار\nومروان أيهما أشعر فقال بشار فسئل عن السبب في ذلك فقال لأن مروان سلك طريقا كثر ما يسلكه فلم يلحق من تقدمه وشركه فيه من كان في عصره وبشار سلك طريقا لم يسلك وأحسن فيه وتفرد به وهو أكثر تصرفا وفنون شعر وأغزر وأوسع بديعا ومروان لم يتجاوز مذاهب الأوائل أخبرني هاشم بن محمد قال حدثني العنزي عن أبي حاتم قال سمعت الأصمعي وقد عاد إلى البصرة من بغداد فسأله رجل عن مروان بن أبي حفصة فقال وجد أهل بغداد قد ختموا به الشعراء وبشار أحق بأن يختموهم به من مروان فقيل له ولم فقال وكيف لا يكون كذلك وما كان مروان في حياة بشار يقول شعرا حتى يصلحه له بشار ويقومه وهذا سلم الخاسر من طبقة مروان يزاحمه بين أيدي الخلفاء بالشعر ويساويه في الجوائز وسلم معترف بأنه تبع لبشار","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":4,"spl":"هو أحد أصحاب الكلام الستة — بشار أحسن الناس ابتداء بين المحدثين"},
{"id":"b25-9","bab":"الجزء 3","sec":"بشار أحسن الناس ابتداء بين المحدثين","page":"ج3 ص140","text":"أخبرني جحظة قال سمعت علي بن يحيى المنجم يقول سمعت من لا أحصي في الرواة يقولون أحسن الناس ابتداء في الجاهلية امرؤ القيس حيث يقول\n(ألا انعم صباحا أيها الطلل البالي ... )\nحيث يقول\n(قفا نبك من ذكرى حبيب ومنزل ... )\nوفي الإسلام القطامي حيث يقول\n(إنا محيوك فأسلم أيها الطلل ... )\nمن المحدثين بشار حيث يقول صوت\n(أبى طلل بالجزع أن يتكلما ... وماذا عليه لو أجاب متيما)\n(وبالفرع آثار بقين وباللوى ... ملاعب لا يعرفن إلا توهما)\nفي هذين البيتين لابن المكي ثاني ثقيل بالخنصر في مجرى الوسطى من كتابه وفيهما لابن جؤذر رمل أخبرني عمي عن الكراني عن أبي حاتم قال كان الأصمعي يعجب بشعر بشار لكثرة فنونه وسعة تصرفه ويقول كان مطبوعا لا يكلف طبعه شيئا متعذرا لا كمن يقول البيت ويحككه أياما وكان يشبه بشارا بالأعشى والنابغة الذبياني ويشبه مروان بزهير والحطيئة ويقول هو متكلف قال الكراني قال أبو حاتم وقلت لأبي زيد أيما أشعر بشار أم مروان\nفقال بشار أشعر ومروان أكفر قال أبو حاتم وسألت أبا زيد مرة أخرى عنهما فقال مروان أجد وبشار أهزل فحدثت الأصمعي بذلك فقال بشار يصلح للجد والهزل ومروان لا يصلح إلا لأحدهما","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":4,"spl":"هو أحد أصحاب الكلام الستة — بشار أحسن الناس ابتداء بين المحدثين","partial":1},
{"id":"b25-10","bab":"الجزء 3","sec":"كان الناس يعجبون بشعره ويتناشدونه","page":"ج3 ص142","text":"نسخت من كتاب هارون بن علي بن يحيى قال حدثنا علي بن مهدي قال حدثنا نجم بن النطاح قال عهدي بالبصرة وليس فيها غزل ولا غزلة إلا يروي من شعر بشار ولا نائحة ولا مغنية إلا تتكسب به ولا ذو شرف إلا وهو يهابه ويخاف معرة لسانه أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن المبارك قال حدثني أبي قال قلت لبشار ليس لأحد من شعراء العرب شعر إلا وقد قال فيه شيئا استنكرته العرب من ألفاظهم وشك فيه وإنه ليس في شعرك ما يشك فيه قال ومن أين يأتيني الخطأ ولدت هاهنا ونشأت في حجور ثمانين شيخا من فصحاء بني عقيل ما فيهم أحد يعرف كلمة من الخطأ وإن دخلت إلى نسائهم فنساؤهم أفصح منهم وأيفعت فأبديت إلى أن أدركت فمن أين يأتيني الخطأ\nأخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز ويحيى بن علي قالوا حدثنا عمر بن شبة قال كان الأصمعي يقول إن بشارا خاتمة الشعراء والله لولا أن أيامه تأخرت لفضلته على كثير منهم أخبرنا يحيى بن علي قال حدثني أبو الفضل المروزي قال حدثني قعنب بن المحرز الباهلي قال قال الأصمعي لقي أبو عمرو بن العلاء بعض الرواة فقال له يا أبا عمرو من أبدع الناس بيتا قال الذي يقول\n(لم يطل ليلى ولكن لم أنم ... ونفى عني الكرى طيف ألم)\n(روحي عني قليلا واعلمي ... أنني يا عبد من لحم ودم)\nال فمن أمدح الناس قال الذي يقول\n(لمست بكفي كفه أبتغي الغنى ... ولم أدر أن الجود من كفه يعدي)\n(فلا أنا منه ما أفاد ذوو الغنى ... أفدت وأعداني فأتلفت ما عندي)\nال فمن أهجى الناس قال الذي يقول\n(رأيت السهيلين استوى الجود فيهما ... على بعد ذا من ذاك في حكم حاكم)\n(سهيل بن عثمان يجود بماله ... كما جاد بالوجعا سهيل بن سالم)\nقال وهذه الأبيات كلها لبشار","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":5,"spl":"كان الناس يعجبون بشعره ويتناشدونه — خبره مع حمدان الخراط"},
{"id":"b25-11","bab":"الجزء 3","sec":"نسبة ما في هذا الخبر من الأشعار التي يغنى فيها","page":"ج3 ص144","text":"صوت\n(لم بطل ليلى ولكن لم أنم ... ونفى عني الكرى طيف ألم)\n(وإذا قلت لها جودي لنا ... خرجت بالصمت عن لا ونعم)\n(نفسي يا عبد عني واعلمي ... أنني يا عبد من لحم ودم)\n(إن في بردي جسما ناحلا ... لو توكأت عليه لانهدم)\n(ختم الحب لها في عنقي ... موضع الخاتم من أهل الذمم)\nناه إبراهيم هزجا بالسبابة في مجرى الوسطى عن ابن المكي والهشامي وفيه لقعنب الأسود خفيف ثقيل فأما الأبيات التي ذكر أبو عمرو أنه فيها أمدح الناس وأولها\n(لمست بكفي كفه أبتغي الغنى ... )\nإنه ذكر أنها لبشار وذكر الزبير بن بكار أنها لابن الخياط في المهدي وذكر له فيها معه خبرا طويلا قد ذكرته في أخبار ابن الخياط في هذا الكتاب أخبرنا يحيى بن علي قال حدثنا علي بن مهدي الكسروي قال حدثنا أبو حاتم قال كان بشار كثير الولوع بديسم العنزي وكان صديقا له وهو مع ذلك يكثر هجاءه وكان ديسم لا يزال يحفظ شيئا من شعر حماد وأبي هشام الباهلي في بشار فبلغه ذلك فقال فيه\n(أديسم يابن الذئب من نجل زارع ... أتروي هجائي سادرا غير مقصر)\nال أبو حاتم فأنشدت أبا زيد هذا البيت وسأتله ما يقول فيه فقال لمن هذا الشعر فقلت لبشار يقوله في ديسم العنزي فقال قاتله الله ما أعلمه بكلام العرب ثم قال الديسم ولد الذئب من الكلبة ويقال للكلاب أولاد زارع والعسبار ولد الضبع من الذئب والسمع ولد الذئب من الضبع وتزعم العرب أن السمع لا يموت حتف أنفه وأنه أسرع من الريح وإنما هلاكه بعرض من أعراض الدنيا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":5,"spl":"كان الناس يعجبون بشعره ويتناشدونه — خبره مع حمدان الخراط","partialRef":{"sid":"b25-10","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b25-12","bab":"الجزء 3","sec":"خبره مع حمدان الخراط","page":"ج3 ص145","text":"أخبرنا حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال كان بالبصرة رجل يقال له حمدان الخراط فاتخذ جاما لإنسان كان بشار عنده فسأله بشار أن يتخذ له جاما فيه صور طير تطير فاتخذه له وجاءه به فقال له ما في هذا الجام فقال صور طير تطير فقال له قد كان ينبغي أن تتخذ فوق هذه الطير طائرا من الجوارح كأنه يريد صيدها فإنه كان أحسن قال لم أعلم قال بلى قد علمت ولكن علمت أني أعمى لا أبصر شيئا وتهدده بالهجاء فقال له حمدان لا تفعل فإنك تندم قال أو تهددني أيضا قال نعم قال فأي شيء تستطيع أن تصنع بي إن هجوتك قال أصورك على باب داري بصورتك هذه وأجعل من خلفك قردا ينكحك حتى يراك الصادر والوارد قال بشار اللهم اخزه أنا أمازحه وهو يأبى إلا الجد","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":5,"spl":"كان الناس يعجبون بشعره ويتناشدونه — خبره مع حمدان الخراط"},
{"id":"b25-13","bab":"الجزء 3","sec":"قول بشار في جرير بن المنذر السدوسي","page":"ج3 ص146","text":"أخبرنا يحيى بن علي بن يحيى والحسن بن علي ومحمد بن عمران الصيرفي قالوا حدثنا العنزي قال حدثني جعفر بن محمد العدوي عن محمد بن سلام قال حدثني مخلد أبو سفيان قال كان جرير بن المنذر السدوسي يفاخر بشارا فقال فيه بشار\n(أمثل بني مضر وائل ... فقدتك من فاخر ما أجن)\n(أفي النوم هذا أبا منذر ... فخيرا رأيت وخيرا يكن)\n(رأيتك والفخر في مثلها ... كعاجنة غير ما تطحن)\nقال يحيى في خبره فحدثني محمد بن القاسم قال حدثني عاصم بن وهب أبو شبل الشاعر البرجمي قال حدثني محمد بن الحجاج السراداني قال كنا عند بشار وعنده رجل ينازعه في اليمانية والمضرية إذ أذن فقال له بشار رويدا تفهم هذا الكلام فلما قال أشهد أن محمدا رسول الله قال له بشار أهذا الذي نودي باسمه مع اسم الله عز و جل من مضر هو أم من صداء وعك وحمير فسكت الرجل أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال أنشد بشار قول الشاعر\n(وقد جعل الأعداء ينتقصوننا ... وتطمع فينا ألسن وعيون)\n(ألا إنما ليلى عصا خيزرانة ... إذا غمزوها بالأكف تلين)\nقال والله لو زعم أنها عصا مخ أو عصا زبد لقد كان جعلها جافية خشنة بعد أن جعلها عصا ألا قال كما قلت\n(ودعجاء المحاجر من معد ... كأن حديثها ثمر الجنان)\n(إذا قامت لمشيتها تثنت ... كأن عظامها من خيزران)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال أخبرني محمد بن صالح بن الحجاج قال قلت لبشار إني أنشدت فلانا قولك\n(إذا أنت لم تشرب مرارا على القذى ... ظمئت وأي الناس تصفو مشاربه)\nقال لي ما كنت أظنه إلا لرجل كبير فقال لي بشار ويلك أفلا قلت له هو والله لأكبر الجن والإنس","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":6,"spl":"قول بشار في جرير بن المنذر السدوسي — خبره مع امرأة وعدته أن تزوره ليلا وأخلفت"},
{"id":"b25-14","bab":"الجزء 3","sec":"خبره مع امرأة وعدته أن تزوره ليلا وأخلفت","page":"ج3 ص147","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو الشبل عن محمد بن الحجاج قال كان بشار يهوى امرأة من أهل البصرة فراسلها يسألها زيارته فوعدته بذلك ثم أخلفته وجعل ينتظرها ليلته حتى أصبح فلما لم تأته أرسل إليها يعاتبها فاعتذرت بمرض أصابها فكتب إليها بهذه الأبيات\n(يا ليلتي تزداد نكرا ... من حب من أحببت بكرا)\n(حوراء إن نظرت إليك ... سقتك بالعينين خمرا)\n(وكأن رجع حديثها ... قطع الرياض كسين زهرا)\n(وكأن تحت لسانها ... هاروت ينفث فيه سحرا)\n(وتخال ما جمعت عليه ... ثيابها ذهبا وعطرا)\n(وكأنها برد الشراب ... صفا ووافق منك فطرا)\n(جنية إنسية ... أو بين ذاك أجل أمرا)\n(وكفاك أني لم أحط ... بشكاة من أحببت خبرا)\n(إلا مقالة زائر ... نثرت لي الأحزان نثرا)\n(متخشعا تحت الهوى ... عشرا وتحت الموت عشرا)\nدثني جحظة قال حدثني علي بن يحيى قال كان إسحاق الموصلي لا يعتد ببشار ويقول هو كثير التخليط في شعره وأشعاره مختلفة لا يشبه بعضها بعضا أليس هو القائل\n(إنما عظم سليمى حبتي ... قصب السكر لا عظم الجمل)\n(وإذا أدنيت منها بصلا ... غلب المسك على ريح البصل)\nو قال كل شيء جيد ثم أضيف إلى هذا لزيفه قال وكان يقدم عليه مروان ويقول هذا هو أشد استواء شعر منه وكلامه ومذهبه أشبه بكلام العرب ومذاهبها وكان لا يعد أبا نواس البتة ولا يرى فيه خيرا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":6,"spl":"قول بشار في جرير بن المنذر السدوسي — خبره مع امرأة وعدته أن تزوره ليلا وأخلفت"},
{"id":"b25-15","bab":"الجزء 3","sec":"هجاؤه للمنصور","page":"ج3 ص149","text":"حدثنا محمد بن علي بن يحيى قال حدثنا محمد بن زكريا قال حدثنا محمد بن عبد الرحمن التيمي قال دخل بشار إلى إبراهيم بن عبد الله بن حسن فأنشده قصيدة يهجو فيها المنصور ويشير عليه برأي يستعمله في أمره فلما قتل إبراهيم خاف بشار فقلب الكنية وأظهر أنه كان قالها في أبي مسلم وحذف منها أبياتا وأولها\n(أبا جعفر ما طول عيش بدائم ... ولا سالم عما قليل بسالم)\nلب هذا البيت فقال أبا مسلم\n(على الملك الجبار يقتحم الردى ... ويصرعه في المأزق المتلاحم)\n(كأنك لم تسمع بقتل متوج ... عظيم ولم تسمع بفتك الأعاجم)\n(تقسم كسرى رهطه بسيوفهم ... وأمسى أبو العباس أحلام نائم)\nيعني الوليد بن يزيد\n(وقد كان لا يخشى انقلاب مكيدة ... عليه ولا جري النحوس الأشائم)\n(مقيما على اللذات حتى بدت له ... وجوه المنايا حاسرات العمائم)\n(وقد ترد الأيام غرا وربما ... وردن كلوحا باديات الشكائم)\n(ومروان قد دارت على رأسه الرحى ... وكان لما أجرمت نزر الجرائم)\n(فأصبحت تجري سادرا في طريقهم ... ولا تتقي أشباه تلك النقائم)\n(تجردت للإسلام تعفو سبيله ... وتعري مطاه لليوث الضراغم)\n(فما زلت حتى استنصر الدين أهله ... عليك فعاذوا بالسيوف الصوارم)\n(فرم وزرا ينجيك يابن سلامة ... فلست بناج من مضيم وضائم)\nعل موضع يابن سلامة يابن وشيكة وهي أم أبي مسلم\n(لحا الله قوما رأسوك عليهم ... وما زلت مرؤوسا خبيث المطاعم)\n(أقول لبسام عليه جلالة ... غدا أريحيا عاشقا للمكارم)\n(من الفاطميين الدعاة إلى الهدى ... جهارا ومن يهديك مثل ابن فاطم)\nذا البيت الذي خافه وحذفه بشار من الأبيات\n(سراج لعين المستضيء وتارة ... يكون ظلاما للعدو المزاحم)\n(إذا بلغ الرأي المشورة فاستعن ... براي نصيح أو نصيحة حازم)\n(ولا تعجل الشورى عليك غضاضة ... فإن الخوافي قوة للقوادم)\n(وما خير كف أمسك الغل أختها ... وما خير سيف لم يؤيد بقائم)\n(وخل الهوينا للضعيف ولا تكن ... نؤوما فإن الحزم ليس بنائم)\n(وحارب إذا لم تعط إلا ظلامة ... شبا الحرب خير من قبول المظالم)\nال محمد بن يحيى فحدثني الفضل بن الحباب قال سمعت أبا عثمان المازني يقول سمعت أبا عبيدة يقول ميمية بشار هذه أحب إلي من ميميتي جرير والفرزدق قال محمد وحدثني ابن الرياشي قال حدثني أبي قال قال الأصمعي قلت لبشار يا أبا معاذ إن الناس يعجبون من أبياتك في المشورة فقال لي يا أبا سعيد إن المشاور بين صواب يفوز بثمرته أو خطأ يشارك في مكروهه فقلت له أنت والله في قولك هذا أشعر منك في شعرك","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":7,"spl":"هجاؤه للمنصور — خبر بشار مع رجل في دار المهدي"},
{"id":"b25-16","bab":"الجزء 3","sec":"خبر بشار مع رجل في دار المهدي","page":"ج3 ص151","text":"حدثني الحسن بن علي قال حدثنا الفضل بن محمد اليزيدي عن إسحاق وحدثني به محمد بن مزيد بن أبي الأزهر عن حماد عن أبيه قال كان بشار جالسا في دار المهدي والناس ينتظرون الإذن فقال بعض موالي المهدي لمن حضر ما عندكم في قول الله عز و جل\n(وأوحى ربك إلى النحل أن اتخذي من الجبال بيوتا ومن الشجر ... )\nفقال له بشار النحل التي يعرفها الناس قال هيهات يا أبا معاذ النحل بنو هاشم\nوقوله ( يخرج من بطونها شراب مختلف ألوانه فيه شفاء للناس\nيعني العلم فقال له بشار أراني الله طعامك وشرابك وشفاءك فيما يخرج من بطون بني هاشم فقد أوسعتنا غثاثة فغضب وشتم بشارا وبلغ المهدي الخبر فدعا بهما فسألهما عن القصة فحدثه بشار بها فضحك حتى أمسك على بطنه ثم قال للرجل أجل فجعل الله طعامك وشرابك مما يخرج من بطون بني هاشم فإنك بارد غث وقال محمد بن مزيد في خبره إن الذي خاطب بشارا بهذه الحكاية وأجابه عنها من موالي المهدي المعلى بن طريف","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":7,"spl":"هجاؤه للمنصور — خبر بشار مع رجل في دار المهدي","partial":1},
{"id":"b25-17","bab":"الجزء 3","sec":"بشار يسخر من خال المهدي","page":"ج3 ص152","text":"أخبرنا الحسين بن يحيى عن حماد بن إسحاق عن أبيه قال دخل يزيد بن منصور الحميري على المهدي وبشار بين يديه ينشده قصيدة امتدحه بها فلما فرغ منها أقبل عليه يزيد بن منصور الحميري وكانت فيه غفلة فقال له يا شيخ ما صناعتك فقال أثقب اللؤلؤ فضحك المهدي ثم قال لبشار أعزب ويلك أتتنادر على خالي فقال له وما أصنع به يرى شيخا أعمى ينشد الخليفة شعرا ويسأله عن صناعته\nأخبرني الحسين عن حماد عن أبيه قال وقف على بشار بعض المجان وهو ينشد شعرا فقال له استر شعرك هذا كما تستر عورتك فصفق بشار بيديه وغضب وقال له من أنت ويلك قال أنا أعزك الله رجل من باهلة وأخوالي من سلول وأصهاري عكل واسمي كلب ومولدي بأضاخ ومنزلي بنهر بلال فضحك بشار ثم قال اذهب ويلك فأنت عتيق لؤمك قد علم الله أنك استترت مني بحصون من حديد أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني الفضل بن سعيد قال حدثني أبي قال مر بشار بقاص بالبصرة فسمعه يقول في قصصه من صام رجبا وشعبان ورمضان بنى الله له قصرا في الجنة صحنه ألف فرسخ في مثلها وعلوه ألف فرسخ وكل باب من أبواب بيوته ومقاصره عشرة فراسخ في مثلها قال فالتفت بشار إلى قائده فقال بئست والله الدار هذه في كانون الثاني قال الفضل بن سعيد وحدثني رجل من أهل البصرة ممن كان يتزوج بالنهاريات قال تزوجت امرأة منهن فاجتمعت معها في علو بيت وبشار تحتنا أو كنا في أسفل البيت وبشار في علوه مع امرأة فنهق حمار في الطريق فأجابه حمار في الجيران وحمار في الدار فارتجت الناحية بنهيقها وضرب الحمار الذي في\nالدار الأرض برجله وجعل يدقها بها دقا شديدا فسمعت بشارا يقول للمرأة نفخ يعلم الله في الصور وقامت القيامة أما تسمعين كيف يدق على أهل القبور حتى يخرجوا منها قال ولم يلبث أن فزعت شاة كانت في السطح فقطعت حبلها وعدت فألقت طبقا وغضارة إلى الدار فانكسرا وتطاير حمام ودجاج كن في الدار لصوت الغضارة وبكى صبي في الدار فقال بشار صح والله الخبر ونشر أهل القبور من قبورهم أزفت يشهد الله الآزفة وزلزلت الأرض زلزالها فعجبت من كلامه وغاظني ذلك فسألت من المتكلم فقيل لي بشار فقلت قد علمت أنه لا يتكلم بمثل هذا غير بشار","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":8,"spl":"بشار يسخر من خال المهدي"},
{"id":"b25-18","bab":"الجزء 3","sec":"بعض من نوادره","page":"ج3 ص154","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن محمد جدار قال حدثني قدامة بن نوح قال مر بشار برجل قد رمحته بغلة وهو يقول الحمد لله شكرا فقال له بشار استزده يزدك قال ومر به قوم يحملون جنازة وهم يسرعون المشي بها فقال ما لهم مسرعين أتراهم سرقوه فهم يخافون أن يلحقوا فيؤخذ منهم أخبرني يحيى بن علي بن يحيى عن أبيه عن عافية بن شبيب وأخبرني به وكيع عن محمد بن عمر بن محمد بن عبد الملك عن الحسن بن جمهور قالا\nتوفي ابن لبشار فجزع عليه فقيل له أجر قدمته وفرط افترطته وذخر أحرزته فقال ولد دفنته وثكل تعجلته وغيب وعدته فانتظرته والله لئن لم أجزع للنقص لا أفرح للزيادة وقال يرثيه\n(أجارتنا لا تجزعي وأنيبي ... أتاني من الموت المطل نصيبي)\n(بنيي على رغمي وسخطي رزئته ... وبدل أحجارا وجال قليب)\n(وكان كريحان الغصون تخاله ... ذوى بعد إشراق يسر وطيب)\n(أصيب بنيي حين أورق غصنه ... وألقى علي الهم كل قريب)\n(عجبت لإسراع المنية نحوه ... وما كان لو مليته بعجيب)\nخبرني يحيى بن علي قال ذكر عافية بن شبيب عن أبي عثمان الليثي وحدثني به الحسن بن علي عن ابن مهرويه عن أبي مسلم قالا رفع غلام بشار إليه في حساب نفقته جلاء مرآة عشرة دراهم فصاح به بشار وقال والله ما في الدنيا أعجب من جلاء مرآة أعمى بعشرة دراهم والله لو صدئت عين الشمس حتى يبقى العالم في ظلمة ما بلغت أجرة من يجلوها عشرة دراهم أخبرنا محمد ين يحيى الصولي قال حدثني المغيرة بن محمد المهلبي قال حدثنا أبو معاذ النميري قال قلت لبشار لم مدحت\nيزيد بن حاتم ثم هجوته قال سألني أن أنيكه فلم أفعل فضحكت ثم قلت فهو كان ينبغي له أن يغضب فما موضع الهجاء فقال أظنك تحب أن تكون شريكه فقلت أعوذ بالله من ذلك ويلك حدثني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا أحمد بن خلاد وأخبرنا يحيى بن علي ومحمد بن عمران الصيرفي قالا حدثنا العنزي قال حدثنا أحمد بن خلاد قال حدثني أبي قال قلت لبشار إنك لتجيء بالشيء الهجين المتفاوت قال وما ذاك قال قلت بينما تقول شعرا تثير به النقع وتخلع به القلوب مثل قولك\n(إذا ما غضبنا عضبة مضرية ... هتكنا حجاب الشمس أو تمطر الدما)\n(إذا ما أعرنا سيدا من قبيلة ... ذرى منبر صلى علينا وسلما)\nقول\n(ربابة ربة البيت ... تصب الخل في الزيت)\n(لها عشر دجاجات ... وديك حسن الصوت)\nقال لكل وجه وموضع فالقول الأول جد وهذا قلته في ربابة جاريتي وأنا لا آكل البيض من السوق وربابة هذه لها عشر دجاجات وديك فهي تجمع لي البيض وتحفظه عندها فهذا عندها من قولي أحسن من\n(قفا نبك من ذكرى حبيب ومنزل ... )\nعندك أخبرني الحسن بن علي قال حدثني أحمد بن محمد جدار قال حدثني قدامة بن نوح قال كان بشار يحشو شعره إذا أعوزته القافية والمعنى بالأشياء التي لا حقيقة لها فمن ذلك أنه أنشد يوما شعرا له فقال فيه\n(غنني للغريض يابن قنان ... )\nقيل له من ابن قنان هذا لسنا نعرفه من مغني البصرة قال وما عليكم منه ألكم قبله دين فتطالبوه به أو ثأر تريدون أن تدركوه أو كفلت لكم به فإذا غاب طالبتموني بإحضاره قالوا ليس بيننا وبينه شيء من هذا وإنما أردنا أن نعرفه فقال هو رجل يغني لي ولا يخرج من بيتي فقالوا له إلى متى قال مذ يوم ولد وإلى يوم يموت قال وأنشدنا أيضا في هذه القصيدة\n(ووافاني هلال السماء في البردان ... )\nقلنا يا أبا معاذ أين البردان هذا لسنا نعرفه بالبصرة فقال هو بيت في بيتي سميته البردان أفعليكم من تسميتي داري وبيوتها شيء فتسألوني عنه حدثني هاشم بن محمد الخزاعي قال حدثني أبو غسان دماذ واسمه رفيع بن سلمة قال حدثني يحيى بن الجون العبدي راوية بشار قال كنا عند بشار يوما فأنشدنا قوله\n(وجارية خلقت وحدها ... كأن النساء لديها خدم)\n(دوار العذارى إذا زرنها ... أطفن بحوراء مثل الصنم)\n(ظمئت إليها فلم تسقني ... بري ولم تشفني من سقم)\n(وقالت هويت فمت راشدا ... كما مات عروة غما بغم)\n(فلما رأيت الهوى قاتلي ... ولست بجار ولا بابن عم)\n(دسست إليها أبا مجلز ... وأي فتى إن أصاب اعتزم)\n(فما زال حتى أثابت له ... فراح وحل لنا ما حرم)\nقال له الرجل ومن أبو مجلز هذا يا أبا معاذ قال وما حاجتك إليه لك عليه دين أو تطالبه بطائلة هو رجل يتردد بيني وبين معارفي في رسائل قال وكان كثيرا ما يحشو شعره بمثل هذا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":9,"spl":"بعض من نوادره","partialRef":{"sid":"b25-9","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b25-19","bab":"الجزء 3","sec":"شعره في جارية","page":"ج3 ص158","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه قال كانت بالبصرة قينة لبعض ولد سليمان بن علي وكانت محسنة بارعة\nالظرف وكان بشار صديقا لسيدها ومداحا له فحضر مجلسه يوما والجارية تغني فسر بحضوره وشرب حتى سكر ونام ونهض بشار فقالت يا أبا معاذ أحب أن تذكر يومنا هذا في قصيدة ولا تذكر فيها اسمي ولا اسم سيدي وتكتب بها إليه فانصرف وكتب إليه\n(وذات دل كأن البدر صورتها ... باتت تغني عميد القلب سكرانا)\n(إن العيون التي في طرفها حور ... قتلننا ثم لم يحيين قتلانا)\n(فقلت أحسنت يا سؤلي ويا أملي ... فأسمعيني جزاك الله إحسانا)\n(يا حبذا جبل الريان من جبل ... وحبذا ساكن الريان من كانا)\n(قالت فهلا فدتك النفس أحسن من ... هذا لمن كان صب القلب حيرانا)\n(يا قوم أذني لبعض الحي عاشقة ... والأذن تعشق قبل العين أحيانا)\n(فقلت أحسنت أنت الشمس طالعة ... أضرمت في القلب والأحشاء نيرانا)\n(فأسمعيني صوتا مطربا هزجا ... يزيد صبا محبا فيك أشجانا)\n(يا ليتني كنت تفاحا مفلجة ... أو كنت من قضب الريحان ريحانا)\n(حتى إذا وجدت ريحي فأعجبها ... ونحن في خلوة مثلت إنسانا)\n(فحركت عودها ثم انثنت طربا ... تشدو به ثم لا تخفيه كتمانا)\n(أصبحت أطوع خلق الله كلهم ... لأكثر الخلق لي في الحب عصيانا)\n(فقلت أطربتنا يا زين مجلسنا ... فهات إنك بالإحسان أولانا)\n(لو كنت أعلم أن الحب يقتلني ... أعددت لي قبل أن ألقاك أكفانا)\n(فغنت الشرب صوتا مؤنقا رملا ... يذكي السرور ويبكي العين ألوانا)\n(لا يقتل الله من دامت مودته ... والله يقتل أهل الغدر أحيانا)\nوجه بالأبيات إليها فبعث إليه سيدها بألفي دينار وسر بها سرورا شديدا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":10,"spl":"شعره في جارية — هجاؤه لأعرابي"},
{"id":"b25-20","bab":"الجزء 3","sec":"هجاؤه لأعرابي","page":"ج3 ص160","text":"أخبرني أحمد بن العباس العسكري قال حدثني الحسن بن عليل قال حدثني علي بن منصور أبو الحسن الباهلي قال حدثني أبو عبد الله المقرئ الجحدري الذي كان يقرأ في المسجد الجامع بالبصرة قال دخل أعرابي على مجزأة بن ثور السدوسي وبشار عنده وعليه بزة الشعراء فقال الأعرابي من الرجل فقالوا رجل شاعر فقال أمولى هو أم عربي قالوا بل مولى فقال الأعرابي وما للموالي وللشعر فغضب بشار وسكت هنيهة ثم قال أتأذن لي يا أبا ثور قال قل ما شئت يا أبا معاذ فأنشأ بشار يقول\n(خليلي لا أنام على اقتسار ... ولا آبى على مولى وجار)\n(سأخبر فاخر الأعراب عني ... وعنه حين تأذن بالفخار)\n(أحين كسيت بعد العري خزا ... ونادمت الكرام على العقار)\n(تفاخر يابن راعية وراع ... بني الأحرار حسبك من خسار)\n(وكنت إذا ظمئت إلى قراح ... شركت الكلب في ولغ الإطار)\n(تريغ بخطبة كسر الموالي ... وينسيك المكارم صيد فار)\n(وتغدو للقنافذ تدريها ... ولم تعقل بدراج الديار)\n(وتتشح الشمال للابسيها ... وترعى الضأن بالبلد القفار)\n(مقامك بيننا دنس علينا ... فليتك غائب في حر نار)\n(وفخرك بين خنزير وكلب ... على مثلي من الحدث الكبار)\nفقال مجزأة للأعرابي قبحك الله فأنت كسبت هذا الشر لنفسك ولأمثالك أخبرني أحمد بن العباس العسكري قال حدثني العنزي عن الرياشي قال حضر بشار باب محمد بن سليمان فقال له الحاجب اصبر فقال إن الصبر لا يكون إلا على بلية فقال له الحاجب إني أظن أن وراء قولك هذا شرا ولن أتعرض له فقم فادخل","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":10,"spl":"شعره في جارية — هجاؤه لأعرابي"},
{"id":"b25-21","bab":"الجزء 3","sec":"خبر بشار مع هلال الرأي","page":"ج3 ص161","text":"أخبرني وكيع قال حدثنا أبو أيوب المديني عن محمد بن سلام قال\nقال هلال الرأي وهو هلال بن عطية لبشار وكان له صديقا يمازحه إن الله لم يذهب بصر أحد إلا عوضه بشيء فما عوضك قال الطويل العريض قال وما هذا قال ألا أراك ولا أمثالك من الثقلاء ثم قال له يا هلال أتطيعني في نصيحة أخصك بها قال نعم قال إنك كنت تسرق الحمير زمانا ثم تبت وصرت رافضيا فعد إلى سرقة الحمير فهي والله خير لك من الرفض\nقال محمد بن سلام وكان هلال يستثقل وفيه يقول بشار\n(وكيف يخف لي بصري وسمعي ... وحولي عسكران من الثقال)\n(قعودا حول دسكرتي وعندي ... كأن لهم علي فضول مال)\n(إذا ما شئت صبحني هلال ... وأي الناس أثقل من هلال)\nأخبرني أبو دلف الخزاعي بهذا الخبر عن عيسى بن إسماعيل عن ابن عائشة فذكر أن الذي خاطب بشارا بهذه المخاطبة ابن سيابة فلما أجابه بشار بالجواب المذكور قال له من أنت قال ابن سيابة فقال له يابن سيابة لو نكح الأسد ما افترس قال وكان يتهم بالأبنة قال أيوب وحدثني محمد بن سلام وغيره قالوا مر ابن أخي بشار به ومعه قوم فقال لرجل معه من هذا فقال ابن أخيك قال أشهد أن أصحابه أنذال قال وكيف علمت قال ليست لهم نعال أخبرنا محمد بن علي قال حدثني أبي قال حدثني عافية بن شبيب عن أبي دهمان الغلابي قال مررت ببشار يوما وهو جالس على بابه وحده وليس معه خلق وبيده مخصرة يلعب بها وقدامه طبق فيه تفاح وأترج فلما رأيته وليس عنده أحد تاقت نفسي إلى أن أسرق ما بين يديه فجئت قليلا قليلا وهو كاف يده حتى مددت يدي لأتناول منه فرفع القضيب وضرب به يدي ضربة كاد يكسرها فقلت\nله قطع الله يدك يابن الفاعلة أنت الآن أعمى فقال يا أحمق فأين الحس","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":11,"spl":"خبر بشار مع هلال الرأي — خبره مع نسوة خمس"},
{"id":"b25-22","bab":"الجزء 3","sec":"خبره مع نسوة خمس","page":"ج3 ص163","text":"أخبرني يحيى بن علي قال حدثني العنزي قال حدثني خالد ين يزيد بن وهب بن جرير عن أبيه قال كان لبشار في داره مجلسان مجلس يجلس فيه بالغداة يسميه البردان ومجلس يجلس فيه بالعشي اسمه الرقيق فأصبح ذات يوم فاحتجم وقال لغلامه أمسك علي بابي واطبخ لي من طيب طعامي وصف نبيذي قال فإنه لكذلك إذ قرع الباب قرعا عنيفا فقال ويحك يا غلام انظر من يدق الباب دق الشرط قال فنظر الغلام فقال له نسوة خمس بالباب يسألن أن تقول لهن شعرا ينحن به فقال أدخلهن فلما دخلن نظرن إلى النبيذ مصفى في قنانيه في جانب بيته قال فقالت واحدة منهن هو خمر وقالت الأخرى هو زبيب وعسل وقالت الثالثة نقيع زبيب فقال لست بقائل لكن حرفا أو تطعمن من طعامي وتشربن من شرابي قال فتماسكن ساعة ثم قالت واحدة منهن ما عليكن هو أعمى فكلن من طعامه واشربن من شرابه وخذن شعره فبلغ ذلك الحسن البصري فعابه وهتف ببشار فبلغه ذلك وكان بشار يسمي الحسن البصري القس فقال\n(لما طلعن من الرقيق ... علي بالبردان خمسا)\n(وكأنهن أهلة ... تحت الثياب زففن شمسا)\n(باكرن عطر لطيمة ... وغمسن في الجادي غمسا)\nصوت\n(لما طلعن خففنها ... وأصخن ما يهمسن همسا)\n(فسألنني من في البيوت ... فقلت ما يؤوين إنسا)\n(ليت العيون الطارفات ... طمسن عنا اليوم طمسا)\n(فأصبن من طرف الحديث ... لذاذة وخرجن ملسا)\n(لولا تعرضهن لي ... يا قس كنت كأنت قسا)\nغنى في هذه الأبيات يحيى المكي ولحنه رمل بالبنصر عن عمرو أخبرنا يحيى قال حدثني العنزي قال حدثنا علي بن محمد قال حدثني جعفر بن محمد النوفلي وكان يروي شعر بشار بن برد قال جئت بشارا ذات يوم فحدثني قال ما شعرت منذ أيام إلا بقارع يقرع بابي مع الصبح فقلت يا جارية انظري من هذا فرجعت إلي وقالت هذا مالك بن دينار فقلت ما هو من أشكالي ولا أضرابي ثم قلت ائذني له فدخل فقال يا أبا معاذ أتشتم أعراض\nالناس وتشبب بنسائهم فلم يكن عندي إلا أن دفعت عن نفسي وقلت لا أعود فخرج عني وقلت في أثره\n(غدا مالك بملاماته ... علي وما بات من باليه)\n(تناول خودا هضيم الحشى ... من الحور محظوظة عاليه)\n(فقلت دع اللوم في حبها ... فقبلك أعييت عذاليه)\n(وإني لأكتمهم سرها ... غداة تقول لها الجاليه)\n(عبيدة مالك مسلوبة ... وكنت معطرة حاليه)\n(فقالت على رقبة إنني ... رهنت المرعث خلخاليه)\n(بمجلس يوم سأوفي به ... ولو أجلب الناس أحواليه)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":11,"spl":"خبر بشار مع هلال الرأي — خبره مع نسوة خمس"},
{"id":"b25-23","bab":"الجزء 3","sec":"شعره في محبوبته فاطمة","page":"ج3 ص165","text":"أخبرنا يحيى بن علي قال حدثنا العنزي قال حدثني السميدع بن محمد الأزدي قال حدثني عبد الرحمن بن الجهم عن هشام بن الكلبي قال كان أول بدء بشار أنه عشق جارية يقال لها فاطمة وكان قد كف وذهب بصره فسمعها تغني فهويها وأنشأ يقول\n(درة بحرية مكنونة ... مازها التاجر من بين الدرر)\n(عجبت فطمة من نعتي لها ... هل يجيد النعت مكفوف البصر)\n(أمتا بدد هذا لعبي ... ووشاحي حله حتى انتثر)\n(فدعيني معه يا أمتا ... علنا في خلوة نقضي الوطر)\n(أقبلت مغضبة تضربها ... واعتراها كجنون مستعر)\n(بأبي والله ما أحسنه ... دمع عين يغسل الكحل قطر)\n(أيها النوام هبوا ويحكم ... واسألوني اليوم ما طعم السهر)\nخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني خالد بن يزيد بن وهب بن جرير قال حدثني أبي عن الحكم بن مخلد بن حازم قال مررت أنا ورجل من عكل من أبناء سوار بن عبد الله بقصر أوس فإذا نحن ببشار في ظل القصر وحده فقال لي العكلي لا بد لي من أن أعبث ببشار فقلت ويحك مه لا تعرض بنفسك وعرضك له فقال إني لا أجده في وقت أخلى منه في هذا الوقت قال فوقفت ناحية ودنا منه فقال يا بشار فقال من هذا الذي لا يكنيني ويدعوني باسمي قال سأخبرك من أنا فأخبرني أنت عن أمك أولدتك أعمى أم عميت بعد ما ولدتك قال وما تريد إلى ذلك قال وددت أنه فسح لك في بصرك ساعة لتنظر إلى وجهك في المرآة فعسى أن تمسك عن هجاء الناس وتعرف قدرك فقال ويحكم من هذا أما أحد يخبرني من هذا فقال له على رسلك أنا رجل من عكل وخالي يبيع الفحم بالعبلاء فما تقدر أن تقول لي قال لا شيء إذهب بأبي أنت في حفظ الله","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":12,"spl":"شعره في محبوبته فاطمة — قوله في خالد بن برمك"},
{"id":"b25-24","bab":"الجزء 3","sec":"قوله في خالد بن برمك","page":"ج3 ص166","text":"أخبرني علي بن سليمان الأخفش قال حدثني هارون بن علي بن يحيى\nالمنجم قال حدثني علي بن مهدي قال حدثني العباس بن خالد البرمكي قال كان الزوار يسمون في قديم الدهر إلى أيام خالد بن برمك السؤال فقال خالد هذا والله اسم استثقله لطلاب الخير وأرفع قدر الكريم عن أن يسمى به أمثال هؤلاء المؤملين لأن فيهم الأشراف والأحرار وأبناء النعيم ومن لعله خير ممن يقصد وأفضل أدبا ولكنا نسميهم الزوار فقال بشار يمدحه بذلك\n(حذا خالد في فعله حذو برمك ... فمجد له مستطرف وأصيل)\n(وكان ذوو الآمال يدعون قبله ... بلفظ على الإعدام فيه دليل)\n(يسمون بالسؤال في كل موطن ... وإن كان فيهم نابه وجليل)\n(فسماهم الزوار سترا عليهم ... فأستاره في المجتدين سدول)\nقال وقال بشار هذا الشعر في مجلس خالد في الساعة التي تكلم خالد بهذا الكلام في أمر الزوار فأعطاه لكل بيت ألف درهم أخبرني عمي قال حدثني محمد بن القاسم بن مهرويه قال حدثني أبو شبل عاصم بن وهب قال نهق حمار ذات يوم بقرب بشار فخطر بباله بيت فقال\n(ما قام أير حمار فامتلا شبقا ... إلا تحرك عرق في است تسنيم)\nال ولم يرد تسنيما بالهجاء ولكنه لما بلغ إلى قوله إلا تحرك عرق قال في است من ومر به تسنيم بن الحواري وكان صديقه فسلم عليه وضحك فقال\nفي است تسنيم علم الله فقال له أيش ويحك فأنشده البيت فقال له عليك لعنة الله فما عندك فرق بين صديقك وعدوك أي شي حملك على هذا ألا قلت في است حماد الذي هجاك وفضحك وأعياك وليست قافيتك على الميم فأعذرك قال صدقت والله في هذا كله ولكن ما زلت أقول في است من في است من ولا يخطر ببالي أحد حتى مررت وسلمت فرزقته فقال له تسنيم إذا كان هذا جواب السلام عليك فلا سلم الله عليك ولا علي حين سلمت عليك وجعل بشار يضحك ويصفق بيديه وتسنيم يشتمه أخبرنا عيسى بن الحسين قال حدثنا علي بن محمد النوفلي عن عمه قال قالت امرأة لبشار ما أدري لم يهابك الناس مع قبح وجهك فقال لها بشار ليس من حسنه يهاب الأسد","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":12,"spl":"شعره في محبوبته فاطمة — قوله في خالد بن برمك"},
{"id":"b25-25","bab":"الجزء 3","sec":"بشار وعقبة بن رؤبة في حضرة عقبة بن سلم","page":"ج3 ص168","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا محمد ابن الحجاج قال دخل بشار على عقبة بن سلم فأنشده بعض مدائحه فيه وعنده عقبة بن رؤبة ينشده رجزا يمدحه به فسمعه بشار وجعل يستحسن ما قاله إلى أن فرغ ثم أقبل على بشار فقال هذا طراز لا تحسنه أنت يا معاذ فقال له بشار إلي يقال هذا أنا والله أرجز منك ومن أبيك وجدك فقال له عقبة أنا والله وأبي فتحنا\nللناس باب الغريب وباب الرجز ووالله إني لخليق أن أسده عليهم فقال بشار ارحمهم رحمك الله فقال عقبة أتستخف بي يا أبا معاذ وأنا شاعر ابن شاعر ابن شاعر فقال له بشار فأنت إذا من أهل البيت الذين أذهب الله عنهم الرجس وطهرهم تطهيرا ثم خرج من عنده عقبة مغضبا فلما كان من غد غدا على عقبة ابن سلم وعنده عقبة بن رؤبة فأنشده أرجوزته التي مدحه فيها\n(يا طلل الحي بذات الصمد ... بالله خبر كيف كنت بعدي)\n(أوحشت من دعد وترب دعد ... سقيا لأسماء ابنة الأشد)\n(قامت تراءى إذ رأتني وحدي ... كالشمس تحت الزبرج المنقد)\n(صدت بخد وجلت عن خد ... ثم انثنت كالنفس المرتد)\n(عهدي بها سقيا له من عهد ... تخلف وعدا وتفي بوعد)\n(فنحن من جهد الهوى في جهد ... وزاهر من سبط وجعد)\n(أهدى له الدهر ولم يستهد ... أفواف نور الحبر المجد)\n(يلقى الضحى ريحانه بسجد ... بذلت من ذاك بكى لا يجدي)\n(وافق حظا من سعى بجد ... ما ضر أهل النوك ضعف الجد)\n(الحر يلحى والعصا للعبد ... وليس للملحف مثل الرد)\n(والنصف يكفيك من التعدي ... وصاحب كالدمل الممد)\n(حملته في رقعة من جلدي ... أرقب منه مثل يوم الورد)\n(حتى مضى غير فقيد الفقد ... وما درى ما رغبتي من زهدي)\n(اسلم وحييت أبا الملد ... مفتاح باب الحدث المنسد)\n(مشترك النيل وري الزند ... أغر لباس ثياب الحمد)\n(ما كان مني لك غير الود ... ثم ثناء مثل ريح الورد)\n(نسجته في محكمات الند ... فالبس طرازي غير مسترد)\n(لله أيامك في معد ... وفي بني قحطان غير عد)\n(يوما بذي طخفة عند الحد ... ومثله أودعت أرض الهند)\n(بالمرهفات والحديد السرد ... والمقربات المبعدات الجرد)\n(إذا الحيا أكدى بها لا تكدي ... تلحم أمرا وأمورا تسدي)\n(وابن حكيم إن أتاك يردي ... أصم لا يسمع صوت الرعد)\n(حييته بتحفة المعد ... فانهد مثل الجبل المنهد)\n(كل امرىء رهن بما يؤدي ... ورب ذي تاج كريم الجد)\n(كآل كسرى وكآل برد ... أنكب جاف عن سبيل القصد)\n(فضلته عن ماله والولد ... )\nفطرب عقبة بن سلم وأجزل صلته وقام عقبة بن رؤبة فخرج عن المجلس بخزي وهرب من تحت ليلته فلم يعد إليه وذكر لي أبو دلف هاشم بن محمد الخزاعي هذا الخبر عن الجاحظ وزاد فيه الجاحظ قال فانظر إلى سوء أدب عقبة بن رؤبة وقد أجمل بشار محضره وعشرته فقابله بهذه المقابلة القبيحة وكان أبوه أعلم خلق الله به لأنه قال له وقد فاخره بشعره أنت يا بني ذهبان الشعر إذا مت مات شعرك معك فلم يوجد من يرويه بعدك فكان كما قال له ما يعرف له بيت واحد ولا خبر غير هذا الخبر القبيح الإخبار عنه الدال علي سخفه وسقوطه وسوء أدبه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":13,"spl":"بشار وعقبة بن رؤبة في حضرة عقبة بن سلم — شعره في امرأة من البصرة","partial":1},
{"id":"b25-26","bab":"الجزء 3","sec":"شعره في امرأة من البصرة","page":"ج3 ص171","text":"أخبرني هاشم بن محمد قال حدثنا أبو غسان دماذ قال حدثنا أبو عبيدة قال كان بشار يهوى امرأة من أهل البصرة يقال لها عبيدة فخرجت عن البصرة إلى عمان مع زوجها فقال بشار فيها صوت\n(هوى صاحبي ريح الشمال إذا جرت ... وأشفى لقلبي أن تهب جنوب)\n(وما ذاك إلا أنها حين تنتهي ... تناهى وفيها من عبيدة طيب)\n(عذيري من العذال إذ يعذلونني ... سفاها وما في العاذلين لبيب)\nوت\n(يقولون لو عزيت قلبك لارعوى ... فقلت وهل للعاشقين قلوب)\n(إذا نطق القوم الجلوس فإنني ... مكب كأني في الجميع غريب)\nخبرني هاشم قال حدثني دماذ قال حدثني رجل من الأنصار قال جاء أبو الشمقمق إلى بشار يشكو إليه الضيقة ويحلف له أنه ما عنده شيء فقال له بشار والله ما عندي شيء يغنيك ولكن قم معي إلى عقبة بن سلم فقام معه فذكر له أبا الشمقمق وقال هو شاعر وله شكر وثناء فأمر له بخمسمائة درهم فقال له بشار\n(يا واحد العرب الذي ... أمسى وليس له نظير)\n(لو كان مثلك آخر ... ما كان في الدنيا فقير)\nأمر لبشار بألفي درهم فقال له أبو الشمقمق نفعتنا ونفعناك يا أبا معاذ فجعل بشار يضحك","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":13,"spl":"بشار وعقبة بن رؤبة في حضرة عقبة بن سلم — شعره في امرأة من البصرة"},
{"id":"b25-27","bab":"الجزء 3","sec":"خبره مع أبي جعفر المنصور","page":"ج3 ص172","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا زكريا بن يحيى أبو السكين الطائي قال حدثني زحر بن حصن قال حج المنصور فاستقبلناه بالرضم الذي بين زبالة والشقوق فلما\nرحل من الشقوق رحل في وقت الهاجرة فلم يركب القبة وركب نجيبا فسار بيننا فجعلت الشمس تضحك بين عينيه فقال إني قائل بيتا فمن أجازه وهبت له جبتي هذه فقلنا يقول أمير المؤمنين فقال\n(وهاجرة نصبت لها جبيني ... يقطع ظهرها ظهر العظايه)\nبدر بشار الأعمى فقال\n(وقفت بها القلوص ففاض دمعي ... على خدي وأقصر واعظايه)\nنزع الجبة وهو راكب فدفعها إليه فقلت لبشار بعد ذلك ما فعلت بالجبة فقال بشار بعتها والله بأربعمائة دينار أخبرني أحمد بن العباس العسكري قال حدثنا الحسن بن عليل العنزي قال حدثني علي بن محمد النوفلي قال حدثني عبد الرحمن بن العباس بن الفضل بن عبد الرحمن بن عياش بن أبي ربيعة عن أبيه قال كان بشار منقطعا إلي وإلى إخوتي فكان يغشانا كثيرا ثم خرج إبراهيم بن عبد الله فخرج معه عدة منا فلما قتل إبراهيم توارينا وحبس المنصور منا عدة من إخوتي فلما ولي المهدي أمن الناس جميعا وأطلق المحبوسين فقدمت بغداد أنا وإخوتي نلتمس أمانا من المهدي وكان الشعراء يجلسون بالليل في مسجد\nالرصافة ينشدون ويتحدثون فلم أطلع بشارا على نفسي إلا بعد أن أظهر لنا المهدي الأمان وكتب أخي إلى خليفته بالليل فصحت به يا أبا معاذ من الذي يقول\n(أحب الخاتم الأحمر ... من حب مواليه)\nأعرض عني وأخذ في بعض إنشاده شعره ثم صحت يا أبا معاذ من الذي يقول\n(إن سلمى خلقت من قصب ... قصب السكر لا عظم الجمل)\n(وإذا أدنيت منها بصلا ... غلب المسك على ريح البصل)\nغضب وصاح من الذي يقرعنا بأشياء كنا نعبث بها في الحداثة فهو يعيرنا بها فتركته ساعة ثم صحت به يا أبا معاذ من الذي يقول\n(أخشاب حقا أن دارك تزعج ... وأن الذي بيني وبينك ينهج)\nقال ويحك عن مثل هذا فسل ثم أنشدها حتى أتى على آخرها وهي من جيد شعره وفيه غناء صوت\n(فواكبدا قد أنضج الشوق نصفها ... ونصف على نار الصبابة ينضج)\n(وواحزنا منهن يحففن هودجا ... وفي الهودج المحفوف بدر متوج)\n(فإن جئتها بين النساء فقل لها ... عليك سلام مات من يتزوج)\n(بكيت وما في الدمع منك خليفة ... ولكن أحزاني عليك توهج)\nلغناء لسليم بن سلام رمل بالوسطى ووجدت هذا الخبر بخط ابن مهرويه فذكر أنه قال هذه القصيدة في امرأة كانت تغشى مجلسه وكان إليها مائلا يقال لها خشابة فارسية فزوجت وأخرجت عن البصرة أخبرني عمي قال حدثني الكراني قال حدثني أبو حاتم قال أبو النضير الشاعر أنشدت بشارا قصيدة لي فقال لي أيجيئك شعرك هذا كلما شئت أم هذا شيء يجيئك في الفينة بعد الفينة إذا تعملت له فقلت بل هذا شعر يجيئني كلما أردته فقال لي قل فإنك شاعر فقلت له لعلك حابيتني أبا معاذ وتحملت لي فقال أنت أبقاك الله أهون علي من ذلك","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":14,"spl":"خبره مع أبي جعفر المنصور"},
{"id":"b25-28","bab":"الجزء 3","sec":"شعره في الاعتذار عن محاولة تقبيل جارية لصديق له","page":"ج3 ص175","text":"أخبرني عمي قال حدثنا الكراني عن العمري عن عباس بن عباس الزنادي عن رجل من باهلة قال\nكنت عند بشار الأعمى فأتاه رجل فسلم عليه فسأله عن خبر جارية عنده وقال كيف ابنتي قال في عافية تدعوك اليوم فقال بشار يا باهلي انهض بنا فجئنا إلى منزل نظيف وفرش سري فأكلنا ثم جيء بالنبيذ فشربنا مع الجارية فلما أراد الانصراف قامت فأخذت بيد بشار فلما صار في الصحن أومأ إليها ليقبلها فأرسلت يدها من يده فجعل يجول في العرصة وخرج المولى فقال مالك يا أبا معاذ فقال أذنبت ذنبا ولا أبرح أو أقول شعرا فقال\n(أتوب إليك من السيئات ... وأستغفر الله من فعلتي)\n(تناولت ما لم أرد نيله ... على جهل أمري وفي سكرتي)\n(ووالله والله ما جئته ... لعمد ولا كان من همتي)\n(وإلا فمت إذا ضائعا ... وعذبني الله في ميتتي)\n(فمن نال خيرا على قبلة ... فلا بارك الله في قبلتي)\nخبرنا هاشم بن محمد الخزاعي قال حدثنا الرياشي عن الأصمعي قال لما أنشد بشار أرجوزته\n(يا طلل الحي بذات الصمد ... )\nبا الملد عقبة بن سلم أمر له بخمسين ألف درهم فأخرها عنه وكيله ثلاثة أيام فأمر غلامه بشار أن يكتب على باب عقبة عن يمين الباب\n(ما زال ما منيتني من همي ... والوعد غم فأزح من غمي)\n(إن لم ترد حمدي فراقب ذمي ... )\nفلما خرج عقبة رأى ذلك فقال هذه من فعلات بشار ثم دعا بالقهرمان فقال هل حملت إلى بشار ما أمرت له به فقال أيها الأمير نحن مضيفون وغدا أحملها إليه فقال زد فيها عشرة آلاف درهم واحملها إليه الساعة فحملها من وقته أخبرني هاشم قال حدثنا أبو غسان دماذ قال سألت أبا عبيدة عن السبب الذي من أجله نهى المهدي بشارا عن ذكر النساء قال كان أول ذلك استهتار نساء البصرة وشبانها بشعره حتى قال سوار بن عبد الله الأكبر ومالك بن دينار ما شيء أدعى لأهل هذه المدينة إلى الفسق من أشعار\nهذا الأعمى وما زالا يعظانه وكان واصل بن عطاء يقول إن من أخدع حبائل الشيطان وأغواها لكلمات هذا الأعمى الملحد فلما كثر ذلك وانتهى خبره من وجوه كثيرة إلى المهدي وأنشد المهدي ما مدحه به نهاه عن ذكر النساء وقول التشبيب وكان المهدي من أشد الناس غيرة قال فقلت له ما أحسب شعر هذا أبلغ في هذه المعاني من شعر كثير وجميل وعروة بن حزام وقيس بن ذريح وتلك الطبقة فقال ليس كل من يسمع تلك الأشعار يعرف المراد منها وبشار يقارب النساء حتى لا يخفى عليهن ما يقول وما يريد وأي حرة حصان تسمع قول بشار فلا يؤثر في قلبها فكيف بالمرأة الغزلة والفتاة التي لا هم لها إلا الرجال ثم أنشد قوله\n(قد لامني في خليلتي عمر ... واللوم في غير كنهه ضجر)\n(قال أفق قلت لا فقال بلى ... قد شاع في الناس منكما الخبر)\n(قلت وإذ شاع ما اعتذارك مما ... ليس لي فيه عندهم عذر)\n(ماذا عليهم وما لهم خرسوا ... لو أنهم في عيوبهم نظروا)\n(أعشق وحدي ويؤخذون به ... كالترك تغزو فتؤخذ الحزر)\n(يا عجبا للخلاف يا عجبا ... بفي الذي لام في الهوى الحجر)\n(حسبي وحسب الذي كلفت به ... مني ومنه الحديث والنظر)\n(أو قبلة في خلال ذاك وما ... بأس إذا لم تحل لي الأزر)\n(أو عضة في ذراعها ولها ... فوق ذراعي من عضها أثر)\n(أو لمسة دون مرطها بيدي ... والباب قد حال دونه الستر)\n(والساق براقة مخلخلها ... أو مص ريق وقد علا البهر)\n(واسترخت الكف للعراك وقالت ... إيه عني والدمع منحدر)\n(إنهض فما أنت كالذي زعموا ... أنت وربي مغازل أشر)\n(قد غابت اليوم عنك حاضنتي ... والله لي منك فيك ينتصر)\n(يا رب خذ لي فقد ترى ضرعي ... من فاسق جاء ما به سكر)\n(أهوى إلى معضدي فرضضه ... ذو قوة ما يطاق مقتدر)\n(ألصق بي لحية له خشنت ... ذات سواد كأنها الإبر)\n(حتى علاني وأسرتي غيب ... ويلي عليهم لو أنهم حضروا)\n(أقسم بالله لا نجوت بها ... فاذهب فأنت المساور الظفر)\n(كيف بأمي إذا رأت شفتي ... أم كيف إن شاع منك ذا الخبر)\n(قد كنت أخشى الذي ابتليت به ... منك فماذا أقول يا عبر)\n(قلت لها عند ذاك يا سكني ... لا بأس إني مجرب خبر)\n(قولي لها بقة لها ظفر ... إن كان في البق ما له ظفر)\nم قال له بمثل هذا الشعر تميل القلوب ويلين الصعب قال دماذ قال لي أبو عبيدة قال رجل يوما لبشار في المسجد الجامع يعابثه يا أبا معاذ أيعجبك الغلام الجادل فقال غير محتشم ولا مكتثرث لا ولكن تعجبني أمه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":15,"spl":"شعره في الاعتذار عن محاولة تقبيل جارية لصديق له","partialRef":{"sid":"b25-25","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b25-29","bab":"الجزء 3","sec":"بشار يمدح خالد بن برمك","page":"ج3 ص179","text":"أخبرني عمي قال حدثنا العنزي قال حدثني محمد بن سهل عن محمد بن الحجاج قال ورد بشار على خالد بن برمك وهو بفارس فامتدحه فوعده ومطله فوقف على طريقه وهو يريد المسجد فأخذ بلجام بغلته وأنشده\n(أظلت علينا منك يوما سحابة ... أضاءت لنا برقا وأبطا رشاشها)\n(فلا غيمها يجلي فييأس طامع ... ولا غيثها يأتي فيروي عطاشها)\nحبس بغلته وأمر له بعشرة آلاف درهم وقال لن تنصرف السحابة حتى تبلك إن شاء الله أخبرني يحيى بن علي قال حدثنا الحسن بن عليل قال حدثني علي بن حرب\nالطائي قال حدثني إسماعيل بن زياد الطائي قال كان رجل منا يقال له سعد بن القعقاع يتندم بشارا في المجانة فقال لبشار وهو ينادمه ويحك يا أبا معاذ قد نسبنا الناس إلى الزندقة فهل لك أن تحج بنا حجة تنفى ذلك عنا قال نعم ما رأيت فاشتريا بعيرا ومحملا وركبا فلما مرا بزرارة قال له ويحك يا أبا معاذ ثلاثمائة فرسخ متى نقطعها مل بنا إلى زرارة نتنعم فيها فإذا قفل الحاج عارضناهم بالقادسية وجززنا رؤوسنا فلم يشك الناس أنا جئنا من الحج فقال له بشار نعم ما رأيت لولا خبث لسانك وإني أخاف أن تفضحنا قال لا تخف فمالا إلى زرارة فما زالا يشربان الخمر ويفسقان فلما نزل الحاج بالقادسية راجعين أخذا بعيرا ومحملا وجزا رؤوسهما وأقبلا وتلقاهما الناس يهنئونهما فقال سعد بن القعقاع\n(ألم ترني وبشارا حججنا ... وكان الحج من خير التجاره)\n(خرجنا طالبي سفر بعيد ... فمال بنا الطريق إلى زراره)\n(فآب الناس قد حجوا وبروا ... وأبنا موقرين من الخساره)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":16,"spl":"بشار يمدح خالد بن برمك — رده على داود بن رزين"},
{"id":"b25-30","bab":"الجزء 3","sec":"رده على داود بن رزين","page":"ج3 ص180","text":"أخبرنا يحيى بن علي قال حدثني محمد بن القاسم الدينوري قال حدثني محمد بن عمران بن مطر الشامي قال حدثني محمد بن الحسان الضبي قال حدثني محمود الوراق قال حدثني داود بن رزيق قال أتينا بشارا فأذن لنا والمائدة موضوعة بين يديه فلم يدعنا إلى طعامه فلما\nأكل دعا بطست فكشف عن سوءته فبال ثم حضرت الظهر والعصر فلم يصل فدنونا منه فقلنا أنت أستاذنا وقد رأينا منك أشياء أنكرناها قال وما هي قلنا دخلنا والطعام بين يديك فلم تدعنا إليه فقال إنما أذنت لكم أن تأكلوا ولو لم أرد أن تأكلوا لما أذنت لكم قال ثم ماذا قلنا ودعوت بطست ونحن حضور فبلت ونحن نراك فقال أنا مكفوف وأنتم بصراء وأنتم المأمورون بغض الأبصار ثم قال ومه قلنا حضرت الظهر والعصر والمغرب فلم تصل فقال إن الذي تفاريق يقبلها جملة أخبرنا يحيى قال حدثني أبو أيوب المديني عن بعض أصحاب بشار قال كنا إذا حضرت الصلاة نقوم ويقعد بشار فنجعل حول ثيابه ترابا لننظر هل يصلي فنعود والتراب بحاله أخبرنا يحيى قال أخبرنا أبو أيوب عن الحرمازي قال قعد إلى بشار رجل فاستثقله فضرط عليه ضرطة فظن الرجل أنها أفلتت منه ثم ضرط أخرى فقال أفلتت ثم ضرط ثالثة فقال يا أبا معاذ ما هذا قال مه أرأيت أم سمعت قال بل سمعت صوتا قبيحا فقال فلا تصدق حتى ترى قال وأنشد أبو أيوب لبشار في رجل استثقله\n(ربما يثقل الجليس وإن كان ... خفيفا في كفة الميزان)\n(كيف لا تحمل الأمانة أرض ... حملت فوقها أبا سفيان)\nقال فيه أيضا\n(هل لك في مالي وعرضي معا ... وكل ما يملك جرانيه)\n(واذهب إلى أبعد ما ينتوى ... لا ردك الله ولا ماليه)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":16,"spl":"بشار يمدح خالد بن برمك — رده على داود بن رزين"},
{"id":"b25-31","bab":"الجزء 3","sec":"انشاده الوليد بن يزيد شعرا يطربه","page":"ج3 ص182","text":"أخبرني عيسى بن الحسين الوراق قال حدثني محمد بن إبراهيم الجيلي قال حدثني محمد بن عمران الضبي قال أنشدنا الوليد بن يزيد قول بشار الأعمى\n(أيها الساقيان صبا شرابي ... واسقياني من ريق بيضاء رود)\n(إن دائي الظما وإن دوائي ... شربة من رضاب ثغر برود)\n(ولها مضحك كغر الأقاحي ... وحديث كالوشي وشي البرود)\n(نزلت في السواد من حبة القلب ... ونالت زيادة المستزيد)\n(ثم قالت نلقاك بعد ليال ... والليالي يبلين كل جديد)\n(عندها الصبر عن لقائي وعندي ... زفرات يأكلن قلب الحديد)\nال فطرب الوليد وقال من لي بمزاج كاسي هذه من ريق سلمى فيروى ظمئي وتطفأ غلتي ثم بكى حتى مزج كأسه بدمعه وقال إن فاتنا ذاك فهذا أخبرني عمي وقال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد بن سليمان الطفاوي قال حدثني عبد الله بن أبي بكر وكان جليسا لبشار قال كان لنا جار يكنى أبا زيد وكان صديقا لبشار فبعث إليه يوما يطلب منه ثيابا\nبنسيئة فلم يصادفها عنده فقال يهجوه\n(ألا إن أبا زيد ... زنى في ليلة القدر)\n(ولم يرع تعالى الله ربي حرمة الشهر ... )\nكتبها في رقعة وبعث بها إليه ولم يكن أبو زيد يقول الشعر فقلبها وكتب في ظهرها\n(ألا إن أبا زيد ... له في ذلكم عذر)\n(أتته أم بشار ... وقد ضاق بها الأمر)\n(فواثبها فجامعها ... وما ساعده الصبر)\nقال فلما قرئت على بشار غضب وندم على تعرضه لرجل لا نباهة له فجعل ينطح الحائط برأسه غيظا ثم قال لا تعرضت لهجا سفلة مثل هذا أبدا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":17,"spl":"انشاده الوليد بن يزيد شعرا يطربه — شعره في جارية","partial":1},
{"id":"b25-32","bab":"الجزء 3","sec":"شعره في جارية","page":"ج3 ص183","text":"أخبرني عمي قال حدثنا أبن مهرويه قال حدثني بعض ولد أبي عبيد الله وزير المهدي قال دخل بشار على المهدي وقد عرضت عليه جارية مغنية فسمع غناءها فأطربه وقال لبشار قل في صفتها شعرا فقال\n(ورائحة للعين فيها محيلة ... إذا برقت لم تسق بطن صعيد)\n(من المستهلات السرور على الفتى ... خفا برقها في عبقر وعقود)\n(كأن لسانا ساحرا في كلامها ... أعين بصوت للقلوب صيود)\n(تميت به ألبابنا وقلوبنا ... مرارا وتحيينهن بعد همود)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":17,"spl":"انشاده الوليد بن يزيد شعرا يطربه — شعره في جارية"},
{"id":"b25-33","bab":"الجزء 3","sec":"شعره في عقبة بن سلم","page":"ج3 ص184","text":"أخبرني عمي قال حدثنا أبو أيوب المديني قال قال أبو عدنان حدثني يحيى ابن الجون قال دخل بشار يوما على عقبة بن سلم فأنشده قوله فيه صوت\n(إنما لذة الجواد ابن سلم ... في عطاء ومركب للقاء)\n(ليس يعطيك للرجاء ولا الخوف ... ولكن يلذ طعم العطاء)\n(يسقط الطير حيث ينتثر الحب ... وتغشى منازل الكرماء)\n(لا أبالي صفح اللئيم ولا تجري ... دموعي على الحرون الصفاء)\n(فعلى عقبة السلام مقيما ... وإذا سار تحت ظل اللواء)\nوصله بعشرة آلاف درهم وفي هذه الأبيات خفيف رمل مطلق في مجرى البنصر لرذاذ وهو مختار صنعته وصدورها ومما تشبه فيه بالقدماء ومذاهبهم أخبرني أحمد بن العباس العسكري قال حدثنا الحسن بن عليل العنزي قال حدثنا أحمد بن خلاد عن الأصمعي وأخبرني به الحسن بن علي قال حدثنا\nمحمد بن القاسم بن مهرويه قال حدثني أحمد بن خلاد عن الأصمعي قال كنت أشهد خلف بن أبي عمرو بن العلاء وخلفا الأحمر يأتيان بشارا ويسلمان عليه بغاية التعظيم ثم يقولان يا أبا معاذ ما أحدثت فيخبرهما وينشدهما ويسألانه ويكتبان عنه متواضعين له حتى يأتي وقت الظهر ثم ينصرفان عنه فأتياه يوما فقالا له ما هذه القصيدة التي أحدثتها في سلم بن قتيبة قال هي التي بلغتكما قالا بلغنا أنك أكثرت فيها من الغريب فقال نعم بلغني أن سلما يتباصر بالغريب فأحببت أن أورد عليه ما لا يعرفه قالا فأنشدناها فأنشدهما\n(بكرا صاحبي قبل الهجير ... إن ذاك النجاح في التبكير)\nتى فرغ منها فقال له خلف لو قلت يا أبا معاذ مكان إن ذاك النجاح\n(بكرا فالنجاح في التبكير ... )\nان أحسن فقال بشار بنيتها أعرابية وحشية فقلت إن ذاك النجاح كما يقول الأعراب البدويون ولو قلت بكرا فالنجاح كان هذا من كلام المولدين ولا يشبه ذلك الكلام ولا يدخل في معنى القصيدة فقام خلف فقبل بين عينيه\nوقال له خلف بن أبي عمرو يمازحه لو كان علاثة ولدك يا أبا معاذ لفعلت كما فعل أخي ولكنك مولى فمد بشار يده فضرب بها فخذ خلف وقال\n(أرفق بعمرو إذا حركت نسبته ... فإنه عربي من قوارير)\nفقال له أفعلتها يا أبا معاذ قال وكان أبو عمرو يغمز في نسبه وأخبرني ببعض هذا الخبر حبيب بن نصر عن عمر بن شبة عن أبي عبيدة فذكر نحوه وقال فيه إن سلما يعجبه الغريب أخبرني هاشم بن محمد بن سلام قال قال لي خلف كنت أسمع ببشار قبل أن أراه فذكروه لي يوما وذكروا بيانه وسرعة جوابه وجودة شعره فاستنشدتهم شيئا من شعره فأنشدوني شيئا لم يكن بالمحمود عندي فقلت والله لآتينه ولأطأطئن منه فأتيته وهو جالس على بابه فرأيته أعمى قبيح المنظر عظيم الجثة فقلت لعن الله من يبالي بهذا فوقفت أتأمله طويلا فبينما أنا كذلك إذ جاءه رجل فقال إن فلانا سبك عند الأمير محمد بن سليمان ووضع منك فقال أو قد فعل قال نعم فأطرق وجلس الرجل عنده وجلست وجاء قوم فسلموا عليه فلم يردد عليهم فجعلوا ينظرون إليه وقد درت أوداجه فلم يلبث إلا ساعة حتى أنشدنا بأعلى صوته وأفخمه\n(نبئت نائك أمه يغتابني ... عند الأمير وهل علي أمير)\n(ناري محرقة وبيتي واسع ... للمعتفين ومجلسي معمور)\n(ولي المهابة في الأحبة والعدا ... وكأنني أسد له تامور)\n(غرثت حليلته وأخطأ صيده ... فله على لقم الطريق زئير)\nال فارتعدت والله فرائصي واقشعر جلدي وعظم في عيني جدا حتى قلت في نفسي الحمد لله الذي أبعدني من شرك","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":18,"spl":"شعره في عقبة بن سلم","partial":1},
{"id":"b25-34","bab":"الجزء 3","sec":"مدحه خالد بن برمك","page":"ج3 ص187","text":"نسخت من كتاب هارون بن علي بن يحيى قال حدثني علي بن مهدي قال حدثنا العباس بن خالد قال مدح بشار خالد بن برمك فقال فيه\n(لعمري لقد أجدى علي ابن برمك ... وما كل من كان الغنى عنده يجدي)\n(حلبت بشعري راحتيه فدرتا ... سماحا كما در السحاب مع الرعد)\n(إذا جئته للحمد أشرق وجهه ... إليك وأعطاك الكرامة بالحمد)\n(له نعم في القوم لا يستثيبها ... جزاء وكيل التاجر المد بالمد)\n(مفيد ومتلاف سبيل تراثه ... إذا ما غدا أرواح كالجزر والمد)\n(أخالد إن الحمد يبقى لأهله ... جمالا ولا تبقى الكنوز على الكد)\n(فأطعم وكل من عارة مستردة ... ولا تبقها إن العواري للرد)\nأعطاه خالد ثلاثين ألف درهم وكان قبل ذلك يعطيه في كل وفادة خمسة آلاف درهم وأمر خالد أن يكتب هذان البيتان في صدر مجلسه الذي كان يجلس فيه وقال ابنه يحيى بن خالد آخر ما أوصاني به أبي العمل بهذين البيتين أخبرني عمي قال حدثنا عبد الله بن عمر بن أبي سعد قال حدثني محمد بن عبد الله بن عثمان قال كان الوزير مولى عبد القيس من عمال الخراج وكان عفيفا بخيلا فسأل عمر بن العلاء وكان جوادا شجاعا في رجل فوهب له مائة ألف درهم فدخل أبو الوزير على المهدي فقال له يا أمير المؤمنين إن عمر بن العلاء خائن قال ومن أين علمت ذلك قال كلم في رجل كان أقصى أمله ألف درهم فوهب له مائة ألف درهم فضحك المهدي ثم قال قل كل يعمل على شاكلته أما سمعت قول بشار في عمر\n(إذا دهمتك عظام الأمور ... فنبه لها عمرا ثم نم)\n(فتى لا ينام على دمنة ... ولا يشرب الماء إلا بدم)\nو ما سمعت قول أبي العتاهية فيه صوت\n(إن المطايا تشتكيك لأنها ... قطعت إليك سباسيا ورمالا)\n(فإذا وردن بنا وردن مخفة ... وإذا رجعن بنا رجعن ثقالا)\nالغناء لإبراهيم ثاني ثقيل بالوسطى عن عمرو بن بانة أو ليس الذي يقول فيه أبو العتاهية\n(يابن العلاء ويابن القرم مرداس ... إني لأطريك في صحبي وجلاسي)\n(حتى إذا قيل ما أعطاك من نشب ... ألفيت من عظم ما أسديت كالناسي)\nم قال من اجتمعت ألسن الناس على مدحه كان حقيقا أن يصدقها بفعله","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":19,"spl":"مدحه خالد بن برمك — وصفه لجارية سوداء"},
{"id":"b25-35","bab":"الجزء 3","sec":"وصفه لجارية سوداء","page":"ج3 ص189","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أبو بكر الربعي قال كانت لبشار جارية سوداء وكان يقع عليها وفيها يقول\n(وغادة سوداء براقة ... كالماء في طيب وفي لين)\n(كأنها صيغت لمن نالها ... من عنبر بالمسك معجون)\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أبو الشبل البرجمي قال قال رجل لبشار إن مدائحك عقبة بن سلم فوق مدائحك كل أحد فقال بشار إن عطاياه إياي كانت فوق عطاء كل أحد دخلت إليه يوما فأنشدته\n(حرم الله أن ترى كابن سلم ... عقبة الخير مطعم الفقراء)\n(ليس يعطيك للرجاء ولا الخوف ... ولكن يلذ طعم العطاء)\n(يسقط الطير حيث ينتثر الحب ... وتغشى منازل الكرماء)\nأمر لي بثلاثة آلاف دينار وهأنا قد مدحت المهدي وأبا عبيد الله ووزيره أو قال يعقوب بن داود وأقمت بأبوابهما حولا فلم يعطياني شيئا أفألام على مدحي هذا\nونسخت من كتاب هارون بن علي أيضا حدثني علي قال حدثني عبيد الله بن أبي الشيص عن دعبل بن علي قال كان بشار يعطي أبا الشمقمق في كل سنة مائتي درهم فأتاه أبو الشمقمق في بعض تلك السنين فقال له هلم الجزية يا أبا معاذ فقال ويحك أجزية هي قال هو ما تسمع فقال له بشار يمازحه أنت أفصح مني قال لا قال فأعلم مني بمثالب الناس قال لا قال فأشعر مني قال لا قال فلم أعطيك قال لئلا أهجوك فقال له إن هجوتني هجوتك فقال له أبو الشمقمق هكذا هو قال نعم فقل ما بدا لك فقال أبو الشمقمق\n(إني إذا ما شاعر هجانيه ... ولج في القول له لسانيه)\n(أدخلته في است أمه علانيه ... بشار يا بشار . . . . . .)\nأراد أن يقول يابن الزانيه فوثب بشار فأمسك فاه وقال أراد والله أن يشتمني ثم دفع إليه مائتي درهم ثم قال له لا يسمعن هذا منك الصبيان يا أبا الشمقمق أخبرني أحمد بن العباس العسكري قال حدثني الحسن بن عليل العنزي قال حدثني محمد بن بكر قال حدثني الأصمعي قال أمر عقبة بن سلم الهنائي لبشار بعشرة آلاف درهم فأخبر أبو الشمقمق بذلك فوافى بشار فقال له يا أبا معاذ إني مررت بصبيان فسمعتهم ينشدون\n(هللينه هللينه ... طعن قثاة لتينه)\n(إن بشار بن برد ... تيس اعمى في سفينه)\nفأخرج إليه بشار مائتي درهم فقال خذ هذه ولا تكن راوية الصبيان يا أبا الشمقمق","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":19,"spl":"مدحه خالد بن برمك — وصفه لجارية سوداء"},
{"id":"b25-36","bab":"الجزء 3","sec":"هجاؤه للعباس بن محمد بن علي","page":"ج3 ص191","text":"أخبرني أحمد قال حدثنا أبو محمد الصعتري قال حدثنا محمد بن عثمان البصري قال استمنح بشار بن برد العباس بن محمد بن علي بن عبد الله بن عباس فلم يمنحه فقال يهجوه\n(ظل اليسار على العباس ممدود ... وقلبه أبدا في البخل معقود)\n(إن الكريم ليخفي عنك عسرته ... حتى تراه غنيا وهو مجهود)\n(وللبخيل على أمواله علل ... زرق العيون عليها أوجه سود)\n(إذا تكرهت أن تعطي القليل ولم ... تقدر على سعة لم يظهر الجود)\n(أورق بخير ترجى للنوال فما ... ترجى الثمار إذا لم يورق العود)\n(بث النوال ولا تمنعك قلته ... فكل ما سد فقرا فهو محمود)\nخبرني أحمد قال حدثنا العنزي قال حدثني المغيرة بن محمد المهلبي قال حدثني أبي عن عباد بن عباد قال مررت ببشار فقلت السلام عليك يا أبا معاذ فقال وعليك السلام أعباد فقلت نعم قال إني لحسن الرأي فيك فقلت ما أحوجني إلى ذلك\nمنك يا أبا معاذ أخبرني يحيى بن علي قال أخبرني محمد بن عمر الجرجاني عن أبي يعقوب الخريمي الشاعر أن بشارا قال لم أزل منذ سمعت قول امرئ القيس في تشبيهه شيئين بشيئين في بيت واحد حيث يقول\n(كأن قلوب الطير رطبا ويابسا ... لدى وكرها العناب والحشف البالي)\nأعمل نفسي في تشبيه شيئين بشيئين في بيت حتى قلت\n(كأن مثار النقع فوق رؤوسنا ... وأسيافنا ليل تهاوى كواكبه)\nال يحيى وقد أخذ هذا المعنى منصور النمري فقال وأحسن\n(ليل من النقع لا شمس ولا قمر ... إلا جبينك والمذروبة الشرع)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":20,"spl":"هجاؤه للعباس بن محمد بن علي"},
{"id":"b25-37","bab":"الجزء 3","sec":"طعن إسحاق الموصلي في شعره","page":"ج3 ص192","text":"أخبرني يحيى بن علي قال حدثني أبي قال كان إسحاق الموصلي يطعن على شعر بشار ويضع منه ويذكر أن كلامه مختلف لا يشبه بعضه بعضا فقلنا أتقول هذا القول لمن يقول\nصوت\n(إذا كنت في كل الأمور معاتبا ... صديقك لم تلق الذي لا تعاتبه)\n(فعش واحدا أو صل أخاك فإنه ... مقارف ذنب مرة ومجانبه)\n(إذا أنت لم تشرب مرارا على القذى ... ظمئت وأي الناس تصفو مشاربه)\nأبي العبيس بن حمدون في هذه الأبيات خفيف ثقيل بالبنصر قال علي بن يحيى وهذا الكلام الذي ليس فوقه كلام من الشعر ولا حشو فيه فقال لي إسحاق أخبرني أبو عبيدة معمر بن المثنى أن شبيل بن عزرة الضبعي أنشده هذه الأبيات للمتلمس وكان عالما بشعره لأنهما جميعا من بني ضبيعة فقلت له أفليس قد ذكر أبو عبيدة أنه قال لبشار أن شبيلا أخبره للمتلمس فقال كذب والله شبيل هذا شعري ولقد مدحت به ابن هبيرة فأعطاني عليه أربعين ألفا وقد صدق بشار وقد مدح في هذه القصيدة ابن هبيرة وقال فيها\n(رويد تصاهل بالعراق جيادنا ... كأنك بالضحاك قد قام نادبه)\n(وسام لمروان ومن دونه الشجا ... وهول كلج البحر جاشت غواربه)\n(أحلت به أم المنايا بناتها ... بأسيافنا إنا ردى من نحاربه)\n(وكنا إذا دب العدو لسخطنا ... وراقبنا في ظاهر لا نراقبه)\n(ركبنا له جهرا بكل مثقف ... وأبيض تستسقي الدماء مضاربه)\nم قلت لإسحاق أخبرني عن قول بشار في هذه القصيدة\n(فلما تولى الحر واعتصر الثرى ... لظى الصيف من نجم توقد لاهبه)\n(وطارت عصافير الشقائق واكتسى ... من الآل أمثال المجرة ناضبه)\n(غدت عانة تشكو بأبصارها الصدى ... إلى الجأب إلا أنها لا تخاطبه)\nلعانة القطيع من الحمير والجأب ذكرها ومعنى شكواها الصدى بأبصارها أن العطش قد تبين في أحداقها فغارت قال وهذا من أحسن ما وصف به الحمار والأتن أفهذا للمتلمس أيضا قال لا فقلت أفما هو في غاية الجودة وشبيه بسائر الشعر فكيف قصد بشار لسرقة تلك الأبيات خاصة وكيف خصه بالسرقة منه وحده من بين الشعراء وهو قبله بعصر طويل وقد روى الرواة شعره وعلم بشار أن ذلك لا يخفى ولم يعثر على بشار أنه سرق شعرا قط جاهليا ولا إسلاميا وأخرى فإن شعر المتلمس يعرف في بعض شعر بشار فلم يردد ذلك بشيء وقد أخبرني بهذا الخبر هاشم بن محمد الخزاعي قال حدثنا أبو غسان معاذ عن أبي عبيدة أن بشارا أنشده\n(إذا كنت في كل الأمور معاتبا ... صديقك لم تلق الذي لا تعاتبه)\nوذكر الأبيات قال وأنشدتها شبيل بن عزرة الضبعي فقال هذا للمتلمس فأخبرت بذلك بشارا قال كذب والله شبيل لقد مدحت ابن هبيرة بهذه القصيدة وأعطاني عليها أربعين ألفا أخبرنا يحيى بن علي قال حدثنا علي بن مهدي قال حدثنا علي بن إبراهيم المروزي وكان أبوه من قواد طاهر قال حدثني أبي قال لما خلع محمد المأمون وندب له علي بن عيسى ندب المأمون للقاء علي بن عيسى طاهر بن الحسين ذا اليمينين وجلس له لعرضه وعرض أصحابه فمر به ذو اليمينين معترضا وهو ينشد\n(رويد تصاهل بالعراق جيادنا ... كأنك بالضحاك قد قام نادبه)\nتفاءل المأمون بذلك فاستدناه فاستعاده البيت فأعاد عليه فقال ذو الرياستين يا أمير المؤمنين هو حجر العراق قال أجل فلما صار ذو اليمينين إلى العراق سأل هل بقي من ولد بشار أحد فقالوا لا فتوهمت أنه قد كان هم لهم بخير","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":21,"spl":"طعن إسحاق الموصلي في شعره"},
{"id":"b25-38","bab":"الجزء 3","sec":"سرقة سلم الخاسر من معانيه","page":"ج3 ص195","text":"أخبرنا يحيى قال حدثنا أبي قال أخبرني أحمد بن صالح وكان أحد الأدباء قال غضب بشار على سلم الخاسر وكان من تلامذته ورواته فاستشفع عليه بجماعة من إخوانه فجاءوه في أمره فقال لهم كل حاجة لكم مقضية إلا سلما\nقالوا ما جئناك إلا في سلم ولا بد من أن ترضى عنه لنا فقال أين هو الخبيث قالوا ها هو هذا فقام إليه سلم فقبل رأسه ومثل بين يديه وقال يا أبا معاذ خريجك وأديبك فقال يا سلم من الذي يقول\n(من راقب الناس لم يظفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\nال أنت يا أبا معاذ جعلني الله فداءك قال فمن الذي يقول\n(من راقب الناس مات غما ... وفاز باللذة الجسور)\nال خريجك يقول ذلك يعني نفسه قال أفتأخذ معاني التي قد عنيت بها وتعبت في استنباطها فتكسوها ألفاظا أخف من ألفاظي حتى يروى ما تقول ويذهب شعري لا أرضى عنك أبدا قال فما زال يتضرع إليه ويشفع له القوم حتى رضي عنه وفي هذه القصيدة يقول بشار\n(لو كنت تلقين ما نلقى قسمت لنا ... يوما نعيش به منكم ونبتهج)\nصوت\n(لا خير في العيش إن كنا كذا أبدا ... لا نلتقي وسبيل الملتقى نهج)\n(قالوا حرام تلاقينا فقلت لهم ... ما في التلاقي ولا في قبلة حرج)\n(من راقب الناس لم يظفر بحاجته ... وفاز بالطيبات الفاتك اللهج)\n(أشكو إلى الله هما ما يفارقني ... وشرعا في فؤادي الدهر تعتلج)\nخبرنا محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال\nحدثنا أحمد بن خلاد قال أنشدت الأصمعي قول بشار يهجو باهلة\n(ودعاني معشر كلهم ... حمق دام لهم ذاك الحمق)\n(ليس من جرم ولكن غاظهم ... شرفي العارض قد سد الأفق)\nفاغتاظ الأصمعي فقال ويلي على هذا العبد القن ابن القن نسخت من كتاب هارون بن علي بن يحيى قال حدثني علي بن مهدي قال حدثني عباس بن خالد قال سمعت غير واحد من أهل البصرة يحدث أن امرأة قالت لبشار أي رجل أنت لو كنت أسود اللحية والرأس قال بشار أما علمت أن بيض البزاة أثمن من سود الغربان فقالت له أما قولك فحسن في السمع ومن لك بأن يحسن شيبك في العين كما حسن قولك في السمع فكان بشار يقول ما أفحمني قط غير هذه المرأة ونسخت من كتابه حدثني علي بن مهدي قال حدثني إسحاق بن كلبة قال قال لي أبو عثمان المازني سئل بشار أي متاع الدنيا آثر عندك فقال طعام مز وشراب مر وبنت عشرين بكر","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":22,"spl":"سرقة سلم الخاسر من معانيه — خالد البرمكي يجيزه على مدحه"},
{"id":"b25-39","bab":"الجزء 3","sec":"قوله بعد امتناع امرأة عنه","page":"ج3 ص197","text":"أخبرني عمي قال حدثني عبد الله بن أبي سعد وأخبرنا الحسن بن علي قال حدثني أحمد بن أبي طاهر قال حدثني عبد الله بن أبي سعد قال حدثني أبو توبة عن صالح بن عطية قال\nكان النساء المتظرفات يدخلن إلى بشار في كل جمعة يومين فيجتمعن عنده ويسمعن من شعره فسمع كلام امرأة منهن فعلقها قلبه وراسلها يسألها أن تواصله فقالت لرسوله وأي معنى فيك لي أو لك في وأنت أعمى لا تراني فتعرف حسني ومقداره وأنت قبيح الوجه فلا حظ لي فيك فليت شعري لأي شيء تطلب وصال مثلي وجعلت تهزأ به في المخاطبة فأدى الرسول الرسالة فقال له عد إليها فقل لها\n(أيري له فضل على آيارهم ... وإذا أشظ سجدن غير أوابي)\n(تلقاه بعد ثلاث عشرة قائما ... فعل المؤذن شك يوم سحاب)\n(وكأن هامة رأسه بطيخة ... حملت إلى ملك بدجلة جابي)\nخبرني علي بن صالح بن الهيثم قال حدثنا أبو هفان قال أخبرني أحمد بن عبد الأعلى الشيباني عن أبيه قال قال مروان لبشار لما أنشده هذا البيت\n(وإذا قلت لها جودي لنا ... خرجت بالصمت من لا ونعم)\nعلني الله فداءك يا أبا معاذ هلا قلت خرست بالصمت قال إذا أنا في عقلك فض الله فاك أأتطير على من أحب بالخرس","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":22,"spl":"سرقة سلم الخاسر من معانيه — خالد البرمكي يجيزه على مدحه"},
{"id":"b25-40","bab":"الجزء 3","sec":"خالد البرمكي يجيزه على مدحه","page":"ج3 ص198","text":"نسخت من كتاب هارون بن علي بن يحيى حدثني بعض أصحابنا قال\nوفد بشار إلى خالد بن برمك وهو على فارس فأنشده\n(أخالد لم أخبط إليك بذمة ... سوى أنني عاف وأنت جواد)\n(أخالد بين الأجر والحمد حاجتي ... فأيهما تأتي فأنت عماد)\n(فإن تعطني أفرغ عليك مدائحي ... وإن تأب لم يضرب علي سداد)\n(ركابي على حرف وقلبي مشيع ... ومالي بأرض الباخلين بلاد)\n(إذا أنكرتني بلدة أو نكرتها ... خرجت مع البازي علي سواد)\nال فدعا خالد بأربعة آلاف دينار في أربعة أكياس فوضع واحدا عن يمينه وواحدا عن شماله وآخر بين يديه وآخر خلفه وقال يا أبا معاذ هل استقل العماد فلمس الأكياس ثم قال استقل والله أيها الأمير","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":22,"spl":"سرقة سلم الخاسر من معانيه — خالد البرمكي يجيزه على مدحه"},
{"id":"b25-41","bab":"الجزء 3","sec":"الهيثم بن معاوية يجيزه على مدحه","page":"ج3 ص199","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال قال محمد بن الحجاج حدثني بشار قال دخلت على الهيثم بن معاوية وهو أمير بالبصرة فأنشدته\n(إن السلام أيها الأمير ... عليك والرحمة والسرور)\nسمعته يقول إن هذا الأعمى لا يدعنا أو يأخذ من دراهمنا شيئا فطمعت فيه فما برحت حتى انصرفت بجائزته أخبرني هاشم بن محمد قال حدثنا عيسى بن إسماعيل عن محمد بن سلام قال وقف رجل من بني زيد شريف لا أحب أن أسميه على بشار فقال له يا بشار قد أفسدت علينا موالينا تدعوهم إلى الانتفاء منا وترغبهم في الرجوع إلى أصولهم وترك الولاء وأنت غير زاكي الفرع ولا معروف الأصل فقال له بشار والله لأصلي أكرم من الذهب ولفرعي أزكى من عمل الأبرار وما في الأرض كلب يود أن نسبك له بنسبه ولو شئت أن أجعل جواب كلامك كلاما لفعلت ولكن موعدك غدا بالمربد فرجع الرجل إلى منزله وهو يتوهم أن بشارا يحضر معه المربد ليفاخره فخرج من الغد يريد المربد فإذا رجل ينشد\n(شهدت على الزيدي أن نساءه ... ضياع إلى أير العقيلي تزفر)\nسأل عمن قال هذا البيت فقيل له هذا لبشار فيك فرجع إلى منزله من فوره ولم يدخل المربد حتى مات قال ابن سلام وأنشد رجل يوما يونس في هذه القصيدة وهي\n(بلوت بني زيد فما في كبارهم ... حلوم ولا في الأصغرين مطهر)\n(فأبلغ بني زيد وقل لسراتهم ... وإن لم يكن فيهم سراة توقر)\n(لأمكم الويلات إن قصائدي ... صواعق منها منجد ومغور)\n(أجدهم لا يتقون دنية ... ولا يؤثرون الخير والخير يؤثر)\n(يلفون أولاد الزنا في عدادهم ... فعدتهم من عدة الناس أكثر)\n(إذا ما رأوا من دأبه مثل دأبهم ... أطافوا به والغي للغي أصور)\n(ولو فارقوا من فيهم من دعارة ... لما عرفتهم أمهم حين تنظر)\n(لقد فخروا بالملحقين عشية ... فقلت افخروا إن كان في اللؤم مفخر)\n(يريدون مسعاتي ودون لقائها ... قناديل أبواب السموات تزهر)\n(فقل في بني زيد كما قال معرب ... قوارير حجام غدا تتكسر)\nقال يونس للذي أنشده حسبك حسبك من هيج هذا الشيطان عليهم قيل فلان فقال رب سفيه قوم قد كسب لقومه شرا عظيما أخبرني عمي قال حدثنا ابن مهرويه قال حدثني عبد الله بن بشر بن هلال قال حدثني محمد بن محمد البصري قال حدثني النضر بن طاهر أبو الحجاج قال قال بشار دعاني عقبة بن سلم ودعا بحماد عجرد وأعشى باهلة فلما\nاجتمعنا عنده قال لنا إنه خطر ببالي البارحة مثل يتمثله الناس ذهب الحمار يطلب قرنين فجاء بلا أذنين فأخرجوه من الشعر ومن أخرجه فله خمسة آلاف درهم وإن لم تفعلوا جلدتكم كلكم خمسمائة فقال حماد أجلنا أعز الله الأمير شهرا وقال الأعشى أجلنا أسبوعين قال وبشار ساكت لا يتكلم فقال له عقبة مالك يا أعمى لا تتكلم أعمى الله قلبك فقال أصلح الله الأمير قد حضرني شيء فإن أمرت قلته فقال قل فقال\n(شط بسلمى عاجل البين ... وجاورت أسد بني القين)\n(ورنت النفس لها رنة ... كادت لها تنشق نصفين)\n(يابنة من لا أشتهي ذكره ... أخشى عليه علق الشين)\n(والله لو ألقاك لا أتقي ... عينا لقبلتك ألفين)\n(طالبتها ديني فراغت به ... وعلقت قلبي مع الدين)\n(فصرت كالعير غدا طالبا ... قرنا فلم يرجع بأذنين)\nال فانصرف بشار بالجائزة","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":23,"spl":"الهيثم بن معاوية يجيزه على مدحه"},
{"id":"b25-42","bab":"الجزء 3","sec":"خبره مع قوم من قيس عبلان","page":"ج3 ص202","text":"نسخت من كتاب هارون بن علي بن يحيى حدثنا علي بن مهدي قال حدثني عبد الله بن عطية الكوفي قال حدثني عثمان بن عمرو الثقفي قال قال أبان بن عبد الحميد اللاحقي نزل في ظاهر البصرة قوم من أعراب قيس عيلان وكان فيهم بيان وفصاحة فكان بشار يأتيهم وينشدهم أشعاره التي يمدح بها قيسا فيجلونه لذلك ويعظمونه وكان نساؤهم يجلسن معه ويتحدثن إليه وينشدهن أشعاره في الغزل وكن يعجبن\nبه وكنت كثيرا ما آتي ذلك الموضع فاسمع منه ومنهم فأتيتهم يوما فإذا هم قد ارتحلوا فجئت إلى بشار فقلت له يا أبا معاذ أعلمت أن القوم قد ارتحلوا قال لا فقلت فاعلم قال قد علمت لا علمت ومضيت فلما كان بعد ذلك بأيام سمعت الناس ينشدون\n(دعا بفراق من تهوى أبان ... ففاض الدمع واحترق الجنان)\n(كأن شرارة وقعت بقلبي ... لها في مقلتي ودمي استنان)\n(إذا أنشدت أو نسمت عليها ... رياح الصيف هاج لها دخان)\nعلمت أنها لبشار فأتيته فقلت يا أبا معاذ ما ذنبي إليك قال ذنب غراب البين فقلت هل ذكرتني بغير هذا قال لا فقلت أنشدك الله ألا تزيد فقال امض لشأنك فقد تركتك ونسخت من كتابه حدثني علي بن مهدي قال حدثني يحيى بن سعيد الأيوزرذي المعتزلي قال حدثني أحمد بن المعذل عن أبيه قال أنشد بشار جعفر بن سليمان\n(أقلي فإنا لاحقون وإنما ... يؤخرنا أنا يعد لنا عدا)\n(وما كنت إلا كالأغر ابن جعفر ... رأى المال لا يبقى فأبقى به حمدا)\nقال له جعفر بن سليمان من ابن جعفر قال الطيار في الجنة فقال لقد ساميت غير مسامي فقال والله ما يقعدني عن شأوه بعد النسب لكن قلة النشب وإني لأجود بالقليل وإن لم يكن عندي الكثير وما على من جاد بما\nيملك ألا يهب البدور فقال له جعفر لقد هززت أبا معاذ ثم دعا له بكيس فدفعه إليه ونسخت من كتابه حدثني علي بن مهدي قال حدثني أحمد بن سعيد الرازي عن سليمان بن سليمان العلوي قال قيل لبشار إنك لكثير الهجاء فقال إني وجدت الهجاء المؤلم آخذ بضبع الشاعر من المديح الرائع ومن أراد من الشعراء أن يكرم في دهر اللئام على المديح فليستعد للفقر وإلا فليبالغ في الهجاء ليخاف فيعطى","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":24,"spl":"خبره مع قوم من قيس عبلان — بعض من سيرة حياته في صباه"},
{"id":"b25-43","bab":"الجزء 3","sec":"بعض من سيرة حياته في صباه","page":"ج3 ص204","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان برد أبو بشار طيانا حاذقا بالتطيين وولد له بشار وهو أعمى فكان يقول ما رأيت مولودا أعظم بركة منه ولقد ولد وما عندي درهم فما حال الحول حتى جمعت مائتي درهم ولم يمت برد حتى قال بشار الشعر وكان لبشار أخوان يقال لأحدهما بشر وللآخر بشير وكانا قصابين وكان بشار بارا بهما على أنه كان ضيق الصدر متبرما بالناس فكان يقول اللهم إني قد تبرمت بنفسي وبالناس جمعيا اللهم فأرحني منهم وكان إخوته يستعيرون ثيابه فيوسخونها وينتنون ريحها فاتخذ قميصا له جيبان وحلف ألا يعيرهم ثوبا من ثيابه فكانوا يأخذونها بغير إذنه فإذا دعا بثوبه فلبسه فأنكر رائحته فيقول إذا وجد رائحة كريهة من ثوبه أينما أتوجه ألق سعدا فإذا أعياه الأمر خرج إلى الناس في تلك الثياب على\nنتنها ووسخها فيقال له ما هذا يا أبا معاذ فيقول هذه ثمرة صلة الرحم قال وكان يقول الشعر وهو صغير فإذا هجا قوما جاءوا إلى أبيه فشكوه فيضربه ضربا شديدا فكانت أمه تقول كم تضرب هذا الصبي الضرير أما ترحمه فيقول بلى والله إني لأرحمه ولكنه يتعرض للناس فيشكونه إلي فسمعه بشار فطمع فيه فقال له يا أبت إن هذا الذي يشكونه مني إليك هو قول الشعر وإني إن ألممت عليه أغنيتك وسائر أهلي فإن شكوني إليك فقل لهم أليس الله يقول ( ليس على الأعمى حرج\nلما عاودوه شكواه قال لهم برد ما قاله بشار فانصرفوا وهم يقولون فقه برد أغيظ لنا من شعر بشار أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني محمد بن عثمان الكريزي قال حدثني بعض الشعراء قال أتيت بشارا الأعمى وبين يديه مائتا دينار فقال لي خذ منها ما شئت أو تدري ما سببها قلت لا قال جاءني فتى فقال لي أنت بشار فقلت نعم فقال إني آليت أن أدفع إليك مائتي دينار وذلك أني عشقت امرأة فجئت إليها فكلمتها فلم تلتفت إلي فهممت أن أتركها فذكرت قولك\n(لا يويسنك من مخبأة ... قول تغلظه وإن جرحا)\n(عسر النساء إلى مياسرة ... والصعب يمكن بعد ما جمحا)\nعدت إليها فلازمتها حتى بلغت منها حاجتي","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":24,"spl":"خبره مع قوم من قيس عبلان — بعض من سيرة حياته في صباه"},
{"id":"b25-44","bab":"الجزء 3","sec":"هابه الأخفش فاستشهد بشعره","page":"ج3 ص206","text":"أخبرني عمي قال حدثني الكراني عن أبي حاتم قال كان الأخفش طعن على بشار في قوله\n(فالآن أقصر عن سمية باطلي ... وأشار بالوجلى علي مشير)\nفي قوله\n(على الغزلى مني السلام فربما ... لهوت بها في ظل مرؤومة زهر)\nفي قوله في صفة سفينة\n(تلاعب نينان البحور وربما ... رأيت نفوس القوم من جريها تجري)\nوقال لم يسمع من الوجل والغزل فعلى ولم أسمع بنون ونينان فبلغ ذلك بشارا فقال ويلي على القصارين متى كانت الفصاحة في بيوت القصارين دعوني وإياه فبلغ ذلك الأخفش فبكى وجزع فقيل له ما يبكيك فقال وما لي لا أبكي وقد وقعت في لسان بشار الأعمى فذهب أصحابه إلى بشار فكذبوا عنه واستوهبوا منه عرضه وسألوه ألا يهجوه فقال قد وهبته للؤم عرضه فكان الأخفش بعد ذلك يحتج بشعره في كتبه ليبلغه فكف عن ذكره بعد هذا قال وقال غير أبي حاتم إنما بلغه أن سيبويه عاب هذه الأحرف عليه لا الأخفش فقال يهجوه\n(أسبويه يابن الفارسية ما الذي ... تحدثت عن شتمي وما كنت تنبذ)\n(أظلت تغني سادرا في مساءتي ... وأمك بالمصرين تعطي وتأخذ)\nال فتوقاه سيبويه بعد ذلك وكان إذا سئل عن شيء فأجاب عنه ووجد له شاهدا من شعر بشار احتج به استكفافا لشره","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":25,"spl":"هابه الأخفش فاستشهد بشعره — دفاعه عن أبي النضير"},
{"id":"b25-45","bab":"الجزء 3","sec":"أهله يستعينون به لهجاء بني سدوس","page":"ج3 ص207","text":"أخبرني محمد بن عمران الصيرفي قال حدثني الحسن بن عليل العنزي قال حدثني أحمد بن علي بن سويد بن منجوف قال كان بشار مجاورا لبني عقيل وبني سدوس في منزل الحيين فكانوا لا يزالون يتفاخرون فاستعانت عقيل ببشار وقالوا له يا أبا معاذ نحن أهلك وأنت ابننا وربيت في حجورنا فأعنا فخرج عليهم وهم يتفاخرون فجلس ثم أنشد\n(كأن بني سدوس رهط ثور ... خنافس تحت منكسر الجدار)\n(تحرك للفخار زبانييها ... وفخر الخنفساء من الصغار)\nوثب بنو سدوس إليه فقالوا ما لنا ولك يا هذا نعوذ بالله من شرك فقال هذا دأبكم إن عاودتم مفاخرة بني عقيل فلم يعاودوها أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني محمد بن إسماعيل عن محمد بن سلام قال قال يونس النحوي العجب من الأزد\nيدعون هذا العبد ينسب بنسائهم ويهجو رجالهم يعني بشارا ويقول\n(ألا يا صنم الأزد ... الذي يدعونه ربا)\nلا يبعثون إليه من يفتق بطنه أخبرني الحسن قال حدثني ابن مهرويه عن أحمد بن إسماعيل عن محمد بن سلام قال مر ابن أخ لبشار ببشار ومعه قوم فقال لرجل معه وسمع كلامه من هذا فقال ابن أخيك قال أشهد أن أصحابه سفلة قال وكيف علمت قال ليس عليهم نعال أخبرني الحسن قال حدثنا محمد بن القاسم قال حدثني الفضل بن يعقوب قال كنا عند جارية لبعض التجار بالكرخ تغنينا وبشار عندنا فغنت في قوله\n(إن الخليفة قد أبى ... وإذا أبى شيئا أبيته)\n(ومخضب رخص البنان ... بكى علي وما بكيته)\n(يا منظرا حسنا رأيت ... بوجه جارية فديته)\n(بعثت إلي تسومني ... ثوب الشباب وقد طويته)\nطرب بشار وقال هذا والله يا أبا عبد الله أحسن من سورة الحشر وقد روى هذه الكلمة عن بشار غير من ذكرته فقال عنه إنه قال هي والله أحسن من سورة الحشر الغناء في هذه الأبيات وتمام الشعر\n(وأنا المطل على العدا ... وإذا غلا الحمد اشتريته)\n(وأميل في أنس النديم ... من الحياء وما اشتهيته)\n(ويشوقني بيت الحبيب ... إذا غدوت وأين بيته)\n(حال الخليفة دونه ... فصبرت عنه وما قليته)\nوأنشدني أبو دلف هاشم بن محمد الخزاعي هذه الأبيات وأخبرني أن الجاحظ أخبره أن المهدي نهى بشارا عن الغزل وأن يقول شيئا من النسيب فقال هذه الأبيات قال وكان الخليل بن أحمد ينشدها ويستحسنها ويعجب بها أخبرني هاشم بن محمد قال حدثنا دماذ أبو غسان عن محمد بن الحجاج قال قالت بنت بشار لبشار يا أبت مالك يعرفك الناس ولا تعرفهم قال كذلك الأمير يا بنية","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":25,"spl":"هابه الأخفش فاستشهد بشعره — دفاعه عن أبي النضير"},
{"id":"b25-46","bab":"الجزء 3","sec":"دفاعه عن أبي النضير","page":"ج3 ص209","text":"أخبرني عبد الله بن محمد الرازي قال حدثنا أحمد بن الحارث الخراز عن المدائني قال قال عبد الله بن مسور الباهلي يوما لأبي النضير وقد تحاورا في شيء يابن اللخناء أتكلمني ولو اشتريت عبدا بمائتي درهم وأعتقته لكان خيرا منك فقال له أبو النضير والله لو كنت ولد زنا لكنت خيرا من باهلة كلها فغضب الباهلي فقال له بشار أنت منذ ساعة تزني أمه ولا يغضب فلما كلمك كلمة واحدة لحقك\nهذا كله فقال له وأمه مثل أمي يا أبا معاذ فضحك ثم قال والله لو كانت أمك أم الكتاب ما كان بينكما من المصارمة هذا كله","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":25,"spl":"هابه الأخفش فاستشهد بشعره — دفاعه عن أبي النضير"},
{"id":"b25-47","bab":"الجزء 3","sec":"هجاؤه ليزيد بن مزيد","page":"ج3 ص210","text":"نسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال حدثني سعيد بن عبيد الخزاعي قال ورد بشار بغداد فقصد يزيد بن مزيد وسأله أن يذكره للمهدي فسوفه أشهرا ثم ورد روح بن حاتم فبلغه خبر بشار فذكره للمهدي من غير أن يلقاه وأمر بإحضاره فدخل إلى المهدي وأنشده شعرا مدحه به فوصله بعشرة آلاف درهم ووهب له عبدا وقينة وكساه كسا كثيرة وكان يحضر قيسا مرة فقال بشار يهجو يزيد بن مزيد\n(ولما التقينا بالجنينة غرني ... بمعروفه حتى خرجت أفوق)\nرني أوجرني كما يغر الصبي أي يوجر اللبن\n(حباني بعبد قعسري وقينة ... ووشي وآلاف لهن بريق)\n(فقل ليزيد يلعص الشهد خاليا ... لنا دونه عند الخليفة سوق)\n(رقدت فنم يابن الخبيثة إنها ... مكارم لا يستطيعهن لصيق)\n(أبى لك عرق من فلانة أن ترى ... جوادا ورأس حين شبت حليق)\nخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال حدثنا الأصمعي\nقال كان بشار كتب إلى إبراهيم بن عبد الله بن الحسن بقصيدة يمدحه بها ويحرضه ويشير عليه فلم تصل إليه حتى قتل وخاف بشار أن تشتهر فقلبها وجعل التحريض فيها على أبي مسلم والمدح والمشورة لأبي جعفر المنصور فقال\n(أبا مسلم ما طيب عيش بدائم ... ولا سالم عما قليل بسالم)\nإنما كان قال أبا جعفر ما طيب عيش فغيره وقال فيها\n(إذا بلغ الرأي النصيحة فاستعن ... بعزم نصيح أو بتأييد حازم)\n(ولا تجعل الشورى عليك غضاضة ... مكان الحوافي نافع للقوادم)\n(وخل الهوينى للضعيف ولا تكن ... نؤوما فإن الحزم ليس بنائم)\n(وما خير كف أمسك الغل أختها ... وما خير سيف لم يؤيد بقائم)\n(وحارب إذا لم تعط إلا ظلامة ... شبا الحرب خير من قبول المظالم)\n(وأدن على القربى المقرب نفسه ... ولا تشهد الشورى امرأ غير كاتم)\n(فإنك لا تستطرد الهم بالمنى ... ولا تبلغ العليا بغير المكارم)\n(إذا كنت فردا هرك القوم مقبلا ... وإن كنت أدنى لم تفز بالعزائم)\n(وما قرع الأقوام مثل مشيع ... أريب ولا جلى العمى مثل عالم)\nال الأصمعي فقلت لبشار إني رأيت رجال الرأي يتعجبون من أبياتك في\nالمشورة فقال أما علمت أن المشاور من إحدى الحسنين بين صواب يفوز بثمرته أو خطأ يشارك في مكروهه فقلت أنت والله أشعر في هذا الكلام منك في الشعر أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني علي بن الصباح عن بعض الكوفيين قال مررت ببشار وهو متبطح في دهليزه كأنه جاموس فقلت له يا أبا معاذ من القائل\n(في حلتي جسم فتى ناحل ... لو هبت الريح به طاحا)\nال أنا قلت فما حملك على هذا الكذب والله إني لأرى أن لو بعث الله الرياح التي أهلك بها الأمم الخالية ما حركتك من موضعك فقال بشار من أين أنت قلت من أهل الكوفة فقال يا أهل الكوفة لا تدعون ثقلكم ومقتكم على كل حال نسخت من كتاب هارون بن علي قال حدثني عافية بن شبيب قال قدم كردي بن عامر المسمعي من مكة فلم يهد لبشار شيئا وكان صديقه فكتب إليه\n(ما أنت يا كردي بالهش ... ولا أبريك من الغش)\n(لم تهدنا نعلا ولا خاتما ... من أين أقبلت من الحش)\nأهدى إليه هدية حسنة وجاءه فقال عجلت يا أبا معاذ علينا فأنشدك الله ألا تزيد شيئا على ما مضى\nونسخت من كتابه عن عافية بن شبيب أيضا قال حدثني صديق لي قال قلت لبشار كنا أمس في عرس فكان أول صوت غنى به المغني\n(هوى صاحبي ريح الشمال إذا جرت ... وأشفى لنفسي أن تهب جنوب)\n(وما ذاك إلا أنها حين تنتهي ... تناهى وفيها من عبيدة طيب)\nفطرب وقال هذا والله أحسن من فلج يوم القيامة أخبرنا يحيى بن علي قال حدثنا أبي عن عافية بن شبيب عن أبي جعفر الأسدي قال مدح بشار المهدي فلم يعطه شيئا فقيل له لم يستجد شعرك فقال والله لقد قلت شعرا لو قيل في الدهر لم يخش صرفه على أحد ولكنا نكذب في القول فنكذب في الأمل","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":26,"spl":"هجاؤه ليزيد بن مزيد"},
{"id":"b25-48","bab":"الجزء 3","sec":"هجاء روح بن حاتم","page":"ج3 ص213","text":"أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني يحيى بن خليفة الدارمي عن نصر بن عبد الرحمن العجلي قال هجا بشار روح بن حاتم فبلغه ذلك فقذفه وتهدده فلما بلغ ذلك بشارا قال فيه\n(تهددني أبو خلف ... وعن أوتاره ناما)\n(بسيف لأبي صفرة ... لا يقطع إبهاما)\n(كأن الورس يعلوه ... إذا ما صدره قاما)\nال ابن أبي سعد ومن الناس من يروي هذين البيتين لعمرو الظالمي قال فبلغ ذلك روحا فقال كل مالي صدقة إن وقعت عيني عليه لأضربنه ضربة بالسيف ولو أنه بين يدي الخليفة فبلغ ذلك بشارا فقام من فوره حتى دخل على المهدي فقال له ما جاء بك في هذا الوقت فأخبره بقصة روح وعاذ به منه فقال يا نصير وجه إلى روح من يحضره الساعة فأرسل إليه في الهاجرة وكان ينزل المخرم فظن هو وأهله أنه دعي لولاية قال يا روح إني بعثت إليك في حاجة فقال له أنا عبدك يا أمير المؤمنين فقل ما شئت سوى بشار فإني حلفت في أمره بيمين غموس قال قد علمت وإياه أردت قال له فاحتل ليميني يا أمير المؤمنين فأحضر القضاة والفقهاء فاتفقوا على أن يضربه ضربة على جسمه بعرض السيف وكان بشار وراء الخيش فأخرج وأقعد واستل روح سيفه فضربه ضربة بعرضه فقال أوه باسم الله فضحك المهدي وقال له ويلك هذا وإنما ضربك بعرضه وكيف لو ضربك بحده","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":27,"spl":"هجاء روح بن حاتم — مدح سليمان بن هشام"},
{"id":"b25-49","bab":"الجزء 3","sec":"مدح سليمان بن هشام","page":"ج3 ص214","text":"أخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثنا أبو عبيدة قال\nمدح بشار سليمان بن هشام بن عبد الملك وكان مقيما بحران وخرج إليه فأنشده قوله فيه\n(نأتك على طول التجاور زينب ... وما شعرت أن النوى سوف تشعب)\n(يرى الناس ما تلقى بزينب إذ نأت ... عجيبا وما تخفي بزينب أعجب)\n(وقائلة لي حين جد رحيلنا ... وأجفان عينيها تجود وتسكب)\n(أغاد إلى حران في غير شيعة ... وذلك شأو عن هواها مغرب)\n(فقلت لها كلفتني طلب الغنى ... وليس وراء ابن الخليفة مذهب)\n(سيكفي فتى من سعيه حد سيفه ... وكور علافي ووجناء ذعلب)\n(إذا استوغرت دار عليه رمى بها ... بنات الصوى منها ركوب ومصعب)\n(فعدي إلى يوم ارتحلت وسائلي ... بزورك والرحال من جاء يضرب)\n(لعلك أن تستيقني أن زورتي ... سليمان من سير الهواجر تعقب)\n(أغر هشامي القناة إذا انتمى ... نمته بدور ليس فيهن كوكب)\n(وما قصدت يوما مخيلين خيله ... فتصرف إلا عن دماء تصبب)\nوصله سليمان بخمسة آلاف درهم وكان يبخل فلم يرضها وانصرف عنه مغضبا فقال\n(إن أمس منقبض اليدين عن الندى ... وعن العدو مخيس الشيطان)\n(فلقد أروح عن اللئام مسلطا ... ثلج المقيل منعم الندمان)\n(في ظل عيش عشيرة محمودة ... تندى يدي ويخاف فرط لساني)\n(أزمان جني الشباب مطاوع ... وإذ الأمير علي من حران)\n(ريم بأحوية العراق إذا بدا ... برقت عليه أكلة المرجان)\n(فاكحل بعبدة مقلتيك من القذى ... وبوشك رؤيتها من الهملان)\n(فلقرب من تهوى وأنت متيم ... أشفى لدائك من بني مروان)\nلما رجع إلى العراق بره ابن هبيرة ووصله وكان يعظم بشارا ويقدمه لمدحه قيسا وافتخاره بهم فلما جاءت دولة أهل خراسان عظم شأنه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":27,"spl":"هجاء روح بن حاتم — مدح سليمان بن هشام"},
{"id":"b25-50","bab":"الجزء 3","sec":"المهدي ينهاه عن التشبيب","page":"ج3 ص216","text":"أخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثني محمد بن الحجاج قال قدم بشار الأعمى على المهدي بالرصافة فدخل عليه في البستان فأنشده مديحا فيه تشبيب حسن فنهاه عن التشبيب لغيرة شديدة كانت فيه فأنشده مديحا فيه يقول فيه\n(كأنما جئته أبشره ... ولم أجىء راغبا ومحتلبا)\n(يزين المنبر الأشم بعطفيه ... وأقواله إذا خطبا)\n(تشم نعلاه في الندي كما ... يشم ماء الريحان منتهبا)\nأعطاه خمسة آلاف درهم وكساه وحمله على بغل وجعل له وفادة في كل سنة ونهاه عن التشبيب البتة فقدم عليها في السنة الثالثة فدخل عليه فأنشده\n(تجاللت عن فهر وعن جارتي فهر ... وودعت نعمى بالسلام وبالبشر)\n(وقالت سليمى فيك عنا جلادة ... محلك دان والزيارة عن عفر)\n(أخي في الهوى مالي أراك جفوتنا ... وقد كنت تقفونا على العسر واليسر)\n(تثاقلت إلا عن يد أستفيدها ... وزورة أملاك أشد بها أزري)\n(وأخرجني من وزر خمسين حجة ... فتى هاشمي يقشعر من الوزر)\n(دفنت الهوى حيا فلست بزائر ... سليمى ولا صفراء ما قرقر القمري)\n(ومصفرة بالزعفران جلودها ... إذا اجتليت مثل المفرطحة الصفر)\n(فرب ثقال الردف هبت تلومني ... ولو شهدت قبري لصلت على قبري)\n(تركت لمهدي الأنام وصالها ... وراعيت عهدا بيننا ليس بالختر)\n(ولولا أمير المؤمنين محمد ... لقبلت فاها أو لكان بها فطري)\n(لعمري لقد أوقرت نفسي خطيئة ... فما أنا بالمزداد وقرا على وقر)\nي قصيدة طويلة امتدحه بها فأعطاه ما كان يعطيه قبل ذلك ولم يزده شيئا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":28,"spl":"المهدي ينهاه عن التشبيب"},
{"id":"b25-51","bab":"الجزء 3","sec":"تمثل بقول جرير في رثائه لابنه","page":"ج3 ص218","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل العتكي عن محمد بن سلام عن بعض أصحابه قال حضرنا جنازة ابن لبشار توفي فجزع عليه جزعا شديدا وجعلنا نعزيه ونسليه فما يغني ذلك شيئا ثم التفت إلينا وقال لله در جرير حيث يقول وقد عزي بسوادة ابنه\n(قالوا نصيبك من أجر فقلت لهم ... كيف العزاء وقد فارقت أشبالي)\n(ودعتني حين كف الدهر من بصري ... وحين صرت كعظم الرمة البالي)\n(أودى سوادة يجلو مقلتي لحم ... باز يصرصر فوق المربأ العالي)\n(إلا تكن لك بالديرين نائحة ... فرب نائحة بالرمل معوال)\nخبرني هاشم بن محمد قال حدثنا عمر بن شبة قال حدثني خلاد الأرقط قال لما أنشد المهدي قول بشار\n(لا يؤيسنك من مخبأة ... قول تغلظه وإن جرحا)\n(عسر النساء إلى مياسرة ... والصعب يمكن بعد ما جمحا)\nفنهاه المهدي عن قوله مثل هذا ثم حضر مجلسا لصديق له يقال له عمرو بن سمان فقال له أنشدنا يا أبا معاذ شيئا من غزلك فأنشأ يقول\n(وقائل هات شوقنا فقلت له ... أنائم أنت يا عمرو بن سمان)\n(أما سمعت بما قد شاع في مضر ... وفي الحليفتين من نجر وقحطان)\n(قال الخليفة لا تنسب بجارية ... إياك إياك أن تشقى بعصيان)\nخبرني عيسى بن الحسين الوراق قال حدثنا سليمان بن أيوب المدائني قال قال مروان بن أبي حفصة قدمت البصرة فأنشدت بشارا قصيدة لي واستنصحته فيها فقال لي ما أجودها تقدم بغداد فتعطى عليها عشرة آلاف درهم فجزعت من ذلك وقلت قتلتني فقال هو ما أقول لك وقدمت بغداد فأعطيت عليها عشرة آلاف درهم ثم قدمت عليه قدمة أخرى فأنشدته قصيدتي\n(طرقتك زائرة فحي خيالها ... )\nقال تعطى عليها مائة ألف درهم فقدمت فأعطيت مائة ألف درهم فعدت إلى البصرة فأخبرته بحالي في المرتين وقلت له ما رأيت أعجب من حدسك فقال يا بني أما علمت أنه لم يبق أحد أعلم بالغيب من عمك أخبرنا بهذا الخبر محمد بن يحيى الصولي قال حدثنا يزيد بن محمد المهلبي عن محمد بن عبد الله بن أبي عيينة عن مروان أنه قدم على بشار فأنشده قوله\n(طرقتك زائرة فحي خيالها ... )\nقال له يعطونك عليها عشرة آلاف درهم ثم قدم فيه فأنشده قوله\n(أنى يكون وليس ذاك بكائن ... لبني البنات وراثة الأعمام)\nقال يعطونك عليها مائة ألف درهم وذكر باقي الخبر مثل الذي قبله أخبرني عيسى قال حدثنا سليمان قال قال بعض أصحاب بشار كنا نكون عنده فإذا حضرت الصلاة قمنا إليها ونجعل على ثيابه ترابا حتى ننظر هل يقوم يصلي فنعود والتراب مجاله وما صلى أخبرني عيسى قال حدثنا سليمان قال قال أبو عمرو بعث المهدي إلى بشار فقال له قل في الحب شعرا ولا تطل واجعل الحب قاضيا بين المحبين ولا تسم أحدا فقال\n(اجعل الحب بين حبي وبيني ... قاضيا إنني به اليوم راضي)\n(فاجتمعنا فقلت يا حب نفسي ... إن عيني قليلة الإغماض)\n(أنت عذبتني وانحلت جسمي ... فارحم اليوم دائم الأمراض)\n(قال لي لا يحل حكمي عليها ... أنت أولى بالسقم والإحراض)\n(قلت لما أجابني بهواها ... شمل الجور في الهوى كل قاضي)\nبعث إليه المهدي حكمت علينا ووافقنا ذلك فأمر له بألف دينار أخبرني عيسى قال حدثني سليمان المدني قال حدثني الفضل بن إسحاق الهاشمي قال أنشد بشار قوله\n(يروعه السوار بكل أرض ... مخافة أن يكون به السرار)\nفقال له رجل أظنك أخذت هذا من قول أشعب ما رأيت اثنين يتساران إلا ظننت أنهما يأمران لي بشيء فقال إن كنت أخذت هذا من قول أشعب فإنك أخذت ثقل الروح والمقت من الناس جميعا فانفردت به دونهم ثم قام فدخل وتركنا وأخذ أبو نواس هذا المعنى بعينه من بشار فقال فيه\n(تركتني الوشاة نصب المسرين ... وأحدوثه بكل مكان)\n(ما أرى خاليين في السر إلا ... قلت ما يخلوان إلا لشاني)\nخبرني عمي قال حدثني سليمان قال قال لي أبو عدنان حدثني سعيد جليس كان لأبي زيد قال أتاني أعشى سليم وأبو حنش فقالا لي انطلق معنا إلى بشار فتسأله أن ينشدك شيئا من هجائه في حماد عجرد أو في عمرو الظالمي فإنه إن عرفنا لم ينشدنا فمضيت معهما حتى دخلت على بشار فاستنشدته فأنشد قصيدة له على الدال فجعل يخرج من واد في الهجاء إلى واد آخر يستمعان وبشار لا يعرفهما فلما خرجا قال أحدهما للآخر أما تعجب مما جاء به هذا الأعمى فقال أبو حنش أما أنا فلا أعرض والله والدي له أبدا وكانا قد جاءا يزورانه وأحسبهما أرادا أن يتعرضا لمهاجائه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":29,"spl":"تمثل بقول جرير في رثائه لابنه","partial":1},
{"id":"b25-52","bab":"الجزء 3","sec":"مدحه لواصل بن عطاء","page":"ج3 ص221","text":"أخبرني هاشم بن محمد الخزاعي عن الجاحظ قال كان بشار صديقا لأبي حذيفة واصل بن عطاء قبل أن يدين بالرجعة ويكفر الأمة وكان قد مدح واصلا وذكر خطبته التي خطبها فنزع منها كلها الراء وكانت\nعلى البديهة وهي أطول من خطبتي خالد بن صفوان وشبيب بن شيبة فقال\n(تكلفوا القول والأقوام قد حفلوا ... وحبروا خطبا ناهيك من خطب)\n(فقام مرتجلا تغلي بداهته ... كمرجل القين لما حف باللهب)\n(وجانب الراء لم يشعر به أحد ... قبل التصفح والإغراق في الطلب)\nال فلما دان بالرجعة زعم أن الناس كلهم كفروا بعد رسول الله فقيل له وعلي بن أبي طالب فقال\n(وما شر الثلاثة أم عمرو ... بصاحبك الذي لا تصبحينا)\nخبرني هاشم بن محمد قال حدثنا عيسى بن إسماعيل تينة قال قال لي محمد بن الحجاج قال بشار ما كان الكميت شاعرا فقيل له وكيف وهو الذي يقول\n(أنصف امرىء من نصف حي يسبني ... لعمري لقد لاقيت خطبا من الخطب)\n(هنيئا لكلب أن كلبا يسبني ... وأني لم أردد جوابا على كلب)\nقال بشار لا بل شانئك أترى رجلا لو ضرط ثلاثين سنة لم يستحل من ضرطه\nضرطة واحدة نسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال حدثني حجاج المعلم قال سمعت سفيان بن عيينة يقول عهدي بأصحاب الحديث وهم أحسن الناس أدبا ثم صاروا الآن أسوأ الناس أدبا وصبرنا عليهم حتى أشبهناهم فصرنا كما قال الشاعر\n(وما أنا إلا كالزمان إذا صحا ... صحوت وإن ماق الزمان أموق)\nخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال حدثني محمد بن الحجاج قال كنا مع بشار فأتاه رجل فسأله عن منزل رجل ذكره له فجعل يفهمه ولا يفهم فأخذ بيده وقام يقوده إلى منزل الرجل وهو يقول\n(أعمى يقود بصيرا لا أبالكم ... قد ضل من كانت العميان تهديه)\nتى صار به إلى منزل الرجل ثم قال له هذا هو منزله يا أعمى أخبرني عمي قال حدثني أحمد بن أبي طاهر قال زعم أبو دعامة أن عطاء الملط أخبره أنه أتى بشارا فقال له يا أبا معاذ أنشدك شعرا حسنا فقال ما أسرني بذلك فأنشده\n(أعاذلتي اليوم ويلكما مهلا ... فما جزعا م الآن أبكي ولا جهلا)\nلما فرغ منها قال له بشار أحسنت ثم أنشده على رويها ووزنها\n(لقد كاد من أخفي من الوجد والهوى ... يكون جوى بين الجوانج أو خبلا)\nصوت\n(إذا قال مهلا ذو القرابة زادني ... ولوعا بذكراها ووجدا بها مهلا)\n(فلا يحسب البيض الأوانس أن في ... فؤادي سوى سعدى لغانية فضلا)\n(فأقسم إن كان الهوى غير بالغ ... بي القتل من سعدى لقد جاوز القتلا)\n(فيا صاح خبرني الذي أنت صانع ... بقاتلتي ظلما وما طلبت ذحلا)\n(سوى أنني في الحب بيني وبينها ... شددت على أكظام سر لها قفلا)\nذكر أحمد بن المكي أن لإسحاق في هذه الأبيات ثقيلا أول بالوسطى فاستحسنت القصيدة وقلت يا أبا معاذ قد والله أجدت وبالغت فلو تفضلت بأن تعيدها فأعادها على خلاف ما أنشدنيها في المرة الأولى فتوهمت أنه قالها في تلك الساعة أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن خلاد قال حدثني أبي قال كنت أكلم بشارا وأرد عليه سوء مذهبه بميله إلى الإلحاد فكان يقول لا أعرف إلا ما عاينته أو عاينت مثله وكان الكلام يطول بيننا فقال لي ما أظن الأمر يا أبا خالد إلا كما تقول وأن الذي نحن فيه خذلان ولذلك أقول\n(طبوعت على ما في غير مخير ... هواي ولو خيرت كنت المهذبا)\n(أريد فلا أعطى وأعطى ولم أرد ... وقصر علمي أن أنال المغيبا)\n(فأصرف عن قصدي وعلمي مقصر ... وأمسي وما أعقبت إلا التعجبا)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":30,"spl":"مدحه لواصل بن عطاء"},
{"id":"b25-53","bab":"الجزء 3","sec":"خبره مع فتى من بني منقر أهدى إليه أضحية","page":"ج3 ص224","text":"أخبرني الحسن بن علي قال حدثني ابن مهرويه قال حدثني أحمد بن خلاد\nابن المبارك قال حدثني أبي قال كان بالبصرة فتى من بني منقر أمه عجلية وكان يبعث إلى بشار في كل أضحية بأضحية من الأضاحي التي كان أهل البصرة يسمنونها سنة وأكثر للأضاحي ثم تباع الأضحية بعشرة دنانير ويبعث معها بألف درهم قال فأمر وكيله في بعض السنين أن يجريه على رسمه فاشترى له نعجة كبيرة غير سمينة وسرق باقي الثمن وكانت نعجة عبدلية من نعاج عبد الله بن دارم وهو نتاج مرذول فلما أدخلت عليه قالت له جاريته ربابة ليست هذه الشاة من الغنم التي كان يبعث بها إليك فقال أدنيها مني فأدنتها ولمسها بيده ثم قال اكتب يا غلام\n(وهبت لنا يا فتى منقر ... وعجل وأكرمهم أولا)\n(وأبسطهم راحة في الندى ... وأرفعهم ذروة في العلا)\n(عجوزا قد اوردها عمرها ... وأسكنها الدهر دار البلى)\n(سلوحا توهمت أن الرعاء ... سقوها ليسهلها الحنظلا)\n(وأضرط من أم مبتاعها ... إن اقتحمت بكرة حرملا)\n(فلو تأكل الزبد بالنرسيان ... وتدمج المسك والمندلا)\n(لما طيب الله أرواحها ... ولا بل من عظمها الأقحلا)\n(وضعت يميني على ظهرها ... فخلت حراقفها جندلا)\n(وأهوت شمالي لعرقوبها ... فخلت عراقبها مغزلا)\n(وقلبت أليتها بعد ذا ... فشبهت عصعصها منجلا)\n(فقلت أبيع فلا مشربا ... أرجي لديها ولا مأكلا)\n(أم اشوي وأطبخ من لحمها ... وأطيب من ذاك مضغ السلى)\n(إذا ما أمرت على مجلس ... من العجب سبح أو هللا)\n(رأوا آية خلفها سائق ... يحث وإن هرولت هرولا)\n(وكنت أمرت بها ضخمة ... بلحم وشحم قد استكملا)\n(ولكن روحا عدا طوره ... وما كنت أحسب أن يفعلا)\n(فعض الذي خان في أمرها ... من است امه بظرها الأغرلا)\n(ولولا مكانك قلدته ... علاطا وأنشقته الخردلا)\n(ولولا استحائيك خضبتها ... وعلقت في جيدها جلجلا)\n(فجاءتك حتى ترى حالها ... فتعلم أني بها مبتلى)\n(سألتك لحما لصبياننا ... فقد زدتني فيهم عيلا)\n(فخذها وأنت بنا محسن ... وما زلت بي محسنا مجملا)\nقال وبعث بالرقعة إلى الرجل فدعا بوكيله وقال له ويلك تعلم أني أفتدي من بشار بما أعطيه وتوقعني في لسانه إذهب فاشتر أضحية وإن قدرت أن تكون مثل الفيل فافعل وابلغ بها ما بلغت وابعث بها إليه أخبرني هاشم بن محمد قال حدثنا عبد الرحمن ابن أخي الأصمعي قال حدثني عمي قال أخبرنا أبو عمرو بن العلاء قال رأيت بشارا المرعث يرثي بنية له وهو يقول\n(يا بنت من لم يك يهوى بنتا ... ما كنت إلا خمسة أو ستا)\n(حتى حللت في الحشى وحتى ... فتت قلبي من جوى فانفتا)\n(لأنت خير من غلام بتا ... يصبح سكران ويمسي بهتا)\nخبرني وكيع قال حدثني أبو أيوب المديني قال كان نافع بن عقبة بن سلم جوادا ممدحا وكان بشار منقطعا إلى أبيه فلما مات أبوه وفد إليه وقد ولي أبيه فمدحه بقوله\n(ولنافع فضل على أكفائه ... إن الكريم أحق بالتفضيل)\n(يا نافع الشبرات حين تناوحت ... هوج الرياح وأعقبت بوبول)\n(أشبهت عقبة غير ما متشبه ... ونشأت في حلم وحسن قبول)\n(ووليت فينا أشهرا فكفيتنا ... عنت المريب وسلة التضليل)\n(تدعى هلالا في الزمان ونافعا ... والسلم نعم أبوة المأمول)\nأعطاه مثل ما كان أبوه يعطيه في كل سنة إذا وفد عليه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":31,"spl":"خبره مع فتى من بني منقر أهدى إليه أضحية — خبر المهدي مع جارية تغتسل وشعر بشار في ذلك"},
{"id":"b25-54","bab":"الجزء 3","sec":"خبر المهدي مع جارية تغتسل وشعر بشار في ذلك","page":"ج3 ص228","text":"أخبرني هاشم بن محمد قال حدثنا الحسن بن عليل العنزي قال حدثني إبراهيم بن عقبة الرفاعي قال حدثني إسحاق بن إبراهيم التمار البصري قال دخل المهدي إلى بعض حجر الحرم فنظر إلى جارية منهن تغتسل فلما رأته حصرت ووضعت يدها على فرجها فأنشأ يقول\n(نظرت عيني لحيني ... )\nثم أرتج عليه فقال من بالباب من الشعراء قالوا بشار فأذن له فدخل فقال له أجز\n(نظرت عيني لحيني ... )\nقال بشار\n(نظرت عيني لحيني ... نظرا وافق شيني)\n(سترت لما رأتني ... دونه بالراحتين)\n(فضلت منه فضول ... تحت طي العكنتين)\nقال له المهدي قبحك الله ويحك أكنت ثالثنا ثم ماذا فقال\n(فتمنيت وقلبي ... للهوى في زفرتين)\n(أنني كنت عليه ... ساعة أو ساعتين)\nفضحك المهدي وأمر له بجائزة فقال يا أمير المؤمنين أقنعت من هذه الصفة بساعة أو ساعتين فقال اخرج عني قبحك الله فخرج بالجائزة","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":31,"spl":"خبره مع فتى من بني منقر أهدى إليه أضحية — خبر المهدي مع جارية تغتسل وشعر بشار في ذلك","partial":1},
{"id":"b25-55","bab":"الجزء 3","sec":"شعر على لسان حمار له مات عشقا","page":"ج3 ص229","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو شبل عاصم بن وهب البرجمي قال حدثني محمد بن الحجاج قال جاءنا بشار يوما فقلنا له مالك مغتما فقال مات حماري فرأيته في النوم فقلت له لم مت ألم أكن أحسن إليك فقال\n(سيدي خذ بي أتانا ... عند باب الأصبهاني)\n(تيمتني ببنان ... وبدل قد شجاني)\n(تيمتني يوم رحنا ... بثناياها الحسان)\n(وبغنج ودلال ... سل جسمي وبراني)\n(ولها خد أسيل ... مثل خد الشيفران)\n(فلذا مت ولو عشت ... إذا طال هواني)\nقلت له ما الشيفران قال ما يدريني هذا من غريب الحمار فإذا لقيته فاسأله أخبرني الحسن قال حدثني محمد بن القاسم قال حدثني علي بن إياس قال حدثني السري بن الصباح قال شهد بشار مجلسا فقال لا تصيروا مجلسنا هذا شعرا كله ولا حديثا كله ولا غناء كله فإن العيش فرض ولكن غنوا وتحدثوا وتناشدوا وتعالوا نتناهب بالعيش تناهبا أخبرني عمي قال حدثني الكراني عن ابن عائشة قال جاء بشار يوما إلى أبي وأنا على الباب فقال لي من أنت يا غلام فقلت\nمن ساكني الدار قال فكلمني والله بلسان ذرب وشدق هريت أخبرني عمي قال حدثني الكراني عن أبي حاتم قال كان سهيل بن عمر القرشي يبعث إلى بشار في كل سنة بقواصر تمر ثم أبطأ عليه سنة فكتب إليه بشار\n(تمركم يا سهيل در وهل يطمع ... في الدر من يدي متعتي)\n(فاحبني يا سهيل من ذلك التمر ... نواة تكون قرطا لبنتي)\nبعث إليه بالتمر وأضعفه له وكتب إليه يستعفيه من الزيادة في هذا الشعر ونسخت من كتاب هارون بن علي عن عافية بن شبيب عن الحسن بن صفوان قال جلس إلى بشار أصدقاء من أهل الكوفة كانوا على مثل مذهبه فسألوه أن ينشدهم شيئا مما أحدثه فأنشدهم قوله\n(أنى دعاه الشوق فارتاحا ... من بعد ما أصبح جحجاحا)\nتى أتى على قوله\n(في حلتي جسم فتى ناحل ... لو هبت الريح به طاحا)\nقالوا يابن الزانية أتقول هذا وأنت كأنك فيل عرضك أكثر من طولك فقال\nقوموا عني يا بني الزناء فإني مشغول القلب لست أنشط اليوم لمشاتمتكم","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":32,"spl":"شعر على لسان حمار له مات عشقا — ألح على امرأة فشكته إلى زوجها"},
{"id":"b25-56","bab":"الجزء 3","sec":"ألح على امرأة فشكته إلى زوجها","page":"ج3 ص231","text":"أخبرني يحيى بن علي بن يحيى عن أبيه عن عافية بن شبيب قال كان لبشار مجلس يجلس فيه بالعشي يقال له البردان فدخل عليه نسوة في مجلسه هذا فسمعن شعره فعشق امرأة منهن وقال لغلامه عرفها محبتي لها واتبعها إذا إنصرفت إلى منزلها ففعل الغلام وأخبرها بما أمره فلم تجبه إلى ما أحب فتبعها إلى منزلها حتى عرفه فكان يتردد إليها حتى برمت به فشكته إلى زوجها فقال لها أجيبيه وعديه إلى أن يجيئك إلى هاهنا ففعلت وجاء بشار مع امرأة وجهت بها إليه فدخل وزوجها جالس وهو لا يعلم فجعل يحدثها ساعة وقال له ما اسمك بأبي أنت فقالت أمامة فقال\n(أمامة قد وصفت لنا بحسن ... وإنا لا نراك فألمسينا)\nال فأخذت يده فوضعتها على أير زوجها وقد أنعظ ففزع ووثب قائما وقال\n(علي ألية ما دمت حيا ... أمسك طائعا إلا بعود)\n(ولا أهدي لقوم أنت فيهم ... سلام الله إلا من بعيد)\n(طلبت غنيمة فوضعت كفي ... على أير أشد من الحديد)\n(فخير منك من لا خير فيه ... وخير من زيارتكم قعودي)\nقبض زوجها عليه وقال هممت بأن أفضحك فقال له كفاني فديتك ما فعلت بي ولست والله عائدا إليها أبدا فحسبك ما مضى وتركه وانصرف وقد روي مثل هذه الحكاية عن الأصمعي في قصة بشار هذه وهذا الخبر بعينه يحكى بإسناد أقوى من هذا الإسناد وأوضح عن أبي العباس الأعمى السائب بن\nفروخ وقد ذكرته في أخبار أبي العباس بإسناده","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":32,"spl":"شعر على لسان حمار له مات عشقا — ألح على امرأة فشكته إلى زوجها"},
{"id":"b25-57","bab":"الجزء 3","sec":"بشار يرثي أصدقاءه الخمسة","page":"ج3 ص232","text":"نسخت من كتاب هارون بن علي قال حدثني علي بن مهدي قال حدثني حمدان الآبنوسي قال حدثنا أبو نواس قال كان لبشار خمسة ندماء فمات منهم أربعة وبقي واحد يقال له البراء فركب في زورق يريد عبور دجلة العوراء فغرق وكان المهدي قد نهى بشارا عن ذكر النساء والعشق فكان بشار يقول ما خير في الدنيا بعد الأصدقاء ثم رثى أصدقاءه بقوله\n(يابن موسى ماذا يقول الإمام ... في فتاة بالقلب منها أوام)\n(بت من حبها أوقر بالكأس ... ويهفو على فؤادي الهيام)\n(ويحها كاعبا تدل بجهم ... كعثبي كأنه حمام)\n(لم يكن بينها وبيني إلا ... كتب العاشقين والأحلام)\n(يابن موسى اسقني ودع عنك سلمى ... إن سلمى حمى وفي احتشام)\n(رب كأس كالسلسبيل تعللت ... بها والعيون عني نيام)\n(حبست للشراة في بيت رأس ... عتقت عانسا عليها الختام)\n(نفحت نفحة فهزت نديمي ... بنسيم وانشق عنها الزكام)\n(وكأن المعلول منها إذا راح ... شج في لسانه برسام)\n(صدمته الشمول حتى بعينيه ... انكسار وفي المفاصل خام)\n(وهو باقي الأطراف حيت به الكأس ... وماتت أوصاله والكلام)\n(وفتى يشرب المدامة بالمال ... ويمشي يروم ما لا يرام)\n(أنفدت كأسه الدنانير حتى ... ذهب العين واستمر السوام)\n(تركته الصهباء يرنو بعين ... نام إنسانها وليست تنام)\n(جن من شربة تعل بأخرى ... وبكى حين سار فيه المدام)\n(كان لي صاحبا فأودى به الدهر ... وفارقته عليه السلام)\n(بقي الناس بعد هلك نداماي ... وقوعا لم يشعروا ما الكلام)\n(كجزور الأيسار لا كبد فيها ... لباغ ولا عليها سنام)\n(يابن موسى فقد الحبيب على العين ... قذاة وفي الفؤاد سقام)\n(كيف يصفو لي النعيم وحيدا ... والأخلاء في المقابر هام)\n(نفستهم علي أم المنايا ... فأنامتهم بعنف فناموا)\n(لا يغيض انسجام عيني عنهم ... إنما غاية الحزين السجام)\nخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن الأصمعي\nأن بشارا وفد إلى عمر بن هبيرة وقد مدحه بقوله\n(يخاف المنايا أن ترحلت صاحبي ... كأن المنايا في المقام تناسبه)\n(فقلت له إن العراق مقامه ... وخيم إذا هبت عليك جنائبه)\n(لألقى بني عيلان إن فعالهم ... تزيد على كل الفعال مراتبه)\n(أولاك الألى شقوا العمى بسيوفهم ... عن العين حتى أبصر الحق طالبه)\n(وجيش كجنح الليل يزحف بالحصا ... وبالشوك والخطي حمرا ثعالبه)\n(غدونا له والشمس في خدر أمها ... تطالعنا والطل لم يجر ذائبه)\n(بضرب يذوق الموت من ذاق طعمه ... وتدرك من نجى الفرار مثالبه)\n(كأن مثار النقع فوق رؤوسنا ... وأسيافنا ليل تهاوى كوكبه)\n(بعثنا لهم موت الفجاءة إننا ... بنو الموت خفاق علينا سبائبه)\n(فراحوا فريق في الإسار ومثله ... قتيل ومثل لاذ بالبحر هاربه)\n(إذا الملك الجبار صعر خده ... مشينا إليه بالسيوف نعاتبه)\nوصله بعشرة آلاف درهم فكانت أول عطية سنية أعطيها بشار ورفعت من ذكره وهذه القصيدة هي التي يقول فيها\nصوت\n(إذا كنت في كل الأمور معاتبا ... صديقك لم تلق الذي لا تعاتبه)\n(فعش واحدا أو صل أخاك فإنه ... مقارف ذنب مرة ومجانبه)\n(إذا أنت لم تشرب مرارا على القذى ... ظمئت وأي الناس تصفو مشاربه)\nلغناء في هذه الأبيات لأبي العبيس بن حمدون خفيف ثقيل بالبنصر في مجراها أخبرني يحيى بن علي بن يحيى قال ذكر أبو أيوب المديني عن الأصمعي قال كان لبشار مجلس يجلس فيه يقال له البردان وكان النساء يحضرنه فبينما هو ذات يوم في مجلسه إذ سمع كلام امرأة في المجلس فعشقها فدعا غلامه فقال إذا تكلمت المرأة عرفتك فاعرفها فإذا انصرفت من المجلس فاتبعها وكلمها وأعلمها أني لها محب وقال فيها\n(يا قوم أذني لبعض الحي عاشقة ... والأذن تعشق قبل العين أحيانا)\n(قالوا بمن لا ترى تهذي فقلت لهم ... الأذن كالعين توفي القلب ما كانا)\n(هل من دواء لمشغوف بجارية ... يلقى بلقيانها روحا وريحانا)\nوقال في مثل ذلك\n(قالت عقيل بن كعب إذ تعلقها ... قلبي فأضحى به من حبها أثر)\n(أنى ولم ترها تهذي فقلت لهم ... إن الفؤاد يرى ما لا يرى البصر)\n(أصبحت كالحائم الحيران مجتنبا ... لم يقض وردا ولا يرجى له صدر)\nال يحيى بن علي وأنشدني أصحاب أحمد بن إبراهيم عنه لبشار في هذا المعنى وكان يستحسنه\n(يزهدني في حب عبدة معشر ... قلوبهم فيها مخالفة قلبي)\n(فقلت دعوا قلبي وما اختار وارتضى ... فبالقلب لا بالعين يبصر ذو الحب)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":33,"spl":"بشار يرثي أصدقاءه الخمسة"},
{"id":"b25-58","bab":"الجزء 3","sec":"بشار يرثي أصدقاءه الخمسة","page":"ج3 ص232","text":"(فما تبصر العينان في موضع الهوى ... ولا تسمع الأذنان إلا من القلب)\n(وما الحسن إلا كل حسن دعا الصبا ... وألف بين العشق والعاشق الصب)\nال أبو أحمد وقال في ذلك\n(يا قلب مالي أراك لا تقر ... إياك أعني وعندك الخبر)\n(أذعت بعد الألى مضوا حرقا ... أم ضاع ما استودعوك إذ بكروا)\nال أبو أحمد وقال في مثل ذلك\n(إن سليمى والله يكلؤها ... كالسكر تزداده على السكر)\n(بلغت عنها شكلا فأعجبني ... والسمع يكفيك غيبة البصر)\nخبرني محمد بن القاسم الأنباري قال حدثني أبي قال زعم أبو العالية أن بشارا قدم على المهدي فلما استأذن عليه قال له الربيع قد أذن لك وأمرك ألا تنشد شيئا من الغزل والتشبيب فادخل على ذلك فأنشده قوله\n(يا منظرا حسنا رأيته ... من وجه جارية فديته)\n(بعثت إلي تسومني ... برد الشباب وقد طويته)\n(والله رب محمد ... ما إن غدرت ولا نويته)\n(أمسكت عنك وربما ... عرض البلاء وما ابتغيته)\n(إن الخليفة قد أبى ... وإذا أبى شيئا أبيته)\n(ومخضب رخص البنان ... بكى علي وما بكيته)\n(ويشوقني بيت الحبيب ... إذا ادكرت وأين بيته)\n(قام الخليفة دونه ... فصبرت عنه وما قليته)\n(ونهاني الملك الهمام ... عن النسيب وما عصيته)\n(لا بل وفيت فلم أضع ... عهدا ولا رأيا رأيته)\n(وأنا المطل على العدا ... وإذا غلا علق شريته)\n(أصفي الخليل إذا دنا ... وإذا نأى عني نأيته)\nم أنشده ما مدحه به بلا تشبيه فحرمه ولم يعطه شيئا فقيل له إنه لم يستحسن شعرك فقال والله لقد مدحته بشعر لو مدح به الدهر لم يخش صرفه على أحد ولكنه كذب أملي لأني كذبت في قولي ثم قال في ذلك\n(خليلي إن العسر سوف يفيق ... وإن يسارا في غد لخليق)\n(وما كنت إلا كالزمان إذا صحا ... صحوت وإن ماق الزمان أموق)\n(أأدماء لا أستطيع في قلة الثرى ... خزوزا ووشيا والقليل محيق)\n(خذي من يدي ما قل إن زماننا ... شموس ومعروف الرجال رقيق)\n(لقد كنت لا أرضى بأدنى معيشة ... ولا يشتكي بخلا علي رفيق)\n(خليلي إن المال ليس بنافع ... إذا لم ينل منه أخ وصديق)\n(وكنت إذا ضاقت علي محلة ... تيممت أخرى ما علي تضيق)\n(وما خاب بين الله والناس عامل ... له في التقى أو في المحامد سوق)\n(ولا ضاق فضل الله عن متعفف ... ولكن أخلاق الرجال تضيق)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":34,"spl":"بشار يرثي أصدقاءه الخمسة"},
{"id":"b25-59","bab":"الجزء 3","sec":"المهدي يتهدده إذا عاد إلى قول النسيب","page":"ج3 ص238","text":"أخبرني حبيب بن نصر قال حدثني عمر بن شبة قال بلغ المهدي قول بشار\n(قاس الهموم تنل بها نجحا ... والليل إن وراءه صبحا)\n(لا يؤيسنك من مخباة ... قول تغلظه وإن جرحا)\n(عسر النساء إلى مياسرة ... والصعب يمكن بعد ما جمحا)\nلما قدم عليه استنشده هذا الشعر فأنشده إياه وكان المهدي غيورا فغضب وقال تلك أمك يا عاض كذا من أمه أتحض الناس على الفجور وتقذف المحصنات المخبات والله لئن قلت بعد هذا بيتا واحدا في نسيب لأتين على روحك فقال بشار في ذلك\n(والله لولا رضا الخليفة ما ... أعطيت ضيما علي في شجن)\n(وربما خير لابن آدم في الكره ... وشق الهوى على البدن)\n(فاشرب على ابنة الزمان فما ... تلقى زمانا صفا من الأبن)\n(الله يعطيك من فواضله والمرء ... يغضي عينا على الكمن)\n(قد عشت بين الريحان والراح والمزهر ... في ظل مجلس حسن)\n(وقد ملأت البلاد ما بين فغفور ... الى القيروان فاليمن)\nال عمر بن شبة فغفور ملك الصين\n(شعرا تصلي له العواتق والثيب ... صلاة الغواة للوثن)\n(ثم نهاني المهدي فانصرفت ... نفسي صنيع الموفق اللقن)\n(فالحمد لله لا شريك له ... ليس بباق شيء على الزمن)\nم أنشده قصيدته التي أولها\n(تجاللت عن فهر وعن جارتي فهر ... )\nوصف بها تركه التشبيب ومدحه فقال\n(تسلى عن الأحباب صرام خلة ... ووصال أخرى ما يقيم على أمر)\n(وركاض أفراس الصبابة والهوى ... جرت حججا ثم استقرت فما تجري)\n(فأصبحن ما يركبن إلا إلى الوغى ... وأصبحت لا يزرى علي ولا أزري)\n(فهذا وإني قد شرعت مع التقى ... وماتت همومي الطارقات فما تسري)\nثم قال يصف السفينة\n(وعذراء لا تجري بلحم ولا دم ... قليلة شكوى الأين ملجمة الدبر)\n(إذا ظعنت فيها الفلول تشخصت ... بفرسانها لا في وعوث ولا وعر)\n(وإن قصدت زلت على متنصب ... ذليل القوى لا شيء يفري كما تفري)\n(تلاعب تيار البحور وربما ... رأيت نفوس القوم من جريها تجري)\nال وكان قال نينان البحور فعابه بذلك سيبويه فجعله تيار البحور\n(إلى ملك من هاشم في نبوة ... ومن حمير في الملك في العدد الدثر)\n(من المشترين الحمد تندى من الندى ... يداه ويندى عارضاه من العطر)\n(فألزمت حبلي حبل من لا تغبه ... عفاة الندى من حيث يدري ولا يدري)\n(بنى لك عبد الله بيت خلافة ... نزلت بها بين الفراقد والنسر)\n(وعندك عهد من وصاة محمد ... فرعت به الأملاك من ولد النضر)\nلم يحظ منه أيضا بشيء فهجاه فقال في قصيدته","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":35,"spl":"المهدي يتهدده إذا عاد إلى قول النسيب","partialRef":{"sid":"b25-50","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b25-60","bab":"الجزء 3","sec":"المهدي يأمر بقتله بعد أن هجاه","page":"ج3 ص241","text":"(خليفة يزني بعماته ... يلعب بالدبوق والصولجان)\n(أبدلنا الله به غيره ... ودس موسى في حر الخيزران)\nأنشدها في حلقة يونس النحوي فسعي إلى يعقوب بن داود وكان بشار قد هجاه فقال\n(بني أمية هبوا طال نومكم ... إن الخليفة يعقوب بن داود)\n(ضاعت خلافتكم يا قوم فالتمسوا ... خليفة الله بين الزق والعود)\nدخل يعقوب على المهدي فقال له يا أمير المؤمنين إن هذا الأعمى الملحد الزنديق قد هجاك فقال بأي شيء فقال بما لا ينطق به لساني ولا يتوهمه فكري قال له بحياتي إلا أنشدتني فقال والله لو خيرتني بين إنشادي إياه وبين ضرب عنقي لاخترت ضرب عنقي فحلف عليه المهدي بالأيمان التي لا فسحة فيها أن يخبره فقال أما لفظا فلا ولكني أكتب ذلك فكتبه ودفعه إليه فكاد ينشق غيظا وعمد على الانحدار إلى البصرة للنظر في أمرها وما وكده غير بشار فانحدر فلما بلغ إلى البطيحة سمع أذانا في وقت ضحى النهار فقال انظروا ما هذا الأذان فإذا بشار يؤذن سكران فقال له يا زنديق يا عاض بظر أمه عجبت أن يكون هذا غيرك أتلهو بالأذان في غير وقت صلاة وأنت سكران ثم دعا بابن نهيك فأمره بضربه بالسوط فضربه بين يديه على صدر الحراقة سبعين\nسوطا أتلفه فيها فكان إذا أوجعه السوط يقول حس وهي كلمة تقولها العرب للشيء إذا أوجع فقال له بعضهم انظر إلى زندقته يا أمير المؤمنين يقول حس ولا يقول بسم الله فقال ويلك أطعام هو فأسمي الله عليه فقال له الآخر أفلا قلت الحمد لله قال أو نعمة هي حتى أحمد الله عليها فلما ضربه سبعين صوتا بان الموت فيه فألقي في سفينة حتى مات ثم رمي به في البطيحة فجاء بعض أهله فحملوه إلى البصرة فدفن بها أخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثني خالد بن يزيد بن وهب بن جرير عن أبيه قال لما ولي صالح بن داود أخو يعقوب بن داود وزير المهدي البصرة قال بشار يهجوه\n(هم حملوا فوق المنابر صالحا ... أخاك فضجت من أخيك المنابر)\nبلغ ذلك يعقوب فدخل على المهدي فقال يا أمير المؤمنين أبلغ من قدر هذا الأعمى المشرك أن يهجو أمير المؤمنين قال ويحك وما قال قال يعفيني أمير المؤمنين من إنشاده ثم ذكر باقي الخبر مثل الذي تقدمه فقال خالد بن يزيد بن وهب في خبره وخاف يعقوب بن داود أن يقدم على المهدي فيمدحه ويعفو عنه فوجه إليه من استقبله فضربه بالسياط حتى قتله ثم ألقاه في البطيحة في الخرارة أخبرني أحمد بن عبيد الله بن عمار قال حدثنا علي بن محمد النوفلي عن أبيه وعن جماعة من رواة البصريين وأخبرنا يحيى بن علي عن أحمد بن أبي طاهر عن علي بن محمد وخبره أتم قالوا خرج بشار إلى المهدي ويعقوب بن داود وزيره فمدحه ومدح يعقوب فلم يحفل به يعقوب ولم يعطه شيئا ومر يعقوب ببشار يريد منزله فصاح به بشار\n(طال الثواء على رسوم المنزل ... )\nفقال يعقوب\n(فإذا تشاء أبا معاذ فارحل ... )\nغضب بشار وقال يهجوه\n(بني أمية هبوا طال نومكم ... إن الخليفة يعقوب بن داود)\n(ضاعت خلافتكم يا قوم فالتمسوا ... خليفة الله بين الزق والعود)\nال النوفلي فلما طالت أيام بشار على باب يعقوب دخل عليه وكان من عادة بشار إذا أراد أن ينشد أو يتكلم أو يتفل عن يمينه ويصفق بإحدى يديه على الآخرى ففعل ذلك وأنشد\n(يعقوب قد ورد العفاة عشية ... متعرضين لسيبك المنتاب)\n(فسقيتهم وحسبتني كمونة ... نبتت لزارعها بغير شراب)\n(مهلا لديك فإنني ريحانة ... فاشمم بأنفك واسقها بذناب)\n(طال الثواء على تنظر حاجة ... شمطت لديك فمن لها بخضاب)\n(تعطي الغزيرة درها فإذا أبت ... كانت ملامتها على الحلاب)\nقول ليعقوب أنت من المهدي بمنزله الحالب من الناقة الغزيرة التي إذا لم يوصل إلى درها فليس ذلك من قبلها إنما هو في منع الحالب منها وكذلك الخليفة ليس من قبله لسعة معروفة إنما هي من قبل السبب إليه قال فلم يعطف ذلك يعقوب عليه وحرمه فانصرف إلى البصرة مغضبا فلما قدم المهدي البصرة أعطى عطايا كثيرة ووصل الشعراء وذلك كله على يدي يعقوب فلم يعط بشارا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":36,"spl":"المهدي يأمر بقتله بعد أن هجاه","partial":1},
{"id":"b25-61","bab":"الجزء 3","sec":"المهدي يأمر بقتله بعد أن هجاه","page":"ج3 ص241","text":"شيئا من ذلك فجاء بشار إلى حلقة يونس النحوي فقال هل ها هنا أحد يحتشم قالوا له لا فأنشأ بيتا يهجو فيه المهدي فسعى به أهل الحلقة إلى يعقوب فقال يونس للمهدي إن بشارا زنديق وقامت عليه البينة عندي بذلك وقد هجا أمير المؤمنين فأمر ابن نهيك بأخذه وأزف خروجهم فخرجوا وأخرجه ابن نهيك معه في زورق فلما كانوا بالبطيحة ذكره المهدي فأرسل إلى ابن نهيك يأمره أن يضرب بشارا ضرب التلف ويلقيه بالبطيحة فأمر به فأقيم على صدر السفينة وأمر الجلادين أن يضربوه ضربا يتلفون فيه نفسه ففعلوا ذلك فجعل يسترجع فقال بعض من حضر أما تراه لا يحمد الله فقال بشار أنعمة هي فأحمد الله عليها إنما هي بلية أسترجع عليها فضرب سبعين سوطا مات منها وألقي في البطيحة قال يحيى بن علي فحكى قعنب بن محرز الباهلي قال حدثني محمد بن الحجاج قال لما ضرب بشار بالسياط وطرح في السفينة قال ليت عين أبي الشمقمق رأتني حين يقول\n(إن بشار بن برد ... تيس أعمى في سفينة)\nخبرني أحمد بن عبيد الله بن عمار وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال أمر المهدي عبد الجبار صاحب الزنادقة فضرب بشارا فما بقي في بالبصرة شريف إلا بعث إليه بالفرش والكسوة والهدايا ومات بالبطيحة قال وكانت وفاته وقد ناهز ستين سنة","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":37,"spl":"المهدي يأمر بقتله بعد أن هجاه — قول الناس في موت بشار"},
{"id":"b25-62","bab":"الجزء 3","sec":"نعي بشار","page":"ج3 ص244","text":"قال عمر بن شبة حدثني سالم بن علي قال كنا عند يونس فنعى بشارا إلينا ناع فأنكر يونس ذلك وقال لم يمت فقال الرجل أنا رأيت قبره فقال أنت رأيته قال نعم وإلا فعلي وعلي وحلف له حتى رضي فقال يونس لليدين وللفم قال أبو زيد وحدثني جماعة من أهل البصرة منهم محمد بن عون بن بشير وكان يتهم بمذهب بشار فقال لما مات بشار ألقيت جثته بالبطيحة في موضع يعرف بالخرارة فحمله الماء فأخرجه إلى دجلة البصرة فأخذ فأتي به أهله فدفنوه قال وكان كثيرا ما ينشدني\n(سترى حول سريري ... حسرا يلطمن لطما)\n(يا قتيلا قتلته ... عبدة الحوراء ظلما)\nال وأخرجت جنازته فما تبعها أحد إلا أمة له سوداء سندية عجماء ما تفصح رأيتها خلف جنازته تصيح واسيداه واسيداه","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":37,"spl":"المهدي يأمر بقتله بعد أن هجاه — قول الناس في موت بشار"},
{"id":"b25-63","bab":"الجزء 3","sec":"قول الناس في موت بشار","page":"ج3 ص245","text":"قال أبو زيد وحدثني سالم بن علي قال لما مات بشار ونعي إلى أهل البصرة تباشر عامتهم وهنأ بعضهم بعضا وحمدوا الله وتصدقوا لما كانوا منوا به من لسانه\nوقال أبو هشام الباهلي فيما أخبرنا به يحيى بن علي في قتل بشار\n(يا بؤس ميت لم يبكه أحد ... أجل ولم يفتقده مفتقد)\n(لا أم أولاده بكته ولم ... يبك عليه لفرقة ولد)\n(ولا ابن أخت بكى ولا ابن أخ ... ولا حميم رقت له كبد)\n(بل زعموا أن أهله فرحا ... لما أتاهم نعيه سجدوا)\nال وقال أيضا في ذلك\n(قد تبع الأعمى قفا عجرد ... فأصبحا جارين في دار)\n(قالت بقاع الأرض لا مرحبا ... بروح حماد وبشار)\n(تجاورا بعد تنائيهما ... ما أبغض الجار إلى الجار)\n(صارا جميعا في يدي مالك ... في النار والكافر في النار)\nال أبو أحمد يحيى بن علي وأخبرنا بعض إخواني عن عمر بن محمد عن أحمد بن خلاد عن أبيه قال مات بشار سنة ثمان وستين ومائة وقد بلغ نيفا وسبعين سنة","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":37,"spl":"المهدي يأمر بقتله بعد أن هجاه — قول الناس في موت بشار"},
{"id":"b25-64","bab":"الجزء 3","sec":"المهدي يندم على أمره بقتل بشار","page":"ج3 ص246","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال لما ضرب المهدي بشارا بعث إلى منزله من يفتشه وكان يتهم بالزندقة فوجد في منزله طومار فيه بسم الله الرحمن الرحيم إني أردت هجاء آل سليمان بن علي لبخلهم فذكرت قرابتهم من رسول الله فأمسكت عنهم إجلالا له على أني قد قلت فيهم\n(دينار آل سليمان ودرهمهم ... كالبابليين حفا بالعفاريت)\n(لا يبصران ولا يرجى لقاؤهما ... كما سمعت بهاروت وماروت)\nلما قرأه المهدي بكى وندم على قتله وقال لا جزى الله يعقوب بن داود خيرا فإنه لما هجاه لفق عندي شهودا على أنه زنديق فقتلته ثم ندمت حين لا يغني الندم أخبرني محمد بن خلف بن المرزبان قال حدثنا عمر بن محمد بن عبد الملك قال حدثني محمد بن هارون قال لما نزل المهدي البصرة كان معه حمدويه صاحب الزنادقة فدفع إليه بشارا وقال اضربه ضرب التلف فضربه ثلاثة عشر سوطا فكان كلما ضربه سوطا قال له أوجعتني ويلك فقال يا زنديق أتضرب ولا تقول بسم الله قال ويلك أثريد هو فأسمي الله عليه قال ومات من ذلك الضرب ولبشار أخبار كثيرة قد ذكرت في عدة مواضع منها أخباره مع عبدة فإنها أفردت في بعض شعره فيها الذي غنى فيه المغنون وأخباره مع حماد عجرد في تهاجيهما فإنها أيضا أفردت وكذلك أخباره مع أبي هاشم الباهلي فإنا لا نجمع جميعها في هذا الموضع إذ كان كل صنف منها مستغنيا بنفسه حسبما شرط في تصدير الكتاب","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":38,"spl":"المهدي يندم على أمره بقتل بشار — جمال وجهه وخصاله"},
{"id":"b25-65","bab":"الجزء 3","sec":"أخبار يزيد حوراء طبقة يزيد حوراء","page":"ج3 ص248","text":"يزيد حوراء رجل من أهل المدينة ثم من موالي بني ليث بن بكر بن عبد مناة ابن كنانة ويكنى أبا خالد مغن محسن كثير الصناعة من طبقة ابن جامع وإبراهيم الموصلي وكان ممن قدم على المهدي في خلافته فغناه وكان حسن الصوت حلو الشمائل وذكر ابن خرداذبه أنه بلغه أن إبراهيم الموصلي حسده على شمائله وإشارته في الغناء فاشترى عدة جوار وشاركه فيهن وقال له علمهن فما رزق الله فيهن من ربح فهو بيننا وأمرهن أن يجعلن وكدهن أخذ إشارته ففعلن ذلك وكان إبراهيم يأخذها عنهن هو وابنه ويأمرهن بتعليم كل من يعرفنه ذلك حتى شهرها في الناس فأبطل عليه ما كان منفردا به من ذلك\nأخبرني الحسن بن علي قال حدثنا محمد بن موسى قال حدثني جماعة من موالي الرشيد إن يزيد حوراء كان صديقا لأبي العتاهية فقال أبو العتاهية أبياتا في أمر عتبة يتنجز فيها المهدي ما وعده إياه من تزويجها فإذا وجد المهدي طيب النفس غناه بها وهي\n(ولقد تنسمت الرياح حاجتي ... فإذا لها من راحتيك نسيم)\n(أشربت نفسي من رجائك ماله ... عنق يخب إليك بي ورسيم)\n(ورميت نحو سماء جودك ناظري ... أرعى مخايل برقه وأشيم)\n(ولربما استيأست ثم أقول لا ... إن الذي ضمن النجاح كريم)\nصنع بها لحنا وتوخى لها وقتا وجد المهدي فيه طيب النفس فغناه بها فدعا بأبي العتاهية وقال له أما عتبة فلا سبيل إليها لأن مولاتها منعت من ذلك ولكن هذه خمسون ألف درهم فاشتر ببعضها خيرا من عتبة فحملت إليه وانصرف","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":38,"spl":"المهدي يندم على أمره بقتل بشار — جمال وجهه وخصاله"},
{"id":"b25-66","bab":"الجزء 3","sec":"جمال وجهه وخصاله","page":"ج3 ص249","text":"أخبرني عمي قال حدثني أحمد بن المرزبان قال حدثنا شيبة بن هشام عن عبد الله بن العباس الربيعي قال\nكان يزيد حوراء نظيفا ظريفا حسن الوجه شكلا لم يقدم علينا من الحجاز أنظف ولا أشكل منه وما كنت تشاء أن ترى خصلة جميلة لا تراها في أحد منهم إلا رأيتها فيهم وكان يتعصب لإبراهيم الموصلي على ابن جامع فكان إبراهيم يرفع منه ويشيع ذكره بالجميل وينبه على مواضع تقدمه وإحسانه ويبعث بابنه إسحاق إليه يأخذ عنه وكان صديقا لأبي مالك الأعرج التميمي لا يكاد أن يفارقه فمرض مرضا شديدا واحتضر فاغتم عليه الرشيد وبعث بمسرور الخادم يسأل عنه ثم مات فقال أبو مالك يرثيه صوت\n(لم يمتع من الشباب يزيد ... صار في الترب وهو غض جديد)\n(خانه دهره وقابله منه ... بنحس ودابرته السعود)\n(حين زقت دنياه من كل وجه ... وتدانى إليه منه البعيد)\n(فكأن لم يكن يزيد ولم يشج ... نديما يهزه التغريد)\nفي هذه الأبيات لحسين بن محرز لحن من الثقيل الثاني بالبنصر من نسخة عمرو بن بانة","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":38,"spl":"المهدي يندم على أمره بقتل بشار — جمال وجهه وخصاله"},
{"id":"b25-67","bab":"الجزء 3","sec":"إنشاده شعر أبي العتاهية في حضرة المهدي","page":"ج3 ص250","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن أبي يوسف قال حدثني الحسين بن جمهور بن زياد بن طرخان مولى المنصور قال حدثني أبو محمد عبد الرحمن بن عيينة بن شارية الدؤلي قال حدثني محمد بن ميمون أبو زيد قال حدثني يزيد حوراء المغني قال\nكلمني أبو العتاهية في أن أكلم له المهدي في عتبة فقلت له إن الكلام لا يمكنني ولكن قل شعرا أغنه به فقال صوت\n(نفسي بشيء من الدنيا معلقة ... الله والقائم المهدي يكفيها)\n(إني لأيأس منها ثم يطمعني ... فيها احتقارك للدنيا وما فيها)\nال فعملت فيه لحنا وغنيته به فقال ما هذا فأخبرته خبر أبي العتاهية فقال ننظر فيما سأل فأخبرت أبا العتاهية ثم مضى شهر فجاءني وقال هل حدث خبر فقلت لا قال فاذكرني للمهدي قلت إن أحببت ذلك فقل شعرا تحركه وتذكره وعده حتى أغنيه به فقال صوت\n(ليت شعري ما عندكم ليت شعري ... فلقد أخر الجواب لأمر)\n(ما جواب أولى بكل جميل ... من جواب يرد من بعد شهر)\nقال يزيد فغنيت به المهدي فقال علي بعتبة فأحضرت فقال إن أبا العتاهية كلمني فيك فما تقولين ولك وله ما تحبان مما لا تبلغه أمانيكما فقالت له قد علم أمير المؤمنين ما أوجب الله علي من حق مولاتي وأريد أن أذكر لها هذا قال فافعلي قال وأعلمت أبا العتاهية ومضت أيام فسألني معاودة المهدي فقلت قد عرفت الطريق فقل ما شئت حتى أغنيه به فقال صوت\n(أشربت قلبي من رجائك ما له ... عنق يخب إليك بي ورسيم)\n(وأملت نحو سماء جودك ناظري ... أرعى مخايل برقها وأشيم)\n(ولربما استيأست ثم أقول لا ... إن الذي وعد النجاح كريم)\nال يزيد فغنيته المهدي فقال علي بعتبة فجاءت فقال ما صنعت فقالت ذكرت ذلك لمولاتي فكرهته وأبته فليفعل أمير المؤمنين ما يريد فقال ما كنت لأفعل شيئا تكرهه فأعلمت أبا العتاهية بذلك فقال\n(قطعت منك حبائل الآمال ... وأرحت من حل ومن ترحال)\n(ما كان أشأم إذ رجاؤك قاتلي ... وبنات وعدك يعتلجن ببالي)\n(ولئن طعمت لرب برقة خلب ... مالت بذي طمع ولمعة آل)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":39,"spl":"إنشاده شعر أبي العتاهية في حضرة المهدي — صوت من المائة المختارة"},
{"id":"b25-68","bab":"الجزء 3","sec":"عشقه لجارية","page":"ج3 ص252","text":"أخبرني محمد بن أبي الأزهر قال حدثني حماد بن إسحاق عن أبيه قال قال يزيد حوراء كنت أجلس بالمدينة على أبواب قريش فكانت تمر بي جارية تختلف إلى الزرقاء تتعلم منها الغناء فقلت لها يوما افهمي قولي وردي جوابي وكوني عند ظني فقالت هات ما عندك فقلت بالله ما اسمك فقالت ممنعة فأطرقت طيرة من اسمها مع طمعي فيها فقلت بل باذلة أو مبذولة إن شاء الله فاسمعي مني فقالت وهي تتبسم إن كان عندك شيء فقل فقلت\n(ليهنك مني أنني لست مفشيا ... هواك إلى غيري ولو مت من كرب)\n(ولا مانحا خلقا سواك مودتي ... ولا قائلا ما عشت من حبكم حسبي)\nال فنظرت إلي طويلا ثم قالت أنشدك الله أعن فرط محبة أم اهتياج غلمة\nتكلمت فقلت لا والله ولكن عن فرط محبة فقالت\n(فوالله رب الناس لا خنتك الهوى ... ولا زلت مخصوص المحبة من قلبي)\n(فثق بي فإني قد وثقت ولا تكن ... على غير ما أظهرت لي يا أخا الحب)\nال فوالله لكأنما أضرمت في قلبي نارا فكانت تلقاني في الطريق الذي كانت تسلكه فتحدثني وأتفرج بها ثم اشتراها بعض أولاد الخلفاء فكانت تكاتبني وتلاطفني دهرا طويلا","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":39,"spl":"إنشاده شعر أبي العتاهية في حضرة المهدي — صوت من المائة المختارة"},
{"id":"b25-69","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص253","text":"(يا ليلة جمعت لنا الأحبابا ... لو شئت دام لنا النعيم وطابا)\n(بيتنا نسقاها شمولا قرقفا ... تدع الصحيح بعقله مرتابا)\n(حمراء مثل دم الغزال وتارة ... عند المزاج تخالها زريابا)\n(من كف جارية كأن بنانها ... من فضة قد قمعت عنابا)\n(وكأن يمناها إذا نقرت بها ... تلقي على الكف الشمال حسابا)\nروضه من الكامل الشعر لعكاشة العمي والغناء لعبد الرحيم الدفاف ولحنه المختار هزج بإطلاق الوتر في مجرى الوسطى","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":39,"spl":"إنشاده شعر أبي العتاهية في حضرة المهدي — صوت من المائة المختارة"},
{"id":"b25-70","bab":"الجزء 3","sec":"سبب تسميته بالعمي","page":"ج3 ص254","text":"هو عكاشة بن عبد الصمد العمي من أهل البصرة من بني العم وأصل بني العم كالمدفوع يقال إنهم نزلوا ببني تميم بالبصرة في أيام عمر بن الخطاب فأسلموا وغزوا مع المسلمين وحسن بلاؤهم فقال الناس أنتم وإن لم تكونوا من العرب إخواننا وأهلنا وأنتم الأنصار والإخوان وبنو العم فلقبوا بذلك وصاروا في جملة العرب وقال بعض الشعراء وهو كعب بن معدان يهجو بني ناجية ويشبههم ببني العم\n(وجدنا آل سامة في قريش ... كمثل العم بين بني تميم)\nيروى في سلفي تميم أخبرني عيسى بن الحسين عن حماد بن إسحاق عن أبيه قال حدثني أبو عبيدة قال لما تواقف جرير والفرزدق بالمربد للهجاء اقتتلت بنو يربوع وبنو\nمجاشع فأمدت بنو العم بني مجاشع وجاؤوهم وفي أيدهم الخشب فطردوا بني يربوع فقال جرير من هؤلاء قالوا بنو العم فقال جرير يهجوهم\n(ما للفرزدق من عز يلوذ به ... إلا بني العم في أيديهم الخشب)\n(سيروا بني العم فالأهواز داركم ... ونهر تيرى ولم تعرفكم العرب)\nعكاشة شاعر مقل من شعراء الدولة العباسية ليس ممن شهر وشاع شعره في أيدي الناس ولا ممن خدم الخلفاء ومدحهم","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":40,"spl":"سبب تسميته بالعمي"},
{"id":"b25-71","bab":"الجزء 3","sec":"خبره مع جارية تدعى نعيم","page":"ج3 ص255","text":"أخبرني الحسن بن علي قال حدثني محمد بن القاسم بن مهرويه قال حدثني علي بن الحسن عن ابن الأعرابي قال حدثني سعيد بن حميد الكاتب البصري قال قال أبي كان عكاشة بن عبد الصمد العمي صديقا لي وإلفا وكنا نتعاشر ولا نكاد نفترق ولا يكتم أحدنا صاحبه شيئا فرأيته في بعض أيامه متغير الهيئة عما عهدته مقسم القلب والفكر غير آخذ ما كنا فيه من الفكاهة والمزاح فسألته عن حاله فكاتمنيها مليا ثم أخبرني أنه يهوى جارية لبعض الهاشميين يقال لها نعيم وأن مرامها عليه مستصعب لا يراها إلا من جناح لدارهم تشرف عليه في الفيئة بعد الفيئة فتكلمه كلاما يسيرا ثم تذهب فعاتبته على ذلك فلم يزدجر وتمادى في\nأمره ثم جاءني يوما فقال قد وعدتني الزيارة لأن شكواي إليها طالت فقلت له فهل حققت لك الوعد على يوم بعينه قال لا إنما سألتها الزيارة فقالت نعم أفعل فقلت له هذا والله أعجب من سائر ما مضى وأي شيء لك فيه هذا من الفائدة بلا تحصيل وعد فقال لي يا أخي إن لي في قولها نعم فرجا كبيرا فقلت أنت أقنع الناس ثم جاءني بعد يومين وهو كاسف البال مهموم فقلت له مالك فقال مضيت إلى نعيم فتنجزت وعدها فقالت لي إن لي صاحبة أستنصحها وأعلم أنها تشفق علي شفقة الأخت على أختها والأم على ولدها وقد نهتني عن ذلك وقالت لي إن في الرجال غدرا ومكرا ولا آمن أن تفتضحي ثم لا تحصلي منه على شيء وقد انقطعت عني ثم أنشدني لنفسه\n(علام حبل الصفاء منصرم ... وفيم عني الصدود والصمم)\n(يا من كنينا عن اسمه زمنا ... نتبع مرضاته ويجترم)\n(قد عيل صبري وأنت لاهية ... عني وقلبي عليك يضطرم)\n(من جد حبل الوفاء سيدتي ... منك ومن سامني له العدم)\n(فكم أتاني واش يعيبكم ... فقلت إخسأ لأنفك الرغم)\n(أنت الفدأ والحمى لمن عبت فارجع ... صاغرا راغما لك الندم)\nصوت\n(يا رب خذ لي من الوشاة إذا ... قاموا وقمنا إليك نختصم)\n(دبوا إليها يوسوسون لها ... كي يستزلوا حبيبتي زعموا)\n(هيهات من ذاك ضل سعيهم ... ما قلبها المستعار يقتسم)\n(يا حاسدينا موتوا بغيظكم ... حبلي متين بقولها نعم)\n(بالله لا تشمتي العداة بنا ... كوني كقلبي فلست أتهم)\nالغناء في هذه الأبيات لعريب رمل وقيل إنه لغيرها قال ثم طال ترداده إليها واستصلاحه لها فلم ألبث أن جاءتني رقعته في يوم خميس يعلمني أنها قد حصلت عنده ويستدعيني فحضرت وتوارت عني ساعة وهو يخبرها أنه لا فرق بيني وبينه ولا يحتشمني في حال البتة إلى أن خرجت فاجتمعنا وشربنا وغنت غناء حسنا إلى وقت العصر ثم انصرفت وأخذ دواة ورقعة فكتب فيها\n(سقيا لمجلسنا الذي كنا به ... يوم الخميس جماعة أترابا)\n(في غرفة مطرت سماوة سقفها ... بحيا النعيم من الكروم شرابا)\n(إذ نحن نسقاها شمولا قرقفا ... تدع الصحيح بعقله مرتابا)\n(حمراء مثل دم الغزال وتارة ... بعد المزاج تخالها زريابا)\n(من كف جارية كأن بنانها ... من فضة قد قمعت عنابا)\n(تزداد حسنا كأسها من كفها ... ويطيب منها نشرها أحقابا)\n(وإذا المزاج علا فشج جبينها ... نفثت بألسنة المزاج حبابا)\n(وتخال ما جمعت فأحدق سمطه ... بالطوق ريق حبائب ورضابا)\n(كفت المناصف أن تذب أكفها ... عنها إذا جعلت تفوح ذبابا)\n(والعود متبع غناء خريدة ... غردا يقول كما تقول صوابا)\n(وكأن يمناها إذا نطقت به ... تلقي على يدها الشمال حسابا)\n(فهناك خف بنا النعيم وصار من ... دون الثقيل لنا عليه حجابا)\n(آليت لا ألحى على طلب الهوى ... متلذدا حتى أكون ترابا)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":41,"spl":"خبره مع جارية تدعى نعيم"},
{"id":"b25-72","bab":"الجزء 3","sec":"شعره في نعيم بعد تزويجها وسفرها","page":"ج3 ص258","text":"قال ثم قدم قادم من أهل بغداد فاشترى نعيم هذه من مولاتها ورحل إلى بغداد فعظم أسف عكاشة وحزنه عليها واستهيم بها طول عمره فاستحالت صورته وطبعه وخلقه إلى أن فرق الدهر بيننا فكان أكثر وكده وشغله أن يقول فيها الشعر وينوح به عليها ويبكي قال حميد بن سعيد فأنشدني أبي له في ذلك\n(ألا ليت شعري هل يعودن ما مضى ... وهل راجع ما مات من صلة الحبل)\n(وهل أجلسن في مثل مجلسنا الذي ... نعمنا به يوم السعادة بالوصل)\n(عشية صبت لذة الوصل طيبها ... علينا وأفنان الجنان جنى البذل)\n(وقد دار ساقينا بكأس روية ... ترحل أحزان الكئيب مع العقل)\n(وشج شمولا بالمزاج فطيرت ... كألسنة الحيات خافت من القتل)\n(فبتنا وعين الكأس سح دموعها ... لكل فتى يهتز للمجد كالنصل)\n(وقينتنا كالظبي تسمح بالهوى ... وبث تباريح الفؤاد على رسل)\n(إذا ما حكت بالعود رجع لسانها ... رأيت لسان العود من كفها يملي)\n(فلم أر كاللذات أمطرت الهوى ... ولا مثل يومي ذاك صادفه مثلي)\nومما قاله فيها\n(أنعيم حبك سلني وبلاني ... وإلى الأمر من الأمور دعاني)\n(أنعيم لو تجدين وجدي والذي ... ألقى بكيت من الذي أبكاني)\n(أنعيم سيدتي عليك تقطعت ... نفسي من الحسرات والأحزان)\n(أنعيم قد رحم الهوى قلبي وقد ... بكت الثياب أسى على جثماني)\n(أنعيم وانحدرت مدامع مقلتي ... حتى رحمت لرحمتي إخواني)\n(أنعيم مثلك الهيام لمقلتي ... فكأنني ألقاك كل مكان)\n(أنعيم نظرة سحر عينك بالهوى ... معروفة بالقتل في إنسان)\n(أنعيم اشفي أو دعي من داؤه ... ودواؤه بيديك مقترنان)\n(هذا وكم من مجلس لي مؤنف ... بين النعيم وبين عيش داني)\n(نازعته أردانه فلبستها ... مع ظبية في عيشنا الفينان)\n(تنسي الحليم من الرجال معاده ... بين الغناء وعودها الحنان)\n(حتى يعود كأن حبة قلبه ... مشدودة بمثالب ومثاني)\n(ظلت تغنيني وتعطف كفها ... بالعود بين الراح والريحان)\n(فسمعت ما أبكى وأضحك سامعا ... وسكرت من طرب ومن أشجان)\n(ومشيت في لجج الهوى متبخترا ... ومشى إلي اللهو في الألوان)\n(فعلمت أن قد عاد قلبي عائد ... من بين عود مطرب وبنان)\nومما قاله أيضا فيها\n(نعيم هل بكيت كما بكيت ... وهل بعدي وفيت كما وفيت)\n(ألا يا ليت شعري كيف بعدي اصطبارك ... إذ نأيت وإذ نأيت)\n(فكم من عبرة ذرفت فلما ... خشيت عيون أهلي واستحيت)\n(نهضت بها مكاتمة فلما ... خلوت ذرفتها حتى اشتفيت)\n(وقلت لصحبتي لما رماني ... هواك بدائه حتى انطويت)\n(أراني من هموم النفس ميتا ... ولم أر في نعيم ما نويت)\n(فليت الموت عجل قبض روحي ... جهارا فاسترحت وأين ليت)\nقال أيضا في فراقه إياها\n(أنعيم في قلبي عليك شرار ... وعلى الفؤاد من الصبابة نار)\n(وعلى الجفون غشاوة وعلى الهوى ... داع دعته لحينى الأقدار)\n(بمضلة لب الحليم إذا رمت ... بالمقلتين كأنها سحار)\n(طالبتها حولين لا ليلي بها ... ليل ولا هذا النهار نهار)\n(حتى إذا ظفرت يداي بكاعب ... كالشمس تقصر دونها الأبصار)\n(وثلجت صدرا بالفتاة وصارتا ... كالنفس نفسانا وقر قرار)\n(بلغ الشقاء أشد ما يسطيعه ... فينا وفرق بيننا المقدار)\nمما يغنى فيه من شعر عكاشة الذي قاله في هذه الجارية\nصوت\n(لهفي على الزمن الذي ... ولى ببهجته القصير)\n(قد كان يؤنقني الهوى ... ويقر عيني بالسرور)\n(إذ نحن خلان الهوى ... ريحاننا عبق العبير)\n(وغناؤنا وصف الهوى ... نلتذ بالحب اليسير)\nلغناء في هذه الأبيات لابن صغير العين من كتاب إبراهيم ولم يذكر طريقته وفيه لأبي العبيس بن حمدون خفيف رمل وتمام هذه الأبيات\n(وجه التواصل بيننا ... في الحسن كالقمر المنير)\n(إيماؤنا يحكي الكلام ... وسرنا فطن المشير)\n(وحديثنا بحواجب ... نطقت بألسنة الضمير)\n(بل رسلنا الكتب التي ... تجري بخافية الصدور)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":42,"spl":"شعره في نعيم بعد تزويجها وسفرها"},
{"id":"b25-73","bab":"الجزء 3","sec":"المهدي أراد له الحد بعد أن أنشده شعرا في الخمر","page":"ج3 ص261","text":"حدثني الحسن بن عليل قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو مسلم عن المدائني قال\nأنشد عكاشة بن عبد الصمد المهدي قوله في الخمر\n(حمراء مثل دم الغزال وتارة ... عند المزاج تخالها زريابا)\nقال له المهدي لقد أحسنت في وصفها إحسان من قد شربها ولقد استحققت بذلك الحد فقال أيؤمنني أمير المؤمنين حتى أتكلم بحجتي قال قد أمنتك\nقال وما يدريك يا أمير المؤمنين أني أحسنت وأجدت صفتها إن كنت لا تعرفها فقال له المهدي اعزب قبحك الله قال الحسن وأخبرني بهذا الخبر أحمد بن سعيد الدمشقي قال حدثنا الزبير ابن بكار أن عكاشة أنشد موسى الهادي هذا الشعر ثم أنشده قوله\n(كأن فضول الكأس من زبداتها ... خلاخل شدت بالجمان إلى حجل)\nقال له موسى والله لأجلدنك حد الخمر قال ولم يا أمير المؤمنين إنما نقول ولا نفعل فقال كذبت قد وصفتها صفة عالم بها قال فاجعل لي الأمان حتى أتكلم بحجتي قال تكلم وأنت آمن قال أجدت وصفها أم لم أجد قال بل قد أجدت قال وما يدريك أني أجدت إن كنت لا تعرفها إن كنت وصفتها بطبعي دون امتحاني فقد شركتني في ذلك بطبعك وإن كان وصفها لا يعلم إلا بالتجربة فقد شركتني أيضا فيها فضحك موسى وقال له قد نجوت بحيلتك مني قاتلك الله فما أدهاك","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":43,"spl":"المهدي أراد له الحد بعد أن أنشده شعرا في الخمر — الخلاف في اسم أبيه"},
{"id":"b25-74","bab":"الجزء 3","sec":"متفرقات من شعره","page":"ج3 ص262","text":"ومما وجدت فيه غناء من شعر عكاشة قوله\n(وجاءوا إليه بالتعاويذ والرقى ... وصبوا عليه الماء من شدة النكس)\n(وقالوا به من أعين الجن نظرة ... ولو صدقوا قالوا به أعين الإنس)\nلغناء لعريب ومنها\n(طرفي يذوب وماء طرفك جامد ... وعلي من سيما هواك شواهد)\n(هذا هواك قسمته بين الورى ... ومنحتني أرقا وطرفك راقد)\n(فعلي منه اليوم تسعة أسهم ... وعلى جميع الناس سهم واحد)\nلغناء لجحظة ومنها\n(غاد الهوى بالكأس بردا ... وأطع إمارة من تبدى)\nومنها\n(كما اشتهت خلقت حتى إذا اعتدلت ... تمت قواما فلا طول ولا قصر)\nمنها\n(وزعفرانية في اللون تحسبها ... إذا تأملتها في جسم كافور)\n(تخال أن سقيط الطل بينهما ... دمع تحير في أجفان مهجور)","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":43,"spl":"المهدي أراد له الحد بعد أن أنشده شعرا في الخمر — الخلاف في اسم أبيه"},
{"id":"b25-75","bab":"الجزء 3","sec":"الخلاف في اسم أبيه","page":"ج3 ص264","text":"عبد الرحيم بن الفضل الكوفي ويكنى أبا القاسم وقيل هو عبد الرحيم ابن سعد وقيل عبد الرحيم بن الهيثم بن سعد مولى لآل الأشعث بن قيس وقيل بل هو مولى خزاعة ذكر أبو أيوب المديني أن حمادا الراوية حدثه قال رأيت عبد الرحيم الدفاف أيام هارون الرشيد بالرقة وقد ظهرت فحضرني وسمعته يغني يومئذ صوتا سئل عنه فذكر أنه من صنعته وهو\n(فديتك لو تدرين كيف أحبكم ... وكيف إذا ما غبت عنك أقول)\nوكان عبد الرحيم منقطعا إلى علي بن المهدي المعروف بأمه ريطة بنت أبي العباس فأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال حدثني عبد الصمد بن المعذل قال غنت جارية يوما بحضرة الرشيد\n(قل لعلي أيا فتى العرب ... وخير أنام وخير مكتسب)\n(أعلاك جداك يا علي إذا ... قصر جد عن ذروة الحسب)\nأمر بضرب عنقها فقالت يا سيدي ما ذنبي هذا صوت علمته والله ما أدري من قاله ولا فيمن قيل فعلم أنها صدقت فقال لها عمن أخذته فقالت عن عبد الرحيم الدفاف فأمر بإحضاره فأحضر فقال له يا عاض بظر أمه أتغني في شعر تفاخر فيه بيني وبين أخي جردوه فجردوه ودعا له بالسياط فضرب بين يديه خمسمائة سوط أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد عن القطراني عن محمد بن جبر قال قال لي عبد الرحيم بن القاسم الدفاف دخلت على علي بن ريطة يوما وستارته منصوبة فغنت جاريته\n(أناس أمناهم فنموا حديثنا ... فلما كتمنا السر عنهم تقولوا)\nقلت أرأيت إن غنيتك هذا الصوت وفي تمامه زيادة بيت واحد أي شيء لي عليك قال خلعتي التي علي فغنيته\n(فلم يحفظوا الود الذي كان بيننا ... ولا حين هموا بالقطيعة أجملوا)\nال فنزع خلعته فخلعها علي وأقمت عنده بقية يومي على عربدة كانت فيه الشعر لعباس بن الأحنف والغناء لعبد الرحيم الدفاف هزج بالبنصر وهذا أخذه العباس من قول أبي دهبل صوت\n(أمنا أناسا كنت تأتمنينهم ... فزادوا علينا في الحديث وأوهموا)\n(وقالوا لها مالم نقل ثم أكثروا ... علي وباحوا بالذي كنت أكتم)\n(وفي هذين البيتين أغاني قديمة منها لحن لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق ... )\n(ولابن زرزور الطائفي خفيف ثقيل بالوسطى عن عمرو ... )\n(وفيه خفيف رمل بالبنصر والوسطى لمتيم وعريب ... )","topic":"أخبار بشار بن برد ونسبه","topicNo":25,"sp":43,"spl":"المهدي أراد له الحد بعد أن أنشده شعرا في الخمر — الخلاف في اسم أبيه","partial":1},
{"id":"b26-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص266","text":"(بكرت سمية غدوة فتمتعي ... وغدت غدو مفارق لم يربع)\n(وتعرضت لك فاستبتك بواضح ... صلت كمنتص الغزال الأتلع)\nروضه من الكامل والشعر للحادرة الثعلبي والغناء في اللحن المختار لسعيد بن مسجح وإيقاعه من خفيف الثقيل الأول بإطلاق الوتر في مجرى\nالبنصر عن إسحاق وذكر عمرو بن بانة أنه لابن محرز وفيهما للغريض ثقيل أول بالبنصر عن عمرو وفيهما خفيف رمل بالوسطى لابن سريج عن حبش ومما يغنى فيه من هذه القصيدة\n(أسمي ما يدريك كم من فتية ... بادرت لذتهم بأدكن مترع)\n(بكروا علي بسحرة فصبحتهم ... من عاتق كدم الذبيح مشعشع)\nناه مالك ولحنه من الثقيل الأول بالبنصر عن عمرو وفيه لمالك خفيف ثقيل أيضا وفيهما لعلويه ثقيل أول صحيح من جيد صنعته قوله فتمتعي يخاطب نفسه أي تمتعي منها قبل فراقها ولم يربع لم يقم والواضح الصلت يعني عنقها وأصل الصلت الماضي ومنه الناقة المصلات الماضية وشد عليه بالسيف صلتا أي خارجا من غمده والصلت في هذا الشعر الطويل الذي لا قصر فيه والمنتص المنتصب يقال انتص فلان أي انتصب ومنصة العروس مأخوذة من هذا ومنه نص الحديث رفعه إلى صاحبه واستبتك غلبتك على عقلك والواضح الخالص الأبيض وأدكن مترع يعني الزق والمشعشع المرقرق بالماء","topic":"أخبار الحادرة ونسبه","topicNo":26,"sp":0,"spl":"صوت من المائة المختارة — سبب الهجاء بينه وبين زبان بن سيار"},
{"id":"b26-2","bab":"الجزء 3","sec":"أخبار الحادرة ونسبه","page":"ج3 ص268","text":"أخبرني بنسبه هذا محمد بن العباس اليزيدي عن عبد الرحمن بن عبد الله بن قريب ابن أخي الأصمعي عن عمه قال وإنما سمي الحادرة بقول زبان بن سيار الفزاري له\n(كأنك حادرة المنكبين ... رصعاء تنقض في حائر)\n(عجوز ضفادع محجوبة ... يطيف بها ولدة الحاضر)\nال والحادرة الضخم وذكر أبو عمرو الشيباني أن الحادرة خرج هو وزبان الفزاري يصطادان فاصطادا جميعا فخرج زبان يشتوي ويأكل في الليل وحده فقال الحادرة\n(تركت رفيق رحلك قد تراه ... وأنت لفيك في الظلماء هادي)\nحقدها عليه زبان ثم أتيا غديرا فتجرد الحادرة وكان ضخم المنكبين\nارسح فقال زبان\n(كأنك حادرة المنكبين ... رصعاء تنقض في حائر)\nقال له الحادرة\n(لحا الله زبان من شاعر ... أخي خنعة فاجر غادر)\n(كأنك فقاحة نورت ... مع الصبح في طرف الحائر)\nغلب هذا اللقب على الحادرة حدثني محمد بن العباس اليزيدي قال حدثنا عبد الرحمن ابن أخي الأصمعي قال حدثني عمي قال سمعت شيخا من بني كنانة من أهل المدينة يقول كان حسان بن ثابت إذا قيل له تنوشدت الأشعار في موضع كذا وكذا يقول فهل أنشدت كلمة الحويدرة\n(بكرت سمية غدوة فتمتعي ... )\nال أبو عبيدة وهي من مختار الشعر أصمعية مفضلية","topic":"أخبار الحادرة ونسبه","topicNo":26,"sp":0,"spl":"صوت من المائة المختارة — سبب الهجاء بينه وبين زبان بن سيار","partialRef":{"sid":"b26-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b26-3","bab":"الجزء 3","sec":"سبب الهجاء بينه وبين زبان بن سيار","page":"ج3 ص269","text":"نسخت من كتاب ابن الأعرابي قال حدثني المفضل قال كان الحادرة جارا لرجل من بني سليم فأغار زبان بن سيار على إبله فأخذها فدفعها إلى رجل من أهل وادي القرى يهودي ومكان له عليه دين فأعطاه إياها بدينه وكان أهل وادي القرى حلفاء لبني ثعلبة فلما سمع اليهودي بذلك قال سيجعل الحادرة هذا سببا لنقض العهد الذي بيننا وبينه ونحن نقرأ الكتاب ولا ينبغي لنا أن\nنغدر فرد الإبل على الحادرة فردها على جاره ورجع إلى زبان فقال له أعطني مالي الذي عليك فأعطاه إياه زبان ووقع الهجاء بينه وبين الحادرة فقال الحادرة فيه\n(لعمرة بين الأخرمين طلول ... تقادم منها مشهر ومحيل)\n(وقفت بها حتى تعالى لي الضحى ... لأخبر عنها إنني لسئول)\nيقول فيها\n(فإن تحسبوها بالحجاب ذليلة ... فما أنا يوما إن ركبت ذليل)\n(سأمنعها في عصبة ثعلبية ... لهم عدد واف وعز أصيل)\n(فإن شئتم عدنا صديقا وعدتم ... وإما أبيتم فالمقام زحول)\nال ولج الهجاء بينهما بعد ذلك فكان هذا سببه","topic":"أخبار الحادرة ونسبه","topicNo":26,"sp":0,"spl":"صوت من المائة المختارة — سبب الهجاء بينه وبين زبان بن سيار"},
{"id":"b26-4","bab":"الجزء 3","sec":"شعره في غزوة بني عامر","page":"ج3 ص270","text":"ونسخت من كتاب عمرو بن أبي عمرو الشيباني يذكر عن أبيه أن جيشا لبني عامر بن صعصعة أقبل وعليهم ثلاثة رؤساء ذؤاب بن غالب من عقيل ثم من بني كعب بن ربيعة وعبد الله بن عمرو من بني الصموت وعقيل بن مالك من بني نمير وهم يريدون غزو بني ثعلبة بن سعد رهط الحادرة ومن معهم من محارب وكانوا يومئذ معهم فنذرت بهم بنو ثعلبة فركب قيس بن مالك المحاربي الخصفي وجؤية بن نصر الجرمي أحد بني ثعلبة للنظر إلى القوم فما دنوا منهم عرف عقيل بن مالك النميري جؤية بن نصر الجريم فناداه إلي يا جؤية بن نصر فإن لي خبرا أسره إليك فقال إليك أقبلت لكن لغير ما\nظننت فقال له ما فعلت قلوص يعني إمرأته فقال هي في الظعن أسر ما كانت قط وأجمله ثم حمل كل واحد منهما على صاحبه واختلفا طعنتين فطعنه جؤية طعنة دقت صلبه وانطلق قيس بن مالك المحاربي إلى بني ثعلبة فأنذرهم فاقتتلوا قتالا شديدا فهزمت بنو نمير وسائر بني عامر ومات عقيل النميري وقتل ذؤاب بن غالب وعبد الله بن عمرو أحد بني الصموت فقال الحادرة في ذلك\n(كأن عقيلا في الضحى حلقت به ... وطارت به في الجو عنقاء مغرب)\nيروي وطارت به في اللوح وهو الهواء\n(وذي كرم يدعوكم آل عامر ... لدى معرك سرباله يتصبب)\n(رأت عامر وقع السيوف فأسلموا ... أخاهم ولم يعطف من الخيل مرهب)\n(وسلم لما أن رأى الموت عامر ... له مركب فوق الأسنة أحدب)\n(إذا ما أظلته عوالي رماحنا ... تدلى به نهد الجزارة منهب)\n(على صلويه مرهفات كأنها ... قوادم نسر بز عنهن منكب)\nال وفي هذه الوقعة يقول خداش بن زهير\n(أيا أخوينا من أبينا وأمنا ... إليكم إليكم لا سبيل إلى جسر)\nسر قبيلة من محارب قال وهذا اليوم يعرف بيوم شواحط قبيلة من محارب","topic":"أخبار الحادرة ونسبه","topicNo":26,"sp":1,"spl":"شعره في غزوة بني عامر — شعره في يوم الكفافة"},
{"id":"b26-5","bab":"الجزء 3","sec":"شعره في يوم الكفافة","page":"ج3 ص272","text":"وقال أبو عمرو خرج خارجة بن حصن في جمع من بني فزارة ومن بني ثعلبة بن سعد وهو يريد غزو بني عبس بن بغيض فلقوا جيشا لبني تميم على ماء يقال له الكفافة وتميم في جمع سعد والرباب وبني عمرو فقاتلوهم قتالا شديدا وهزمت تميم وأجفلت وهذا اليوم يقال له يوم كفافة فقال الحادرة في ذلك\n(ونحن منعنا من تميم وقد طغت ... مراعي الملا حتى تضمنها نجد)\n(كمعطفنا يوم الكفافة خيلنا ... لتتبع أخرى الجيش إذ بلغ الجد)\n(على حين شالت واستخفت رجالهم ... جلائب أحياء يسيل بها الشد)\n(إذا هي شك السمهري نحورها ... وخامت عن الأبطال أتعبها القد)\n(تكر سراعا في المضيق عليهم ... وتثنى بطاء ما تخب ولا تعدو)\n(فأثنوا علينا لا أبا لأبيكم ... بإحساننا إن الثناء هو الخلد)","topic":"أخبار الحادرة ونسبه","topicNo":26,"sp":1,"spl":"شعره في غزوة بني عامر — شعره في يوم الكفافة"},
{"id":"b27-1","bab":"الجزء 3","sec":"أخبار ابن مسجح ونسبه","page":"ج3 ص273","text":"سعيد بن مسجح أبو عثمان مولى بني جمح وقيل إنه مولى بني نوفل بن الحارث بن عبد المطلب مكي أسود مغن متقدم من فحول المغنين وأكابرهم وأول من صنع الغناء منهم ونقل غناء الفرس إلى غناء العرب ثم رحل إلى الشأم وأخذ ألحان الروم والبربطية والأسطوخوسية وانقلب إلى فارس فأخذ بها غناء كثيرا وتعلم الضرب ثم قدم إلى الحجاز وقد أخذ محاسن تلك النغم وألقى منها ما استقبحه من النبرات والنغم التي هي موجودة في نغم غناء الفرس والروم خارجة عن غناء العرب وغنى على هذا المذهب فكان أول من أثبت ذلك ولحنه وتبعه الناس بعد أخبرني محمد بن خلف بن المرزبان والحسين بن يحيى قالا حدثنا حماد بن إسحاق عن أبيه عن هشام بن المرية أن أول من غنى هذا الغناء العربي بمكة ابن مسجح مولى بني مخزوم وذلك أنه مر بالفرس وهم يبنون المسجد الحرام فسمع غناءهم بالفارسية فقلبه في شعر عربي وهو الذي علم ابن سريج والغريض وكان ابن مسجح مولدا أسود يكنى بأبي عيسى أخبرني محمد بن عبيد الله بن محمد الرازي قال حدثنا أحمد بن الحارث الخراز عن المدائني وذكر إسحاق عن المدائني عن أبي بكر الهذلي قال كان سبب بناء ابن الزبير الكعبة لما احترقت أن أهل الشام لما حاصروه\nسمع أصواتا بالليل فوق الجبل فخاف أن يكون أهل الشام قد وصلوا إليه وكانت ليلة ظلماء ذات ريح شديدة صعبة ورعد وبرق فرفع نارا على رأس رمح لينظر إلى الناس فأطارتها الريح فوقعت على أستار الكعبة فأحرقتها واستطالت فيها وجهد الناس في إطفائها فلم يقدروا وأصبحت الكعبة تتهافت وماتت امرأة من قريش فخرج الناس كلهم في جنازتها خوفا من أن ينزل العذاب عليهم وأصبح ابن الزبير ساجدا يدعو ويقول اللهم إني لم أتعمد ما جرى فلا تهلك عبادك بذنبي وهذه ناصيتي بين يديك فلما تعالى النهار أمن وتراجع الناس فقال لهم الله الله أن ينهدم في بيت أحدكم حجر فيزول عن موضعه فيبنيه ويصلحه وأترك الكعبة خرابا ثم هدمها مبتدئا بيده وتبعه الفعلة حتى بلغوا إلى قواعدها ودعا ببنائين من الفرس والروم فبناها","topic":"أخبار ابن مسجح ونسبه","topicNo":27,"sp":0,"spl":"أخبار ابن مسجح ونسبه — نقل غناء الفرس من بنائي الكعبة الذين أعادوا بناءها"},
{"id":"b27-2","bab":"الجزء 3","sec":"نقل غناء الفرس من بنائي الكعبة الذين أعادوا بناءها","page":"ج3 ص274","text":"قال إسحاق وأخبرني ابن الكلبي عن أبي مسكين قال\nكان سعيد بن مسجح أسود مولدا يكنى أبا عيسى مولى لبني جمح فرأى الفرس وهم يعملون الكعبة لابن الزبير ويتغنون بالفارسية فاشتق غناءه على ذلك\nقال إسحاق وحدثني محمد بن سلام عن شعيب بن صخر وجرير قالا\nكان سعيد بن مسجح أسود وهو مولى بني جمح يكنى أبا عيسى\nقال إسحاق وحدثني المدائني عن صخر بن جعفر عن أبي قبيل بمثل\nذلك وذكر أنه كان يكنى أبا عثمان قال وهو مولى لبني نوفل بن الحارث كان هو وابن سريج لرجل واحد ولذلك قبل عنه ابن سريج","topic":"أخبار ابن مسجح ونسبه","topicNo":27,"sp":0,"spl":"أخبار ابن مسجح ونسبه — نقل غناء الفرس من بنائي الكعبة الذين أعادوا بناءها"},
{"id":"b27-3","bab":"الجزء 3","sec":"ظهرت عليه علامات الذكاء منذ صغره","page":"ج3 ص275","text":"قال إسحاق وحدثني الهيثم بن عدي عن صالح بن حسان فذكر مثل ما ذكر أبو قبيل من كنيته وولائه وقال كان ابن مسجح فطنا كيسا ذكيا وكان أصفر حسن اللون وكان مولاه معجبا به وكان يقول في صغره ليكونن لهذا الغلام شأن وما منعني من عتقه إلا حسن فراستي فيه ولئن عشت لأتعرفن ذلك وإن مت فهو حر فسمعه مولاه يوما وهو يتغنى بشعر ابن الرقاع العاملي وهو من الثقيل الأول بالسبابة في مجرى الوسطى صوت\n(ألمم على طلل عفا متقادم ... بين اللكيك وبين غيب الناعم)\n(لولا الحياء وأن رأسي قد عثا ... فيه المشيب لزرت أم القاسم)\nدعا به مولاه فقال له يا بني أعد ما سمعته منك علي فأعاده فإذا هو أحسن مما\nابتدأ به فقال إن هذا لمن بعض ما كنت أقول ثم قال أنى لك هذا قال سمعت هذه الأعاجم تتغنى بالفارسية فثقفتها وقلبتها في هذا الشعر قال له فأنت حر لوجه الله فلزم مولاه وكثر أدبه واتسع في غنائه ومهر بمكة وأعجبوا به لظرفه وحسن ما سمعوه منه فدفع إليه مولاه عبيد بن سريج وقال له يا بني علمه واجتهد فيه وكان ابن سريج أحسن الناس صوتا فتعلم منه ثم برز عليه حتى لم يعرف له نظير أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا أخي هارون عن ابن الماجشون عن شيخ من أهل المدينة وأخبرني محمد بن خلف بن المرزبان والحسين بن يحيى قالا أخبرنا حماد بن إسحاق عن أبيه قال ذكر ابن الكلبي عن أبي مسكين عن شيخ من أهل المدينة قال دخلت على رجل من قريش بالمدينة وعنده رجل ساكن الطرف نبيل تأخذه العين لا أعرفه فقال له القرشي أقسمت عليك إلا ما غنيت صوتا فحول خاتمه من خنصره اليسرى إلى بنصره اليمنى ثم تناول قدحا فغناه لحن ابن سريج في شعر كعب بن جعيل\n(إذا امتشطت عالوا لها بوسادة ... ومدت عسيب المتن أن يتعفرا)\n(ثوت نصف شهر تحسب الشهر ليلة ... تناغي غزالا ساجي الطرف أحورا)\n(تزين حتى تسلب المرء عقله ... وحتى يحار الطرف فيها ويسكرا)\nم غنى في شعر توبة بن الحمير\n(وغيرني إن كنت لما تغيري ... هواجر تكتنينها وأسيرها)\n(وأدماء من سر المهارى كأنها ... مهاة صوار غير ما مس كورها)\n(قطعت بها أجواز كل تنوفة ... مخوف رداها كلما استن مورها)\n(ترى ضعفاء القوم فيها كأنهم ... دعاميص ماء نش عنها غديرها)\nال فقلت له إني لأروي هذا الشعر وما أعرف هذه الأبيات فيه فقال هكذا رويتها عن عبد الله بن جعفر قال وإذا هو نافع الخير مولى عبد الله بن جعفر الغناء في هذين اللحنين لابن مسجح ولم أجد لهما طريقة في شيء من الكتب التي مرت وذكر حبش أن في أبيات كعب بن جعيل لإبراهيم خفيف رمل بالوسطى","topic":"أخبار ابن مسجح ونسبه","topicNo":27,"sp":1,"spl":"ظهرت عليه علامات الذكاء منذ صغره — خبر آخر عن نقله غناء الفرس"},
{"id":"b27-4","bab":"الجزء 3","sec":"خبر آخر عن نقله غناء الفرس","page":"ج3 ص278","text":"حدثني جعفر بن قدامة بن زياد الكاتب وعمي وحبيب بن نصر المهلبي قالوا حدثنا عبد الله بن أبي سعد قال حدثني عبد الله بن محمد بن موسى الهاشمي قال حدثني أحمد بن موسى بن حمزة بن عمارة بن صفوان الجمحي عن أبيه قال أول من نقل الغناء الفارسي من الفارسي إلى الغناء العربي سعيد بن مسجح مولى بني مخزوم قال وقد يختلف في ولائه إلا أن الأغلب عليه ولاء بني مخزوم وذلك أن معاوية بن أبي سفيان لما بنى دوره التي يقال لها الرقط وهي ما بين الدارين إلى الردم أولها الدار البيضاء وآخرها دار الحمام وهي على يسار المصعد من المسجد إلى ردم عمر حمل لها بنائين فرسا من العراق فكانوا يبنونها بالجص والآجر وكان سعيد بن مسجح يأتيهم فيسمع من غنائهم على بنيانهم فما استحسن من ألحانهم أخذه ونقله إلى الشعر العربي ثم صاغ على نحو ذلك وهو الذي علم الغريض فكان من قديم غنائه الذي صنعه على تلك الأغاني صوت\n(أسلام إنك قد ملكت فأسجحي ... قد يملك الحر الكريم فيسجح)\n(مني على عان أطلت عناءه ... في الغل عندك والعناة تسرح)\n(إني لأنصحكم وأعلم أنه ... سيان عندك من يغش وينصح)\n(وإذا شكوت إلى سلامة حبها ... قالت أجد منك ذا أم تمزح)\nلشعر للأحوص والغناء لابن مسجح ثقيل أول بالبنصر ولدحمان فيه ثقيل أول بالبنصر ولمالك فيه خفيف ثقيل عن الهشامي قال وهو أول من غنى الغناء العربي المنقول عن الفارسي وعاش سعيد بن مسجح حتى لقيه معبد وأخذ عنه في أيام الوليد بن عبد الملك","topic":"أخبار ابن مسجح ونسبه","topicNo":27,"sp":1,"spl":"ظهرت عليه علامات الذكاء منذ صغره — خبر آخر عن نقله غناء الفرس"}]);
window.__BOOK__['p02'].push([{"id":"b27-5","bab":"الجزء 3","sec":"خبره مع عبد الملك بن مروان","page":"ج3 ص279","text":"حدثني عمي والحسين بن القاسم الكوفي قالا جميعا حدثنا محمد بن سعيد الكراني قال حدثني النضر بن عمرو قال حدثني أبو أمية القرشي قال حدثنا دحمان الأشقر قال كنت عاملا لعبد الملك بن مروان بمكة فنمي إليه أن رجلا أسود يقال له سعيد بن مسجح أفسد فتيان قريش وأنفقوا عليه أموالهم فكتب إلي أن اقبض ماله وسيره ففعلت فتوجه ابن مسجح إلى الشام فصحبه رجل له جوار مغنيات في طريقه فقال له أين تريد فأخبره خبره وقال له أريد الشام قال له فتكون معي قال نعم فصحبه حتى بلغا دمشق فدخلا مسجدها فسألا من أخص الناس بأمير المؤمنين فقالوا هؤلاء النفر من قريش وبنو عمه فوقف ابن مسجح عليهم وسلم ثم قال يا فتيان هل فيكم من يضيف رجلا غريبا من أهل الحجاز فنظر بعضهم إلى بعض وكان عليهم موعد أن يذهبوا إلى قينة يقال لها برق الأفق فتثاقلوا به إلا فتى منهم تذمم فقال أنا أضيفك وقال لأصحابه\nانطلقوا أنتم وأنا أذهب مع ضيفي قالوا لا بل تجيء أنت وضيفك فذهبوا جميعا إلى بيت القينة فلما أتوا بالغداء قال لهم سعيد إني رجل أسود ولعل فيكم من يقذرني فأنا أجلس وآكل ناحية وقام فاسحيوا منه وبعثوا إليه بما أكل فلما صاروا إلى الشراب قال لهم مثل ذلك ففعلوا به وأخرجوا جاريتين فجلستا على سرير قد وضع لهما فغنتا إلى العشاء ثم دخلتا وخرجت جارية حسنة الوجه والهيئة وهما معها فجلست على السرير وجلستا أسفل منها عن يمين السرير وشماله قال ابن مسجح فتمثلت هذا البيت\n(فقلت أشمس أم مصابيح بيعة ... بدت لك خلف السجف أم أنت حالم)\nغضبت الجارية وقالت أيضرب هذا الأسود بي الأمثال فنظروا إلي نظرا منكرا ولم يزالوا يسكنونها ثم غنت صوتا فقال ابن مسجح أحسنت والله فغضب مولاها وقال أمثل هذا الأسود يقدم على جاريتي فقال لي الرجل الذي أنزلني عنده قم فانصرف إلى منزلي فقد ثقلت على القوم فذهبت أقوم فتذمم القوم وقالوا لي بل أقم وأحسن أدبك فأقمت وغنت فقلت أخطأت والله يا زانية وأسأت ثم اندفعت فغنيت الصوت فوثبت الجارية فقالت لمولاها هذا والله أبو عثمان سعيد بن مسجح فقلت إني والله أنا هو والله لا أقيم عندكم فوثب القرشيون فقال هذا يكون عندي وقال هذا يكون عندي وقال هذا بل عندي فقلت والله لا أقيم إلا عند سيدكم يعني الرجل الذي أنزله منهم ثم سألوه عما أقدمه فأخبرهم الخبر فقال له صاحبه إني أسمر الليلة مع أمير المؤمنين فهل تحسن أن تحدو قال لا ولكني أستعمل حداء قال فإن منزلي بحذاء منزل أمير المؤمنين فإن وافقت منه طيب نفس أرسلت إليك ومضى إلى عبد الملك فلما رآه طيب النفس أرسل إلى ابن مسجح وأخرج رأسه من وراء شرف القصر ثم حدا\n(إنك يا معاذ يابن الفضل ... إن زلزل الأقدام لم تزلزل)\n(عن دين موسى والكتاب المنزل ... تقيم أصداغ القرون الميل)\n(للحق حتى ينتحوا للأعدل ... )\nقال عبد الملك للقرشي من هذا قال رجل حجازي قدم علي قال أحضره فأحضره له وقال له أحد مجدا ثم قال له هل تغني غناء الركبان قال نعم قال غنه فتغنى فقال له فهل تغني الغناء المتقن قال نعم قال غنه فتغنى فاهتز عبد الملك طربا ثم قال له أقسم إن لك في القوم لأسماء كثيرة من أنت ويلك قال له أنا المظلوم المقبوض ماله المسير عن وطنه سعيد بن مسجح قبض مالي عامل الحجاز ونفاني فتبسم عبد الملك ثم قال له قد وضح عذر فتيان قريش في أن ينفقوا عليك أموالهم وأمنه ووصله وكتب إلى عامله برد ماله عليه وألا يعرض له بسوء","topic":"أخبار ابن مسجح ونسبه","topicNo":27,"sp":2,"spl":"خبره مع عبد الملك بن مروان","partial":1},
{"id":"b28-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص281","text":"(سلا دار ليلى هل تبين فتنطق ... وأنى ترد القول بيداء سملق)\n(وأنى ترد القول دار كأنها ... لطول بلاها والتقادم مهرق)\nروضه من الطويل الشعر لابن المولى وذكر يحيى بن علي بن يحيى عن إسحاق أن الشعر للأعشى وذلك غلط وقد التمسناه في شعر كل أعشى ذكر في شعراء العرب فلم نجده ولا رواه أحد من الرواة لأحد منهم ووجدناه في شعر\nابن المولى من قصيدة له طويلة جيدة وقد أثبتناها بعقب أخباره ليوقف على صحة ما ذكرناه إذ كان الغلط إذا وقع من مثل هذه الجهة احتيج إلى إيضاح الحجة على ما خالفه والدلالة على الصواب فيه والغناء في اللحن المختار لعطرد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق ويونس وعمرو وفيه لأيوب زهرة خفيف ثقيل بالوسطى عن الهشامي وأحمد بن المكي وفي غناء أيوب زهرة زيادة بيتين وهما\n(وقال خليلي والبكا لي غالب ... أقاض عليك ذا الأسى والتشوق)\n(وقد طال توقاني أكفكف عبرة ... تكاد إذا ردت لها النفس تزهق)","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":0,"spl":"صوت من المائة المختارة — مدح المهدي فاستحق عطاءه"},
{"id":"b28-2","bab":"الجزء 3","sec":"أخبار ابن المولى ونسبه","page":"ج3 ص282","text":"هو محمد بن عبد الله بن مسلم بن المولى مولى الأنصار ثم من بني عمرو بن عوف شاعر متقدم مجيد من مخضرمي الدولتين ومداحي أهلهما وقدم على المهدي وامتدحه بعدة قصائد فوصله بصلات سنية وكان ظريفا عفيفا نظيف الثياب حسن الهيئة","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":0,"spl":"صوت من المائة المختارة — مدح المهدي فاستحق عطاءه"},
{"id":"b28-3","bab":"الجزء 3","sec":"مدح المهدي فاستحق عطاءه","page":"ج3 ص283","text":"أخبرني عمي قال حدثنا محمد بن عبد الله الحزنبل قال قال لي محمد بن صالح بن النطاح كان ابن المولى يسمى محمدا مولى بني عمرو بن عوف من الأنصار وكان مسكنه بقباء وكان يقدم على المهدي فيمدحه فقدم عليه فأنشده قوله\n(سلا دار ليلى هل تبين فتنطق ... وأني ترد القول بيداء سملق)\n(وأنى ترد القول دار كأنها ... لطول بلاها والتقادم مهرق)\n(وقال خليلي والبكا لي غالب ... أقاض عليك ذا الأسى والتشوق)\n(وإنسان عيني في دوائر لجة ... من الدمع يبدو تارة ثم يغرق)\nيقول فيها\n(إلى القائم المهدي أعملت ناقتي ... بكل فلاة آلها يترقرق)\n(إذا غال منها الركب صحراء برحت ... بهم بعدها في السير صحراء دردق)\n(رميت قراها بين يوم وليلة ... بفتلاء لم ينكب لها الزور مرفق)\n(مزمرة سقبا كأن زمامها ... بحرداء من عم الصنوبر معلق)\n(موكلة بالفادحات كأنها ... وقد جعلت منها الثميلة تخلق)\n(بقي الملا هيق أمام رئاله ... أصم هجف أقرع الرأس نقنق)\n(تراها إذا استعجلتها وكأنها ... على الأين يعروها من الروع أولق)\n(موركة أرض العذيب وقد بدا ... فسر به للآئبين الخورنق)\nاستحسنها المهدي وأجزل صلته وأمر فغني في نسيب القصيدة فأما ما شرطت ذكره من تمام القصيدة فهو بعقب البيت الثاني منها\n(عفتها الرياح الرامسات مع البلى ... بأذيالها والرائح المتبعق)\n(بكل شآبيب من الماء خلفها ... شآبيب ماء مزنها متألق)\n(إذا ريق منها هريقت سجاله ... أعيد لها كرفي ماء وريق)\n(فأصبح يرمي بالرباب كأنما ... بأرجله منه نعام معلق)\n(فلا تبك أطلال الديار فإنها ... خبال لمن لا يدفع الشوق عولق)\n(وإن سفاها أن ترى متفجعا ... بأطلال دار أو يقودك معلق)\n(فلا تجزعن للبين كل جماعة ... وجدك مكتوب عليها التفرق)\n(وخذ بالتعزي كل ما أنت لابس ... جديدا على الأيام بال ومخلق)\n(فصبر الفتى عما تولى فإنه ... من الأمر أولى بالسداد وأوفق)\nيروى أدنى للذي هو أوفق\n(وإنك بالإشفاق لا تدفع الردى ... ولا الحين مجلوب فما لك تشفق)\n(كأن لم يرعك الدهر أو أنت آمن ... لأحداثه فيما يغادي ويطرق)\n(وقال خليلي والبكا لي غالب ... أقاض عليك ذا الأسى والتشوق)\n(وقد طال توقاني أكفكف عبرة ... على دمنة كادت لها النفس تزهق)\n(وإنسان عيني في دوائر لجة ... من الماء يبدو تارة ثم يغرق)\n(وللدمع من عيني شريجا صبابة ... مرش الرجا والجائل المترقرق)\n(وكنت أخا عشق ولم يك صاحبي ... فيعذرني مما يصب ويعشق)\n(وقد يعذر الصب السقيم ذوي الهوى ... ويلحى المحبين الصديق فيخرق)\n(وعاب رجال أن علقت وقد بدا ... لهم بعض ما أهوى وذو الحلم يعلق)\nالقصيدة طويلة وفي بعض ما ذكرته منها دلالة على صحة ما قلته","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":0,"spl":"صوت من المائة المختارة — مدح المهدي فاستحق عطاءه"},
{"id":"b28-4","bab":"الجزء 3","sec":"تشبيه بقوس له سماه ليلى","page":"ج3 ص286","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز قال خرجت أنا وأبو السائب المخزومي وعبيد الله بن مسلم بن جندب وابن المولى وأصبغ بن عبد العزيز بن مروان إلى قباء وابن المولى متنكب قوسا عربية فأنشد ابن المولى لنفسه\n(وأبكي فلا ليلى بكت من صبابة ... إلي ولا ليلى لذي الود تبذل)\n(وأخنع بالعتبى إذا كنت مذنبا ... وإن أذنبت كنت الذي أتنصل)\nقال له أبو السائب وعبيد الله بن مسلم بن جندب من ليلى هذه حتى نقودها إليك فقال لهما ابن المولى ما هي والله إلا قوسي هذه سميتها ليلى في هذين البيتين ثقيل أول مطلق في مجرى الوسطى لخزرج ويقال إنه لهاشم بن سليمان أخبرني عمي قال حدثنا أبو هفان قال أخبرني أبو محلم عن المفضل الضبي قال وفد ابن المولى على يزيد بن حاتم وقد مدحه بقصيدته التي يقول فيها\n(يا واحد العرب الذي ... أضحى وليس له نظير)\n(لو كان مثلك آخر ... ما كان في الدنيا فقير)\nال فدعا بخازنه وقال كم في بيت مالي فقال له من الورق والعين بقية عشرون ألف دينار فقال ادفعها إليه ثم قال يا أخي المعذرة إلى الله وإليك والله لو أن في ملكي أكثر لما احتجبتها عنك","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":1,"spl":"تشبيه بقوس له سماه ليلى — حنينه إلى المدينة"},
{"id":"b28-5","bab":"الجزء 3","sec":"يزيد بن حاتم يعوده في مرضه","page":"ج3 ص287","text":"أخبرني الحسن بن علي ومحمد بن خلف بن المرزبان قالا حدثنا أحمد بن زهير بن حرب قال حدثنا مصعب الزبيري عن عبد الملك بن الماجشون قال كان ابن المولى مداحا لجعفر بن سليمان وقثم بن العباس الهاشميين ويزيد بن حاتم بن قبيصة بن المهلب واستفرغ مدحه في يزيد وقال في قصيدته التي يقول فيها\n(يا واحد العرب الذي دانت له ... قحطان قاطبة وساد نزارا)\n(إني لأرجو إن لقيتك سالما ... ألا أعالج بعدك الأسفارا)\n(رشت الندى ولقد تكسر ريشه ... فعلا الندى فوق البلاد وطارا)\nثم قصده بها إلى مصر وأنشده إياها فأعطاه حتى رضي ومرض ابن المولى عنده مرضا طويلا وثقل حتى أشفى فلما أفاق من علته ونهض دخل عليه يزيد بن حاتم متعرفا خبره فقال لوددت والله يا أبا عبد الله ألا تعالج بعدي الأسفار حقا ثم أضعف صلته\nأخبرني الحسن قال حدثنا أحمد بن زهير قال حدثني الزبير بن بكار عن عبد الملك بن عبد العزيز قال أخبرني ابن المولى قال كنت أمدح يزيد بن حاتم من غير أن أعرفه ولا ألقاه فلما ولاه المنصور مصر أخذ على طريق المدينة فلقيته فأنشدته وقد خرج من مسجد رسول الله إلى أن صار إلى مسجد الشجرة فأعطاني رزمتي ثياب وعشرة آلاف دينار فاشتريت بها ضياعا تغل ألف دينار أقوم في أدناها وأصيح بقيمي ولا يسمعني وهو في أقصاها أخبرني عمي قال حدثنا الحزنبل عن عمرو بن أبي عمرو قال بلغني أن الحسن بن زيد دعا بابن المولى فأغلظ له وقال أتشبب بحرم المسلمين وتنشد ذلك في مسجد رسول الله وفي الأسواق والمحافل ظاهرا فحلف له بالطلاق أنه ما تعرض لمحرم قط ولا شبب بامرأة مسلم ولا معاهد قط قال فمن ليلى هذه التي تذكر في شعرك فقال له امرأتي طالق إن كانت إلا قوسي هذه سميتها ليلى لأذكرها في شعري فإن الشعر لا يحسن إلا بالتشبيب فضحك الحسن ثم قال إذا كانت القصة هذه فقل ما شئت","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":1,"spl":"تشبيه بقوس له سماه ليلى — حنينه إلى المدينة"},
{"id":"b28-6","bab":"الجزء 3","sec":"حنينه إلى المدينة","page":"ج3 ص288","text":"فقال الحزنبل وحدثت عن ابن عائشة محمد بن يحيى قال قدم ابن المولى إلى العراق في بعض سنيه فأخفق وطال مقامه وغرض به وتشوق إلى المدينة فقال في ذلك\nصوت\n(ذهب الرجال فلا أحس رجالا ... وأرى الإقامة بالعراق ضلالا)\n(وطربت إذ ذكر المدينة ذاكر ... يوم الخميس فهاج لي بلبالا)\n(فظللت أنظر في السماء كأنني ... أبغي بناحية السماء هلالا)\n(طربا إلى أهل الحجاز وتارة ... أبكي بدمع مسبل إسبالا)\nغنى في هذه الأربعة الأبيات ابن عائشة ولحنه ثاني ثقيل عن الهشامي وذكره حماد عن أبيه في أخباره ولم يذكر طريقته\n(فيقال قد أضحى يحدث نفسه ... والعين تذرف في الرداء سجالا)\n(إن الغريب إذا تذكر أوشكت ... منه المدامع أن تفيض علالا)\n(ولقد أقول لصاحبي وكأنه ... مما يعالج ضمن الأغلالا)\n(خفض عليك فما يرد بك تلقه ... لا تكثرن وإن جزعت مقالا)\n(قد كنت إذ تدع المدينة كالذي ... ترك البحار ويمم الأوشالا)\n(فأجابني خاطر بنفسك لا تكن ... أبدا تعد مع العيال عيالا)\n(واعلم بأنك لن تنال جسيمة ... حتى تجشم نفسك الأهوالا)\n(إني وجدك يوم أترك زاخرا ... بحرا ينفل سيبه الأنفالا)\n(لأضل من جلب القوافي صعبة ... حتى أذل متونها إذلالا)","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":1,"spl":"تشبيه بقوس له سماه ليلى — حنينه إلى المدينة"},
{"id":"b28-7","bab":"الجزء 3","sec":"مدح المهدي والتعريض بالطالبين","page":"ج3 ص290","text":"قال الحزنبل وحدثني عمرو بن أبي عمرو عن أبيه قال حدثني مولى للحسن بن زيد قال قدم ابن المولى على المهدي وقد مدحه بقصيدته التي يقول فيها\n(وما قارع الأعداء مثل محمد ... إذا الحرب أبدت عن حجول الكواعب)\n(فتى ماجد الأعراق من آل هاشم ... تبحبح منها في الذرى والذوائب)\n(أشم من الرهط الذين كأنهم ... لدى حندس الظلماء زهر الكواكب)\n(إذا ذكرت يوما مناقب هاشم ... فإنكم منها بخير المناصب)\n(ومن عيب في أخلاقه ونصابه ... فما في بني العباس عيب لعائب)\n(وإن أمير المؤمنين ورهطه ... لأهل المعالي من لؤي بن غالب)\n(أولئك أوتاد البلاد ووارثوا النبي ... بأمر الحق غير التكاذب)\nم ذكر فيها آل أبي طالب فقال\n(وما نقموا إلا المودة منهم ... وأن غادروا فيهم جزيل المواهب)\n(وأنهم نالوا لهم بدمائهم ... شفاء نفوس من قتيل وهارب)\n(وقاموا لهم دون العدا وكفوهم ... بسمر القنا والمرهفات القواضب)\n(وحاموا على أحسابهم وكرائم ... حسان الوجوه واضحات الترائب)\n(وإن أمير المؤمنين لعائد ... بإنعامه فيهم على كل تائب)\n(إذا ما دنوا أدناهم وإذا هفوا ... تجاوز عنهم ناظرا في العواقب)\n(شفيق على الأقصين أن يركبوا الردى ... فكيف به في واشجات الأقارب)\nال فوصله المهدي بصلة سنية وقدم المدينة فأنفق وبنى داره ولبس ثيابا فاخرة ولم يزل كذلك مدى حياته بعد ما حباه ثم قدم على الحسن بن زيد وكانت له عليه وظيفة في كل سنة فدخل عليه فأنشده قوله يمدحه\n(هاج شوقي تفرق الجيران ... واعترتني طوارق الأحزان)\n(وتذكرت ما مضى من زماني ... حين صار الزمان شر زمان)\nقول فيها يمدح الحسن بن زيد\n(ولو ان امرأ ينال خلودا ... بمحل ومنصب ومكان)\n(أو ببيت ذراه تلصق بالنجم ... قرانا في غير برج قران)\n(أو بمجد الحياة أو بسماح ... أو بحلم أوفى على ثهلان)\n(أو بفضل لناله حسن الخير ... بفضل الرسول ذي البرهان)\n(فضله واضح برهط أبي القاسم ... رهط اليقين والإيمان)\n(هم ذوو النور والهدى ومدى الأمر ... وأهل البرهان والعرفان)\n(معدن الحق والنبوة والعدل ... إذا ما تنازع الخصمان)\n(وابن زيد إذا الرجال تجاروا ... يوم حفل وغاية ورهان)\n(سابق مغلق مجيز رهان ... ورث السبق من أبيه الهجان)\nقال فلما أنشده إياها دعا به خاليا ثم قال له يا عاض كذا من أمه أما إذا جئت إلى الحجاز فتقول لي هذا وأما إذا مضيت إلى العراق فتقول\n(وإن أمير المؤمنين ورهطه ... لرهط المعالي من لؤي بن غالب)\n(أولئك أوتاد البلاد ووارثوا النبي ... بأمر الحق غير التكاذب)\nقال له أتنصفني يابن الرسول أم لا فقال فقال ألم أقل\n(وإن أمير المؤمنين ورهطه ... )\nألستم رهطه فقال دع هذا ألم تقدر أن ينفق شعرك ومديحك إلا بتهجين أهلي والطعن عليهم والإغراء بهم حيث تقول\n(وما نقموا إلا المودة منهم ... وأن غادروا فيهم جزيل المواهب)\n(وأنهم نالوا لهم بدمائهم ... شفاء نفوس من قتيل وهارب)\nوجم ابن المولى وأطرق ثم قال يابن الرسول إن الشاعر يقول ويتقرب بجهده ثم قال فخرج من عنده منكسرا فأمر الحسن وكيله أن يحمل إليه وظيفته ويزيده فيها ففعل فقال ابن المولى والله لا أقبلها وهو علي ساخط فأما إن قرنها بالرضا فقبلتها وأما إن أقام وهو علي ساخط البتة فلا فعاد الرسول إلى الحسن فأخبره فقال له قل له قد رضيت فاقبلها ودخل على الحسن فأنشده قوله فيه\n(سألت فأعطاني وأعطى ولم أسل ... وجاد كما جادت غواد رواعد)\n(فأقسم لا أنفك أنشد مدحه ... إذا جمعتني في الحجيج المشاهد)\n(إذا قلت يوما في ثنائي قصيدة ... ثنيت بأخرى حيث تجزى القصائد)\nال الحزنبل وحدثني مالك بن وهب مولى يزيد بن حاتم المهلبي قال\nلما انصرف يزيد بن حاتم بن حرب الأزارقة وقد ظفر خلع عليه وعقد له لواء على كرر الأهواز وسائر ما افتتحه فدخل عليه ابن المولى وقد مدحه فاستأذن في الإنشاد فأذن له فأنشده صوت\n(ألا يا لقومي هل لما فات مطلب ... وهل يعذرن ذو صبوة وهو أشيب)\n(يحن إلى ليلى وقد شطت النوى ... بليلى كما حن اليراع المثقب)\nنى في هذين البيتين عطرد ولحنه رمل بالوسطى عن عمرو بن بانة وفيه ليونس لحن ذكره لنفسه في كتابه ولم يذكر طريقته\n(تقربت ليلى كي تثيب فزادني ... بعادا على بعد إليها التقرب)\n(فداويت وجدي باجتناب فلم يكن ... دواء لما ألقاه منها التجنب)","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":2,"spl":"مدح المهدي والتعريض بالطالبين","partial":1},
{"id":"b28-8","bab":"الجزء 3","sec":"مدح المهدي والتعريض بالطالبين","page":"ج3 ص290","text":"(فلا أنا عند النأي سال لحبها ... ولا أنا منها مشتف حين تصقب)\n(وما كنت بالراضي بما غيره الرضا ... ولكنني أنوي العزاء فأغلب)\n(وليل خداري الرواق جشمته ... إذا هابه السارون لا أتهيب)\n(لأظفر يوما من يزيد بن حاتم ... بحبل جوار ذاك ما كنت أطلب)\n(بلوت وقلبت الرجال كما بلا ... بكفيه أوساط القداح مقلب)\n(وصعدني همي وصوب مرة ... وذو الهم يوما مصعد ومصوب)\n(لأعرف ما آتى فلم أر مثله ... من الناس فيما حاز شرق ومغرب)\n(أكر على جيش وأعظم هيبة ... وأوهب في جود لما ليس يوهب)\n(تصدى رجال في المعالي ليلحقوا ... مداك وما أدركته فتذبذبوا)\n(ورمت الذي راموا فأذللت صعبه ... وراموا الذي أذللت منه فأصعبوا)\n(ومهما تناول من منال سنية ... يساعدك فيها المنتمي والمركب)\n(ومنصب آباء كرام نماهم ... إلى المجد آباء كرام ومنصب)\nوت\n(كواكب دجن كلما انقض كوكب ... بدا منهم در منير وكوكب)\n(أنار به آل المهلب بعدما ... هوى منكب منهم بليل ومنكب)\n(وما زال إلحاح الزمان عليهم ... بنائبة كادت لها الأرض تخرب)\n(فلو أبقت الأيام حيا نفاسة ... لأبقاهم للجود ناب ومخلب)\n(وكنت ليومي نعمة ونكاية ... كما فيهما للناس كان المهلب)\n(ألا حبذا الأحياء منكم وحبذا ... قبور بها موتاكم حين غيبوا)\nأمر له يزيد بن حاتم بعشرة آلاف درهم وفرس بسرجه ولجامه وخلعة وأقسم على من كان بحضرته أن يجيزوه كل واحد منهم بما يمكنه فانصرف بملء يده","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":3,"spl":"مدح المهدي والتعريض بالطالبين — استحسان عمرو بن أبي عمرو لشعره"},
{"id":"b28-9","bab":"الجزء 3","sec":"استحسان عمرو بن أبي عمرو لشعره","page":"ج3 ص294","text":"قال الحزنبل أنشدني عمرو بن أبي عمرو لابن المولى وكان يستحسنها\nصوت\n(حي المنازل قد بلينا ... أقوين عن مر السنينا)\n(وسل الديار لعلها ... تخبرك عن أم البنينا)\n(بانت وكل قرينة ... يوما مفارقة قرينا)\n(وأخو الحياة من الحياة ... معالج غلظا ولينا)\nنى في هذه الأبيات نبيه حفيف ثقيل بالبنصر\n(وترى الموكل بالغواني ... راكبا أبدا فنونا)\n(ومن البلية أن تدان ... بما كرهت ولن تدينا)\n(والمرء تحرم نفسه ... ما لا يزال به حزينا)\n(وتراه يجمع ماله ... جمع الحريص لوارثينا)\n(يسعى بأفضل سعيه ... فيصير ذاك لقاعدينا)\n(لم يعط ذا النسب القريب ... ولم يجد للأبعدينا)\n(قد حل منزله الذميم ... وفارق المتنصحينا)","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":3,"spl":"مدح المهدي والتعريض بالطالبين — استحسان عمرو بن أبي عمرو لشعره"},
{"id":"b28-10","bab":"الجزء 3","sec":"المهدي يأمر له ولعياله ما يكفيه","page":"ج3 ص295","text":"قال الحزنبل وذكر أحمد بن صالح بن النطاح عن المدائني أن المهدي لما ولي الخلافة وحج فرق في قريش والأنصار وسائر الناس أموالا عظيمة ووصلهم صلات سنية فحسنت أحوالهم بعد جهد أصاب الناس في أيام أبيه لتسرعهم مع محمد بن عبد الله بن حسن وكانت سنة ولايته سنة خصب ورخص فأحبه الناس وتبركوا به وقالوا هذا هو المهدي وهذا ابن عم رسول الله وسميه فلقوه فدعوا له وأثنوا عليه ومدحته الشعراء فمد عينه في الناس\nفرأى ابن المولى فأمر بتقريبه فقرب منه فقال له هات يا مولى الأنصار ما عندك فأنشده قوله فيه\n(يا ليل لا تبخلي يا ليل بالزاد ... واشفي بذلك داء الحائم الصادي)\n(وأنجزي عدة كانت لنا أملا ... قد جاء ميعادها من بعد ميعاد)\n(ما ضره غير أن أبدى مودته ... إن المحب هواه ظاهر بادي)\nم قال فيها يصف ناقته\n(تطوي البلاد إلى جم منافعه ... فعال خير لفعل الخير عواد)\n(للمهتدين إليه من منافعه ... خير يروح وخير باكر غادي)\n(أغنى قريشا وأنصار النبي ومن ... بالمسجدين بإسعاد وإحفاد)\n(كانت منافعه في الأرض شائعة ... تترى وسيرته كالماء للصادي)\n(خليفة الله عبد الله والده ... وأمه حرة تنمى لأمجاد)\n(من خير ذي يمن في خير رابية ... من القبول إليها معقل النادي)\nتى أتى على آخرها فأمر له بعشرة آلاف درهم وكسوة وأمر صاحب الجاري بأن يجري له ولعياله في كل سنة ما يكفيهم وألحقهم في شرف العطاء قال وذكر ابن النطاح عن عبد الله بن مصعب الزبيري قال وفدنا إلى المهدي ونحن جماعة من قريش والأنصار فلما دخلنا عليه سلمنا ودعونا وأثنينا فلما فرغنا من كلامنا أقبل على ابن المولى فقال هات يا محمد ما قلت فأنشده\nصوت\n(نادى الأحبة باحتمال ... إن المقيم إلى زوال)\n(رد القيان عليهم ... ذلل المطي من الجمال)\n(فتحملوا بعقيلة ... زهراء آنسة الدلال)\n(كالشمس راق جمالها ... بين النساء على الجمال)\n(لما رأيت جمالهم ... في الآل تغرق باللآلىء)\n(يا ليت ذلك بعد أن ... أظهرت أنك لا تبالي)\n(ولمثل ما جربت من ... إخلافهن لذي الوصال)\n(أسلاك عن طلب الصبا ... وأخو الصبا لا بد سالي)\n(يابن الأطايب للأطايب ... ذا المكارم والمعالي)\n(وابن الهداة بني الهداة ... وكاشفي ظلم الضلال)\n(أصحبت أكرم غالب ... عند التفاخر والنضال)\n(وإذا تحصل هاشم ... يعلو بمجدك كل عالي)\n(ويكون بيتك منهم ... في الشاهقات من القلال)\n(هذا وأنت ثمالها ... وابن الثمال أخو الثمال)\n(ومآلها بأمورها ... إن الأمور إلى مآل)\nقال فأمر له خاصة بعشرة آلاف درهم معجلة ثم ساواه بسائر الوفد بعد ذلك في\nالجائزة وأعطاه مثل ما أعطاهم وقال ذلك بحق المديح وهذا بحق الوفادة أخبرني محمد بن عمران الصيرفي أبو أحمد وعمي قالا حدثنا الحسن بن عليل العنزي قال حدثني إبراهيم بن إسحاق بن عبد الرحمن بن طلحة بن عمر بن عبيد الله قال حدثني عبد الله بن إبراهيم الجمحي قال قدم عبد الملك بن مروان المدينة وكان ابن المولى يكثر مدحه وكان يسأل عنه من غير أن يكونا التقيا قال وابن المولى مولى الأنصار فلما قدم عبد الملك المدينة قدم ابن المولى لما بلغه من مسألة عبد الملك عنه فوردها وقد رحل عبد الملك عنها فأتبعه فأدركه بإضم بذي خشب بين عين مروان وعين الحديد وهما جميعا لمروان فالتفت عبد الملك إليه وابن المولى على نجيب متنكبا قوسا عربية فقال له عبد الملك ابن المولى قال لبيك يا أمير المؤمنين قال مرحبا بمن نالنا شكره ولم ينله منا فعل ثم قال له أخبرني عن ليلى التي تقول فيها\n(وأبكي فلا ليلى بكت من صبابة ... إلي ولا ليلى لذي الود تبذل)\nالله لئن كانت ليلى حرة لأزوجنكها ولئن كانت أمة لأبتاعنها لك بما بلغت فقال كلا يا أمير المؤمنين والله ما كنت لأذكر حرمة حر أبدا ولا أمته والله يا ليلى إلا قوسي هذه سميتها ليلى لأشبب بها وإن الشاعر لا يستطاب إذا لم يتشبب فقال له عبد الملك ذلك والله أظرف لك فأقام عنده يومه وليلته ينشده ويسامره ثم أمر له بمال وكسوة وانصرف إلى المدينة","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":4,"spl":"المهدي يأمر له ولعياله ما يكفيه"},
{"id":"b28-11","bab":"الجزء 3","sec":"شعره في جعفر بن سليمان","page":"ج3 ص298","text":"أخبرني حبيب المهلبي عن الزبير وغيره عن محمد بن فضالة النحوي قال\nقدم ابن المولى البصرة فأتى جعفر بن سليمان فوقف على طريقه وقد ركب فناداه\n(كم صارخ يدعو وذي فاقة ... يا جعفر الخيرات يا جعفر)\n(أنت الذي أحييت بذل الندى ... وكان قد مات فلا يذكر)\n(سليل عباس ولي الهدى ... ومن به في المحل يستمطر)\n(هذا امتداحيك عقيد الندى ... أشهد بالمجد لك الأشقر)","topic":"أخبار ابن المولى ونسبه","topicNo":28,"sp":5,"spl":"شعره في جعفر بن سليمان"},
{"id":"b29-1","bab":"الجزء 3","sec":"أخبار عطرد ونسبه","page":"ج3 ص300","text":"عطرد مولى الأنصار ثم مولى بني عمرو بن عوف وقيل إنه مولى مزينة مدني يكنى أبا هارون وكان ينزل قباء وزعم إسحاق أنه كان جميل الوجه حسن الغناء طيب الصوت جيد الصنعة حسن الرأي والمروءة فقيها قارئا للقرآن وكان يغني مرتجلا وأدرك دولة بني أمية وبقي إلى أيام الرشيد وذكر ابن خرداذبه فيما حدثني به علي بن عبد العزيز عنه أنه كان معدل الشهادة بالمدينة أخبره بذلك يحيى بن علي المنجم عن أبي أيوب المديني عن إسحاق وأخبرنا محمد بن خلف وكيع عن حماد بن إسحاق عن أبيه أن سلمة بن عباد ولي القضاء بالبصرة فقصد ابنه عباد بن سلمة عطردا وهو بها مقيم قد قصد آل سليمان بن علي وأقام معهم فأتى بابه ليلا فدق عليه ومعه جماعة من أصحابه أصحاب القلانس فخرج عطرد إليه فلما رآه ومن معه فزع فقال لا ترع\n(إني قصدت إليك من أهلي ... في حاجة يأتي لها مثلي)\nقال وما هي أصلحك الله قال\n(لا طالبا شيئا إليك سوى ... حي الحمول بجانب العزل)\nفقال انزلوا على بركة الله فلم يزل يغنيهم هذا وغيره حتى أصبحوا","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":0,"spl":"أخبار عطرد ونسبه — خبر إبراهيم بن خالد مع ابن جامع"},
{"id":"b29-2","bab":"الجزء 3","sec":"نسبة هذا الصوت","page":"ج3 ص300","text":"صوت\n(حي الحمول بجانب العزل ... إذ لا يوافق شكلها شكلي)\n(الله أنجح ما طلبت به ... والبر خير حقيبة الرحل)\n(إني بحبلك واصل حبلي ... وبريش نبلك رائش نبلي)\n(وشمائلي ما قد علمت وما ... نبحت كلابك طارقا مثلي)\nلشعر لامرئ القيس بن عابس الكندي هكذا روى أبو عمرو الشيباني وقال إن من يرويه لامرئ القيس بن حجر يغلط والغناء لعطرد ثقيل أول بالبنصر عن عمرو بن بانة وفيه لعمرو بن بانة ثقيل بالوسطى من روايته أيضا وفيه لابن عائشة خفيف رمل بالبنصر وفيه عنه وعن دنانير لمالك خفيف ثقيل أول بالوسطى وفيه عنه أيضا لإبراهيم ثاني ثقيل بالبنصر","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":0,"spl":"أخبار عطرد ونسبه — خبر إبراهيم بن خالد مع ابن جامع"},
{"id":"b29-3","bab":"الجزء 3","sec":"المهدي لا يأنس لغناء إبراهيم بن خالد المعيطي","page":"ج3 ص301","text":"وأخبرني يحيى بن علي قال حدثنا أبو أيوب المديني وأخبرني به الحسن بن علي قال\nكتب إلي أبو أيوب المديني وخبره أتم قال حدثني علي بن محمد النوفلي عن أبيه عن إبراهيم بن خالد المعيطي قال دخلت على المهدي وقد كان وصف له غنائي فسألني عن الغناء وعن علمي به فنسبته من ذلك طرفا فقال لي أتغني النواقيس قلت نعم وأغني الصلبان يا أمير المؤمنين فتبسم والنواقيس لحن معبد كان معبد وأهل الحجاز يسمونه النواقيس وهو\n(سلا دار ليلى هل تبين فتنطق ... وأنى ترد القول بيداء سملق)\nال ثم قال لي المهدي وهو يضحك غنه فعنيته فأمر لي بمال جزيل وخلع علي وصرفني ثم بلغني أنه قال هذا معيطي وأنا لا آنس به ولا حاجة لي إلى أن أدنيه من خلوتي وأنا لا آنس به هكذا ذكر في هذا الخبر أن اللحن لمعبد وما ذكره أحد من رواة الغناء له ولا وجد في ديوان من دواوينهم منسوبا إليه على انفراد به ولا شركة فيه ولعله غلط","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":0,"spl":"أخبار عطرد ونسبه — خبر إبراهيم بن خالد مع ابن جامع"},
{"id":"b29-4","bab":"الجزء 3","sec":"خبر إبراهيم بن خالد مع ابن جامع","page":"ج3 ص302","text":"وقد أخبرني هذا الخبر الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال كان إبراهيم بن المعيطي يغني فدخل يوما الحمام وابن جامع فيه وكان له شيء يجاوز ركبتيه فقال له ابن جامع يا إبراهيم أتبيع هذا البغل قال لا بل أحملك عليه يا أبا القاسم فلما خرج ابن جامع من الحمام رأى ثياب\nالمعيطي رثة فأمر له بخلعة من ثيابه فقال له المعيطي لو قبلت حملاني قبلت خلعتك فضحك ابن جامع وقال له مالك أخزاك الله ويلك أما تدع ولعك وبطالتك وشرك ودخل إلى الرشيد فحدثه حديثه فضحك وأمر بإحضاره فأحضر فقال له أتغني النواقيس قال نعم وأغني الصلبان أيضا ثم ذكر باقي الخبر مثل الذي تقدمه أخبرني يحيى بن علي قال حدثني أبو أيوب المديني عن إسحاق قال كان عطرد منقطعا في دولة بني هاشم إلى آل سليمان بن علي لم يخدم غيرهم وتوفي في خلافة المهدي قال وكان يوما يغني بين يدي سليمان بن علي فغناه صوت\n(أله فكم من ماجد قد لها ... ومن كريم عرضه وافر)\nلغناء لعطرد ثاني ثقيل عن الهشامي فقيل له سرقت هذا من لحن الغريض\n(يا ربع سلامة بالمنحنى ... فخيف سلع جادك الوابل)\nقال لم أسرقه ولكن العقول تتوافق وحلف أنه لم يسمعه قط","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":0,"spl":"أخبار عطرد ونسبه — خبر إبراهيم بن خالد مع ابن جامع"},
{"id":"b29-5","bab":"الجزء 3","sec":"نسبة هذا الصوت","page":"ج3 ص303","text":"صوت\n(يا ربع سلامة بالمنحنى ... فخيف سلع جادك الوابل)\n(إن تمس وحشا طالما قد ترى ... وأنت معمور بهم آهل)\n(أيام سلامة رعبوبة ... خود لعوب حبها قاتل)\n(محطوطة المتن هضيم الحشى ... لا يطبيها الورع الواغل)\nلغناء للغريض ثاني ثقيل بالوسطى عن عمرو بن يحيى المكي قال ومن الناس من ينسبه إلى ابن سريج","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":1,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين"},
{"id":"b29-6","bab":"الجزء 3","sec":"إطلاقه ومن معه بعد أن حبسه زبراء والي المدينة","page":"ج3 ص303","text":"أخبرني أحمد بن علي بن يحيى قال سمعت جدي علي بن يحيى قال حدثني أحمد بن إبراهيم الكاتب قال حدثني خالد بن كلثوم قال\nكنت مع زبراء بالمدينة وهو وال عليها وهو من بني هاشم أحد بني ربيعة بن الحارث بن عبد المطلب فأمر بأصحاب الملاهي فحبسوا وحبس عطرد وأخبروه أنه من أهل الهيئة والمروءة والنعمة والدين فدعا به فخلى سبيله وأمره برفع حوائجه إليه فدعا له وخرج فإذا هو بالمغنين أحضروا ليعرضوا فعاد إليه عطرد فقال أصلح الله الأمير أعلى الغناء حبست هؤلاء قال نعم قال فلا تظلمهم فوالله ما أحسنوا منه شيئا قط فضحك وخلى سبيلهم","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":1,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين"},
{"id":"b29-7","bab":"الجزء 3","sec":"خبره مع الوليد بن يزيد","page":"ج3 ص304","text":"أخبرني محمد بن مزيد وجحظة قالا حدثنا حماد بن إسحاق قال قرأت على أبي عن محمد بن عبد الحميد بن إسماعيل بن عبد الحميد بن يحيى عن عمه أيوب بن إسماعيل قال\nلما استخلف الوليد بن يزيد كتب إلى عامله بالمدينة يأمره بالشخوص إليه بعطرد المغني قال عطرد فأقرأني العامل الكاتب وزودني نفقة وأشخصني إليه فأدخلت عليه وهو جالس في قصره على شفير بركة مرصصة مملوءة خمرا ليست بالكبيرة ولكنها يدور الرجل فيها سباحة فوالله ما تركني أسلم عليه حتى قال أعطرد قلت نعم يا أمير المؤمنين قال لقد كنت إليك مشتاقا يا أبا هارون غنني\n(حي الحمول بجانب العزل ... إذ لا يلائم شكلها شكلي)\n(إني بحبلك واصل حبلي ... وبريش نبلك رائش نبلي)\n(وشمائلي ما قد علمت وما ... نبحت كلابك طارقا مثلي)\nال فغينته إياه فوالله ما أتممته حتى شق حلة وشي كانت عليه لا أدري كم قيمتها فتجرد منها كما ولدته أمه وألقاها نصفين ورمى بنفسه في البركة فنهل منها حتى تبينت علم الله فيها أنها قد نقصت نقصانا بينا وأخرج منها وهو كالميت سكرا فأضجع وغطي فأخذت الحلة وقمت فوالله ما قال لي أحد دعها ولا خذها فانصرفت إلى منزلي متعجبا مما رأيت من ظرفه وفعله وطربه فلما كان من غد جاءني رسوله في مثل الوقت فأحضرني فلما دخلت عليه قال لي يا عطرد قلت لبيك يا أمير المؤمنين قال غنني\n(أيذهب عمري هكذا لم أنل بها ... مجالس تشفي قرح قلبي من الوجد)\n(وقالوا تداو إن في الطب راحة ... فعللت نفسي بالدواء فلم يجد)\nغنيته إياه فشق حلة وشي كانت تلتمع عليه بالذهب التماعا احتقرت والله الأولى عندها ثم ألقى نفسه في البركة فنهل فيها حتى تبينت علم الله نقصانها وأخرج\nمنها كالميت سكرا وألقي وغطي فنام وأخذت الحلة فوالله ما قال لي أحد دعها ولا خذها وانصرفت فلما كان اليوم الثالث جاءني رسوله فدخلت إليه وهو في بهو قد ألقيت ستوره فكلمني من وراء الستور وقال يا عطرد قلت لبيك يا أمير المؤمنين قال كأني بك الآن قد أتيت المدينة فقمت بي في مجلسها ومحفلها وقعدت وقلت دعاني أمير المؤمنين فدخلت إليه فاقترح علي فغنيته وأطربته فشق ثيابه وأخذت سلبه وفعل وفعل والله يابن الزانية لئن تحركت شفتاك بشيء مما جرى فبلغني لأضربن عنقك يا غلام أعطه ألف دينار خذها وانصرف إلى المدينة فقلت إن رأى أمير المؤمنين أن يأذن لي في تقبيل يده ويزودني نظرة منه وأغنيه صوتا فقال لا حاجة بي ولا بك إلى ذلك فانصرف قال عطرد فخرجت من عنده وما علم الله أني ذكرت شيئا مما جرى حتى مضت من دولة بني هاشم مدة","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":1,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين"},
{"id":"b29-8","bab":"الجزء 3","sec":"نسبة هذين الصوتين","page":"ج3 ص306","text":"الصوت الأول مما غناه عطرد الوليد قد نسب في أول أخباره والثاني الذي أوله\n(أيذهب عمري هكذا لم أنل بها ... )\nلغناء فيه لعطرد ثاني ثقيل بالسبابة في مجرى البنصر عن إسحاق وفيه ليونس من كتابه لحن لم يذكر طريقته وذكر عمرو بن بانة أن فيه لإبراهيم ثاني ثقيل بالوسطى","topic":"أخبار عطرد ونسبه","topicNo":29,"sp":1,"spl":"نسبة هذا الصوت — نسبة هذين الصوتين","partialRef":{"sid":"b29-7","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b30-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص307","text":"(إن امرأ تعتاده ذكر ... منها ثلاث منى لذو صبر)\n(ومواقف بالمشعرين لها ... ومناظر الجمرات والنحر)\n(وإفاضة الركبان خلفهم ... مثل الغمام أرذ بالقطر)\n(حتى استلمن الركن في أنف ... من ليلهن يطأن في الأزر)\n(يقعدن في التطواف آونة ... ويطفن أحيانا على فتر)\n(ففرغن من سبع وقد جهدت ... أحشاؤهن موائل الخمر)\nلشعر للحارث بن خالد المخزومي والغناء في اللحن المختار للأبجر وإيقاعه من الثقيل الأول بإطلاق الوتر في مجرى البنصر في الأول والثاني والسادس من الأبيات عن إسحاق وفيه للغريض خفيف ثقيل أول بالوسطى عن عمرو ولابن سريج في الثالث والرابع رمل بالسبابة في مجرى البنصر عن إسحاق","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":0,"spl":"صوت من المائة المختارة — الحارث بن خالد يقصر شعره على الغزل"},
{"id":"b30-2","bab":"الجزء 3","sec":"أخبار الحارث بن خالد المخزومي ونسبه","page":"ج3 ص307","text":"الحارث بن خالد بن العاص بن هاشم بن المغيرة بن عبد الله بن عمرو بن مخزوم بن يقظة بن مرة بن كعب بن لؤي بن غالب وأمه فاطمة بنت أبي سعيد بن الحارث بن هشام وأمها بنت أبي جهل بن هشام وكان العاص بن هشام جد الحارث بن خالد خرج مع المشركين يوم بدر فقتله أمير المؤمنين علي بن أبي طالب رضي الله عنه","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":0,"spl":"صوت من المائة المختارة — الحارث بن خالد يقصر شعره على الغزل"},
{"id":"b30-3","bab":"الجزء 3","sec":"أبو لهب يسترق العاص بن هشام","page":"ج3 ص308","text":"حدثني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ قال حدثني مصعب بن عبد الله قال قامر أبو لهب العاص بن هشام في عشر من الإبل فقمره أبو لهب ثم في عشر فقمره ثم في عشر فقمره ثم في عشر فقمره ثم في عشر فقمره إلى أن خلعه من ماله فلم يبق له شيء فقال له إني أرى القداح قد حالفتك يابن عبد المطلب فهلم أقامرك فأينا قمر كان عبدا لصاحبه قال افعل ففعل فقمره أبو لهب فكره أن يسترقه فتغضب بنو مخزوم فمشى إليهم وقال افتدوه مني بعشر من الإبل فقالوا لا والله ولا بوبرة فاسترقه فكان يرعى له إبلا إلى أن خرج\nالمشركون إلى بدر وقال غير مصعب فاسترقه وأجلسه قينا يعمل الحديد فلما خرج المشركون إلى بدر كان من لم يخرج أخرج بديلا وكان أبو لهب عليلا فأخرجه وقعد على أنه إن عاد إليه أعتقه فقتله علي بن أبي طالب رضي الله عنه يومئذ","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":0,"spl":"صوت من المائة المختارة — الحارث بن خالد يقصر شعره على الغزل"},
{"id":"b30-4","bab":"الجزء 3","sec":"الحارث بن خالد يقصر شعره على الغزل","page":"ج3 ص309","text":"والحارث بن خالد أحد شعراء قريش المعدودين الغزليين وكان يذهب مذهب عمر بن أبي ربيعة لا يتجاوز الغزل إلى المديح ولا الهجاء وكان يهوى عائشة بنت طلحة بن عبيد الله ويشبب بها وولاه عبد الملك بن مروان مكة وكان ذا قدر وخطر ومنظر في قريش وأخوه عكرمة بن خالد المخزومي محدث جليل من وجوه التابعين قد روى عن جماعة من الصحابة وله أيضا أخ يقال له عبد الرحمن بن خالد شاعر وهو الذي يقول\n(رحل الشباب وليته لم يرحل ... وغدا لطية ذاهب متحمل)\n(ولى بلا ذم وغادر بعده ... شيبا أقام مكانه في المنزل)\n(ليت الشباب ثوى لدينا حقبة ... قبل المشيب وليته لم يعجل)\n(فنصيب من لذاته ونعيمه ... كالعهد إذ هو في الزمان الأول)\nفيه غناء حدثني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال حدثنا الأصمعي قال قال معاذ بن العلاء أخو أبي عمرو بن العلاء كان أبو عمرو إذا لم يحج\nاستبضعني الحروف أسأل عنها الحارث بن خالد بن العاص بن هاشم بن المغيرة الشاعر وآتيه بجوابها قال فقدمت عليه سنة من السنين وقد ولاه عبد الملك بن مروان مكة فلما رآني قال يا معاذ هات ما معك من بضائع أبي عمرو فجعلت أعجب من اهتمامه بذلك وهو أمير","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":0,"spl":"صوت من المائة المختارة — الحارث بن خالد يقصر شعره على الغزل"},
{"id":"b30-5","bab":"الجزء 3","sec":"هو أحد شعراء قريش الخمسة المشهورين","page":"ج3 ص310","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار وأخبرني به الحسن ابن علي عن أحمد بن سعيد عن الزبير ولفظه أتم قال حدثني محمد بن الضحاك الحزامي قال كانت العرب تفضل قريشا في كل شيء إلا الشعر فلما نجم في قريش عمر بن أبي ربيعة والحارث بن خالد المخزومي والعرجي وأبو دهبل وعبيد الله بن قيس الرقيات أقرت لها العرب بالشعر أيضا أخبرني علي بن صالح بن الهيثم وإسماعيل بن يونس وحبيب بن نصر وأحمد بن عبد العزيز قالوا حدثنا عمر بن شبة قال حدثني محمد بن يحيى أبو غسان قال\nتفاخر مولى لعمر بن أبي ربيعة ومولى للحارث بن خالد بشعريهما فقال مولى الحارث لمولى عمر دعني منك فإن مولاك والله لا يعرف المنازل إذا قلبت يعني قول الحارث\n(إني وما نحروا غداة منى ... عند الجمار تؤودها العقل)\n(لو بدلت أعلى مساكنها ... سفلا وأصبح سفلها يعلو)\n(فيكاد يعرفها الخبير بها ... فيرده الإقداء والمحل)\n(لعرفت مغناها بما احتملت ... مني الضلوع لأهلها قبل)\nال عمر بن شبة وحدثني محمد بن سلام بهذا الخبر على نحو مما ذكره أبو غسان وزاد فيه فقال مولى ابن أبي ربيعة لمولى الحارث والله ما يحسن مولاك في شعر إلا نسب إلى مولاي قال ابن سلام وأنشد الحارث بن خالد عبد الله بن عمر هذه الأبيات كلها حتى انتهى إلى قوله\n(لعرفت مغناها بما احتملت ... مني الضلوع لأهلها قبل)\nقال له ابن عمر قل إن شاء الله قال إذا يفسد بها الشعر يا عم فقال له يابن أخي إنه لا خير في شيء يفسده إن شاء الله قال عمر وحدثني هذه الحكاية إسحاق بن إبراهيم في مخاطبته لابن عمر ولم يسندها إلى أحد وأظنه لم يروها إلا عن محمد بن سلام وأخبرني محمد بن خلف بن المرزبان عن أبي الفضل المروروذي عن إسحاق عن أبي عبيدة فذكر قصة الحارث مع ابن عمر مثل الذي تقدمه","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":1,"spl":"هو أحد شعراء قريش الخمسة المشهورين — نسبة ما في هذه الأخبار من الأغاني في أبيات كثير الأول"},
{"id":"b30-6","bab":"الجزء 3","sec":"كثير عزة يفضله على نفسه","page":"ج3 ص312","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا الرياشي قال حدثني أبو سلمة الغفاري عن يحيى بن عروة بن أذينة عن أبيه قال كان كثير جالسا في فتية من قريش إذ مر بهم سعيد الراس وكان مغنيا فقالوا لكثير يا أبا صخر هل لك أن نسمعك غناء هذا فإنه مجيد قال افعلوا فدعوا به فسألوه أن يغنيهم صوت\n(هلا سألت معالم الأطلال ... بالجزع من حرض وهن بوالي)\n(سقيا لعزة خلتي سقيا لها ... إذ نحن بالهضبات من أملال)\n(إذ لا تكلمنا وكان كلامها ... نفلا نؤمله من الأنفال)\nفغناه فطرب كثير وارتاح وطرب القوم جميعا واستحسنوا قول كثير وقالوا له يا أبا صخر ما يستطيع أحد أن يقول مثل هذا فقال بلى الحارث بن خالد حيث يقول صوت\n(إني وما نحروا غداة منى ... عند الجمار تؤودها العقل)\n(لو بدلت أعلى مساكنها ... سفلا وأصبح سفلها يعلو)\n(لعرفت مغناها بما احتملت ... مني الضلوع لأهلها قبل)","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":1,"spl":"هو أحد شعراء قريش الخمسة المشهورين — نسبة ما في هذه الأخبار من الأغاني في أبيات كثير الأول"},
{"id":"b30-7","bab":"الجزء 3","sec":"نسبة ما في هذه الأخبار من الأغاني في أبيات كثير الأول","page":"ج3 ص312","text":"التي أولها\n(هلا سألت معالم الأطلال ... )\nابن سريج منها في الثاني والثالث رمل مطلق في مجرى البنصر عن إسحاق وللغريض في الأول والثاني ثقيل أول مطلق في مجرى البنصر عنه وفيهما لعلويه رمل بالوسطى عن عمرو وفي أبيات الحارث بن خالد لإبراهيم الموصلي رمل بالسبابة في مجرى الوسطى عن إسحاق أيضا","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":1,"spl":"هو أحد شعراء قريش الخمسة المشهورين — نسبة ما في هذه الأخبار من الأغاني في أبيات كثير الأول","partialRef":{"sid":"b30-6","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b30-8","bab":"الجزء 3","sec":"أشعب يتمثل بشعره","page":"ج3 ص313","text":"أخبرني عمي حدثنا الكراني قال حدثنا الخليل بن أسد عن العمري عن الهيثم بن عدي قال دخل أشعب مسجد النبي فجعل يطوف الحلق فقيل له ما تريد فقال أستفتي في مسألة فبينا هو كذلك إذ مر برجل من ولد الزبير وهو مسند إلى سارية وبين يديه رجل علوي فخرج أشعب مبادرا فقال له الذي سأله عن دخوله وتطوافه أوجدت من أفتاك في مسألتك قال لا ولكني علمت ما هو خير لي منها قال وما ذاك قال وجدت المدينة قد صارت كما قال الحارث بن خالد\n(قد بدلت أعلى مساكنها ... سفلا وأصبح سفلها يعلو)\nأيت رجلا من ولد الزبير جالسا في الصدر ورجلا من ولد علي بن أبي طالب رضي الله عنه جالسا بين يديه فكفى هذا عجبا فانصرفت أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرني هذا الخبر إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا محمد بن يحيى أبو غسان وأخبرني به محمد بن خلف بن المرزبان قال حدثنا عمر بن شبة قال حدثنا أبو عبد الله بن محمد بن حفص عن أبيه قال قال محمد بن خلف أخبرني به أبو أيوب سليمان بن أيوب المدني قال حدثنا مصعب الزبيري وأخبرني به أيضا الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي وقد جمعت رواياتهم في هذا الخبر أن بني مخزوم كلهم كانوا زبيرية سوى الحارث بن خالد فإنه كان مروانيا","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":2,"spl":"أشعب يتمثل بشعره — نسبة ما في الأخبار من الغناء"},
{"id":"b30-9","bab":"الجزء 3","sec":"عبد الملك يوليه مكة","page":"ج3 ص314","text":"فلما ولي عبد الملك الخلافة عام الجماعة وفد عليه في دين كان عليه وذلك في سنة خمس وسبعين وقال مصعب في خبره بل حج عبد الملك في تلك السنة فلما انصرف رحل معه الحارث إلى دمشق فظهرت له منه جفوة وأقام ببابه شهرا لا يصل إليه فانصرف عنه وقال فيه\n(صحبتك إذ عيني عليها غشاوة ... فلما انجلت قطعت نفسي ألومها)\n(وما بي وإن أقصيتني من ضراعة ... ولا افتقرت نفسي إلى من يضيمها)\nذا البيت في رواية ابن المرزبان وحده\n(عطفت عليك النفس حتى كأنما ... بكفيك بؤسي أو عليك نعيمها)\nوبلغ عبد الملك خبره وأنشد الشعر فأرسل إليه من رده من طريقه فلما دخل عليه قال له حار أخبرني عنك هل رأيت عليك في المقام ببابي غضاضة أو في قصدي دناءة قال لا والله يا أمير المؤمنين قال فما حملك على ما قلت وفعلت قال جفوة ظهرت لي كنت حقيقا بغير هذا قال فاختر فإن شئت أعطيتك مائة ألف درهم أو قضيت دينك أو وليتك مكة سنة فولاه إياها فحج بالناس وحجت عائشة بنت طلحة عامئذ وكان يهواها فأرسلت إليه أخر الصلاة حتى أفرغ من طوافي فأمر المؤذنين فأخروا الصلاة حتى فرغت من طوافها ثم أقيمت الصلاة فصلى بالناس وأنكر أهل الموسم ذلك من فعله وأعظموه فعزله وكتب إليه يؤنبه فيما فعل فقال ما أهون والله غضبه إذا رضيت والله لو لم تفرغ من طوافها إلى الليل لأخرت الصلاة إلى الليل فلما قضت حجها أرسل إليها يابنة عمي ألمي بنا أوعدينا مجلسا نتحدث فيه فقالت في غد أفعل ذلك ثم رحلت من ليلتها فقال الحارث فيها صوت\n(ما ضركم لو قلتم سددا ... إن المطايا عاجل غدها)\n(ولها علينا نعمة سلفت ... لسنا على الأيام نجحدها)\n(لو تممت أسباب نعمتها ... تمت بذلك عندنا يدها)\nلمعبد في هذه الأبيات ثقيل أول بالوسطى عن عمرو بن بانة ويونس ودنانير وقد ذكره إسحاق فنسبه إلى ابن محرز ثقيلا أول في أصوات قليلة الأشباه وقال عمرو بن بانة من الناس من نسبه إلى الغريض","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":2,"spl":"أشعب يتمثل بشعره — نسبة ما في الأخبار من الغناء"},
{"id":"b30-10","bab":"الجزء 3","sec":"نسبة ما في الأخبار من الغناء","page":"ج3 ص315","text":"صوت\n(وما بي وإن أقصيتني من ضراعة ... ولا افتقرت نفسي إلى من يهينها)\n(بلى بأبي إني إليك لضارع ... فقير ونفسي ذاك منها يزينها)\nلبيت الأول للحارث بن خالد والثاني ألحق به والغناء للغريض ثقيل أول بالوسطى عن ابن المكي وذكر الهشامي أن لحن الغريض خفيف ثقيل في البيت الأول فقط وحكى أن قافيته على ما كان الحارث قاله\n(ولا افتقرت نفسي إلى من يضيمها ... )\nأن الثقيل الأول لعلية بنت المهدي ومن غنائها البيت المضاف وأخلق بأن يكون الأمر على ما ذكره لأن البيت الثاني ضعيف يشبه شعرها","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":2,"spl":"أشعب يتمثل بشعره — نسبة ما في الأخبار من الغناء","partialRef":{"sid":"b30-9","gi":0,"vi":1,"side":1},"partial":1},
{"id":"b30-11","bab":"الجزء 3","sec":"شعره بعائشة بنت طلحة بعد رحيلها وزوجها","page":"ج3 ص316","text":"أخبرني أحمد بن عبد العزيز وحبيب بن نصر وإسماعيل بن يونس قالوا حدثنا عمر بن شبة قال حدثني أبو غسان محمد بن يحيى قال لما تزوج مصعب بن الزبير عائشة بنت طلحة ورحل بها إلى العراق قال الحارث بن خالد في ذلك صوت\n(ظعن الأمير بأحسن الخلق ... وغدا بلبك مطلع الشرق)\n(في البيت ذي الحسب الرفيع ومن ... أهل التقى والبر والصدق)\n(فظللت كالمقهور مهجته ... هذا الجنون وليس بالعشق)\n(أترجة عبق العبير بها ... عبق الدهان بجانب الحق)\n(ما صبحت أحدا برؤيتها ... إلا غدا بكواكب الطلق)\nهي أبيات غنى ابن محرز في البيتين الأولين خفيف رمل بالسبابة في مجرى الوسطى عن إسحاق وذكر عمرو بن بانة أن فيها لمالك ثقيلا بالوسطى وذكر حبش أن فيهما لمالك رملا بالوسطى وذكر حبش أيضا أن فيهما للدلال ثاني ثقيل بالبنصر ولابن سريج ومالك رملين ولسعيد بن جابر هزجا بالوسطى","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":3,"spl":"شعره بعائشة بنت طلحة بعد رحيلها وزوجها"},
{"id":"b30-12","bab":"الجزء 3","sec":"خبره في مكة مع عائشة","page":"ج3 ص317","text":"أخبرني محمد بن مزيد بن أبي الأزهر والحسين بن يحيى عن حماد بن إسحاق عن أبيه عن محمد بن سلام عن ابن جعدية قال لما أن قدمت عائشة بنت طلحة أرسل إليها الحارث بن خالد وهو أمير على مكة إني أريد السلام عليك فإذا خف عليك أذنت وكان الرسول الغريض فقالت له إنا حرم فإذا أحللنا أذناك فلما أحلت سرت على بغلاتها ولحقها الغريض بعسفان أو قريب منه ومعه كتاب الحارث إليها\n(ما ضركم لو قلتم سددا ... )\nالأبيات المذكورة فلما قرأت الكتاب قالت ما يدع الحارث باطله ثم قالت\nللغريض هل أحدثت شيئا قال نعم فاسمعي ثم اندفع يغني في هذا الشعر فقالت عائشة والله ما قلنا إلا سددا ولا أردنا إلا أن نشتري لسانه وأتى على الشعر كله فاستحسنته عائشة وأمرت له بخمسة آلاف درهم وأثواب وقالت زدني فغناها في قول الحارث بن خالد أيضا\n(زعموا بأن البين بعد غد ... فالقلب مما أحدثوا يجف)\n(والعين منذ أجد بينهم ... مثل الجمان دموعها تكف)\n(ومقالها ودموعها سجم ... أقلل حنينك حين تنصرف)\n(تشكو ونشكو ما أشت بنا ... كل بوشك البين معترف)\nيقاع هذا الصوت ثقيل أول مطلق في مجرى الوسطى عن الهشامي ولم يذكر له حماد طريقا قال فقالت له عائشة يا غريض بحقي عليك أهو أمرك أن تغنيني في هذا الشعر فقال لا وحياتك يا سيدتي فأمرت له بخمسة آلاف درهم ثم قالت له غنني في شعر غيره فغناها قول عمر فيها صوت\n(أجمعت خلتي مع الفجر بينا ... جلل الله ذلك الوجه زينا)\n(أجمعت بينها ولم نك منها ... لذة العيش والشباب قضينا)\n(فتولت حمولها واستقلت ... لم ننل طائلا ولم نقض دينا)\n(ولقد قلت يوم مكة لما ... أرسلت تقرأ السلام علينا)\n(أنعم الله بالرسول الذي أرسل ... والمرسل الرسالة عينا)\nالشعر لعمر بن أبي ربيعة والغناء للغريض خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وغيره ينسبه إلى ابن سريج وفيه لمعبد خفيف ثقيل بالوسطى عن عمرو وأظنه هذا اللحن قال فضحكت ثم قالت وأنت يا غريض فأنعم الله بك عينا وبابن أبي ربيعة عينا لقد تلطفت حتى أديت إلينا رسالته وإن وفاءك له لمما يزيدنا رغبة فيك وثقة بك وقد كان عمر سأل الغريض أن يغنيها هذا الصوت لأنه قد كان ترك ذكرها لما غضبت بنو تيم من ذلك فلم يحب التصريح بها وكره إغفال ذكرها وقال له عمر إن أبلغتها هذه الأبيات في غناء فلك خمسة آلاف درهم فوفى له بذلك وأمرت له عائشة بخمسة آلاف درهم أخرى ثم انصرف الغريض من عندها فلقي عاتكة بنت يزيد بن معاوية امرأة عبد الملك بن مروان وكانت قد حجت في تلك السنة فقال لها جواريها هذا الغريض فقالت لهن علي به فجيء به إليها قال الغريض فلما دخلت سلمت فردت علي وسألتني عن الخبر فقصصته عليها فقالت غنني بما غنيتها به ففعلت فلم أرها تهش لذلك فغنيتها معرضا لها ومذكرا بنفسي في شعر مرة بن محكان السعدي يخاطب امرأته وقد نزل به أضياف\n(أقول والضيف مخشي ذمامته ... على الكريم وحق الضيف قد وجبا)\nوت\n(يا ربة البيت قومي غير صاغرة ... ضمي إليك رحال القوم والقربا)\n(في ليلة من جمادى ذات أندية ... لا يبصر الكلب من ظلمائها الطنبا)\n(لا ينبح الكلب فيها غير واحدة ... حتى يلف على خيشومه الذنبا)\nلشعر لمرة بن محكان السعدي والغناء لابن سريج ذكر يونس أن فيه ثلاثة ألحان فوجدت منها واحدا في كتاب عمرو بن بانة رملا بالوسطى والآخر في كتاب الهشامي خفيف ثقيل بالوسطى والآخر ثاني ثقيل في كتاب أحمد بن المكي قال فقالت وهي متبسمة قد وجب حقك يا غريض فغنني فغنيتها صوت\n(يا دهر قد أكثرت فجعتنا ... بسراتنا ووقرت في العظم)\n(وسلبتنا ما لست مخلفه ... يا دهر ما أنصفت في الحكم)\n(لو كان لي قرن أناضله ... ما طاش عند حفيظة سهمي)\n(لو كان يعطي النصف قلت له ... أحرزت سهمك فاله عن سهمي)\nقالت نعطيك النصف ولا نضيع سهمك عندنا ونجزل لك قسمك وأمرت لي بخمسة آلاف درهم وثياب عدنية وغير ذلك من الألطاف وأتيت الحارث بن خالد فأخبرته الخبر وقصصت عليه القصة فأمر لي بمثل ما أمرتا لي به جميعا فأتيت ابن أبي ربيعة وأعلمته بما جرى فأمر لي بمثل ذلك فما انصرف واحد من ذلك الموسم بمثل ما انصرفت به بنظرة من عائشة ونظرة من عاتكة وهما من أجمل نساء عالمهما وبما أمرتا لي به وبالمنزلة عند الحارث وهو أمير مكة وابن أبي ربيعة وما أجازاني به جميعا من المال","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":4,"spl":"خبره في مكة مع عائشة","partialRef":{"sid":"b30-9","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b30-13","bab":"الجزء 3","sec":"خبره في مكة مع عائشة","page":"ج3 ص317","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أبو الحسن المروزي قال حدثنا محمد بن سلام عن يونس قال لما حجت عائشة بنت طلحة أرسل إليها الحارث بن خالد وهو أمير مكة أنعم الله بك عينا وحياك وقد أردت زيارتك فكرهت ذلك إلا عن أمرك فإن أذنت فيها فعلت فقالت لمولاة لها جزلة وما أرد على هذا السفيه فقالت لها أنا أكفيك فخرجت إلى الرسول وقالت له اقرأ عليه السلام وقل له وأنت أنعم الله بك عينا وحياك نقضي نسكنا ثم يأتيك رسولنا إن شاء الله ثم قالت لها قومي فطوفي واسعي واقضي عمرتك واخرجي في الليل ففعلت وأصبح الحارث فسأل عنها فأخبر خبرها فوجه إليها رسولا بهذه الأبيات فوجدها قد خرجت عن عمل مكة فأوصل الكتاب إليها فقالت لمولاتها خذيه فإني أظنه بعض سفاهاته فأخذته وقرأته وقالت له ما قلنا إلا سددا وأنت فارغ للبطالة ونحن عن فراغك في شغل","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":5,"spl":"خبره في مكة مع عائشة — يحمل قادما إلى المدينة رقعة كتب فيها لعائشة"},
{"id":"b30-14","bab":"الجزء 3","sec":"يحمل قادما إلى المدينة رقعة كتب فيها لعائشة","page":"ج3 ص321","text":"أخبرني أحمد بن عبيد الله بن عمار وأحمد بن عبد العزيز الجوهري وحبيب ابن نصر المهلبي وإسماعيل بن يونس الشيعي قالوا حدثنا عمر بن شبة قال حدثنا إسحاق بن إبراهيم الموصلي قال زعم كلثوم بن أبي بكر بن عمر بن الضحاك بن قيس الفهري قال قدم المدينة قادم من مكة فدخل على عائشة بنت طلحة فقالت له من أين أقبل الرجل قال من مكة فقالت فما فعل الأعرابي فلم يفهم ما أرادت فلما عاد إلى مكة دخل على الحارث فقال له من أين قال من المدينة قال فهل دخلت على عائشة بنت طلحة قال نعم قال فعماذا سألتك قال قالت\nلي ما فعل الأعرابي قال له الحارث فعد إليها ولك هذه الراحلة والحلة ونفقتك لطريقك وادفع إليها هذه الرقعة وكتب إليها فيها صوت\n(من كان يسأل عنا أين منزلنا ... فالأقموانة منا منزل قمن)\n(إذ نلبس العيش صفوا ما يكدره ... طعن الوشاة ولا ينبو بنا الزمن)\nال إسحاق وزادني غير كلثوم فيها\n(ليت الهوى لم يقربني إليك ولم ... أعرفك إذ كان حظي منكم الحزن)\nنى في هذه الأبيات ابن محرز خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر يونس أن فيها لحنا ولم يجنسه وذكر عمرو أن فيه لبابويه ثاني ثقيل بالبنصر أخبرني الحسين بن يحيى عن حماد عن أبيه عن محمد بن سلام قال لما ولى عبد الملك بن مروان الحارث بن خالد المخزومي مكة بعث إلى الغريض فقال له لا أرينك في عملي وكان قبل ذلك يطلبه ويستدعيه فلا يجبيه فخرج الغريض إلى ناحية الطائف وبلغ ذلك الحارث فرق له فرده وقال له لم كنت تبغضنا وتهجر شعرنا ولا تقربنا قال له الغريض كانت هفوة من هفوات النفس وخطرة من خطرات الشيطان ومثلك وهب الذنب وصفح عن الجرم وأقال العثرة وغفر الزلة ولست بعائد إلى ذلك أبدا قال وهل غنيت\nفي شيء من شعري قال نعم قد غنيت في ثلاثة أصوات من شعرك قال هات ما غنيت فغينت صوت\n(بان الخليط فما عاجوا ولا عدلوا ... إذا ودعوك وحنت بالنوى الإبل)\n(كأن فيهم غداة البين إذ رحلوا ... أدماء طاع لها الحوذان والنفل)\nلغناء للغريض ثقيل أول بالوسطى عن الهشامي وحبش قال حبش وفيه لابن سريج خفيف رمل بالبنصر ولإسحاق ثاني ثقيل بالبنصر فقال له أحسنت والله يا غريض هات ما غنيت فيه أيضا من شعري فغناه في قوله صوت\n(يا ليت شعري وكم من منية قدرت ... وفقا وأخرى أتى من دونها القدر)\n(ومضمر الكشح يطويه الضجيع له ... طي الحمالة لا جاف ولا فقر)\n(له شبيهان لا نقص يعيبهما ... بحيث كانا ولا طول ولا قصر)\nم أعرف لهذا الشعر لحنا في شيء من الكتب ولا سمعته فقال له الحارث أحسنت والله يا غريض إيه وماذا أيضا فغناه قوله\n(عفت الديار فما بها أهل ... حزانها ودماثها السهل)\n(إني وما نحروا غداة مني ... عند الجمار تؤدها العقل)\nالأبيات المذكورة وقد مضت نسبتها معها فقال له الحارث يا غريض لا لوم في حبك ولا عذر في هجرك ولا لذة لمن لا يروح قلبه بك يا غريض لو لم يكن لي في ولايتي مكة حظ إلا أنت لكان حظا كافيا وافيا يا غريض إنما الدنيا زينة فأزين الزينة ما فرح النفس ولقد فهم قدر الدنيا على حقيقته من فهم قدر الغناء","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":5,"spl":"خبره في مكة مع عائشة — يحمل قادما إلى المدينة رقعة كتب فيها لعائشة"},
{"id":"b30-15","bab":"الجزء 3","sec":"سكينة بنت الحسين تنقد شعره","page":"ج3 ص323","text":"أخبرني الحسن بن علي عن أحمد بن زهير عن مصعب الزبيري قال أنشدت سكينة بيت الحسين قول الحارث بن خالد\n(ففرغن من سبع وقد جهدت ... أحشاؤهن موائل الخمر)\nفقال أحسن عندكم ما قال قالوا نعم فقالت وما حسنه فوالله لو طافت الإبل سبعا لجهدت أحشاؤها أخبرني الحسين عن حماد عن أبيه عن كلثوم بن أبي بكر قال لما مات عمر بن عبد الله التيمي عن عائشة بنت طلحة وكانت قبله عند مصعب بن الزبير قيل للحارث بن خالد ما يمنعك الآن منها قال لا يتحدث والله رجال من قريش أن نسيبي بها كان لشيء من الباطل","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":6,"spl":"سكينة بنت الحسين تنقد شعره — تشبيبه بزوجته أم عبد الملك"},
{"id":"b30-16","bab":"الجزء 3","sec":"شعره في أبان بن عثمان بعد أن تولى على موسم الحج","page":"ج3 ص324","text":"أخبرنا محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن محمد بن حبيب عن ابن الأعرابي قال\nلما خرج ابن الأشعث على عبد الملك بن مروان شغل عن أن يولي على\nالحج رجلا وكان الحارث بن خالد عامله على مكة فخرج أبان بن عثمان من المدينة وهو عامله عليها فغدا على الحارث بمكة ليحج بالناس فنازعه الحارث وقال له لم يأتني كتاب أمير المؤمنين بتوليتك على الموسم وتغالبا فغلبه أبان ابن عثمان بنسبه ومال إليه الناس فحج بهم فقال الحارث بن خالد في ذلك\n(فإن تنج منها يا أبان مسلما ... فقد أفلت الحجاج خيل شبيب)\n(وكاد غداة الدير ينفذ حضنه ... غلام بطعن القرن جد طبيب)\n(وأنسوه وصف والدير لما رآهم ... وحسن خوف الموت كل معيب)\nلقيه الحجاج بعد ذلك فقال مالي ولك يا حارث أينازعك أبان عملا فتذكرني فقال له ما اعتمدت مساءتك ولكن بلغني أنك أنت كاتبته قال والله ما فعلت فقال له الحارث المعذرة إلى الله وإليك أبا محمد نسخت من كتاب هارون بن محمد بن عبد الملك الزيات حدثني عمرو ابن سلم قال حدثني هارون بن موسى الفروي قال حدثني موسى بن جعفر أن يحيى قال حدثني مؤدب لبني هشام بن عبد الملك قال بينا أنا ألقي على ولد هشام شعر قريش إذ أنشدتهم شعر الحارث بن خالد\n(إن امرأ تعتاده ذكر ... منها ثلاث منى لذو صبر)\nهشام مصغ إلي حتى ألقيت عليهم قوله\n(ففرغن من سبع وقد جهدت ... أحشاؤهن موائل الخمر)\nفانصرف وهو يقول هذا كلام معاين","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":6,"spl":"سكينة بنت الحسين تنقد شعره — تشبيبه بزوجته أم عبد الملك"},
{"id":"b30-17","bab":"الجزء 3","sec":"شعره في عائشة بعد أن قدمت تريد العمرة","page":"ج3 ص325","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أبو عبد الله السدوسي قال وحدثنا أبو حاتم السجستاني قال أخبرنا أبو عبيدة قال قدمت عائشة بنت طلحة مكة تريد العمرة فلم يزل الحارث يدور حولها وينظر إليها ولا يمكنه كلامها حتى خرجت فأنشأ يقول وذكر في هذه الأبيات بسرة حاضنتها وكنى عنها صوت\n(يا دار أقفر رسمها ... بين المحصب والحجون)\n(أقوت وغير آيها ... مر الحوادث والسنين)\n(واستبدلوا ظلف الحجاز ... وسرة البلد الأمين)\n(يا بسر إني فاعلمي ... بالله مجتهدا يميني)\n(ما إن صرمت حبالكم ... فصلي حبالي أو ذريني)\nي هذه الأبيات ثاني ثقيل لمالك بالبنصر عن الهشامي وحبش قال وفيها لابن مسجح ثقيل أول وذكر أحمد بن المكي أن فيها لابن سريج رملا بالبنصر فيها لمعبد ثقيل أول بالوسطى عن حبش","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":6,"spl":"سكينة بنت الحسين تنقد شعره — تشبيبه بزوجته أم عبد الملك"},
{"id":"b30-18","bab":"الجزء 3","sec":"تشبيبه بزوجته أم عبد الملك","page":"ج3 ص326","text":"أخبرني الطوسي والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال\nحدثني مصعب بن عثمان بن مصعب بن عروة بن الزبير وأخبرني به محمد بن خلف بن المرزبان عن أحمد بن زهير عن مصعب الزبيري قال كانت أم عبد الملك بنت عبد الله بن خالد بن أسيد عند الحارث بن خالد فولدت منه فاطمة بنت الحارث وكانت قبله عند عبد الله بن مطيع فولدت منه عمران ومحمدا فقال فيها الحارث وكناها بابنها عمران\n(يا أم عمران ما زالت وما برحت ... بي الصبابة حتى شفني الشفق)\n(القلب تاق إليكم كي يلاقيكم ... كما يتوق إلى منجاته الغرق)\n(تنيل نزرا قليلا وهي مشفقة ... كما يخاف مسيس الحية الفرق)\nال مصعب بن عثمان فأنشد رجل يوما بحضرة ابنها عمران بن عبد الله بن مطيع هذا الشعر ثم فطن فأمسك فقال له لا عليك فإنها كانت زوجته وقال ابن المرزبان في خبره فقال له امض رحمك الله وما بأس بذلك رجل تزوج بنت عمه وكان لها كفئا كريما فقال فيها شعرا بلغ ما بلغ فكان ماذا","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":6,"spl":"سكينة بنت الحسين تنقد شعره — تشبيبه بزوجته أم عبد الملك"},
{"id":"b30-19","bab":"الجزء 3","sec":"تشبيبه بأم بكر أحسن الناس وجها","page":"ج3 ص327","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن عبد الرحمن التميمي عن أبي شعيب الأسدي عن القحذمي قال بينا الحارث بن خالد واقف على جمرة العقبة إذ رأى أم بكر وهي ترمي الجمرة فرأى أحسن الناس وجها وكان في خدها خال ظاهر فسأل عنها فأخبر باسمها حتى عرف رحلها ثم أرسل إليها يسألها أن تأذن له في الحديث فأذنت له فكان يأتيها يتحدث إليها حتى انقضت أيام الحج فأرادت الخروج إلى بلدها فقال فيها\n(ألا قل لذات الخال يا صاح في الخد ... تدوم إذا بانت على أحسن العهد)\n(ومنها علامات بمجرى وشاحها ... وأخرى تزين الجيد من موضع العقد)\n(وترعى من الود الذي كان بيننا ... فما يستوي راعي الأمانة والمبدي)\n(وقل قد وعدت اليوم وعدا فأنجزي ... ولا تخلفي لا خير في مخلف الوعد)\n(وجودي علي اليوم منك بنائل ... ولا تبخلي قدمت قبلك في اللحد)\n(فمن ذا الذي يبدي السرور إذا دنت ... بك الدار أو يعنى بنأيكم بعدي)\n(دنوكم منا رخاء نناله ... ونأيكم والبعد جهد على جهد)\n(كثير إذا تدنوا اغتباطي بك النوى ... ووجدي إذا ما بنتم ليس كالوجد)\n(أقول ودمعي فوق خدي مخضل ... له وشل قد بل تهتانه خدي)\n(لقد منح الله البخيلة ودنا ... وما منحت ودي بدعوى ولا قصد)\nخبرني محمد بن خلف قال وحدثت عن المدائني ولست أحفظ من حدثني به قال طافت ليلى بنت أبي مرة بن عروة بن مسعود وأمها ميمونة بنت أبي سفيان ابن حرب بالكعبة فرآها الحارث بن خالد فقال فيها\n(أطافت بنا شمس النهار ومن رأى ... من الناس شمسا بالعشاء تطوف)\n(أبو أمها أوفى قريش بذمة ... وأعمامها إما سألت ثقيف)\nفيها يقول\n(أمن طلل بالجزع من مكة السدر ... عفا بين أكناف المشقر فالحضر)\n(ظللت وظل القوم من غير حاجة ... لدن غدوة حتى دنت حزة العصر)\n(يبكون من ليلى عهودا قديمة ... وماذا يبكي القوم من منزل قفر)\nلغناء في هذه الأبيات لابن سريج ثاني ثقيل بالخنصر والبنصر عن يحيى المكي وذكر غيره أنه للغريض وفي ليلى هذه يقول أنشدناه وكيع عن عبد الله بن شبيب عن إبراهيم بن المنذر الحزامي للحارث بن خالد وفي بعض الأبيات غناء صوت\n(لقد أرسلت في السر ليلى تلومني ... وتزعمني ذا ملة طرفا جلدا)\n(وقد أخلفتنا كل ما وعدت به ... ووالله ما أخلفتها عامدا وعدا)\n(فقلت مجيبا للرسول الذي أتى ... تراه لك الويلات من قولها جدا)\n(إذا جئتها فاقر السلام وقل لها ... دعي الجور ليلى واسلكي منهجا قصدا)\n(أفي مكثنا عنكم ليال مرضتها ... تزيدينني ليلى على مرضي جهدا)\n(تعدين ذنبا واحدا ما جنيته ... علي وما أحصي ذنوبكم عدا)\n(فإن شئت حرمت النساء سواكم ... وإن شئت لم أطعم نقاخا ولا بردا)\n(وإن شئت غرنا بعدكم ثم لم نزل ... بمكة حتى تجلسي قابلا نجدا)\nلغناء للغريض ثاني ثقيل بالسبابة في مجرى الوسطى وذكر ابن المكي أن\nفيه لدحمان ثاني ثقيل بالوسطى لا أدري أهذا أم غيره وفيه ثقيل أول للأبجر عن يونس والهشامي وفيه لابن سريج رمل بالبنصر ولعرار خفيف ثقيل عن الهشامي وحبش أخبرني محمد بن خلف قال أخبرني محمد بن الحارث الخراز قال حدثنا أبو الحسن المدائني قال كان الحارث بن خالد واليا على مكة وكان أبان بن عثمان ربما جاءه كتاب الخليفة أن يصلي بالناس ويقيم لهم حجهم فتأخر عنه في سنة الحرب كتابه ولم يأت الحارث كتاب فلما حضر الموسم شخص أبان من المدينة فصلى بالناس وعاونته بنو أمية ومواليهم فغلب الحارث على الصلاة فقال\n(فإن تنج منها يا أبان مسلما ... فقد أفلت الحجاج خيل شبيب)\nبلغ ذلك الحجاج فقال مالي وللحارث أيغلبه أبان بن عثمان على الصلاة ويهتف بي أنا ما ذكره أياي فقال له عبيد بن موهب أتاذن أيها الأمير في إجابته وهجائه قال نعم فقال عبيد\n(أبا وابص ركب علاتك والتمس ... مكاسبها إن اللئيم كسوب)\n(ولا تذكر الحجاج إلا بصالح ... فقد عشت من معروفه بذنوب)\n(ولست بوال ما حييت إمارة ... لمستخلف إلا عليك رقيب)\nال المدائني وبلغني أن عبد الملك قال للحارث أي البلاد أحب إليك قال ما حسنت فيه حالي وعرض وجهي ثم قال\n(لا كوفة أمي ولا بصرة أبي ... ولست كمن يثنيه عن وجهه الكسل)","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":7,"spl":"تشبيبه بأم بكر أحسن الناس وجها"},
{"id":"b30-20","bab":"الجزء 3","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج3 ص330","text":"منها في تشبيب الحارث بامرأته أم عمران صوت\n(بان الخليط الذي كنا به نثق ... بانوا وقلبك مجنون بهم علق)\n(تنيل نزرا قليلا وهي مشفقة ... كما يخاف مسيس الحية الفرق)\n(يا أم عمران ما زلت وما برحت ... بي الصبابة حتى شفني الشفق)\n(لا أعتق الله رقي من صبابتكم ... ما ضرني أنني صب بكم قلق)\n(ضحكت عن مرهف الأنياب ذي أشر ... لا قضم في ثناياه ولا روق)\n(يتوق قلبي إليكم كي يلاقيكم ... كما يتوق إلى منجاته الغرق)\nنى ابن محرز في الثالث ثم السادس ثم الخامس ثم الثاني ولحنه من القدر الأوسط من الثقيل الأول بالسبابة في مجرى الوسطى عن إسحاق وللغريض في الرابع والثاني والثالث والسادس خفيف ثقيل بالبنصر عن عمرو ولسلسل في الأول والثاني ثقيل أول مطلق عن الهشامي ولابن سريج في الثاني والأول والرابع والخامس رمل بالخنصر في مجرى البنصر عن إسحاق وللهذلي في الثاني ثم الأول هزج عن الهشامي وذكر حبش أن فيها لابن سريج ثاني ثقيل بالوسطى ولابن محرز ثاني ثقيل آخر بالبنصر وذكر الهشامي أن لابن سريج في الأبيات خفيف رمل","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":8,"spl":"نسبة ما في هذا الخبر من الأغاني"},
{"id":"b30-21","bab":"الجزء 3","sec":"معبد يغني شعره في عائشة","page":"ج3 ص331","text":"ومما يغني فيه من شعر الحارث بن خالد في عائشة بنت طلحة تصريحا وتعريضا ببسرة جاريتها\nصوت\n(يا ربع بسرة بالجناب تكلم ... وأبن لنا خبرا ولا تستعجم)\n(مالي رأيتك بعد أهلك موحشا ... خلقا كحوض الباقر المتهدم)\n(تسبي الضجيع إذا النجوم تغورت ... طوع الضجيع أنيقة المتوسم)\n(قب البطون أوانس مثل الدمى ... يخلطن ذاك بعفة وتكرم)\nلغناء لمعبد خفيف رمل بإطلاق الوتر في مجرى الوسطى والأبيات أكثر من هذه إلا أني اعتمدت على ما غني فيه ومنها صوت قد جمعت فيه عدة طرائق وأصوات في أبيات من القصيدة\n(أعرفت أطلال الرسوم تنكرت ... بعدي وبدل آيهن دثورا)\n(وتبدلت بعد الأنيس بأهلها ... عفرا بواغم يرتعين وعورا)\n(من كل مصبية الحديث ترى لها ... كفلا كرابية الكثيب وثيرا)\n(دع ذا ولكن هل رأيت ظعائنا ... قربن أجمالا لهن بكورا)\n(قربن كل مخيس متحمل ... بزلا تشبه هامهن قبورا)\n(يفتن لا يألون كل مغفل ... يملأنه بحديثهن سرورا)\n(يا دار حسرها البلى تحسيرا ... وسفت عليها الريح بعدك بورا)\n(دق التراب نخيله فمخيم ... بعراصها ومسير تسييرا)\n(يا ربع بسرة إن أضر بك البلى ... فلقد عهدتك آهلا معمورا)\n(عقب الرذاذ خلافهم فكأنما ... بسط الشواطب بينهن حصيرا)\n(إن يمس حبلك بعد طول تواصل ... خلقا ويصبح بينكم مهجورا)\n(فلقد أراني والجديد إلى بلى ... زمنا بوصلك قانعا مسرورا)\n(جذلا بمالي عندكم لا أبتغي ... للنفس غيرك حلة وعشيرا)\n(كنت المنى وأعز من وطئ الحصا ... عندي وكنت بذاك منك جديرا)\nنى في الأول والثاني من هذه الأبيات معبد ولحنه ثقيل أول بالبنصر عن عمرو مطلق في مجرى الوسطى عن إسحاق وللغريض فيه ثقيل أول بالبنصر عن عمرو ولإسحاق فيهما ثاني ثقيل ولإبراهيم فيهما وفي الثالث خفيف ثقيل بالسبابة والوسطى عن ابن المكي وغنى الغريض في الثالث والسادس والرابع والخامس ثاني ثقيل بإطلاق الوتر في مجرى الوسطى عن إسحاق وغنى معبد في السابع والثامن والعاشر خفيف ثقيل بالسبابة والوسطى عن يحيى المكي وفيها ثاني ثقيل ينسب إلى طويس وابن مسجح وابن سريج ولمالك في التاسع والعاشر والحادي عشر والثاني عشر خفيف ثقيل بالسبابة والوسطى عن يحيى المكي وفيها بأعيانها لابن سريج رمل بالسبابة والوسطى عن يحيى أيضا وليحيى المكي في الحادي عشر وما بعده إلى آخر الأبيات ثاني ثقيل ولإبراهيم فيها بعينها ثقيل أول عن الهشامي وفيها لإسحاق رمل وفي الثالث والرابع لحن لخليدة المكية خفيف رمل عن الهشامي أيضا ومنها من أبيات قالها بالشأم عند عبد الملك أولها\n(هل تعرف الدار أضحت آيها عجما ... كالرق أجرى عليها حاذق قلما)\n(بالخيف هاجت شؤونا غير جامدة ... فانهلت العين تذري واكفا سجما)\n(دار لبسرة أمست ما تكلمنا ... وقد أبنت لها لو تعرف الكلما)\n(واها لبسرة لو يدنو الأمير بها ... يا ليت بسرة قد أمست لنا أمما)\nصوت\n(حلت بمكة لا دار مصاقبة ... هيهات جيرون ممن يسكن الحرما)\n(يا بسر إنكم شط البعاد بكم ... فما تنيلوننا وصلا ولا نعما)\nنى في هذين البيتين الهذلي ثاني ثقيل بالوسطى وفيهما ليحيى المكي ثقيل أول بالبنصر جميعا من روايته\n(قد قلت بالخيف إذ قالت لجارتها ... أدام وصل الذي أهدي لنا الكلما)\nوت\n(لا يرغم الله أنفا أنت حامله ... بل أنف شانيك فيما سركم رغما)\n(إن كان رابك شيء لست أعلمه ... مني فهذي يميني بالرضا سلما)\n(أو كنت أحببت شيئا مثل حبكم ... فلا أرحت إذا أهلا ولا نعما)\n(لا تكليني إلى من ليس يرحمني ... وقاك من تبغضين الحتف والسقما)\n(إن الوشاة كثير إن أطعتهم ... لا يرقبون بنا إلا ولا ذمما)\nنى ابن محرز في\n(لا يرغم الله أنفا أنت حامله ... )\nفيف ثقيل بالبنصر ولابن مسجح فيه ثاني ثقيل عن حبش وفي\n(لا تكليني إلى من ليس يرحمني ... )\nابن محرز ثقيل أول بالبنصر عن حبش والهشامي","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":9,"spl":"معبد يغني شعره في عائشة","partial":1},
{"id":"b30-22","bab":"الجزء 3","sec":"عزله عبد الملك لأنه أخر الصلاة لعائشة","page":"ج3 ص335","text":"أخبرني محمد بن مزيد والحسين بن يحيى قالا أخبرنا حماد بن إسحاق عن أبيه عن الزبيري قال أذن المؤذن يوما وخرج الحارث بن خالد إلى الصلاة فأرسلت إليه عائشة ابنة طلحة إنه بقي علي شيء من طوافي لم أتمه فقعد وأمر المؤذنين فكفوا عن الإقامة وجعل الناس يصيحون حتى فرغت من طوافها فبلغ ذلك عبد الملك بن مروان فعزله وولى مكة عبد الرحمن بن عبد الله بن خالد بن أسيد وكتب إلى الحارث ويلك أتركت الصلاة لعائشة بنت طلحة فقال الحارث والله لو لم تقض طوافها إلى الفجر لما كبرت وقال في ذلك\n(لم أرحب بأن سخطت ولكن ... مرحبا أن رضيت عنا وأهلا)\n(إن وجها رأيته ليلة البدر ... عليه انثنى الجمال وحلا)\n(وجهها الوجه لو يسأل به المزن ... من الحسن والجمال استهلا)\n(إن عند الطواف حين أتته ... لجمالا فعما وخلقا رفلا)\n(وكسين الجمال إن غبن عنها ... فإذا ما بدت لهن اضمحلا)\nي شعر الحارث هذا غناء قد جمع كل ما في شعره منه على اختلاف طرائقه وهو صوت\n(أثل جودي على المتيم أثلا ... لا تزيدي فؤاده بك خبلا)\n(أثل إني والراقصات بجمع ... يتبارين في الأزمة فتلا)\n(سانحات يقطعن من عرفات ... بين أيدي المطي حزنا وسهلا)\n(والأكف المضمرات على الركن ... بشعث سعوا إلى البيت رجلى)\n(لا أخون الصديق في السر حتى ... ينقل البحر بالغرابيل نقلا)\n(أو تمر الجبال مر سحاب ... مرتق قد وعى من الماء ثقلا)\n(أنعم الله لي بذا الوجه عينا ... وبه مرحبا وأهلا وسهلا)\n(حين قالت لا تفشين حديثي ... يابن عمي أقسمت قلت أجل لا)\n(إتقي الله واقبلي العذر مني ... وتجافي عن بعض ما كان زلا)\n(لا تصدي فتقتليني ظلما ... ليس قتل المحب للحب حلا)\n(ما أكن سؤتكم به فلك العتبى ... لدينا وحق ذاك وقلا)\n(لم أرحب بأن سخطت ولكن ... مرحبا أن رضيت عنا وأهلا)\n(إن شخصا رأيته ليلة البدر ... عليه انثنى الجمال وحلا)\n(جعل الله كل أنثى فداء ... لك بل خدها لرجلك نعلا)\n(وجهك البدر لو سألت به المزن ... من الحسن والجمال استهلا)\nنى معبد في الأبيات الأربعة الأولى خفيف ثقيل بالوسطى عن عمرو ولابن تيزن في الأول والثاني ثقيل أول عن إسحاق ولابن سريج في الأول والثاني والخامس ثقيل أول عن الهشامي وللغريض في الخامس إلى الثامن خفيف ثقيل بالوسطى عن عمرو ولدحمان في التاسع والعاشر والثالث عشر والرابع عشر خفيف ثقيل بالبنصر عن عمرو ولمالك في التاسع إلا آخر الثاني عشر لحن ذكره يونس ولم يجنسه ولابن سريج في هذه الأبيات بعينها رمل بالوسطى عن عمرو وللغريض فيها أيضا خفيف رمل بالبنصر عن ابن المكي ولابن عائشة في الخامس إلى آخر الثامن لحن ذكره حماد عن أبيه ولم يذكر طريقته ومنها صوت\n(أحقا أن جيرتنا استحبوا ... خزون الأرض بالبلد السخاخ)\n(إلى عقر الأباطح من ثبير ... إلى ثور فمدفع ذي مراخ)\n(فتلك ديارهم لم يبق فيها ... سوى طلل المعرس والمناخ)\n(وقد تغنى بها في الدار حور ... نواعم في المجاسد كالإراخ)\nنى في هذه الأبيات الغريض ولحنه من الثقيل الأول بالوسطى عن الهشامي\nوأخبرني محمد بن خلف بن المرزبان قال حدثنا عبد الله بن محمد قال أخبرني محمد بن سلام قال كانت سوداء بالمدينة مشغوفة بشعر عمر بن أبي ربيعة وكانت من مولدات مكة فلما ورد على أهل المدينة نعي عمر بن أبي ربيعة أكبروا ذلك واشتد عليهم وكانت السوداء أشدهم حزنا وتسلبا وجعلت لا تمر بسكة من سكك المدينة إلا ندبته فلقيها بعض فتيان مكة فقال لها خفضي عليك فقد نشأ ابن عم له يشبه شعره شعره فقالت أنشدني بعضه فأنشدها قوله\n(إني وما نحروا غداة منى ... عند الجمار تؤودها العقل)\nلأبيات كلها قال فجعلت تمسح عينيها من الدموع وتقول الحمد لله الذي لم يضيع حرمه أخبرني اليزيدي قال حدثني عمي جد عبيد الله عن ابن حبيب عن ابن الأعرابي قال ناضل سليمان بن عبد الملك بين الحارث وبين رجل من أخواله من بني عبس فرمى الحارث بن خالد فأخطأ ورمى العبسي فأصاب فقال\n(أنا نضلت الحارث بن خالد ... )\nم رمى العبسي فأخطأ ورمى الحارث فأصاب فقال الحارث\n(حسبت نضل الحارث بن خالد ... )\nرميا فأخطأ العبسي وأصاب الحارث فقال الحارث\n(مشيك بين الزرب والمرابد ... )\nورميا فأخطأ العبسي وأصاب الحارث فقال الحارث\n(وإنك الناقص غير الزائد ... )\nقال سليمان أقسمت عليك يا حارث إلا كففت عن القول والرمي فكف","topic":"أخبار الحارث بن خالد المخزومي ونسبه","topicNo":30,"sp":10,"spl":"عزله عبد الملك لأنه أخر الصلاة لعائشة","partial":1},
{"id":"b31-1","bab":"الجزء 3","sec":"أخبار الأبجر ونسبه","page":"ج3 ص340","text":"الأبجر لقب غلب عليه واسمه عبيد الله بن القاسم بن ضبية ويكنى أبا طالب هكذا روى محمد بن عبد الله بن مالك عن إسحاق وروى هارون بن الزيات عن حماد عن أبيه أن اسمه محمد بن القاسم بن ضبية وهو مولى لكنانة ثم لبني بكر ويقال إنه مولى لبني ليث أخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثنا محمد بن عبد الله بن مالك وأخبرني الحسن بن علي قال حدثنا ابن مهرويه وهارون بن الزيات قالا حدثنا عبد الله بن أبي سعد عن محمد بن عبد الله بن مالك قال كنا يوما جلوسا عند إسحاق فغنتنا جارية يقال لها سمحة\n(إن العيون التي في طرفها مرض ... قتلننا ثم لم يحيين قتلانا)\nهبت إسحاق أن أسأله لم الغناء فقلت لبعض من كان معنا سله فسأله فقال له إسحاق ما كان عهدي بك في شبيبتك لتسألنا عن هذا فقال أحببته لما أسننت فقال لا ولكن هذا النقب عمل هذا اللص وضرب بيده إلى تلابيبي فقال له الرجل صدقت يا أبا محمد فأقبل علي فقال لي ألم أقل لك إذا اشتهيت شيئا فسل عنه أما لأعطينك فيه ما تعايي به من شئت منهم\nأتدري لمن الشعر فقلت لجرير فقال لي والغناء للأبجر وكان مدنيا منشؤه بمكة أو مكيا منشؤه بالمدينة أتدري ما اسمه قلت لا قال اسمه عبيد الله بن القاسم بن ضبية أتدري ما كنيته قلت لا قال أبو طالب ثم قال اذهب فعاي بهذا من شئت منهم فإنك تظفر به","topic":"أخبار الأبجر ونسبه","topicNo":31,"sp":0,"spl":"أخبار الأبجر ونسبه — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b31-2","bab":"الجزء 3","sec":"كان يلقب بالحسحاس","page":"ج3 ص341","text":"وقال هارون حدثني حماد عن أبيه قال الأبجر اسمه محمد بن القاسم بن ضبية وقال مرة أخرى عبيد الله بن القاسم مولى لبني بكر بن كنانة وقيل إنه مولى لبني ليث يلقب بالحسحاس قال هارون وحدثني حماد عن أبيه قال حدثني عورك اللهبي قال لم يكن بمكة أحد أظرف ولا أسرى ولا أحسن هيئة من الأبجر كانت حلته بمائة دينار وفرسه بمائة دينار ومركبه بمائة دينار وكان يقف بين المأزمين فيرفع صوته فيقف الناس له يركب بعضهم بعضا أخبرني علي بن عبد العزيز الكاتب عن عبيد الله بن عبد الله بن خرداذبه عن إسحاق وأخبرني الحسين بن يحيى عن حماد عن أبيه قالا جلس الأبجر في ليلة اليوم السابع من أيام الحج على قريب من التنعيم فإذا عسكر جرار قد أقبل في آخر الليل وفيه دواب تجنب وفيها فرس أدهم عليه سرج حليته ذهب فاندفع فغنى\n(عرفت ديار الحي خالية قفرا ... كأن بها لما توهمتها سطرا)\nفلما سمعه من في القباب والمحامل أمسكوا وصاح صائح ويحك أعد الصوت فقال لا والله إلا بالفرس الأدهم بسرجه ولجامه وأربعمائة دينار فإذا الوليد بن يزيد صاحب الإبل فنودي أين منزلك ومن أنت فقال أنا الأبجر ومنزلي على باب زقاق الخرازين فغدا عليه رسول الوليد بذلك الفرس وأربعمائة دينار وتخت من ثياب وشي وغير ذلك ثم أتى به الوليد فأقام عنده وراح مع أصحابه عشية التروية وهو أحسنهم هيئة وخرج معه أو بعده إلى الشأم","topic":"أخبار الأبجر ونسبه","topicNo":31,"sp":0,"spl":"أخبار الأبجر ونسبه — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b31-3","bab":"الجزء 3","sec":"خروجه مع الوليد بن يزيد إلى الشام","page":"ج3 ص341","text":"قال إسحاق وحدثني عورك اللهبي أن خروجه كان معه وذلك في ولاية محمد بن هشام بن إسماعيل مكة وفي تلك السنة حج الوليد لأن هشاما ما أمره بذلك ليهتكه عند أهل الحرم فيجد السبيل إلى خلعه فظهر منه أكثر مما أراد به من التشاغل بالمغنين واللهو وأقبل الأبجر معه حتى قتل الوليد ثم خرج إلى مصر فمات بها","topic":"أخبار الأبجر ونسبه","topicNo":31,"sp":0,"spl":"أخبار الأبجر ونسبه — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b31-4","bab":"الجزء 3","sec":"نسبة الصوت المذكور في هذا الخبر","page":"ج3 ص342","text":"صوت\n(عرفت ديار الحي خالية قفرا ... كأن بها لما توهمتها سطرا)\n(وقفت بها كيما ترد جوابها ... فما بينت لي الدار عن أهلها خبرا)\nلغناء لأبي عباد ثقيل أول بالبنصر عن عمرو وفيه لسياط خفيف رمل بالبنصر قال إسحاق وحدثت أن الأبجر أخذ صوتا من الغريض ليلا ثم دخل في الطواف حين أصبح فرأى عطاء بن أبي رباح يطوف بالبيت فقال يا أبا محمد اسمع صوتا أخذته في هذه الليلة من الغريض قال له ويحك أفي هذا\nالموضع فقال كفرت برب هذا البيت لئن لم تسمعه مني سرا لأجهرن به فقال هاته فغناه صوت\n(عوجي علينا ربة الهودج ... إنك إلا تفعلي تحرجي)\n(إني أتيحت لي يمانية ... إحدى بني الحارث من مذحج)\n(نلبث حولا كاملا كله ... لا نلتقي إلا على منهج)\n(في الحج إن حجت وماذا منى ... وأهله إن هي لم تحجج)\nقال له عطاء الخير الكثير والله في منى وأهله حجت أو لم تحج فاذهب الآن وقد مرت نسبة هذا الصوت وخبره في أخبار العرجي والغريض قال إسحاق وذكر عمرو بن الحارث عن عبد الله بن عبيد بن عمير قال ختن عطاء بن أبي رباح بنيه أو بني أخيه فكان الأبجر يختلف إليهم ثلاثة أيام يغني لهم","topic":"أخبار الأبجر ونسبه","topicNo":31,"sp":0,"spl":"أخبار الأبجر ونسبه — نسبة الصوت المذكور في هذا الخبر"},
{"id":"b31-5","bab":"الجزء 3","sec":"تنازعه مع ابن عائشة في الغناء","page":"ج3 ص343","text":"قال هارون بن محمد حدثني حماد بن إسحاق قال نسخت من كتاب ابن أبي نجيح بخطه حدثني غرير بن طلحة الأرقمي عن يحيى بن عمران عن عمر بن حفص بن أبي كلاب قال كان الأبجر مولانا وكان مكيا فكان إذا قدم المدينة نزل علينا فقال لنا يوما أسمعوني غناء ابن عائشتكم هذا فأرسلنا فيه فجمعنا بينهما في بيت ابن هبار فتغنى ابن عائشة فقال الأبجر كل مملوك لي حر إن تغنيت معك إلا\nبنصف صوتي ثم أدخل إصبعه في شدقه فتغنى فسمع صوته من في السوق فحشر الناس علينا فلم يفترقا حتى تشاتما قال وكان ابن عائشة حديدا جاهلا أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال وحدثني ابن أبي سعد قال حدثنا القطراني المغني عن محمد بن جبر عن إبراهيم بن المهدي قال حدثني ابن أشعب عن أبيه قال دعي ذات يوم المغنون للوليد بن يزيد وكنت نازلا معهم فقلت للرسول خذني فيهم قال لم أومر بذلك وإنما أمرت بإحضار المغنين وأنت بطال لا تدخل في جملتهم فقلت أنا والله أحسن غناء منهم ثم اندفعت فغنيته فقال لقد سمعت حسنا ولكني أخاف فقلت لا خوف عليك ولك مع هذا شرط قال وما هو كل ما أصبته فلك شطره فقال للجماعة اشهدوا عليه فشهدوا ومضينا فدخلنا على الوليد وهو لقس النفس فغناه المغنون في كل فن من خفيف وثقيل فلم يتحرك ولا نشط فقام الأبجر إلى الخلاء وكان خبيثا داهيا فسأل الخادم عن خبره وبأي سبب هو خاثر فقال بينه وبين امرأته شر لأنه عشق أختها فغضبت عليه فهو إلى أختها أميل وقد عزم على طلاقها وحلف لها ألا يذكرها أبدا بمراسلة ولا مخاطبة وخرج على هذا الحال من عندها فعاد الأبجر إلينا وما جلس حتى اندفع فغنى\nصوت\n(فبيني فإني لا أبالي وأيقني ... أصعد باقي حبكم أم تصوبا)\n(ألم تعلمي أني عزوف عن الهوى ... إذا صاحبي من غير شيء تغضبا)\nطرب الوليد وارتاح وقال أصبت يا عبيد والله ما في نفسي وأمر له بعشرة آلاف درهم وشرب حتى سكر ولم يحظ بشيء أحد سوى الأبجر فلما أيقنت بانقضاء المجلس وثبت فقلت إن رأيت يا أمير المؤمنين أن تأمر من يضربني مائة الساعة بحضرتك فضحك وقال قبحك الله وما السبب في ذلك فأخبرته بقصتي مع الرسول وقلت إنه بدأني من المكروه في أول يومه بما اتصل علي إلى آخره فأريد أن أضرب مائة ويضرب بعدي مثلها فقال له لقد لطفت أعطوه مائة دينار وأعطوا الرسول خمسين دينارا من مالنا عوضنا عن الخمسين التي أراد أن يأخذها فقبضتها وما حظي أحد بشيء غيري وغير الرسول والشعر الذي غنى فيه الأبجر الوليد بن يزيد لعبد الرحمن بن الحكم أخي مروان بن الحكم والغناء للأبجر ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق وفيه لغيره عدة ألحان نسبت","topic":"أخبار الأبجر ونسبه","topicNo":31,"sp":1,"spl":"تنازعه مع ابن عائشة في الغناء"},
{"id":"b32-1","bab":"الجزء 3","sec":"صوت من المائة المختارة من رواية جحظة","page":"ج3 ص345","text":"(حمزة المبتاع بالمال الثنا ... ويرى في بيعه أن قد غبن)\n(فهو إن أعطى عطاء فاضلا ... ذا إخاء لم يكدره بمن)\n(وإذا ما سنة مجدية ... برت الناس كبري بالسفن)\n(كان للناس ربيعا مغدقا ... ساقط الأكناف إن راح ارجحن)\n(نور شرق بين في وجهه ... لم يصب أثوابه لون الدرن)\nروضه من الرمل الشعر لموسى شهوات والغناء لمعبد خفيف ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة — سبب لقبه بشهوات"},
{"id":"b32-2","bab":"الجزء 3","sec":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","page":"ج3 ص346","text":"هو موسى بن يسار مولى قريش ويختلف في ولائه فيقال أنه مولى بني سهم ويقال مولى بني تيم بن مرة ويقال مولى بني عدي بن كعب ويكنى أبا محمد وشهوات لقب غلب عليه","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة — سبب لقبه بشهوات"},
{"id":"b32-3","bab":"الجزء 3","sec":"سبب لقبه بشهوات","page":"ج3 ص347","text":"وحدثني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال إنما لقب موسى شهوات لأنه كان سؤوالا ملحفا فكان كلما رأى مع أحد شيئا يعجبه من مال أو متاع أو ثوب أو فرس تباكى فإذا قيل له مالك قال أشتهي هذا فسمي موسى شهوات قال وذكر آخرون أنه كان من أهل أذربيجان وأنه نشأ بالمدينة وكان يجلب إليه القند والسكر فقالت له امرأة من أهله ما يزال موسى يجيئنا بالشهوات فغلبت عليه أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال كان محمد بن يحيى يقول موسى شهوات مولى بني عدي بن كعب وليس ذاك بصحيح هو مولى تيم بن مرة وذكر عبد الله بن شبيب عن الحزامي أنه مولى بني سهم\nوأخبرني وكيع عن أحمد بن أبي خيثمة عن مصعب ومحمد بن سلام قال موسى شهوات مولى بني سهم","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":0,"spl":"صوت من المائة المختارة من رواية جحظة — سبب لقبه بشهوات"},
{"id":"b32-4","bab":"الجزء 3","sec":"سعيد بن خالد بن عبد الله بن أسيد يعينه في ثمن جارية فيمدحه","page":"ج3 ص348","text":"وأخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة قال هوي موسى شهوات جارية بالمدينة فاستهيم بها وساوم مولاها فيها فاستام بها عشرة آلاف درهم فجمع كل ما يملكه واستماح إخوانه فبلغ أربعة آلاف درهم فأتى إلى سعيد بن خالد العثماني فأخبره بحاله واستعان به وكان صديقه وأوثق الناس عنده فدافعه واعتل عليه فخرج من عنده فلما ولى تمثل سعيد قوله الشاعر\n(كتبت إلي تستهدي الجواري ... لقد أنعظت من بلد بعيد)\nأتى سعيد بن خالد بن عبد الله بن خالد بن أسيد فأخبره بقصته فأمر له بستة آلاف درهم فلما قبضها ونهض قال له اجلس إذا ابتعتها بهذا المال وقد أنفدت كل ما تملك فبأي حال تعيشان ثم دفع إليه ألفي درهم وكسوة وطيبا وقال أصلح بهذا شأنكما فقال فيه\n(أبا خالد أعني سعيد بن خالد ... أخا العرف لا أعني ابن بنت سعيد)\nعمرو بن عثمان بن عفان فقال يا أمير المؤمنين أتيتك مستعديا قال ومن بك قال موسى شهوات قال وماله قال سمع بي واستطال في عرضي فقال يا غلام علي بموسى فأقين به فأتي به فقال ويلك أسمعت به واستطلت في عرضه قال ما فعلت يا أمير المؤمنين ولكني مدحت ابن عمه فغضب هو قال وكيف ذلك قال علقت جارية لم يبلغ ثمنها جدتي فأتيته وهو صديقي فشكوت إليه ذلك فلم أصب عنده شيئا فأتيت ابن عمه سعيد بن خالد بن عبد الله بن خالد بن أسيد فشكوت إليه ما شكوته إلى هذا فقال تعود إلي فتركته ثلاثا ثم أتيته فسهل من إذني فلما استقر بي المجلس قال يا غلام قل لقيمتي هاتي وديعتي ففتح بابا بين بيتين وإذا بجارية فقال لي أهذه بغيتك قلت نعم فداك أبي وأمي قال اجلس ثم قال يا غلام قل لقيمتي هاتي ظبية نفقتي فأتي بظبية فنثرت بين يديه فإذا فيها مائة دينار ليس فيها غيرها فردت في الظبية ثم قال عتيدة طيبي فأتي بها فقال ملحفة فراشي فأتي بها فصير ما في الظبية وما في العتيدة في حواشي الملحفة ثم قال شأنك بهواك واستعن بهذا عليه فقال له سليمان بن عبد الملك فذلك حين تقول ماذا قال قلت\n(يا خالد أعني سعيد بن خالد ... أخا العرف لا أعني ابن بنت سعيد)\n(ولكنني أعني ابن عائشة الذي ... أبو أبويه خالد بن أسيد)\n(عقيد الندى ما عاش يرضى به الندى ... فإن مات لم يرض الندى بعقيد)\n(دعوه دعوه إنكم قد رقدتم ... وما هو عن أحسابكم برقود)\nفقال سليمان علي يا غلام بسعيد بن خالد فأتي به فقال أحق ما وصفك به موسى قال وما ذاك يا أمير المؤمنين فأعاد عليه فقال قد كان ذلك يا أمير المؤمنين قال فما طوقتك هذه الأفعال قال دين ثلاثين ألف دينار فقال له قد أمرت لك بمثلها وبمثلها وبمثلها وبثلث مثلها فحملت إليه مائة ألف دينار قال فلقيت سعيد بن خالد بعد ذلك فقلت له ما فعل المال الذي وصلك به سليمان قال ما أصبحت والله أملك منه إلا خمسين دينارا قلت ما اغتاله قال خلة من صديق أو فاقة من ذي رحم أخبرني وكيع قال حدثنا أحمد بن أبي خيثمة عن مصعب الزبيري ومحمد بن سلام قال عشق موسى شهوات جارية بالمدينة فأعطى بها عشرة آلاف درهم ثم ذكر باقي الحديث مثل حديث سليمان بن أبي شيخ وقال فيه أما والله لئن مدحته وهو سميك وأبوه سمي أبيك ولم أفرق بينكما ليقولن الناس أهذا أم هذا ولكن والله لأقولن قولا لا يشك فيه وتمام هذه الأبيات التي مدح بها سعيدا بعد الأربعة المذكورة منها\n(فدى للكريم العبشتمي ابن خالد ... بني ومالي طارفي وتليدي)\n(على وجهه تلقى الأيامن واسمه ... وكل جواري طيره بسعود)\n(أبان وما استغنى عن الثدي خيره ... أبان به في المهد قبل قعود)\n(دعوه دعوه إنكم قد رقدتم ... وما هو عن أحسابكم برقود)\n(ترى الجند والجناب يغشون بابه ... بحاجاتهم من سيد ومسود)\n(فيعطي ولا يعطى ويغشى ويجتدى ... وما بابه للمجتدي بسديد)\n(قتلت أناسا هكذا في جلودهم ... من الغيظ لم تقتلهم بحديد)\n(يعيشون ما عاشوا بغيظ وإن تحن ... مناياهم يوما تحن بحقود)\n(فقل لبغاة العرف قد مات خالد ... ومات الندى إلا فضول سعيد)","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":1,"spl":"سعيد بن خالد بن عبد الله بن أسيد يعينه في ثمن جارية فيمدحه"},
{"id":"b32-5","bab":"الجزء 3","sec":"سعيد بن خالد بن عبد الله بن أسيد يعينه في ثمن جارية فيمدحه","page":"ج3 ص348","text":"ال وكيع في خبره أما قوله لا أعني ابن بنت سعيد فإن أم سعيد بن خالد بن عمرو بن عثمان آمنة بنت سعيد بن العاصي وعائشة أم عقيد الندى بنت عبد الله بن خلف الخزاعية أخت طلحة الطلحات وأمها صفية بنت الحارث بن طلحة بن أبي طلحة من بني عبد الدار بن قصي وأم أبي عقيد الندى رملة بنت معاوية بن أبي سفيان أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال لما أنشد موسى شهوات سليمان بن عبد الملك شعره في سعيد بن خالد قال له اتفق اسماهما وإسما أبويهما فتخوفت أن يذهب شعري باطلا ففرقت بينهما بأمهما فأغضبه أن مدحت ابن عمه فقال له سليمان بلى والله لقد هجوته وما خفي علي ولكني لا أجد إليك سبيلا فأطلقه أخبرني وكيع قال حدثني أحمد بن زهير قال حدثنا محمد بن سلام قال حدثنا محمد بن مسلمة الثقفي قال قال موسى شهوات لمعبد أأمدح حمزة بن عبد الله بن الزبير بأبيات\nوتغني فيها ويكون ما يعطينا بيني وبينك قال نعم فقال موسى\n(حمزة المبتاع بالمال الثنا ... ويرى في بيعه أن قد غبن)\n(فهو إن أعطى عطاء فاضلا ... ذا إخاء لم يكدره بمتن)\n(وإذا ما سنة مجحفة ... برت الناس كبري بالسفن)\n(حسرت عنه نقيا عرضه ... ذا بلاء عند مخناها حسن)\n(نور صدق بين في وجهه ... لم يدنس ثوبه لون الدرن)\n(كنت للناس ربيعا مغدقا ... ساقط الأكناف إن راح ارجحن)\nال أحمد بن زهير وأول هذه القصيدة عن غير ابن سلام\n(شاقني اليوم حبيب قد ظعن ... ففؤادي مستهام مرتهن)\n(إن هندا تديمتني حقبة ... ثم بانت وهي للنفس شجن)\n(فتنة ألحقها الله بنا ... عائذ من شر الفتن)","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":2,"spl":"سعيد بن خالد بن عبد الله بن أسيد يعينه في ثمن جارية فيمدحه — فاطمة بنت الحسين تجيزه على شع"},
{"id":"b32-6","bab":"الجزء 3","sec":"فاطمة بنت الحسين تجيزه على شعره","page":"ج3 ص353","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال أخبرني الطلحي قال أخبرني عبد الرحمن بن حماد عن عمران بن موسى بن طلحة قال لما زفت فاطمة بنت الحسين رضوان الله عليه إلى عبد الله بن عمرو بن عثمان بن عفان عارضها موسى شهوات\n(طلحة الخير جدكم ... ولخير الفواطم)\n(أنت للطاهرات من ... فرع تيم وهاشم)\n(أرتجيكم لنفعكم ... ولدفع المظالم)\nأمر له بكسوة ودنانير وطيب","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":2,"spl":"سعيد بن خالد بن عبد الله بن أسيد يعينه في ثمن جارية فيمدحه — فاطمة بنت الحسين تجيزه على شع"},
{"id":"b32-7","bab":"الجزء 3","sec":"تنقله بين الهجاء والمدح","page":"ج3 ص354","text":"قال حدثنا الكراني قال حدثنا العنزي عن العتبي قال كانت فاطمة بنت عبد الملك بن مروان تحت عمر بن عبد العزيز فلما مات عنها تزوجها داود بن سليمان بن مروان وكان قبيح الوجه فقال في ذلك موسى شهوات\n(أبعد الأغر ابن عبد العزيز ... قريع قريش إذا يذكر)\n(تزوجت داود مختارة ... ألا ذلك الخلف الأعور)\nكانت إذا سخطت عليه تقول صدق والله موسى إنك لأنت الخلف الأعور فيشتمه داود أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال أقام موسى شهوات ليزيد بن خالد بن يزيد بن معاوية على بابه بدمشق وكان فتى جوادا سمحا فلما ركب وثب إليه فأخذ بعنان دابته ثم قال\n(قم فصوت إذا أتيت دمشقا ... يا يزيد بن خالد بن يزيد)\n(يا يزيد بن خالد إن تجبني ... يلقني طائري بنجم السعود)\nفأمر له بخمسة آلاف درهم وكسوة وقال له كلما شئت فنادنا نجبك أخبرنا وكيع قال حدثني أحمد بن زهير قال حدثنا مصعب الزبيري قال زوج موسى شهوات بنت مولى لمعن بن عبد الرحمن بن عوف يقال له داود ابن أبي حميدة فلما جليت عليه قال داود ما للجلوة فأنشأ يقول\n(تقول لي النساء غداة تجلى ... حميدة يا فتى ما للجلاء)\n(فقلت لهم سمرقند وبلخ ... وما بالصين من نعم وشاء)\n(أبوها حاتم إن سيل خيرا ... وليث كريهة عند اللقاء)\nخبرني وكيع قال حدثنا أحمد بن زهير قال حدثنا مصعب قال قضى أبو بكر بن عبد الرحمن بن أبي سفيان بن حويطب على موسى شهوات بقضية وكان خالد بن عبد الملك استقضاه في أيام هشام بن عبد الملك فقال موسى يهجوه\n(وجدتك فها في القضاء مخلطا ... فقدتك من قاض ومن متأمر)\n(فدع عنك ما شيدته ذات رخة ... أذى الناس لا تحشرهم محشر)\nثم ولي القضاء سعيد بن سليمان بن زيد بن ثابت الأنصاري فقال يمدحه\n(من سره الحكم صرفا لا مزاج له ... من القضاة وعدل غير مغموز)\n(فليأت دار سعيد الخير إن بها ... أمضى على الحق من سيف ابن جرموز)\nال وكان سعد بن إبراهيم بن عبد الرحمن بن عوف قد ولي المدينة واشتد على السفهاء والشعراء والمغنين ولحق موسى شهوات بعض ذلك منه وكان قبيح الوجه فقال موسى يهجوه\n(قل لسعد وجه العجوز لقد كنت ... لما قد أوتيت سعدا مخيلا)\n(إن تكن ظالما جهولا فقد كان ... أبوك الأدنى ظلوما جهولا)\nقال يهجوه\n(لعن الله والعباد ثطيط الوجه ... لا يرتجى قبيح الجوار)\n(يتقي الناس فحشه وأذاه ... مثل ما يتقون بول الحمار)\n(لا تغرنك سجدة بين عينيه ... حذار منها ومنه حذار)\n(إنها سجدة بها يخدع الناس ... عليها من سجدة بالدبار)\nخبرني عمي قال أخبرني ثعلب عن عبد الله بن شبيب قال ذكر الحزامي أن موسى شهوات سأل بعض آل الزبير حاجة فدفعه عنها وبلغ ذلك عبد الله بن عمرو بن عثمان فبعث إليه بما كان التمسه من الزبيري من غير مسألة فوقف عليه موسى وهو جالس في المسجد ثم أنشأ يقول\n(ليس فيما بدا لنا منك عيب ... عابه الناس غير أنك فاني)\n(أنت نعم المتاع لو كنت تبقى ... غير أن لا بقاء للإنسان)\nالشعر المذكور فيه الغناء يقوله موسى شهوات في حمزة بن عبد الله بن الزبير وكان فتى كريما جوادا على هوج كان فيه وولاه أبوه العراقين وعزل مصعبا لما تزوج سكينة بنت الحسين رضي الله عنه وعائشة بنت طلحة وأمهر كل واحدة منهما ألف ألف درهم","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":3,"spl":"تنقله بين الهجاء والمدح"},
{"id":"b32-8","bab":"الجزء 3","sec":"ابن الزبير يعزل أخاه مصعبا عن البصرة ويولي ابنه حمزة","page":"ج3 ص357","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ عن مصعب الزبيري وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرني عبيد الله بن محمد الرازي والحسين بن علي قال عبيد الله حدثنا أحمد بن الحارث عن المدائني وقال الحسين حدثنا الحارث بن أبي أسامة عن المدائني عن أبي محنف\nأن أنس بن زنيم الليثي كتب إلى عبد الله بن الزبير\n(أبلغ أمير المؤمنين رسالة ... من ناصح لك لا يريك خداعا)\n(بضع الفتاة بألف ألف كامل ... وتبيت قادات الجيوش جياعا)\n(لو لأبي حفص أقول مقالتي ... وأبت ما أبثثتكم لارتاعا)\nلما وصلت الأبيات إليه جزع ثم قال صدق والله لو لأبي حفص يقول\nإن مصعبا تزوج امرأتين بألفي ألف درهم لا رتاع وإنا بعثنا مصعبا إلى العراق فأغمد سيفه وسل أيره وسنعزله فدعا بابنه حمزة وأمه بنت منظور بن زبان الفزاري وكان لها منه محل لطيف فولاه البصرة وعزل مصعبا فبلغ قوله عبد الملك في أخيه مصعب فقال لكن أنا خبيب أغمد سيفه وأيره وخيره وأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال هذه الأبيات لعبد الله بن همام السلولي قالوا جميعا فلما ولي ابنه حمزة البصرة أساء السيرة وخلط تخليطا شديدا وكان جوادا شجاعا أهوج فوفدت إلى أبيه الوفود في أمره وكتب إليه الأحنف بأمره وما ينكره الناس منه وأنه يخشى أن تفسد عليه طاعتهم فعزله عن البصرة أخبرني أحمد بن عبد العزيز قال حدثنا المدائني قال لما قدم حمزة بن عبد الله البصرة واليا عليها وكان جوادا شجاعا مخلطا يجود أحيانا حتى لا يدع شيئا يملكه إلا وهبه ويمنع أحيانا ما لا يمنع من مثله فظهرت منه بالبصرة خفة وضعف وركب يوما إلى فيض البصره فلما رآه قال إن هذا الغدير إن رفقوا به ليكفينهم صيفتهم هذه فلما كان بعد ذلك ركب إليه فوافقه جازرا فقال قد رأيته ذات يوم فظننت أن لن يكفيهم فقال له الأحنف إن هذا ماء يأتينا ثم يغيض عنا ثم يعود وشخص إلى الأهواز فرأى جبلها فقال هذا قعيقعان وقعيقعان جبل بمكة فلقب ذلك الجبل بقعيقعان قال أبو زيد وحدثني غير المدائني أنه سمع بذكر الجبل بالبصرة فدعا بعامله فقال له ابعث فأتنا بخراج الجبل فقال له إن الجبل ليس ببلد فآتيك\nبخراجه وبعث إلى مردانشاه فاستحثه بالخراج فأبطأ به فقام إليه بسيفه فقتله فقال له الأحنف ما أحد سيفك أيها الأمير وهدم بعبد العزيز بن شبيب بن خياط أن يضربه بالسياط فكتب إلى ابن الزبير بذلك وقال له إذا كانت لك بالبصرة حاجة فاصرف ابنك عنها وأعد إليها مصعبا ففعل ذلك وقال بعض الشعراء يهجو حمزة ويعيبه بقوله في أمر الماء الذي رآه قد جزر\n(يابن الزبير بعثت حمزة عاملا ... يا ليت حمزة كان خلف عمان)\n(أزرى بدجلة حين عب عبابها ... وتقاذفت بزواخر الطوفان)","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":4,"spl":"ابن الزبير يعزل أخاه مصعبا عن البصرة ويولي ابنه حمزة — خبر الفرزدق مع النوار ابنة أعين الم"},
{"id":"b32-9","bab":"الجزء 3","sec":"خبر الفرزدق مع النوار ابنة أعين المجاشعية","page":"ج3 ص359","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال خطب النوار ابنة أعين المجاشعية رجل من قومها فجعلت أمرها إلى الفرزدق وكان ابن عمها دنية ليزوجها منه فأشهد عليها بذلك وبأن أمرها إليه شهودا عدولا فلما أشهدتهم على نفسها قال بهم الفرزدق فإني أشهدكم أني قد تزوجتها فمنعته النوار نفسها وخرجت إلى الحجاز إلى عبد الله بن الزبير فاستجارت بامرأته بنت منظور بن زبان وخرج الفرزدق فعاد بابنه حمزة وقال يمدحه\n(يا حمز هل لك في ذي حاجة غرضت ... أنضاؤه بمكان غير ممطور)\n(فأنت أولى قريش أن تكون لها ... وأنت بين أبي بكر ومنظور)\nجعل أمر النوار يقوى وأمر الفرزدق يضعف فقال الفرزدق في ذلك\n(أما بنوه فلم تنفع شفاعتهم ... وشفعت بنت منظور بن زبانا)\n(ليس الشفيع الذي يأتيك مؤتزرا ... مثل الشفيع الذي يأتيك عريانا)\nفبلغ ابن الزبير شعره ولقيه على باب المسجد وهو خارج منه فضغط حلقه حتى كاد يقتله ثم خلاه وقال\n(لقد أصبحت عرس الفرزدق ناشزا ... ولو رضيت رمح استه لاستقرت)\nم دخل إلى النوار فقال لها إن شئت فرقت بينك وبينه ثم ضربت عنقه فلا يهجونا أبدا وإن شئت أمضيت نكاحه فهو ابن عمك وأقرب الناس إليك وكانت امرأة صالحة فقالت أو ما غير هذا قال لا قالت ما أحب أن يقتل ولكني أمضي أمره فلعل الله أن يجعل في كرهي إياه خيرا فمضت إليه وخرجت معه إلى البصرة","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":4,"spl":"ابن الزبير يعزل أخاه مصعبا عن البصرة ويولي ابنه حمزة — خبر الفرزدق مع النوار ابنة أعين الم"},
{"id":"b32-10","bab":"الجزء 3","sec":"معبد يغني بشعره حمزة بن عبد الله","page":"ج3 ص360","text":"أخبرني الحسين بن يحيى ومحمد بن مزيد بن أبي الأزهر قالا حدثنا حماد ابن إسحاق عن أبيه عن الزبيري أن حمزة بن عبد الله كان جوادا فدخل إليه معبد يوما وقد أرسله ابن قطن مولاه يقترض له من حمزة ألف دينار فأعطاه ألف الدينار فلما خرج من عنده قيل له هذا عبد ابن قطن وهويروي فيك شعر موسى شهوات فيحسن روايته فأمر برده فرد وقال له ما حكاه القوم عنه فغناه معبد الصوت فأعطاه أربعين دينارا ولما كان بعد ذلك رد ابن قطن عليه المال فلم يقبله وقال له إنه إذا خرج عني مال لم يعد إلى ملكي وقد روي أن الداخل على حمزة والمخاطب في أمره بهذه المخاطبة ابن سريج وليس ذلك بثبت هذا هو الصحيح والغناء لمعبد\nأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة عن محمد بن يحيى الغساني أن موسى شهوات أملق فقال لمعبد قد قلت في حمزة بن عبد الله شعرا فغن فيه حتى يكون أجزل لصلتنا ففعل ذلك معبد وغنى في هذه الأبيات ثم دخلا على حمزة فأنشده إياها موسى ثم غناه فيها معبد فأمر لكل واحد منهما بمائتي دينار أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا العمري عن الهيثم بن عبد الله بن عبد الله بن عياش قال كان موسى شهوات مولى لسليمان بن أبي خيثمة بن حذيفة العدوي وكان شاعرا من شعراء أهل الحجاز وكان الخلفاء من بني أمية يحسنون إليه ويدرون عطاءه وتجيئه صلاتهم إلى الحجاز وكانت فاطمة بنت عبد الملك بن مروان تحت عمر بن عبد العزيز فلما مات عنها تزوجها داود بن سليمان بن مروان وكان دميما قبيحا فقال موسى شهوات في ذلك\n(أبعد الأغر ابن العزيز ... قريع قريش إذا يذكر)\n(تزوجت داود مختارة ... ألا ذلك الخلف الأعور)\nغلب عليه ذلك في بني مروان فكان يقال له الخلف الأعور","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":5,"spl":"معبد يغني بشعره حمزة بن عبد الله — صوت من المائة المختارة"},
{"id":"b32-11","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص361","text":"(عوجا خليلي على المحضر ... والربع من سلامة المقفر)\n(عوجا به فاستنطقاه فقد ... ذكرني ما كنت لم أذكر)\n(ذكرني سلمى وأيامها ... إذ جاورتنا بلوى عسجر)\n(بالربع من ودان مبدا لنا ... ومحورا ناهيك من محور)\n(في محضر كنا به نلتقي ... يا حبذا ذلك من محضر)\n(إذ نحن والحي به جيرة ... فيما مضى من سالف الأعصر)\nلشعر للوليد بن يزيد وقيل إنه لعمر بن أبي ربيعة وقيل إنه للعرجي وهو للوليد صحيح والغناء واللحن المختار لابن سريج خفيف رمل بالبنصر في مجراها وفيه لشارية خفيف رمل آخر عن ابن المعتز وذكر الهشامي أن فيه لحكم الوادي خفيف رمل أيضا","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":5,"spl":"معبد يغني بشعره حمزة بن عبد الله — صوت من المائة المختارة"},
{"id":"b32-12","bab":"الجزء 3","sec":"خبر أشعب مع زيد بن عمرو بن عثمان زوج سكينة بنت الحسين","page":"ج3 ص362","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني قال كان زيد بن عمرو بن عثمان قد تزوج سكينة بنت الحسين رضي الله تعالى عنه فعتب عليها يوما فخرج إلى مال له فذكر أشعب أن سكينة دعته فقالت له إن ابن عثمان خرج عاتبا علي فاعلم لي حاله قلت لا أستطيع أن أذهب إليه الساعة فقالت أنا أعطيك ثلاثين دينارا فأعطتني إياها فأتيته ليلا فدخلت الدار فقال انظروا من في الدار فأتوه فقالوا أشعب فنزل عن فرشه وصار إلى الأرض فقال أشعيب قلت نعم قال ما جاء بك قلت أرسلتني سكينة لأعلم خبرك أتذكرت منها ما تذكرت منك وأنا أعلم أنك قد فعلت حين نزلت عن فرشك وصرت إلى الأرض قال دعني من هذا وغنني\n(عوجا به فاستنطقاه فقد ... ذكرني ما كنت لم أذكر)\nغنيته فلم يطرب ثم قال غنني ويحك غير هذا فإن أصبت ما في نفسي فلك خلتي هذه وقد اشتريتها آنفا بثلمثمائة دينار فغنيته صوت\n(علق القلب بعض ما قد شجاه ... من حبيب أمسى هوانا هواه)\n(ما ضراري نفسي بهجران من ليس ... مسيئا ولا بعيدا نواه)\n(واجتنابي بنت الحبيب وما الخلد ... بأشهى إلي من أن أراه)\nقال ما عدوت ما في نفسي خذ الحلة فأخذتها ورجعت إلى سكينة فقصصت عليها القصة فقالت وأين الحلة قلت معي فقالت وأنت الآن تريد أن تلبس حلة ابن عثمان لا والله ولا كرامة فقلت قد أعطانيها فأي شيء تريدين مني فقالت أنا أشتريها منك فبعتها إياها بثلثمائة دينار الشعر المذكور في هذا الخبر لعمر بن أبي ربيعة والغناء للدارمي خفيف ثقيل بالخنصر في مجرى الوسطى وذكر عمرو بن بانة أنه للهذلي وفيه لابن جامع ثاني ثقيل بالوسطى أخبرني الحسين بن يحيى عن حماد عن أبيه أن رجلا كانت له جارية يهواها وتهواه فغاضبها يوما وتمادى ذلك بينهما واتفق أن مغنية دخلت فغنتهما\n(ما ضراري نفسي بهجران من ليس ... مسيئا ولا بعيدا نواه)\nقالت الجارية لا شيء والله إلا الحمق ثم قامت إلى مولاها فقبلت رأسه واصطلحا","topic":"أخبار موسى شهوات ونسبه وخبره في هذا الشعر","topicNo":32,"sp":6,"spl":"خبر أشعب مع زيد بن عمرو بن عثمان زوج سكينة بنت الحسين"},
{"id":"b33-1","bab":"الجزء 3","sec":"صوت من المائة المختارة","page":"ج3 ص363","text":"(يا ويح نفسي لو أنه أقصر ... ما كان عيشي كما أرى أكدر)\n(يا من عذيري ممن كلفت به ... يشهد قلبي بأنه يسحر)\n(يا رب يوم رأيتني مرحا ... آخذ في اللهو مسبل المئزر)\n(بين ندامى تحث كأسهم ... عليهم كف شادن أحور)\nلشعر لأبي العتاهية والغناء لفريدة خفيف رمل بالبنصر إلى هنا انتهى الجزء الثالث من كتاب الأغاني ويليه إن شاء الله تعالى الجزء الرابع منه وأوله ذكر نسب أبي العتاهية وأخباره سوى ما كان منها مع عتبة","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبة"},
{"id":"b33-2","bab":"الجزء 4","sec":"بسم الله الرحمن الرحيم ذكر نسب أبي العتاهية وأخباره","page":"ج4 ص3","text":"أبو العتاهية لقب غلب عليه واسمه إسماعيل بن القاسم بن سويد بن كيسان مولى عنزة وكنيته أبو إسحاق وأمه أم زيد بنت زياد المحاربي مولى بني زهرة وفي ذلك يقول أبو قابوس النصراني وقد بلغه أن أبا العتاهية فضل عليه العتابي\n(قل للمكني نفسه ... متخيرا بعتاهيه)\n(والمرسل الكلم القبيح ... وعته أذن واعيه)\n(إن كنت سرا سؤتني ... أو كان ذاك علانيه)\n(فعليك لعنة ذي الجلال ... وأم زيد زانيه)\nمنشؤه بالكوفة وكان في أول أمره يتخنث ويحمل زاملة المخنثين ثم كان يبيع الفخار بالكوفة ثم قال الشعر فبرع فيه وتقدم ويقال أطبع الناس بشار والسيد وأبو العتاهية وما قدر أحد على جمع شعر هؤلاء الثلاثة لكثرته وكان\nغزير البحر لطيف المعاني سهل الألفاظ كثير الافتنان قليل التكلف إلا أنه كثير الساقط المرذول مع ذلك وأكثر شعره في الزهد والأمثال وكان قوم من أهل عصره ينسبونه إلى القول بمذهب الفلاسفة ممن لا يؤمن بالبعث ويحتجون بأن شعره إنما هو في ذكر الموت والفناء دون ذكر النشور والمعاد وله أوزان طريفة قالها مما لم يتقدمه الأوائل فيها وكان أبخل الناس مع يساره وكثرة ما جمعه من الأموال","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبة"},
{"id":"b33-3","bab":"الجزء 4","sec":"سبب لقبة","page":"ج4 ص4","text":"حدثني محمد بن يحيى الصولي قال أخبرني محمد بن موسى بن حماد قال قال المهدي يوما لأبي العتاهية أنت إنسان متحذلق معته فاستوت له من ذلك كنية غلبت عليه دون اسمه وكنيته وسارت له في الناس قال ويقال\nللرجل المتحذلق عتاهية كما يقال للرجل الطويل شناحية ويقال أبو عتاهية بإسقاط الألف واللام قال محمد بن يحيى وأخبرني محمد بن موسى قال أخبرني ميمون بن هارون عن بعض مشايخه قال كني بأبي العتاهية أن كان يحب الشهرة والمجون والتعته وبلده الكوفة وبلد آبائه وبها مولده ومنشؤه وباديته قال محمد بن سلام وكان محمد بن أبي العتاهية يذكر أن أصلهم من عنزة وأن جدهم كيسان كان من أهل عين التمر فلما غزاها خالد بن الوليد كان كيسان جدهم هذا يتيما صغيرا يكفله قرابة له من عنزة فسباه خالد مع جماعة صبيان من أهلها فوجه بهم إلى أبي بكر فوصلوا إليه وبحضرته عباد بن رفاعة العنزي بن أسد بن ربيعة بن نزار فجعل أبو بكر رضي الله عنه يسأل الصبيان عن أنسابهم فيخبره كل واحد بمبلغ معرفته حتى سأل كيسان فذكر له أنه من عنزة فلما سمعه عباد يقول ذلك استوهبه من أبي بكر رضي الله عنه وقد كان خالصا له فوهبه له فأعتقه فتولى عنزة أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا أحمد بن الحجاج الجلاني الكوفي قال حدثني أبو دؤيل مصعب بن دؤيل الجلاني قال لم أر قط مندل بن علي العنزي وأخاه حيان بن علي غضبا من شيء قط إلا يوما واحدا دخل عليها أبو العتاهية وهو مضمخ بالدماء فقالا له ويحك ما بالك فقال لهما من أنا فقالا له أنت أخونا وابن عمنا\nومولانا فقال إن فلانا الجزار قتلني وضربني وزعم أني نبطي فإن كنت نبطيا هربت على وجهي وإلا فقوما فخذا لي بحقي فقام معه مندل بن علي وما تعلق نعله غضبا وقال له والله لو كان حقك على عيسى بن موسى لأخذته لك منه ومر معه حافيا حتى أخذ له بحقه أخبرني الصولي قال حدثنا محمد بن موسى عن الحسن بن علي عن عمر بن معاوية عن جبارة بن المفلس الحماني قال أبو العتاهية مولى عطاء بن محجن العنزي","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":0,"spl":"صوت من المائة المختارة — سبب لقبة"},
{"id":"b33-4","bab":"الجزء 4","sec":"صنعة أبي العتاهية","page":"ج4 ص6","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال قال أبو عون أحمد بن المنجم أخبرني خيار الكاتب قال كان أبو العتاهية وإبراهيم الموصلي من أهل المذار جميعا وكان أبو العتاهية وأهله يعملون الجرار الخضر فقدما إلى بغداد ثم افترقا فنزل إبراهيم الموصلي ببغداد ونزل أبو العتاهية الحيرة وذكر عن الرياشي أنه قال مثل ذلك وأن أبا أبي العتاهية نقله إلى الكوفة\nقال محمد بن موسى فولاء أبي العتاهية من قبل أبيه لعنزة ومن قبل أمه لبني زهرة ثم لمحمد بن هاشم بن عتبة بن أبي وقاص وكانت أمه مولاة لهم يقال لها أم زيد أخبرني الحسن بن علي قال حدثنا محمد بن مهرويه قال قال الخليل بن أسد كان أبو العتاهية يأتينا فيستأذن ويقول أبو إسحاق الخزاف وكان أبوه حجاما من أهل ورجة ولذلك يقول أبو العتاهية\n(ألا إنما التقوى هو العز والكرم ... وحبك للدنيا هو الفقر والعدم)\n(وليس على عبد تقي نقيصة ... إذا صحح التقوى وإن حاك أو حجم)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":1,"spl":"صنعة أبي العتاهية — مذهب أبي العتاهية"},
{"id":"b33-5","bab":"الجزء 4","sec":"شعره بعد أن فاخره رجل من كنانة","page":"ج4 ص7","text":"حدثني محمد بن يحيى الصولي قال حدثنا الغلابي قال حدثنا محمد بن أبي العتاهية قال جاذب رجل من كنانة أبا العتاهية في شيء ففخر عليه الكناني واستطال بقوم من أهله فقال أبو العتاهية\n(دعني من ذكر أب وجد ... ونسب يعليك سور المجد)\n(ما الفخر إلا في التقى والزهد ... وطاعة تعطي جنان الخلد)\n(لا بد من ورد لأهل الورد ... إما إلى ضحل وإما عد)\nدثني الصولي قال حدثنا محمد بن موسى عن أحمد بن حرب قال كان مذهب أبي العتاهية القول بالتوحيد وأن الله خلق جوهرين متضادين لا\nمن شيء ثم إنه بنى العالم هذه البنية منهما وأن العالم حديث العين والصنعة لا محدث له إلا الله وكان يزعم أن الله سيرد كل شيء إلى الجوهرين المتضادين قبل أن تفنى الأعيان جميعا وكان يذهب إلى أن المعارف واقعة بقدر الفكر والاستدلال والبحث طباعا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":1,"spl":"صنعة أبي العتاهية — مذهب أبي العتاهية"},
{"id":"b33-6","bab":"الجزء 4","sec":"مذهب أبي العتاهية","page":"ج4 ص8","text":"وكان يقول بالوعيد وبتحريم المكاسب ويتشيع بمذهب الزيدية البترية المبتدعة لا يتنقص أحدا ولا يرى مع ذلك الخروج على السلطان وكان مجبرا قال الصولي فحدثني يموت بن المزرع قال حدثني الجاحظ قال قال أبو العتاهية لثمامة بين يدي المأمون وكان كثيرا ما يعارضه بقوله في الإجبار أسألك عن مسألة فقال له المأمون عليك بشعرك فقال إن رأى أمير المؤمنين أن يأذن لي في مسألته ويأمره بإجابتي فقال له أجبه إذا سألك فقال أنا أقول إن كل ما فعله العباد من خير وشر فهو من الله وأنت تأبى ذلك فمن حرك يدي هذه وجعل أبو العتاهية يحركها فقال له ثمامة حركها من أمه زانية فقال شتمني والله يا أمير المؤمنين فقال ثمامة ناقض الماص بظر أمه والله يا أمير المؤمنين فضحك المأمون وقال له ألم أقل لك أن تشتغل بشعرك وتدع ما ليس من عملك قال ثمامة فلقيني بعد ذلك فقال لي يا أبا معن أما أغناك الجواب\nعن السفه فقلت إن من أتم الكلام ما قطع الحجة وعاقب على الإساءة وشفى من الغيظ وانتصر من الجاهل قال محمد بن يحيى وحدثني عون بن محمد الكندي قال سمعت العباس بن رستم يقول كان أبو العتاهية مذبذبا في مذهبه يعتقد شيئا فإذا سمع طاعنا عليه ترك اعتقاده إباه وأخذ غيره حدثني أحمد بن عبيد الله بن عمار قال حدثني ابن أبي الدنيا قال حدثني الحسين بن عبد ربه قال حدثني علي بن عبيدة الريحاني قال حدثني أبو الشمقمق أنه رأى أبا العتاهية يحمل زاملة المخنثين فقلت له أمثلك يضع نفسه هذا الموضع مع سنك وشعرك وقدرك فقال له أريد أن أتعلم كيادهم وأتحفظ كلامهم","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":1,"spl":"صنعة أبي العتاهية — مذهب أبي العتاهية"},
{"id":"b33-7","bab":"الجزء 4","sec":"مارس صنعة الحجامة","page":"ج4 ص9","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا عبد الله بن أبي سعد قال ذكر أحمد بن إبراهيم بن إسماعيل أن بشر بن المعتمر قال يوما لأبي العتاهية بلغني أنك لما نسكت جلست تحجم اليتامى والفقراء للسبيل أكذلك كان قال نعم قال له فما أردت بذلك قال أردت أن أضع من نفسي حسبما رفعتني الدنيا وأضع منها ليسقط عنها الكبر وأكتسب بما فعلته الثواب وكنت أحجم اليتامى والفقراء خاصة فقال له بشر دعني من تذليلك نفسك بالحجامة فإنه ليس بحجة لك أن تؤدبها وتصلحها بما لعلك تفسد به أمر غيرك أحب أن تخبرني هل كنت تعرف الوقت الذي كان يحتاج فيه من تحجمه إلى إخراج الدم قال لا قال هل كنت تعرف مقدار ما يحتاج كل واحد منهم إلى أن\nيخرجه على قدر طبعه مما إذا زدت فيه أو نقصت منه ضر المحجوم قال لا قال فما أراك إلا أردت أن تتعلم الحجامة على أقفاء اليتامى والمساكين أخبرني محمد بن يحيى الصولي قال حدثنا أبو ذكوان قال حدثنا العباس بن رستم قال كان حمدويه صاحب الزنادقة قد أراد أن يأخذ أبا العتاهية ففزع من ذلك وقعد حجاما أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال قال أبو دعامة علي بن يزيد أخبر يحيى بن خالد أن أبا العتاهية قد نسك وأنه جلس يحجم الناس للأجر تواضعا بذلك فقال ألم يكن يبيع الجرار قبل ذلك فقيل له بلى فقال أما في بيع الجرار من الذل ما يكفيه ويستغني به عن الحجامة أخبرني محمد بن يحيى قال حدثني شيخ من مشايخنا قال حدثني أبو شعيب صاحب ابن أبي داود قال قلت لأبي العتاهية القرآن عندك مخلوق أم غير مخلوق فقال أتسألتني عن الله أم عن غير الله قلت عن غير الله فأمسك وأعدت عليه فأجابني هذا الجواب حتى فعل ذلك مرارا فقلت له ما لك لا تجيبني قال قد أجبتك ولكنك حمار","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":2,"spl":"مارس صنعة الحجامة — أوصافه"},
{"id":"b33-8","bab":"الجزء 4","sec":"أوصافه","page":"ج4 ص10","text":"أخبرني محمد بن يحيى قال حدثنا شيخ من مشايخنا قال حدثني محمد بن موسى قال كان أبو العتاهية قضيفا أبيض اللون أسود الشعر له وفرة جعدة\nوهيئة حسنة ولباقة وحصافة وكان له عبيد من السودان ولأخيه زيد أيضا عبيد منهم يعملون الخزف في أتون لهم فإذا اجتمع منه شيء ألقوه على أجير لهم يقال له أبو عباد اليزيدي من أهل طاق الجرار بالكوفة فيبيعه على يديه ويرد فضله إليهم وقيل بل كان يفعل ذلك أخوه زيد لا هو وسئل عن ذلك فقال أنا جرار القوافي وأخي جرار التجارة قال محمد بن موسى وحدثني عبد الله بن محمد قال حدثني عبد الحميد بن سريع مولى بني عجل قال أنا رأيت أبا العتاهية وهو جرار يأتيه الأحداث والمتأدبون فينشدهم أشعاره فيأخذون ما تكسر من الخزف فيكتبونها فيها حدثني محمد بن يحيى الصولي قال حدثني عون بن محمد الكندي قال حدثني محمد بن عمر الجرجاني قال لما هاجى أبو قابوس النصراني كلثوم بن عمرو العتابي جعل أبو العتاهية يشتم أبا قابوس ويضع منه ويفضل العتابي عليه فبلغه ذلك فقال فيه\n(قل للمكني نفسه ... متخيرا بعتاهيه)\n(والمرسل الكلم القبيح ... وعته أذن واعيه)\n(إن كنت سرا سؤتني ... أو كان ذاك علانيه)\n(فعليك لعنة ذي الاجلال ... وأم زيد زانيه)\nعني أم أبي العتاهية وهي أم زيد بنت زياد فقيل له أتشتم مسلما فقال لم أشتمه وإنما قلت\n(فعليك لعنة ذي الجلال ... ومن عنينا زانيه)\nقال وفيه يقول والبة بن الحباب وكان يهاجيه\n(كان فينا يكنى أبا إسحاق ... وبها الركب سار في الآفاق)\n(فتكنى معتوهنا بعتاه ... يا لها كنية أتت باتفاق)\n(خلق الله لحية لك لا تنفك ... معقودة بداء الحلاق)\nخبرنا محمد بن مزيد بن أبي الأزهر قال حدثنا الزبير بن بكار قال حدثنا النوشجاني قال أتاني البواب يوما فقال لي أبو إسحاق الخزاف بالباب فقلت ائذن له فإذا أبو العتاهية قد دخل فوضعت بين يديه قنو موز فقال قد صرت تقتل العلماء بالموز قتلت أبا عبيدة بالموز وتريد أن تقتلني به لا والله لا أذوقه قال فحدثني عروة بن يوسف الثقفي قال رأيت أبا عبيدة قد خرج من دار النوشجاني في شق محمل مسجى إلا أنه حي وعند رأسه قنو موز وعند رجليه قنو موز آخر يذهب به إلى أهله فقال النوشجاني وغيره لما دخلنا عليه نعوده قلنا ما سبب علتك قال هذا النوشجاني جاءني بموز كأنه أيور المساكين فأكثرت منه فكان سبب علتي قال ومات في تلك العلة","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":2,"spl":"مارس صنعة الحجامة — أوصافه"},
{"id":"b33-9","bab":"الجزء 4","sec":"مصعب يقول أبو العتاهية أشعر الناس","page":"ج4 ص12","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال سمعت مصعب بن عبد الله يقول أبو العتاهية أشعر الناس فقلت له بأي شيء استحق ذلك عندك فقال بقوله\n(تعلقت بآمال ... طوال أي آمال)\n(وأقبلت على الدنيا ... ملحا أي إقبال)\n(أيا هذا تجهز لفراق ... الأهل والمال)\n(فلا بد من الموت ... على حال من الحال)\nم قال مصعب هذا كلام سهل حق لا حشو فيه ولا نقصان يعرفه العاقل ويقربه الجاهل أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال سمعت الأصمعي يستحسن قول أبي العتاهية\n(أنت ما استغنيت عن صاحبك ... الدهر أخوه)\n(فإذا احتجت إليه ... ساعة مجك فوه)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":3,"spl":"مصعب يقول أبو العتاهية أشعر الناس — شعره في الرشيد وهو مريض"},
{"id":"b33-10","bab":"الجزء 4","sec":"سلم الخاسر يقول أبو العتاهية أشعر الأنس والجن","page":"ج4 ص13","text":"حدثنا محمد بن العباس اليزيدي إملاء قال حدثني عمي الفضل بن محمد\nقال حدثني موسى بن صالح الشهرزوري قال أتيت سلما الخاسر فقلت له أنشدني لنفسك قال لا ولكن أنشدك لأشعر الجن والإنس لأبي العتاهية ثم أنشدني قوله صوت\n(سكن يبقى له سكن ... ما بهذا يؤذن الزمن)\n(نحن في دار يخبرنا ... ببلاها ناطق لسن)\n(دار سوء لم يدم فرح ... لامرىء فيها ولا حزن)\n(في سبيل الله أنفسنا ... كلنا بالموت مرتهن)\n(كل نفس عند ميتتها ... حظها من مالها الكفن)\n(إن مال المرء ليس له ... منه إلا ذكره الحسن)\nأخبرني أحمد بن عبيد الله بن عمار قال حدثني محمد بن القاسم قال حدثني رجل من أهل البصرة أنسيت اسمه قال حدثني حمدون بن زيد قال حدثني رجاء بن مسلمة قال قلت لسلم الخاسر من أشعر الناس فقال إن شئت أخبرتك بأشعر الجن والإنس فقلت إنما أسالك عن الإنس فإن زدتني الجن فقد أحسنت فقال أشعرهم الذي يقول\n(سكن يبقى له سكن ... ما بهذا يؤذن الزمن)\nقال والشعر لأبي العتاهية حدثني اليزيدي قال حدثني عمي الفضل قال حدثنا عبد الله بن محمد قال حدثنا يحيى بن زياد الفراء قال دخلت على جعفر بن يحيى فقال لي يا أبا زكريا ما تقول فيما أقول فقلت وما تقول أصلحك الله قال أزعم أن أبا العتاهية أشعر أهل هذا العصر فقلت هو والله أشعرهم عندي حدثني محمد بن يحيى الصولي قال حدثني محمد بن موسى قال حدثني جعفر بن النضر الواسطي الضرير قال حدثني محمد بن شيرويه الأنماطي قال قلت لداود بن زيد بن رزين الشاعر من أشعر أهل زمانه قال أبو نواس قلت فما تقول في أبي العتاهية فقال أبو العتاهية أشعر الإنس والجن أخبرني الصولي قال حدثني محمد بن موسى قال قال الزبير بن بكار أخبرني إبراهيم بن المنذر عن الضحاك قال قال عبد الله بن عبد العزيز العمري أشعر الناس أبو العتاهية حيث يقول\n(ما ضر من جعل التراب مهاده ... ألا ينام على الحرير إذا قنع)\nدق والله وأحسن\nحدثني الصولي قال حدثني محمد بن محمد بن موسى قال حدثني أحمد بن حرب قال حدثني المعلى بن عثمان قال قيل لأبي العتاهية كيف تقول الشعر قال ما أردته قط إلا مثل لي فأقول ما أريد وأترك ما لا أريد أخبرني ابن عمار قال حدثني ابن مهرويه قال حدثني روح بن الفرج الحرمازي قال جلست إلى أبي العتاهية فسمعته يقول لو شئت أن أجعل كلامي كله شعرا لفعلت حدثنا الصولي قال حدثنا العنزي قال حدثنا أبو عكرمة قال قال محمد بن أبي العتاهية سئل أبي هل تعرف العروض فقال أنا أكبر من العروض وله أوزان لا تدخل في العروض","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":3,"spl":"مصعب يقول أبو العتاهية أشعر الناس — شعره في الرشيد وهو مريض"},
{"id":"b33-11","bab":"الجزء 4","sec":"شعره في الرشيد وهو مريض","page":"ج4 ص16","text":"أخبرني الحسن بن علي قال حدثنا العنزي قال حدثنا أبو عكرمة قال حم الرشيد فصار أبو العتاهية إلى الفضل بن الربيع برقعة فيها\n(لو علم الناس كيف أنت لهم ... ماتوا إذا ما ألمت أجمعهم)\n(خليفة الله أنت ترجح بالناس ... إذا ما وزنت أنت وهم)\n(قد علم الناس أن وجهك يستغني ... إذا ما رآه معدمهم)\nأنشدها الفضل بن الربيع الرشيد فأمر بإحضار أبي العتاهية فما زال يسامره ويحدثه إلى أن برئ ووصل إليه بذلك السبب مال جليل","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":3,"spl":"مصعب يقول أبو العتاهية أشعر الناس — شعره في الرشيد وهو مريض"},
{"id":"b33-12","bab":"الجزء 4","sec":"ابن الأعرابي يدافع عنه","page":"ج4 ص17","text":"قال وحدثت أن ابن الأعرابي حدث بهذا الحديث فقال له رجل بالمجلس ما هذا الشعر بمستحق لما قلت قال ولم قال لأنه شعر ضعيف فقال ابن الأعرابي وكان أحد الناس الضعيف والله عقلك لا شعر أبي العتاهية ألأبي العتاهية تقول إنه ضعيف الشعر فوالله ما رأيت شاعرا قط أطبع ولا أقدر على بيت منه وما أحسب مذهبه إلا ضربا من السحر ثم أنشد له\n(قطعت منك حبائل الآمال ... وحططت عن ظهر المطي رحالي)\n(ووجدت برد اليأس بين جوانحي ... فأرحت من حل ومن ترحال)\n(يأيها البطر الذي هو من غد ... في قبره متمزق الأوصال)\n(حذف المنى عنه المشمر في الهدى ... وأرى مناك طويلة الأذيال)\n(حيل ابن آدم في الأمور كثيرة ... والموت يقطع حيلة المحتال)\n(قست السؤال فكان أعظم قيمة ... من كل عارفة جرت بسؤال)\n(فإذا ابتليت ببذل وجهك سائلا ... فابذله للمتكرم المفضال)\n(وإذا خشيت تعذرا في بلدة ... فاشدد يديك بعاجل الترحال)\n(واصبر على غير الزمان فإنما ... فرج الشدائد مثل حل عقال)\nثم قال للرجل هل تعرف أحدا يحسن أن يقول مثل هذا الشعر فقال له الرجل يا أبا عبد الله جعلني الله فداءك إني لم أردد عليك ما قلت ولكن الزهد مذهب أبي العتاهية وشعره في المديح ليس كشعره في الزهد فقال أفليس الذي يقول في المديح\n(وهارون ماء المزن يشفى به الصدى ... إذا ما الصدي بالريق غصت حناجره)\n(وأوسط بيت في قريش لبيته ... وأول عز في قريش وآخره)\n(وزحف له تحكي البروق سيوفه ... وتحكي الرعود القاصفات حوافره)\n(إذا حميت شمس النهار تضاحكت ... إلى الشمس فيه بيضه ومغافره)\n(إذا نكب الإسلام يوما بنكبة ... فهارون من بين البرية ثائره)\n(ومن ذا يفوت الموت والموت مدرك ... كذا لم يفت هارون ضد ينافره)\nال فتخلص الرجل من شر ابن الأعرابي بأن قال له القول كما قلت وما كنت سمعت له مثل هذين الشعرين وكتبهما عنه حدثني محمد قال حدثني أحمد بن أبي طاهر قال حدثني ابن الأعرابي المنجم قال حدثني هارون بن سعدان بن الحارث مولى عباد قال","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":4,"spl":"ابن الأعرابي يدافع عنه — أبو نواس يفضله على نفسه"},
{"id":"b33-13","bab":"الجزء 4","sec":"أبو نواس يفضله على نفسه","page":"ج4 ص18","text":"حضرت أبا نواس في مجلس وأنشد شعرا فقال له من حضر في المجلس أنت أشعر الناس قال أما والشيخ حي فلا يعني أبا العتاهية أخبرني يحيى بن علي إجازة قال حدثني علي بن مهدي قال حدثني الحسين ابن أبي السري قال قال ثمامة بن أشرس أنشدني أبو العتاهية\n(إذا المرء لم يعتق من المال نفسه ... تملكه المال الذي هو مالكه)\n(ألا إنما مالي الذي أنا منفق ... وليس لي المال الذي أنا تاركه)\n(إذا كنت ذا مال فبادر به الذي ... يحق وإلا استهلكته مهالكه)\nقلت له من أين قضيت بهذا فقال من قول رسول الله إنما لك من مالك ما أكلت فأفنيت أو لبست فأبليت أو تصدقت فأمضيت فقلت له أتؤمن بأن هذا قول رسول الله وأنه الحق قال نعم قلت فلم تحبس عندك سبعا وعشرين بدرة في دارك ولا تأكل منها ولا تشرب ولا تزكي ولا تقدمها ذخرا ليوم فقرك وفاقتك فقال يا أبا معن والله إن ما قلت لهو الحق ولكني أخاف الفقر والحاجة إلى الناس فقلت وبم تزيد حال من افتقر على حالك وأنت دائم الحرص دائم الجمع شحيح على نفسك لا تشتري اللحم إلا من عيد إلى عيد فترك جواب كلامي كله ثم قال لي والله لقد اشتريت في يوم عاشوراء لحما وتوابله وما يتبعه بخمسة دراهم فلما قال لي هذا القول أضحكني حتى أذهلني عن جوابه ومعاتبته فأمسكت عنه وعلمت أنه ليس ممن شرح الله صدره للإسلام","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":4,"spl":"ابن الأعرابي يدافع عنه — أبو نواس يفضله على نفسه"},
{"id":"b33-14","bab":"الجزء 4","sec":"أخبار عن بخله","page":"ج4 ص19","text":"أخبرني يحيى بن علي إجازة قال حدثني علي بن المهدي قال قال الجاحظ حدثني ثمامة قال دخلت يوما إلى أبي العتاهية فإذا هو يأكل خبزا بلا شيء فقلت كأنك رأيته يأكل خبزا وحده قال لا ولكني رأيته يتأدم بلا شيء فقلت وكيف\nذلك فقال رأيت قدامه خبزا يابسا من رقاق فطير وقدحا فيه لبن حليب فكان يأخذ القطعة من الخبز فيغمسها من اللبن ويخرجها ولم تتعلق منه بقليل ولا كثير فقلت له كأنك اشتهيت أن تتأدم بلا شيء وما رأيت أحدا قبلك تأدم بلا شيء قال الجاحظ وزعم لي بعض أصحابنا قال دخلت على أبي العتاهية في بعض المتنزهات وقد دعا عياشا صاحب الجسر وتهيأ له بطعام وقال لغلامه إذا وضعت قدامهم الغداء فقدم إلي ثريدة بخل وزيت فدخلت عليه وإذا هو يأكل منها أكل متكمش غير منكر لشيء فدعاني فمددت يدي معه فإذا بثريدة بخل بزر بدلا من الزيت فقلت له أتدري ما تأكل قال نعم ثريدة بخل وبزر فقلت ما دعاك إلى هذا قال غلط الغلام بين دبة الزيت ودبة البزر فلما جاءني كرهت التجبر وقلت دهن كدهن فأكلت وما أنكرت شيئا أخبرني يحيى بن علي قال حدثني علي بن مهدي قال حدثنا عبد الله بن عطية الكوفي قال حدثنا محمد بن عيسى الخزيمي وكان جار أبي العتاهية قال كان لأبي العتاهية جار يلتقط النوى ضعيف سيئ الحال متجمل عليه ثياب فكان يمر بأبي العتاهية طرفي النهار فيقول أبو العتاهية اللهم أغنه عما هو بسبيله شيخ ضعيف سيئ الحال عليه ثياب متجمل اللهم أغنه إصنع له بارك فيه فبقي على هذا إلى أن مات الشيخ نحوا من عشرين سنة ووالله إن تصدق عليه بدرهم ولا دانق قط وما زاد على الدعاء شيئا فقلت له يوما يا أبا إسحاق إني أراك تكثر الدعاء لهذا الشيخ وتزعم أنه فقير مقل فلم لا تتصدق عليه بشيء فقال أخشى أن يعتاد الصدقة والصدقة أخر كسب العبد وإن في الدعاء لخيرا كثيرا\nقال محمد بن عيسى الخزيمي هذا وكان لأبي العتاهية خادم أسود طويل كأنه محراك أتون وكان يجري عليه في كل يوم رغيفين فجاءني الخادم يوما فقال لي والله ما أشبع فقلت وكيف ذاك قال لأني ما أفتر من الكد وهو يجري علي رغيفين بغير إدام فإن رأيت أن تكلمه حتى يزيدني رغيفا فتؤجر فوعدته بذلك فلما جلست معه مر بنا الخادم فكرهت إعلامه أنه شكا إلي ذلك فقلت له يا أبا إسحاق كم تجري على هذا الخادم في كل يوم قال رغيفين فقلت له لا يكفيانه قال من لم يكفه القليل لم يكفه الكثير وكل من أعطى نفسه شهوتها هلك وهذا خادم يدخل إلى حرمي وبناتي فإن لم أعوده القناعة والاقتصاد أهلكني وأهلك عيالي ومالي فمات الخادم بعد ذلك فكفنه في إزار وفراش له خلق فقلت له سبحان الله خادم قديم الحرمة طويل الخدمة واجب الحق تكفنه في خلق وإنما يكفيك له كفن بدينار فقال إنه يصير إلى البلى والحي أولى بالجديد من الميت فقلت له يرحمك الله أبا إسحاق فلقد عودته الاقتصاد حيا وميتا قال محمد بن عيسى هذا وقف عليه ذات يوم سائل من العيارين الظرفاء وجماعة من جيرانه حوله فسأله من بين الجيران فقال صنع الله لك فأعاد السؤال فأعاد عليه ثانية فأعاد عليه ثالثة فرد عليه مثل ذلك فغضب وقال له ألست القائل\n(كل حي عند ميتته ... حظه من ماله الكفن)\nم قال فبالله عليك أتريد أن تعد مالك كله ثمن كفنك قال لا قال فبالله كم قدرت لكفنك قال خمسة دنانير قال فهي إذا حظك من مالك كله قال نعم","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":5,"spl":"أخبار عن بخله"},
{"id":"b33-15","bab":"الجزء 4","sec":"أخبار عن بخله","page":"ج4 ص19","text":"قال فتصدق علي من غير حظك بدرهم واحد قال لو تصدقت عليك لكان حظي قال فاعمل على أن دينارا من الخمسة الدنانير وضيعة قيراط وادفع إلي قيراطا واحدا وإلا فواحدة أخرى قال وما هي قال القبور تحفر بثلاثة دراهم فأعطني درهما وأقيم لك كفيلا بأني أحفر لك قبرك به متى مت وتربح درهمين لم يكونا في حسبابك فإن لم أحتفر رددته على ورثتك أو رده كفيلي عليهم فخجل أبو العتاهية وقال اعزب لعنك الله وغضب عليك فضحك جميع من حضر ومر السائل يضحك فالتفت إلينا أبو العتاهية فقال من أجل هذا وأمثاله حرمت الصدقة فقلنا له ومن حرمها ومتى حرمت فما رأينا أحدا ادعى أن الصدقة حرمت قبله ولا بعده قال محمد بن عيسى هذا وقلت لأبي العتاهية أتزكي مالك فقال والله ما أنفق على عيالي إلا من زكاة مالي فقلت سبحان الله إنما ينبغي أن تخرج زكاة مالك إلى الفقراء والمساكين فقال لو انقطعت عن عيالي زكاة مالي لم يكن في الأرض أفقر منهم أخبرني عيسى بن الحسين الوراق قال حدثنا الزبير بن بكار قال قال سليمان بن أبي شيخ قال إبراهيم بن أبي شيخ قلت لأبي العتاهية أي شعر قلته أحكم قال قولي\n(علمت يا مجاشع بن مسعده ... أن الشباب والفراغ والجده)\n(مفسدة للمرء أي مفسده ... )\nخبرني عيسى قال حدثنا الزبير بن بكار قال حدثنا أبو غزية قال كان مجاشع بن مسعدة أخو عمرو بن مسعدة صديقا لأبي العتاهية فكان يقوم بحوائجه كله ويخلص مودته فمات وعرضت لأبي العتاهية حاجة إلى أخيه\nعمرو بن مسعدة فتباطأ فيها فكتب إليه أبو العتاهية\n(غنيت عن العهد القديم غنيتا ... وضيعت ودا بيننا ونسيتا)\n(ومن عجب الأيام أن مات مألفي ... ومن كنت تغشاني به وبقيتا)\nقال عمرو استطال أبو إسحاق أعمارنا وتوعدنا ما بعد هذا خير ثم قضى حاجته أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا أبو غزية قال كان أبو العتاهية إذا قدم من المدينة يجلس إلي فأراد مرة الخروج من المدينة فودعني ثم قال\n(إن نعش نجتمع وإلا فما أشغل ... من مات عن جميع الأنام)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":6,"spl":"أخبار عن بخله — شعره في غلام طالبه بدين","partial":1},
{"id":"b33-16","bab":"الجزء 4","sec":"شعره في غلام طالبه بدين","page":"ج4 ص23","text":"أخبرني أحمد بن العباس العسكري قال حدثنا الحسن بن عليل العنزي قال حدثني عبد الرحمن بن إسحاق العذري قال كان لبعض التجار من أهل باب الطاق على أبي العتاهية ثمان ثياب أخذها منه فمر به يوما فقال صاحب الدكان لغلام ممن يخدمه حسن الوجه أدرك أبا العتاهية فلا تفارقه حتى تأخذ منه مالنا عنده فأدركه على رأس الجسر فأخذ بعنان حماره ووقفه فقال له ما حاجتك يا غلام قال أنا رسول فلان بعثني إليك لأخذ ماله عليك فأمسك عنه أبو العتاهية وكان كل من مر فرأى الغلام متعلقا به وقف ينظر حتى رضي أبو العتاهية جمع الناس وحفلهم ثم أنشأ يقول\n(والله ربك إنني ... لأجل وجهك عن فعالك)\n(لو كان فعلك مثل وجهك ... كنت مكتفيا بذلك)\nخجل الغلام وأرسل عنان الحمار ورجع إلى صاحبه وقال بعثتني إلى شيطان جمع علي الناس وقال في الشعر حتى أخجلني فهربت منه أخبرني أحمد بن العباس قال حدثنا العنزي قال قال إبراهيم بن إسحاق ابن إبراهيم التيمي حدثني إبراهيم بن حكيم قال كان أبو العتاهية يختلف إلى عمرو بن مسعدة لود كان بينه وبين أخيه مجاشع فاستأذن عليه يوما فحجب عنه فلزم منزله فاستبطأه عمرو فكتب إليه إن الكسل يمنعني من لقائك وكتب في أسفل رقعته\n(كسلني اليأس منك عنك فما ... أرفع طرفي إليك من كسل)\n(إني إذا لم يكن أخي ثقة ... قطعت منه حبائل الأمل)\nدثني علي بن سليمان الأخفش قال حدثني محمد بن يزيد النحوي قال استأذن أبو العتاهية على عمرو بن مسعدة فحجب عنه فكتب إليه\n(ما لك قد حلت عن إخائك ... واستبدلت يا عمرو شميبة كدره)\n(إني إذا الباب تاه حاجبه ... لم يك عندي في هجره نظره)\n(لستم ترجون للحساب ولا ... يوم تكون السماء منفطره)\n(لكن لدنيا كالظل بهجتها ... سريعة الانقضاء منشمره)\n(قد كان وجهي لديك معرفة ... فاليوم أضحى حرفا من النكره)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":6,"spl":"أخبار عن بخله — شعره في غلام طالبه بدين"},
{"id":"b33-17","bab":"الجزء 4","sec":"قصيدته في هجو عبد الله بن معن","page":"ج4 ص25","text":"أخبرني محمد بن القاسم الأنباري قال حدثنا أبو عكرمة قال كان الرشيد إذا رأى عبد الله بن معن بن زائدة تمثل قول أبي العتاهية\n(أخت بني شيبان مرت بنا ... ممشوطة كورا على بغل)\nأول هذه الأبيات\n(يا صاحبي رحلي لا تكثرا ... في شتم عبد الله من عذل)\n(سبحان من خص ابن معن بما ... أرى به من قلة العقل)\n(قال ابن معن وجلا نفسه ... على من الجلوة يا أهلي)\n(أنا فتاة الحي من وائل ... في الشرف الشامخ والنبل)\n(ما في بني شيبان أهل الحجا ... جارية واحدة مثلي)\n(ويلي ويا لهفي على أمرد ... يلصق مني القرط بالحجل)\n(صافحته يوما على خلوة ... فقال دع كفي وخذ رجلي)\n(أخت بني شيبان مرت بنا ... ممشوطة كورا على بغل)\n(تكنى أبا الفضل ويا من رأى ... جارية تكنى أبا الفضل)\n(قد نقطت في وجهها نقطة ... مخافة العين من الكحل)\n(إن زرتموها قال حجابها ... نحن عن الزوار في شغل)\n(مولاتنا مشغولة عندها ... بعل ولا إذن على البعل)\n(يا بنت معن الخير لا تجهلي ... وأين إقصار عن الجهل)\n(أتجلد الناس وأنت امرؤ ... تجلد في الدبر وفي القبل)\n(ما ينبغي للناس أن ينسبوا ... من كان ذا جود إلى البخل)\n(يبذل ما يمنع أهل الندى ... هذا لعمري منتهى البذل)\n(ما قلت هذا فيك إلا وقد ... جفت به الأقلام من قبلي)\nال فبعث إليه عبد الله بن معن فأتي به فدعا بغلمان له ثم أمرهم أن يرتكبوا منه الفاحشة ففعلوا ذلك ثم أجلسه وقال له قد جزيتك على قولك في فهل لك في الصلح ومعه مركب وعشرة آلاف درهم أو تقيم على الحرب قال بل الصلح قال فأسمعني ما تقوله في الصلح فقال\n(ما لعذالي ومالي ... أمروني بالضلال)\n(عذلوني في اغتفاري ... لابن معن واحتمالي)\n(إن يكن ما كان منه ... فبجرمي وفعالي)\n(أنا منه كنت أسوأ ... عشرة في كل حال)\n(قل لمن يعجب من حسن ... رجوعي ومقالي)\n(رب ود بعد صد ... وهوى بعد تقالي)\n(قد رأينا ذا كثيرا ... جاريا بين الرجال)\n(إنما كانت يميني ... لطمت مني شمالي)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":7,"spl":"قصيدته في هجو عبد الله بن معن — خبره مع سعدى مولاه ابن معن"},
{"id":"b33-18","bab":"الجزء 4","sec":"خبره مع سعدى مولاه ابن معن","page":"ج4 ص27","text":"حدثني محمد بن يحيى الصولي قال حدثنا محمد بن موسى اليزيدي قال حدثنا أبو سويد عبد القوي بن محمد بن أبي العتاهية ومحمد بن سعد قالا كان أبو العتاهية يهوى في حداثته امرأة نائحة من أهل الحيرة لها حسن وجمال يقال لها سعدى وكان عبد الله بن معن بن زائدة المكني بأبي الفضل يهواها أيضا وكانت مولاة لهم ثم أتهمها أبو العتاهية بالنساء فقال فيها\n(ألا يا ذوات السحق في الغرب والشرق ... أفقن فإن النيك أشفى من السحق)\n(أفقن فإن الخبز بالأدم يشتهى ... وليس يسوغ الخبز بالخبز في الحلق)\n(أراكن ترقعن الخروق بمثلها ... وأي لبيب يرقع الخرق بالخرق)\n(وهل يصلح المهراس إلا بعوده ... إذا احتيج منه ذات يوم إلى الدق)\nدثني الصولي قال حدثني الغلابي قال حدثني مهدي بن سابق قال تهدد عبد الله بن معن أبا العتاهية وخوفه ونهاه أن يعرض لمولاته سعدى فقال أبو العتاهية\n(ألا قل لابن معن ذا الذي ... في الود قد حالا)\n(لقد بلغت ما قال ... فما باليت ما قالا)\n(ولو كان من الأسد ... لما صال ولا هالا)\n(فصغ ما كنت حليت ... به سيفك خلخالا)\n(وما تصنع بالسيف ... إذا لم تك قتالا)\n(ولو مد إلى أذنيه ... كفيه لما نالا)\n(قصير الطول والطيلة ... لا شب ولا طالا)\n(أرى قومك أبطالا ... وقد أصبحت بطالا)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":7,"spl":"قصيدته في هجو عبد الله بن معن — خبره مع سعدى مولاه ابن معن"},
{"id":"b33-19","bab":"الجزء 4","sec":"هجاؤه معن وأخاه يزيد","page":"ج4 ص28","text":"حدثنا الصولي قال حدثنا محمد بن موسى قال حدثني سليمان المدائني قال احتال عبد الله بن معن على أبي العتاهية حتى أخذ في مكان فضربه مائة سوط ضربا ليس بالمبرح غيظا عليه وإنما لم يعنف في ضربه خوفا من كثرة من يعنى به فقال أبو العتاهية يهجوه\n(جلدتني بكفها ... بنت معن بن زائده)\n(جلدتني فأوجعت ... بأبي تلك جالده)\n(وتراها مع الخصي ... على الباب قاعده)\n(تتكنى كنى الرجال ... بعمد مكايده)\n(جلدتني وبالغت ... مائة غير واحده)\n(إجلديني واجلدي ... إنما أنت والده)\nقال أيضا\n(ضربتني بكفها بنت معن ... أوجعت كفها وما أوجعتني)\n(ولعمري لولا أذى كفها إذ ... ضربتني بالسوط ما تركتني)\nال الصولي حدثنا عون بن محمد ومحمد بن موسى قالا لما اتصل هجاء أبي العتاهية بعبد الله بن معن وكثر غضب أخوه يزيد بن\nمعن من ذلك وتوعد أبا العتاهية فقال فيه قصيدته التي أولها\n(بنى معن ويهدمه يزيد ... كذاك الله يفعل ما يريد)\n(فمعن كان للحساد غما ... وهذا قد يسر به الحسود)\n(يزيد يزيد في منع وبخل ... وينقص في العطاء ولا يزيد)\nحدثني الصولي قال حدثني جبلة بن محمد قال حدثني أبي قال مضى بنو معن إلى مندل وحيان ابني علي العنزيين الفقيهين وهما من بني عمرو بن عامر بطن من يقدم بن عنزة وكان من سادات أهل الكوفة فقالوا لهما نحن بيت واحد وأهل ولا فرق بيننا وقد أتانا من مولاكم هذا ما لو أتانا من بعيد الولاء لوجب أن تردعاه فأحضر أبا العتاهية ولم يكن يمكنه الخلاف عليهما فأصلح بينه وبين عبد الله ويزيد ابني معن وضمنا عنه خلوص النية وعنهما أن ألا يتبعاه بسوء وكان ممن لا يمكن خلافهما فرجحت الحال إلى المودة والصفاء فجعل الناس يعذلون أبا العتاهية على ما فرط منه ولامه آخرون في صلحه لهما فقال\n(ما لعذالي ومالي ... أمروني بالضلال)\nقد كتبت متقدمة حدثني الصولي قال حدثنا محمد بن موسى قال كان زائدة بن معن صديقا لأبي العتاهية ولم يعن إخوته عليه فمات فقال أبو العتاهية يرثيه\n(حزنت لموت زائدة بن معن ... حقيق أن يطول عليه حزني)\n(فتى الفتيان زائدة المصفى ... أبو العباس كان أخي وخدني)\n(فتى قوم وأي فتى توارت ... به الأكفان تحت ثرى ولبن)\n(ألا يا قبر زائدة بن معن ... دعوتك كي تجيب فلم تجبني)\n(سل الأيام عن أركان قومي ... أصبن بهن ركنا بعد ركن)\nخبرني الصولي قال حدثنا الحسن بن علي الرازي القارئ قال حدثني أحمد بن أبي فنن قال كنا عند ابن الأعرابي فذكروا قول ابن نوفل في عبد الملك بن عمير\n(إذا ذات دل كلمته لحاجة ... فهم بأن يقضي تنحنح أو سعل)\nوأن عبد الملك قال تركني والله وإن السعلة لتعرض لي في الخلاء فأذكر قوله فأهاب أن أسعل قال فقلت لابن الأعرابي فهذا أبو العتاهية قال في عبد الله بن معن بن زائدة\n(فصغ ما كنت حليت ... به سيفك خلخالا)\n(وما تصنع بالسيف ... إذا لم تك قتالا)\nقال عبد الله بن معن ما لبست سيفي قط فرأيت إنسانا يلمحني إلا ظننت أنه يحفظ قول أبي العتاهية في فلذلك يتأملني فأخجل فقال ابن الأعرابي اعجبوا لعبد يهجو مولاه قال وكان ابن الأعرابي مولى بني شيبان","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":8,"spl":"هجاؤه معن وأخاه يزيد"},
{"id":"b33-20","bab":"الجزء 4","sec":"ناظر مسلم بن الوليد في قول الشعر","page":"ج4 ص30","text":"نسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال\nحدثني الحسين بن أبي السري قال اجتمع أبو العتاهية ومسلم بن الوليد الأنصاري في بعض المجالس فجرى بينهما كلام فقال له مسلم والله لو كنت أرضى أن أقول مثل قولك\n(الحمد والنعمة لك ... والملك لا شريك لك)\n(لبيك إن الملك لك ... )\nقلت في اليوم عشرة آلاف بيت ولكني أقول\n(موف على مهج في يوم ذي رهج ... كأنه أجل يسعى إلى أمل)\n(ينال بالرفق ما يعيا الرجال به ... كالموت مستعجلا يأتي على مهل)\n(يكسو السيوف نفوس الناكثين به ... ويجعل الهام تيجان القنا الذبل)\n(لله من هاشم في أرضه جبل ... وأنت وابنك ركنا ذلك الجبل)\nقال له أبو العتاهية قل مثل قولي\n(الحمد والنعمة لك ... )\nقل مثل قولك\n(كأنه أجل يسعى إلى أمل ... )\nشار يستحسن اعتذاره حدثني الصولي قال حدثنا الغلابي قال حدثنا مهدي بن سابق قال قال بشار لأبي العتاهية أنا والله أستحسن اعتذارك من دمعك حيث تقول\n(كم من صديق لي أسارقه ... البكاء من الحياء)\n(فإذا تأمل لامني ... فأقول ما بي من بكاء)\n(لكن ذهبت لأرتدي ... فطرفت عيني بالرداء)\nقال له أبو العتاهية لا والله يا أبا معاذ ما لذت إلا بمعناك ولا اجتنيت إلا من غرسك حيث تقول صوت\n(شكوت إلى الغواني ما ألاقي ... وقلت لهن ما يومي بعيد)\n(فقلن بكيت قلت لهن كلا ... وقد يبكي من الشوق الجليد)\n(ولكني أصاب سواد عيني ... عويد قذى له طرف حديد)\n(فقلن فما لدمعهما سواء ... أكلتا مقلتيك أصاب عود)\nإبراهيم لموصلي في هذه الأبيات لحن من الثقيل الأول بالوسطى مطلق أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن هارون الأزرقي مولى بني هاشم عن ابن عائشة عن ابن لمحمد بن الفضل الهاشمي قال جاء أبو العتاهية إلى أبي فتحدثا ساعة وجعل أبي يشكو إليه تخلف الصنعة وجفاء السلطان فقال لي أبو العتاهية اكتب\n(كل على الدنيا له حرص ... والحادثات أناتها غفص)\n(وكأن من واروه في جدث ... لم يبد منه لناظر شخص)\n(تبغي من الدنيا زيادتها ... وزيادة الدنيا هي النقص)\n(ليد المنية في تلطفها ... عن ذخر كل شفيقة فحص)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":9,"spl":"ناظر مسلم بن الوليد في قول الشعر","partial":1},
{"id":"b33-21","bab":"الجزء 4","sec":"عفو الرشيد عنه بعد حبسه","page":"ج4 ص33","text":"حدثني عمرو قال حدثني علي بن محمد الهشامي عن جده ابن حمدون قال أخبرني مخارق قال لما تنسك أبو العتاهية ولبس الصوف أمره الرشيد أن يقول شعرا في الغزل فامتنع فضربه الرشيد ستين عصا وحلف ألا يخرج من حبسه حتى يقول شعرا في الغزل فلما رفعت المقارع عنه قال أبو العتاهية كل مملوك له حر وامرأته طالق إن تكلم سنة إلا بالقرآن أو بلا إله إلا الله محمد رسول الله فكأن الرشيد تحزن مما فعله فأمر أن يحبس في دار ويوسع عليه ولا يمنع من دخول من يريد إليه قال مخارق وكانت الحال بينه وبين إبراهيم الموصلي لطيفة فكان يبعثني إليه في الأيام أتعرف خبره فإذا دخلت وجدت بين يديه ظهرا ودواة فيكتب إلي ما يريد وأكلمه فمكث هكذا سنة واتفق أن إبراهيم الموصلي صنع صوته صوت\n(أعرفت دار الحي بالحجر ... فشدوريان فقنة الغمر)\n(وهجرتنا وألفت رسم بلى ... والرسم كان أحق بالهجر)\nلحن إبراهيم في هذا الشعر خفيف رمل بالوسطى وفيه لإسحاق رمل بالوسطى قال مخارق فقال لي إبراهيم اذهب إلى أبي العتاهية حتى تغنيه هذا الصوت فأتيته في اليوم الذي انقضت فيه يمينه فغنيته إياه فكتب إلي بعد أن غنيته هذا اليوم تنقضي فيه يميني فأحب أن تقيم عندي إلى الليل فأقمت عنده نهاري كله حتى إذا أذن الناس المغرب كلمني فقال يا مخارق قلت لبيك قال قل لصاحبك يابن الزانية أما والله لقد أبقيت للناس فتنة إلى يوم القيامة فانظر أين أنت من الله غدا قال مخارق فكنت أول من أفطر على كلامه فقلت دعني من هذا هل قلت شيئا للتخلص من هذا الموضع فقال نعم قد قلت في امرأتي شعرا قلت هاته فأنشدني صوت\n(من لقلب متيم مشتاق ... شفه شوقه وطول الفراق)\n(طال شوقي إلى قعيدة بيتي ... ليت شعري فهل لنا من تلاقي)\n(هي حظي قد اقتصرت عليها ... من ذوات العقود والأطواق)\n(جمع الله عاجلا بك شملي ... عن قريب وفكني من وثاقي)\nال فكتبتها وصرت بها إلى إبراهيم فصنع فيها لحنا ودخل بها على الرشيد فكان أول صوت غناه إياه في ذلك المجلس وسأله لمن الشعر والغناء فقال إبراهيم أما الغناء فلي وأما الشعر فلأسيرك أبي العتاهية فقال أو قد فعل قال نعم قد كان ذلك فدعا به ثم قال لمسرور الخادم كم ضربنا أبا العتاهية قال ستين عصا فأمر بستين ألف درهم وخلع عليه وأطلقه\nنسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال حدثنا الحسين بن أبي السري قال","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":10,"spl":"عفو الرشيد عنه بعد حبسه"},
{"id":"b33-22","bab":"الجزء 4","sec":"الفضل بن العباس يترضى يالرشيد له","page":"ج4 ص35","text":"قال لي الفضل بن العباس وجد الرشيد وهو بالرقة على أبي العتاهية وهو بمدينة السلام فكان أبو العتاهية يرجو أن يتكلم الفضل بن الربيع في أمره فأبطأ عليه بذلك فكتب إليه أبو العتاهية\n(أجفوتني فيمن جفاني ... وجعلت شأنك غير شاني)\n(ولطالما أمنتني ... مما أرى كل الأمان)\n(حتى إذا انقلب الزمان ... علي صرت مع الزمان)\nكلم الفضل فيه الرشيد فرضي عنه وأرسل إليه الفضل يأمره بالشخوص ويذكر له أن أمير المؤمنين قد رضي عنه فشخص إليه فلما دخل إلى الفضل أنشده قوله فيه\n(قد دعوناه نائيا فوجدناه ... على نأيه قريبا سميعا)\nأدخله إلى الرشيد فرجع إلى حالته الأولى أخبرنا يحيى بن علي بن يحيى إجازة قال حدثني علي بن مهدي قال حدثني الحسين بن أبي السري قال كان يزيد بن منصور خال المهدي يتعصب لأبي العتاهية لأنه كان يمدح اليمانية أخوال المهدي في شعره فمن ذلك قوله\nصوت\n(سقيت الغيث يا قصر السلام ... فنعم محلة الملك الهمام)\n(لقد نشر الإله عليك نورا ... وحفك بالملائكة الكرام)\n(سأشكر نعمة المهدي حتى ... تدور علي دائرة الحمام)\n(له بيتان بيت تبعي ... وبيت حل بالبلد الحرام)\nقال وكان أبو العتاهية طول حياة يزيد بن منصور يدعي أنه مولى لليمن وينتفي من عنزة فلما مات يزيد رجع إلى ولائه الأول فحدثني الفضل بن العباس قال قلت له ألم تكن تزعم أن ولاءك لليمن قال ذلك شيء احتجنا إليه في ذلك الزمن وما في واحد ممن انتميت إليه خير ولكن الحق أحق أن يتبع وكان ادعى ولاء اللخميين قال وكان يزيد بن منصور من أكرم الناس وأحفظهم لحرمة وأرعاهم لعهد وكان بارا بأبي العتاهية كثيرا فضله عليه وكان أبو العتاهية منه في منعة وحصن حصين مع كثرة ما يدفعه إليه ويمنعه من المكاره فلما مات قال أبو العتاهية يرثيه\n(أنعى يزيد بن منصور إلى البشر ... أنعى يزيد لأهل البدو والحضر)\n(يا ساكن الحفرة المهجور ساكنها ... بعد المقاصر والأبواب والحجر)\n(وجدت فقدك في مالي وفي نشبي ... وجدت فقدك في شعري وفي بشري)\n(فلست أدري جزاك الله صالحة ... أمنظري اليوم أسوا فيك أم خبري)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":11,"spl":"الفضل بن العباس يترضى يالرشيد له — اجتماعه مع بشار عند المهدي"},
{"id":"b33-23","bab":"الجزء 4","sec":"اجتماعه مع بشار عند المهدي","page":"ج4 ص36","text":"حدثنا ابن عمار قال حدثنا محمد بن إبراهيم بن خلف قال حدثني أبي قال\nحدثت أن المهدي جلس للشعراء يوما فأذن لهم وفيهم بشار وأشجع وكان أشجع يأخذ عن بشار ويعظمه وغير هذين وكان في القوم أبو العتاهية قال أشجع فلما سمع بشار كلامه قال يا أخا سليم أهذا ذلك الكوفي الملقب قلت نعم قال لا جزى الله خيرا من جمعنا معه ثم قال له المهدي أنشد فقال ويحك أو يبدأ فيستنشد أيضا قبلنا فقلت قد ترى فأنشد\n(ألا ما لسيدتي ما لها ... أدلا فأحمل إدلالها)\n(وإلا ففيم تجنت وما ... جنيت سقى الله أطلالها)\n(ألا إن جارية للإمام ... قد أسكن الحب سربالها)\n(مشت بين حور قصار الخطا ... تجاذب في المشي أكفالها)\n(وقد أتعب الله نفسي بها ... وأتعب باللوم عذالها)\nال أشجع فقال لي بشار ويحك يا أخا سليم ما أدري من أي أمريه أعجب أمن ضعف شعره أم من تشبيبه بجارية الخليفة يسمع ذلك بأذنه حتى أتى على قوله\n(أتته الخلافة منقادة ... إليه تجرر أذيالها)\n(ولم تك تصلح إلا له ... ولم يك يصلح إلا لها)\n(ولو رامها أحد غيره ... لزلزلت الأرض زلزالها)\n(ولو لم تطعه بنات القلوب ... لما قبل الله أعمالها)\n(وإن الخليفة من بغض لا ... إليه ليبغض من قالها)\nال أشجع فقال لي بشار وقد اهتز طربا ويحك يا أخا سليم أترى الخليفة لم يطر عن فرشه طربا لما يأتي به هذا الكوفي","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":11,"spl":"الفضل بن العباس يترضى يالرشيد له — اجتماعه مع بشار عند المهدي"},
{"id":"b33-24","bab":"الجزء 4","sec":"رمي بالزندقة","page":"ج4 ص38","text":"أخبرني يحيى بن علي إجازة قال حدثني ابن مهرويه قال حدثني العباس بن ميمون قال حدثني رجاء بن سلمة قال سمعت أبا العتاهية يقول قرأت البارحة ( عم يتساءلون\nثم قلت قصيدة أحسن منها قال وقد قيل إن منصور بن عمار شنع عليه بهذا قال يحيى بن علي حدثنا ابن مهرويه قال حدثني أبو عمر القرشي قال لما قص منصور بن عمار على الناس مجلس البعوضة قال أبو العتاهية إنما سرق منصور هذا الكلام من رجل كوفي فبلغ قوله منصورا فقال أبو العتاهية زنديق أما ترونه لا يذكر في شعره الجنة ولا النار وإنما يذكر الموت فقط فبلغ ذلك أبا العتاهية فقال فيه\n(يا واعظ الناس قد أصبحت متهما ... إذ عبت منهم أمورا أنت تأتيها)\n(كالملبس الثوب من عري وعورته ... للناس بادية ما إن يواريها)\n(فأعظم الإثم بعد الشرك نعلمه ... في كل نفس عماها عن مساويها)\n(عرفانها بعيوب الناس تبصرها ... منهم ولا تبصر العيب الذي فيها)\nفلم تمض إلا أيام يسيرة حتى مات منصور بن عمار فوقف أبو العتاهية على قبره وقال يغفر الله لك أبا السري ما كنت رميتني به أخبرني محمد بن يحيى قال حدثنا محمد بن موسى قال أخبرني النسائي عن محمد بن أبي العتاهية قال كانت لأبي العتاهية جارة تشرف عليه فرأته ليلة يقنت فروت عنه أنه يكلم القمر واتصل الخبر بحمدويه صاحب الزنادقة فصار إلى منزلها وبات وأشرف على أبي العتاهية ورآه يصلي ولم يزل يرقبه حتى قنت وانصرف إلى مضجعه وانصرف حمدويه خاسئا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":12,"spl":"رمي بالزندقة"},
{"id":"b33-25","bab":"الجزء 4","sec":"شعره الذي يدل على توحيده","page":"ج4 ص39","text":"حدثنا محمد بن يحيى قال حدثنا محمد بن الرياشي قال حدثنا الخليل بن أسد النوشجاني قال جاءنا أبو العتاهية إلى منزلنا فقال زعم الناس أني زنديق والله ما ديني إلا التوحيد فقلنا له فقل شيئا نتحدث به عنك فقال\n(ألا إننا كلنا بائد ... وأي بني آدم خالد)\n(وبدؤهم كان من ربهم ... وكل إلى ربه عائد)\n(فيا عجبا كيف يعصى الإله ... أم كيف يجحده الجاحد)\n(وفي كل شيء له آية ... تدل على أنه واحد)\nخبرني أبو دلف هاشم بن محمد الخزاعي قال\nتذاكروا يوما شعر أبي العتاهية بحضرة الجاحظ إلى أن جرى ذكر أرجوزته المزدوجة التي سماها ذات الأمثال فأخذ بعض من حضر ينشدها حتى أتى على قوله\n(يا للشباب المرح التصابي ... روائح الجنة في الشباب)\nقال الجاحظ للمنشد قف ثم قال انظروا إلى قوله\n(روائح الجنة في الشباب ... )\nإن له معنى كمعنى الطرب الذي لا يقدر على معرفته إلا القلوب وتعجز عن ترجمته الألسنة إلا بعد التطويل وإدامة التفكير وخير المعاني ما كان القلب إلى قبوله أسرع من اللسان إلى وصفه وهذه الأرجوزة من بدائع أبي العتاهية ويقال إن له فيها أربعة آلاف مثل منها قوله\n(حسبك مما تبتغيه القوت ... ما أكثر القوت لمن يموت)\n(الفقر فيما جاوز الكفافا ... من اتقى الله رجا وخافا)\n(هي المقادير فلمني أو فذر ... إن كنت أخطأت فما أخطا القدر)\n(لكل ما يؤذي وإن قل ألم ... ما أطول الليل على من لم ينم)\n(ما انتفع المرء بمثل عقله ... وخير ذخر المرء حسن فعله)\n(إن الفساد ضده الصلاح ... ورب جد جره المزاح)\n(من جعل النمام عينا هلكا ... مبلغك الشر كباغيه لكا)\n(إن الشباب والفراغ والجدة ... مفسدة للمرء أي مفسدة)\n(يغنيك عن كل قبيح تركه ... ترتهن الرأي الأصيل شكه)\n(ما عيش من آفته بقاؤه ... نغص عيشا كله فناؤه)\n(يا رب من أسخطنا بجهده ... قد سرنا الله بغير حمده)\n(ما تطلع الشمس ولا تغيب ... إلا لأمر شأنه عجيب)\n(لكل شيء معدن وجوهر ... وأوسط وأصغر وأكبر)\n(من لك بالمحض وكل ممتزج ... وساوس في الصدر منه تعتلج)\n(وكل شيء لاحق بجوهره ... أصغره متصل بأكبره)\n(ما زالت الدنيا لنا دار أذى ... ممزوجة الصفو بألوان القذى)\n(الخير والشر بها أزواج ... لذا نتاج ولذا نتاج)\n(من لك بالمحض وليس محض ... يخبث بعض ويطيب بعض)\n(لكل إنسان طبيعتان ... خير وشر وهما ضدان)\n(إنك لو تستنشق الشحيحا ... وجدته أنتن شيء ريحا)\n(والخير والشر إذا ما عدا ... بينهما بون بعيد جدا)\n(عجبت حتى غمني السكوت ... صرت كأني حائر مبهوت)\n(كذا قضى الله فكيف أصنع ... الصمت إن ضاق الكلام أوسع)\nهي طويلة جدا وإنما ذكرت هذا القدر منها حسب ما استاق الكلام من صفتها أخبرني الحسن بن علي قال حدثنا ابن مهرويه عن روح بن الفرج قال شاور رجل أبا العتاهية فيما ينقشه على خاتمه فقال انقش عليه لعنة الله على الناس وأنشد\n(برمت بالناس وأخلاقهم ... فصرت أستأنس بالوحدة)\n(ما أكثر الناس لعمري وما ... أقلهم في حاصل العده)\nدثنا الصولي قال حدثنا الغلابي قال حدثنا عبد الله بن الضحاك أن\nعمر بن العلاء مولى عمرو بن حريث صاحب المهدي كان ممدحا فمدحه أبو العتاهية فأمر له بسبعين ألف درهم فأنكر ذلك بعض الشعراء وقال كيف فعل هذا بهذا الكوفي وأي شيء مقدار شعره فبلغه ذلك فأحضر الرجل وقال له والله إن الواحد منكم ليدور على المعنى فلا يصيبه ويتعاطاه فلا يحسنه حتى يشبب بخمسين بيتا ثم يمدحنا ببعضها وهذا كأن المعاني تجمع له مدحني فقصر التشبيب وقال\n(إني أمنت من الزمان وريبه ... لما علقت من الأمير حبالا)\n(لو يستطيع الناس من إجلاله ... لحذوا له حر الوجوه نعالا)\nصوت\n(إن المطايا تشتكيك لأنها ... قطعت إليك سباسبا ورمالا)\n(فإذا وردن بنا وردن مخفة ... وإذا رجعن بنا رجعن ثقالا)\nخذ هذا المعنى من قول نصيب\n(فعاجوا فأثنوا بالذي أنت أهله ... ولو سكتوا أثنت عليك الحقائب)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":13,"spl":"شعره الذي يدل على توحيده","partial":1},
{"id":"b33-26","bab":"الجزء 4","sec":"العتابي يقول عنه أنه أشعر الناس","page":"ج4 ص42","text":"حدثنا الصولي قال حدثنا محمد بن عون قال حدثني محمد بن النضر كاتب\nغسان بن عبد الله قال أخرجت رسولا إلى عبد الله بن طاهر وهو يريد مصر فنزلت على العتابي وكان لي صديقا فقال أنشدني لشاعر العراق يعني أبا نواس وكان قد مات فأنشدته ما كنت أحفظ من ملحه وقلت له ظننتك تقول هذا لأبي العتاهية فقال لو أردت أبا العتاهية لقلت لك أنشدني لأشعر الناس ولم أقتصر على العراق أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني هارون بن سعدان عن شيخ من أهل بغداد قال قال أبو العتاهية أكثر الناس يتكلمون بالشعر وهم لا يعلمون ولو أحسنوا تأليفه كانوا شعراء كلهم قال فبينما نحن كذلك إذ قال رجل لآخر عليه مسح يا صاحب المسح تبيع المسح فقال لنا أبو العتاهية هذا من ذلك ألم تسمعوه يقول\n(يا صاحب المسح تبيع المسحا ... )\nد قال شعرا وهو لا يعلم ثم قال الرجل تعال إن كنت تريد الربح فقال أبو العتاهية وقد أجاز المصراع بمصراع آخر وهو لا يعلم قال له\n(تعال إن كنت تريد الربحا ... )\nدثنا الصولي قال حدثنا محمد بن موسى قال حدثنا أحمد بن بشير أبو طاهر الحلبي قال حدثنا مزيد الهاشمي عن السدري قال سمعت الأصمعي يقول شعر أبي العتاهية كساحة الملوك يقع فيها الجوهر والذهب والتراب والخزف والنوى أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا الزبير بن بكار قال\nلما حبس المهدي أبا العتاهية تكلم فيه يزيد بن منصور الحميري حتى أطلقه فقال فيه أبو العتاهية\n(ما قلت في فضله شيئا لأمدحه ... إلا وفضل يزيد فوق ما قلت)\n(ما زلت من ريب دهري خائفا وجلا ... فقد كفاني بعد الله ما خفت)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":14,"spl":"العتابي يقول عنه أنه أشعر الناس — ارتجاله الشعر","partial":1},
{"id":"b33-27","bab":"الجزء 4","sec":"ارتجاله الشعر","page":"ج4 ص43","text":"أخبرني يحيى بن علي إجازة قال حدثني علي بن مهدي قال حدثني محمد بن يحيى قال حدثني عبد الله بن الحسن قال جاءني أبو العتاهية وأنا في الديوان فجلس إلي فقلت يا أبا إسحاق أما يصعب عليك شيء من الألفاظ فتحتاج فيه إلى استعمال الغريب كما يحتاج إليه سائر من يقول الشعر أو إلى ألفاظ مستكرهة قال لا فقلت له إني لأحسب ذلك من كثرة ركوبك القوافي السهلة قال فاعرض علي ما شئت من القوافي الصعبة فقلت قل أبياتا على مثل البلاغ فقال من ساعته\n(أي عيش يكون أبلغ من عيش ... كفاف قوت بقدر البلاغ)\n(صاحب البغي ليس يسلم منه ... وعلى نفسه بغى كل باغي)\n(رب ذي نعمة تعرض منها ... حائل بينه وبين المساغ)\n(أبلغ الدهر في مواعظه بل ... زاد فيهن لي على الإبلاغ)\n(غبنتني الأيام عقلي ومالي ... وشبابي وصحتي وفراغي)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":14,"spl":"العتابي يقول عنه أنه أشعر الناس — ارتجاله الشعر"},
{"id":"b33-28","bab":"الجزء 4","sec":"مسلم بن الوليد يكبره بعد أن سمع غزله","page":"ج4 ص44","text":"أخبرنا يحيى إجازة قال حدثنا علي بن مهدي قال حدثني أبو علي اليقطيني قال حدثني أبو خارجة بن مسلم قال\nقال مسلم بن الوليد كنت مستخفا بشعر أبي العتاهية فلقيني يوما فسألني أن أصير إليه فصرت إليه فجاءني بلون واحد فأكلناه وأحضرني تمرا فأكلناه وجلسنا نتحدث وأنشدته أشعارا لي في الغزل وسألته أن ينشدني فأنشدني قوله\n(بالله يا قرة العينين زوريني ... قبل الممات وإلا فاستزيريني)\n(إني لأعجب من حب يقربني ... ممن يباعدني منه ويقصيني)\n(أما الكثير فما أرجوه منك ولو ... أطمعتني في قليل كان يكفيني)\nثم أنشدني أيضا\n(رأيت الهوى جمر الغضى غير أنه ... على حره في صدر صاحبه حلو)\nي صوت\n(أخلاي بي شجو وليس بكم شجو ... وكل امرىء عن شجو صاحبه خلو)\n(وما من محب نال ممن يحبه ... هوى صادقا إلا سيدخله زهو)\n(بليت وكان المزح بدء بليتي ... فأحببت حقا والبلاء له بدو)\n(وعلقت من يزهو علي تجبرا ... وإني في كل الخصال له كفو)\n(رأيت الهوى جمر الغضى غير أنه ... على كل حال عند صاحبه حلو)\nالغناء لإبراهيم ثقيل أول مطلق في مجرى الوسطى عن إسحاق وله فيه أيضا خفيف ثقيل أول بالوسطى عن عمرو ولعمرو بن بانة رمل بالوسطى من كتابه ولعريب فيه خفيف ثقيل من كتاب ابن المعتز قال مسلم ثم أنشدني أبو العتاهية\nصوت\n(خليلي مالي لا تزال مضرتي ... تكون على الأقدار حتما من الحتم)\n(يصاب فؤادي حين أرمي ورميتي ... تعود إلى نحري ويسلم من أرمي)\n(صبرت ولا والله ما بي جلادة ... على الصبر لكني صبرت على رغمي)\n(ألا في سبيل الله جسمي وقوتي ... ألا مسعد حتى أنوح على جسمي)\n(تعد عظامي واحدا بعد واحد ... بمنحى من العذال عظما على عظم)\n(كفاك بحق الله ما قد ظلمتني ... فهذا مقام المستجير من الظلم)\nلغناء لسياط في هذه الأبيات وإيقاعه من خفيف الثقيل الأول بالسبابة في مجرى البنصر عن إسحاق قال مسلم فقلت له لا والله يا أبا إسحاق ما يبالي من أحسن أن يقول مثل هذا الشعر ما فاته من الدنيا فقال يابن أخي لا تقولن مثل هذا فإن الشعر أيضا من بعض مصايد الدنيا أخبرنا يحيى إجازة قال حدثني علي بن مهدي قال حدثني عبد الرحمن بن الفضل قال حدثني ابن الأعرابي قال اجتمعت الشعراء على باب الرشيد فأذن لهم فدخلوا وأنشدوا فأنشد أبو العتاهية\n(يا من تبغى زمنا صالحا ... صلاح هارون صلاح الزمن)\n(كل لسان هو في ملكه ... بالشكر في إحسانه مرتهن)\nال فاهتز له الرشيد وقال له أحسنت والله وما خرج في ذلك اليوم أحد من الشعراء بصلة غيره أخبرني يحيى بن علي إجازة قال حدثنا علي بن مهدي قال حدثنا عامر بن عمران الضبي قال حدثني ابن الأعرابي قال أجرى هارون الرشيد الخيل فجاءه فرس يقال له المشمر سابقا وكان الرشيد معجبا بذلك الفرس فأمر الشعراء أن يقولوا فيه فبدرهم أبو العتاهية فقال\n(جاء المشمر والأفراس يقدمها ... هونا على رسله منها وما انبهرا)\n(وخلف الريح حسرى وهي جاهدة ... ومر يختطف الأبصار والنظرا)\nأجزل صلته وما جسر أحد بعد أبي العتاهية أن يقول فيه شيئا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":15,"spl":"مسلم بن الوليد يكبره بعد أن سمع غزله"},
{"id":"b33-29","bab":"الجزء 4","sec":"رثى صديقه ابن ثابت","page":"ج4 ص47","text":"أخبرني يحيى إجازة قال حدثني الفضل بن عباس بن عقبة بن جعفر قال كان علي بن ثابت صديقا لأبي العتاهية وبينهما مجاوبات كثيرة في الزهد والحكمة فتوفي علي بن ثابت قبله فقال يرثيه\n(مؤنس كان لي هلك ... والسبيل التي سلك)\n(يا علي بن ثابت ... غفر الله لي ولك)\n(كل حي مملك ... سوف يفنى وما ملك)\nال الفضل وحضر أبو العتاهية علي بن ثابت وهو يجود بنفسه فلم يزل\nملتزمه حتى فاض فلما شد لحياه بكى طويلا ثم أنشد يقول\n(يا شريكي في الخير قربك الله ... فنعم الشريك في الخير كنتا)\n(قد لعمري حكيت لي غصص الموت ... فحركتني لها وسكنتا)\nال ولما دفن وقف على قبره يبكي طويلا أحر بكاء ويردد هذه الأبيات\n(ألا من لي بأنسك يا أخيا ... ومن لي أن أبثك ما لديا)\n(طوتك خطوب دهرك بعد نشر ... كذاك خطوبه نشرا وطيا)\n(فلو نشرت قواك لي المنايا ... شكوت إليك ما صنعت إليا)\n(بكيتك يا علي بدمع عيني ... فما أغنى البكاء عليك شيا)\n(وكانت في حياتك لي عظات ... وأنت اليوم أوعظ منك حيا)\nال علي بن الحسين مؤلف هذا الكتاب هذه المعاني أخذها كلها أبو العتاهية من كلام الفلاسفة لما حضروا تابوت الإسكندر وقد أخرج الإسكندر ليدفن قال بعضهم كان الملك أمس أهيب منه اليوم وهو اليوم أوعظ منه أمس وقال آخر سكنت حركة الملك في لذاته وقد حركنا اليوم في سكونه جزعا لفقده وهذان المعنيان هما اللذان ذكرهما أبو العتاهية في هذه الأشعار أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني جعفر ابن الحسين المهلبي قال لقينا أبو العتاهية فقلنا له يا أبا إسحاق من أشعر الناس قال الذي يقول\n(الله أنجح ما طلبت به ... والبر خير حقيبة الرحل)\nقلت أنشدني شيئا من شعرك فأنشدني\n(يا صاحب الروح ذي الأنفاس في البدن ... بين النهار وبين الليل مرتهن)\n(لقلما يتخطاك اختلافهما ... حتى يفرق بين الروح والبدن)\n(لتجذبني يد الدنيا بقوتها ... إلى المنايا وإن نازعتها رسني)\n(لله دنيا أناس دائبين لها ... قد ارتعوا في رياض الغي والفتن)\n(كسائمات رتاع تبتغي سمنا ... وحتفها لو درت في ذلك السمن)\nال فكتبتها ثم قلت له أنشدني شيئا من شعرك في الغزل فقال يابن أخي إن الغزل يسرع إلى مثلك فقلت له أرجو عصمة الله جل وعز فأنشدني\n(كأنها من حسنها درة ... أخرجها اليم إلى الساحل)\n(كأن في فيها وفي طرفها ... سواحرا أقبلن من بابل)\n(لم يبق مني حبها ما خلا ... حشاشة في بدن ناحل)\n(يا من رأى قبلي قتيلا بكى ... من شدة الوجد على القاتل)\nفقلت له يا أبا إسحاق هذا قول صاحبنا جميل\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\nقال هو ذاك يا بن أخي وتبسم","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":16,"spl":"رثى صديقه ابن ثابت — شعره في رحيل الشباب"},
{"id":"b33-30","bab":"الجزء 4","sec":"شعره في رحيل الشباب","page":"ج4 ص49","text":"أخبرني محمد بن القاسم الأنباري قال حدثني أبي قال حدثني أبو عكرمة عن شيخ له من أهل الكوفة قال\nدخلت مسجد المدينة ببغداد بعد أن بويع الأمين محمد بسنة فإذا شيخ عليه جماعة وهو ينشد\n(لهفي على ورق الشباب ... وغصونه الخضر الرطاب)\n(ذهب الشباب وبان عني ... غير منتظر الإياب)\n(فلأبكين على الشباب ... وطيب أيام التصابي)\n(ولأبكين من البلى ... ولأبكين من الخضاب)\n(إني لآمل أن أخلد ... والمنية في طلابي)\nال فجعل ينشدها وإن دموعه لتسيل على خديه فلما رأيت ذلك لم أصبر أن ملت فكتبتها وسألت عن الشيخ فقيل لي هو أبو العتاهية أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني أبو العباس محمد بن أحمد قال كان ابن الأعرابي يعيب أبا العتاهية ويثلبه فأنشدته\n(كم من سفيه غاظني سفها ... فشفيت نفسي منه بالحلم)\n(وكفيت نفسي ظلم عاديتي ... ومنحت صفو مودتي سلمي)\n(ولقد رزقت لظالمي غلظا ... ورحمته إذ لج في ظلمي)\nخبرني محمد بن عمران قال حدثني العنزي قال حدثني محمد بن إسحاق قال حدثني محمد بن أحمد الأزدي قال قال لي أبو العتاهية لم أقل شيئا قط أحب إلي من هذين البيتين في معناهما\n(ليت شعري فإنني لست أدري ... أي يوم يكون آخر عمري)\n(وبأي البلاد يقبض روحي ... وبأي البقاع يحفر قبري)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":16,"spl":"رثى صديقه ابن ثابت — شعره في رحيل الشباب"},
{"id":"b33-31","bab":"الجزء 4","sec":"خبره مع فتيان يتذاكرون الشعر","page":"ج4 ص51","text":"أخبرني محمد بن العباس اليزيدي قال حدثني محمد بن الفضل قال حدثنا محمد بن عبد الجبار الفزاري قال اجتاز أبو العتاهية في أول أمره وعلى ظهره قفص فيه فخار يدور به في الكوفة ويبيع منه فمر بفتيان جلوس يتذاكرون الشعر ويتناشدونه فسلم ووضع القفص عن ظهره ثم قال يا فتيان أراكم تذاكرون الشعر فأقول شيئا منه فتجيزونه فإن فعلتم فلكم عشرة دراهم وإن لم تفعلوا فعليكم عشرة دراهم فهزئوا منه وسخروا به وقالوا نعم قال لا بد أن يشترى بأحد القمارين رطب يؤكل فإنه قمار حاصل وجعل رهنه تحت يد أحدهم ففعلوا فقال أجيزوا\n(ساكني الأجداث أنتم ... )\nجعل بينه وبينهم وقتا في ذلك الموضع إذا بلغته الشمس ولم يجيزوا البيت غرموا الحطر وجعل يهزأ بهم وتممه\n(. . . . . . . . . . . . . . . ... . مثلنا بالأمس كنتم)\n(ليت شعري ما صنعتم ... أربحتم أم خسرتم)\nهي قصيدة طويلة في شعره أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله عن أبي خيثم العنزي قال لما حبس الرشيد أبا العتاهية وحلف ألا يطلقه أو يقول شعرا قال لي أبو حبش أسمعت بأعجب من هذا الأمر تقول الشعراء الشعر الجيد النادر فلا يسمع\nمنهم ويقول هذا المخنث المفكك تلك الأشعار بالشفاعة ثم أنشدني\n(أبا إسحاق راجعت الجماعه ... وعدت إلى القوافي والصناعه)\n(وكنت كجامح في الغي عاص ... وأنت اليوم ذو سمع وطاعه)\n(فجر الخز مما كنت تكسى ... ودع عنك التقشف والبشاعه)\n(وشبب بالتي تهوى وخبر ... بأنك ميت في كل ساعه)\n(كسدنا ما نراد وإن أجدنا ... وأنت تقول شعرك بالشفاعه)\nخبرني أحمد بن العباس العسكري قال حدثنا العنزي قال حدثنا محمد بن عبد الله قال حدثني أبو خيثم العنزي وكان صديقا لأبي العتاهية قال حدثني أبو العتاهية قال أخرجني المهدي معه إلى الصيد فوقعنا منه على شيء كثير فتفرق أصحابه في طلبه وأخذ هو في طريق غير طريقهم فلم يلتقوا وعرض لنا واد جرار وتغيمت السماء وبدأت تمطر فتحيرنا وأشرفنا على الوادي فإذا فيه ملاح يعبر الناس فلجأنا إليه فسألناه عن الطريق فجعل يضعف رأينا ويعجزنا في بذلنا أنفسنا في ذلك الغيم للصيد حتى أبعدنا ثم أدخلنا كوخا له وكاد المهدي يموت بردا فقال له أغطيك بجبتي هذه الصوف فقال نعم فغطاه بها فتماسك قليلا ونام فافتقده غلمانه وتبعوا أثره حتى جاؤونا فلما رأى الملاح كثرتهم علم أنه الخليفة فهرب وتبادر الغلمان فنحوا الجبة عنه وألقوا عليه الخز والوشي فلما انتبه قال لي ويحك ما فعل الملاح فقد والله وجب حقه علينا فقلت هرب والله خوفا من قبح ما خاطبنا به قال إنا لله والله لقد أردت أن أغنيه وبأي شيء خاطبنا نحن والله مستحقون لأقبح مما خاطبنا به بحياتي عليك إلا ما هجوتني فقلت يا أمير المؤمنين كيف تطيب نفسي بأن أهجوك قال والله لتفعلن فإني ضعيف الرأي مغرم بالصيد فقلت\n(يا لابس الوشي على ثوبه ... ما أقبح الأشيب في الراح)\nقال زدني بحياتي فقلت\n(لو شئت أيضا جلت في خامة ... وفي وشاحين وأوضاح)\nقال ويلك هذا معنى سوء يرويه عنك الناس وأنا استأهل زدني شيئا آخر فقلت أخاف أن تغضب قال لا والله فقلت\n(كم من عظيم القدر في نفسه ... قد نام في جبة ملاح)\nقال معنى سوء عليك لعنة الله وقمنا وركبنا وانصرفنا أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد قال حدثنا جماعة من كتاب الحسن بن سهل قالوا وقعت رقعة فيها بيتا شعر في عسكر المأمون فجيء بها إلى مجاشع بن مسعدة فقال هذا كلام أبي العتاهية وهو صديقي وليست المخاطبة لي ولكنها للأمير الفضل بن سهل فذهبوا بها فقرأها وقال ما أعرف هذه العلامة فبلغ المأمون خبرها فقال هذه إلي وأنا أعرف العلامة والبيتان صوت\n(ما على ذا كنا افترقنا بسندان ... وما هكذا عهدنا الإخاء)\n(تضرب الناس بالمهندة البيض ... على غدرهم وتنسى الوفاء)\nقال فبعث إليه المأمون بمال في هذين البيتين لأبي عيسى بن المتوكل رمل من رواية ابن المعتز","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":17,"spl":"خبره مع فتيان يتذاكرون الشعر","partial":1},
{"id":"b33-32","bab":"الجزء 4","sec":"أبو العتاهية يستعجل بر ابن يقطين","page":"ج4 ص54","text":"قال وكان علي بن يقيطن صديقا لأبي العتاهية وكان يبره في كل سنة ببر واسع فأبطأ عليه بالبر في سنة من السنن وكان إذا لقيه أبو العتاهية أو دخل عليه يسر به ويرفع مجلسه ولا يزيده على ذلك فلقيه ذات يوم وهو يريد دار الخليفة فاستوقفه فوقف له فأنشده\n(حتى متى ليت شعري يابن يقطين ... أثني عليك بما لا منك توليني)\n(إن السلام وإن البشر من رجل ... في مثل ما أنت فيه ليس يكفيني)\n(هذا زمان ألح الناس فيه على ... تيه الملوك وأخلاق المساكين)\n(أما علمت جزاك الله صالحة ... وزادك الله فضلا يابن يقطين)\n(أني أريدك للدنيا وعاجلها ... ولا أريدك يوم الدين للدين)\nقال علي بن يقطين لست والله أبرح ولا تبرح من موضعنا هذا إلا راضيا وأمر له بما كان يبعث به إليه في كل سنة فحمل من وقته وعلي واقف إلى أن تسلمه وأخبرني محمد بن جعفر النحوي صهر المبرد قال حدثنا محمد بن يزيد قال بلغني من غير وجه أن الرشيد لما ضرب أبا العتاهية وحبسه وكل به صاحب خبر يكتب إليه بكل ما يسمعه فكتب إليه أنه سمعه ينشد\n(أما والله إن الظلم لوم ... وما زال المسيء هو الظلوم)\n(إلى ديان يوم الدين نمضي ... وعند الله تجتمع الخصوم)\nال فبكى الرشيد وأمر بإحضار أبي العتاهية وإطلاقه وأمر له بألفي دينار","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":18,"spl":"أبو العتاهية يستعجل بر ابن يقطين — شنع عليه منصور بن عمار بالزندقة"},
{"id":"b33-33","bab":"الجزء 4","sec":"شنع عليه منصور بن عمار بالزندقة","page":"ج4 ص55","text":"أخبرني محمد بن جعفر قال حدثني محمد بن موسى عن أحمد بن حرب عن محمد بن أبي العتاهية قال لما قال أبي في عتبة\n(كأن عتابة من حسنها ... دمية قس فتنت قسها)\n(يا رب لو أنسيتنيها بما ... في جنة الفردوس لم أنسها)\nنع عليه منصور بن عمار بالزندقة وقال يتهاون بالجنة ويبتذل ذكرها في شعره بمثل هذا التهاون وشنع عليه أيضا بقوله\n(إن المليك رآك أحسن ... خلقه ورأى جمالك)\n(فحذا بقدرة نفسه ... حور الجنان على مثالك)\nقال أيصور الحور على مثال امرأة آدمية والله لا يحتاج إلى مثال وأوقع له هذا على ألسنة العامة فلقي منهم بلاء حدثني هاشم بن محمد الخزاعي قال حدثنا خليل بن أسد قال حدثني أبو سلمة الباذغيسي قال\nقلت لأبي العتاهية في أي شعر أنت أشعر قال قولي\n(الناس في غفلاتهم ... ورحا المنية تطحن)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":18,"spl":"أبو العتاهية يستعجل بر ابن يقطين — شنع عليه منصور بن عمار بالزندقة"},
{"id":"b33-34","bab":"الجزء 4","sec":"أنشد المأمون أحسن ما قاله في الموت","page":"ج4 ص56","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني يحيى بن عبد الله القرشي قال حدثني المعلى بن أيوب قال دخلت على المأمون يوما وهو مقبل على شيخ حسن اللحية خضيب شديد بياض الثياب على رأسه لاطئة فقلت للحسن بن أبي سعيد قال وهو ابن خالة المعلى بن أيوب وكان الحسن كاتب المأمون على العامة من هذا فقال أما تعرفه فقلت لو عرفته ما سألتك عنه فقال هذا أبو العتاهية فسمعت المأمون يقول له أنشدني أحسن ما قلت في الموت فأنشده\n(أنساك محياك المماتا ... فطلبت في الدنيا الثباتا)\n(أوثقت بالدنيا وأنت ... ترى جماعتها شتاتا)\n(وعزمت منك على الحياة ... وطولها عزما بتاتا)\n(يا من رأى أبويه فيمن ... قد رأى كانا فماتا)\n(هل فيهما لك عبرة ... أم خلت أن لك انفلاتا)\n(ومن الذي طلب التفلت ... من منيته ففاتا)\n(كل تصبحه المنية ... أو تبيته بياتا)\nال فلما نهض تبعته فقبضت عليه في الصحن أو في الدهليز فكتبتها عنه نسخت من كتاب هارون بن علي بن يحيى قال حدثني علي بن مهدي قال حدثني الجاحظ عن ثمامة قال\nدخل أبو العتاهية على المأمون فأنشده\n(ما أحسن الدنيا وإقبالها ... إذا أطاع الله من نالها)\n(من لم يواس الناس من فضلها ... عرض للإدبار إقبالها)\nقال له المأمون ما أجود البيت الأول فأما الثاني فما صنعت فيه شيئا الدنيا تدبر عمن واسى أو ضن بها وإنما يوجب السماحة بها الأجر والضن بها الوزر فقال صدقت يا أمير المؤمنين أهل الفضل أولى بالفضل وأهل النقص أولى بالنقص فقال المأمون ادفع إليه عشرة آلاف درهم لاعترافه بالحق فلما كان بعد أيام عاد فأنشده\n(كم غافل أودى به الموت ... لم يأخذ الأهبة للفوت)\n(من لم تزل نعمته قبله ... زال عن النعمة بالموت)\nقال له أحسنت الآن طيبت المعنى وأمر له بعشرين ألف درهم أخبرني أحمد بن العباس العسكري قال حدثنا الحسن بن عليل العنزي قال حدثني ابن سنان العجلي عن الحسن بن عائذ قال كان أبو العتاهية يحج في كل سنة فإذا قدم أهدى إلى المأمون بردا ومطرفا ونعلا سوداء ومساويك أراك فيبعث إليه بعشرين ألف درهم وكان يوصل الهدية من جهته منجاب مولى المأمون ويجيئه بالمال فأهدى مرة له كما كان يهدي كل سنة إذا قدم فلم يثبه ولا بعث إليه بالوظيفة فكتب إليه أبو العتاهية\n(خبروني أن من ضرب السنة ... جددا بيضا وصفرا حسنه)\n(أحدثت لكنني لم أرها ... مثل ما كنت أرى كل سنه)\nفأمر المأمون بحمل العشرين ألف درهم وقال أغفلناه حتى ذكرنا حدثنا محمد بن يحيى الصولي قال حدثنا المغيرة بن محمد المهلبي قال حدثنا الزبير بن بكار قال أخبرني عروة بن يوسف الثقفي قال لما ولي الهادي الخلافة كان واجدا على أبي العتاهية لملازمته أخاه هارون وانقطاعه إليه وتركه موسى وكان أيضا قد أمر أن يخرج معه إلى الري فأبى ذلك فخافه وقال يستعطفه\n(ألا شافع عند الخليفة يشفع ... فيدفع عنا شر ما يتوقع)\n(وإني على عظم الرجاء لخائف ... كأن على رأسي الأسنة تشرع)\n(يروعني موسى على غير عثرة ... ومالي أرى موسى من العفو أوسع)\n(وما آمن يمسي ويصبح عائذا ... بعفو أمير المؤمنين يروع)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":19,"spl":"أنشد المأمون أحسن ما قاله في الموت"},
{"id":"b33-35","bab":"الجزء 4","sec":"مدح الهادي فأجازه","page":"ج4 ص58","text":"حدثني الصولي قال حدثني علي بن الصباح قال حدثني محمد بن أبي العتاهية قال دخل أبي على الهادي فأنشده\n(يا أمين الله مالي ... لست أدري اليوم مالي)\n(لم أنل منك الذي قد ... نال غيري من نوال)\n(تبذل الحق وتعطي ... عن يمين وشمال)\n(وأنا البائس لا تنظر ... في رقة حالي)\nال فأمر المعلى الخازن أن يعطيه عشرة آلاف درهم قال أبو العتاهية\nفأتيته فأبى أن يعطيها ذلك أن الهادي امتحنني في شيء من الشعر وكان مهيبا فكنت أخافه فلم يطعني طبعي فأمر لي بهذا المال فخرجت فلما منعنيه المعلى صرت إلى أبي الوليد أحمد بن عقال وكان يجالس الهادي فقلت له\n(أبلغ سلمت أبا الوليد سلامي ... عني أمير المؤمنين إمامي)\n(وإذا فرغت من السلام فقل له ... قد كان ما شاهدت من إفحامي)\n(وإذا حصرت فليس ذاك بمبطل ... ما قد مضى من حرمتي وذمامي)\n(ولطالما وفدت إليك مدائحي ... مخطوطة فليأت كل ملام)\n(أيام لي لسن ورقة جدة ... والمرء قد يبلى مع الأيام)\nال فاستخرج لي الدراهم وأنفذها إلي حدثني الصولي ومحمد بن عمران الصيرفي قالا حدثنا العنزي قال حدثنا محمد بن أحمد بن سليمان قال ولد للهادي ولد في أول يوم ولي الخلافة فدخل أبو العتاهية فأنشده\n(أكثر موسى غيظ حساده ... وزين الأرض بأولاده)\n(وجاءنا من صلبه سيد ... أصيد في تقطيع أجداده)\n(فاكتست الأرض به بهجة ... واستبشر الملك بميلاده)\n(وابتسم المنبر عن فرحة ... علت بها ذروة أعواده)\n(كأنني بعد قليل به ... بين مواليه وقواده)\n(في محفل تخفق راياته ... قد طبق الأرض بأجناده)\nال فأمر له موسى بألف دينار وطيب كثير وكان ساخطا عليه فرضي عنه\nأخبرني يحيى بن علي بن يحيى إجازة قال حدثني علي بن مهدي قال حدثني علي بن يزيد الخزرجي الشاعر عن يحيى بن الربيع قال دخل أبو عبيد الله على المهدي وكان قد وجد عليه في أمر بلغه عنه وأبو العتاهية حاضر المجلس فجعل المهدي يشتم أبا عبيد الله ويتغيظ عليه ثم أمر به فجر برجله ثم وحبس ثم أطرق المهدي طويلا فلما سكن أنشده أبو العتاهية\n(أرى الدنيا لمن هي في يديه ... عذابا كلما كثرت لديه)\n(تهين المكرمين لها بصغر ... وتكرم كل من هانت عليه)\n(إذا استغنيت عن شيء فدعه ... وخذ ما أنت محتاج إليه)\nتبسم المهدي وقال لأبي العتاهية أحسنت فقام أبو العتاهية ثم قال والله يا أمير المؤمنين ما رأيت أحدا أشد إكراما للدنيا ولا أصون لها ولا أشح عليها من هذا الذي جر برجله الساعة ولقد دخلت إلى أمير المؤمنين ودخل هو وهو أعز الناس فما برحت حتى رأيته أذل الناس ولو رضي من الدنيا بما يكفيه لاستوت أحواله ولم تتفاوت فتبسم المهدي ودعا بأبي عبيد الله فرضي عنه فكان أبو عبيد الله يشكر ذلك لأبي العتاهية أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن الحسن قال حدثني إسحاق بن حفص قال أنشدني هارون بن مخلد الرازي لأبي العتاهية\n(ما إن يطيب لذي الرعاية للأيام ... لا لعب ولا لهو)\n(إذ كان يطرب في مسرته ... فيموت من أجزائه جزو)\nفقلت ما أحسنهما فقال أهكذا تقول والله لهما روحانيان يطيران بين السماء والأرض","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":20,"spl":"مدح الهادي فأجازه"},
{"id":"b33-36","bab":"الجزء 4","sec":"ابن مناذر يقول أبو العتاهية أشعر المحدثين","page":"ج4 ص61","text":"أخبرني محمد بن القاسم الأنباري قال حدثني أبي عن ابن عكرمة عن مسعود بن بشر المازني قال لقيت ابن مناذر بمكة فقلت له من أشعر أهل الإسلام فقال أترى من إذا شئت هزل وإذا شئت جد قلت من قال مثل جرير حين يقول في النسيب\n(إن الذين غدوا بلبك غادروا ... وشلا بعينك ما يزال معينا)\n(غيضن من عبراتهن وقلن لي ... ماذا لقيت من الهوى ولقينا)\nم قال حين جد\n(إن الذي حرم المكارم تغلبا ... جعل النبوة والخلافة فينا)\n(مضر أبي وأبو الملوك فهل لكم ... يا آل تغلب من أب كأبينا)\n(هذا ابن عمي في دمشق خليفة ... لو شئت ساقكم إلي قطينا)\nمن المحدثين هذا الخبيث الذي يتناول شعره من كمه فقلت من قال أبو العتاهية قلت في ماذا قال قوله\n(الله بيني وبين مولاتي ... أبدت لي الصد والملالات)\n(لا تغفر الذنب إن أسأت ولا ... تقبل عذري ولا مواتاتي)\n(منحتها مهجتي وخالصتي ... فكان هجرانها مكافاتي)\n(أقلقني حبها وصيرني ... أحدوثة في جميع جاراتي)\nم قال حين جد\n(ومهمه قد قطعت طامسه ... قفر على الهول والمحاماة)\n(بحرة جسرة عذافرة ... خوصاء عيرانة علنداة)\n(تبادر الشمس كلما طلعت ... بالسير تبغي بذاك مرضاتي)\n(يا ناق خبي بنا ولا تعدي ... نفسك مما ترين راحات)\n(حتى تناخي بنا إلى ملك ... توجه الله بالمهابات)\n(عليه تاجان فوق مفرقه ... تاج جلال وتاج إخبات)\n(يقول للريح كلما عصفت ... هل لك يا ريح في مباراتي)\n(من مثل من عمه الرسول ومن ... أخواله أكرم الخؤولات)\nخبرني وكيع قال قال الزبير بن بكار حدثني أبو غزية وكان قاضيا على المدينة قال كان إسحاق بن عزيز يتعشق عبادة جارية المهلبية وكانت المهلبية منقطعة إلى الخيزران فركب إسحاق يوما ومعه عبد الله بن مصعب يريدان\nالمهدي فلقيا عبادة فقال إسحاق يا أبا بكر هذه عبادة وحرك دابته حتى سبقها فنظر إليها فجعل عبد الله بن مصعب يتعجب من فعله ومضيا فدخلا على المهدي فحدثه عبد الله بن مصعب بحديث إسحاق وما فعل فقال أنا أشتريها لك يا إسحاق ودخل على الخيزران فدعا بالمهلبية فحضرت فأعطاها بعبادة خمسين ألف درهم فقالت له يا أمير المؤمنين إن كنت تريدها لنفسك فبها فداك الله وهي لك فقال إنما أريدها لإسحاق بن عزيز فبكت وقالت أتؤثر علي إسحاق بن عزيز وهي يدي ورجلي ولساني في جميع حوائجي فقالت لها الخيزران عند ذلك ما يبكيك والله لا وصل إليها ابن عزيز أبدا صار يتعشق جواري الناس فخرج المهدي فأخبر ابن عزيز بما جرى وقال له الخمسون ألف درهم لك مكانها وأمر له بها فأخذها عن عبادة فقال أبو العتاهية يعيره بذلك\n(من صدق الحب لأحبابه ... فإن حب ابن عزيز غرور)\n(أنساه عبادة ذات الهوى ... وأذهب الحب الذي في الضمير)\n(خمسون ألفا كلها راجح ... حسنا لها في كل كيس صرير)\nقال أبو العتاهية في ذلك أيضا\n(حبك للمال لا كحبك عبادة ... يا فاضح المحبينا)\n(لو كنت أصفيتها الوداد كما ... قلت لما بعتها بخمسينا)\nدثني الصولي قال حدثي جبلة بن محمد قال حدثني أبي قال رأيت أبا العتاهية بعدهما تخلص من حبس المهدي وهو يلزم طبيبا على بابنا ليكحل عينه فقيل له قد طال وجع عينك فأنشأ يقول\nصوت\n(أيا ويح نفسي ويحها ثم ويحها ... أما من خلاص من شباك الحبائل)\n(أيا ويح عيني قد أضر بها البكا ... فلم يغن عنها طب ما في المكاحل)\nي هذين البيتين لإبراهيم الموصلي لحن من الثقيل الأول","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":21,"spl":"ابن مناذر يقول أبو العتاهية أشعر المحدثين"},
{"id":"b33-37","bab":"الجزء 4","sec":"مدح الهادي فأجزل صلته","page":"ج4 ص64","text":"أخبرني عيسى بن الحسين قال حدثنا عمر بن شبة قال كان الهادي واجدا على أبي العتاهية لملازمته أخاه هارون في خلافة المهدي فلما ولي موسى الخلافة قال أبو العتاهية يمدحه صوت\n(يضطرب الخوف والرجاء إذا ... حرك موسى القضيب أو فكر)\n(ما أبين الفضل في مغيب ما ... أورد من رأيه وما أصدر)\nي هذين البيتين لأبي عيسى بن المتوكل لحن من الثقيل الأول في نهاية الجودة وما بان به فضله في الصناعة\n(فكم ترى عز عند ذلك من ... معشر قوم وذل من معشر)\n(يثمر من مسه القضيب ولو ... يمسه غيره لما أثمر)\n(من مثل موسى ومثل والده المهدي ... أو جده أبي جعفر)\nال فرضي عنه فلما دخل عليه أنشده\n(لهفي على الزمن القصير ... بين الخورنق والسدير)\n(إذ نحن في غرف الجنان ... نعوم في بحر السرور)\n(في فتية ملكوا عنان ... الدهر أمثال الصقور)\n(ما منهم إلا الجسور ... على الهوى غير الحصور)\n(يتعاورون مدامة ... صهباء من حلب العصير)\n(عذراء رباها شعاع ... الشمس في حر الهجير)\n(لم تدن من نار ولم ... يعلق بها وضر القدور)\n(ومقرطق يمشي أمام ... القوم كالرشأ الغرير)\n(بزجاجة تستخرج السر ... الدفين من الضمير)\n(زهراء مثل الكوكب الدري ... في كف المدير)\nدع الكريم وليس يدري ... ما قبيل من دبير ومخصرات زرننا ... بعد الهدو من الخدور ريا روادفهن يلبسن ... الخواتم في الخصور غر الوجوه محجبات ... قاصرات الطرف حور متنعمات في النعيم ... مضمخات بالعبير يرفلن في حلل المحاسن ... والمجاسد والحرير ما إن يرين الشمس ... إلا الفرط من خلل الستور\n(وإلى أمين الله مهربنا ... من الدهر العثور)\n(وإليه أتعبنا المطايا ... يا بالرواح وبالبكور)\n(صعر الخدود كأنما ... جنحن أجنحة النسور)\n(متسربلات بالظلام ... على السهولة والوعور)\n(حتى وصلن بنا إلى ... رب المدائن والقصور)\n(ما زال قبل فطامه ... في سن مكتهل كبير)\nال قيل له لو كان جزل اللفظ لكان أشعر الناس فأجزل صلته وعاد إلى أفضل ما كان له عليه أخبرني عمي الحسن بن محمد قال حدثني الكراني عن أبي حاتم قال قدم علينا أبو العتاهية في خلافة المأمون فصار إليه أصحابنا فاستنشدوه فكان أول ما أنشدهم\n(ألم تر ريب الدهر في كل ساعة ... له عارض فيه المنية تلمع)\n(أيا باني الدنيا لغيرك تبتني ... ويا جامع الدنيا لغيرك تجمع)\n(أرى المرء وثابا على كل فرصة ... وللمرء يوما لا محالة مصرع)\n(تبارك من لا يملك الملك غيره ... متى تنقضي حاجات من ليس يشبع)\n(وأي امرئ في غاية ليس نفسه ... إلى غاية أخرى سواها تطلع)\nال وكان أصحابنا يقولون لو أن طبع أبي العتاهية بجزالة لفظ لكان أشعر الناس أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني سليمان بن جعفر\nالجزري قال حدثني أحمد بن عبد الله قال كانت مرتبة أبي العتاهية مع الفضل بن الربيع في موضع واحد في دار المأمون فقال الفضل لأبي العتاهية يا أبا إسحاق ما أحسن بيتين لك وأصدقهما قال وما هما قال قولك\n(ما الناس إلا للكثير المال أو ... لمسلط ما دام في سلطانه)\n(فإذا الزمان رماهما ببلية ... كان الثقات هناك من أعوانه)\nعني من أعوان الزمان قال وإنما تمثل الفضل بن الربيع بهذين البيتين لانحطاط مرتبته في دار المأمون وتقدم غيره وكان المأمون أمر بذلك لتحريره مع أخيه","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":22,"spl":"مدح الهادي فأجزل صلته"},
{"id":"b33-38","bab":"الجزء 4","sec":"حبسه الرشيد بعد أن تنسك ثم أطلقه","page":"ج4 ص67","text":"أخبرني عمي الحسن بن محمد قال حدثنا عبد الله بن أبي سعد قال قال لي محمد بن أبي العتاهية كان أبي لا يفارق الرشيد في سفر ولا حضر إلا في طريق الحج وكان يجري عليه في كل سنة خمسين ألف درهم سوى الجوائز والمعاون فلما قدم الرشيد الرقة لبس أبي الصوف وتزهد وترك حضور المنادمة والقول في الغزل وأمر الرشيد بحبسه فحبس فكتب إليه من وقته صوت\n(أنا اليوم لي والحمد لله أشهر ... يروح علي الهم منكم ويبكر)\n(تذكر أمين الله حقي وحرمتي ... وما كنت توليني لعلك تذكر)\n(ليالي تدني منك بالقرب مجلسي ... ووجهك من ماء البشابة يقطر)\n(فمن لي بالعين التي كنت مرة ... إلي بها في سالف الدهر تنظر)\nال فلما قرأ الرشيد الأبيات قال قولوا له لا بأس عليك فكتب إليه صوت\n(أرقت وطار عن عيني النعاس ... ونام السامرون ولم يواسوا)\n(أمين الله أمنك خير أمن ... عليك من التقى فيه لباس)\n(تساس من السماء بكل بر ... وأنت به تسوس كما تساس)\n(كأن الخلق ركب فيه روح ... له جسد وأنت عليه راس)\n(أمين الله إن الحبس بأس ... وقد أرسلت ليس عليك باس)\nنى في هذه الأبيات إبراهيم ولحنه ثاني ثقيل بإطلاق الوتر في مجرى الوسطى وفيه أيضا ثقيل أول عن الهشامي قال وكتب إليه أيضا في الحبس\n(وكلفتني ما حلت بيني وبينه ... وقلت سأبقي ما تريد وما تهوى)\n(فلو كان لي قلبان كلفت واحدا ... هواك وكلفت الخلي لما يهوى)\nال فأمر بإطلاقه حدثني عمي قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني الزبير بن بكار قال حدثني ثابت بن الزبير بن حبيب قال حدثني ابن أخت أبي خالد الحربي قال قال لي الرشيد احبس أبا العتاهية وضيق عليه حتى يقول الشعر الرقيق في الغزل كما كان يقول فحبسته في بيت خمسة أشبار في مثلها فصاح الموت أخرجوني فأنا أقول كل ما شئتم فقلت قل فقال حتى أتنفس فأخرجته وأعطيته دواة وقرطاسا فقال أبياته التي أولها\nصوت\n(من لعبد أذله مولاه ... ما له شافع إليه سواه)\n(يشتكي ما به إليه ويخشاه ... ويرجوه مثل ما يخشاه)\nال فدفعتها إلى مسرور الخادم فأوصلها وتقدم الرشيد إلى إبراهيم الموصلي فغنى فيها وأمر بإحضار أبي العتاهية فأحضر فلما أحضر قال له أنشدني قولك صوت\n(يا عتب سيدتي أما لك دين ... حتى متى قلبي لديك رهين)\n(وأنا الذلول لكل ما حملتني ... وأنا الشقي البائس المسكين)\n(وأنا الغداة لكل باك مسعد ... ولكل صب صاحب وخدين)\n(لا بأس إن لذاك عندي راحة ... للصب أن يلقى الحزين حزين)\n(يا عتب أين أفر منك أميرتي ... وعلي حصن من هواك حصين)\nإبراهيم في هذه الأبيات هزج عن الهشامي فأمر له الرشيد بخمسين ألف درهم ولأبي العتاهية في الرشيد لما حبسه أشعار كثيرة منها قوله\n(يا رشيد الأمر أرشدني إلى ... وجه نجحي لا عدمت الرشدا)\n(لا أراك الله سوءا أبدا ... ما رأت مثلك عين أحدا)\n(أعن الخائف وارحم صوته ... رافعا نحوك يدعوك يدا)\n(وابلائي من دعاوى أمل ... كلما قلت تدانى بعدا)\n(كم أمني بغد بعد غد ... ينفذ العمر ولم ألق غدا)\nنسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال حدثني الحسين بن أبي السري قال مر القاسم بن الرشيد في موكب عظيم وكان من أتيه الناس وأبو العتاهية جالس مع قوم على ظهر الطريق فقام أبو العتاهية حين رآه إعظاما له فلم يزل قائما حتى جاز فأجازه ولم يلتفت إليه فقال أبو العتاهية\n(يتيه ابن آدم من جهله ... كأن رحا الموت لا تطحنه)\nسمع بعض من في موكبه ذلك فأخبر به القاسم فبعث إلى أبي العتاهية وضربه مائة مقرعة وقال له يابن الفاعلة أتعرض بي في مثل ذلك الموضع وحبسه في داره فدس أبو العتاهية إلى زبيدة بنت جعفر وكانت توجب له حقه هذه الأبيات\n(حتى متى ذو التيه في تيهه ... أصلحه الله وعافاه)\n(يتيه أهل التيه من جهلهم ... وهم يموتون وإن تاهوا)\n(من طلب العز ليبقى به ... فإن عز المرء تقواه)\n(لم يعتصم بالله من خلقه ... من ليس يرجوه ويخشاه)\nكتب إليها بحاله وضيق حبسه وكانت مائلة إليه فرثت له وأخبرت الرشيد بأمره وكلمته فيه فأحضره وكساه ووصله ولم يرض عن القاسم حتى بر أبا العتاهية وأدناه واعتذر إليه","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":23,"spl":"حبسه الرشيد بعد أن تنسك ثم أطلقه"},
{"id":"b33-39","bab":"الجزء 4","sec":"مدحه الرشيد والفضل بن الربيع","page":"ج4 ص70","text":"ونسخت من كتاب هارون بن علي قال حدثني علي بن مهدي قال حدثني\nمحمد بن سهل عن خالد بن أبي الأزهر قال بعث الرشيد بالحرشي إلى ناحية الموصل فجبى له منها مالا عظيما من بقايا الخراج فوافى به باب الرشيد فأمر بصرف المال أجمع إلى بعض جواريه فاستعظم الناس ذلك وتحدثوا به فرأيت أبا العتاهية وقد أخذه شبه الجنون فقلت له مالك ويحك فقال لي سبحان الله أيدفع هذا المال الجليل إلى امرأة ولا تتعلق كفي بشيء منه ثم دخل إلى الرشيد بعد أيام فأنشده\n(الله هون عندك الدنيا ... وبغضها إليكا)\n(فأبيت إلا أن تصغر ... كل شيء في يديكا)\n(ما هانت الدنيا على ... أحد كما هانت عليكا)\nقال له الفضل بن الربيع يا أمير المؤمنين ما مدحت الخلفاء بأصدق من هذا المدح فقال يا فضل أعطه عشرين ألف درهم فغدا أبو العتاهية على الفضل فأنشده\n(إذا ما كنت متخذا خليلا ... فمثل الفضل فاتخذ الخليلا)\n(يرى الشكر القليل له عظيما ... ويعطى من مواهبه الجزيلا)\n(أراني حيثما يممت طرفي ... وجدت على مكارمه دليلا)\nقال له الفضل والله لولا أن أساوي أمير المؤمنين لأعطيتك مثلها ولكن سأوصلها إليك في دفعات ثم أعطاه ما أمر له به الرشيد وزاد له خمسة آلاف درهم من عنده أخبرني علي بن سليمان الأخفش قال حدثنا المبرد قال حدثني عبد الصمد بن المعذل قال\nسمعت الأمير علي بن عيسى بن جعفر يقول كنت صبيا في دار الرشيد فرأيت شيخا ينشد والناس حوله\n(ليس للإنسان إلا ما رزق ... أستعين الله بالله أثق)\n(علق الهم بقلبي كله ... وإذا ما علق الهم علق)\n(بأبي من كان لي من قلبه ... مرة ود قليل فسرق)\n(يا بني الإسلام فيكم ملك ... جامع الإسلام عنه يفترق)\n(لندى هارون فيكم وله ... فيكم صوب هطول وورق)\n(لم يزل هارون خيرا كله ... قتل الشر به يوم خلق)\nقلت لبعض الهاشميين أما ترى إعجاب الناس بشعر هذا الرجل فقال يا بني إن الأعناق لتقطع دون هذا الطبع قال ثم كان الشيخ أبا العتاهية والذي سأله إبراهيم بن المهدي حدثني الصولي قال حدثنا أحمد بن محمد بن إسحاق قال حدثني عبد القوي بن محمد بن أبي العتاهية عن أبيه قال لبس أبو العتاهية كساء صوف ودراعة صوف وآلى على نفسه ألا يقول شعرا في الغزل وأمر الرشيد بحبسه والتضييق عليه فقال صوت\n(يابن عم النبي سمعا وطاعه ... قد خلعنا الكساء والدراعه)\n(ورجعنا إلى الصناعة لما ... كان سخط الإمام ترك الصناعه)\nقال أيضا\n(أما رحمتني يوم ولت فأسرعت ... وقد تركتني واقفا أتلفت)\n(أقلب طرفي كي أراها فلا أرى ... وأحلب عيني درها وأصوت)\nلم يزل الرشيد متوانيا في إخراجه إلى أن قال\n(أما والله إن الظلم لوم ... وما زال المسيء هو الظلوم)\n(إلى ديان يوم الدين نمضي ... وعند الله تجتمع الخصوم)\n(لأمر ما تصرفت الليالي ... وأمر ما توليت النجوم)\n(تموت غدا وأنت قرير عين ... من الغفلات في لجج تعوم)\n(تنام ولم تنم عنك المنايا ... تنبه للمنية يا نؤوم)\n(سل الأيام عن أمم تقضت ... ستخبرك المعالم والرسوم)\n(تروم الخلد في دار المنايا ... وكم قد رام غيرك ما تروم)\n(ألا يأيها الملك المرجى ... عليه نواهض الدنيا تحوم)\n(أقلني زلة لم أجر منها ... إلى لوم وما مثلي ملوم)\n(وخلصني تخلص يوم بعث ... إذا للناس برزت الجحيم)\nرق وأمر بإطلاقه نسخت من كتاب هارون بن علي قال حدثني علي بن مهدي قال حدثني ابن أبي الأبيض قال أتيت أبا العتاهية فقلت له إني رجل أقول الشعر في الزهد ولي فيه أشعار كثيرة وهو مذهب أستحسنه لأني أرجو ألا آثم فيه وسمعت شعرك في هذا المعنى فأحببت أن أستزيد منه فأحب أن تنشدني من جيد ما قلت فقال أعلم\nأن ما قلته رديء قلت وكيف قال لأن الشعر ينبغي أن يكون مثل أشعار الفحول المتقدمين أو مثل شعر بشار وابن هرمة فإن لم يكن كذلك فالصواب لقائله أن تكون ألفاظه مما لا تخفى على جمهور الناس مثل شعري ولا سيما الأشعار التي في الزهد فإن الزهد ليس من مذاهب الملوك ولا من مذاهب رواة الشعر ولا طلاب الغريب وهو مذهب أشغف الناس به الزهاد وأصحاب الحديث والفقهاء وأصحاب الرياء والعامة وأعجب الأشياء إليهم ما فهموه فقلت صدقت ثم أنشدني قصيدته\n(لدوا للموت وابنوا للخراب ... فكلكم يصير إلى تباب)\n(ألا يا موت لم أر منك بدا ... أتيت وما تحيف وما تحابي)\n(كأنك قد هجمت على مشيبي ... كما هجم المشيب على شبابي)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":24,"spl":"مدحه الرشيد والفضل بن الربيع"},
{"id":"b33-40","bab":"الجزء 4","sec":"مدحه الرشيد والفضل بن الربيع","page":"ج4 ص70","text":"ال فصرت إلى أبي نواس فأعلمته ما دار بيننا فقال والله ما أحسب في شعره مثل ما أنشدك بيتا آخر فصرت إليه فأخبرته بقول أبي نواس فأنشدني قصيدته التي يقول فيها\n(طول التعاشر بين الناس مملول ... ما لابن آدم إن فتشت معقول)\n(يا راعي الشاء لا تغفل رعايتها ... فأنت عن كل ما استرعيت مسؤول)\n(إني لفي منزل ما زلت أعمره ... على يقين بأني عنه منقول)\n(وليس من موضع يأتيه ذو نفس ... إلا وللموت سيف فيه مسلول)\n(لم يشغل الموت عنا مذ أعد لنا ... وكلنا عنه باللذات مشغول)\n(ومن يمت فهو مقطوع ومجتنب ... والحي ما عاش مغشي وموصول)\n(كل ما بدا لك فالآكال فانية ... وكل ذي أكل لا بد مأكول)\nال ثم أنشدني عدة قصائد ما هي بدون هذه فصرت إلى أبي نواس فأخبرته فتغير لونه وقال لم خبرته بما قلت قد والله أجاد ولم يقل فيه سوءا أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني علي بن عبد الله بن سعد قال حدثني هارون بن سعدان مولى البجليين قال كنت مع أبي نواس قريبا من دور بني نيبخت بنهر طابق وعنده جماعة فجعل يمر به القواد والكتاب وبنو هاشم فيسلمون عليه وهو متكئ ممدود الرجل لا يتحرك لأحد منهم حتى نظرنا إليه قد قبض رجليه ووثب وقام إلى شيخ قد أقبل على حمار له فاعتنق أبا نواس ووقف أبو نواس يحادثه فلم يزل واقفا معه يراوح بين رجليه يرفع رجلا ويضع أخرى ثم مضى الشيخ ورجع إلينا أبو نواس وهو يتأوه فقال له بعض من حضر والله لأنت أشعر منه فقال والله ما رأيته قط إلا ظننت أنه سماء وأنا أرض","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":25,"spl":"مدحه الرشيد والفضل بن الربيع — رأي بشار فيه"},
{"id":"b33-41","bab":"الجزء 4","sec":"رأي بشار فيه","page":"ج4 ص75","text":"قال محمد بن القاسم حدثني علي بن محمد بن عبد الله الكوفي قال حدثني السري بن الصباح مولى ثوبان بن علي قال كنت عند بشار فقلت له من أشعر أهل زماننا فقال مخنث أهل بغداد يعني أبا العتاهية أخبرني يحيى بن علي بن يحيى المنجم إجازة قال حدثني علي بن مهدي\nقال حدثني الخزرجي الشاعر قال حدثني عبد الله بن أيوب الأنصاري قال حدثني أبو العتاهية قال ماتت بنت المهدي فحزن عليها حزنا شديدا حتى امتنع من الطعام والشراب فقلت أبياتا أعزيه بها فوافيته وقد سلا وضحك وأكل وهو يقول لا بد من الصبر على ما لا بد منه ولئن سلونا عمن فقدنا ليسلون عنا من يفقدنا وما يأتي الليل والنهار على شيء إلا أبلياه فلما سمعت هذا منه قلت يا أمير المؤمنين أتأذن لي أن أنشدك قال هات فأنشدته\n(ما للجديدين لا يبلى اختلافهما ... وكل غض جديد فيهما بالي)\n(يا من سلا عن حبيب بعد ميتته ... كم بعد موتك أيضا عنك من سالي)\n(كأن كل نعيم أنت ذائقه ... من لذة العيش يحكي لمعة الآل)\n(لا تلعبن بك الدنيا وأنت ترى ... ما شئت من عبر فيها وأمثال)\n(ما حيلة الموت إلا كل صالحة ... أولا فما حيلة فيه لمحتال)\nفقال لي أحسنت ويحك وأصبت ما في نفسي ووعظت وأوجزت ثم أمر لي لكل بيت بألف درهم","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":25,"spl":"مدحه الرشيد والفضل بن الربيع — رأي بشار فيه"},
{"id":"b33-42","bab":"الجزء 4","sec":"هو يشعر وإبراهيم الموصلي يغني والرشيد يطلق سراحهما","page":"ج4 ص76","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني أحمد بن خلاد قال حدثني أبي قال\nلما مات موسى الهادي قال الرشيد لأبي العتاهية قل شعرا في الغزل فقال لا أقول شعرا بعد موسى أبدا فحبسه\nوأمر إبراهيم الموصلي أن يغني فقال لا أغني بعد موسى أبدا وكان محسنا إليهما فحبسه\nفلما شخص إلى\nالرقة حفر لهما حفيرة واسعة وقطع بينهما بحائط وقال كونا بهذا المكان لا تخرجا منه حتى تشعر أنت ويغني هذا فصبرا على ذلك برهة وكان الرشيد يشرب ذات يوم وجعفر بن يحيى معه فغنت جارية صوتا فاستحسناه وطربا عليه طربا شديدا وكان بيتا واحدا فقال الرشيد ما كان أحوجه إلى بيت ثان ليطول الغناء فيه فنستمتع مدة طويلة به فقال له جعفر قد أصبته قال من أين قال تبعث إلى أبي العتاهية فيلحقة به لقدرته على الشعر وسرعته قال هو أنكد من ذلك لا يجيبنا وهو محبوس ونحن في نعيم وطرب قال بلى فاكتب إليه حتى تعلم صحة ما قلت لك فكتب إليه بالقصة وقال ألحق لنا بالبيت بيتا ثانيا فكتب إليه أبو العتاهية\n(شغل المسكين عن تلك المحن ... فارق الروح وأخلى من بدن)\n(ولقد كلفت أمرا عجبا ... أسأل التفريح من بيت الحزن)\nلما وصلت قال الرشيد قد عرفتك أنه لا يفعل قال فتخرجه حتى يفعل قال لا حتى يشعر فقد حلفت فأقام أياما لا يفعل قال ثم قال أبو العتاهية لإبراهيم إلى كم هذا نلاج الخلفاء هلم أقل شعرا وتغن فيه فقال أبو العتاهية\n(بأبي من كان في قلبي له ... مرة حب قليل فسرق)\n(يا بني العباس فيكم ملك ... شعب الإحسان منه تفترق)\n(إنما هارون خير كله ... مات كل الشرمذ يوم خلق)\nغنى فيه إبراهيم فدعا بهما الرشيد فأنشده أبو العتاهية وغناه إبراهيم فأعطى كل واحد منهما مائة ألف درهم ومائة ثوب\nحدثني الصولي بهذا الحديث عن الحسين بن يحيى عن عبد الله بن العباس ابن الفضل بن الربيع فقال فيه غضب الرشيد على جارية له فحلف ألا يدخل إليها أياما ثم ندم فقال\n(صد عني إذ رآني مفتتن ... وأطال الصد لما أن فطن)\n(كان مملوكي فأضحى مالكي ... إن هذا من أعاجيب الزمن)\nوقال لجعفر بن يحيى أطلب لي من يزيد على هذين البيتين فقال له ليس غير أبي العتاهية فبعث إليه فأجاب بالجواب المذكور فأمر بإطلاقه وصلته فقال الآن طاب القول ثم قال\n(عزة الحب أرته ذلتي ... في هواه وله وجه حسن)\n(ولهذا صرت مملوكا له ... ولهذا شاع ما بي وعلن)\nقال أحسنت والله وأصبت ما في نفس وأضعف صلته نسخت من كتاب هارون بن علي بن يحيى قال حدثني علي بن مهدي قال حدثني الهيثم بن عثمان قال حدثني شبيب بن منصور قال كنت في الموقف واقفا على باب الرشيد فإذا رجل بشع الهيئة على بغل قد جاء فوقف وجعل الناس يسلمون عليه ويسائلونه ويضاحكونه ثم وقف في الموقف فأقبل الناس يشكون أحوالهم فواحد يقول كنت منقطعا إلى فلان فلم يصنع بي خيرا ويقول آخر أملت فلانا فخاب أملي وفعل بي ويشكو آخر من حاله فقال الرجل\n(فتشت ذي الدنيا فليس بها ... أحد أراه لآخر حامد)\n(حتى كأن الناس كلهم ... قد أفرغوا في قالب واحد)\nسألت عنه فقيل هو أبو العتاهية","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":26,"spl":"هو يشعر وإبراهيم الموصلي يغني والرشيد يطلق سراحهما"},
{"id":"b33-43","bab":"الجزء 4","sec":"اتهم سلما الخاسر بالبخل","page":"ج4 ص79","text":"حدثني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني أحمد بن خلاد عن أبيه عن عبد الله بن الحسن قال أنشد المأمون بيت أبي العتاهية يخاطب سلما الخاسر\n(تعالى الله يا سلم بن عمرو ... أذل الحرص أعناق الرجال)\nقال المأمون إن الحرص لمفسد للدين والمروءة والله ما عرفت من رجل قط حرصا ولا شرها فرأيت فيه مصطنعا فبلغ ذلك سلما فقال ويلي على المخنث الجرار الزنديق جمع الأموال وكنزها وعبأ البدور في بيته ثم تزهد مراءاة ونفاقا فأخذ يهتف بي إذا تصديت للطلب أخبرني أحمد بن العباس العسكري المؤدب ومحمد بن عمران الصيرفي قالا حدثنا الحسن بن عليل العنزي قال حدثني محمد بن أحمد بن سليمان العتكي قال حدثني العباس بن عبيد الله بن سنان بن عبد الملك بن مسمع قال كنا عند قثم بن جعفر بن سليمان وعنده أبو العتاهية ينشد في الزهد فقال قثم يا عباس أطلب الساعة الجماز حيث كان ولك عندي سبق فطلبته فوجدته عند ركن دار جعفر بن سليمان فقلت أجب الأمير فقام معي حتى أتى قثم فجلس في ناحية مجلسه وأبو العتاهية ينشده فأنشأ الجماز يقول\n(ما أقبح التزهيد من واعظ ... يزهد الناس ولا يزهد)\n(لو كان في تزهيده صادقا ... أضحى وأمسى بيته المسجد)\n(يخاف أن تنفد أرزاقه ... والرزق عند الله لا ينفد)\n(والرزق مقسوم على من ترى ... يناله الأبيض والأسود)\nال فالتفت أبو العتاهية إليه فقال من هذا قالوا هذا الجماز وهو ابن أخت سلم الخاسر اقتص لخاله منك فأقبل عليه وقال يابن أخي إني لم أذهب حيث ظننت ولا ظن خالك ولا أردت أن أهتف به وإما خاطبته كما يخاطب الرجل صديقه فالله يغفر لكما ثم قام","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":27,"spl":"اتهم سلما الخاسر بالبخل — مخارق يغني بشعره"},
{"id":"b33-44","bab":"الجزء 4","sec":"مخارق يغني بشعره","page":"ج4 ص80","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثني محمد بن أحمد بن خلف الشمري عن أبيه قال كنت عند مخارق فجاء أبو العتاهية في يوم جمعة فقال لي حاجة وأريد الصلاة فقال مخارق لا أبرح حتى تعود قال فرجع وطرح ثيابه وهي صوف وغسل وجهه ثم قال له غنني صوت\n(قال لي أحمد ولم يدر ما بي ... أتحب الغداة عتبة حقا)\n(فتنفست ثم قلت نعم حبا ... جرى في العروق عرقا فعرقا)\nجذب مخارق دواة كانت بين يديه فأوقع عليها ثم غناه فاستعاده ثلاث مرات فأعاده عليه ثم قام وهو يقول لا يسمع والله هذا الغناء أحد فيفلح وهذا الخبر رواية محمد بن القاسم بن مهرويه عنه وحدثنا به أيضا في كتاب هارون بن علي بن يحيى عن ابن مهرويه عن ابن عمار قال حدثني أحمد بن يعقوب عن محمد بن حسان الضبي قال حدثنا مخارق قال\nلقيني أبو العتاهية فقال بلغني أنك خرجت قولي\n(قال لي أحمد ولم يدر ما بي ... أتحب الغداة عتبة حقا)\nقلت نعم فقال غنه فملت معه إلى خراب فيه قوم فقراء سكان فغنيته إياه فقال أحسنت والله منذ ابتدأت حتى سكت ثم قال لي أما ترى ما فعل الملك بأهل هذا الخراب أخبرني جحظة قال حدثني ميمون بن هارون قال قال مخارق لقيت أبا العتاهية على الجسر فقلت له يا أبا إسحاق أتنشدني قولك في تبخيلك الناس كلهم فضحك وقال لي ها هنا قلت نعم فأنشدني\n(إن كنت متخذا خليلا ... فتنق وانتقد الخليلا)\n(من لم يكن لك منصفا ... في الود فابغ به بديلا)\n(ولربما سئل البخيل ... الشيء لا يسوى فتيلا)\n(فيقول لا أجد السبيل ... إليه يكره أن ينيلا)\n(فلذاك لا جعل الإله ... له إلى خير سبيلا)\n(فاضرب بطرفك حيث شئت ... فلن ترى إلا بخيلا)\nقلت له أفرطت يا أبا إسحاق فقال فديتك فأكذبني بجواد واحد فأحببت موافقته فالتفت يمينا وشمالا ثم قلت ما أجد فقبل بين عيني وقال فديتك يا بني لقد رفقت حتى كدت تسرف أخبرني محمد بن خلف وكيع قال حدثني هارون بن مخارق قال كان أبو العتاهية لما نسك يقول لي يا بني حدثني فإن ألفاظك تطرب كما يطرب غناؤك","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":27,"spl":"اتهم سلما الخاسر بالبخل — مخارق يغني بشعره"},
{"id":"b33-45","bab":"الجزء 4","sec":"عتابه لأحمد بن يوسف","page":"ج4 ص82","text":"أخبرني علي بن صالح بن الهيثم الأنباري قال حدثني أبو هفان قال حدثني موسى بن عبد الملك قال كان أحمد بن يوسف صديقا لأبي العتاهية فلما خدم المأمون وخص به رأى منه أبو العتاهية جفوة فكتب إليه\n(أبا جعفر إن الشريف يشينه ... تتايهه على الأخلاء بالوفر)\n(ألم تر أن الفقر يرجى له الغنى ... وأن الغنى يخشى عليه من الفقر)\n(فإن نلت تيها بالذي نلت من غنى ... فإن غناي في التجمل والصبر)\nال فبعث إليه بألفي درهم وكتب إليه يعتذر مما أنكره أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني إبراهيم بن أحمد بن إبراهيم الكوفي قال حدثني أبو جعفر المعبدي قال قلت لأبي العتاهية أجز لي قول الشاعر\n(وكان المال يأتينا فكنا ... نبذره وليس لنا عقول)\n(فلما أن تولى المال عنا ... عقلنا حين ليس لنا فضول)\nال فقال أبو العتاهية على المكان\n(فقصر ما ترى بالصبر حقا ... فكل إن صبرت له مزيل)\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني الحسن بن الفضل الزعفراني قال حدثني من سمع أبا العتاهية يقول لابنه وقد غضب عليه اذهب فإنك ثقيل الظل جامد الهواء","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":28,"spl":"عتابه لأحمد بن يوسف — خبر النعل الذي كتب على شراكها شعرا"},
{"id":"b33-46","bab":"الجزء 4","sec":"خبر النعل الذي كتب على شراكها شعرا","page":"ج4 ص82","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني يحيى بن خليفة الرازي قال حدثنا حبيب بن الجهم النميري قال حضرت الفضل بن الربيع متجزا جائزتي وفرضي فلم يدخل عليه أحد قبلي فإذا عون حاجبه قد جاء فقال هذا أبو العتاهية يسلم عليك وقد قدم من مكة فقال أعفني منه الساعة يشغلني عن ركوبي فخرج إليه عون فقال إنه على الركوب إلى أمير المؤمنين فأخرج من كمه نعلا عليها شراك فقال قل له إن أبا العتاهية أهداها إليك جعلت فداءك قال فدخل بها فقال ما هذه فقال نعل وعلى شراكها مكتوب كتاب فقال يا حبيب اقرأ ما عليها فقرأته فإذا هو\n(نعل بعثت بها ليلبسها ... قرم بها يمشي إلى المجد)\n(لو كان يصلح أن أشركها ... خدي جعلت شراكها خدي)\nقال لحاجبه عون احملها معنا فحملها فلما دخل على الأمين قال له يا عباسي ما هذه النعل فقال أهداها إلي أبو العتاهية وكتب عليها بيتين وكان أمير المؤمنين أولى بلبسها لما وصف به لابسها فقال وما هما فقرأهما فقال أجاد والله وما سبقه إلى هذا المعنى أحد هبوا له عشرة آلاف درهم فأخرجت والله في بدرة وهو راكب على حماره فقبضها وانصرف","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":28,"spl":"عتابه لأحمد بن يوسف — خبر النعل الذي كتب على شراكها شعرا"},
{"id":"b33-47","bab":"الجزء 4","sec":"سذاجته وقلة معرفته","page":"ج4 ص83","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا\nإسماعيل بن عبد الله الكوفي قال حدثنا عمرو صاحب الطعام وكان جار أبي العتاهية قال كان أبو العتاهية من أقل الناس معرفة سمعت بشرا المريسي يقول له يا أبا إسحاق لا تصل خلف فلان جارك وإما مسجدكم فإنه مشبه قال كلا إنه قرأ بنا البارحة في الصلاة ( قل هو الله أحد\nوإذا هو يظن أن المشبه لا يقرأ ( قل هو الله أحد\nخبرني الحسن قال حدثنا ابن مهرويه قال حدثني أحمد بن يعقوب الهاشمي قال حدثني أبو شيخ منصور بن سليمان عن أبيه قال كتب بكر بن المعتمر إلى أبي العتاهية يشكو إليه ضيق القيد وغم الحبس فكتب إليه أبو العتاهية\n(هي الأيام والعبر ... وأمر الله ينتظر)\n(أتيأس أن ترى فرجا ... فأين الله والقدر)\nخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا أحمد بن عبيد بن ناصح قال كنت أمشي مع أبي العتاهية يده في يدي وهو متكئ علي ينظر إلى الناس يذهبون ويجيئون فقال أما تراهم هذا يتيه فلا يتكلم وهذا يتكلم بصلف ثم قال لي مر بعض أولاد المهلب بمالك بن دينار وهو يخطر فقال يا بني لو خفضت بعض هذه الخيلاء ألم يكن أحسن بك من هذه الشهرة التي قد شهرت بها\nنفسك فقال له الفتى أو ما تعرف من أنا فقال له بلى والله أعرفك معرفة جيدة أولك نطفة مذرة وآخرك جيفة قذرة وأنت بين ذينك حامل عذرة قال فأرخى الفتى أذنيه وكف عما كان يفعل وطأطأ رأسه ومشى مسترسلا ثم أنشدني أبو العتاهية\n(أيا واها لذكر الله ... يا واها له واها)\n(لقد طيب ذكرو الله ... بالتسبيح أفواها)\n(فيا أنتن من حش ... على حش إذا تاها)\n(أرى قوما يتيهون ... حشوشا رزقوا جاها)\nدثني اليزيدي عن عمه إسماعيل بن محمد بن أبي محمد قال قلت لأبي العتاهية وقد جاءنا يا أبا إسحاق شعرك كله حسن عجيب ولقد مرت بي منذ أيام أبيات لك استحسنتها جدا وذلك أنها مقلوبة أيضا فأواخرها كأنها رأسها لو كتبها الإنسان إلى صديق له كتابا والله لقد كان حسنا أرفع ما يكون شعرا قال وما هي قلت\n(المرء في تأخير مدته ... كالثوب يخلق بعد جدته)\n(وحياته نفس يعد له ... ووفاته استكمال عدته)\n(ومصيره من بعد مدته ... لبلى وذا من بعد وحدته)\n(من مات مال ذوو مودته ... عنه وحالوا عن مودته)\n(أزف الرحيل ونحن في لعب ... ما نستعد له بعدته)\n(ولقلما تبقي الخطوب على ... أشر الشباب وحر وقدته)\n(عجبا لمنتبه يضيع ما ... يحتاج فيه ليوم رقدته)\nال اليزيدي قال عمي وحدثني الحسين بن الضحاك قال كنت مع أبي نواس فأنشدني أبياته التي يقول فيها\n(يا بني النقص والغير ... وبني الضعف والخور)\nلما فرغ منها قال لي يا أبا علي والله لكأنها من كلام صاحبك يعني أبا العتاهية أخبرني الحسن بن علي قال حدثني حذيفة بن محمد الطائي قال حدثني أبو دلف القاسم بن عيسى العجلي قال حججت فرأيت أبا العتاهية واقفا على أعرابي في ظل ميل وعليه شملة إذا غطى بها رأسه بدت رجلاه وإذا غطى رجليه بدا رأسه فقال له أبو العتاهية كيف اخترت هذا البلد القفر على البلدان المخصبة فقال له يا هذا لولا أن الله أقنع بعض العباد بشر البلاد ما وسع خير البلاد جميع العباد فقال له فمن أين معاشكم فقال منكم معشر الحاج تمرون بنا فننال من فضولكم وتنصرفون فيكون ذلك فقال له إنما نمر وننصرف في وقت من السنة فمن أين معاشكم فأطرق الأعرابي ثم قال لا والله لا أدري ما أقول إلا أنا نرزق من حيث لا نحتسب أكثر مما نرزق من حيث نحتسب فولى أبو العتاهية وهو يقول\n(ألا يا طالب الدنيا ... دع الدنيا لشانيكا)\n(وما تصنع بالدنيا ... وظل الميل يكفيكا)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":29,"spl":"سذاجته وقلة معرفته"},
{"id":"b33-48","bab":"الجزء 4","sec":"سلم الخاسر يشتمه بعد أن سمع هجوه","page":"ج4 ص86","text":"أخبرني محمد بن مزيد قال حدثنا الزبير بن بكار قال لما قال أبو العتاهية\n(تعالى الله يا سلم بن عمر ... أذل الحرص أعناق الرجال)\nال سلم ويلي على ابن الفاعلة كنز البدور ويزعم أني حريص وأنا في ثوبي هذين أخبرني محمد بن مزيد والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال حدثني عمرو بن أدعج قال قلت لعبد الله بن عبد العزيز العمري وسمعته يتمثل كثيرا من شعر أبي العتاهية أشهد أني سمعته ينشد لنفسه\n(مرت اليوم شاطره ... بضة الجسم ساخره)\n(إن دنيا هي التي ... مرت اليوم سافره)\n(سرقوا نصف اسمها ... فهي دنيا وآخره)\nقال عبد الله بن عبد العزيز وكله الله إلى آخرتها قال وما سمع بعد ذلك يتمثل ببيت من شعره قال علي بن الحسين مؤلف هذا الكتاب هذه الأبيات لأبي عيينة المهلبي وكان يشبب بدنيا في شعره فإما أن يكون الخبر غلطا وإما أن يكون الرجل أنشدها العمري لأبي العتاهية وهو لا يعلم أنها ليست له","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":30,"spl":"سلم الخاسر يشتمه بعد أن سمع هجوه"},
{"id":"b33-49","bab":"الجزء 4","sec":"الموازنة بينه وبين أبي نواس","page":"ج4 ص87","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل قال\nقال لي الحرمازي شهدت أبا العتاهية وأبا نواس في مجلس وكان أبو العتاهية أسرع الرجلين جوابا عند البديهة وكان أبو نواس أسرعهما في قول الشعر فإذا تعاطيا جميعا السرعة فضله أبو العتاهية وإذا توقفا وتمهلا فضله أبو نواس أخبرني أحمد بن العباس عن ابن عليل العنزي قال حدثنا أبو أنس كثير بن محمد الحزامي قال حدثني الزبير بن بكار عن معروف العاملي قال قال أبو العتاهية كنت منقطعا إلى صالح المسكين وهو ابن أبي جعفر المنصور فأصبت في ناحيته مائة ألف درهم وكان لي ودودا وصديقا فجئته يوما وكان لي في مجلسه مرتبة لا يجلس فيها غيري فنظرت إليه قد قصر بي عنها وعاودته ثانية فكانت حاله تلك ورأيت نظره إلي ثقيلا فنهضت وقلت\n(أراني صالح بغضا ... فأظهرت له بغضا)\n(ولا والله لا ينقض ... إلا زدته نقضا)\n(وإلا زدته مقتا ... وإلا زدته رفضا)\n(ألا يا مفسد الود ... وقد كان له محضا)\n(تغضبت من الريح ... فما أطلب أن ترضى)\n(لئن كان لك المال ... المصفى إن لي عرضا)\nال أبو العتاهية فنمي الكلام إلى صالح فنادى بالعداوة فقلت فيه\n(مددت لمعرض حبلا طويلا ... كأطول ما يكون من الحبال)\n(حبال بالصريمة ليس تفنى ... موصلة على عدد الرمال)\n(فلا تنظر إلي ولا تردني ... ولا تقرب حبالك من حبالي)\n(فليت الردم من يأجوج بيني ... وبينك مثبتا أخرى الليالي)\n(فكرش إن أردت لنا كلاما ... ونقطع قحف رأسه بالقذال)\nدثني أحمد بن عبيد الله بن عمار قال حدثنا علي بن سليمان النوفلي قال قال مساور السباق وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير عن مساور السباق قال شهدت جنازة في أيام الحاج وقت خروج الحسين بن علي بن الحسن بن الحسن بن الحسن المقتول بفخ فرأيت رجلا قد حضر الجنازة معنا وقد قال لآخر هذا الرجل الذي صفته كذا وكذا أبو العتاهية فالتفت إليه فقلت له أنت أبو العتاهية فقال لا أنا أبو إسحاق فقلت له أنشدني شيئا من شعرك فقال لي ما أحمقك نحن على سفر وعلى شفير قبر وفي أيام العشر وببلدكم هذا تستنشدني الشعر ثم أدبر عني ثم عاد إلي فقال وأخرى أزيدكها لا والله ما رأيت في بني آدم قط أسمج منك وجها قال النوفلي في خبره وصدق أبو العتاهية كان مساور هذا مقبحا طويل الوجه كأنه ينظر في سيف أخبرني عمي الحسن بن محمد وجحظة قالا حدثنا ميمون بن هارون قال قدم أبو العتاهية يوما منزل يحيى بن خاقان فلما قام بادر له الحاجب\nفانصرف وأتاه يوما آخر فصادفه حين نزل فسلم عليه ودخل إلى منزله ولم يأذن له فأخذ قرطاسا وكتب إليه\n(أراك تراع حين ترى خيالي ... فما هذا يروعك من خيالي)\n(لعلك خائف مني سؤالي ... ألا فلك الأمان من السؤال)\n(كفيتك إن حالك لم تمل بي ... لأطلب مثلها بدلا بحالي)\n(وإن اليسر مثل العسر عندي ... بأيهما منيت فلا أبالي)\nلما قرأ الرقعة أمر الحاجب بإدخاله إليه فطلبه فأبى أن يرجع معه ولم يلتقيا بعد ذلك أخبرني عبد الله بن محمد الرازي قال حدثنا أحمد بن الحارث قال حدثنا المدائني قال اجتمع أبو نواس وأبو الشمقمق في بيت ابن أذين وكان بين أبي العتاهية وبين أبي الشمقمق شر فخبأوه من أبي العتاهية في بيت ودخل أبو العتاهية فنظر إلى غلام عندهم فيه تأنيث فظن أنه جارية فقال لابن أذين متى استطرفت هذه الجارية فقال قريبا يا أبا إسحاق فقال قل فيها ما حضر فمد أبو العتاهية يده إليه وقال\n(مددت كفي نحوكم سائلا ... ماذا تردون على السائل)\nلم يلبث أبو الشمقمق حتى ناداه من البيت\n(نرد في كفك ذا فيشة ... يشفي جوى في استك من داخل)\nقال أبو العتاهية شمقمق والله وقام مغضبا\nأخبرني أحمد بن عبيد الله بن عمار قال حدثنا علي بن محمد النوفلي قال حدثني سليمان بن عباد قال حدثنا سليمان بن مناذر قال كنا عند جعفر بن يحيى وأبو العتاهية حاضر في وسط المجلس فقال أبو العتاهية لجعفر جعلني الله فداك معكم شاعر يعرف بابن أبي أمية أحب أن اسمعه ينشد فقال له جعفر هو أقرب الناس منك فأقبل أبو العتاهية على محمد وكان إلى جانبه وسأله أن ينشده فكأنه حصر ثم أنشده صوت\n(رب وعد منك لا أنساه لي ... أوجب الشكر وإن لم تفعل)\n(أقطع الدهر بوعد حسن ... وأجلي غمرة ما تنجلي)\n(كلما أملت وعدا صالحا ... عرض المكروه دون الأمل)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":31,"spl":"الموازنة بينه وبين أبي نواس"},
{"id":"b33-50","bab":"الجزء 4","sec":"الموازنة بينه وبين أبي نواس","page":"ج4 ص87","text":"(وأرى الأيام لا تدني الذي ... أرتجي منك وتدني أجلي)\nفي هذه الأبيات لأبي حبشة رمل قال فأقبل أبو العتاهية يردد البيت الأخير ويقبل رأس ابن أبي أمية ويبكي وقال وددت والله أنه لي بكثير من شعري","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":32,"spl":"الموازنة بينه وبين أبي نواس — أسماء أبنائه"},
{"id":"b33-51","bab":"الجزء 4","sec":"أسماء أبنائه","page":"ج4 ص91","text":"أخبرني حبيب بن نصر قال حدثنا عمر بن شبة قال كانت لأبي العتاهية بنتان اسم إحداهما لله والأخرى بالله فخطب منصور بن المهدي لله فلم يزوجه وقال إنما طلبها لأنها بنت أبي العتاهية وكأني بها قد ملها فلم يكن لي إلى الانتصاف منه سبيل وما كنت لأزوجها إلا بائع خزف وجرار ولكني أختاره لها موسرا\nوكان لأبي العتاهية ابن يقال له محمد وكان شاعرا وهو القائل\n(قد أفلح السالم الصموت ... كلام راعي الكلام قوت)\n(ما كل نطق له جواب ... جواب ما يكره السكوت)\n(يا عجبا لامرىء ظلوم ... مستيقن أنه يموت)\nسخت من كتاب هارون بن علي بن يحيى حدثنا زكريا بن الحسين عن عبد الله بن الحسن بن سهل الكاتب قال قلت لأبي العتاهية أنشدني من شعرك ما تستحسن فأنشدني\n(ما أسرع الأيام في الشهر ... وأسرع الأشهر في العمر)\nصوت\n(ليس لمن ليست له حيلة ... موجودة خير من الصبر)\n(فاخط مع الدهر إذا ما خطا ... واجر مع الدهر كما يجري)\n(من سابق الدهر كبا كبوة ... لم يستقلها آخر الدهر)\nإبراهيم في هذه الأبيات خفيف ثقيل وثقيل أول قال عبد الله بن الحسن وسمعت أبا العتاهية يحدث قال ما زال الفضل ابن الربيع من أميل الناس إلي فلما رجع من خراسان بعد موت الرشيد دخلت إليه فاستنشدني فأنشدته\n(أفنيت عمرك إدبارا وإقبالا ... تبغي البنين وتبغي الأهل والمالا)\n(الموت هول فكن ما شئت ملتمسا ... من هوله حيلة إن كنت محتالا)\n(ألم تر الملك الأمسي حين مضى ... هل نال حي من الدنيا كما نالا)\n(أفناه من لم يزل يفني القرون فقد ... أضحى وأصبح عنه الملك قد زالا)\n(كم من ملوك مضى ريب الزمان بهم ... فأصبحوا عيرا فينا وأمثالا)\nاستحسنها وقال أنت تعرف شغلي فعد إلي في وقت فراغي اقعد معك وآنس بك فلم أزل أراقب أيامه حتى كان يوم فراغه فصرت إليه فبينما هو مقبل علي يستنشدني ويسألني فأحدثه إذ أنشدته\n(ولى الشباب فماله من حيلة ... وكسا ذؤابتي المشيب خمارا)\n(أين البرامكة الذين عهدتهم ... بالأمس أعظم أهلها أخطارا)\nلما سمع ذكرى البرامكة تغير لونه ورأيت الكراهية في وجهه فما رأيت منه خيرا بعد ذلك قال وكان أبو العتاهية يحدث هذا الحديث ابن الحسن بن سهل فقال له لئن كان ذلك ضرك عند الفضل بن الربيع لقد نفعك عندنا فأمر له بعشرة آلاف درهم وعشرة أثواب وأجرى له كل شهر ثلاثة آلاف درهم فلم يزل يقبلها دارة إلي أن مات قال عبد الله بن الحسن بن سهل وسمعت عمرو بن مسعدة يقول قال لي أخي مجاشع بينما أنا في بيتي إذ جاءتني رقعة من أبي العتاهية فيها\n(خليل لي أكاتمه ... أراني لا ألائمه)\n(خليل لا تهب الريح ... إلا هب لائمه)\n(كذا من نال سلطانا ... ومن كثرت دراهمه)\nال فبعثت إليه فأتاني فقلت له أما رعيت حقا ولا ذماما ولا مودة فقال لي ما قلت سوءا قلت فما حملك على هذا قال أغيب عنك عشرة أيام فلا تسأل\nعني ولا تبعث إلي رسولا فقلت يا أبا إسحاق أنسيت قولك\n(يأبى المعلق بالمنى ... إلا رواحا وادلاجا)\n(أرفق فعمرك عود ذي ... أود رأيت به اعوجاجا)\n(من عاج من شيء إلى ... شيء أصاب له معاجا)\nفقال حسبك حسبك أوسعتني عذرا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":32,"spl":"الموازنة بينه وبين أبي نواس — أسماء أبنائه"},
{"id":"b33-52","bab":"الجزء 4","sec":"عاب شعر ابن مناذر","page":"ج4 ص94","text":"أخبرني محمد بن عمران الصيرفي الزارع قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عمران بن عبد الصمد الزارع قال حدثنا ابن عائشة قال قال أبو العتاهية لابن مناذر شعرك مهجن لا يلحق بالفحول وأنت خارج عن طبقة المحدثين فإن كنت تشبهت بالعجاج ورؤبة فما لحقتهما ولا أنت في طريقهما وإن كنت تذهب مذهب المحدثين فما صنعت شيئا أخبرني عن قولك\n(ومن عاداك لاقى المرمريسا ... )\nأخبرني عن المرمريس ما هو قال فخجل ابن مناذر وما راجعه حرفا قال وكان بينهما تناغر نسخت من كتاب هارون بن علي بن يحيى قال حدثني الحسين بن إسماعيل المهدي قال حدثني رجاء بن سلمة قال وجد المأمون علي في شيء فاستأذنته في الحج فأذن لي فقدمت البصرة وعبيد الله بن إسحاق بن الفضل الهاشمي عليها وإليه أمر الحج فزاملته إلى مكة فبينا نحن في الطواف رأيت أبا العتاهية فقلت لعبيد الله جعلت فداك أتحب أن ترى أبا العتاهية فقال والله إني لأحب أن أراه وأعاشره قلت فافرغ من طوافك واخرج ففعل فأخذت بيد أبي العتاهية فقلت له يا أبا إسحاق هل لك في رجل من أهل البصرة شاعر أديب ظريف قال وكيف لي بذلك فأخذت بيده فجئت به إلى عبيد الله وكان لا يعرفه فتحدثا ساعة ثم قال له أبو العتاهية هل لك في بيتين تجيزهما فقال له عبيد الله إنه لا رفث ولا فسوق ولا جدال في الحج فقال له لا نرفث ولا نفسق ولا نجادل فقال هات إذا فقال أبو العتاهية\n(إن المنون غدوها ورواحها ... في الناس دائبة تجيل قداحها)\n(يا ساكن الدنيا لقد أوطنتها ... ولتنزحن وإن كرهت نزاحها)\nأطرق عبيد الله ينظر إلى الأرض ساعة ثم رفع رأسه فقال\n(خذ لا أبالك للمنية عدة ... واحتل لنفسك إن أردت صلاحها)\n(لا تغترر فكأنني بعقاب ريب ... الموت قد نشرت عليك جناحها)\nال ثم سمعت الناس ينحلون أبا العتاهية هذه الأربعة الأبيات كلها وليس له إلا البيتان الأولان","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":33,"spl":"عاب شعر ابن مناذر","partial":1},
{"id":"b33-53","bab":"الجزء 4","sec":"خبره في السجن مع داعية عيسى بن زيد","page":"ج4 ص96","text":"أخبرني عمي الحسن بن محمد قال حدثنا ميمون بن هارون قال حدثني إبراهيم بن رباح قال أخبرني إبراهيم بن عبد الله وأخبرني محمد بن خلف وكيع قال حدثنا هارون بن مخارق قال حدثني إبراهيم بن دسكرة وأخبرني أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ قال قال أبو العتاهية حبسني الرشيد لما تركت قول الشعر فأدخلت السجن وأغلق الباب علي فدهشت كما يدهش مثلي لتلك الحال وإذا أنا برجل جالس في جانب الحبس مقيد فجعلت أنظر إليه ساعة ثم تمثل صوت\n(تعودت مر الصبر حتى ألفته ... وأسلمني حسن العزاء إلى الصبر)\n(وصيرني يأسى من الناس راجيا ... لحسن صنيع الله من حيث لا أدري)\nقلت له أعد يرحمك الله هذين البيتين فقال لي ويلك أبا العتاهية ما أسوأ\nأدبك وأقل عقلك دخلت علي الحبس فما سلمت تسليم المسلم على المسلم ولا سألت مسألة الحر للحر ولا توجعت توجع المبتلى للمبتلى حتى إذا سمعت بيتين من الشعر الذي لا فضل فيك غيره لم تصبر عن استعادتهما ولم تقدم قبل مسألتك عنهما عذرا لنفسك في طلبهما فقلت يا أخي إني دهشت لهذه الحال فلا تعذلني واعذرني متفضلا بذلك فقال أنا والله أولى بالدهش والحيرة منك لأنك حبست في أن تقول شعرا به ارتفعت وبلغت فإذا قلت أمنت وأنا مأخوذ بأن أدل على ابن رسول الله ليقتل أو أقتل دونه ووالله لا أدل عليه أبدا والساعة يدعى بي فأقتل فأينا أحق بالدهش فقلت له أنا والله أولى سلمك الله وكفاك ولو علمت أن هذه حالك ما سألتك قال فلا نبخل عليك إذا ثم أعاد البيتين حتى حفظتهما قال فسألته من هو فقال أنا خاص داعية عيسى بن زيد وابنه أحمد ولم نلبث أن سمعنا صوت الأقفال فقام فسكب عليه ماء كان عنده في جرة ولبس ثوبا نظيفا كان عنده ودخل الحرس والجند معهم الشمع فأخرجونا جميعا وقدم قبلي إلى الرشيد فسأله عن أحمد بن عيسى فقال لا تسألني عنه واصنع ما أنت صانع فلو أنه تحت ثوبي هذا ما كشفته عنه وأمر بضرب عنقه فضرب ثم قال لي أظنك قد ارتعت يا إسماعيل فقلت دون ما رأيته تسيل منه النفوس فقال ردوه إلى محبسه فرددت وانتحلت هذين البيتين وزدت فيهما\n(إذا أنا لم أقبل من الدهر كل ما ... تكرهت منه طال عتبي على الدهر)\nزرزور غلام المارقي في هذه البيتين المذكورين خفيف رمل وفيهما لعريب خفيف ثقيل\nنسخت من كتاب هارون بن علي بن يحيى حدثني علي بن مهدي قال حدثني ناجية بن عبد الواحد قال قال لي أبو العباس الخزيمي كان أبو العتاهية خلفا في الشعر بينما هو يقول في موسى الهادي\n(لهفي على الزمن القصير ... بين الخورنق والسدير)\nذ قال\n(أيا ذوي الوخامه ... أكثرتم الملامة)\n(فليس لي على ذا ... صبر ولا قلامه)\n(نعم عشقت موقا ... هل قامت القيامة)\n(لأركبن فيمن ... هويته الصرامه)\nنسخت من كتابه حدثني علي بن مهدي قال حدثني أحمد بن عيسى قال حدثني الجماز قال قال سلم الخاسر صار إلي أبو العتاهية فقال جئتك زائرا فقلت مقبول منك ومشكور أنت عليه فأقم فقال إن هذا مما يشتد علي قلت ولم يشتد عليك ما يسهل على أهل الأدب فقال لمعرفتي بضيق صدرك فقلت له وأنا أضحك وأعجب من مكابرته رمتني بدائها وانسلت فقال دعني من هذا واسمع مني أبياتا فقلت هات فأنشدني\n(نغص الموت كل لذة عيش ... يا لقومي للموت ما أوحاه)\n(عجبا أنه إذا مات ميت ... صد عنه حبيبه وجفاه)\n(حيثما وجه امرؤ ليفوت الموت ... فالموت واقف بحذاه)\n(إنما الشيب لابن أدم ناع ... قام في عارضيه ثم نعاه)\n(من تمنى المنى فأغرق فيها ... مات من قبل أن ينال مناه)\n(ما أذل المقل في أعين الناس ... لإقلاله وما أقماه)\n(إنما تنظر العيون من الناس ... إلى من ترجوه أو تخشاه)\nم قال لي كيف رأيتها فقلت له لقد جودتها لو لم تكن ألفاظها سوقية فقال والله ما يرغبني فيها إلا الذي زهدك فيها","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":34,"spl":"خبره في السجن مع داعية عيسى بن زيد"},
{"id":"b33-54","bab":"الجزء 4","sec":"شعره في التكبر","page":"ج4 ص99","text":"ونسخت من كتابة عن علي بن مهدي قال حدثني عبد الله بن عطية عن محمد بن عيسى الحربي قال كنت جالسا مع أبي العتاهية إذ مر بنا حميد الطوسي في موكبه وبين يديه الفرسان والرجالة وكان بقرب أبي العتاهية سوادي على أتان فضربوا وجه الأتان ونحوه عن الطريق وحميد واضع طرفه على معرفة فرسه والناس ينظرون إليه يعجبون منه وهو لا يلتفت تيها فقال أبو العتاهية\n(للموت أبناء بهم ... ما شئت من صلف وتيه)\n(وكأنني بالموت قد ... دارت رحاه على بنيه)\nال فلما جاز حميد مع صاحب الأتان قال أبو العتاهية\n(ما أذل المقل في أعين الناس ... لإقلاله وما أقماه)\n(إنما تنظر العيون من الناس ... إلى من ترجوه أو تخشاه)\nال علي بن مهدي وحدثني الحسين بن أبي السري قال قيل لأبي العتاهية مالك تبخل بما رزقك الله قال والله ما بخلت بما رزقني الله قط قيل له وكيف ذاك وفي بيتك من المال ما لا يحصى قال ليس ذلك رزقي ولو كان رزقي لأنفقته قال علي بن مهدي وحدثني محمد بن جعفر الشهرزوري قال حدثني رجاء مولى صالح الشهرزوري قال كان أبو العتاهية صديقا لصالح الشهرزوري وآنس الناس به فسأله أن يكلم الفضل بن يحيى في حاجة له فقال له صالح لست أكلمه في أشباه هذا ولكن حملني ما شئت في مالي فانصرف عنه أبو العتاهية وأقام أياما لا يأتيه فكتب إليه أبو العتاهية\n(أقلل زيارتك الصديق ولا تطل ... إتيانه فتلج في هجرانه)\n(إن الصديق يلج في غشيانه ... لصديقه فيمل من غشيانه)\n(حتى تراه بعد طول مسرة ... بمكانه متبرما بمكانه)\n(وأقل ما يلفى الفتى ثقلا على ... إخوانه ما كف عن إخوانه)\n(وإذا توانى عن صيانة نفسه ... رجل تنقص واستخف بشانه)\nفلما قرأ الأبيات قال سبحان الله أتهجرني لمنعي إياك شيئا تعلم إني ما ابتذلت نفسي له قط وتنسى مودتي وأخوتي ومن دون ما بيني وبينك ما أوجب عليك أن تعذرني فكتب إليه\n(أهل التخلق لو يدوم تخلق ... لسكنت ظل جناح من يتخلق)\n(ما الناس في الإمساك إلا واحد ... فبأيهم إن حصلوا أتعلق)\n(هذا زمان قد تعود أهله ... تيه الملوك وفعل من يتصدق)\nلما أصبح صالح غدا بالأبيات على الفضل بن يحيى وحدثه بالحديث فقال له لا والله ما على الأرض أبغض إلي من إسداء عارفة إلى أبي العتاهية لأنه ممن ليس يظهر عليه أثر صنيعة وقد قضيت حاجته لك فرجع وأرسلني بقضاء حاجته فقال أبو العتاهية\n(جزى الله عني صالحا بوفائه ... وأضعف أضعافا له في جزائه)\n(بلوت رجالا بعده في إخائهم ... فما ازددت إلا رغبة في إخائه)\n(صديق إذا ما جئت أبغيه حاجة ... رجعت بما أبغي ووجهي بمائه)\nخبرني الصولي قال حدثني محمد بن موسى قال حدثني أحمد بن حرب قال أنشدني محمد بن أبي العتاهية لأبيه يعاتب صالحا هذا في تأخيره قضاء حاجته صوت\n(أعيني جودا وابكيا ود صالح ... وهيجا عليه معولات النوائح)\n(فما زال سلطانا أخ لي أوده ... فيقطعني جرما قطيعة صالح)\nلغناء في هذين البيتين لإبراهيم ثقيل أول بإطلاق الوتر في مجرى البنصر\nأخبرني محمد بن أبي الأزهر قال حدثني حماد بن إسحاق عن أبيه عن جده قال كان الرشيد معجبا بشعر أبي العتاهية فخرج إلينا يوما وفي يده رقعتان على نسخة واحدة فبعث بإحداهما إلى مؤدب لولده وقال ليروهم ما فيها ودفع الأخرى إلي وقال غن في هذه الأبيات ففتحتها فإذا فيها صوت\n(قل لمن ضن بوده ... وكوى القلب بصده)\n(ما ابتلى الله فؤادي ... بك إلا شؤم جده)\n(أيها السارق عقلي ... لا تضنن برده)\n(ما أرى حبك إلا ... بالغا بي فوق حده)\nأخبرني هاشم بن محمد الخزاعي قال حدثني عبد الله بن الأموي العتبي قال قال لي محمد بن عبد الملك الزيات لما أحس المعتصم بالموت قال لابنه الواثق ذهب والله أبوك يا هارون لله در أبي العتاهية حيث يقول\n(الموت بين الخلق مشترك ... لا سوقة يبقى ولا ملك)\n(ما ضر أصحاب القليل وما ... أغنى عن الأملاك ما ملكوا)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":35,"spl":"شعره في التكبر"},
{"id":"b33-55","bab":"الجزء 4","sec":"أبو تمام يقول لأبي العتاهية خمسة أبيات ما شركه فيها أحد","page":"ج4 ص103","text":"أخبرني حبيب بن نصر المهلبي وعمي الحسن والكوكبي قالوا حدثنا عبد الله بن أبي سعد قال قال لي أبو تماح الطائي لأبي العتاهية خمسة أبيات ما شركه فيها أحد ولا قدر على مثلها متقدم ولا متأخر وهو قوله\n(الناس في غفلاتهم ... ورحى المنية تطحن)\nقوله لأحمد بن يوسف\n(ألم تر أن الفقر يرجى لي الغنى ... وأن الغنى يخشى عليه من الفقر)\nقوله في موسى الهادي\n(ولما استقلوا بأثقالهم ... وقد أزمعوا للذي أزمعوا)\n(قرنت التفاتي بآثارهم ... وأتبعتهم مقلة تدمع)\nقوله\n(هب الدنيا تصير إليك عفوا ... أليس مصير ذاك إلى زوال)\nأخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني محمد بن سعيد المهدي عن يحيى بن سعيد الأنصاري قال\nمات شيخ لنا ببغداد فلما دفناه أقبل الناس على أخيه يعزونه فجاء أبو العتاهية إليه وبه جزع شديد فعزاه ثم أنشد\n(لا تأمن الدهر والبس ... لكل حين لباسا)\n(ليدفننا أناس ... كما دفنا أناسا)\nال فانصرف الناس وما حفظوا غير قول أبي العتاهية نسخت من كتاب هارون بن علي حدثني علي بن مهدي قال حدثني حبيب ابن عبد الرحمن عن بعض أصحابه قال كنت في مجلس خزيمة فجرى حديث ما يسفك من الدماء فقال والله ما لنا عند الله عذر ولا حجة إلا رجاء عفوه ومغفرته ولولا عز السلطان وكراهة الذلة وأن أصير بعد الرياسة سوقة وتابعا بعد ما كنت متبوعا ما كان في الأرض أزهد ولا أعبد مني فإذا هو بالحاجب قد دخل عليه برقعة من أبي العتاهية فيها مكتوب\n(أراك امرأ ترجو من الله عفوه ... وأنت على مالا يحب مقيم)\n(تدل على التقوى وأنت مقصر ... أيا من يداوي الناس وهو سقيم)\n(وإن امرأ لم يلهه اليوم عن غد ... تخوف ما يأتي به لحكيم)\n(وإن امرأ لم يجعل البر كنزه ... وإن كانت الدنيا له لعديم)\nغضب خزيمة وقال والله ما المعروف عند هذا المعتوه الملحف من كنوز البر فيرغب فيه حر فقيل له وكيف ذاك فقال لأنه من الذين يكنزون الذهب\nوالفضة ولا ينفقونها في سبيل الله ونسخت من كتابه عن علي بن مهدي قال حدثني الحسين بن أبي السري قال قال لي الفضل بن العباس قال لي أبو العتاهية دخلت على يزيد بن مزيد فأنشدته قصيدتي التي أقول فيها\n(وما ذاك إلا أنني واثق بما ... لديك وأني عالم بوفائكا)\n(كأنك في صدري إذا جئت زائرا ... تقدر فيه حاجتي بابتدائكا)\n(وإن أمير المؤمنين وغيره ... ليعلم في الهيجاء فضل غنائكا)\n(كأنك عند الكرفي الحرب إنما ... تفر من السلم الذي من ورائكا)\n(فما آفة الأملاك غيرك في الوغى ... ولا آفة الأموال غير حبائكا)\nقال فأعطاني عشرة آلاف درهم ودابة بسرجها ولجامها وأخبرني عيسى بن الحسين الوراق وعمي الحسن بن محمد وحبيب بن نصر المهلبي قالوا حدثنا عمر بن شبة قال مر عابد براهب في صومعة فقال له عظني فقال أعظك وعليكم نزل القرآن ونبيكم محمد قريب العهد بكم قلت نعم قال فاتعظ ببيت من شعر شاعركم أبي العتاهية حين يقول\n(تجرد من الدنيا فإنك إنما ... وقعت إلى الدنيا وأنت مجرد)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":36,"spl":"أبو تمام يقول لأبي العتاهية خمسة أبيات ما شركه فيها أحد — العتابي يفضله على أبي نواس"},
{"id":"b33-56","bab":"الجزء 4","sec":"العتابي يفضله على أبي نواس","page":"ج4 ص105","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني الفضل بن محمد الزارع قال حدثني جعفر بن جميل قال\nقدم العتابي الشاعر على المأمون فأنزله على إسحاق بن إبراهيم فأنزله على كاتبه ثوابة بن يونس وكنا نختلف إليه نكتب عنه فجرى ذات يوم ذكر الشعراء فقال لكم يأهل العراق شاعر منوه الكنية ما فعل فذكر القوم أبا نواس فانتهرهم ونفض يده وقال ليس ذلك حتى طال الكلام فقلت لعلك تريد أبا العتاهية فقال نعم ذاك أشعر الأولين والآخرين في وقته أخبرني محمد بن عمران قال حدثني العنزي قال حدثني محمد بن إسحاق عن علي بن عبد الله الكندي قال جلس أبو العتاهية يوما يعذل أبا نواس ويلومه في استماع الغناء ومجالسته لأصحابه فقال له أبو نواس\n(أتراني يا عتاهي ... تاركا تلك الملاهي)\n(أتراني مفسدا بالنسك ... عند القوم جاهي)\nال فوثب أبو العتاهية وقال لا بارك الله عليك وجعل أبو نواس يضحك","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":36,"spl":"أبو تمام يقول لأبي العتاهية خمسة أبيات ما شركه فيها أحد — العتابي يفضله على أبي نواس"},
{"id":"b33-57","bab":"الجزء 4","sec":"إبراهيم بن المهدي يتهمه بالزندقة","page":"ج4 ص106","text":"أخبرني جحظة قال حدثني هبة الله بن إبراهيم بن المهدي قال بلغ أبا العتاهية أن أبي رماه في مجلسه بالزندقة وذكره بها فبعث إليه يعاتبه على لسان إسحاق الموصلي فأدى إليه إسحاق الرسالة فكتب إليه أبي\n(إن المنية أمهلتك عتاهي ... والموت لا يسهو وقلبك ساهي)\n(يا ويح ذي السن الضعيف أماله ... عن غيه قبل الممات تناهي)\n(وكلت بالدنيا تبكيها وتندبها ... وأنت عن القيامة لاهي)\n(والعيش حلو والمنون مريرة ... والدار دار تفاخر وتباهي)\n(فاختر لنفسك دونها سبلا ولا ... تتحامقن لها فإنك لاهي)\n(لا يعجبنك أن يقال مفوه ... حسن البلاغة أو غريض الجاه)\n(أصلح جهولا من سريرتك التي ... تخلو بها وارهب مقام الله)\n(إني رأيتك مظهرا لزهادة ... تحتاج منك لها إلى أشباه)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":37,"spl":"إبراهيم بن المهدي يتهمه بالزندقة — عبد الله بن العباس يشغف بغناء شعره"},
{"id":"b33-58","bab":"الجزء 4","sec":"عبد الله بن العباس يشغف بغناء شعره","page":"ج4 ص107","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى الصولي قال حدثني عبد الله بن العباس بن الفضل بن الربيع قال رآني الرشيد مشغوفا بالغناء في شعر أبي العتاهية صوت\n(أحمد قال لي ولم يدر ما بي ... أتحب الغداة عتبة حقا)\n(فتنفست ثم قلت نعم حبا ... جرى في العروق عرقا فعرقا)\n(لو تجسين يا عتيبة قلبي ... لوجدت الفؤاد قرحا تفقا)\n(قد لعمري مل الطبيب ومل الأهل ... مني مما أقاسي وألقى)\n(ليتني مت فاسترحت فإني ... أبدا ما حييت منها ملقى)\nولا سيما من مخارق وكان يغني فيه رملا لإبراهيم أخذه عنه وفيه لحن لفريدة رمل هكذا قال الصولي فريدة بالياء وغيره يقول فرندة بالنون\nحدثني الصولي قال حدثنا محمد بن موسى قال حدثنا محمد بن صالح العدوي قال أخبرني أبو العتاهية قال كان الرشيد مما يعجبه غناء الملاحين في الزلالات إذا ركبها وكان يتأذى بفساد كلامهم ولحنهم فقال قولوا لمن معنا من الشعراء يعملوا لهؤلاء شعرا يغنون فيه فقيل له ليس أحد أقدر على هذا من أبي العتاهية وهو في الحبس قال فوجه إلي الرشيد قل شعرا حتى أسمعه منهم ولم يأمر بإطلاقي فغاظني ذلك فقلت والله لأقولن شعرا يحزنه ولا يسر به فعملت شعرا ودفعته إلى من حفظه الملاحين فلما ركب الحراقة سمعه وهو\n(خانك الطرف الطموح ... أيها القلب الجموح)\n(لدواعي الخير والشر ... دنو ونزوح)\n(هل لمطلوب بذنب ... توبة منه نصوح)\n(كيف إصلاح قلوب ... إنما هن قروح)\n(أحسن الله بنا أن ... الخطايا لا تفوح)\n(فإذا المستور منا ... بين ثوبيه نضوح)\n(كم رأينا من عزيز ... طويت عنه الكشوح)\n(صاح منه برحيل ... صائح الدهر الصدوح)\n(موت بعض الناس في الأرض ... على قوم فتوح)\n(سيصير المرء يوما ... جسدا)\n(بين عيني كل حي ... علم الموت يلوح)\n(كلنا في غفلة والموت ... يغدو ويروح)\n(لبني الدنيا من الدنيا ... غبوق وصبوح)\n(رحن في الوشي وأصبحن ... علين المسوح)\n(كل نطاح من الدهر له يوم نطوح ... )\n(نح على نفسك يا مسكين ... إن كنت تنوح)\n(لتموتن وإن عمرت ... ما عمر نوح)\nال فلما سمع ذلك الرشيد جعل يبكي وينتحب وكان الرشيد من أغزر الناس دموعا في وقت الموعظة وأشدهم عسفا في وقت الغضب والغلظة فلما رأى الفضل بن الربيع كثرة بكائه أومأ إلى الملاحين أن يسكتوا حدثني الصولي قال حدثني الحسن بن جابر كاتب الحسن بن رجاء قال لما حبس الرشيد أبا العتاهية دفعه إلى منجاب فكان يعنف به فقال أبو العتاهية\n(منجاب مات بدائه ... فاعجل له بدوائه)\n(إن الإمام أعله ... ظلما بحد شقائه)\n(لا تعنفن سياقه ... ما كل ذاك برائه)\n(ما شمت هذا في مخايل ... بارقات سمائه)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":37,"spl":"إبراهيم بن المهدي يتهمه بالزندقة — عبد الله بن العباس يشغف بغناء شعره","partial":1},
{"id":"b33-59","bab":"الجزء 4","sec":"مدح الرشيد وأبناءه الثلاثة","page":"ج4 ص109","text":"أخبرني محمد بن عمران الصيرفي قال حدثنا العنزي قال حدثني أحمد بن\nمعاوية القرشي قال لما عقد الرشيد ولاية العهد لبنيه الثلاثة الأمين والمأمون والمؤتمن قال أبو العتاهية\n(رحلت عن الربع المحيل قعودي ... إلى ذي زحوف جمة وجنود)\n(وراع يراعي الليل في حفظ أمة ... يدافع عنها الشر غير رقود)\n(بألوية جبريل يقدم أهلها ... ورايات نصر حوله وبنود)\n(تجافى عن الدنيا وأيقن أنها ... مفارقة ليست بدار خلود)\n(وشد عرا الإسلام منه بفتية ... ثلاثة أملاك ولاة عهود)\n(هم خير أولاد لهم خير والد ... له خير آباء مضت وجدود)\n(بنو المصطفى هارون حول سريره ... فخير قيام حوله وقعود)\n(تقلب ألحاظ المهابة بينهم ... عيون ظباء في قلوب أسود)\n(جدودهم شمس أتت في أهلة ... تندت لراء في نجوم سعود)\nال فوصله الرشيد بصلة ما وصل بمثلها شاعرا قط أخبرنا أبو الحسن أحمد بن محمد الأسدي إجازة قال حدثني الرياشي قال قدم رسول لملك الروم إلى الرشيد فسأل عن أبي العتاهية وأنشده شيئا من شعره وكان يحسن العربية فمضى إلى ملك الروم وذكره له فكتب ملك الروم إليه ورد رسوله يسأل الرشيد أن يوجه بأبي العتاهية ويأخذ فيه رهائن من أراد وألح في ذلك فكلم الرشيد أبا العتاهية في ذلك فاستعفى منه وأباه واتصل بالرشيد أن ملك الروم أمر أن يكتب بيتان من شعر أبي العتاهية على أبواب مجالسه\nوباب مدينته وهما صوت\n(ما اختلف الليل والنهار ولا ... دارت نجوم السماء في الفلك)\n(إلا لنقل السلطان عن ملك ... قد انقضى ملكه إلى ملك)\nخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثنا الربيع بن محمد الختلي الوراق قال أخبرني ابن أبي العتاهية أن الرشيد لما أطلق أباه من الحبس لزم بيته وقطع الناس فذكره الرشيد فعرف خبره فقال قولوا له صرت زير نساء وحلس بيت فكتب إليه أبو العتاهية\n(برمت بالناس وأخلاقهم ... فصرت أستأنس بالوحده)\n(ما أكثر الناس لعمري وما ... أقلهم في منتهى العده)\nم قال لا ينبغي أن يمض شعر إلى أمير المؤمنين ليس فيه مدح له فقرن هذين البيتين بأربعة أبيات مدحه فيها وهي صوت\n(عاد لي من ذكرها نصب ... فدموع العين تنسكب)\n(وكذاك الحب صاحبه ... يعتريه الهم والوصب)\n(خير من يرجى ومن يهب ... ملك دانت له العرب)\n(وحقيق أن يدان له ... من أبوه للنبي أب)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":38,"spl":"مدح الرشيد وأبناءه الثلاثة"},
{"id":"b33-60","bab":"الجزء 4","sec":"قال شعرا فأبكى الرشيد","page":"ج4 ص112","text":"حدثنا الصولي قال حدثنا عون بن محمد قال حدثنا محمد بن أبي العتاهية قال قال الرشيد لأبي عظني فقال له أخافك فقال له أنت آمن فأنشده\n(لا تأمن الموت في طرف ولا نفس ... إذا تسترت بالأبواب والحرس)\n(واعلم بأن سهام الموت قاصدة ... لكل مدرع منا ومترس)\n(ترجو النجاة ولم تسلك طريقتها ... إن السفينة لا تجري على اليبس)\nال فبكى الرشيد حتى بل كمه حدثني عمي قال حدثني أحمد بن أبي طاهر قال قال لي أحمد بن أبي فنن تناظرت أنا والفتح بن خاقان في منزله أيما الرجلين أشعر أبو نواس أم أبو العتاهية فقال الفتح أبو نواس وقلت أبو العتاهية ثم قلت لو وضعت أشعار العرب كلها بإزاء شعر أبي العتاهية لفضلها وليس بيننا خلاف في أن له في كل قصيدة جيدا ووسطا وضعيفا فإذا جمع جيده كان أكثر من جيد كل مجود ثم قلت له بمن ترضى قال بالحسين بن الضحاك فما انقطع كلامنا حتى دخل الحسين بن الضحاك فقلت ما تقول\nفي رجلين تشاجرا فضل أحدهما أبو نواس وفضل الآخر أبا العتاهية فقال الحسين أم من فضل أبا نواس على أبي العتاهية زانية فخجل الفتح حتى تبين ذلك فيه ثم لم يعاودني في شيء من ذكرهما حتى افترقنا وقد حدثني الحسن بن محمد بهذا الخبر على خلاف ما ذكره إبراهيم بن المهدي فيما تقدم فقال حدثني هارون بن مخارق قال حدثني أبي قال جاءني أبو العتاهية فقال قد عزمت على أن أتزود منك يوما تهبه لي فمتى تنشط فقلت متى شئت فقال أخاف أن تقطع بي فقلت والله لا فعلت وإن طلبني الخليفة فقال يكون ذلك في غد فقلت أفعل فلما كان من غد باكرني رسوله فجئته فأدخلني بيتا له نظيفا فيه فرش نظيف ثم دعا بمائدة عليها خبز سميذ وخل وبقل وملح وجدي مشوي فأكلنا منه ثم دعا بسمك مشوي فأصبنا منه حتى اكتفينا ثم دعا بحلواء فأصبنا منها وغسلنا أيدينا وجاؤونا بفاكهة وريحان وألوان من الأنبذة فقال اختر ما يصلح لك منها فاخترت وشربت وصب قدحا ثم قال غنني في قولي\n(أحمد قال لي ولم يدر ما بي ... أتحب الغداة عتبة حقا)\nغنيته فشرب قدحا وهو يبكي أحر بكاء ثم قال غنني في قولي\n(ليس لمن ليست له حيلة ... موجودة خير من الصبر)\nغنيته وهو يبكي وينشج ثم شرب قدحا آخر ثم قال غنني فديتك في قولي\n(خليلي مالي لا تزال مضرتي ... تكون مع الأقدار حتما من الحتم)\nفغنيته إياه وما زال يقترح علي كل صوت غني به في شعره فأغنيه ويشرب ويبكي حتى صار العتمة فقال أحب أن تصبر حتى ترى ما أصنع فجلست فأمر ابنه وغلامه فكسرا كل ما بين أيدنا من النبيذ وآلته والملاهي ثم أمر بإخراج كل ما في بيته من النبيذ وآلته فأخرج جميعه فما زال يكسره ويصب النبيذ وهو يبكي حتى لم يبق من ذلك شيء ثم نزع ثيابه واغتسل ثم لبس ثيابا بيضا من صوف ثم عانقني وبكى ثم قال السلام عليك يا حبيبي وفرحي من الناس كلهم سلام الفراق الذي لا لقاء بعده وجعل يبكي وقال هذا آخر عهدي بك في حال تعاشر أهل الدنيا فظننت أنها بعض حماقاته فانصرفت وما لقيته زمانا ثم تشوقته فأتيته فاستأذنت عليه فأذن لي فدخلت فإذا هو قد أخذ قوصرتين وثقب إحداهما وأدخل رأسه ويديه فيها وأقامها مقام القميص وثقب الأخرى وأخرج رجليه منها وأقامها مقام السراويل فلما رأيته نسيت كل ما كان عندي من الغم عليه والوحشة لعشرته وضحكت والله ضحكا ما ضحكت مثله قط فقال من أي شيء تضحك فقلت أسخن الله عينك هذا أي شيء هو من بلغك عنه أنه فعل مثل هذا من الأنبياء والزهاد والصحابة والمجانين إنزع عنك هذا يا سخين العين فكأنه استحيا مني ثم بلغني أنه جلس حجاما فجهدت أن أراه بتلك الحال فلم أره ثم مرض فبلغني أنه اشتهى أن أغنيه فأتيته عائدا فخرج إلي رسوله يقول إن دخلت إلي جددت لي حزنا وتاقت نفسي من سماعك إلى ما قد غلبتها عليه وأن أستودعك الله وأعتذر إليك من ترك الإلتقاء ثم كان آخر عهدي به حدثني جحظة قال حدثنا حماد بن إسحاق عن أبيه قال قيل لأبي العتاهية عند الموت ما تشتهي فقال أشتهي أن يجيء مخارق\nفيضع فمه على أذني ثم يغنيني\n(سيعرض عن ذكري وتنسى مودتي ... ويحدث بعدي للخليل خليل)\n(إذا ما انقضت عني من الدهر مدتي ... فإن غناء الباكيات قليل)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":39,"spl":"قال شعرا فأبكى الرشيد"},
{"id":"b33-61","bab":"الجزء 4","sec":"قال شعرا فأبكى الرشيد","page":"ج4 ص112","text":"أخبرني به أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال قال بشر بن الوليد لأبي العتاهية عند الموت ما تشتهي فذكر مثل الأول وأخبرني به ابن عمار أبو العباس عن ابن أبي سعد عن محمد بن صالح أن بشرا قال ذلك لأبي العتاهية عند الموت فأجابه بهذا الجواب","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":40,"spl":"قال شعرا فأبكى الرشيد — الشعر الذي كتب على قبره"},
{"id":"b33-62","bab":"الجزء 4","sec":"آخر شعر قاله قبل موته","page":"ج4 ص115","text":"نسخت من كتاب هارون بن علي حدثني علي بن مهدي قال حدثني عبد الله بن عطية قال حدثني محمد بن أبي العتاهية قال آخر شعر قاله أبي في مرضه الذي مات فيه\n(إلهي لا تعذبني فإني ... مقر بالذي قد كان مني)\n(فما لي حيلة إلا رجائي ... لعفوك إن عفوت وحسن ظني)\n(وكم من زلة لي في الخطايا ... وأنت علي ذو فضل ومن)\n(إذا فكرت في ندمي عليها ... عضضت أناملي وقرعت سني)\n(أجن بزهرة الدنيا جنونا ... وأقطع طول عمري بالتمني)\n(ولو أني صدقت الزهد عنها ... قلبت لأهلها ظهر المجن)\n(يظن الناس بي خيرا وإني ... لشر الخلق إن لم تعف عني)\nأخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل قال حدثني أحمد بن حمزة الضبعي قال أخبرني أبو محمد المؤدب قال قال أبو العتاهية لابنته رقية في علته التي مات فيها قومي يا بنية فاندبي أباك بهذه الأبيات فقامت فندبته بقوله\n(لعب البلى بمعالمي ورسومي ... وقبرت حيا تحت ردم همومي)\n(لزم البلى جسمي فاوهن قوتي ... إن البلى لموكل بلزومي)\nخبرني أحمد بن عبيد الله بن عمار قال حدثنا محمد بن داود بن الجراح قال حدثني عل بن محمد قال حدثني مخارق المغني قال توفي أبو العتاهية وإبراهيم الموصلي وأبو عمرو الشيباني عبد السلام في يوم واحد في خلافة المأمون وذلك في سنة ثلاث عشرة ومائتين أخبرني الحسن بن علي قال حدثنا ابن مهرويه عن أحمد بن يوسف عن أحمد بن الخليل عن إسماعيل بن أبي قتسة قال مات أبو العتاهية وراشد الخناق وهشيمة الخمارة في يوم واحد سنة تسع ومائتين وذكر الحارث بن أبي أسامة عن محمد بن سعد كاتب الواقدي أن أبا العتاهية مات في يوم الاثنين لثمان خلون من جمادى الأولى سنة إحدى عشرة ومائتين ودفن حيال قنطرة الزياتين في الجانب الغربي ببغداد أخبرني الصولي عن محمد بن موسى عن أبي محمد الشيباني عن محمد بن أبي العتاهية أن أباه توفي سنة عشر ومائتين","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":40,"spl":"قال شعرا فأبكى الرشيد — الشعر الذي كتب على قبره"},
{"id":"b33-63","bab":"الجزء 4","sec":"الشعر الذي كتب على قبره","page":"ج4 ص117","text":"أخبرني الصولي قال حدثني محمد بن موسى عن محمد بن القاسم عن إبراهيم بن عبد الله بن الجنيد عن إسحاق بن عبد الله بن شعيب قال أمر أبو العتاهية أن يكتب على قبره\n(أذن حي تسمعي ... إسمعي ثم عي وعي)\n(أنا رهن بمضجعي ... فاحذري مثل مصرعي)\n(عشت تسعين حجة ... أسلمتني لمضجعي)\n(كم ترى الحي ثابتا ... في ديار التزعزع)\n(ليس زاد سوى التقى ... فخذي منه أو دعي)\nخبرني الحسن بن علي قال حدثنا أحمد بن أبي خيثمة قال لما مات أبو العتاهية رثاه ابنه محمد بن أبي العتاهية فقال\n(يا أبي ضمك الثرى ... وطوى الموت أجمعك)\n(ليتني يوم مت صرت ... إلى حفرة معك)\n(رحم الله مصرعك ... برد الله مضجعك)\nخبرني الحسن قال حدثني أحمد بن زهير قال قال محمد بن أبي العتاهية لقيني محمد بن أبي محمد اليزيدي فقال أنشدني الأبيات التي أوصى أبوك أن تكتب على قبره فأنشأت أقول له\n(كذبت على أخ لك في مماته ... وكم كذب فشا لك في حياته)\n(وأكذب ما تكون على صديق ... كذبت عليه حيا في مماته)\nفخجل وانصرف قال والناس يقولون إنه أوصى أن يكتب على قبره شعر له وكان ابنه ينكر ذلك وذكر هارون بن علي بن مهدي عن عبد الرحمن بن الفضل أنه قرأ الأبيات العينية التي أولها\n(أذن حي تسمعي ... )\nلى حجر عند قبر أبي العتاهية ولم أذكر هاهنا مع أخبار أبي العتاهية أخباره مع عتبة وهي من أعظم أخباره لأنها طويلة وفيها أغان كثيرة وقد طالت أخباره هاهنا فأفردتها","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":40,"spl":"قال شعرا فأبكى الرشيد — الشعر الذي كتب على قبره","partial":1},
{"id":"b33-64","bab":"الجزء 4","sec":"أخبار فريدة","page":"ج4 ص119","text":"قال مؤلف هذا الكتاب هما اثنتان محسنتان لهما صنعة تسميان بفريدة فأما إحداهما وهي الكبرى فكانت مولدة نشأت بالحجاز ثم وقعت إلى آل الربيع فعلمت الغناء في دورهم ثم صارت إلى البرامكة فلما قتل جعفر بن يحيى ونكبوا هربت وطلبها الرشيد فلم يجدها ثم صارت إلى الأمين فلما قتل خرجت فتزوجها الهيثم بن مسلم فولدت له ابنه عبد الله ثم مات عنها فتزوجها السندي بن الحرشي وماتت عنده ولها صنعة جيدة منها في شعر الوليد بن يزيد صوت\n(ويح سلمى لو تراني ... لعناها ما عناني)\n(واقفا في الدار أبكي ... عاشقا حور الغواني)\nلحنها فيه خفيف رمل ومن صنعتها\nصوت\n(ألا أيها الركب النيام ألا هبوا ... نسائلكم هل يقتل الرجل الحب)\n(ألا رب ركب قد وقفت مطيهم ... عليك ولولا أنت لم يقف الركب)\nحنها فيه ثاني ثقيل وفيه لابن جامع خفيف رمل بالسبابة في مجرى الوسطى فحدثني محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثني العمري قال حدثني الهيثم بن عدي قال قال صالح بن حسان يوما ما نصف بيت كأنه أعرابي في شملة والنصف الآخر كأنه مخنث مفكك قلت لا أدري فقال قد أجلتك حولا فقلت لو أجلتني عشرة أحوال ما عرفته فقال أوه أف لك قد كنت أحسبك أجود ذهنا مما أرى فقلت فما هو الآن قال قول جميل\n(ألا أيها الركب النيام ألا هبوا ... )\nذا كلام أعرابي ثم قال\n(أسائلكم هل يقتل الرجل الحب ... )\nأنه والله من مخنثي العقيق وأما فريدة الأخرى فهي التي أرى بل لا أشك في أن اللحن المختار لها لأن إسحاق اختار هذه المائة الصوت للواثق فاختار فيها لمتيم لحنا ولأبي دلف لحنا ولسليم بن سلام لحنا ولرياض جارية أبي حماد لحنا وكانت فريدة أثيرا عند الواثق وحظية لديه جدا فاختار لها هذا الصوت لمكانها من الواثق ولأنها ليست دون من اختار له من نظرائها أخبرني الصولي قال حدثنا الحسين بن يحيى عن ريق أنها اجتمعت هي\nوخشف الواضحية يوما فتذاكرتا أحسن ما سمعتاه من المغنيات فقالت ريق شارية أحسنهن غناء ومتيم وقالت خشف عريب وفريدة ثم اجتمعتا على تساويهن وتقديم متيم في الصنعة وعريب في الغزارة والكثرة وشارية وفريدة في الطيب وأحكام الغناء حدثني جحظة قال حدثني أبو عبد الله الهشامي قال كانت فريدة جارية الواثق لعمرو بن بانة وهو أهداها إلى الواثق وكانت من الموصوفات المحسنات وربيت عند عمرو بن بانة مع صاحبة لها اسمها خل وكانت حسنة الوجه حسنة الغناء حادة الفطنة والفهم قال الهشامي فحدثني عمرو بن بانة قال غنيت الواثق\n(قلت حلا فاقبلي معذرتي ... ما كذا يجزي محب من أحب)\nقال لي تقدم إلى الستارة فألقه على فريدة فألقيته عليها فقالت هو حل أو خل كيف هو فعلمت أنها سألتني عن صاحبتها في خفاء من الواثق ولما تزوجها المتوكل أرادها على الغناء فأبت أن تغني وفاء للواثق فأقام على رأسها خادما وأمره أن يضرب رأسها أبدا أو تغني فاندفعت وغنت\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":41,"spl":"أخبار فريدة","partial":1},
{"id":"b33-65","bab":"الجزء 4","sec":"خبر لها مع الواثق","page":"ج4 ص121","text":"أخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال حدثني محمد\nابن الحارث بن بسخنر قال كانت لي نوبة في خدمة الواثق في كل جمعة إذا حضرت ركبت إلى الدار فإن نشط إلى الشرب أقمت عنده وإن لم ينشط انصرفت وكان رسمنا ألا يحضر أحد منا إلا في يوم نوبته فإني لفي منزلي في غير يوم نوبتي إذا رسل الخليفة قد هجموا علي وقالوا لي احضر فقلت ألخير قالوا خير فقلت إن هذا يوم لم يحضرني فيه أمير المؤمنين قط ولعلكم غلطتم قالوا الله المستعان لا تطل وبادر فقد أمرنا ألا ندعك تستقر على الأرض فداحلني فزع شديد وخفت أن يكون ساع قد سعى بي أو بلية قد حدثت في رأي الخليفة علي فتقدمت بما أردت وركبت حتى وافيت الدار فذهبت لأدخل على رسمي من حيث كنت أدخل فمنعت وأخذ بيدي الخدم فأدخلوني وعدلوا بي إلى ممرات لا أعرفها فزاد ذلك في جزعي وغمي ثم لم يزل الخدم يسلمونني من خدم إلى خدم حتى أفضيت إلى دار مفروشة الصحن ملبسة الحيطان بالوشي المنسوج بالذهب ثم أفضيت إلى رواق أرضه وحيطانه ملبسة بمثل ذلك وإذا الواثق في صدره على سرير مرصع بالجوهر وعليه ثياب منسوجة بالذهب وإلى جانبه فريدة جاريته عليها مثل ثيابه وفي حجرها عود فلما رآني قال جودت والله يا محمد إلينا فقبلت الأرض ثم قلت يا أمير المؤمنين خيرا قال خيرا أما ترانا طلبت والله ثالثا يؤنسنا فلم أر أحق بذلك منك فبحياتي بادر فكل شيئا وبادر إلينا فقلت قد والله يا سيدي أكلت وشربت أيضا قال فاجلس فجلست وقال هاتوا لمحمد رطلا في قدح فأحضرت ذلك واندفعت فريدة تغني\n(أهابك إجلالا وما بك قدرة ... علي ولكن ملء عين حبيبها)\n(وما هجرتك النفس يا ليل أنها ... قلتك ولا أن قل منك نصيبها)\nجاءت والله بالسحر وجعل الواثق يجاذبها وفي خلال ذلك تغني الصوت بعد الصوت وأغني أنا في خلال غنائها فمر لنا أحسن ما مر لأحد فإنا لكذلك إذ رفع رجله فضرب بها صدر فريدة ضربة تدحرجت منها من أعلى السرير إلى الأرض وتفتت عودها ومرت تعدو وتصيح وبقيت أنا كالمنزوع الروح ولم أشك في أن عينه وقعت علي وقد نظرت إليها ونظرت إلي فأطرق ساعة إلى الأرض متحيرا وأطرقت أتوقع ضرب العنق فإني لكذلك إذ قال لي يا محمد فوثبت فقال ويحك أرأيت أغرب مما تهيأ علينا فقلت يا سيدي الساعة والله تخرج روحي فعلى من أصابنا بالعين لعنة الله فما كان السبب ألذنب قال لا والله ولكن فكرت أن جعفرا بقعد هذا المقعد ويقعد معها كما هي قاعدة معي فلم أطق الصبر وخامرني ما أخرجني إلى ما رأيت فسري عني وقلت بل يقتل الله جعفرا ويحيا أمير المؤمنين أبدا وقبلت الأرض وقلت يا سيدي الله الله ارحمها ومر بردها فقال لبعض الخدم الوقوف ما يجيء بها فلم يكن بأسرع من أن خرجت وفي يدها عودها وعليها غير الثياب التي كانت عليها فلما رآها جذبها وعانقها فبكت وجعل هو يبكي واندفعت أنا في البكاء فقالت ما ذنبي يا مولاي ويا سيدي وبأي شيء استوجبت هذا فأعاد عليها ما قاله لي وهو يبكي وهي تبكي فقالت سألتك بالله يا أمير المؤمنين إلا ضربت عنقي الساعة وأرحتني من الفكر في هذا وأرحت قلبك من الهم بي وجعلت تبكي ويبكي ثم مسحا أعينهما ورجعت إلى مكانها وأومأ إلى خدم وقوف بشيء لا أعرفه فمضوا وأحضروا أكياسا فيها عين وورق ورزما فيه ثياب كثيرة وجاء خادم بدرج ففتحه وأخرج منه عقدا ما رأيت قط مثل جوهر كان فيه فألبسها إياه وأحضرت\nبدرة فيها عشرة آلاف درهم فجعلت بين يدي وخمسة تخوت فيها ثياب وعدنا إلى أمرنا وإلى أحسن مما كنا فلم نزل كذلك إلى الليل ثم تفرقنا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":42,"spl":"خبر لها مع الواثق"},
{"id":"b33-66","bab":"الجزء 4","sec":"قصتها مع المتوكل","page":"ج4 ص124","text":"وضرب الدهر ضربة وتقلد المتوكل فوالله إني لفي منزلي بعد يوم نوبتي إذ هجم علي رسل الخليفة فما أمهلوني حتى ركبت وصرت إلى الدار فأدخلت والله الحجرة بعينها وإذا المتوكل في الموضع الذي كان فيه الواثق على السرير بعينه وإلى جانبه فريدة فلما رآني قال ويحك أما ترى ما أنا فيه من هذه أنا منذ غدوة أطالبها بأن تغنيني فتأبى ذلك فقلت لها يا سبحان الله أتخالفين سيدك وسيدنا وسيد البشر بحياته غني فعرفت والله ثم اندفعت تغني\n(مقيم بالمجازة من قنونى ... وأهلك بالأجيفر فالثماد)\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)\nم ضربت بالعود الأرض ثم رمت بنفسها عن السرير ومرت تعدو وهي تصيح واسيداه فقال لي ويحك ما هذا فقلت لا أدري والله يا سيدي فقال فما ترى فقلت أرى أن أنصرف أنا وتحضر هذه ومعها غيرها فإن الأمر يؤول إلى ما يريد أمير المؤمنين قال فانصرف في حفظ الله فانصرفت ولم أدر ما كانت القصة أخبرني جعفر بن قدامة قال حدثني محمد بن عبد الملك قال سمعت فريدة تغني\n(أخلاي بي شجو وليس بكم شجو ... وكل امرئ مما بصاحبه خلو)\n(أذاب الهوى لحمي وجسمي ومفصلي ... فلم يبق إلا الروح والجسد النضو)\nما سمعت قبله ولا بعده غناء أحسن منه الشعر لأبي العتاهية والغناء لإبراهيم ثقيل أول مطلق في مجرى الوسطى عن الهشامي وله أيضا فيه خفيف ثقيل بالسبابة والبنصر عن ابن المكي وفيه لعمرو بن بانة رمل بالوسطى من مجموع أغانيه وفيه لعريب خفيف ثقيل آخر صحيح في غنائها من جمع ابن المعتز وعلي بن يحيى وتمام هذه الأبيات\n(وما من محب نال ممن يحبه ... هوى صادقا إلا سيدخله زهو)\nفيها كلها غناء مفترق الألحان في أبياته\n(بليت وكان المزح بدء بليتي ... فأحببت جهلا والبلايا لها بدو)\n(وعلقت من يزهو علي تجبرا ... وإني في كل الخصال له كفو)\nصوت","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":43,"spl":"قصتها مع المتوكل — من المائة المختارة من رواية جحظة عن أصحابه"},
{"id":"b33-67","bab":"الجزء 4","sec":"من المائة المختارة من رواية جحظة عن أصحابه","page":"ج4 ص125","text":"(باتت همومي تسري طوارقها ... أكف عيني والدمع سابقها)\n(لما أتاها من اليقين ولم ... تكن تراه يلم طارقها)\nالشعر لأميه بن أبي الصلت والغناء للهذلي خفيف ثقيل أول بالوسطى\nوفيه لابن محرز لحنان هزج وثقيل أول بالوسطى عن الهشامي وحبش وذكر يونس أن فيه لابن محرز لحنا واحدا مجنسا","topic":"ذكر نسب أبي العتاهية وأخباره","topicNo":33,"sp":43,"spl":"قصتها مع المتوكل — من المائة المختارة من رواية جحظة عن أصحابه"},
{"id":"b34-1","bab":"الجزء 4","sec":"ذكر أمية بن أبي الصلت ونسبه وخبره","page":"ج4 ص127","text":"واسم أبي الصلت عبد الله ين أبي ربيعة بن عوف بن عقدة بن عنزة بن قسي وهو ثقيف بن منبه بن بكر بن هوازن هكذا يقول من نسبهم إلى قيس وقد شرح ذلك في خبر طريح وأم أمية بن أبي الصلت رقية بنت عبد شمس بن عبد مناف وكان أبو الصلت شاعرا وهو الذي يقول في مدح سيف بن ذي يزن\n(ليطلب الثأر أمثال ابن ذي يزن ... إذ صار في البحر للأعداء أحوالا)\nقد كتب خبر ذلك في موضعه وكان له أربعة بنين عمرو وربيعة ووهب والقاسم وكان القاسم شاعرا وهو الذي يقول أنشدنيه الأخفش وغيره عن ثعلب وذكر الزبير أنها لأمية صوت\n(قوم إذا نزل الغريب بدارهم ... ردوه رب صواهل وقيان)\n(لا ينكتون الأرض عند سؤالهم ... لتلمس العلات بالعيدان)\nيمدح عبد الله بن جدعان بها وأولها\n(قومي ثقيف إن سألت وأسرتي ... وبهم أدافع ركن من عاداني)\nناه الغريض ولحنه ثقيل أول بالبنصر ولابن محرز فيه خفيف ثقيل أول بالوسطى عن الهشامي جميعا وكان ربيعة ابنه شاعرا وهو الذي يقول\n(وإن يك حيا من إياد فإننا ... وقيسا سواء ما بقينا وما بقوا)\n(ونحن خيار الناس طرا بطانة ... لقيس وهم خير لنا إن هم بقوا)","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":0,"spl":"ذكر أمية بن أبي الصلت ونسبه وخبره — طمعه في النبوة"},
{"id":"b34-2","bab":"الجزء 4","sec":"أتى في شعره بكلمات غريبة","page":"ج4 ص128","text":"أخبرني إبراهيم بن أيوب قال حدثنا عبد الله بن مسلم قال كان أمية بن أبي الصلت قد قرأ كتاب الله عز و جل الأول فكان يأتي في شعره بأشياء لا تعرفها العرب فمنها قوله\n(قمر وساهور يسل ويغمد ... )\nكان يسمى الله عز و جل في شعره السلطيط فقال\n(والسلطيط فوق الأرض مقتدر ... )\nوسماه في موضع آخر التغرور فقال وأيده التغرور وقال ابن قتيبة وعلماؤنا لا يحتجون بشيء من شعره لهذه العلة أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال قال أبو عبيدة إتفقت العرب على أن أشعر أهل المدن أهل يثرب ثم عبد القيس ثم ثقيف وأن أشعر ثقيف أمية بن أبي الصلت أخبرنا الحرمي قال حدثنا الزبير قال قال يحيى بن محمد قال الكميت أمية أشعر الناس قال كما قلنا ولم نقل كما قال","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":0,"spl":"ذكر أمية بن أبي الصلت ونسبه وخبره — طمعه في النبوة","partial":1},
{"id":"b34-3","bab":"الجزء 4","sec":"طمعه في النبوة","page":"ج4 ص129","text":"قال الزبير وحدثني عمي مصعب عن مصعب بن عثمان قال كان أمية بن أبي الصلت قد نظر في الكتب وقرأها ولبس المسوح تعبدا وكان ممن ذكر إبراهيم وإسماعيل والحنيفية وحرم الخمر وشك في الأوثان وكان محققا والتمس الدين وطمع في النبوة لأنه قرأ في الكتب أن نبيا يبعث من العرب فكان يرجو أن يكونه قال فلما بعث النبي قيل له هذا الذي كنت تستريث وتقول فيه فحسده عدو الله وقال إنما كنت أرجو أن أكونه فأنزل الله فيه عز و جل ( واتل عليهم نبأ الذي آتيناه آياتنا فانسلخ منها\nال وهو\nالذي يقول\n(كل دين يوم القيامة عند الله ... إلا دين الحنيفة زور)\nال الزبير وحدثني يحيى بن محمد قال كان أمية يحرض قريشا بعد وقعة بدر وكان يرثي من قتل من قريش في وقعة بدر فمن ذلك قوله\n(ماذا ببدر والعقنقل ... من مرازبة جحاجح)\nقال وهي قصيدة نهى رسول الله عن رواياتها ويقال إن أمية قدم على أهل مكة باسمك اللهم فجعلوها في أول كتبهم مكان بسم الله الرحمن الرحيم قال الزبير وحدثني علي بن محمد المدائني قال قال الحجاج على المنبر ذهب قوم يعرفون شعر أمية وكذلك اندراس الكلام","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":0,"spl":"ذكر أمية بن أبي الصلت ونسبه وخبره — طمعه في النبوة"},
{"id":"b34-4","bab":"الجزء 4","sec":"تكدر بعد أن أخبر ببعثة النبي","page":"ج4 ص130","text":"أخبرني الحرمي قال حدثنا الزبير عن عمر بن أبي بكر المؤملي وغيره قال كان أمية بن أبي الصلت يلتمس الدين ويطمع في النبوة فخرج إلى الشام فمر بكنيسة وكان معه جماعة من العرب وقريش فقال أمية إن لي حاجة في هذه الكنيسة فانتظروني فدخل الكنيسة وأبطأ ثم خرج إليهم كاسفا متغير اللون فرمى بنفسه وأقاموا حتى سري عنه ثم مضوا فقضوا حوائجهم ثم رجعوا فلما\nصاروا إلى الكنيسة قال لهم انتظروني ودخل إلى الكنيسة فأبطأ ثم خرج إليهم أسوأ من حاله الأولى فقال أبو سفيان بن حرب قد شققت على رفقائك فقال خلوني فإني أرتاد على نفسي لمعادي إن هاهنا راهبا عالما أخبرني أنه تكون بعد عيسى عليه السلام ست رجعات وقد مضت منها خمس وبقيت واحدة وأنا أطمع في النبوة وأخاف أن تخطئني فأصابني ما رأيت فلما رجعت ثانية أتيته فقال قد كانت الرجعة وقد بعث نبي من العرب فيئست من النبوة فأصابني ما رأيت إذ فاتني ما كنت أطمع فيه قال وقال الزهري خرج أمية في سفر فنزلوا منزلا فأم أمية وجها وصعد في كثيب فرفعت له كنيسة فانتهى إليها فإذا شيخ جالس فقال لأمية حين رآه إنك لمتبوع فمن أين يأتيك رئيك قال من شقي الأيسر قال فأي الثياب أحب إليك أن يلقاك فيها قال السواد قال كدت تكون نبي العرب ولست به هذا خاطر من الجن وليس بملك وإن نبي العرب صاحب هذا الأمر يأتيه من شقه الأيمن وأحب الثياب إليه أن يلقاه فيها البياض قال الزهري وأتى أمية أبا بكر فقال يا أبا بكر عمي الخبر فهل أحسست شيئا قال لا والله قال قد وجدته يخرج العام","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":1,"spl":"تكدر بعد أن أخبر ببعثة النبي — سؤاله عن عتبة بن ربيعة"},
{"id":"b34-5","bab":"الجزء 4","sec":"سؤاله عن عتبة بن ربيعة","page":"ج4 ص131","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال سمعت خالد بن يزيد يقول إن أمية وأبا سفيان اصطحبا في تجارة إلى الشأم ثم ذكر نحوه وزاد فيه فخرج من عند الراهب وهو ثقيل فقال له أبو سفيان إن بك لشرا فما قصتك قال خير أخبرني عن عتبة بن ربيعة كم سنه فذكر سنا وقال أخبرني عن ماله فذكر مالا فقال له وضعته فقال أبو\nسفيان بل رفعته فقال له إن صاحب هذا الأمر ليس بشيخ ولا ذي مال قال وكان الراهب أشيب وأخبره أن الأمر لرجل من قريش أخبرني الحرمي قال حدثني الزبير قال حدثت عن عبد الرحمن بن أبي حماد المنقري قال كان أمية جالسا معه قوم فمرت بهم غنم فثغت منها شاة فقال للقوم هل تدرون ما قالت الشاة قالوا لا قال إنها قالت لسخلتها مري لا يجيء الذئب فيأكلك كما أكل أختك عام أول في هذا الموضع فقام بعض القوم إلى الراعي فقال له أخبرني عن هذه الشاة التي ثغت ألها سخلة فقال نعم هذه سخلتها قال أكانت لها عام أول سخلة قال نعم وأكلها الذئب في هذا الموضع","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":1,"spl":"تكدر بعد أن أخبر ببعثة النبي — سؤاله عن عتبة بن ربيعة"},
{"id":"b34-6","bab":"الجزء 4","sec":"ذهب في شعره بعامة ذكر الآخرة","page":"ج4 ص132","text":"قال الزبير وحدثني يحيى بن محمد عن الأصمعي قال ذهب أمية في شعره بعامة ذكر الآخرة وذهب عنترة بعامة ذكر الحرب وذهب عمر بن أبي ربيعة بعامة ذكر الشباب قال الزبير حدثني عمر بن أبي بكر المؤملي قال حدثني رجل من أهل الكوفة قال كان أمية نائما فجاء طائران فوقع أحدهما على باب البيت ودخل الآخر فشق عن قلبه ثم رده الطائر فقال له الطائر الآخر أوعى قال نعم قال زكا قال أبى\nأخبرني عمي قال حدثني أحمد بن الحارث عن ابن الأعرابي عن ابن دأب قال خرج ركب من ثقيف إلى الشأم وفيهم أمية بن أبي الصلت فلما قفلوا راجعين نزلوا منزلا ليتعشوا بعشاء إذ أقبلت عظاية حتى دنت منهم فحصبها بعضهم بشيء في وجهها فرجعت وكفتوا سفرتهم ثم قاموا يرحلون ممسين فطلعت عليهم عجوز من رواء كثيب مقابل لهم تتوكأ على عصا فقالت ما منعكم أن تطعموا رجيمة الجارية اليتيمة التي جاءتكم عشية قالوا ومن أنت قالت أنا أم العوام إمت منذ أعوام أما ورب العباد لتفترقن في البلاد وضربت بعصاها الأرض ثم قالت بطئي إيابهم ونفري ركابهم فوثبت الإبل كأن على ذروة كل بعير منها شيطانا ما يملك منها شيء حتى افترقت في الوادي فجمعناها في آخر النهار من الغد ولم نكد فلما أنخناها لنرحلها طلعت علينا العجوز فضربت الأرض بعصاها ثم قالت كقولها الأول ففعلت الإبل كفعلها بالأمس فلم نجمعها إلا الغد عشية فلما أنخناها لنرحلها أقبلت العجوز ففعلت كفعلها في اليومين ونفرت الإبل فقلنا لأمية أين ما كنت تخبرنا به عن نفسك فقال اذهبوا أنتم في طلب الإبل ودعوني فتوجه إلى ذلك الكثيب الذي كانت العجوز تأتي منه حتى علاه وهبط منه إلى واد فإذا فيه كنيسة وقناديل وإذا رجل مضطجع معترض على بابها وإذا رجل أبيض الرأس واللحية فلما رأى أمية قال إنك لمتبوع فمن أين يأتيك صاحبك قال من أذني اليسرى قال فبأي الثياب يأمرك قال بالسواد قال هذا خطيب الجن كدت والله أن تكونه ولم\nتفعل إن صاحب النبوة يأتيه صاحبه من قبل أذنه اليمنى ويأمره بلباس البياض فما حاجتك فحدثه حديث العجوز فقال صدقت وليست بصادقة هي امرأة يهودية من الجن هلك زوجها منذ أعوام وإنها لن تزال تصنع ذلك بكم حتى تهلككم إن استطاعت فقال أمية وما الحيلة فقال جمعوا ظهركم فإذا جاءتكم ففعلت كما كانت تفعل فقولوا لها سبع من فوق وسبع من أسفل باسمك اللهم فلن تضركم فرجع أمية إليهم وقد جمعوا الظهر فلما أقبلت قال لها ما أمره به الشيخ فلم تضرهم فلما رأت الإبل لم تتحرك قالت قد عرفت صاحبكم وليبيضن أعلاه وليسودن أسفله فأصبح أمية وقد برص في عذاريه وأسود أسفله فلما قدموا مكة ذكروا لهم هذا الحديث فكان ذلك أول ما كتب أهل مكة باسمك اللهم في كتبهم","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":2,"spl":"ذهب في شعره بعامة ذكر الآخرة"},
{"id":"b34-7","bab":"الجزء 4","sec":"خبر الطائرين اللذين حاورهما","page":"ج4 ص134","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيى قال حدثنا عبد العزيز بن عمران عن عبد الرحمن بن عبد الله بن عامر بن مسعود عن الزهري قال دخل يوما أمية بن أبي الصلت على أخته وهي تهيء أدما لها فأدركه النوم فنام على سرير في ناحية البيت قال فانشق جانب من السقف في البيت وإذا بطائرين قد وقع أحدهما على صدره ووقف الآخر مكانه فشق الواقع صدره فأخرج قلبه فشقه فقال الطائر الواقف للطائر الذي على صدره أوعى قال وعى قال أقبل قال أبى قال فرد قلبه في موضعه فنهض فأتبعهما أمية طرفه فقال\n(لبيكما لبيكما ... هأنذا لديكما)\nلا بريء فاعتذر ولا ذو عشيرة فأنتصر فرجع الطائر فوقع على صدره فشقه ثم أخرج قلبه فشقه فقال الطائر الأعلى أوعى قال وعى قال أقبل قال أبى ونهض فأتبعهما بصره وقال\n(لبيكما لبيكما ... هأنذا لديكما)\nا مال يغنيني ولا عشيرة تحميني فرجع الطائر فوقع على صدره فشقه ثم أخرج قلبه فشقه فقال الطائر الأعلى أوعى قال وعى قال أقبل أبى ونهض فأتبعهما بصره وقال\n(لبيكما لبيكما ... هأنذا لديكما)\nمحفوف بالنعم محوط من الريب قال فرجع الطائر فوقع على صدره فشقه وأخرج قلبه فشقه فقال الأعلى أوعى فقال وعى قال أقبل قال أبى قال ونهض فأتبعهما بصره وقال\n(لبيكما لبيكما ... هأنذا ليدكما)\n(إن تغفر اللهم تغفر جما ... وأي عبد لك لا ألما)\nالت أخته ثم انطبق السقف وجلس أمية يمسح صدره فقلت يا أخي هل تجد شيئا قال لا ولكني أجد حرا في صدري ثم أنشأ يقول\n(ليتني كنت قبل ما قد بدا لي ... في قنان الجبال أرعى الوعولا)\n(إجعل الموت نصب عينك واحذر ... غولة الدهر إن للدهر غولا)\nالنبي شعره حدثني محمد بن جرير الطبري قال حدثنا ابن حميد قال حدثني سلمة عن ابن إسحاق عن يعقوب بن عتبة عن عكرمة عن ابن عباس أن رسول الله صدق أمية في قوله\n(رجل وثور تحت رجل يمينه ... والنسر للأخرى وليث مرصد)\nقال رسول الله ( صدق\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني حماد بن عبد الرحمن بن الفضل الحراني قال حدثنا أبو يوسف وليس بالقاضي عن الزهري عن عروة عن عائشة عن النبي بمثل هذا","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":3,"spl":"خبر الطائرين اللذين حاورهما — قول النبي إن كاد أمية ليسلم"},
{"id":"b34-8","bab":"الجزء 4","sec":"قول النبي إن كاد أمية ليسلم","page":"ج4 ص136","text":"أخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثنا جعفر بن الحسين المهلبي قال حدثني إبراهيم بن إبراهيم بن أحمد عن عكرمة قال أنشد النبي قول أمية\n(الحمد لله ممسانا ومصبحنا ... بالخير صبحنا ربي ومسانا)\n(رب الحنيفة لم تنفد خزائنها ... مملوءة طبق الآفاق سلطانا)\n(ألا نبي لنا منا فيخبرنا ... ما بعد غايتنا من رأس محيانا)\n(بينا يربيننا آباؤنا هلكوا ... وبينما نقتني الأولاد أفنانا)\n(وقد علمنا لو أن العلم ينفعنا ... أن سوف يلحق أخرانا بأولانا)\nفقال النبي ( إن كاد أمية ليسلم\nخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أحمد بن معاوية قال حدثنا عبد الله بن أبي بكر وحدثنا خالد بن عمارة","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":3,"spl":"خبر الطائرين اللذين حاورهما — قول النبي إن كاد أمية ليسلم"},
{"id":"b34-9","bab":"الجزء 4","sec":"أن أمية عتب على ابن له فأنشأ يقول","page":"ج4 ص137","text":"(غذوتك مولودا ومنتك يافعا ... تعل بما أجني عليك وتنهل)\n(إذا ليلة نابتك بالشكو لم أبت ... لشكواك إلا ساهرا أتململ)\n(كأني أنا المطروق دونك بالذي ... طرقت به دوني فعيني تهمل)\n(تخاف الردى نفسي عليك وإنني ... لأعلم أن الموت حتم مؤجل)\n(فلما بلغت السن والغاية التي ... إليها مدى ما كنت فيك أؤمل)\n(جعلت جزائي غلظة وفظاظة ... كأنك أنت المنعم المتفضل)\nال الزبير قال أبو عمرو الشيباني قال أبو بكر الهذلي قال قلت لعكرمة ما رأيت من يبلغنا عن النبي أنه قال لأمية ( آمن شعره وكفر قلبه\nفقال هو حق وما الذي أنكرتم من ذلك فقلت له أنكرنا قوله\n(والشمس تطلع كل آخر ليلة ... حمراء مطلع لونها متورد)\n(تأبى فلا تبدو لنا في رسلها ... إلا معذبة وإلا تجلد)\nما شأن الشمس تجلد قال والذي نفسي بيده ما طلعت قط حتى ينخسها سبعون ألف ملك يقولن لها اطلعي فتقول أأطلع على قوم يعبدونني من دون الله قال فيأتيها شيطان حين تستقبل الضياء يريد أن يصدها عن الطلوع فتطلع على قرنيه فيحرقه الله تحتها وما غربت قط إلا خرت لله ساجدة فيأتيها شيطان يريد أن يصدها عن السجود فتغرب على قرنيه فيحرقه الله تحتها وذلك قول النبي\n(تطلع بين قرني شيطان وتغرب بين قرني شيطان ... )\nدثني أحمد بن محمد بن الجعد قال حدثنا محمد بن عباد قال حدثنا سفيان بن عيينة عن زياد بن سعد أنه سمع ابن حاضر يقول اختلف ابن عباس وعمرو بن العاصي عند معاوية فقال ابن عباس ألا أغنيك قال بلى فأنشده\n(والشمس تغرب كل آخر ليلة ... في عين ذي خلب وتأط حرمد)","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":4,"spl":"أن أمية عتب على ابن له فأنشأ يقول — أخباره في مرض موته","partial":1},
{"id":"b34-10","bab":"الجزء 4","sec":"أخباره في مرض موته","page":"ج4 ص138","text":"أخبرني الحرمي قال حدثنا عمي عن مصعب بن عثمان عن ثابت بن الزبير قال لما مرض أمية مرضه الذي مات فيه جعل يقول قد دنا أجلي وهذه المرضة منيتي وأنا أعلم أن الحنيفية حق ولكن الشك يداخلني في محمد قال ولما دنت وفاته أغمي عليه قليلا ثم أفاق وهو يقول\n(لبيكما لبيكما ... هأنذا لديكما)\nلا مال يفديني ولا عشيرة تنجيني ثم أغمي عليه أيضا بعد ساعة حتى ظن من حضره من أهله أنه قد قضى ثم أفاق وهو يقول\n(لبيكما لبيكما ... هأنذا لديكما)\nا بريء فأعتذر ولا قوي فأنتصر ثم إنه بقي يحدث من حضره ساعة ثم أغمي\nعليه مثل المرتين الأوليين حتى يئسوا من حياته وأفاق وهو يقول\n(لبيكما لبيكما ... هأنذا لديكما)\nحفوف بالنعم\n(إن تغفر اللهم تغفر جما ... وأي عبد لك لا ألما)\nم أقبل على القوم فقال قد جاء وقتي فكونوا في أهبتي وحدثهم قليلا حتى يئس القوم من مرضه وأنشأ يقول\n(كل عيش وإن تطاول دهرا ... منتهى أمره إلى أن يزولا)\n(ليتني كنت قبل ما قد بدا لي ... في رؤوس الجبال أرعى الوعولا)\n(اجعل الموت نصب عينيك واحذر ... غولة الدهر إن للدهر غولا)\nم قضى نحبه ولم يؤمن بالنبي وقد قيل في وفاة أمية غير هذا أخبرني عبد العزيز بن أحمد عم أبي قال حدثنا أحمد بن يحيى ثعلب قال سمعت في خبر أمية بن أبي الصلت حين بعث النبي أنه أخذ بنتيه وهرب بهما إلى أقصى اليمن ثم عاد إلى الطائف فبينما هو يشرب مع إخوان له في قصر غيلان بالطائف وقد أودع ابنتيه اليمن ورجع إلى بلاد الطائف إذ سقط غراب على شرفة في القصر فنعب نعبة فقال أمية بفيك الكثكث وهو التراب فقال أصحابه ما يقول قال يقول إنك إذا شربت الكأس التي بيدك مت فقلت بفيك الكثكث ثم نعب نعبة أخرى فقال أمية نحو ذلك فقال أصحابه ما يقول قال زعم أنه يقع على هذه المزبلة أسفل القصر فيستثير\nعظما فيبتلعه فيشجى به فيموت فقلت نحو ذلك فوقع الغراب على المزبلة فأثار العظم فشجي به فمات فانكسر أمية ووضع الكأس من يده وتغير لونه فقال له أصحابه ما أكثر ما سمعنا بمثل هذا وكان باطلا فألحوا عليه حتى شرب الكأس فمال في شق وأغمي عليه ثم أفاق ثم قال لا بريء فأعتذر ولا قوي فأنتصر ثم خرجت نفسه","topic":"ذكر أمية بن أبي الصلت ونسبه وخبره","topicNo":34,"sp":4,"spl":"أن أمية عتب على ابن له فأنشأ يقول — أخباره في مرض موته"},
{"id":"b35-1","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص140","text":"(تبلت فؤادك في المنام خريدة ... تشفي الضجيع ببارد بسام)\n(كالمسك تخلطه بماء سحابة ... أو عاتق كدم الذبيح مدام)\nعروضه من - الكامل - الشعر لحسان بن ثابت والغناء لموسى بن خارجة الكوفي ثقيل أول بإطلاق الوتر في مجرى البنصر وذكر حماد عن أبيه أن فيه لحنا لعزة الميلاء وليس موسى بكثير الصنعة ولا مشهور ولا ممن خدم الخلفاء","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":0,"spl":"صوت من المائة المختارة — بماذا أفضل الشعراء"},
{"id":"b35-2","bab":"الجزء 4","sec":"أخبار حسان بن ثابت ونسبه","page":"ج4 ص141","text":"هو حسان بن ثابت بن المنذر بن حرام بن عمرو بن زيد مناة بن عدي بن عمرو بن مالك بن النجار واسمه تيم الله بن ثعلبة بن عمرو بن الخزرج بن حارثة بن ثعلبة وهو العنقاء بن عمرو وإنما سمي العنقاء لطول عنقه وعمرو هو مزيقياء بن عامر بن ماء السماء بن حارثة الغطريف بن امرئ القيس البطريق ابن ثعلبة البهلول بن مازن بن الأزد وهو ذرى وقيل ذراء ممدود بن الغوث بن نبت بن مالك بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان قال مصعب الزبيري فيما أخبرنا به الحسن بن علي عن أحمد بن زهير عمه قال بنو عدي بن عمرو بن مالك بن النجار يسمون بني معالة ومعالة أمه وهي امرأة من القين وإليها كانوا ينسبون وأم حسان بن ثابت بن المنذر الفريعة بنت خالد بن قيس بن لوذان بن عبدود بن زيد بن ثعلبة بن الخزرج بن ساعدة بن كعب بن الخزرج وقيل إن اسم النجار تيم اللات وفي ذلك يقول حسان بن ثابت\n(وأم ضرار تنشد الناس والها ... أما لابن تيم الله ماذا أضلت)\nعني ضرار بن عبد المطلب وكان ضل فنشدته أمه وإنما سماه رسول الله\nتيم الله لأن الأنصار كانت تنسب إليه فكره أن يكون في أنسابها ذكر اللات ويكنى حسان بن ثابت أبا الوليد وهو فحل من فحول الشعراء وقد قيل إنه أشعر أهل المدر وكان أحد المعمرين من المخضرمين عمر مائة وعشرين سنة ستين في الجاهلية وستين في الإسلام","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":0,"spl":"صوت من المائة المختارة — بماذا أفضل الشعراء"},
{"id":"b35-3","bab":"الجزء 4","sec":"سنوات عمره الطويلة","page":"ج4 ص142","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة قال عاش ثابت ابن المنذر مائة وخمسين سنة وعاش حسان مائة وعشرين سنة ومما يحقق ذلك ما أخبرني به الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني الزبير بن بكار قال حدثني محمد بن حسين عن إبراهيم بن محمد عن صالح بن إبراهيم عن يحيى بن عبد الرحمن بن سعد بن زرارة عن حسان بن ثابت قال إني لغلام يفعة ابن سبع سنين أو ثمان إذا بيهودي بيثرب يصرخ ذات غداة يا معشر يهود فلما اجتمعوا إليه قالوا ويلك مالك قال طلع نجم أحمد الذي يولد به في هذه الليلة قال ثم أدركه اليهودي ولم يؤمن به فهذا يدل على مدة عمره في الجاهلية لأنه ذكر أنه أدرك ليلة ولد النبي وله يومئذ ثمان سنين والنبي بعث وله أربعون سنة وأقام بمكة ثلاث عشرة سنة فقدم المدينة ولحسان يومئذ على ما ذكره ستون سنة أو إحدى وستون سنة وحينئذ أسلم أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار عن عبد الرحمن بن عبد الله قال حدثني ابن أبي الزناد قال عمر حسان بن ثابت عشرين ومائة سنة ستين في الجاهلية وستين في الإسلام\nقال أخبرني الحسن بن علي قال أخبرني أحمد بن زهير قال حدث سليمان بن حرب عن حماد بن زيد عن يزيد بن حازم عن سليمان بن يسار قال رأيت حسان بن ثابت وله ناصية قد سدلها بين عينيه أخبرني أحمد بن عبد العزيز الجوهري قال حدثني علي بن محمد النوفلي عن أبيه قال كان حسان بن ثابت يخضب شاربه وعنفقته بالحناء ولا يخضب سائر لحيته فقال له ابنه عبد الرحمن يا أبت لم تفعل هذا قال لأكون كأني أسد والغ في دم","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":0,"spl":"صوت من المائة المختارة — بماذا أفضل الشعراء"},
{"id":"b35-4","bab":"الجزء 4","sec":"بماذا أفضل الشعراء","page":"ج4 ص143","text":"أخبرنا محمد بن الحسن بن دريد قال أخبرنا أبو حاتم عن أبي عبيدة قال فضل حسان الشعراء بثلاث كان شاعر الأنصار في الجاهلية وشاعر النبي في النبوة وشاعر اليمن كلها في الإسلام قال أبو عبيدة وأجمعت العرب على أن حسان أشعر أهل المدر أخبرنا بذلك أيضا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة عن أبي عبيدة قال اتفقت العرب على أن أشعر أهل المدر أهل يثرب ثم عبد القيس ثم ثقيف وعلى أن أشعر أهل يثرب حسان بن ثابت أخبرني حبيب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة قال حدثنا عفان قال حدثنا عبد الواحد بن زياد قال حدثنا معمر عن الزهري عن سعيد بن المسيب قال\nجاء حسان إلى نفر فيهم أبو هريرة فقال أنشدك الله أسمعت رسول الله يقول أجب عني ثم قال اللهم أيده بروح القدس قال أبو هريرة اللهم نعم","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":0,"spl":"صوت من المائة المختارة — بماذا أفضل الشعراء"},
{"id":"b35-5","bab":"الجزء 4","sec":"عارض شعراء قريش","page":"ج4 ص144","text":"أخبرني حبيب بن نصر وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة قال حدثنا وهب بن جرير قال حدثنا أبي قال سمعت محمد بن سيرين قال أبو زيد وحدثنا هوذة بن خليفة قال حدثنا عوف عن محمد بن سيرين قال كان يهجو رسول الله ثلاثة رهط من قريش عبد الله بن الزبعري وأبو سفيان بن الحارث بن عبد المطلب وعمرو بن العاصي فقال قائل لعلي بن أبي طالب رضوان الله عليهم أهج عنا القوم الذين قد هجونا فقال علي رضي الله عنه إن أذن لي رسول الله فعلت فقال رجل يا رسول الله ائذن لعلي كي يهجو عنا هؤلاء القوم الذين قد هجونا قال ليس هناك أو ليس عنده ذلك ثم قال للأنصار ما منع القوم الذين نصروا رسول الله بسلاحهم أن ينصروه بألسنتهم فقال حسان بن ثابت أنا لها وأخذ بطرف لسانه وقال والله ما يسرني به مقول بين بصرى وصنعاء فقال كيف تهجوهم وأنا منهم فقال إني أسلك منهم كما تسل الشعرة من العجين قال فكان يهجوهم ثلاثة من الأنصار حسان بن ثابت وكعب بن مالك وعبد الله بن رواحة فكان حسان وكعب\nيعارضانهم بمثل قولهم بالوقائع والأيام والمآثر ويعيرانهم بالمثالب وكان عبد الله بن رواحة يعيرهم بالكفر قال فكان في ذلك الزمان أشد القول عليهم قول حسان وكعب وأهون القول عليهم قول ابن رواحة فلما أسلموا وفقهوا الإسلام كان أشد القول عليهم قول ابن رواحة أخبرنا أحمد بن عبد العزيز وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا عبد الله بن بكر بن حبيب السهمي قال حدثنا أبو يونس القشيري وهو حاتم بن أبي صغيرة قال حدثنا سماك بن حرب قال قال حسان أبو الحسام فقال يا رسول الله ائذن لي فيه وأخرج لسانا له أسود فقال يا رسول الله لو شئت لفريت به المزاد ائذن لي فيه فقال اذهب إلى أبي بكر فليحدثك حديث القوم وأيامهم وأحسابهم ثم اهجهم وجبريل معك قال أبو زيد قال ابن وهب وحدثنا بهذا الحديث حاتم عن السدي عن البراء بن عازب وعن سماك بن حرب فأنا أشك أهو عن أحدهما أم عنهما جميعا قال أبو زيد وحدثنا علي بن عاصم قال حدثنا حاتم بن أبي صغيرة عن سماك بن حرب بنحوه وزاد فيه فأخرج لسانه أسود فوضعه على طرف أرنبته وقال يا رسول الله لو شئت لفريت به المزاد فقال يا حسان وكيف وهو مني وأنا منه قال والله لأسلنه منك كما يسل الشعر من العجين قال يا\nحسان فأت أبا بكر فإنه أعلم بأنساب القوم منك فأتى أبا بكر فأعلمه ما قال رسول الله فقال كف عن فلانة واذكر فلانة فقال\n(هجوت محمدا فأجبت عنه ... وعند الله في ذاك الجزاء)\n(فإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء)\nتهجوه و لست له بكفء ... فشركما لخيركما الفداء","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":1,"spl":"عارض شعراء قريش"},
{"id":"b35-6","bab":"الجزء 4","sec":"قريش تتهم أبا بكر في شعر حسان","page":"ج4 ص146","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثنا أحمد بن سليمان عن الأصمعي عن عبد الرحمن بن أبي الزناد قال لما أنشدت قريش شعر حسان قالت إن هذا الشتم ما غاب عن ابن أبي قحافة قال الزبير وحدثني محمد بن يحيى عن يعقوب بن إسحاق بن مجمع عن رجل من بني العجلان قال لما بلغ أهل مكة شعر حسان ولم يكونوا علموا أنه قوله جعلوا يقولون لقد قال أبو بكر الشعر بعدنا قال الزبير وحدثني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني محمد بن فضالة عن أبيه عن خالد بن محمد بن فضالة عن أبيه عن خالد بن محمد بن ثابت بن قيس بن شماس قال نهى عمر بن الخطاب الناس أن ينشدوا شيئا من مناقضة الأنصار ومشركي قريش وقال في ذلك شتم الحي بالميت وتجديد الضغائن وقد هدم الله أمر الجاهلية بما جاء من الإسلام فقدم المدينة عبد الله بن الزبعري السهمي وضرار\nابن الخطاب الفهري ثم المحاربي فنزلا على أبي أحمد بن جحش وقالا له نحب أن ترسل إلى حسان بن ثابت حتى يأتيك فننشده وينشدنا مما قلنا له وقال لنا فأرسل إليه فجاءه فقال له يا أبا الوليد هذان أخواك ابن الزبعري وضرار قد جاءا أن يسمعاك وتسمعهما ما قالا لك وقلت لهما فقال ابن الزبعري وضرار نعم يا أبا الوليد إن شعرك كان يحتمل في الإسلام ولا يحتمل شعرنا وقد أحببنا أن نسمعك وتسمعنا فقال حسان أفتبدآن أم أبدأ قالا نبدأ نحن قال ابتدئا فأنشداه حتى فار فصار كالمرجل غضبا ثم استويا على راحلتيهما يريدان مكة فخرج حسان حتى دخل على عمر بن الخطاب فقص عليه قصتهما وقصته فقال له عمر لن يذهبا عنك بشيء إن شاء الله وأرسل من يردهما وقال له عمر لو لم تدركهما إلا بمكة فارددهما علي وخرجا فلما كانا بالروحاء رجع ضرار إلى صاحبه بكرة فقال له يا بن الزبعري أنا أعرف عمر وذبه عن الإسلام وأهله وأعرف حسان وقلة صبره على ما فعلنا به وكأني به قد جاء وشكا إليه ما فعلنا فأرسل في آثارنا وقال لرسوله إن لم تلحقهما إلا بمكة فارددهما علي فاربح بنا ترك العناء وأقم بنا مكاننا فإن كان الذي ظننت فالرجوع من الروحاء أسهل منه من أبعد منها وإن أخطأ ظني فذلك الذي نحب ونحن من وراء المضي فقال ابن الزبعري نعم ما رأيت قال فأقاما بالروحاء فما كان إلا كمر الطائر حتى وافاهما رسول عمر فردهما إليه فدعا لهما بحسان وعمر في جماعة من أصحاب رسول الله فقال لحسان أنشدهما مما قلت لهما فأنشدهما حتى فرغ مما قال لهما فوقف فقال له عمر أفرغت قال نعم فقال له أنشداك\nفي الخلاء وأنشدتهما في الملا وقال لهما عمر إن شئتما فأقيما وإن شئتما فانصرفا وقال لمن حضره إني قد كنت نهيتكم أن تذكروا مما كان بين المسلمين والمشركين شيئا دفعا للتضاغن عنكم وبث القبيح فيما بينكم فأما إذا أبوا فاكتبوه واحتفظوا به فدونوا ذلك عندهم قال خلاد بن محمد فأدركته والله وإن الأنصار لتجدده عندها إذا خافت بلاه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":2,"spl":"قريش تتهم أبا بكر في شعر حسان — هجاؤه لأبي سفيان بن الحارث"},
{"id":"b35-7","bab":"الجزء 4","sec":"هجاؤه لأبي سفيان بن الحارث","page":"ج4 ص148","text":"أخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا عفان بن مسلم قال حدثنا عمران بن زيد قال سمعت أبا إسحاق قال في قصة حسان وأبي سفيان بن الحارث نحو ما ذكره مما قدمنا ذكره وزاد فيه فقال حسان فيه\n(وإن سنام المجد من آل هاشم ... بنو بنت مخزوم ووالدك العبد)\n(ومن ولدت أبناء زهرة منكم ... كرام ولم يلحق عجائزك المجد)\n(وإن امرأ كانت سمية أمه ... وسمراء مغلوب إذا بلغ الجهد)\n(وأنت هجين نيط في آل هاشم ... كما نيط خلف الراكب القدح الفرد)\nقال العباس ومالي وما لحسان يعني في ذكره نتيلة فقال فيها\n(ولست كعباس ولا كابن أمه ... ولكن هجين ليس يورى له زند)\nأخبرنا أحمد قال حدثنا عمر بن شبة قال حدثنا القعنبي قال حدثنا مروان بن معاوية قال حدثنا إياس السلمي عن ابن بريدة قال أعان جبريل عليه السلام حسان بن ثابت في مديح النبي بسبعين بيتا","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":2,"spl":"قريش تتهم أبا بكر في شعر حسان — هجاؤه لأبي سفيان بن الحارث"},
{"id":"b35-8","bab":"الجزء 4","sec":"النبي يمدح حسان وكعبا وابن رواحة","page":"ج4 ص149","text":"أخبرنا أحمد قال حدثنا عمر قال حدثنا محمد بن منصور قال حدثنا سعيد بن عامر قال حدثني جويرية بن أسماء قال بلغني أن رسول الله قال أمرت عبد الله بن رواحة فقال وأحسن وأمرت كعب بن مالك فقال وأحسن وأمرت حسان بن ثابت فشفى واشتفى أخبرنا أحمد قال حدثنا عمر قال حدثنا أحمد بن عيسى قال حدثنا ابن وهب قال أخبرنا عمرو بن الحارث عن سعيد بن أبي هلال عن مروان بن عثمان ويعلى ابن شداد بن أوس عن عائشة قالت سمعت رسول الله يقول لحسان بن ثابت الشاعر إن روح القدس لا يزال يؤيدك ما كافحت عن الله عز و جل وعن رسول الله أخبرنا أحمد قال حدثنا عمر قال حدثنا هوذة بن خليفة قال حدثنا عوف بن محمد قال قال النبي ليلة وهو في سفر أين حسان بن ثابت فقال حسان لبيك يا رسول الله وسعديك قال احد فجعل ينشد ويصغي إليه النبي ويستمع فما زال يستمع إليه وهو سائق راحلته حتى كان رأس الراحلة يمس\nالورك حتى فرغ من نشيده فقال النبي ( لهذا أشد عليهم من وقع النبل","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":3,"spl":"النبي يمدح حسان وكعبا وابن رواحة — النبي يختاره لحماية أعراض المسلمين"},
{"id":"b35-9","bab":"الجزء 4","sec":"رده على عمر عندما انتهره لانشاده في المسجد","page":"ج4 ص149","text":"أخبرنا أحمد قال حدثنا عمر قال حدثنا أبو عاصم النبيل قال أخبرنا ابن جريج قال أخبرنا زياد بن أبي سهل قال حدثني سعيد بن المسيب أن عمر مر بحسان بن ثابت وهو ينشد في مسجد رسول الله فانتهره عمر فقال حسان قد أنشدت فيه من هو خير منك فانطلق عمر أخبرنا أحمد قال حدثنا أبو داود الطيالسي قال حدثنا إبراهيم بن سعد عن الزهري عن سعيد بن المسيب أن عمر مر على حسان وهو ينشد في مسجد رسول الله فذكر مثله وزاد فيه وعلمت أنه يريد النبي أخبرنا أحمد قال حدثنا عمر قال حدثنا محمد بن حاتم قال حدثنا شجاع بن الوليد عن الإفريقي عن مسلم بن يسار أن عمر مر بحسان وهو ينشد الشعر في مسجد رسول الله فأخذ بأذنه وقال أرغاء كرغاء البعير فقال حسان دعنا عنك يا عمر فوالله لتعلم أني كنت أنشد في هذا المسجد من هو خير منك فلا يغير علي فصدقه عمر","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":3,"spl":"النبي يمدح حسان وكعبا وابن رواحة — النبي يختاره لحماية أعراض المسلمين"},
{"id":"b35-10","bab":"الجزء 4","sec":"مدح الزبير بن العوام","page":"ج4 ص150","text":"حدثنا محمد بن جرير الطبري والحرمي بن أبي العلاء وعبد العزيز بن أحمد عم أبي وجماعة غيرهم قالوا حدثنا الزبير بن بكار قال حدثنا أبو غزية محمد بن موسى قال حدثني عبد الله بن مصعب عن هشام بن عروة عن فاطمة بنت المنذر عن\nجدتها أسماء بنت أبي بكر قالت مر الزبير بن العوام بمجلس من أصحاب رسول الله وحسان بن ثابت ينشدهم من شعره وهم غير نشاط لما يسمعون منه فجلس معهم الزبير فقال مالي أراكم غير آذنين لما تسمعون من شعر ابن الفريعة فلقد كان يعرض لرسول الله فيحسن استماعه ويجزل عليه ثوابه ولا يشتغل عنه بشيء فقال حسان\n(أقام على عهد النبي وهديه ... حواريه والقول بالفعل يعدل)\n(أقام على منهاجه وطريقه ... يوالي ولي الحق والحق أعدل)\n(هو الفارس المشهور والبطل الذي ... يصول إذا ما كان يوم محجل)\n(إذا كشفت عن ساقها الحرب حشها ... بأبيض سباق إلى الموت يرقل)\n(وإن امرأ كانت صفية أمة ... ومن أسد في بيتها لمرفل)\n(له من رسول الله قربى قريبة ... ومن نصرة الإسلام نصر مؤثل)\n(فكم كربة ذب الزبير بسيفه ... عن المصطفى والله يعطي فيجزل)\n(فما مثله فيهم ولا كان قبله ... وليس يكون الدهر ما دام يذبل)\n(ثناؤك خير من فعال معاشر ... وفعلك يابن الهاشمية أفضل)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":3,"spl":"النبي يمدح حسان وكعبا وابن رواحة — النبي يختاره لحماية أعراض المسلمين"},
{"id":"b35-11","bab":"الجزء 4","sec":"النبي يختاره لحماية أعراض المسلمين","page":"ج4 ص151","text":"أخبرني أحمد بن عيسى العجلي قال حدثنا واصل بن عبد الأعلى قال حدثنا ابن فضيل عن مجالد عن الشعبي قال لما كان عام الأحزاب وردهم الله بغيظهم لم ينالوا خيرا قال النبي ( من يحمي أعراض المسلمين\nفقال كعب أنا يا رسول الله وقال عبد الله ابن رواحة أنا رسول الله وقال حسان بن ثابت أنا يا رسول الله فقال نعم أهجهم أنت فإنه سيعينك عليهم روح القدس أخبرني أحمد بن عبد الرحمن قال حدثنا عمر بن شبة قال حدثنا أبو داود قال حدثنا حديج بن معاوية عن أبي إسحاق عن سعيد بن جبير قال كنا عند ابن عباس فجاء حسان فقالوا قد جاء اللعين فقال ابن عباس ما هو بلعين لقد نصر رسول الله بلسانه ويده حدثنيه أحمد بن الجعد قال حدثنا محمد بن بكار قال حدثنا حديج بن معاوية قال حدثنا أبو إسحاق عن سعيد بن جبير قال جاء رجل إلى ابن عباس فقال قد جاء اللعين حسان من الشام فقال ابن عباس ما هو بلعين لقد جاهد مع رسول الله بلسانه ونفسه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":3,"spl":"النبي يمدح حسان وكعبا وابن رواحة — النبي يختاره لحماية أعراض المسلمين"},
{"id":"b35-12","bab":"الجزء 4","sec":"حسان يجيب شاعر وفد تميم","page":"ج4 ص152","text":"أخبرنا أحمد قال حدثنا عمر قال حدثنا عبد الله بن عمرو وشريح بن النعمان قالا حدثنا عبد الرحمن بن أبي الزناد عن هشام بن عروة عن أبيه عن عائشة قالت لما قدم وفد بني تميم وضع النبي لحسان منبرا وأجلسه عليه وقال إن الله ليؤيد حسان بروح القدس ما كافح عن نبيه هكذا روى أبو زيد هذا\nالخبر مختصرا وأتينا به على تمامه هاهنا لأن ذلك حسن فيه أخبرنا به الحسن ابن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير قال حدثنا محمد بن الضحاك عن أبيه قال قدم على النبي وفد بني تميم وهم سبعون أو ثمانون رجلا فيهم الأقرع بن حابس والزبرقان بن بدر وعطارد بن حاجب وقيس بن عاصم وعمرو بن الأهتم وانطلق معهم عيينة بن حصن فقدموا المدينة فدخلوا المسجد فوقفوا عند الحجرات فنادو بصوت عال جاف أخرج إلينا يا محمد فقد جئنا لنفاخرك وقد جئنا بشاعرنا وخطيبنا فخرج إليهم رسول الله فجلس فقام الأقرع بن حابس فقال والله إن مدحي لزين وإن ذمي لشين فقال النبي ذلك الله فقالوا إنا أكرم العرب فقال رسول الله أكرم منكم يوسف بن يعقوب بن إسحاق بن إبراهيم عليه السلام فقالوا ايذن لشاعرنا وخطيبنا فقام رسول الله فجلس وجلس معه الناس فقام عطارد بن حاجب فقال الحمد لله الذي له الفضل علينا وهو أهله الذي جعلنا ملوكا وجعلنا أعز أهل المشرق وأتانا أموالا عظاما نفعل فيها المعروف ليس في الناس مثلنا ألسنا برؤوس الناس وذوي فضلهم فمن فاخرنا فليعدد مثل ما عددنا ولو نشاء لأكثرنا\nولكنا نستحي من الإكثار فيما خولنا الله وأعطانا أقول هذا فأتوا بقول أفضل من قولنا أو أمر أبين من أمرنا ثم جلس فقام ثابت بن قيس بن شماس فقال الحمد لله الذي السموات والأرض خلقه قضى فيهن أمره ووسع كرسيه علمه ولم يقض شيئا إلا من فضله وقدرته فكان من قدرته أن اصطفى من خلقه لنا رسولا أكرمهم حسبا وأصدقهم حديثا وأحسنهم رأيا فأنزل عليه كتابا وأتمنه على خلقه وكان خيرة الله من العالمين ثم دعا رسول الله إلى الإيمان فأجابه من قومه وذوي رحمه المهاجرين أكرم الناس أنسابا وأصبح الناس وجوها وأفضل الناس فعالا ثم كان أول من اتبع رسول الله من العرب واستجاب له نحن معشر الأنصار فنحن أنصار الله ووزراء رسوله نقاتل الناس حتى يؤمنوا ويقولوا لا إله إلا الله فمن آمن بالله ورسوله منع منا ماله ودمه ومن كفر بالله ورسوله جاهدناه في الله وكان جهاده علينا يسيرا أقول قولي هذا وأستغفر الله للمؤمنين والمؤمنات فقام الزبرقان فقال\n(نحن الملوك فلا حي يقاربنا ... منا الملوك وفينا يؤخذ الربع)\n(تلك المكارم حزناها مقارعة ... إذا الكرام على أمثالها اقترعوا)\n(كم قد نشدنا من الأحياء كلهم ... عند النهاب وفضل العز يتبع)\n(وننحر الكوم عبطا في منازلنا ... للنازلين إذا ما استطعموا شبعوا)\n(ونحن نطعم عند المحل ما أكلوا ... من العبيط إذا لم يظهر القزع)\n(وننصر الناس تأتينا سراتهم ... من كل أوب فتمضي ثم تتبع)\nأرسل رسول الله إلى حسان بن ثابت فجاء فأمره أن يجيبه فقال حسان\n(إن الذوائب من فهر وإخوتهم ... قد بينوا سنة للناس تتبع)\n(يرضى بها كل من كانت سريرته ... تقوى الإله وبالأمر الذي شرعوا)\n(قوم إذا حاربوا ضروا عدوهم ... أو حاولوا النفع في أشياعهم نفعوا)\n(سجية تلك منهم غير محدثة ... إن الخلائق فاعلم شرها البدع)\n(لا يرقع الناس ما أوهت أكفهم ... عند الدفاع ولا يوهون ما رقعوا)\n(إن كان في الناس سباقون بعدهم ... فكل سبق لأدنى سبقهم تبع)\n(أعفة ذكرت في الوحي عفتهم ... لا يطمعون ولا يزري بهم طمع)\n(ولا يضنون عن جار بفضلهم ... ولا يمسهم من مطمع طبع)\n(يسمون للحرب تبدو وهي كالحة ... إذا الزعانف من أظفارها خشعوا)\n(لا يفرحون إذا نالوا عدوهم ... وإن أصيبوا فلا خور ولا جزع)\n(كأنهم في الوغى والموت مكتنع ... أسود بيشة في أرساغها فدع)\n(خذ منهم ما أتى عفوا وإن منعوا ... فلا يكن همك الأمر الذي منعوا)\n(فإن في حربهم فاترك عداوتهم ... سما يخاض عليه الصاب والسلع)\n(أكرم بقوم رسول الله قائدهم ... إذا تفرقت الأهواء والشيع)\n(أهدى لهم مدحي قلب يؤازره ... فيما أراد لسان حائك صنع)\n(فإنهم أفضل الأحياء كلهم ... إن جد بالناس جد القول أو شمعوا)\nفقام عطارد بن حاجب فقال\n(أتيناك كيما يعلم الناس فضلنا ... إذا اجتمعوا وقت احتضار المواسم)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":4,"spl":"حسان يجيب شاعر وفد تميم"},
{"id":"b35-13","bab":"الجزء 4","sec":"حسان يجيب شاعر وفد تميم","page":"ج4 ص152","text":"(بأنا فروع الناس في كل موطن ... وأن ليس في أرض الحجاز كدارم)\nقام حسان بن ثابت فقال\n(منعنا رسول الله من غضب له ... على أنف راض من معد وراغم)\n(هل المجد إلا السؤدد العود والندى ... وجاه الملوك واحتمال العظائم)\nال فقال الأقرع بن حابس والله إن هذا الرجل لمؤتى له والله لشاعره أشعر من شاعرنا ولخطيبه أخطب من خطيبنا ولأصواتهم أرفع من أصواتنا أعطني\nيا محمد فأعطاه فقال زدني فزاده فقال اللهم إنه سيد العرب فنزلت فيهم ( إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون\nثم إن القوم أسلموا وأقاموا عند النبي يتعلمون القرآن ويتفقهون في الدين ثم أرادوا الخروج إلى قومهم فأعطاهم رسول الله وكساهم وقال ( أما بقي منكم أحد\nوكان عمرو بن الأهتم في ركابهم فقال قيس بن عاصم وهو من رهطه وكان مشاحنا له لم يبق أحد إلا غلام حديث السن في ركابنا فأعطاه رسول الله مثل ما أعطاهم فبلغ عمرا ما قال قيس فقال عمرو بن الأهتم لقيس\n(ظللت مفترش الهلباء تشتمني ... عند الرسول فلم تصدق ولم تصب)\n(إن تبغضونا فإن الروم أصلكم ... والروم لا تملك البغضاء للعرب)\n(فإن سؤددنا عود وسؤددكم ... مؤخر عند أصل العجب والذنب)\nقال له قيس\n(لولا دفاعي كنتم أعبدا ... داركم الحيرة والسيلحون)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":5,"spl":"حسان يجيب شاعر وفد تميم — شعره الذي يقرر به إيمانه بالرسل"}]);
window.__BOOK__['p02'].push([{"id":"b35-14","bab":"الجزء 4","sec":"شعره الذي يقرر به إيمانه بالرسل","page":"ج4 ص157","text":"أخبرنا أحمد بن عبد العزيز وحبيب بن نصر قالا حدثنا عمر بن شبة قال حدثني عمر بن علي بن مقدم عن يحيى بن سعيد عن أبي حيان التيمي عن حبيب ابن أبي ثابت قال أبو زيد وحدثنا محمد بن عبد الله بن الزبير قال حدثنا مسعر عن سعد بن إبراهيم قالوا\nقال حسان بن ثابت للنبي صوت\n(شهدت بإذن الله أن محمدا ... رسول الذي فوق السموات من عل)\n(وأن أخا الأحقاف إذ يعذلونه ... يقوم بدين الله فيهم فيعدل)\n(وأن أبا يحيى ويحيى كلاهما ... له عمل في دينه متقبل)\n(وأن الذي عادى اليهود ابن مريم ... رسول أتى من عند ذي العرش مرسل)\n(وأن الذي بالجزع من بطن نخلة ... ومن دونها فل من الخير معزل)\nنى في هذه الأبيات معبد خفيف ثقيل أول بالبنصر من رواية يونس وغيره فقال النبي ( أنا أشهد معك\nخبرنا أحمد قال حدثنا عمر قال حدثنا زهير بن حرب قال حدثني جرير عن الأعمش عن أبي الضحى عن مسروق وأخبرني بها أحمد بن عيسى العجلي\nقال حدثنا سفيان بن وكيع قال حدثنا جرير عن الأعمش عن أبي الضحى عن مسروق قال دخلت على عائشة وعندها حسان وهو يرثي بنتا له وهو يقول\n(رزان حصان ما تزن بريبة ... وتصبح غرثى من لحوم الغوافل)\nقالت عائشة لكن أنت لست كذلك فقلت لها أيدخل عليك هذا وقد قال الله عز و جل ( والذي تولى كبره منهم له عذاب عظيم\nفقالت أما تراه في عذاب عظيم قد ذهب بصره","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":5,"spl":"حسان يجيب شاعر وفد تميم — شعره الذي يقرر به إيمانه بالرسل"},
{"id":"b35-15","bab":"الجزء 4","sec":"تنبأ بوقعة صفين قبل وقوعها","page":"ج4 ص159","text":"أخبرنا محمد بن خلف وكيع قال حدثنا إسماعيل بن إسحاق القاضي قال حدثنا ابن أبي أويس قال حدثني أبي ومالك بن الربيع بن مالك حدثاني جميعا عن الربيع بن مالك بن أبي عامر عن أبيه أنه قال بينا نحن جلوس عند حسان بن ثابت وحسان مضطجع مسند رجليه إلى فارع قد رفعهما عليه إذ قال مه أما رأيتم ما مر بكم الساعة قال مالك\nقلنا لا والله وما هو فقال حسان فاختة مرت الساعة بيني وبين فارع فصدمتني أو قال فزحمتني قال قلنا وما هي قال\n(ستأتيكم غدوا أحاديث جمة ... فأصغوا لها آذانكم وتسمعوا)\nال مالك بن أبي عامر فصبحنا من الغد حديث صفين أخبرنا وكيع قال حدثنا الليث بن محمد عن الحنظلي عن أبي عبدة عن العلاء بن جزء العنبري قال بينا حسان بن ثابت بالخيف وهو مكفوف إذ زفر زفرة ثم قال\n(وكأن حافرها بكل خميلة ... صاع يكيل به شحيح معدم)\n(عاري الأشاجع من ثقيف أصله ... عبد ويزعم أنه من يقدم)\nال والمغيرة بن شعبة جالس قريبا منه يسمع ما يقول فبعث إليه بخمسة آلاف درهم فقال من بعث بهذا قال المغيرة بن شعبة سمع ما قلت قال واسوءتاه وقبلها أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني الأصمعي قال\nجاء الحارث بن عوف بن أبي حارثة إلى النبي فقال أجرني من شعر حسان فلو مزج البحر بشعره لمزجه قال وكان السبب في ذلك فيما أخبرني به أحمد ابن عبد العزيز عن عمر بن شبة عن الأصمعي وأخبرني به الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير قال حدثني عمي مصعب أن الحارث بن عوف أتى رسول الله فقال ابعث معي من يدعو إلى دينك وأنا له جار فأرسل معه رجلا من الأنصار فغدرت بالحارث عشيرته فقتلوا الأنصاري فقدم الحارث على رسول الله وكان لا يؤنب أحدا في وجهه فقال ( ادعوا لي حسان\nفدعي له فلما رأى الحارث أنشده\n(يا حار من يغدر بذمة جاره ... منكم فإن محمدا لم يغدر)\n(إن تغدروا فالغدر منكم شيمة ... والغدر ينبت في أصول السخبر)\nقال الحارث اكففه عني يا محمد وأؤدي إليك دية الخفارة فأدى إلى النبي سبعين عشراء وكذلك دية الخفارة وقال يا محمد أنا عائذ بك من شره فلو مزج البحر بشعره مزجه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":6,"spl":"تنبأ بوقعة صفين قبل وقوعها"},
{"id":"b35-16","bab":"الجزء 4","sec":"النبي يعوضه بعد أن ضربه ابن المعطل","page":"ج4 ص161","text":"أخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني إبراهيم بن المنذر قال حدثنا عبد الله بن وهب قال أخبرنا العطاف بن خالد قال كان حسان بن ثابت يجلس إلى أطمه فارع ويجلس معه أصحاب له ويضع لهم بساطا يجلسون عليه فقال يوما وهو يرى كثرة من يأتي إلى النبي من العرب فيسلمون\n(أرى الجلابيب قد عزوا وقد كثروا ... وابن الفريعة أمسى بيضة البلد)\nبلغ ذلك رسول الله فقال ( من لي بأصحاب البساط بفارع\nقال صفوان بن المعطل أنا لك يا رسول الله منهم فخرج إليهم فاخترط سيفه فلما رأوه عرفوا الشر في وجهه ففروا وتبددوا وأدرك حسان داخلا بيته فضربه وفلق أليته قال فبلغنا أن النبي عوضه وأعطاه حائطا فباعه من معاوية بعد ذلك بمال كثير فبناه معاوية قصرا وهو الذي يقال له قصر الدارين وقد قيل إن صفوان بن المعطل إنما ضرب حسان لما قاله فيه وفي عائشة زوج النبي من الإفك لأن صفوان هو الذي رمى أهل الإفك عائشة به وأخبرنا محمد بن جرير قال حدثنا محمد بن حميد قال حدثنا سلمة عن محمد بن إسحاق عن يعقوب بن عتبة قال اعترض صفوان بن المعطل حسان بن ثابت بالسيف لما قذفه به من الإفك حين بلغه ما قاله وقد كان حسان قال شعرا يعرض بابن المعطل وبمن أسلم من العرب من مضر فقال\n(أمسى الجلابيب قد عزوا وقد كثروا ... وابن الفريعة أمسى بيضة البلد)\n(قد ثكلت أمه من كنت صاحبه ... أو كان منتشبا في برثن الأسد)\n(ما للقتيل الذي أعدوا فآخذه ... من دية فيه أعطيها ولا قود)\n(ما البحر حين تهب الريح شامية ... فيغطئل ويرمي العبر بالزبد)\n(يوما بأغلب مني حين تبصرني ... بالسيف أفري كفري العارض البرد)\nاعترضه صفوان بن المعطل بالسيف فضربه وقال\n(تلق ذباب السيف عني فإنني ... غلام إذا هوجيت لست بشاعر)\nحدثنا محمد بن جرير وقال حدثنا ابن حميد قال حدثنا سلمة عن محمد ابن إسحاق عن محمد بن إبراهيم بن الحارث التيمي أن ثابت بن قيس بن الشماس أخا بلحارث بن الخزرج وثب على صفوان ابن المعطل في ضربه حسان فجمع يديه على عنقه فانطلق به إلى دار بني الحارث ابن الخزرج فلقيه عبد الله بن رواحة فقال ما هذا فقال ألا أعجبك ضرب حسان بالسيف والله ما أراه إلا قد قتله فقال له عبد الله بن رواحة هل علم رسول الله بشيء من هذا قال لا والله قال لقد اجترأت أطلق الرجل فأطلقه ثم أتوا رسول الله فذكر ذلك له فدعا حسان وصفوان بن المعطل فقال ابن المعطل يا رسول الله آذاني وهجاني فضربته فقال رسول الله لحسان ( يا حسان أتعيب على قومي أن هداهم الله عز و جل للإسلام\nثم قال\n(أحسن يا حسان في الذي أصابك ... )\nقال هي لك يا رسول الله أخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني المدائني قال حدثنا إسماعيل بن إبراهيم قال حدثنا محمد بن إسحاق عن أبيه إسحاق بن يسار عن بعض رجال بني النجار بمثل ذلك وزاد في الشعر الذي قاله حسان زيادة ووافقه عليها مصعب الزبيري فيما أخبرنا به الحسن بن علي قال قال حدثنا أحمد بن زهير قال حدثنا الزبير بن بكار قال حدثني عمي مصعب في القصة فذكر أن فتية من المهاجرين والأنصار تنازعوا على الماء وهم يسقون خيولهم فغضب من ذلك حسان فقال هذا الشعر وذكر الزهري فيما أخبرنا أحمد بن يحيى بن الجعد قال حدثنا محمد بن إسحاق المسيبي قال حدثنا محمد بن فليح عن موسى بن عقبة عن ابن شهاب الزهري أن هذا الخبر كان بعد غزوة النبي المصطلق قال وكان في أصحاب رسول الله رجل يقال له سنان ورجل من بني غفار يقال له جهجاه فخرج جهجاه بفرس لرسول الله وفرس له يومئذ يسقيهما فأوردهما الماء فوجد على الماء فتية من الأنصار فتنازعوا فاقتتلوا فقال عبد الله ابن أبي ابن سلول هذا ما جزونا به آويناهم ثم هم يقاتلوننا وبلغ حسان بن ثابت الذي بين جهجاه وبين الفتية الأنصار فقال وهو يريد المهاجرين من القبائل قدموا على رسول الله في الإسلام وهذا الشعر من رواية مصعب دون الزهري\n(أمسى الجلابيب قد عزوا وقد كثروا ... وابن الفريعة أمسى بيضة البلد)\n(يمشون بالقول سرا في مهادنة ... تهددا لي كأني لست من أحد)\n(قد ثكلت أمه من كنت صاحبه ... أو كان منتشبا في برثن الأسد)\n(ما للقتيل الذي أسموا فأقتله ... من دية فيه أعطيها ولا قود)\n(ما البحر حين تهب الريح شامية ... فيغطئل ويرمى العبر بالزبد)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":7,"spl":"النبي يعوضه بعد أن ضربه ابن المعطل","partial":1},
{"id":"b35-17","bab":"الجزء 4","sec":"النبي يعوضه بعد أن ضربه ابن المعطل","page":"ج4 ص161","text":"(يوما بأغلب مني حين تبصرني ... أفري من الغيظ فري العارض البرد)\n(أما قريش فإني لست تاركهم ... حتى ينيبوا من الغيات بالرشد)\n(ويتركوا اللات والعزى بمعزلة ... ويسجدوا كلهم للواحد الصمد)\n(ويشهدوا أن ما قال الرسول لهم ... حق ويوفوا بعهد الله في سدد)\n(أبلغ بني بأني قد تركت لهم ... من خير ما ترك الآباء للولد)\n(الدار واسطة والنخل شارعة ... والبيض يرفلن في القسي كالبرد)\nال فقال رسول الله ( يا حسان نفست علي إسلام قومي وأغضبه كلامه فغدا صفوان بن المعطل السلمي على حسان فضربه بالسيف وقال صفوان\n(تلق ذباب السيف عني فإنني ... غلام إذا هوجيت لست بشاعر)\nوثب قومه على صفوان فحبسوه ثم جاؤوا سعد بن عبادة بن دليم بن حارثة بن أبي حزيمة بن ثعلبة بن طريف بن الخزرج بن ساعدة بن كعب بن الخزرج بن حارثة ابن ثعلبة بن عمرو بن عامر وهو مقبل على ناضحه بين القربتين فذكروا له ما\nفعل حسان وما فعلوا فقال أشاورتم في ذلك رسول الله قالوا لا فقعد إلى الأرض وقال وانقطاع ظهراه أتأخذون بأيديكم ورسول الله بين ظهرانيكم ودعا بصفوان فأتي به فكساه وخلاه فجاء إلى النبي فقال له رسول الله ( من كساك كساه الله\nقال حسان لأصحابه احملوني إلى رسول الله أترضاه ففعلوا فأعرض عنه رسول الله فردوه ثم سألهم فحملوه إليه الثانية فأعرض عنه رسول الله فانصرفوا به ثم قال لهم عودوا بي إلى رسول الله فقالوا له قد جئنا بك مرتين كل ذلك يعرض فلا نبرمه بك فقال احملوني إليه هذه المرة وحدها ففعلوا فقال يا رسول الله بأبي أنت وأمي احفظ قولي\n(هجوت محمدا فأجبت عنه ... وعند الله في ذاك الجزاء)\n(فإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء)\nرضي عنه رسول الله ووهب له سيرين أخت مارية أم ولد رسول الله إبراهيم هذه رواية مصعب وأما الزهري فإنه ذكر أن رسول الله لما بلغه ضرب السلمي حسان قال لهم ( خذوه فإن هلك حسان فاقتلوه\nأخذوه فأسروه وأوثقوه فبلغ ذلك سعد بن عبادة فخرج في قومه إليهم فقال أرسلوا الرجل فأبوا عليه فقال أعمدتم إلى قوم رسول الله تؤذونهم وتشتمونهم وقد زعمتم أنكم نصرتموهم أرسلوا الرجل فأبوا عليه حتى كاد يكون قتال ثم أرسلوه فخرج به سعد إلى أهله فكساه حلة ثم أرسله سعد إلى أهله فبلغنا أن النبي دخل المسجد ليصلي فيه فقال ( من كساك كساه الله من ثياب الجنة\nقال كساني سعد بن عبادة وذكر باقي الخبر نحوه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":8,"spl":"النبي يعوضه بعد أن ضربه ابن المعطل — الاعتذار عما رمى عائشة به"},
{"id":"b35-18","bab":"الجزء 4","sec":"الاعتذار عما رمى عائشة به","page":"ج4 ص166","text":"وحدثني محمد بن جرير الطبري قال حدثني ابن حميد قال حدثنا سلمة عن\nابن إسحاق عن محمد بن إبراهيم بن الحارث أن رسول الله أعطاه عوضا منها بيرحاء وهي قصر بني جديلة اليوم بالمدينة كانت مالا لأبي طلحة بن سهل تصدق بها إلى رسول الله فأعطاه حسان في ضربته وأعطاه سيرين أمة قبطية فولدت له عبد الرحمن بن حسان قال وكانت عائشة تقول لقد سئل عن صفوان بن المعطل فإذا هو حصور لا يأتي النساء قتل بعد ذلك شهيدا قال ابن إسحاق في روايته عن يعقوب بن عتبة فقال حسان يعتذر من الذي قال في عائشة\n(حصان رزان ما تزن بريبة ... وتصبح غرثى من لحوم الغوافل)\n(فإن كنت قد قلت الذي قد زعمتم ... فلا رفعت سوطي إلي أناملي)\n(وكيف وودي من قديم ونصرتي ... لآل رسول الله زين المحافل)\n(فإن الذي قد قيل ليس بلائط ... ولكنه قول امرىء بي ماحل)\nال الزبير وحدثني محمد بن الضحاك أن رجلا هجا حسان بن ثابت بما فعل به ابن المعطل فقال\n(وإن ابن المعطل من سليم ... أذل قياد رأسك بالخطام)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":8,"spl":"النبي يعوضه بعد أن ضربه ابن المعطل — الاعتذار عما رمى عائشة به"},
{"id":"b35-19","bab":"الجزء 4","sec":"دفاع عائشة عنه","page":"ج4 ص168","text":"أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال أخبرنا أبو عاصم قال أخبرنا ابن جريج قال أخبرني محمد بن السائب عن أمه أنها طافت مع عائشة ومعها أم حكيم وعاتكة امرأتان من بني مخزوم قالت فابتدرنا حسان نشتمه وهو يطوف فقالت ابن الفريعة تسببن قلن قد قال فيك فبراك الله قالت فأين قوله\n(هجوت محمدا فأجبت عنه ... وعند الله في ذاك الجزاء)\n(فإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء)\nخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا إبراهيم بن المنذر عن سفيان بن عيينة عن محمد بن السائب بن بركة عن أمه نحو ذلك وزاد فيه إني لأرجو أن يدخله الله الجنة بقوله أخبرني الحسن قال حدثنا الزبير عن عبد العزيز بن عمران عن سفيان بن عيينة وسلم بن خالد عن يوسف بن ماهك عن أمه قالت كنت أطوف مع عائشة بالبيت فذكرت حسان فسببته فقالت بئس ما قلت أتسبينه وهو الذي يقول\n(فإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء)\nقلت أليس ممن لعن الله في الدنيا والآخرة بما قال فيك قالت لم يقل شيئا ولكنه الذي يقول\n(حصان رزان ما تزن بريبة ... وتصبح غرثى من لحوم الغوافل)\nإن كان ما قد جاء عني قلته ... فلا رفعت سوطي إلي أناملي\nخبرني الحسن قال حدثنا الزبير قال حدثني مصعب عمي قال حدثني بعض أصحابنا عن هشام بن عروة عن أبيه قال\nكنت قاعدا عند عائشة فمر بجنازة حسان بن ثابت فنلت منه فقالت مهلا فقلت أليس الذي يقول قالت فكيف بقوله\n(فإن أبي ووالده وعرضي ... لعرض محمد منكم وقاء)\nأخبرني الحسن قال حدثنا أحمد قال حدثني أحمد بن سلمان عن سلمان بن حرب قال حدثنا حماد بن زيد عن أيوب عن محمد بن سيرين أن حسان أخذ يوما بطرف لسانه وقال يا رسول الله ما يسرني أن لي به مقولا بين صنعاء وبصرى ثم قال\n(لساني مغول لا عيب فيه ... وبحري ما تكدره الدلاء)\nخبرنا محمد بن جرير قال حدثنا محمد بن حميد قال حدثنا سلمة قال حدثني محمد بن إسحاق عن يحيى بن عباد بن عبد الله بن الزبير عن أبيه قال كانت صفية بنت عبد المطلب في فارع حصن حسان بن ثابت يعني يوم الخندق قالت وكان حسان معنا فيه والنساء والصبيان قالت فمر بنا رجل من يهود فجعل يطيف بالحصن وقد حاربت بنو قريظة وقطعت ما بينها وبين رسول الله ليس بيننا وبينهم أحد يدفع عنا ورسول الله والمسلمون في نحور عدوهم لا يستطيعون أن ينصرفوا إلينا عنهم إذ أتانا آت قالت فقلت يا حسان إن هذا اليهودي كما ترى يطيف بالحصن وإني والله ما آمنه أن يدل على عوراتنا من وراءنا من يهود وقد شغل عنا رسول الله وأصحابه فانزل إليه فاقتله فقال يغفر الله لك يابنة عبد المطلب لقد عرفت ما أنا بصاحب هذا\nقالت فلما قال ذلك ولم أر عنده شيئا احتجزت ثم أخذت عمودا ثم نزلت إليه من الحصن فضربته بالعمود حتى قتلته فلما فرغت منه رجعت إلى الحصن فقلت يا حسان انزل إليه فاسلبه فإنه لم يمنعني من سلبه إلا أنه رجل قال مالي بسلبه من حاجة يا بنت عبد المطلب","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":9,"spl":"دفاع عائشة عنه — رواية عن جبنه"},
{"id":"b35-20","bab":"الجزء 4","sec":"رواية عن جبنه","page":"ج4 ص170","text":"وأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا الزبير قال حدثنا علي بن صالح عن جدي عبد الله بن مصعب عن أبيه قال كان ابن الزبير يحدث أنه كان في فارع أطم حسان بن ثابت مع النساء يوم الخندق ومعهم عمر بن أبي سلمة قال ابن الزبير ومعنا حسان بن ثابت ضاربا وتدا في آخر الأطم فإذا حمل أصحاب رسول الله على المشركين حمل على الوتد فضربه بالسيف وإذا أقبل المشركون انحاز عن الوتد حتى كأنه يقاتل قرنا يتشبه بهم كأنه يري أنه مجاهد حين جبن وإني لأظلم ابن أبي سلمة وهو أكبر مني بسنيتن فأقول له تحملني على عنقك حتى أنظر فإني أحملك إذا نزلت قال فإذا حملني ثم سألني أن يركب قلت له هذه المرة أيضا قال وإني لأنظر إلى أبي معلما بصفرة فأخبرتها أبي بعد فقال أين كنت حينئذ فقلت على عنق ابن أبي سلمة يحملني فقال أما والذي نفسي بيده إن رسول الله ليجمع إلى أبويه قال ابن الزبير وجاء يهودي يرتقي إلى الحصن فقالت صفية له أعطني السيف فأعطاها فلما ارتقى اليهودي ضربته حتى قتلته ثم احتزت رأسه\nفأعطته حسان وقالت طوح به فإن الرجل أقوى وأشد رمية من المرأة تريد أن ترعب به أصحابه قال الزبير وحدثني عمي عن الواقدي قال كان أكحل حسان قد قطع فلم يكن يضرب بيده","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":9,"spl":"دفاع عائشة عنه — رواية عن جبنه"},
{"id":"b35-21","bab":"الجزء 4","sec":"تغنى بشجاعة النبي","page":"ج4 ص171","text":"قال الزبير وحدثني علي بن صالح عن جدي أنه سمع أن حسان بن ثابت أنشد رسول الله\n(لقد غدوت أمام القوم منتطقا ... بصارم مثل لون الملح قطاع)\n(يحفز عني نجاد السيف سابغة ... فضفاضة مثل لون النهي بالقاع)\nال فضحك رسول الله فظن حسان أنه ضحك من صفته نفسه مع جبنه قال الزبير وحدثني محمد بن الحسن قال قال حسان بن ثابت جئت نابغة بني ذبيان فوجدت الخنساء بنت\nعمرو حين قامت من عنده فأنشدته فقال إنك لشاعر وإن أخت بني سليم لبكاءة","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":10,"spl":"تغنى بشجاعة النبي — الحطيئة يجيبه بما لم يرضه"},
{"id":"b35-22","bab":"الجزء 4","sec":"الحطيئة يجيبه بما لم يرضه","page":"ج4 ص172","text":"قال الزبير وحدثني يحيى بن طلحة بن عبد الرحمن بن أبي بكر الصديق قال أخبرني غير واحد من مشايخي أن الحطيئة وقف على حسان بن ثابت وحسان ينشد من شعره فقال له حسان وهو لا يعرفه كيف تسمع هذا الشعر يا أعرابي قال الحطيئة لا أرى به بأسا فغضب حسان قولا اسمعوا إلى كلام هذا الأعرابي ما كنيتك قال أبو مليكة قال ما كنت قط أهون علي منك حين كنيت بامرأة فما اسمك قال الحطيئة فقال حسان امض بسلام أخبرني محمد بن العباس اليزيدي قال حدثني محمد بن الحسن بن مسعود الزرقي قال حدثنا عبد لله بن شبيب قال حدثني الزبير وأخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثني الزبير قال حدثني بعض القرشيين قال دخل حسان بن ثابت في الجاهلية بيت خمار بالشام ومعه أعشى بكر بن وائل فاشتريا خمرا وشربا فنام حسان ثم انتبه فسمع الأعشى يقول للخمار كره الشيخ الغرم فتركه حسان حتى نام ثم اشترى خمرا الخمار كلها ثم سكبها في البيت حتى سالت تحت الأعشى فعلم أنه سمع كلامه فاعتذر إليه فقال حسان\n(ولسنا بشرب فوقهم ظل بردة ... يعدون للخمار تيسا ومفصدا)\n(ولكننا شرب كرام إذا انتشوا ... أهانوا الصريح والسديف المسرهدا)\n(كأنهم ماتوا زمان حليمة ... فإن تأتهم تحمد ندامتهم غدا)\n(وإن جئتهم ألفيت حول بوتهم ... من المسك والجادي فتيتا مبددا)\n(ترى حول أثناء الزرابي ساقطا ... نعالا وقسوبا وريطا منضدا)\n(وذا نمرق يسعى وملصق خده ... بديباجة تكفافها قد تقددا)\nهذه القصيدة يقولها حسان بن ثابت في وقعة بدر يفخر بها ويعير الحارث ابن هشام بفراره عن أخيه أبي جهل بن هشام وفيها يقول صوت\n(إن كنت كاذبة الذي حدثتني ... فنجوت منجى الحارث بن هشام)\n(ترك الأحبة أن يقاتل دونهم ... ونجا برأس طمرة ولجام)\nناه يحيى المكي خفيف ثقيل أول بالوسطى ولعزة الميلاء فيه خفيف رمل بالبنصر وفيه خفيف ثقيل بالبنصر لموسى بن خارجة الكوفي فأجاب الحارث بن هشام وهو مشرك يومئذ فقال صوت\n(الله يعلم ما تركت قتالهم ... حتى رموا فرسي بأشقر مزبد)\n(وعلمت أني إن أقاتل واحدا ... أقتل ولا يضرر عدوي مشهدي)\nفررت منهم والأحبة فيهم ... طمعا لهم بعقاب يوم مرصد\nنى فيه إبراهيم الموصلي خفيف ثقيل أول بالبنصر وقيل بل هو لفليح أخبرنا محمد بن خلف وكيع قال حدثني سليمان بن أيوب قال حدثنا محمد بن سلام عن يونس قال لما صار ابن الأشعث إلى رتبيل تمثل رتبيل بقول حسان بن ثابت في الحارث بن هشام\n(ترك الأحبة أن يقاتل دونهم ... ونجا برأس طمرة ولجام)\nقال له ابن الأشعث أو ما سمعت ما رد عليه الحارث بن هشام قال وما هو فقال قال\n(الله يعلم ما تركت قتالهم ... حتى رموا فرسي بأشقر مزبد)\n(وعلمت أني إن أقاتل واحدا ... أقتل ولا يضرر عدوي مشهدي)\n(فصددت عنهم والأحبة فيهم ... طمعا لهم بعقاب يوم مرصد)\nقال رتبيل يا معشر العرب حسنتم كل شيء حتى حسنتم الفرار","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":10,"spl":"تغنى بشجاعة النبي — الحطيئة يجيبه بما لم يرضه"},
{"id":"b35-23","bab":"الجزء 4","sec":"أخبار غزاة بدر","page":"ج4 ص176","text":"حدثني بخبرها محمد بن جرير الطبري في المغازي قال حدثنا محمد بن حميد قال حدثنا سلمة قال حدثني محمد بن إسحاق قال حدثني محمد بن مسلم الزهري وعاصم بن عمر بن قتادة وعبد الله بن أبي بكر ويزيد بن رومان عن غزوة بدر وغيرهم من علمائنا عن عبد الله بن عباس كل قد حدثني بعض هذا الحديث فاجتمع حديثهم فيما سمعت من حديث بدر قالوا لما سمع رسول الله بأبي سفيان مقبلا من الشام ندب المسلمين إليهم وقال ( هذه عير قريش فيها أموالهم فاخرجوا إليها فلعل الله أن ينفلكموها\nفانتدب الناس فخف بعضهم وثقل بعضهم وذلك أنهم لم يظنوا أن رسول الله يلقى حربا وكان أبو سفيان استقدم حين دنا من الحجاز وجعل يتجسس الأخبار ويسأل من لقي من الركبان تخوفا على أموال الناس حتى أصاب خبرا من بعض الركبان أن محمدا استنفر أصحابه لك ولعيرك فجد عند ذلك فاستأجر ضمضم بن عمرو الغفاري فبعثه إلى مكة وأمره أن يأتي قريشا يستنفرهم إلى أموالهم ويخبرهم أن محمدا قد عرض لها في أصحابه فخرج ضمضم بن عمرو سريعا إلى مكة\nرؤيا تفزع عاتكة بنت عبد المطلب قال ابن إسحاق وحدثني من لا أتهم عن عكرمة مولى ابن عباس ويزيد بن رومان عن عروة بن الزبير قال وقد رأت عاتكة بنت عبد المطلب قبل قدوم ضمضم مكة بثلاث ليال رؤيا أفزعتها فبعثت إلى أخيها العباس بن عبد المطلب فقالت يا أخي والله لقد رأيت الليلة رؤيا أفظعتني وتخوفت أن يدخل على قومك منها شر أو مصيبة فاكتم عني ما أحدثك قال لها وما رأيت قالت رأيت راكبا أقبل علي بعير له حتى وقف بالأبطح ثم صرخ بأعلى صوته أن انفروا يا آل غدر لمصارعكم في ثلاث وأرى الناس قد اجتمعوا إليه ثم دخل المسجد والناس يتبعونه فبينما هم حوله مثل به بعيره على ظهر الكعبة ثم صرخ بأعلى صوته انفروا يا آل غدر لمصارعكم في ثلاث ثم مثل به بعيره على رأس أبي قبيس فصرخ بمثلها ثم أخذ صخرة فأرسلها فأقبلت تهوي حتى إذا كانت بأسفل الجبل ارفضت فما بقي بيت من بيوت مكة ولا دار من دورها إلا دخلتها منها فلقه قال العباس إن هذه لرؤيا وأنت فاكتميها ولا تذكريها لأحد ثم خرج العباس فلقي الوليد بن عتبة بن ربيعة وكان له صديقا فذكرها له واستكتمه إياها فذكرها الوليد لأبيه عتبة ففشا الحديث بمكة حتى تحدثت به قريش قال العباس فغدوت أطوف بالبيت وأبو جهل بن هشام ورهط من قريش قعود يتحدثون برؤيا عاتكة فلما رآني أبو جهل قال يا أبا الفضل إذا فرغت من طوافك فأقبل إلينا فلما فرغت أقبلت إليه حتى جلست معهم فقال لي أبو جهل يا بني عبد المطلب متى حدثت فيكم هذه النبية قال قلت وما ذاك قال الرؤيا التي رأت عاتكة قلت وما رأت قال يا بني عبد المطلب أما رضيتم أن\nتتنبأ رجالكم حتى تتنبأ نساؤكم قد زعمت عاتكة في رؤياها أنها قالت انفروا في ثلاث فسنتربص بكم هذه الثلاث فإن يكن ما قالت حقا فسيكون وإن تمض الثلاث ولم يكن من ذلك شيء نكتب كتابا عليكم أنكم أكذب أهل بيت في العرب قال العباس فوالله ما كان إليه مني كبير إلا جحدت ذلك وأنكرت أن تكون رأت شيئا قال ثم تفرقنا فلما أمسينا لم تبق امرأة من بني عبد المطلب إلا أتتني فقالت أقررتم لهذا الفاسق الخبيث أن يقع في رجالكم ويتناول النساء وأنت تسمع ولم يكن عندك غير لشيء مما سمعت قلت قد والله فعلت ما كان مني إليه من كبير وايم الله لأتعرضن له فإن عاد لأكفينكنه قال فغدوت في اليوم الثالث من رؤيا عاتكة وأنا حديد مغضب أرى أني قد فاتني منه أمر أحب أن أدركه منه قال فدخلت المسجد فرأيته فوالله إني لأمشي نحوه العرضنة ليعود لبعض ما كان فأوقع به وكان رجلا خفيفا حديد الوجه حديد اللسان حديد النظر إذ خرج نحو باب المسجد يشتد قال قلت في نفسي ماله لعنه الله أكل هذا فرقا أن أشاتمه فإذا هو قد سمع ما لم أسمع صوت ضمضم بن عمرو الغفاري وهو يصرخ ببطن الوادي واقفا على بعيره قد جدع بعيره وحول رحله وشق قميصه وهو يقول يا معشر قريش اللطيمة اللطيمة أموالكم مع أبي سفيان بن حرب قد عرض لها محمد في أصحابه لا أرى أن تدركوها الغوث الغوث قال فشغلني عنه وشغله عني ما جاء من الأمر قال فتجهز الناس سراعا وقالوا لا يظن محمد وأصحابه أن تكون كعير ابن","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":11,"spl":"أخبار غزاة بدر"},
{"id":"b35-24","bab":"الجزء 4","sec":"أخبار غزاة بدر","page":"ج4 ص176","text":"الحضرمي كلا والله ليعلمن غير ذلك فكانوا بين رجلين إما خارج وإما باعث مكانه رجلا وأوعبت قريش فلم يتخلف من أشرافها أحد إلا أبو لهب بن عبد المطلب تخلف فبعث مكانه العاصي بن هشام بن المغيرة وكان لط له بأربعة آلاف درهم كانت له عليه فأفلس بها فاستأجره بها على أن يجزئ عنه بعثه فخرج عنه وتخلف أبو لهب هكذا في الحديث فذكر أبو عبيدة وابن الكلبي إن أبا لهب قامر العاصي بن هشام في مائة من الإبل فقمره أبو لهب ثم عاد فقمره أيضا ثم عاد فقمره أيضا الثالثة فذهب بكل ما كان يملكه فقال له العاصي أرى القداح قد حالفتك يابن عبد المطلب هلم نجعلها على أينا يكون عبدا على لصاحبه قال ذلك لك فدحاها فقمره أبو لهب فأسلمه قينا وكان يأخذ منه ضريبة فلما كان يوم بدر وأخذت قريش كل من لم يخرج بإخراج رجل مكانه أخرجه أبو لهب عنه وشرط له العتق فخرج فقتله علي بن أبي طالب رضي الله عنه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":12,"spl":"أخبار غزاة بدر — جيش النبي"},
{"id":"b35-25","bab":"الجزء 4","sec":"رجع الحديث إلى وقعة بدر","page":"ج4 ص179","text":"قال محمد بن إسحاق وحدثني عبد الله بن أبي نجيح أن أمية بن خلف كان قد أجمع القعود وكان شيخا جليلا جسيما ثقيلا فجاءه عقبة بن أبي معيط وهو جالس في المسجد بين ظهراني قومه بمجمرة يحملها فيها نار ومجمر حتى وضعها بين يديه ثم قال يا أبي علي استجمر\nفإنما أنت من النساء قال قبحك الله وقبح ما جئت به ثم تجهز وخرج مع الناس فلما فرغوا من جهازهم وأجمعوا السير ذكروا ما كان بينهم وبين بني بكر بن عبد مناة بن كنانة من الحرب فقالوا إنا نخشى أن يأتوا من خلفنا قال محمد بن إسحاق فحدثني يزيد بن رومان عن عروة بن الزبير قال لما أجمعت قريش المسير ذكرت الذي بينها وبين بني بكر بن عبد مناة فكاد ذلك أن يثبطهم فتبدى لهم إبليس في صورة سراقة بن جعشم المدلجي وكان من أشراف بني كنانة فقال إني جار لكم من أن تأتيكم كنانة من خلفكم بشيء تكرهونه فخرجوا سراعا","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":12,"spl":"أخبار غزاة بدر — جيش النبي"},
{"id":"b35-26","bab":"الجزء 4","sec":"جيش النبي","page":"ج4 ص180","text":"وخرج رسول الله فيما بلغني عن غير ابن إسحاق لثلاث ليال خلون من شهر رمضان المعظم في ثلاثمائة وبضعة عشر رجلا من أصحابه فاختلف في مبلغ الزيادة على العشرة فقال بعضهم كانوا ثلاثمائة وثلاثة عشر رجلا وكان المهاجرون يوم بدر سبعة وسبعين رجلا وكان الأنصار مائتين وستة وثلاثين رجلا وكان صاحب راية رسول الله علي بن أبي طالب رضي الله عنه وكان صاحب راية الأنصار سعد بن عبادة\nحدثنا محمد قال حدثنا هارون بن إسحاق قال حدثنا مصعب بن المقدام قال أبو جعفر وحدثني محمد بن إسحاق الأهوازي قال حدثنا أبو أحمد الزبيري قال حدثنا إسرائيل قال حدثنا أبو إسحاق عن البراء قال كنا نتحدث أن عدة أصحاب بدر على عدة أصحاب طالوت الذين جازوا معه النهر ولم يجز معه إلا مؤمن ثلاثمائة وبضعة عشر","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":12,"spl":"أخبار غزاة بدر — جيش النبي"},
{"id":"b35-27","bab":"الجزء 4","sec":"تأييد الأنصار للنبي","page":"ج4 ص181","text":"قال ابن إسحاق في حديثه عمن روى عنه وخرج رسول الله في أصحابه وجعل على الساقة قيس بن أبي صعصعة أخا بني مازن بن النجار في ليال مضت من رمضان فسار حتى إذا كان قريبا من الصفراء بعث بسبس بن عمرو الجهني حليف بني ساعدة وعدي بن أبي الزغباء حليف بني النجار إلى بدر يتجسسان له الخبر عن أبي سفيان بن حرب وغيره ثم ارتحل رسول الله وقدمهما فلما استقبل الصفراء وهي قرية بين جبلين سأل عن جبليها ما اسماهما فقيل يقال لأحدهما هذا مسلح وللآخر هذا مخرىء وسأل عن أهلها فقالوا بنو النار وبنو حراق بطنان من غفار فكرههما رسول الله والمرور بينهما وتفاءل باسميهما وأسماء أهاليهما فتركهما والصفراء يسارا وسلك ذات اليمين على واد يقال له ذفران فخرج منه حتى إذا كان ببعضه نزل وأتاه الخبر عن قريش بمسيرهم ليمنعوا عيرهم فاستشار النبي الناس وأخبرهم عن قريش فقام أبو بكر فقال فأحسن ثم قام عمر فقال فأحسن ثم قام المقداد بن عمرو فقال يا رسول الله امض لما أمرك الله فنحن معك والله لا نقول لك كما قالت بنو إسرائيل لموسى اذهب أنت وربك فقاتلا إنا هاهنا\nقاعدون ولكن اذهب أنت وربك فقاتلا إنا معكما مقاتلون معلمون فوالذي بعثك بالحق لو سرت بنا إلى برك الغماد يغني مدينة الحبشة لجالدنا معك حتى تبلغه فقام رسول الله خيرا ودعا له بخير حدثنا محمد قال حدثنا محمد بن عبيد المحاربي قال حدثني إسماعيل بن إبراهيم أبو يحيى قال حدثنا المخارق عن طارق عن عبد الله بن مسعود قال شهدت من المقداد مشهدا لأن أكون صاحبه أحب إلي مما في الأرض من كل شيء كان رجلا فارسا وكان رسول الله إذا غضب احمارت وجنتاه فأتاه المقداد على تلك الحال فقال أبشر يا رسول الله فوالله لا نقول لك كما قالت بنو إسرائيل لموسى اذهب أنت وربك فقاتلا إنا هاهنا قاعدون لكن والذي بعثك بالحق لنكونن بين يديك ومن خلفك وعن يمينك وشمالك أو يفتح الله تبارك وتعالى","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":13,"spl":"تأييد الأنصار للنبي"},
{"id":"b35-28","bab":"الجزء 4","sec":"رجع الحديث إلى حديث ابن إسحاق","page":"ج4 ص182","text":"ثم قال رسول الله ( أشيروا علي أيها الناس\nوإنما يريد الأنصار وذلك أنهم كانوا عدد الناس وأنهم حين بايعوا بالعقبة قالوا يا رسول الله إنا براء من ذمامك حتى تصير إلى دارنا فإذا وصلت فأنت في ذمامنا نمنعك مما نمنع منه أنفسنا وأبناءنا ونساءنا فكان رسول الله يتخوف ألا تكون الأنصار ترى عليها نصرته إلا ممن دهمه بالمدينة من عدوه وأن ليس عليهم أن يسير بهم إلى عدو في غير بلادهم فلما قال ذلك رسول الله قال له سعد بن معاذ والله لكأنك تريدنا يا رسول الله قال ( أجل\nال فقد آمنا بك يا رسول الله وصدقناك وشهدنا أن ما جئت به هو الحق وأعطيناك على ذلك عهودنا ومواثيقنا على السمع والطاعة\nفامض بنا يا رسول الله لما أردت فنحن معك فوالذي بعثك بالحق لو استعرضت بنا هذا البحر وخضته لخضناه معك ما يتخلف منا رجل واحد وما نكره أن تلقى بنا عدوا غدا إنا لصبر عند الحرب صدق عند اللقاء لعل الله تعالى أن يريك منا ما تقر به عينك فسر بنا على بركة الله فسر رسول الله بقول سعد ونشطه ذلك ثم قال ( سيروا على بركة الله وأبشروا فإن الله قد وعدني إحدى الطائفتين والله لكأني أنظر إلى مصارع القوم\nثم ارتحل رسول الله من ذفران وسلك على ثنايا يقال لها الأصافر ثم انحط على بلد يقال لها الدبة ثم ترك الحنان بيمين وهو كثيب عظيم كالجبل ثم نزل قريبا من بدر فركب هو ورجل من أصحابه قال الطبري قال محمد بن إسحاق حدثني محمد بن يحيى بن حبان حتى وقف على شيخ من العرب فسأله عن قريش وعن محمد وأصحابه وما بلغه عنهم فقال الشيخ لا أخبركما حتى تخبراني ممن أنتما فقال له رسول الله ( إذا أخبرتنا أخبرناك\nقال أوذاك بذاك فقال ( نعم\nال الشيخ فإنه بلغني أن محمدا وأصحابه خرجوا يوم كذا وكذا فإن كان صدقني الذي أخبرني فهم اليوم بمكان كذا وكذا للمكان الذي به رسول الله وبلغني أن قريشا خرجوا يوم كذا وكذا فإن كان الذي حدثني صدقني فهم اليوم بمكان كذا وكذا للمكان الذي به قريش فلما فرغ من خبره قال\nممن أنتما فقال رسول الله ( نحن من ماء\nثم انصرف الشيخ عنه قال يقول الشيخ ما من ماء أمن ماء العراق ثم رجع رسول الله إلى أصحابه فلما أمسى بعث علي بن أبي طالب رضي الله عنه والزبير بن العوام وسعد بن أبي وقاص في نفر من أصحابه إلى بدر يلتمسون له الخبر عليه قال محمد بن إسحاق حدثني يزيد بن رومان عن عروة بن الزبير فأصابوا راوية لقريش فيها أسلم غلام بني الحجاج وعريض أبو يسار غلام بني العاصي بن سعيد فأتوا بهما رسول الله وهو يصلي فسألوهما فقالا نحن سقاة لقريش بعثونا نسقيهم من الماء فكره القوم خبرهما ورجوا أن يكونا لأبي سفيان فضربوهما فلما أذلقوهما قالا نحن لأبي سفيان فتركوهما وركع رسول الله وسجد سجدتين ثم سلم ثم قال ( إذا صدقاكم ضربتموهما فإذا كذباكم تركتموهما صدقا والله إنهما لقريش أخبراني أين قريش\nقالا هم وراء هذا الكثيب الذي ترى بالعدوة القصوى والكثيب العقنقل فقال لهما رسول الله كم القوم\nقالا لا ندري قال ( كم ينحرون كل يوم\nقالا يوما تسعا ويوما عشرا فقال رسول الله ( القوم ما بين التسعمائة والألف\nم قال لهما رسول الله ( فمن فيهم من أشراف قريش\nقالا عتبة بن ربيعة وشيبة بن ربيعة وأبو البختري بن هشام وحكيم بن حزام ونوفل بن خويلد والحارث بن عامر بن نوفل وطعيمة بن عدي والنضر بن الحارث وزمعة بن الأسود وأبو جهل بن هشام وأمية بن خلف ونبيه ومنبه ابن الحجاج وسهيل بن عمرو وعمرو بن ود فأقبل رسول الله على الناس فقال ( هذه مكة قد رمت إليكم أفلاذ كبدها\nقال ابن إسحاق وقد كان بسبس بن عمرو وعدي بن أبي الزغباء مضيا حتى","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":14,"spl":"رجع الحديث إلى حديث ابن إسحاق"},
{"id":"b35-29","bab":"الجزء 4","sec":"رجع الحديث إلى حديث ابن إسحاق","page":"ج4 ص182","text":"نزلا بدرا فأناخا إلى تل قريب من الماء ثم أخذا شنا يستسقيان فيه ومجدي بن عمرو الجهني على الماء فسمع عدي وبسبس جاريتين من جواري الحاضر وهما تتلازمان على الماء والملزومة تقول لصاحبتها إنما تأتي العير غدا أو بعد غد فأعمل لهم ثم أقضيك الذي لك قال مجدي صدقت ثم خلص بينهما وسمع ذلك عدي وبسبس فجلسا على بعيريهما ثم انطلقا حتى أتيا رسول الله فأخبراه بما سمعا وأقبل أبو سفيان قد تقدم العير حذرا حتى ورد الماء فقال لمجدي بن عمرو هل أحسست أحدا قال ما رأيت أحدا أنكره إلا أني رأيت راكبين أناخا إلى هذا التل ثم استقيا في شن لهما ثم انطلقا فأتى أبو سفيان مناخهما فأخذا من أبعار بعيريهما ففته فإذا فيه النوى فقال هذه والله علائف يثرب فرجع إلى أصحابه سريعا فصرف وجه عيره عن الطريق فساحل بها وترك بدرا يسارا ثم انطلق حتى أسرع وأقبلت قريش فلما نزلوا الجحفة رأى جهيم بن أبي الصلت بن مخرمة بن عبد المطلب بن عبد مناف رؤيا فقال إني رأيت فيما يرى النائم وإني لبين النائم واليقظان إذ نظرت إلى رجل أقبل على فرس ومعه بعير له ثم قال قتل عتبة بن ربيعة وشيبة بن ربيعة وأبو الحكم بن هشام وأمية بن خلف وفلان وفلان فعدد رجالا ممن قتل يومئذ من أشراف قريش ورأيته ضرب في لبة بعيره ثم أرسله في العسكر فما بقي خباء من أخبية العسكر إلا أصابه نضح من دمه قال فبلغت أبا جهل فقال وهذا أيضا نبي آخر من بني عبد المطلب سيعلم غدا من المقتول إن نحن التقينا ولما رأى أبو سفيان قد أحرز عيره أرسل إلى\nقريش إنكم إنما خرجتم لتمنعوا عيركم ورحالكم وأموالكم فقد نجاها الله فارجعوا فقال أبو جهل والله لا نرجع حتى نرد بدرا وكان بدر موسما من مواسم العرب تجتمع به لهم بها سوق كل عام فنقيم عليه ثلاثا وننحر الجزر ونطعم الطعام ونسقي الخمور وتعزف علينا القيان وتسمع بنا العرب بمسيرنا وجمعنا فلا يزالون يهابوننا أبدا فأمضوا فقال الأخنس بن شريق بن عمرو بن وهب الثقفي وكان حليفا لبني زهرة وهم بالجحفة يا بني زهرة قد نجى الله لكم عيركم وخلص لكم صاحبكم مخرمة بن نوفل وإنما نفرتم لتمنعوه وماله فاجعلوا بي جبنها وارجعوا فإنه لا حاجة بكم في أن تخرجوا في غير ضيعة لما يقول هذا يعني أبا جهل فلم يشهدها زهري وكان فيهم مطاعا ولم يكن بقي من قريش بطن إلا نفر منهم ناس إلا بني عدي بن كعب لم يخرج منهم رجل واحد فرجعت بنو زهرة مع الأخنس بن شريق فلم يشهد بدرا من هاتين القبيلتين أحد ومضى القوم وقد كان بين طالب بن أبي طالب وكان في القوم وبين بعض قريش محاورة فقالوا والله لقد عرفنا يا بني هاشم وإن خرجتم معنا أن هواكم لمع محمد فرجع طالب إلى مكة فيمن رجع وأما ابن الكلبي فإنه قال فيما حدثت عنه شخص طالب بن أبي طالب إلى بدر مع المشركين أخرج كرها فلم يوجد في الأسرى ولا في القتلى ولم يرجع إلى أهله وكان شاعرا وهو الذي يقول\n(يا رب إما يغزون طالب ... في مقنب من هذه المقانب)\n(فليكن المسلوب غير السالب ... وليكن المغلوب غير الغالب)\nجع الحديث إلى حديث ابن إسحاق قال ومضت قريش حتى نزلوا بالعدوة القصوى من الوادي خلف العقنقل وبطن الوادي وهو يليل بين بدر وبين العقنقل الكثيب الذي خلفه قريش\nوالقليب ببدر من العدوة الدنيا من بطن يليل إلى المدينة وبعث الله عز و جل السماء وكان الوادي دهسا فأصاب النبي وأصحابه منها ما لبد لهم الأرض ولم يمنعهم المسير وأصاب قريشا منها ما لم يقدروا على أن يرتحلوا معه فخرج رسول الله يبادرهم إلى الماء حتى حاذى ماء من مياه بدر فنزل به قال ابن إسحاق فحدثني عشرة رجال من بني سلمة ذكروا أن الحباب بن المنذر بن الجموح قال يا رسول الله أرأيت هذا المنزل أمنزل أنزلكه الله ليس لنا أن نتقدمه ولا نتأخر عنه أم هو الرأي والحرب والمكيدة قال ( بل هو الرأي والحرب والمكيدة\nفقال يا رسول الله إن هذا ليس لك بمنزل فانهض بالناس حتى تأتي أدنى ماء من مياه القوم فتنزله ثم تعور ما سواه من القلب ثم تبنى عليه حوضا فتملأه ماء ثم نقاتل القوم فنشرب ولا يشربوا فقال رسول الله ( لقد أشرت بالرأي\nنهض رسول الله ومن معه من الناس حتى أتى أدنى ماء من القوم فنزل عليه ثم أمر بالقلب فعورت وبنوا حوضا على القليب الذي نزل عليه فملىء ماء ثم قذفوا فيه الآنية","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":15,"spl":"رجع الحديث إلى حديث ابن إسحاق"},
{"id":"b35-30","bab":"الجزء 4","sec":"النبي يراقب من عريش بني له","page":"ج4 ص187","text":"قال محمد بن إسحاق فحدثني محمد بن أبي بكر أن سعد بن معاذ قال يا رسول الله نبني لك عريشا من جريد فتكون فيه ونعد عندك ركائبك ثم نلقى عدونا فإن نحن أعزنا الله وأظهرنا على عدونا كان ذلك ما أحببنا وإن كانت الأخرى جلست على ركائبك فلحقت بمن وراءنا من قومنا فقد تخلف عنك أقوام يا نبي الله ما نحن بأشد حبا لك منهم ولو ظنوا أنك تلقى حربا ما تخلفوا عنك يمنعك الله بهم يناصحونك ويجاهدون معك فأثنى عليه رسول الله\nخيرا ودعا له بخير ثم بني لرسول الله عريش فكان فيه وقد ارتحلت قريش حين أصبحت وأقبلت فلما رآها رسول الله تصوب من العقنقل وهو الكثيب الذي منه جاؤوا إلى الوادي قال ( اللهم هذي قريش قد أقبلت بخيلائها وفخرها تحادك وتكذب رسولك اللهم فنصرك الذي وعدتني اللهم فأحنهم الغداة وقد قال رسول الله ورأى عتبة بن ربيعة في القوم على جمل له أحمر ( إن يكن عند أحد من القوم خير فعند صاحب الجمل الأحمر إن يطيعوه يرشدوا\nقد كان خفاف بن إيماء بن رحضة الغفاري أو أبوه أيما بن رحضة بعث إلى قريش حين مروا به ابنا له بجزائر أهداها لهم وقال لهم إن أحببتم أن نمدكم بسلاح ورجال فعلنا فأرسلوا إليه مع ابنه أن وصلتك رحم فقد قضيت الذي عليك فلعمري لئن كنا إنما نقاتل الناس فما بنا ضعف عنهم ولئن كنا نقاتل الله كما يزعم محمد فما لأحد بالله من طاقة فلما نزل الناس أقبل نفر من قريش حتى وردوا الحوض حوض رسول الله فقال رسول الله ( دعوهم\nفما شرب منهم رجل إلى قتل يومئذ إلا ما كان من حكيم بن حزام فإنه لم يقتل نجا على فرس له يقال له الوجيه وأسلم بعد ذلك فحسن إسلامه فكان إذا اجتهد في يمينه قال والذي نجاني من يوم بدر قال محمد بن إسحاق وحدثني أبي إسحاق بن يسار وغيره من أهل العلم عن أشياخ من الأنصار قالوا لما اطمأن القوم بعثوا عمير بن وهب الجمحي فقالوا احزر لنا أصحاب محمد فاستجال بفرسه حول العسكر ثم رجع إليهم فقال ثلاثمائة رجل يزيدون قليلا أو ينقصونه ولكن أمهلوني حتى أنظر أللقوم كمين أو مدد قال فضرب في الوادي حتى أمعن فلم ير شيئا فرجع فقال لم أر شيئا ولكن قد\nرأيت يا معشر قريش الولايا تحمل المنايا نواضح يثرب تحمل الموت الناقع قوم ليس لهم منعة ولا ملجأ إلا سيوفهم والله ما أرى أن يقتل رجل منهم حتى يقتل رجلا منكم فإذا أصابوا منكم أعدادهم فما خير العيش بعد ذلك فروا رأيكم فلما سمع حكيم بن حزام ذلك مشى في الناس فأتى عتبة بن ربيعة وقال يا أبا الوليد إنك كبير قريش الليلة وسيدها والمطاع فيها هل لك إلى أمر لا تزال تذكر منه بخير إلى آخر الدهر قال وما ذاك يا حكيم قال ترجع بالناس وتحمل دم حليفك عمرو بن الحضرمي قال قد فعلت أنت على ذلك شهيد إنما هو حليفي فعلي عقله وما أصيب من ماله فأت ابن الحنظلية فإني لا أخشى أن يسحر الناس غيره يعني أبا جهل بن هشام حدثنا محمد قال حدثنا الزبير بن بكار قال حدثنا غمامة بن عمرو السهمي قال حدثنا مسور بن عبد الملك اليربوعي عن أبيه عن سعيد بن المسيب قال بينا نحن عند مروان بن الحكم إذ دخل عليه حاجبه فقال هذا أبو خالد حكيم بن حزام قال إيذن له فلما دخل حكيم بن حزام قال مرحبا بك يا أبا خالد أدن فحال له مروان عن صدر المجلس ختى كان بينه وبين الوسادة ثم استقبله مروان فقال حدثنا حديث بدر قال خرجنا حتى إذا نزلنا الجحفة رجعت قبيلة من قبائل قريش بأسرها فلم يشهد أحد من مشركيهم بدرا ثم خرجنا حتى نزلنا العدوة التي قال الله عز و جل فجئت عتبة بن ربيعة فقلت يا أبا الوليد هل لك أن تذهب بشرف هذا اليوم ما بقيت قال أفعل ماذا قال قلت إنكم لا تطلبون من محمد إلا دم واحد ابن الحضرمي وهو حليفك فتحمل","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":16,"spl":"النبي يراقب من عريش بني له"},
{"id":"b35-31","bab":"الجزء 4","sec":"النبي يراقب من عريش بني له","page":"ج4 ص187","text":"ديته فيرجع الناس قال أنت وذاك وأنا أتحمل ديته فاذهب إلى ابن الحنظلية يعني أبا جهل فقل له هل لك أن ترجع اليوم بمن معك عن ابن عمك فجئته فإذا هو في جماعة من بين يديه ومن ورائه فإذا ابن الحضرمي واقف على رأسه وهو يقول قد فسخت عقدي من بني عبد شمس وعقدي إلى بني مخزوم فقلت له يقول لك عتبة بن ربيعة هل لك أن ترجع اليوم عن ابن عمك بمن معك قال أما وجد رسولا غيرك قلت لا ولم أكن لأكون رسولا لغيره قال حكيم فخرج مبادرا إلى عتبة وخرجت معه لئلا يفوتني من الخبر شيء وعتبة يتكىء على إيماء بن رحضة الغفاري وقد أهدى إلى المشركين عشر جزائر فطلع أبو جهل والشر في وجهه فقال لعتبة انتفخ سحرك فقال عتبة فستعلم فسل أبو جهل سيفه فضرب به متن فرسه فقال إيماء بن رحضة بئس المقام هذا فعند ذلك قامت الحرب","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":17,"spl":"النبي يراقب من عريش بني له — رجع الحديث إلى ابن إسحاق"},
{"id":"b35-32","bab":"الجزء 4","sec":"رجع الحديث إلى ابن إسحاق","page":"ج4 ص190","text":"ثم قام عتبة بن ربيعة خطيبا فقال يا معشر قريش والله ما تصنعون بأن تلقوا محمدا وأصحابه شيئا والله لئن أصبتموه لا يزال الرجل منكم ينظر في وجه رجل يكره النظر إليه رجل قتل ابن عمه أو ابن خاله أو رجلا من عشيرته فارجعوا وخلوا بين محمد وبين سائر العرب فإن أصابوه فذلك الذي أردتم وإن كان غير ذلك ألفاكم ولم تعدموا منه ما تريدون قال حكيم فانطلقت حتى جئت أبا جهل فوجدته قد نثل درعا له من جرابها وهو يهيئها فقلت له يا أبا الحكم إن عتبة أرسلني إليك بكذا وكذا الذي قال فقال انتفخ والله سحره حين رأى محمدا وأصحابه كلا والله لا مرجع حتى يحكم الله بيننا وبين محمد وأصحابه وما بعتبة ما قال ولكنه قد رأى أن محمدا وأصحابه أكلة جزور وفيهم ابنه قد\nتخوفكم عليه ثم بعث إلى عامر بن الحضرمي فقال له هذا حليفك يريد أن يرجع بالناس وقد رأيت ثأرك بعينك فقم فانشد خفرتك ومقتل أخيك فقام عامر بن الحضرمي فاكتشف ثم صرخ واعمراه واعمراه فحميت الحرب وحقب أمر الناس واستوسقوا على ما هم عليه من الشر وأفسد على الناس الرأي الذي دعاهم إليه عتبة بن ربيعة ولما بلغ عتبة قول أبي جهل انتفخ سحره قال سيعلم مصفر الإست من انتفخ سحره أنا أم هو ثم التمس عتبة بيضة ليدخلها في رأسه فلم يجد في الجيش بيضة تسعه من عظم هامته فلما رأى ذلك اعتجر على رأسه ببرد له وقد خرج الأسود بن عبد الأسد المخزومي وكان رجلا شرسا سيىء الخلق فقال أعاهد الله لأشربن من حوضهم أو لأهدمنه أو لأموتن دونه فلما خرج وخرج له حمزة بن عبد المطلب فلما التقيا ضربه حمزة فأبان قدمه بنصف ساقه وهو دون الحوض فوقع على ظهره تشخب رجله دما نحو أصحابه ثم حبا إلى الحوض حتى اقتحم فيه يريد أن يبر يمينه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":17,"spl":"النبي يراقب من عريش بني له — رجع الحديث إلى ابن إسحاق"},
{"id":"b35-33","bab":"الجزء 4","sec":"مقتل بعض أعداء النبي","page":"ج4 ص191","text":"وأتبعه حمزة فضربه حتى قتله في الحوض ثم خرج بعده عتبة بن ربيعة بين أخيه شيبة بن ربيعة وابنه الوليد بن عتبة حتى إذا نصل من الصف دعا إلى المبارزة فخرج إليه فتية من الأنصار ثلاثة نفر وهم عوف ومعوذ ابنا الحارث وأمهما عفراء ورجل آخر يقال هو عبد الله بن رواحة فقالوا من أنتم قالوا\nرهط من الأنصار قالوا ما لنا بكم حاجة ثم نادى مناديهم يا محمد أخرج إلينا أكفاءنا من قومنا فقال رسول الله ( قم يا حمزة بن عبد المطلب قم يا عبيدة بن الحارث قم يا علي بن أبي طالب\nلما قاموا ودنوا منهم قالوا من أنتم فقال عبيدة عبيدة وقال حمزة حمزة وقال علي علي قالوا نعم أكفاء كرام فبارز عبيدة بن الحارث وكان أسن القوم عتبة بن ربيعة وبارز حمزة شيبة بن ربيعة وبارز علي الوليد بن عتبة فأما حمزة فلم يمهل شيبة أن قتله وأما علي فلم يمهل الوليد بن عتبة أن قتله واختلف عبيدة وعتبة بينهما بضربتين كلاهما أثبت صاحبه فكر حمزة وعلي على عتبة بأسيافهما فذففا عليه فقتلاه واحتملا صاحبهما عبيدة فجاءا به إلى أصحابه وقد قطعت رجله ومخه يسيل فلما أتوا بعبيدة إلى رسول الله قال ألست شهيدا يا رسول الله قال ( بلى\nفقال عبيدة لو كان أبو طالب حيا لعلم أني بما قال أحق منه حيث يقول\n(ونسلمه حتى نصرع حوله ... ونذهل عن أبنائنا والحلائل)\nال محمد بن إسحاق وحدثني عاصم بن عمر بن قتادة أن عتبة بن ربيعة قال للفتية من الأنصار حين انتسبوا له أكفاء كرام إنما نريد قومنا ثم تزاحف الناس ودنا بعضهم من بعض وقد أمر رسول الله أصحابه ألا يحملوا حتى يأمرهم وقال ( إن اكتنفكم القوم فانضحوهم بالنبل\nورسول الله في العريش معه أبو بكر وكانت وقعة بدر يوم الجمعة صبيحة سبع عشرة من شهر رمضان قال ابن إسحاق كما حدثني أبو جعفر محمد بن علي بن الحسين\nقال محمد بن جرير وحدثنا ابن حميد قال حدثنا سلمة قال قال لي محمد بن إسحاق حدثني حبان بن واسع بن حبان عن أشياخ من قومه أن رسول الله عدل صفوف أصحابه يوم بدر وفي يده قدح يعدل به القوم فمر بسواد بن غزية حليف بني عدي بن النجار وهو مستنتل من الصف فطعن رسول الله في بطنه بالقدح ثم قال ( استو يا سواد بن غزية\nفقال يا رسول الله أوجعتني وقد بعثك الله بالحق فأقدني قال فكشف رسول الله عن بطنه وقال ( استقد\nفاعتنقه وقبل بطنه فقال ( ما حملك على هذا يا سواد\nفقال يا رسول الله حضر ما ترى فلم آمن الموت فأردت أن يكون آخر العهد بك أن يمس جلدي جلدك فدعا له رسول الله بخير وقال له خيرا ثم عدل رسول الله الصفوف ورجع إلى العريش ودخله ومعه أبو بكر وليس معه غيره ورسول الله يناشد ربه ما وعده من النصر ويقول فيما يقول ( اللهم إن تهلك هذه العصابة اليوم يعني المسلمين لا تعبد بعد اليوم\nوأبو بكر يقول يا نبي الله خل بعض مناشدتك ربك فإن الله منجز لك ما وعدك حدثنا محمد بن جرير قال حدثنا محمد بن عبيد المحاربي قال حدثنا عبد الله بن المبارك عن عكرمة بن عمار قال حدثني سماك الحنفي قال سمعت ابن عباس يقول حدثني عمر بن الخطاب قال لما كان يوم بدر ونظر رسول الله إلى المشركين وعدتهم وإلى أصحابه وهم نيف على ثلاثمائة استقبل الكعبة وجعل يدعو ويقول ( اللهم أنجز لي ما وعدتني اللهم إن تهلك هذه العصابة من أهل الإسلام لا تبعد في الأرض\nفلم\nيزل كذلك حتى سقط رداؤه فأخذ أبو بكر فوضع رداءه عليه ثم التزمه من روائه فقال كفاك يا نبي الله بأبي أنت وأمي مناشدتك لربك سينجز لك ما وعدك فأنزل الله تعالى ( إذ تستغيثون ربكم فاستجاب لكم أني ممدكم بألف من الملائكة مردفين\nدثنا محمد قال حدثنا ابن وكيع قال حدثنا الثقفي يعني عبد الوهاب عن خالد عن عكرمة عن ابن عباس أن النبي قال وهو في قبته يوم بدر ( اللهم أسألك عهدك ووعدك اللهم إن شئت لم تعبد بعد اليوم\nال فأخذ أبو بكر بيده فقال حسبك يا نبي الله فقد ألححت على ربك وهو في الدرع فخرج وهو يقول ( سيهزم الجمع ويولون الدبر بل الساعة موعدهم والساعة أدهى وأمر","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":18,"spl":"مقتل بعض أعداء النبي"},
{"id":"b35-34","bab":"الجزء 4","sec":"رجع الحديث إلى حديث ابن إسحاق النبي يبشر بالنصر","page":"ج4 ص194","text":"قال وقد خفق رسول الله خفقه وهو في العريش ثم انتبه فقال ( يا أبا بكر أتاك نصر الله هذا جبريل آخذ بعنان فرسه يقوده وعلى ثناياه النقع\nال وقد رمي مهجع مولى عمر بن الخطاب بسهم فقتل فكان أول قتيل من المسلمين ثم رمي حارثة بن سراقة أحد بني عدي بن النجار وهو يشرب من الحوض بسهم فأصاب نحره فقتل ثم خرج رسول الله إلى الناس فحرضهم ونفل كل امرئ ما أصاب وقال ( والذي نفسي بيده لا يقاتلهم اليوم رجل فيقتل صابرا محتسبا مقبلا غير مدبر إلا أدخله الله الجنة\nقال عمير بن الحمام أخو بني سلمة وفي يده تمرات يأكلها بخ بخ أما بيني وبين أن أدخل\nالجنة إلا أن يقتلني هؤلاء قال ثم قذف التمرات من يده وأخذ سيفه فقاتل القوم حتى قتل وهو يقول\n(ركضا إلى الله بغير زاد ... إلا التقى وعمل المعاد)\n(والصبر في الله على الجهاد ... وكل زاد عرضة النفاد)\n(غير التقى والبر والرشاد ... )\nدثنا محمد بن جرير قال حدثنا ابن حميد قال حدثنا سلمة قال حدثنا محمد بن إسحاق عن عاصم بن عمر بن قتادة أن عوف بن الحارث وهو ابن عفراء قال يا رسول الله ما يضحك الرب من عبده قال غمسه يده في العدو حاسرا فنزع درعا كانت عليه فقذفها ثم أخذ سيفه فقاتل القوم حتى قتل","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":19,"spl":"رجع الحديث إلى حديث ابن إسحاق النبي يبشر بالنصر — هزيمة المشركين","partial":1},
{"id":"b35-35","bab":"الجزء 4","sec":"هزيمة المشركين","page":"ج4 ص195","text":"حدثنا محمد قال حدثنا ابن حميد قال حدثنا سلمة عن ابن إسحاق قال وحدثني محمد بن مسلم الزهري عن عبد الله بن ثعلبة بن صعير العذري حليف بني زهرة قال لما التقى الناس ودنا بعضهم من بعض قال أبو جهل اللهم أقطعنا للرحم وآتانا بما لا يعرف فأحنه الغداة فكان هو المستفتح على نفسه ثم إن رسول الله أخذ حفنة من الحصباء واستقبل بها قريشا ثم قال ( شاهت الوجوه\nثم نفحهم بها وقال لأصحابه ( شدوا\nفكانت الهزيمة فقتل الله من قتل من صناديد قريش وأسر من أسر منهم فلما وضع القوم أيديهم يأسرون ورسول الله في العريش وسعد بن معاذ قائم على باب العريش\nالذي فيه رسول الله متوشحا بالسيف في نفر من الأنصار يحرسون رسول الله يخافون عليه كرة العدو رأي رسول الله فيما ذكر لي في وجه سعد بن معاذ الكراهة فيما يصنع الناس فقال له ( كأنك كرهت ما يصنع الناس\nقال أجل يا رسول الله كانت أول وقعة أوقعها الله عز و جل بأهل الشرك فكان الإثخان في القتل أعجب إلي من استبقاء الرجال حدثنا محمد قال حدثنا ابن حميد قال حدثنا سلمة عن محمد بن إسحاق قال وحدثني العباس بن عبد الله بن معبد عن بعض أهله عن ابن عباس أن رسول الله قال لأصحابه يومئذ ( إني قد عرفت أن رجالا من بني هاشم وغيرهم قد أخرجوا كرها لا حاجة لهم بقتالنا فمن لقي منكم أحدا من بني هاشم فلا يقتله ومن لقي أبا البختري بن هشام بن الحارث فلا يقتله ومن لقي العباس بن عبد المطلب عم رسول الله فلا يقتله فإنما خرج مستكرها\nقال فقال أبو حذيفة بن عتبة بن ربيعة أيقتل آباؤنا وأبناؤنا وإخواننا وعشيرتنا ونترك العباس والله لئن لقيته لألحمنه السيف فبلغت رسول الله فجعل يقول لعمر بن الخطاب ( يا أبا حفص أما تسمع إلى قول أبي حذيفة يقول أضرب وجه عم رسول الله بالسيف\nقال عمر يا رسول الله دعني فلأضربن عنقه بالسيف فوالله لقد نافق قال عمر والله إنه لأول يوم كناني فيه رسول الله بأبي حفص","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":19,"spl":"رجع الحديث إلى حديث ابن إسحاق النبي يبشر بالنصر — هزيمة المشركين"},
{"id":"b35-36","bab":"الجزء 4","sec":"النبي ينهي عن قتل أبي البختري","page":"ج4 ص197","text":"قال فكان أبو حذيفة يقول ما أنا بآمن من تلك الكلمة التي قلت يومئذ ولا أزال منها خائفا إلا أن تكفرها عني الشهادة فقتل يوم اليمامة شهيدا قال وإنما نهى رسول الله عن قتل أبي البختري لأنه كان أكف القوم عن رسول الله وهو بمكة كان لا يؤذيه ولا يبلغه عنه بمكة شيء يكرهه وكان ممن قام في نقض الصحيفة التي كتبت قريش على بني هاشم وبني المطلب فلقيه المجذر بن ذياد البلوي حليف الأنصار من بني عدي فقال المجذر بن ذياد لأبي البختري إن رسول الله قد نهى عن قتلك ومع أبي البختري زميل له خرج معه من مكة وهو جنادة بن مليحة بن زهير بن الحارث بن أسد وجنادة رجل من بني ليث واسم أبي البختري العاصي بن هشام بن الحارث بن أسد قال وزميلي فقال المجذر لا والله ما نحن بتاركي زميلك ما أمرنا رسول الله إلا بك وحدك قال والله إذا لأموتن أنا وهو جميعا لا تتحدث عني نساء قريش بين أهل مكة أني تركت زميلي حرصا على الحياة فقال أبو البختري حين نازله المجذر وأبى إلا القتال وهو يرتجز\n(لن يسلم ابن حرة أكيله ... حتى يموت أو يرى سبيله)\nاقتتلا فقتله المجذر بن ذياد ثم أتى المجذر بن ذياد رسول الله فقال والذي بعثك بالحق لقد جهدت عليه أن يستأسر فآتيك به فأبى إلا القتال فقاتلته فقتلته قال محمد بن إسحاق وحدثني يحيى بن عباد بن عبد الله بن الزبير عن أبيه قال وحدثنيه أيضا عبد الله بن أبي بكر وغيرهما عن عبد الرحمن بن عوف قال\nكان أمية بن خلف لي صديقا بمكة قال وكان اسمي عبد عمرو فسميت حين أسلمت عبد الرحمن ونحن بمكة قال وكان يلقاني بمكة فيقول يا عبد عمرو أرغبت عن اسم سماك به أبواك فأقول نعم فيقول فإني لا أعرف الرحمن فاجعل بيني وبينك شيئا أدعوك به أما أنت فلا تجيبني باسمك الأول وأما أنا فلا أدعوك بما لا أعرف قال فكان إذا دعاني يا عبد عمرو لم أجبه فقلت اجعل بيني وبينك يا أبا علي ما شئت قال فأنت عبد الإله فقلت نعم قال فكنت إذا مررت به قال يا عبد الإله فأجيبه فأتحدث معه حتى إذا كان يوم بدر مررت به وهو واقف مع علي ابنه آخذا بيده ومعي أدراع قد سلبتها وأنا أحملها فلما رآني قال يا عبد عمرو فلم أجبه فقال يا عبد الإله قلت نعم قال هل لك في فأنا خير لك من هذه الأدراع قلت نعم هلم إذا فطرحت الأدراع من يدي وأخذت بيده وبيد ابنه علي وهو يقول ما رأيت كاليوم قط أما لكم حاجة في اللبن ثم خرجت أمشي بينهما قال ابن إسحاق وحدثني عبد الواحد بن أبي عون عن سعد بن إبراهيم بن عبد الرحمن عن أبيه عن عبد الرحمن بن عوف قال قال لي أمية بن خلف وأنا بينه وبين ابنه آخذ بأيديهما يا عبد الإله من الرجل المعلم منكم بريش نعامة في صدره قال قلت ذلك حمزة بن عبد المطلب قال ذلك الذي فعل بنا الأفاعيل قال عبد الرحمن فوالله إني لأقودهما إذ رآه بلال معي وكان هو الذي يعذب بلالا بمكة على أن يترك الإسلام\nفيخرجه إلى رمضاء مكة إذا حميت فيضجعه على ظهره ثم يأمر بالصخرة العظيمة فتوضع على صدره ثم يقول لا تزال هكذا حتى تفارق دين محمد فيقول بلال أحد أحد فقال بلال حين رآه رأس الكفر أمية بن خلف لا نجوت إن نجوا قال قلت أي بلال أبأسيري قال لا نجوت إن نجوا قلت أي بلال أبأسيري تسمع يابن السوداء قال لا نجوت إن نجوا ثم صرخ بأعلى صوته يا أنصار الله رأس الكفر أمية بن خلف لا نجوت إن نجوا قال فأحاطوا بنا حتى جعلونا في مثل المسكة وأنا أذب عنه قال فأخلف رجل السيف فضرب رجل ابنه فوقع وصاح أمية صيحة ما سمعت بمثلها قط قال قلت انج بنفسك ولا نجاء فوالله ما أغني عنك شيئا قال فهبروهما بأسيافهم حتى فرغوا منهما قال فكان عبد الرحمن يقول رحم الله بلالا ذهب بأدراعي وفجعني بأسيري","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":20,"spl":"النبي ينهي عن قتل أبي البختري"},
{"id":"b35-37","bab":"الجزء 4","sec":"الملائكة يؤازرون النبي في بدر","page":"ج4 ص199","text":"قال ابن إسحاق حدثني عبد الله بن أبي بكر أنه حدث عن ابن عباس قال حدثني رجل من بني غفار قال أقبلت أنا وابن عم لي حتى أصعدنا في جبل يشرف بنا على بدر ونحن مشركان ننتظر الوقعة على من تكون الدبرة فننهب مع من ينهب فبينا نحن في الجبل إذ دنت منا سحابة فسمعنا فيها حمحمة الخيل وسمعت قائلا يقول\nأقدم حيزوم قال فأما ابن عمي فانكشف قناع قلبه فمات مكانه وأما أنا فكدت أهلك ثم تماسكت قال محمد بن إسحاق حدثني أبي إسحاق بن يسار عن رجال من بني مازن بن النجار عن أبي داود المازني وكان شهد بدرا قال إني لأتبع رجلا من المشركين يوم بدر لأضربه إذ وقع رأسه قبل أن يصل إليه سيفي فعلمت أنه قد قتله غيري حدثنا محمد بن جرير قال حدثنا عبد الرحمن بن عبد الله بن الحكم المصري قال حدثنا يحيى بن بكير قال حدثني محمد بن إسحاق عن العلاء بن كثير عن أبي بكر بن عبد الرحمن بن المسور بن مخرمة عن أبي أمامة بن سهل بن حنيف قال قال لي أبي يا بني لقد رأيتنا يوم بدر وإن أحدنا ليشير إلى المشرك بسيفه فيقع رأسه عن جسده قبل أن يصل إليه السيف حدثنا محمد قال حدثنا ابن حميد قال حدثنا سلمة عن محمد قال وحدثني الحسن بن عمارة قال أخبرنا سلمة عن الحكم بن عتيبة عن مقسم مولى عبد الله بن الحارث عن عبد الله بن عباس قال كانت سيما الملائكة يوم بدر عمائم بيضا قد أرسلوها على ظهورهم ويوم حنين عمائم حمرا ولم نقاتل الملائكة في يوم من الأيام سوى يوم بدر وكانوا يكونون فيما سواه من الأيام مددا وعددا ولا يضربون حدثنا محمد قال حدثنا ابن حميد قال حدثنا سلمة قال قال محمد وحدثني\nثور بن زيد مولى بني الديل عن عكرمة مولى ابن عباس عن ابن عباس قال وحدثني عبد الله بن أبي بكر قالا كان معاذ بن عمرو بن الجموح أخو بني سلمة يقول لما فرغ رسول الله من غزوة بدر أمر بأبي جهل أن يلتمس في القتلى وقال ( اللهم لا يعجزنك\nكان أول من لقي أبا جهل معاذ بن عمرو بن الجموح قال سمعت القوم وأبو جهل في مثل الحرجة وهم يقولون أبو الحكم لا يخلص إليه فلما سمعتها جعلتها من شأني فعمدت نحوه فلما أمكنني حملت عليه فضربته ضربة أطنت قدمه بنصف ساقه فوالله ما شبهتها حين طاحت إلا كالنواة تطيح من تحت مرضخة النوى حين يضرب بها قال وضربني ابنه عكرمة على عاتقي فطرح يدي فتعلقت بجلدة من جنبي وأجهضني القتال عنها فلقد قاتلت عامة يومي وإني لأسحبها خلفي فلما أذتني جعلت عليها رجلي ثم تمطيت بها حتى طرحتها قال ثم عاش معاذ بعد ذلك حتى كان في زمن عثمان بن عفان قال ثم مر بأبي جهل وهو عقير معوذ بن عفراء فضربه حتى أثبته فتركه وبه رمق وقاتل معوذ حتى قتل فمر عبد الله ابن مسعود بأبي جهل حين أمر رسول الله أن يلتمس في القتلى وقال لهم رسول الله فيما بلغني ( انظروا إن خفي عليكم في القتلى إلى أثر جرح بركبته فإني ازدحمت أنا وهو يوما على مأدبة لعبد الله بن جدعان ونحن غلامان وكنت أشب أو أشف منه بيسير فدفعته فوقع على ركبتيه فخدش في إحداهما خدشا لم يزل أثره فيها بعد\nفقال عبد الله بن مسعود فوجدته بآخر رمق فعرفته\nفوضعت رجلي على عنقه قال وقد كان ضبث بي مرة بمكة فآذاني ولكزني ثم قلت هل أخزاك الله يا عدو الله قال وبماذا أخزاني أعمد من رجل قتلتموه لمن الدبرة اليوم قال قلت لله ولرسوله حدثنا محمد بن جرير قال حدثنا ابن حميد قال حدثنا سلمة عن محمد قال زعم رجال من بني مخزوم أن ابن مسعود كان يقول قال لي أبو جهل لقد ارتقيت يا رويعي الغنم مرتقى صعبا ثم احتززت رأسه ثم جئت به رسول الله فقلت يا رسول الله هذا رأس عدو الله أبي جهل فقال رسول الله ( الله الذي لا إله غيره\nوكانت يمين رسول الله قلت نعم والله الذي لا إله غيره ثم ألقيت رأسه بين يدي رسول الله قال فحمد الله","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":21,"spl":"الملائكة يؤازرون النبي في بدر"},
{"id":"b35-38","bab":"الجزء 4","sec":"النبي يكلم أصحاب القليب بعد موتهم","page":"ج4 ص202","text":"قال محمد بن إسحاق وحدثني يزيد بن رومان عن عروة بن الزبير عن عائشة قالت لما أمر رسول الله بالقتلى أن يطرحوا في القليب طرحوا فيها إلا ما كان من أمية بن خلف فإنه انتفخ في درعه فملأها فذهبوا به ليخرجوه فتزايل فأقروه وألقوا عليه ما غيبه من التراب والحجارة فلما ألقوهم في القليب وقف رسول الله فقال ( يأهل القليب هل وجدتم ما وعدكم ربكم حقا فإني وجدت ما وعدني ربي حقا\nقال له أصحابه يا رسول الله أتكلم قوما موتى قال ( لقد علموا أن ما وعدهم ربهم حق\nالت عائشة والناس يقولون لقد سمعوا ما قلت لهم وإنما قال رسول الله ( لقد علموا\nقال ابن إسحاق وحدثني حميد الطويل عن أنس بن مالك قال لما سمع أصحاب رسول الله وهو يقول من جوف الليل ( يأهل القليب يا عتبة بن ربيعة ويا شيبة بن ربيعة ويا أبا جهل بن هشام فعدد من كان منهم في القليب هل وجدتم ما وعدكم ربكم حقا فإني قد وجدت ما وعدني ربي حقا\nقال المسلمون يا رسول الله أتنادي قوما قد جيفوا فقال ( ما أنتم بأسمع لما أقول منهم ولكنهم لا يستطيعون أن يجيبوني\nال محمد بن إسحاق وحدثني بعض أهل العلم أن رسول الله يوم قال هذه المقالة قال ( يأهل القليب بئس عشيرة النبي كنتم لنبيكم كذبتموني وصدقني الناس وأخرجتموني وآواني الناس وقاتلتموني ونصرني الناس\nثم قال ( هل وجدتم ما وعدكم ربكم حقا\nللمقالة التي قالها ولما أمر بهم رسول الله أن يلقوا في القليب أخذ عتبة فسحب إلى القليب فنظر رسول الله فيما بلغني إلى وجه أبي حذيفة بن عتبة فإذا هو كئيب قد تغير فقال رسول الله ( يا أبا حذيفة لعلك قد دخلك من شأن أبيك شئ\nأو كما قال قال فقال لا والله يا رسول الله ما شككت في أبي ولا في مصرعه ولكنني كنت أعرف من أبي رأيا وفضلا وحلما فكنت أرجو أن يهديه الله إلى الإسلام فلما رأيت ما أصابه وذكرت ما مات عليه من الكفر بعد الذي كنت أرجو له أحزنني ذلك قال فدعا رسول الله بخير وقال له خيرا","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":22,"spl":"النبي يكلم أصحاب القليب بعد موتهم — اختلاف المسلمين على الفيء"},
{"id":"b35-39","bab":"الجزء 4","sec":"اختلاف المسلمين على الفيء","page":"ج4 ص203","text":"ثم إن رسول الله أمر بما في العسكر مما جمع الناس فجمع واختلف المسلمون فيه فقال من جمعه هو لنا وقد كان رسول الله نفل كل امرئ ما\nأصاب فقال الذين كانوا يقاتلون العدو ويطلبونهم لولا نحن ما أصبتموه لنحن شغلنا القوم عنكم حتى أصبتم ما أصبتم وقال الذين كانوا يحرسون رسول الله مخافة أن يخالف إليه العدو والله ما أنتم بأحق منا ولقد رأينا أن نقتل العدو إذ ولانا الله ومنحنا أكتافهم ولقد رأينا أن نأخذ المتاع حين لم يكن دونه من يمنعه ولكن خفنا على رسول الله كرة العدو فقمنا دونه فما أنتم بأحق به منا قال ابن إسحاق وحدثني عاصم بن عمر بن قتادة ويزيد بن رومان أن رسول الله جمع الأسارى من المشركين وكانوا أربعة وأربعين أسيرا وكان من القتلى مثل ذلك وفي الأسارى عقبة بن أبي معيط والنضر بن الحارث بن كلدة حتى إذا كان رسول الله بالصفراء قتل النضر بن الحارث بن كلدة قتله علي بن أبي طالب رضي الله عنه قال محمد بن إسحاق حدثني عبد الله بن أبي بكر عن يحيى بن عبد الله بن عبد الرحمن بن سعد بن زرارة قال قدم بالأسارى حين قدم بهم وسودة بنت زمعة زوج النبي عند آل عفراء في مناحتهم على عوف ومعوذ ابني عفراء وذلك قبل أن يضرب عليهن الحجاب قال تقول سودة والله لعبدهم إني لعندهم إذ أتينا فقيل هؤلاء الأسارى قد أتي بهم فرحت إلى بيتي ورسول الله فيه وإذا أبو يزيد سهيل بن عمرو في ناحية الحجرة مجموعة يداه إلى عنقه بحبل قالت فوالله ما ملكت نفسي حين رأيت أبا يزيد كذلك أن قلت يا أبا يزيد أعطيتم بأيديكم ألا متم كراما فوالله ما أنبهني إلا قول رسول الله من البيت ( يا سودة أعلى الله وعلى رسوله\nقالت فقلت يا رسول الله والذي بعثك بالحق ما ملكت نفسي حين رأيت أبا\nيزيد مجموعة يداه إلى عنقه بحبل أن قلت ما قلت قال محمد بن إسحاق وكان أول من قدم مكة بمصاب قريش الحيسمان بن عبد الله بن إياس بن ضبيعة بن رومان بن كعب بن عمرو الخزاعي قالوا ما وراءك قال قتل عتبة بن ربيعة وشيبة بن ربيعة وأبو الحكم بن هشام وأمية بن خلف وزمعة بن الأسود وأبو البختري بن هشام ونبيه ومنبه ابنا الحجاج قال فلما جعل يعدد أشراف قريش قال صفوان بن أمية وهو قاعد في الحجر والله إن يعقل هذا فسلوه عني قالوا ما فعل صفوان بن أمية قال هو ذلك جالس في الحجر وقد والله رأيت أباه وأخاه حين قتلا","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":22,"spl":"النبي يكلم أصحاب القليب بعد موتهم — اختلاف المسلمين على الفيء"},
{"id":"b35-40","bab":"الجزء 4","sec":"موت أبي لهب","page":"ج4 ص205","text":"قال محمد بن إسحاق حدثني حسين بن عبد الله بن عبيد الله بن عباس عن عكرمة مولى ابن عباس قال قال أبو رافع مولى رسول الله كنت غلاما للعباس بن عبد المطلب وكان الإسلام قد دخلنا أهل البيت فأسلم العباس وأسلمت أم الفضل وأسلمت وكان العباس يهاب قومه ويكره خلافهم وكان يكتم إسلامه وكان ذا مال كثير متفرق في قومه وكان أبو لهب عدو الله قد تخلف عن بدر وبعث مكانه العاصي بن هشام بن المغيرة وكذلك صنعوا لم يتخلف رجل إلا بعث مكانه رجلا فلما جاء الخبر عن مصاب أهل بدر من قريش كبته الله وأخزاه ووجدنا في أنفسنا قوة وعزا وكنت رجلا ضعيفا وكنت أعمل القداح انحتها في\nحجرة زمزم فوالله إني لجالس فيها أنحت القداح وعندي أم الفضل جالسة وقد سرنا ما جاءنا من الخبر إذ أقبل الفاسق أبو لهب يجر رجليه يسير حتى جلس على طنب الحجرة فكان ظهره إلى ظهري فبينا هو جالس إذ قال الناس هذا أبو سفيان بن الحارث بن عبد المطلب قد قدم فقال أبو لهب هلم إلي يابن أخي فعندك لعمري الخبر فجلس إليه والناس قيام عليه فقال يابن أخي أخبرني كيف كان أمر الناس قال لا شيء والله إن كان إلا أن لقيناهم فأبحناهم أكتافنا يقتلون ويأسرون كيف شاؤوا وايم الله مع ذلك ما لمت الناس لقينا رجالا بيضا على خيل بلق بين السماء والأرض ما تليق شيئا ولا يقوم لها شيء قال أبو رافع فرفعت طنب الحجرة بيدي ثم قلت تلك والله الملائكة فرفع أبو لهب يده فضرب وجهي ضربة شديدة قال فساورته فاحتملني فضرب بي الأرض ثم برك علي يضربني وكنت رجلا ضعيفا فقامت أم الفضل إلى عمود من عمد الحجرة فأخذته فضربته به ضربة فشجت في رأسه شجة منكرة وقالت أتستضعفه أن غاب عنه سيده فقام ذليلا فوالله ما عاش فيها إلا سبع ليال حتى رماه الله جل جلاله بالعدسة فقتلته فلقد تركه ابناه ليلتين أو ثلاثا لا يدفنانه حتى أنتن في بيته وكانت قريش تتقي العدسة كما يتقى الطاعون حتى قال لهما رجل من قريش ويحكما لا تستحييان أن أباكما قد أنتن في بيته لا تغيبانه فقالا نخشى هذه القرحة قال فانطلقا فأنا معكما فما غسلوه إلا قذفا بالماء عليه من بعيد ما يمسونه فاحتملوه فدفنوه بأعلى مكة على جدار وقذفوا عليه الحجارة حتى واروه","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":23,"spl":"موت أبي لهب"},
{"id":"b35-41","bab":"الجزء 4","sec":"النبي يتألم لأسر العباس","page":"ج4 ص206","text":"قال محمد بن إسحاق وحدثني العباس بن عبد الله بن معبد عن بعض أهله\nعن الحكم بن عتيبة عن ابن عباس قال لما أمسى القوم من يوم بدر والأسارى محبوسون في الوثاق بات رسول الله ساهرا أول ليلته فقال له أصحابه يا رسول الله ما لك لا تنام فقال ( سمعت تضور العباس في وثاقه\nفقاموا إلى العباس فأطلقوه فنام رسول الله قال ابن إسحاق وحدثني الحسن بن عمارة عن الحكم بن عتيبة عن ابن عباس قال كان الذي أسر العباس أبو اليسر كعب بن عمرو أخو بني سلمة وكان رجلا مجموعا وكان العباس رجلا جسيما فقال رسول الله لأبي اليسر ( كيف أسرت العباس يا أبا اليسر\nفقال يا رسول الله أعانني عليه رجل ما رأيته قبل ذلك ولا بعده هيئته كذا وكذا فقال رسول الله ( لقد أعانك عليه ملك كريم\nال ابن إسحاق عن الكلبي عن أبي صالح عن ابن عباس أن رسول الله قال للعباس بن عبد المطلب حين انتهي به إلى المدينة ( يا عباس افد نفسك وابن أخيك عقيل بن أبي طالب ونوفل بن الحارث وحليفك عتبة بن عمرو بن جحدم أخا بني الحارث بن فهر فإنك ذو مال\nقال يا رسول الله إني كنت مسلما ولكن القوم استكرهوني فقال ( الله أعلم بإسلامك إن يكن ما تذكر حقا فالله يجزيك به فأما ظاهر أمرك فقد كان علينا فافد نفسك\nكان رسول الله قد أخذ منه عشرين أوقية من ذهب فقال العباس يا رسول الله احسبها لي في فدائي قال ( لا ذلك شيء أعطاناه الله منك\nال فإنه ليس لي مال قال قال ( فأين المال الذي وضعته بمكة حين خرجت من عند أم الفضل بنت الحارث ليس معكما أحد ثم قلت لها إن أصبت\nفي سفرتي هذه فللفضل كذا ولعبد الله كذا ولقثم كذا ولعبيد الله كذا\nقال والذي بعثك بالحق ما علم هذا أحد غيري وغيرها وإني لأعلم أنك رسول الله ففدى العباس نفسه وابن أخيه وحليفه قال ابن إسحاق وحدثني يحيى بن عباد بن عبد الله بن الزبير عن أبيه عن عائشة قالت لما بعث أهل مكة في فداء أسراهم بعثت زينب بنت رسول الله في فداء أبي العاصي بن الربيع بمال وبعثت فيه بقلادة لها كانت خديجة أدخلتها بها على أبي العاصي حين بنى عليها فلما رآها رسول الله رق لها رقة شديدة وقال ( إن رأيتم أن تطلقوا لها أسيرها وتردوا عليها الذي لها فافعلوا\nفقالوا نعم يا رسول الله فأطلقوه وردوا عليها الذي لها قال ابن إسحاق حدثني يحيى بن عباد عن أبيه قال ناحت قريش على قتلاها ثم قالت لا تفعلوا فيبلع ذلك محمدا وأصحابه فيشمتوا بكم ولا تبعثوا في فداء أسراكم حتى تستأنوا بهم لا يتأرب عليكم محمد وأصحابه في الفداء قال وكان الأسود بن المطلب قد أصيب له ثلاثة من ولده زمعة وعقيل والحارث بنو الأسود وكان يحب أن يبكي على بنيه فبينا هو كذلك إذ سمع نائحة في الليل فقال لغلامه وقد ذهب بصره أنظر هل أحل النحيب وهل بكت قريش على قتلاها لعلي أبكي على أبي حكيمة يعني زمعة فإن جوفي قد احترق فلما رجع إليه الغلام قال إنما هي امرأة تبكي على بعير لها أضلته فذلك حين يقول الأسود\n(أتبكي أن أضل لها بعير ... ويمنعها البكاء من الهجود)\n(ولا تبكي على بكر ولكن ... على بدر تقاصرت الجدود)\n(على بدر سراة بني هصيص ... ومخزوم ورهط أبي الوليد)\n(وبكي إن بكيت على عقيل ... وبكي حارثا أسد الأسود)\n(وبكيهم ولا تسمي جميعا ... فما لأبي حكيمة من نديد)\n(ألا قد ساد بعدهم رجال ... ولولا يوم بدر لم يسودوا)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":24,"spl":"النبي يتألم لأسر العباس — ومما قيل في بدر من الشعر وغني به قول هند بنت عتبة ترثي أباها"},
{"id":"b35-42","bab":"الجزء 4","sec":"ومما قيل في بدر من الشعر وغني به قول هند بنت عتبة ترثي أباها","page":"ج4 ص209","text":"صوت\n(من حس لي الأخوين كالغصنين ... أو من راهما)\n(قرمان لا يتظالمان ... ولا يرام حماهما)\n(ويلي على أبوي والقبر ... الذي واراهما)\n(لا مثل كهلي في الكهول ... ولا فتى كفتاهما)\nكر الهشامي أن الغناء لابن سريج رمل وفي الكتاب الكبير المنسوب إلى إسحاق أنه للغريض وتمام هذه الأبيات\n(أسدان لا يتذللان ... ولا يرام حماهما)\n(رمحين خطيين في ... كبد السماء تراهما)\n(ما خلفا إذ ودعا ... في سودد شرواهما)\n(سادا بغير تكلف ... عفوا يفيض نداهما)","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":24,"spl":"النبي يتألم لأسر العباس — ومما قيل في بدر من الشعر وغني به قول هند بنت عتبة ترثي أباها"},
{"id":"b35-43","bab":"الجزء 4","sec":"هند بنت عتبة تعاظم الخنساء بعكاظ","page":"ج4 ص210","text":"أخبرني الحسن بن علي قال حدثني الحارث بن أبي أسامة قال حدثنا محمد ابن سعد عن الواقدي وأخبرني ابن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الواقدي عن عبد الرحمن بن أبي الزناد قال لما كانت وقعة بدر قتل فيها عتبة بن ربيعة وشيبة بن ربيعة والوليد بن عتبة فأقبلت هند بنت عتبة ترثيهم وبلغها تسويم الخنساء هودجها في الموسم ومعاظمتها العرب بمصيبتها بأبيها عمرو بن الشريد وأخويها صخر ومعاوية وأنها جعلت تشهد الموسم وتبكيهم وقد سومت هودجها براية وأنها تقول أنا أعظم العرب مصيبة وأن العرب قد عرفت لها بعض ذلك فلما أصيبت هند بما أصيبت به وبلغها ذلك قالت أنا أعظم من الخنساء مصيبة وأمرت بهودجها فسوم براية وشهدت الموسم بعكاظ وكانت سوقا يجتمع فيها العرب فقالت إقرنوا جملي بجمل الخنساء ففعلوا فلما أن دنت منها قالت لها الخنساء من أنت يا أخية قالت أنا هند بنت عتبة أعظم العرب مصيبة وقد بلغني أنك تعاظمين العرب بمصيبتك فبم تعاظمينهم فقالت الخنساء بعمرو بن الشريد وصخر ومعاوية ابني عمرو وبم تعاظمينهم أنت قالت بأبي عتبة بن ربيعة وعمي شيبة بن ربيعة وأخي الوليد قالت الخنساء أو سواء هم عندك ثم أنشدت تقول\n(أبكي أبي عمرا بعين غزيرة ... قليل إذا نام الخلي هجودها)\nصنوي لا أنسى معاوية الذي ... له من سراة الحرتين وفودها\n(وصخرا ومن ذا مثل صخر إذا غدا ... بساهمة الآطال قبا يقودها)\n(فذلك يا هند الرزية فاعلمي ... ونيران حرب حين شب وقودها)\nقالت هند تجيبها\n(أبكي عميد الأبطحين كليهما ... وحاميهما من كل باغ يريدها)\n(أبي عتبة الخيرات ويحك فاعلمي ... وشيبة والحامي الذمار وليدها)\n(أولئك آل المجد من آل غالب ... وفي العز منها حين ينمي عديدها)\nقالت لها أيضا يومئذ\n(من حس لي الأخوين كالغصنين ... أو من راهما)\nخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني بعض القرشيين قال قدم عبد الله بن جعفر على معاوية وافدا فدخل عليه إنسان ثم ذهب إلى معاوية فقال هذا ابن جعفر يشرب النبيذ ويسمع الغناء ويحرك رأسه عليه فجاء معاوية متغيرا حتى دخل على ابن جعفر وعزة الميلاء بين يديه كالشمس الطالعة في كواء البيت يضيء بها البيت تغنيه على عودها\n(تبلت فؤادك في الظلام خريدة ... تشفي الضجيع ببارد بسام)\nوبين يديه عس فقال ما هذا يا أبا جعفر قال أقسمت عليك يا أمير المؤمنين لتشربن منه فإذا عسل مجدوح بمسك وكافور فقال هذا طيب فما هذا الغناء قال هذا شعر حسان بن ثابت في الحارث بن هشام قال فهل تغني بغير هذا قال نعم بالشعر الذي يأتيك به الأعرابي الجافي الأذفر القبيح المنظر فيشافهك به فتعطيه عليه وآخذه أنا فأختار محاسنه ورقيق كلامه فأعطيه هذه الحسنة الوجه اللينة اللمس الطيبة الريح فترتله بهذا الصوت الحسن قال فما تحريكك رأسك قال أريحية أجدها إذا سمعت الغناء لو سئلت عندها لأعطيت ولو لقيت لأبليت فقال معاوية قبح الله قوما عرضوني لك ثم خرج وبعث إليه بصلة","topic":"أخبار حسان بن ثابت ونسبه","topicNo":35,"sp":25,"spl":"هند بنت عتبة تعاظم الخنساء بعكاظ"},
{"id":"b36-1","bab":"الجزء 4","sec":"صوت من المائة المختارة قصيدة عمر بن أبي ربيعة في نعم","page":"ج4 ص213","text":"(أيها القلب لا أراك تفيق ... طالما قد تعلقتك العلوق)\n(من يكن من هوى حبيب قريبا ... فأنا النازح البعيد السحيق)\n(قضي الحب بيننا فالتقينا ... وكلانا إلى اللقاء مشوق)\nلشعر في البيت الأول والثالث لعمر بن أبي ربيعة والبيت الثاني ليس له ولكن هكذا غني وليس هو أيضا مشاكلا لحكاية ما في البيت الثالث والغناء لبابويه الكوفي خفيف ثقيل أول وهذا الشعر يقوله عمر بن أبي ربيعة في امرأة من قريش يقال لها نعم كان كثير الذكر لها في شعره أخبرني بذلك محمد بن خلف بن المرزبان عن أبي عبد الله التميمي عن القحذمي والمدائني قال وهي التي يقول فيها\n(أمن آل نعم أنت غاد فمبكر ... )\nال وكانت تكنى أم بكر وهي من بني جمح وتمام هذه الأبيات على ما حكاه ابن المرزبان عمن ذكرت\n(فالتقينا ولم نخف ما لقينا ... ليلة الخيف والمنى قد تشوق)\n(وجرى بيننا فجدد وصلا ... قلب حول أريب رفيق)\n(لا تظني أن التراسل والبدل ... لكل النساء عندي يليق)\n(هل لك اليوم إن نأت أم بكر ... وتولت إلى عزاء طريق)\nخبرني محمد بن خلف بن المزربان قال حدثت عن محمد بن حميد عن عبد الله بن سوار القاضي عن بشر بن المفضل قال بلغ عمر بن أبي ربيعة أن نعما اغتسلت في غدير فأتاه فأقام عليه وما زال يشرب منه حتى جف أخبرني محمد بن خلف قال قال محمد بن حبيب الراوية بلغني أن نعما استقبلت عمر بن أبي ربيعة في المسجد الحرام وفي يدها خلوق من خلوق المسجد فمسحت به ثوبه ومضت وهي تضحك فقال عمر\n(أدخل الله رب موسى وعيسى ... جنة الخلد من ملاني خلوقا)\n(مسحته من كفها في قميصي ... حين طافت بالبيت مسحا رفيقا)\n(غضبت أن نظرت نحو نساء ... ليس يعرفنني سلكن طريقا)\n(وأرى بينهما وبين نساء ... كنت أهذي بهن بونا سحيقا)\nهذا البيت الأول مما عيب على عمر ومما غني فيه من تشبيب عمر بنعم هذه\nصوت\n(دين هذا القلب من نعم ... بسقام ليس كالسقم)\n(إن نعما أقصدت رجلا ... آمنا بالخيف إذ ترمي)\n(بشتيت نبته رتل ... طيب الأنياب والطعم)\n(وبوحف مائل رجل ... كعناقيد من الكرم)\nمنها صوت\n(خليلي اربعا وسلا ... بمغنى الحي قد مثلا)\n(بأعلى الواد عند البئر ... هيج عبرة سبلا)\n(وقد تغنى به نعم ... وكنت بوصلها جذلا)\n(ليالي لا نحب لنا ... بعيش قد مضى بدلا)\n(وتهوانا ونهواها ... ونعصي قول من عذلا)\n(وترسل في ملاطفة ... ونعمل نحوها الرسلا)\nناه الهذلي ولحنه من القدر الأوسط من الثقيل الأول بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن سريج لحنان رمل بالبنصر في مجراها عن إسحاق وخفيف ثقيل بالوسطى عن عمرو وفيها عن إسحاق ثاني ثقيل\nولسليم خفيف رمل جميعا عن الهشامي قال ويقال إن اللحن المنسوب إلى سليم لحكم الوادي ومنها من قصيدة أولها\n(لقد أرسلت نعم إلينا أن ائتنا ... فأحبب بها من مرسل متغضب)\nغني منها في قوله صوت\n(فقلت لجناد خذ السيف واشتمل ... عليه برفق وارقب الشمس تغرب)\n(وأسرج لي الدهماء واعجل بممطري ... ولا تعلمن حيا من الناس مذهبي)\n(فلما التقينا سلمت وتبسمت ... وقالت مقال المعرض المتجنب)\n(أمن أجل واش كاشح بنميمة ... مشى بيننا صدقته لم تكذب)\n(وقطعت حبل الوصل منا ومن يطع ... بذي وده قول المؤرش يعتب)\nصوت\n(ما بال أهلك يا رباب ... خزرا كأنهم غضاب)\n(إن زرت أهلك أوعدوا ... وتهر دونهم الكلاب)\nروضه من الكامل الشعر لعلس ذي جدن الحميري أخبرنا بذلك محمد ابن الحسن بن دريد عن عمه عن العباس بن هشام عن أبيه والغناء لطويس ولحنه المختار خفيف رمل بالبنصر","topic":"نسب علس ذي جدن وأخباره","topicNo":36,"sp":0,"spl":"صوت من المائة المختارة قصيدة عمر بن أبي ربيعة في نعم — نسب علس ذي جدن وأخباره","partialRef":{"sid":"b2-8","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b36-2","bab":"الجزء 4","sec":"نسب علس ذي جدن وأخباره","page":"ج4 ص216","text":"هو علس بن زيد بن الحارث بن زيد بن الغوث بن سعد بن عوف بن عدي بن مالك بن زيد الجمهور بن سهل بن عمرو بن قيس بن معاوية بن جشم بن عبد شمس بن وائل بن الغوث بن قطن بن عريب بن زهير بن أعز بن الهم بن الهميسع بن حمير بن سبأ بن يشجب بن يعرب بن قحطان وهو ملك من ملوك حمير ولقب ذا جدن لحسن صوته والجدن الصوت بلغتهم ويقال إنه أول من تغنى باليمن أخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي وأبي مسكين قالا إنما سمي ذا جدن لحسن صوته أخبرني أحمد بن عبيد الله بن عمار قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن ابن الكلبي عن إسماعيل بن إبراهيم بن ذي الشعار الهمداني عن حيان بن هانئ الأرحبي عن أبيه قال","topic":"نسب علس ذي جدن وأخباره","topicNo":36,"sp":0,"spl":"صوت من المائة المختارة قصيدة عمر بن أبي ربيعة في نعم — نسب علس ذي جدن وأخباره"},
{"id":"b36-3","bab":"الجزء 4","sec":"ماذا كتب على قبره","page":"ج4 ص217","text":"أخبرني رجل من أهل صنعاء أنهم حفروا حفيرا في زمن مروان فوقفوا على أزج له باب فإذا هو برجل على سرير كأعظم ما يكون من الرجال عليه خاتم من ذهب وعصابة من ذهب وعند رأسه لوح من ذهب مكتوب فيه أنا\nعلس ذو جدن القيل لخليلي مني النيل ولعدوي مني الويل طلبت فأدركت وأنا ابن مائة سنة من عمري وكانت الوحش تأذن لصوتي وهذا سيفي ذو الكف عندي ودرعي ذات الفروج ورمحي الهزبري وقوسي الفجواء وقرني ذات الشر فيها ثلاثمائة حشر من صنعة ذي نمر أعددت ذلك لدفع الموت عني فخانني قال فنظرنا فإذا جميع ذلك عنده ووجدت هذا الخبر عن ابن الكلبي في بعض الكتب من غير رواية ابن عمار فوجدت فيه فإذا طول السيف اثنا عشر شبرا وعليه مكتوب تحت شاربه بالمسند باست امرئ كنت في يده فلم ينتصر انقضت أخباره","topic":"نسب علس ذي جدن وأخباره","topicNo":36,"sp":1,"spl":"ماذا كتب على قبره"},
{"id":"b37-2","bab":"الجزء 4","sec":"أخبار طويس ونسبه — تغنى بشعر ذي جدن","page":"ج4 ص218 – ج4 ص219","text":"طويس لقب واسمه طاوس مولى بني مخزوم وهو أول من غنى الغناء المتقن من المخنثين وهو أول من صنع الهزج والرمل في الإسلام وكان يقال أحسن الناس غناء في الثقيل ابن محرز وفي الرمل ابن سريج وفي الهزج طويس وكان الناس يضربون به المثل فيقال أهزج من طويس أخبرني محمد بن مزيد بن أبي الأزهر والحسين بن يحيى قالا حدثنا حماد ابن إسحاق عن أبيه عن ابن الكلبي عن أبيه وأبي مسكين قال إسحاق وحدثني المدائني والهيثم بن عدي عن صالح بن كيسان\nأن أبان بن عثمان وفد على عبد الملك بن مروان فأمره على الحجاز فأقبل حتى إذا دنا من المدينة تلقاه أهلها وخرج إليه أشرافها فخرج معهم طويس فلما رآه سلم عليه ثم قال له أيها الأمير إني كنت أعطيت الله عهدا لئن رأيتك أميرا لأخضبن يدي إلى المرفقين ثم أزدو بالدف بين يديك ثم أبدى عن دفه وتغنى بشعر ذي جدن الحميري\n(ما بال أهلك يا رباب ... خزرا كأنهم غضاب)\nقال فطرب أبان حتى كاد أن يطير ثم جعل يقول له حسبك يا طاوس\nولا يقول له يا طويس لنبله في عينه ثم قال له اجلس فجلس فقال له أبان قد زعموا أنك كافر فقال جعلت فداءك والله إني لأشهد أن لا إله إلا الله وأن محمدا رسول الله وأصلي الخمس وأصوم شهر رمضان وأحج البيت فقال أفأنت أكبر أم عمرو بن عثمان وكان عمرو أخا أبان لأبيه وأمه فقال له طويس أنا والله جعلت فداءك مع جلائل نساء قومي أمسك بذيولهن يوم زفت أمك المباركة إلى أبيك الطيب قال فاستحيا أبان ورمى بطرفه إلى الأرض وأخبرني بهذه القصة إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثنا العتبي عن أبيه بمثل هذه القصة عن أبان وطويس وزاد فيها أن طويسا قال له نذري أيها الأمير قال وما نذرك قال نذرت إن رأيتك أميرا في هذه الدار أن أغني لك وأزدو بدفي بين يديك فقال له أوف بنذرك فإن الله عز و جل يقول ( يوفون بالنذر\nقال فأخرج يديه مخضوبتين وأخرج دفه وتغنى\n(ما بال أهلك يا رباب ... )\nزاد فيه فقال له أبان يقولون إنك مشؤوم قال وفوق ذلك قال وما بلغ من شؤمك قال ولدت ليلة قبض النبي وفطمت ليلة مات أبو بكر رضي الله عنه واحتلمت ليلة قتل عمر رضوان الله عليه وزفت إلي أهلي ليلة قتل عثمان رضي الله عنه قال فاخرج عني عليك الدبار","topic":"أخبار طويس ونسبه","topicNo":37,"sp":0,"spl":"أخبار طويس ونسبه — تغنى بشعر ذي جدن","partialRef":{"sid":"b36-1","gi":8,"vi":0,"side":0},"partial":1},
{"id":"b37-3","bab":"الجزء 4","sec":"يحيى بن الحكم يهدر دمه مع المخنثين","page":"ج4 ص220","text":"أخبرني إسماعيل قال حدثنا عمر بن شبة قال حدثنا محمد بن الوليد قال حدثني مصعب بن عثمان عن نوفل بن عمارة قال خرج يحيى بن الحكم وهو أمير على المدينة فبصر بشخص بالسبخة\nمما يلي مسجد الأحزاب فلما نظر إلى يحيى بن الحكم جلس فاستراب به فوجه أعوانه في طلبه فأتي به كأنه امرأة في ثياب مصبغة مصقولة وهو ممتشط مختضب فقال له أعوانه هذا ابن نغاش المخنث فقال له ما أحسبك تقرأ من كتاب الله عز و جل شيئا إقرأ أم القرآن فقال يا أبانا لو عرفت أمهن عرفت البنات فقال له أتتهزأ بالقرآن لا أم لك وأمر به فضربت عنقه وصاح في المخنثين من جاء بواحد منهم فله ثلاثمائة درهم قال زرجون المخنث فخرجت بعد ذلك أريد العالية فإذا بصوت دف أعجبني فدنوت من الباب حتى فهمت نغمات قوم آنس بهم ففتحته ودخلت فإذا بطويس قائم في يده الدف يتغنى فلما رآني قال لي إيه يا زرجون قتل يحيى بن الحكم ابن نغاش قلت نعم قال وجعل في المخنثين ثلاثمائة درهم قلت نعم فادفع يغني\n(ما بال أهلك يا رباب ... خزرا كأنهم غضاب)\n(إن زرت أهلك أوعدوا ... وتهر دونهم كلاب)\nم قال ويحك أفما جعل في زيادة ولا فضلني عليهم في الجعل بفضلي شيئا أخبرني محمد بن عمرو العتابي قال حدثنا محمد بن خلف بن المرزبان ولم أسمعه أنا من محمد بن خلف قال حدثني إسحاق بن محمد بن أبان الكوفي قال حدثني حسين بن دحمان الأشقر قال كنت بالمدينة فخلا لي الطريق وسط النهار فجعلت أتغنى\n(ما بال أهلك يا رباب ... خزرا كأنهم غضاب)\nقال فإذا خوخة قد فتحت وإذا وجه قد بدا تتبعه لحية حمراء فقال يا فاسق أسأت التأدية ومنعت القائلة وأذعت الفاحشة ثم اندفع يغنيه فظننت أن طويسا قد نشر بعينه فقلت له أصلحك الله من أين لك هذا الغناء فقال نشأت وأنا غلام حدث أتبع المغنين وآخذ عنهم فقالت لي أمي يا بني إن المغني إذا كان قبيح الوجه لم يلتفت إلى غنائه فدع الغناء واطلب الفقه فإنه لا يضر معه قبح الوجه فتركت المغنين واتبعت الفقهاء فبلغ الله بي عز و جل ما ترى فقلت له فأعد جعلت فداءك قال لا ولا كرامة أتريد أن تقول أخذته عن مالك بن أنس وإذا هو مالك بن أنس ولم أعلم","topic":"أخبار طويس ونسبه","topicNo":37,"sp":1,"spl":"يحيى بن الحكم يهدر دمه مع المخنثين — حديث النبي عن انخساف الأرض"},
{"id":"b37-4","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص221","text":"(لمن ربع بذات الجيش ... أمسى دارسا خلقا)\n(وقفت به أسائله ... ومرت عيسهم حزقا)\n(علوا بك ظاهر البيداء ... والمخزون قد قلقا)\nات الجيش موضع ذكر النبي أن جيشا يغزو الكعبة فيخسف بهم إلا رجلا واحدا يقلب وجهه إلى قفاه فيرجع إلى قومه كذلك فيخبرهم الخبر حدثني بهذا الحديث أحمد بن محمد الجعدي قال حدثنا محمد بن بكار قال حدثنا إسماعيل بن زكريا عن محمد بن سوقة قال سمعت نافع بن جبير بن مطعم يقول حدثتني عائشة قالت","topic":"أخبار طويس ونسبه","topicNo":37,"sp":1,"spl":"يحيى بن الحكم يهدر دمه مع المخنثين — حديث النبي عن انخساف الأرض"},
{"id":"b37-5","bab":"الجزء 4","sec":"حديث النبي عن انخساف الأرض","page":"ج4 ص222","text":"قال رسول الله ( يغزو جيش الكعبة حتى إذا كانوا ببيداء من الأرض\nخسف بأولهم وآخرهم\nقالت عائشة فقلت يا رسول الله كيف يخسف بأولهم وآخرهم وفيهم سواهم ومن ليس منهم قال ( يخسف بأولهم وآخرهم ثم يبعثون على قدر نياتهم\nالشعر للأحوص والغناء في هذا اللحن المختار للدلال المخنث وهو أحد من خصاه ابن حزم بأمر الوليد بن عبد الملك مع المخنثين والخبر في ذلك يذكر بعد ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى البنصر في الأول والثالث ولإسحاق فيه ثقيل أول آخر وفيه لمالك لحن من خفيف الرمل عن يونس والهشامي وغيرهما وفيه رمل ينسب إلى ابن سريج وهو مما يشك في نسبته إليه وقيل إن خفيف الرمل لابن سريج والرمل لمالك وذكر حبش أن فيه للدلال خفيف ثقيل بالبنصر أيضا","topic":"أخبار طويس ونسبه","topicNo":37,"sp":1,"spl":"يحيى بن الحكم يهدر دمه مع المخنثين — حديث النبي عن انخساف الأرض"},
{"id":"b38-1","bab":"الجزء 4","sec":"ذكر الأحوص وأخباره ونسبه","page":"ج4 ص223","text":"هو الأحوص وقيل إن اسمه عبد الله وإنه لقب الأحوص لحوص كان في عيينه وهو ابن محمد بن عبد الله بن عاصم بن ثابت بن أبي الأقلح واسم أبي الأقلح قيس بن عصيمة بن النعمان بن أمية بن ضبيعة بن زيد بن مالك ابن عوف بن عمر بن عوف بن مالك بن الأوس وكان يقال لبني ضبيعة بن زيد في الجاهلية بنو كسر الذهب وقال الأحوص حين نفي إلى اليمن\n(بدل الدهر من ضبيعة عكا ... جيرة وهو يعقب الأبدالا)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":0,"spl":"ذكر الأحوص وأخباره ونسبه — خبر جده عاصم حمي الدبر"},
{"id":"b38-2","bab":"الجزء 4","sec":"خبر جده عاصم حمي الدبر","page":"ج4 ص224","text":"وكان جده عاصم يقال له حمي الدبر وكان رسول الله بعثه بعثا فقتله المشركون وأرادوا أن يصلبوه فحمته الدبر وهي النحل فلم يقدروا عليه حتى بعث الله عز و جل الوادي في الليل فاحتمله فذهب به وفي ذلك يقول الأحوص مفتخرا\n(وأنا ابن الذي حمت لحمه الدبر ... قتيل اللحيان يوم الرجيع)\nدثنا بالخبر في ذلك محمد بن جرير الطبري قال حدثنا ابن حميد قال\nحدثنا سلمة بن الفضل قال حدثنا محمد بن إسحاق عن عاصم بن عمر بن قتادة قال قدم على رسول الله بعد أحد رهط من عضل والقارة فقالوا يا رسول الله إن فينا إسلاما وخيرا فابعث معنا نفرا من أصحابك يفقهونا في الدين ويقرئونا القرآن ويعلمونا شرائع الإسلام فبعث رسول الله معهم نفرا من ستة من أصحابه مرثد بن أبي مرثد الغنوي حليف حمزة بن عبد المطلب وخالد بن البكير حليف بني عدي بن كعب وعاصم بن ثابت بن أبي الأقلح أخا بني عمرو ابن عوف وخبيب بن عدي أخا بني جحجبى بن كلفة بن عمرو بن عوف وزيد ابن الدثنة أخا بني بياضة بن عامر وعبد الله بن طارق حليفا لبني ظفر من بلي وأمر رسول الله عليهم مرثد بن أبي مرثد فخرجوا مع القوم حتى إذا كانوا على الرجيع ماء لهذيل بناحية من الحجاز من صدر الهدأة غدروا بهم واستصرخوا عليهم هذيلا فلم يرع القوم وهم في رحالهم إلا بالرجال في أيديهم السيوف قد غشوهم فأخذوا أسيافهم ليقاتلوا القوم فقالوا إنا والله ما نريد قتلكم ولكنا نريد أن نصيب بكم شيئا من أهل مكة ولكم عهد الله وميثاقه ألا نقتلكم فأما مرثد ابن أبي مرثد وخالد بن البكير وعاصم بن ثابت بن أبي الأقلح فقالوا إنا والله لا نقبل من مشرك عهدا ولا عقدا أبدا فقاتلوهم حتى قتلوهم جميعا وأما زيد بن الدثنة وخبيب بن عدي وعبد الله بن طارق فلانوا ورقوا ورغبوا في الحياة وأعطوا بأيديهم فأسروهم ثم خرجوا بهم إلى مكة ليبيعوهم بها حتى إذا\nكانوا بالظهران انتزع عبد الله بن طارق يده من القرآن ثم أخذ سيفه واستأخر عن القوم فرموه بالحجارة حتى قتلوه فقبره بالظهران وأما خبيب بن عدي وزيد ابن الدثنة فقدموا بهما مكة فباعوهما فابتاع خبيبا حجير بن أبي إهاب التميمي حليف بني نوفل لعقبة بن الحارث بن عامر بن نوفل وكان حجير أخا الحارث بن عامر بن نوفل لأمه ليقتله بأبيه وأما زيد بن الدثنة فابتاعه صفوان بن أمية ليقتله بأمية بن خلف أبيه وقد كانت هذيل حين قتل عاصم بن ثابت قد أرادوا رأسه ليبيعوه من سلافة بنت سعد بن شهيد وكانت قد نذرت حين قتل عاصم ابنها يوم أحد لئن قدرت على رأس عاصم لتشربن في قحفه الخمر فمنعته الدبر فلما حالت بينهم وبينه قالوا دعوه حتى يمسي فتذهب عنه فنأخذه فبعث الله عز و جل الوادي فاحتمل عاصما فذهب به وكان عاصم قد أعطى الله عز و جل عهدا لا يمسه مشرك أبدا ولا يمس مشركا أبدا تنجسا منه فكان عمر بن الخطاب رضي الله عنه يقول حين بلغه أن الدبر منعته عجبا لحفظ الله عز و جل العبد المؤمن كان عاصم نذر ألا يمسه مشرك ولا يمس مشركا أبدا في حياته فمنعه الله بعد مماته كما امتنع منه في حياته قال محمد بن جرير وأما غير ابن إسحاق فإنه قص من خبر هذه السرية غير الذي قصه غيره من ذلك ما حدثنا أبو كريب قال حدثنا جعفر بن عون العمري قال حدثنا إبراهيم بن إسماعيل عن عمر أو عمرو بن أسيد عن أبي هريرة أن رسول الله بعث عشرة رهط وأمر عليهم عاصم بن ثابت بن أبي الأقلح فخرجوا حتى إذا كانوا بالهدأة ذكروا لحي من هذيل يقال لهم بنو","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":0,"spl":"ذكر الأحوص وأخباره ونسبه — خبر جده عاصم حمي الدبر"},
{"id":"b38-3","bab":"الجزء 4","sec":"خبر جده عاصم حمي الدبر","page":"ج4 ص224","text":"لحيان فبعثوا إليهم مائة رجل راميا فوجدوا مأكلهم حيث أكلوا التمر فقالوا نوى يثرب ثم اتبعوا آثارهم حتى إذا أحس بهم عاصم وأصحابه التجأوا إلى الجبل وأحاط بهم الآخرون فاستنزلوهم وأعطوهم العهد فقال عاصم والله لا أنزل على عهد كافر اللهم أخبر نبيك عنا ونزل إليهم ابن الدثنة البياضي وخبيب ورجل آخر فأطلق القوم أوتار قسيهم ثم أوثقوهم فجرحوا رجلا من الثلاثة فقال هذا والله أول الغدر والله لا أتبعكم فضربوه وقتلوه وانطلقوا بخبيب وابن الدثنة إلى مكة فدفعوا خبيبا إلى بني الحارث بن عامر بن نوفل بن عبد مناف وكان خبيب هو الذي قتل الحارث بأحد فبينما خبيب عند بنات الحارث استعار من إحدى بنات الحارث موسى ليستحد بها للقتل فما راع المرأة ولها صبي يدرج إلا خبيب قد أجلس الصبي على فخذه والموسى بيده فصاحت المرأة فقال خبيب أتحسبين أني أقتله إن الغدر ليس من شأننا قال فقالت المرأة بعد ما رأيت أسيرا قط خيرا من خبيب لقد أريته وما بمكة من ثمرة وإن في يده لقطفا من عنب يأكله إن كان إلا رزقا رزقه الله خبيبا وبعث حي من قيس إلى عاصم ليؤتوا من لحمه بشيء وقد كان عاصم فيهم آثار بأحد فبعث الله عليه دبرا فحمت لحمه فلم يستطيعوا أن يأخذوا من لحمه شيئا فلما خرجوا بخبيب من الحرم ليقتلوه قال ذروني أصل ركعتين فتركوه فصلى ركعتين فجرت سنة لمن قتل صبرا يصلي ركعتين ثم قال لولا أن يقال جزع لزدت وما أبالي\n(على أي شق كان لله مصرعي ... )\nم قال\n(وذلك في ذات الإله وإن يشأ ... يبارك على أوصال شلو ممزع)\nاللهم أحصهم عددا وخذهم بددا ثم خرج به أبو سروعة بن الحارث بن عامر بن نوفل بن عبد مناف فضربه فقتله حدثنا محمد قال حدثنا أبو كريب قال حدثنا جعفر بن عون عن إبراهيم بن إسماعيل قال وأخبرني جعفر بن عمرو بن أمية عن أبيه عن جده أن رسول الله بعثه وحده عينا إلى قريش قال فجئت إلى خشبة خبيب وأنا أتخوف العيون فرقيت فيها فحللت خبيبا فوقع إلى الأرض فانتبذت غير بعيد ثم التفت فلم أر لخبيب أثرا فكأنما الأرض ابتلعته فلم تظهر لخبيب رمة حتى الساعة قال محمد بن جرير وأما زيد بن الدثنة فإن صفوان بن أمية بعث به فيما حدثنا ابن حميد قال حدثنا سلمة عن ابن إسحاق مع مولى له يقال له نسطاس إلى التنعيم فأخرجه من الحرم ليقتله واجتمع إليه رهط من قريش فيهم أبو سفيان بن حرب فقال له أبو سفيان حين قدم ليقتل أنشدك الله يا زيد أتحب أن محمدا عندنا الآن مكانك فتضرب عنقه وأنك في أهلك فقال والله ما أحب أن محمدا الآن في مكانه الذي هو فيه تصبيه شوكة تؤذيه وأنا جالس في أهلي قال يقول أبو سفيان ما رأيت من الناس أحدا يحب أحدا كحب أصحاب محمد محمدا ثم قتله نسطاس أخبرني أحمد بن الجعد قال حدثنا محمد بن إسحاق المسيبي قال حدثنا محمد بن فليح عن موسى بن عقبة عن ابن شهاب قال\nنزل عبد الله وأبو أحمد ابنا جحش حين قدما مهاجرين على عاصم بن ثابت وكنيته أبو سليمان وقال عاصم\n(أبو سليمان وريش المقعد ... وهجنا من جلد ثور أجرد)\nذكر لنا الحرمي بن أبي العلاء عن الزبير أن عاصما فيما قيل كان يكنى أبا سفيان قال وقال في يوم الرجيع\n(أنا أبو سفيان مثلي راما ... أضرب كبش العارض القداما)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":1,"spl":"خبر جده عاصم حمي الدبر — ماذا قال الفرزدق في شعر الأحوص","partial":1},
{"id":"b38-4","bab":"الجزء 4","sec":"بعض صفات الأحوص","page":"ج4 ص229","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثنا إسماعيل بن عبد الله عن إسماعيل بن إبراهيم بن عقبة عن عمه قال كنية الأحوص أبو محمد وأمه أثيلة بنت عمير بن مخشي وكان أحمر أحوص العينين","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":1,"spl":"خبر جده عاصم حمي الدبر — ماذا قال الفرزدق في شعر الأحوص"},
{"id":"b38-5","bab":"الجزء 4","sec":"ماذا قال الفرزدق في شعر الأحوص","page":"ج4 ص229","text":"قال الزبير فحدثني محمد بن يحيى قال قدم الفرزدق المدينة ثم خرج منها فسئل عن شعرائها فقال رأيت بها شاعرين وعجبت لهما أحدهما أخضر يسكن خارجا من بطحان يريد ابن هرمة والآخر أحمر كأنه وحرة على برودة في شعره يريد الأحوص والوحرة يعسوب أحمر ينزل الأنبار وقال الأحوص يهجو نفسه ويذكر حوصه\n(أقبح به من ولد وأشقح ... مثل جري الكلب لم يفقح)\n(إن ير سوءا لم يقم فينبح ... بالباب عند حاجة المستفتح)\nال الزبير ولم يبق للأحوص من ولده غير رجلين","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":1,"spl":"خبر جده عاصم حمي الدبر — ماذا قال الفرزدق في شعر الأحوص"},
{"id":"b38-6","bab":"الجزء 4","sec":"رأي أبي الفرج فيه","page":"ج4 ص230","text":"قال الزبير وجعل محمد بن سلام الأحوص وابن قيس الرقيات ونصيبا وجميل بن معمر طبقة سادسة من شعراء الإسلام وجعله بعد ابن\nقيس وبعد نصيب قال أبو الفرج والأحوص لولا ما وضع به نفسه من دنيء الأخلاق والأفعال أشد تقدما منهم عند جماعة أهل الحجاز وأكثر الرواة وهو أسمح طبعا وأسهل كلاما وأصح معنى منهم ولشعره رونق وديباجة صافية وحلاوة وعذوبة ألفاظ ليست لواحد منهم وكان قليل المروءة والدين هجاء للناس مأبونا فيما يروى عنه أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني أبو عبيدة أن جماعة من أهل المدينة أخبروه أن السبب في جلد سليمان بن عبد الملك أو الوليد بن عبد الملك إياه ونفيه له أن شهودا شهدوا عليه عنده أنه قال إذا أخذت جريري لم أبال أي الثلاثة لقيت ناكحا أو منكوحا أو زانيا قالوا وانضاف إلى ذلك أن سكينة بنت الحسين رضي الله عنهما فخرت يوما برسول الله ففاخرها بقصيدته التي يقول فيها\n(ليس جهل أتيته ببديع ... )\nزاده ذلك حنقا عليه وغيظا حتى نفاه","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":2,"spl":"رأي أبي الفرج فيه — تعرضه للخبازين وجلده من قبل عامل المدينة","partial":1},
{"id":"b38-7","bab":"الجزء 4","sec":"مفاخرته لسكينة بنت الحسين","page":"ج4 ص231","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة\nأن الأحوص كان يوما عند سكينة فأذن المؤذن فلما قال أشهد أن لا إله إلا الله أشهد أن محمدا رسول الله فخرت سكينة بما سمعت فقال الأحوص\n(فخرت وانتمت فقلت ذريني ... ليس جهل أتيته ببديع)\n(فأنا ابن الذي حمت لحمه الدبر ... قتيل اللحيان يوم الرجيع)\n(غسلت خالي الملائكة الأبرار ... ميتا طوبى له من صريع)\nال أبو زيد وقد لعمري فخر بفخر لو على غير سكينة فخر به وبأبي سكينة حمت أباه الدبر وغسلت خاله الملائكة أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن يحيى عن أيوب بن عمر عن أبيه قال لما جاء ابن حزم عمله من قبل سليمان بن عبد الملك على المدينة والحج جاءه ابن أبي جهم بن حذيفة وحميد بن عبد الرحمن بن عوف وسراقة فدخلوا عليه فقالوا له إيه يا بن حزم ما الذي جاء بك قال استعملني والله أمير المؤمنين على المدينة على رغم أنف من رغم أنفه فقال له ابن أبي جهم يا بن حزم فإني أول من يرغم من ذلك أنفه قال فقال ابن حزم صادق والله يحب الصادقين فقال الأحوص\n(سليمان إذ ولاك ربك حكمنا ... وسلطاننا فاحكم إذا قلت واعدل)\n(يؤم حجيج المسلمين ابن فرتنى ... فهب ذاك حجا ليس بالمتقبل)\nقال ابن أبي عتيق للأحوص الحمد لله يا أحوص إذ لم أحج ذلك العام بنعمة ربي وشكره قال الحمد لله الذي صرف ذلك عنك يا بن أبي بكر\nالصديق فلم يضلل دينك ولم تعن نفسك وترما يغيظك ويغيظ المسلمين معك","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":2,"spl":"رأي أبي الفرج فيه — تعرضه للخبازين وجلده من قبل عامل المدينة"},
{"id":"b38-8","bab":"الجزء 4","sec":"تعرضه للخبازين وجلده من قبل عامل المدينة","page":"ج4 ص233","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله عن عمه موسى بن عبد العزيز قال وفد الأحوص على الوليد بن عبد الملك وامتدحه فأنزله منزلا وأمر بمطبخه أن يمال عليه ونزل على الوليد بن عبد الملك شعيب بن عبد الله بن عمرو بن العاصي فكان الأحوص يراود وصفاء للوليد خبازين عن أنفسهم ويريدهم أن يفعلوا به وكان شعيب قد غضب على مولى له ونحاه فلما خاف الأحوص أن يفتضح بمراودته الغلمان اندس لمولى شعيب ذلك فقال ادخل على أمير المؤمنين فاذكر له أن شعيبا أرادك عن نفسك ففعل المولى فالتفت الوليد إلى شعيب فقال ما يقول هذا فقال لكلامه غورا يا أمير المؤمنين فاشدد به يدك يصدقك فشدد عليه فقال أمرني بذلك الأحوص فقال قيم الخبازين أصلحك الله إن الأحوص يراود الخبازين عن أنفسهم فأرسل به الوليد إلى ابن حزم بالمدينة وأمره أن يجلده مائة ويصب على رأسه زيتا ويقيمه على البلس ففعل ذلك به فقال وهو على البلس أبياته التي يقول فيها\n(ما من مصيبة نكبة أمنى بها ... إلا تشرفني وترفع شاني)\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني أيوب بن عمر قال أخبرني عبد الله بن عمران بن أبي فروة قال رأيت الأحوص حين وقفه ابن حزم على البلس في سوق المدينة وإنه ليصيح ويقول\n(ما من مصيبة نكبة أمنى بها ... إلا تعظمني وترفع شاني)\n(وتزول حين تزول عن متخمط ... تخشى بوادره على الأقران)\n(إني إذا خفي اللئام رأيتني ... كالشمس لا تخفى بكل مكان)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":2,"spl":"رأي أبي الفرج فيه — تعرضه للخبازين وجلده من قبل عامل المدينة"},
{"id":"b38-9","bab":"الجزء 4","sec":"هجاؤه لابن حزم","page":"ج4 ص234","text":"قال وهجا الأحوص ابن حزم بشعر كثير منه\n(أقول وأبصرت ابن حزم بن فرتنى ... وقوفا له بالمأزمين القبائل)\n(ترى فرتنى كانت بما بلغ ابنها ... مصدقة لو قال ذلك قائل)\nخبرني الحرمي قال حدثنا الزبير عن أبي عبيدة قال كل أمة يقال لها فرتنى وأخبرنا أبو خليفة عن محمد بن سلام قال فرتنى الأمة بنت الأمة قال الزبير فقال ابن حزم حين سمع قول الأحوص فيه ابن فرتنى لرجل من قومه له علم أنحن من ولد فرتنى أو تعرفها فقال لا والله قال ولا أنا أعلم والله ذلك ولقد عضهني به ولو كانت ولدتني لم أجهل ذلك قال الزبير وحدثني عمي مصعب عن عبد الله بن محمد بن عمارة قال\nفرتنى أم لهم في الجاهلية من بلقين كانوا يسبون بها لا أدري ما أمرها قد طرحوها من كتاب النسب وهي أم خالد بنت خالد بن سنان بن وهب ابن لوذان الساعدية أم بني حزم أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الملك بن عبد العزيز عن يوسف بن الماجشون أن الأحوص قال لابن حزم\n(لعمري لقد أجرى ابن حزم بن فرتنى ... إلى غاية فيها السمام المثمل)\n(وقد قلت مهلا آل حزم بن فرتنى ... ففي ظلمنا صاب ممر وحنظل)\nهي طويلة وقال أيضا\n(أهوى أمية إن شطت وإن قربت ... يوما وأهدي لها نصحي وأشعاري)\n(ولو وردت عليها الفيض ما حفلت ... ولا شفت عطشي من مائه الجاري)\n(لا تأوين لحزمي رأيت به ... ضرا ولو طرح الحزمي في النار)\n(الناخسين بمروان بذي خشب ... والمقحمين على عثمان في الدار)\nخبرنا الحرمي قال حدثنا الزبير قال حدثني جماعة من مشايخ الأنصار\nإن ابن حزم لما جلد الأحوص ووقفه على البلس يضربه جاءه بنو زريق فدفعوا عنه واحتملوه من أعلى البلس فقال في ذلك قال ابن الزبير أنشدنيه عبد الملك بن الماجشون عن يوسف بن أبي سلمة الماجشون\n(إما تصبني المنايا وهي لاحقة ... وكل جنب له قد حم مضطجع)\n(فقد جزيت بني حزم بظلمهم ... وقد جزيت زريقا بالذي صنعوا)\n(قوم أبى طبع الأخلاق أولهم ... فهم على ذاك من أخلاقهم طبعوا)\n(وإن أناس ونوا عن كل مكرمة ... وضاق باعهم عن وسعهم وسعوا)\n(إني رأيت غداة السوق محضرهم ... إذ نحن ننظر ما يتلى ونستمع)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":3,"spl":"هجاؤه لابن حزم — شعره بعد أن نفي إلى دهلك"},
{"id":"b38-10","bab":"الجزء 4","sec":"شعره بعد أن نفي إلى دهلك","page":"ج4 ص236","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن أبي بكر المؤملي قال حدثني غير واحد من أهل العلم أن أبا بكر بن محمد بن عمرو بن حزم جلد الأحوص في الخنث وطاف به وغربه إلى دهلك في محمل عريانا فقال الأحوص وهو يطاف به\n(ما من مصيبة نكبة أبلى بها ... )\n237 - الأبيات وزاد فيها\n(إني على ما قد ترون محسد ... أنمى على البغضاء والشنآن)\n(أصبحت للأنصار فيما نابهم ... خلفا وللشعراء من حسان)\nال الزبير ومما ضرب فيه أيضا قوله\n(شر الحزاميين ذو السين منهم ... وخير الحزامين يعدله الكلب)\n(فإن جئت شيخا من حزام وجدته ... من النوك والتقصير ليس له قلب)\n(فلو سبني عون إذا لسببته ... بشعري أو بعض الألى جدهم كعب)\nون يعني عون بن محمد بن علي بن أبي طالب عليه رضوان الله وكعب يعني كعب بن لؤي\n(أولئك أكفاء لبيتي بيوتهم ... ولا تستوي الأعلاث والأقدح القضب)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني محمد بن ثابت الأنصاري عن محمد بن فضالة قال كان الأحوص بن محمد الأنصاري قد أوسع قومه هجاء فملاهم شرا فلم يبق له فيهم صديق إلا فتى من بين جحجبى فلما أراد الأحوص الخروج إلى يزيد بن عبد الملك نهض الفتى في جهازه وقام بحوائجه وشيعه فلما كان بسقاية سليمان وركب الأحوص محمله أقبل على الفتى فقال لا أخلف الله عليك بخير فقال مه غفر الله لك قال الأحوص لا والله أو أعلقها حربا يعني قباء وبني عمرو بن عوف","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":3,"spl":"هجاؤه لابن حزم — شعره بعد أن نفي إلى دهلك","partial":1},
{"id":"b38-11","bab":"الجزء 4","sec":"هجوه بعض خصومه","page":"ج4 ص238","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني محمد بن يحيى قال قال غسان بن عبد الحميد أقبل الأحوص حتى وقف على معن بن حميد الأنصاري أحد بني عمرو ابن عوف بن جحجبى فقال\n(رأيتك مزهوا كأن أباكم ... صهيبة أمسى خير عوف مركبا)\n(تقربكم كوثى إذا ما نسبتم ... وتنكركم عمر بن عوف بن جحجبى)\n(عليك بأدنى الخطب إن أنت نلته ... وأقصر فلا يذهب بك التيه مذهبا)\nقام إليه بنوه ومواليه فقال دعوا الكلب خلوا عنه لا يمسه أحد منكم فانصرف حتى إذا كان عند أحجار المراء بقباء لقيه ابن أبي جرير أحد بني العجلان وكان شديدا ضابطا فقال له الأحوص\n(إن بقوم سودوك لحاجة ... إلى سيد لو يظفرون بسيد)\nألقى ثيابه وأخذ بحلق الأحوص ومع الأحوص راويته وجاء الناس ليخلصوه فحلف لئن خلصه أحد من يديه ليأخذنه وليدعن الأحوص فخنقه حتى استرخى وتركه حتى أفاق ثم قال له كل مملوك لي حر لئن سمع أو سمعت هذا البيت من أحد من الناس لأضربنك ضربة بسيفي أريد بها نفسك ولو كنت تحت أستار الكعبة فأقبل الأحوص على راويته فقال إن هذا مجنون ولم يسمع هذا البيت غيرك فإياك أن يسمعه منك خلق أخبرني الحرمي والطوسي قالا حدثنا الزبير بن بكار قال حدثني بعض أصحابنا\nأن الأحوص مر بعباد بن حمزة بن عبد الله بن الزبير ومحمد بن مصعب بن الزبير بخيمتي أم معبد وهما يريدان الحج مرجعه من عند يزيد بن عبد الملك وهو على نجيب له فاره ورحل فاخر وبزة مرتفعة فحدثهما أنه قدم على يزيد بن عبد الملك فأجازه وكساه وأخدمه فلم يرهما يهشان لذلك فجعل يقول خيمتي أم معبد عباد ومحمد كأنه يروض القوافي للشعر يريد قوله فقال له محمد بن مصعب إني أراك في تهيئة شعر وقواف وأراك تريد أن تهجونا وكل مملوك لي حر لئن هجوتنا بشيء إن لم أضربك بالسيف مجتهدا على نفسك فقال الأحوص جعلني الله فداك إني أخاف أن تسمع هذا في عدوا فيقول شعرا يهجوكما به فينحلنيه وأنا أبرئكما الساعة كل مملوك لي حر إن هجوتكما ببيت شعر أبدا أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي مصعب قال حدثنا الزبير ابن خبيب عن أبيه خبيب بن ثابت قال خرجنا مع محمد بن عباد بن عبد الله بن الزبير إلى العمرة فإنا لبقرب قديد إذ لحقنا الأحوص الشاعر على جمل برحل فقال الحمد لله الذي وفقكم\nلي ما أحب أنكم غيركم وما زلت أحرك في آثاركم مذ رفعتم لي فقد ازددت بكم غبطة فأقبل عليه محمد وكان صاحب جد يكره الباطل وأهله فقال لكنا والله ما اغتبطنا بك ولا نحب مسايرتك فتقدم عنا أو تأخر فقال والله ما رأيت كاليوم جوابا قال هو ذاك قال وكان محمد صاحب جد يكره الباطل وأهله فأشفقنا مما صنع ومعه عدة من آل الزبير فلم يقدر أحد منهم أن يرد عليه قال وتقدم الأحوص ولم يكن لي شأن غير أن أعتذر إليه فلما هبطنا من المشلل على خيمتي أم معبد سمعت الأحوص يهمهم بشيء فتفهمته فإذا هو يقول خيمتي أم معبد محمد كأنه يهيء القوافي فأمسكت راحلتي حتى جاءني محمد فقلت إني سمعت هذا يهيء لك القوافي فإما أذنت لنا أن نعتذر إليه ونرضيه وإما خليت بيننا وبينه فنضربه فإنا لا نصادفه في أخلى من هذا المكان قال كلا إن سعد بن مصعب قد أخذ عليه ألا يهجو زبيريا أبدا فإن فعل رجوت أن يخزيه الله دعه قال الزبير وأما خبره مع سعد بن مصعب فحدثني به عمي مصعب قال أخبرني يحيى بن الزبير بن عباد أو مصعب بن عثمان شك أيهما حدثه قال كانت أمة الملك بنت حمزة بن عبد الله بن الزبير تحت سعد بن مصعب ابن الزبير وكان فيهم مأتم فاتهمته بامرأة فغارت عليه وفضحته فقال الأحوص يمازحه\n(وليس بسعد النار من تزعمونه ... ولكن سعد النار سعد بن مصعب)\n(ألم تر أن القوم ليلة نوحهم ... بغوه فألفوه على شر مركب)\n(فما يبتغي بالغي لا در دره ... وفي بيته مثل الغزال المربب)\nال وسعد النار رجل يقال له سعد حضنة وهو الذي جدد لزياد بن عبيد الله الحارثي الكتاب الذي في جدار المسجد وهو آيات من القرآن أحسب أن منها ( إن الله يأمر بالعدل والإحسان وإيتاء ذي القربى وينهى عن الفحشاء والمنكر والبغي","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":4,"spl":"هجوه بعض خصومه"},
{"id":"b38-12","bab":"الجزء 4","sec":"هجوه بعض خصومه","page":"ج4 ص238","text":"لما فرغ منه قال لزياد أعطني أجري فقال له زياد انتظر فإذا رأيتنا نعمل بما كتبت فخذ أجرك قال فعمل سعد بن مصعب سفرة وقال للأحوص اذهب بنا إلى سد عبيد الله بن عمر نتغد عليه ونشرب من مائه ونستنقع فيه فذهب معه فلما صارا إلى الماء أمر غلمانه أن يربطوه وأراد ضربه وقال ما جزعت من هجائك إياي ولكن ما ذكرك زوجتي فقال له يا سعد إنك لتعلم أنك إن ضربتني لم أكفف عن الهجاء ولكن خير لك من ذلك أحلف لك بما يرضيك ألا أهجوك ولا أحدا من آل الزبير أبدا فأحلفه وتركه أخبرني الحرمي قال حدثنا الزبير قال حدثني مصعب عمي عن مصعب بن عثمان قال قال الأحوص لمجمع بن يزيد بن جارية\n(وجمعت من أشياء شتى خبيثة ... فسميت لما جئت منها مجمعا)\nقال له مجمع إني لا أحسن الشعر ثم أخذ كرنافة فغمسها في ماء فغاصت ثم رفع يده عنها فطفت فقال هكذا والله كانت تصنع خالاتك السواحر\nأخبرني الحرمي قال حدثنا الزبير قال كانت امرأة يقال لها أم ليث امرأة صدق فكانت قد فتحت بينها وببن جارة لها من الأنصار خوخة وكانت الأنصارية من أجمل أنصارية خلقت فكلم الأحوص أم ليث أن تدخله في بيتها يكلم الأنصارية من الخوخة التي فتحت بينها وبينها فأبت فقال أما لأكافئنك ثم قال\n(هيهات منك بنو عمر ومسكنهم ... إذا تشتيت قنسرين أو حلبا)\n(قامت تراءى وقد جد الرحيل بنا ... بين السقيفة والباب الذي نقبا)\n(إني لمانحها ودي ومتخذ ... بأم ليث إلى معروفها سببا)\nلما بلغت الأبيات زوج المرأة سد الخوخة فاعتذرت إليه أم ليث فأبى أن يقبل ويصدقها فكانت أم ليث تدعو على الأحوص أخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة قال حدثني أبي قال ركب الأحوص إلى الوليد بن عبد الملك قبل ضرب ابن حزم إياه فلقيه رجل من بني مخزوم يقال له محمد بن عتبة فوعده أن يعينه فلما دخل على الوليد قال ويحك ما هذا الذي رميت به يا أحوص قال والله يا أمير المؤمنين لو كان الذي رماني به ابن حزم من أمر الدين لاجتنبته فكيف وهو من أكبر معاصي الله فقال ابن عتبة يا أمير المؤمنين إن من فضل ابن حزم وعدله كذا وكذا وأثنى عليه فقال الأحوص هذا والله كما قال الشاعر\n(وكنت كذئب السوء لما رأى دما ... بصاحبه يوما أحال على الدم)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":5,"spl":"هجوه بعض خصومه"},
{"id":"b38-13","bab":"الجزء 4","sec":"رفض عمر بن عبد العزيز أن يأذن له بالقدوم","page":"ج4 ص243","text":"فأما خبره في بقية أيام سليمان بن عبد الملك وعمر بن عبد العزيز فأخبرني به أبو خليفة الفضل بن الحباب الجمحي قال حدثنا عون بن محمد بن سلام قال حدثني أبي عمن حدثه عن الزهري وأخبرني به الطوسي والحرمي بن أبي العلاء قالا حدثنا الزبير بن بكار قال حدثني عمي مصعب عن مصعب بن عثمان قال كان الأحوص ينسب بنساء ذوات أخطار من أهل المدينة ويتغنى في شعره معبد ومالك ويشيع ذلك في الناس فنهي فلم ينته فشكي إلى عامل سليمان بن عبد الملك على المدينة وسألوه الكتاب فيه إليه ففعل ذلك وكتب سليمان إلى عامله يأمره أن يضربه مائة سوط ويقيمه على البلس للناس ثم يصيره إلى دهلك ففعل ذلك به فثوى هناك سلطان سليمان بن عبد الملك ثم ولي عمر بن عبد العزيز فكتب إليه يستأذنه في القدوم ويمدحه فأبى أن يأذن له وكتب فيما كتب إليه به\n(أيا راكبا إما عرضت فبلغن ... هديت أمير المؤمنين رسائلي)\n(وقل لأبي حفص إذا ما لقيته ... لقد كنت نفاعا قليل الغوائل)\n(وكيف ترى للعيش طيبا ولذة ... وخالك أمسى موثقا في الحبائل)\nذه الأبيات من رواية الزبير وحده ولم يذكرها ابن سلام قال فأتى رجال من الأنصار عمر بن عبد العزيز فكلموه فيه وسألوه أن يقدمه وقالوا له قد عرفت نسبه وموضعه وقديمه وقد أخرج إلى أرض الشرك فنطلب إليك أن ترده إلى حرم رسول الله ودار قومه فقال لهم عمر فمن الذي يقول\n(فما هو إلا أن أراها فجاءة ... فأبهت حتى ما أكاد أجيب)\nالوا الأحوص قال فمن الذي يقول\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم ما درت حيث أدور)\n(وما كنت زوارا ولكن ذا الهوى ... إذا لم يزر لا بد أن سيزور)\nالوا الأحوص قال فمن الذي يقول\n(كأن لبنى صبير غادية ... أو دمية زينت بها البيع)\n(الله بيني وبين قيمها ... يفر مني بها وأتبع)\nالوا الأحوص قال بل الله بين قيمها وبينه قال فمن الذي يقول\n(ستبقى لها في مضمر القلب والحشا ... سريرة حب يوم تبلى السرائر)\nالوا الأحوص قال إن الفاسق عنها يومئذ لمشغول والله لا أرده ما كان لي سلطان قال فمكث هناك بقية ولاية عمر وصدرا من ولاية يزيد بن عبد الملك","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":6,"spl":"رفض عمر بن عبد العزيز أن يأذن له بالقدوم — حبابة تنشد شعره ليزيد بن عبد الملك"},
{"id":"b38-14","bab":"الجزء 4","sec":"حبابة تنشد شعره ليزيد بن عبد الملك","page":"ج4 ص245","text":"قال فبينا يزيد وجاريته حبابة ذات ليلة على سطح تغنيه بشعر الأحوص قال لها من يقول هذا الشعر قالت لا وعينيك ما أدري قال وقد كان ذهب من الليل شطره فقال ابعثوا إلى ابن شهاب الزهري فعسى أن يكون عنده علم من ذلك فأتي الزهري فقرع عليه بابه فخرج مروعا إلى يزيد فلما صعد إليه قال له يزيد لا ترع لم ندعك إلا لخير إجلس من يقول هذا الشعر قال الأحوص بن محمد يا أمير المؤمنين قال ما فعل قال قد طال حبسه بدهلك قال قد عجبت لعمر كيف أغفله ثم أمر بتخلية سبيله ووهب له أربعمائة دينار فأقبل الزهري من ليلته إلى قومه من الأنصار فبشرهم بذلك أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثنا محمد بن إسماعيل ومحمد بن زيد الأنصاري قالا لما ولي عمر بن عبد العزيز الخلافة أدنى زيد بن أسلم وجفا الأحوص فقال له الأحوص\n(ألست أبا حفص هديت مخبري ... أفي الحق أن أقصى ويدنى ابن أسلما)\nفقال عمر ذلك هو الحق\nقال الزبير وأنشدنيها عبد الملك بن الماجشون عن يوسف بن الماجشون\n(ألا صلة الأرحام أدنى إلى التقى ... وأظهر في أكقائه لو تكرما)\n(فما ترك الصنع الذي قد صنعته ... ولا الغيظ مني ليس جلدا وأعظما)\n(وكنا ذوي قربى لديك فأصبحت ... قرابتنا ثديا أجد مصرما)\n(وكنت وما أملت منك كبارق ... لوى قطره من بعد ما كان غيما)\n(وقد كنت أرجى الناس عندي مودة ... ليالي كان الظن غيبا مرجما)\n(أعدك حرزا إن جنيت ظلامة ... ومالا ثريا حين أحمل مغرما)\n(تدارك بعتبى عاتبا ذا قرابة ... طوى الغيظ لم يفتح بسخط له فما)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":6,"spl":"رفض عمر بن عبد العزيز أن يأذن له بالقدوم — حبابة تنشد شعره ليزيد بن عبد الملك"},
{"id":"b38-15","bab":"الجزء 4","sec":"شعره الذي غنته حبابة","page":"ج4 ص246","text":"أخبرني الحرمي قال حدثنا الزبير بن بكار قال كتب إلي إسحاق بن إبراهيم أن أبا عبيدة حدثه أن الأحوص لم يزل مقيما بدهلك حتى مات عمر بن عبد العزيز فدس إلى حبابة فغنت يزيد بأبيات له قال أبو عبيدة أظنها قوله صوت\n(أيهذا المخبري عن يزيد ... بصلاح فداك أهلي ومالي)\n(ما أبالي إذا يزيد بقي لي ... من تولت به صروف الليالي)\nلم يجنسه كذا جاء في الخبر أنها غنته به ولم يذكر طريقته قال أبو عبيدة أراه عرض بعمر بن عبد العزيز ولم يقدر أن يصرح مع بني مروان فقال من\nيقول هذا قالت الأحوص وهونت أمره وكلمته في أمانه فأمنه فلما أصبح حضر فاستأذنت له ثم أعطاه مائة ألف درهم أخبرنا الحسين بن يحيى عن حماد عن أبيه عن الهيثم بن عدي عن صالح ابن حسان أن الأحوص دس إلى حبابة فغنت يزيد قوله\n(كريم قريش حين ينسب والذي ... أقرت له بالملك كهلا وأمردا)\n(وليس وإن أعطاك في اليوم مانعا ... إذا عدت من أضعاف أضعافه غدا)\n(أهان تلاد المال في الحمد إنه ... إمام هدى يجري على ما تعودا)\n(تشرف مجدا من أبيه وجده ... وقد ورثا بنيان مجد تشيدا)\nقال يزيد ويلك يا حبابة من هذا من قريش قالت ومن يكون أنت هو يا أمير المؤمنين فقال ومن قال هذا الشعر قالت الأحوص يمدح به أمير المؤمنين فأمر به أمير المؤمنين أن يقدم عليه من دهلك وأمر له بمال وكسوة","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":7,"spl":"شعره الذي غنته حبابة — إعجاب يزيد بن عبد الملك بشعره"},
{"id":"b38-16","bab":"الجزء 4","sec":"إعجاب يزيد بن عبد الملك بشعره","page":"ج4 ص247","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني بعض أهل العلم قال دخل الأحوص على يزيد بن عبد الملك وهو خليفة فقال له يزيد والله لو لم تمت إلينا بحرمة ولا توسلت بدالة ولا جددت لنا مدحا غير أنك مقتصر على البيتين اللذين قلتهما فينا لكنت مستوجبا لجزيل الصلة مني حيث تقول\n(وإني لأستحييكم أن يقودني ... إلى غيركم من سائر الناس مطمع)\n(وأن أجتدي للنفع غيرك منهم ... وأنت إمام للرعية مقنع)\nال وهذه قصيدة مدح بها عمر بن عبد العزيز","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":7,"spl":"شعره الذي غنته حبابة — إعجاب يزيد بن عبد الملك بشعره"},
{"id":"b38-17","bab":"الجزء 4","sec":"إكرام يزيد له","page":"ج4 ص248","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله الزهري قال حدثني عمر بن موسى بن عبد العزيز قال لما ولي يزيد بن عبد الملك بعث إلى الأحوص فأقدم عليه فأكرمه وأجازه بثلاثين ألف درهم فلا قدم قباء صب المال على نطع ودعا جماعة من قومه وقال إني قد عملت لكم طعاما فلما دخلوا عليه كشف لهم عن ذلك المال وقال ( أفسحر هذا أم أنتم لا تبصرون\nال الزبير وقال في يزيد بن عبد الملك يمدحه حينئذ بهذه القصيدة\n(صرمت حبلك الغداة نوار ... إن صرما لكل حبل قصار)\nوهي طويلة يقول فيها\n(من يكن سائلا فإن يزيدا ... ملك من عطائه الإكثار)\n(عم معروفه فعز به الدين ... وذلت لملكه الكفار)\n(وأقام الصراط فابتهج الحق ... منيرا كما أنار النهار)\nمن هذه القصيدة بيتان يغني فيهما وهما صوت\n(بشر لو يدب ذر عليه ... كان فيه من مشيه آثار)\n(إن أروى إذا تذكر أروى ... قلبه كاد قلبه يستطار)\nنت فيه عريب لحنا من الثقيل الأول بالبنصر وذكر ابن المكي أنه لجده يحيى أخبرني الحرمي قال حدثنا الزبير قال حدثني عمي مصعب عن مصعب بن عثمان قال حج يزيد بن عبد الملك فتزوج بنت عون بن محمد بن علي بن أبي طالب رضي الله عنه وأصدقها مالا كثيرا فكتب الوليد بن عبد الملك إلى أبي بكر بن محمد بن عمرو بن حزم أنه بلغ أمير المؤمنين أن يزيد بن عبد الملك قد تزوج بنت عون بن محمد بن علي بن أبي طالب وأصدقها مالا كثيرا ولا أراه فعل ذلك إلا وهو يراها خيرا منه قبح الله رأيه فإذا جاءك كتابي هذا فأدع عونا فاقبض المال منه فإن لم يدفعه إليك فأضربه بالسياط حتى تستوفيه منه ثم افسخ نكاحه فأرسل أبو بكر بن محمد بن عمرو إلى عون بن محمد وطالبه بالمال فقال له ليس عندي شيء وقد فرقته فقال له أبو بكر إن أمير المؤمنين أمرني إن لم تدفعه إلي كله أن أضربك بالسياط ثم لا أرفعها عنك حتى أستوفيه منك فصاح به يزيد تعال إلي فجاءه فقال له فيما بينه وبينه كأنك خشيت أن أسلمك إليه إدفع إليه المال ولا تعرض له نفسك فإنه إن دفعه إلي رددته عليك وإن لم يرده علي أخلفته عليك ففعل فلما ولي يزيد بن عبد الملك كتب في أبي بكر بن محمد بن حزم وفي الأحوص فحملا إليه لما بين أبي بكر والأحوص من العداوة وكان أبو بكر قد ضرب الأحوص وغربه إلى دهلك وأبو بكر مع عمر بن عبد العزيز وعمر إذ ذاك على المدينة فلما صارا بباب يزيد أذن للأحوص فرفع أبو\nبكر يديه يدعو فلم يخفضهما حتى خرج الغلمان بالأحوص ملببا مكسور الأنف وإذا هو لما دخل على يزيد قال له أصلحك الله هذا ابن حزم الذي سفه رأيك ورد نكاحك فقال يزيد كذبت عليك لعنة الله وعلى من يقول ذلك اكسروا أنفه وأمر به فأخرج ملببا","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":8,"spl":"إكرام يزيد له — خبره مع عبد الحكم بن عمرو الجمحي"},
{"id":"b38-18","bab":"الجزء 4","sec":"خبره مع عبد الحكم بن عمرو الجمحي","page":"ج4 ص250","text":"أخبرني الحرمي قال حدثنا الزبير قال حدثني عبد الرحمن بن عبد الله عن عبد الله بن عمرو الجمحي قال كان عبد الحكم بن عمرو بن عبد الله بن صفوان الجمحي قد اتخذ بيتا فجعل فيه شطرنجات ونردات وقرقات ودفاتر فيها من كل علم وجعل في الجدار أوتادا فمن جاء علق ثيابه على وتد منها ثم جر دفترا فقرأه أو بعض ما يلعب به فلعب به مع بعضهم قال فإن عبد الحكم يوما لفي المسجد الحرام إذا فتى داخل من باب الحناطين باب بني جمح عليه ثوبان معصفران مدلوكان وعلى أذنه ضعث ريحان وعليه ردع الخلوق فأقبل يشق الناس حتى جلس إلى عبد الحكم بن عمرو بن عبد الله فجعل من رآه يقول ماذا صب عليه من هذا ألم يجد أحدا يجلس إليه غيره ويقول بعضهم فأي شيء يقوله له عبد\nالحكم وهو أكرم من أن يجبه من يقعد إليه فتحدث إليه ساعة ثم أهوى فشبك يده في يد عبد الحكم وقام يشق المسجد حتى خرج من باب الحناطين قال عبد الحكم فقلت في نفسي ماذا سلط الله علي منك رآني نصف الناس في المسجد ونصفهم في الحناطين حتى دخل مع عبد الحكم بيته فعلق على وتد وحل أزراره واجتز الشطرنج وقال من يلعب فبينا هو كذلك إذ دخل الأبجر المغني فقال له أي زنديق ما جاء بك إلى هاهنا وجعل يشتمه ويمازحه فقال له عبد الحكم أتشتم رجلا في منزلي فقال أتعرفه هذا الأحوص فاعتنقه عبد الحكم وحياه وقال له أما إذا كنت الأحوص فقد هان علي ما فعلت","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":8,"spl":"إكرام يزيد له — خبره مع عبد الحكم بن عمرو الجمحي"},
{"id":"b38-19","bab":"الجزء 4","sec":"عبد الملك بن مروان يتمثل بشعره","page":"ج4 ص251","text":"أخبرني الطوسي والحرمي قالا حدثنا الزبير بن بكار قال حدثني حميد بن عبد العزيز عن أبيه قال لما قدم عبد الملك بن مروان حاجا سنة خمس وسبعين وذلك بعدما اجتمع الناس عليه بعامين جلس على المنبر فشتم أهل المدينة ووبخهم ثم قال إني والله يا أهل المدينة قد بلوتكم فوجدتكم تنفسون القليل وتحسدون على الكثير وما وجدت لكم مثلا إلا ما قال مخنثكم وأخوكم الأحوص\n(وكم نزلت بي من خطوب مهمة ... خذلتم عليها ثم لم أتخشع)\n(فأدبر عني شرها لم أبل بها ... ولم أدعكم في كربها المتطلع)\nقام إليه نوفل بن مساحق فقال يا أمير المؤمنين أقررنا بالذنب وطلبنا المعذرة فعد بحلمك فذلك ما يشبهنا منك ويشبهك منا فقد قال من ذكرت من بعد بيتيه الأولين\n(وإني لمستأن ومنتظر بكم ... وإن لم تقولوا في الملمات دع دع)\n(أؤمل منكم أن تروا غير رأيكم ... وشيكا وكيما تنزعوا خير منزع)\nأخبرني الحرمي والطوسي قالا حدثنا الزبير قال حدثني محمد بن الضحاك عن المنذر بن عبد الله الحزامي أن عراك بن مالك كان من أشد أصحاب عمر بن عبد العزيز على بني مروان في انتزاع ما حازوا من الفيء والمظالم من أيديهم فلما ولي يزيد بن عبد الملك ولي عبد الواحد بن عبد الله النصري المدينة فقرب عراك بن مالك وقال صاحب الرجل الصالح وكان لا يقطع أمرا دونه وكان يجلس معه على سريره فبينا هو معه إذ أتاه كتاب يزيد بن عبد الملك أن ابعث مع عراك بن مالك حرسيا حتى ينزله أرض دهلك وخذ من عراك حمولته فقال لحرسي بين يديه وعراك معه على السرير خذ بيد عراك فابتع من ماله راحلة ثم توجه به نحو دهلك حتى تقر فيها ففعل ذلك الحرسي قال وأقدم الأحوص فمدحه الأحوص فأكرمه وأعطاه قال فأهل دهلك يأثرون الشعر عن الأحوص والفقه عن عراك بن مالك أخبرني أبو خليفة الفضل بن الحباب عن محمد بن سلام عن أبي الغراف عمن يثق به قال بعث يزيد بن عبد الملك حين قتل يزيد بن المهلب في الشعراء فأمر بهجاء يزيد بن المهلب منهم الفرزدق وكثير والأحوص فقال الفرزدق لقد\nامتدحت بني المهلب بمدائح ما امتدحت بمثلها أحدا وإنه لقبيح بمثلي أن يكذب نفسه على كبر السن فليعفني أمير المؤمنين قال فأعفاه وقال كثير إني أكره أن أعرض نفسي لشعراء أهل العراق إن هجوت بني المهلب وأما الأحوص فإنه هجاهم ثم بعث به يزيد بن عبد الملك إلى الجراح بن عبد الله الحكمي وهو بأذربيجان وقد كان بلغ الجراح هجاء الأحوص بني المهلب فبعث إليه بزق من خمر فأدخل منزل الأحوص ثم بعث إليه خيلا فدخلت منزله فصبوا الخمر على رأسه ثم أخرجوه على رؤوس الناس فأتوا به الجراح فأمر بحلق رأسه ولحيته وضربه الحد بين أوجه الرجال وهو يقول ليس هكذا تضرب الحدود فجعل الجراح يقول أجل ولكن لما تعلم ثم كتب إلى يزيد بن عبد الملك يعتذر فأغضى له عليها","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":9,"spl":"عبد الملك بن مروان يتمثل بشعره"},
{"id":"b38-20","bab":"الجزء 4","sec":"رأي أبي الفرج فيه","page":"ج4 ص253","text":"قال أبو الفرج الأصبهاني وليس ما جرى من ذكر الأحوص إرادة للغض منه في شعره ولكنا ذكرنا من كل ما يؤثر عنه ما تعرف به حاله من تقدم وتأخر وفضيلة ونقص فأما تفضيله وتقدمه في الشعر فمتعالم مشهور وشعره ينبئ عن نفسه ويدل على فضله فيه وتقدمه وحسن رونقه وتهدبه وصفائه أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار قال حدثنا عبد الملك بن عبد العزيز قال حدثني عبد الله بن مسلم بن جندب الهذلي قال حدثنا شيخ لنا من هذيل كان خالا للفرزدق من بعض أطرافه قال سمعت بالفرزدق وجرير على باب الحجاج فقلت لو تعرضت ابن\nأختنا فامتطيت إليه بعيرا حتى وجدتهما قبل أن يخلصا ولكل واحد منهما شيعة فكنت في شيعة الفرزدق فقام الآذان يوما فقال أين جرير فقال جرير هذا أبو فراس فأظهرت شيعته لومه وأسرته فقال الآذن أين الفرزدق فقام فدخل فقالوا لجرير أتناوئه وتهاجيه وتشاخصه ثم تبدى عليه فتأبى وتبديه قضيت له على نفسك فقال لهم إنه نزر القول ولم ينشب أن ينفد ما عنده وما قال فيه فيفاخره ويرفع نفسه عليه فما جئت به بعد حمدت عليه واستحسن فقال قائلهم لقد نظرت نظرا بعيدا قال فما نشبوا أن خرج الآذن فصاح أين جرير فقام جرير فدخل قال فدخلت فإذا ما مدحه به الفرزدق قد نفد وإذا هو يقول\n(أين الذين بهم تسامي دارما ... أم من إلى سلفي طهية تجعل)\nقال وعمامته على رأسه مثل المنسف فصحت من روائه\n(هذا ابن يوسف فاعلموا وتفهموا ... برح الخفاء فليس حين تناجي)\n(من سد مطلع النفاق عليكم ... أم من يصول كصولة الحجاج)\n(أم من يغار على النساء حفيظة ... إذ لا يثقن بغيرة الأزواج)\n(قل للجبان إذا تأخر سرجه ... هل أنت من شرك المنية ناجي)\nال وما تشبيبها وطرب فقال جرير\n(لج الهوى بفؤادك الملجاج ... فاحبس بتوضح باكر الأحداج)\nوأمرها أو قال أمضاها فقال أعطوه كذا وكذا فاستقللت ذلك فقال الهذلي وكان جرير عربيا قرويا فقال للحجاج قد أمر لي الأمير بما لم يفهم عنه فلو دعا كاتبا وكتب بما أمر به الأمير فدعا كاتبا واحتاط فيه بأكثر من ضعفه وأعطى الفرزدق أيضا قال الهذلي فجئت الفرزدق فأمر لي بستين دينارا وعبد ودخلت على رواته فوجدتهم يعدلون ما انحرف من شعره فأخذت من شعره ما أردت ثم قلت له يا أبا فراس من أشعر الناس قال أشعر الناس بعدي ابن المراغة قلت فمن أنسب الناس قال الذي يقول\n(لي ليلتان فليلة معسولة ... ألقى الحبيب بها بنجم الأسعد)\n(ومريحة همي علي كأنني ... حتى الصباح معلق بالفرقد)\nلت ذاك الأحوص قال ذاك هو قال الهذلي ثم أتيت جريرا فجعلت أستقل عنده ما أعطاني صاحبي أستخرج به منه فقال كم أعطاك ابن أختك فأخبرته فقال ولك مثله فأعطاني ستين دينارا وعبدا قال وجئت رواته وهم يقومون ما\nانحرف من شعره وما فيه من السناد فأخذت منه ما أردت ثم قلت يا أبا حزرة من أنسب الناس قال الذي يقول\n(يا ليت شعري عمن كلفت به ... من خثعم إذ نأيت ما صنعوا)\n(قوم يحلون بالسدير وبالحيرة ... منهم مرأى ومستمع)\n(أن شطت الدار عن ديارهم ... أأمسكوا بالوصال أم قطعوا)\n(بل هم على خير ما عهدت وما ... ذلك إلا التأميل والطمع)\nلت ومن هو قال الأحوص فاجتمعا على أن الأحوص أنسب الناس","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":10,"spl":"رأي أبي الفرج فيه"},
{"id":"b38-21","bab":"الجزء 4","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج4 ص256","text":"منها الأبيات التي يقول فيها الأحوص\n(لي ليلتان فليلة معسولة ... )\nأول ما يغنى به فيها صوت\n(يا للرجال لوجدك المتجدد ... ولما تؤمل من عقيلة في غد)\n(ترجو مواعد بعث آدم دونها ... كانت خبالا للفؤاد المقصد)\n(هل تذكرين عقيل أو أنساكه ... بعدي تقلب ذا الزمان المفسد)\n(يومي ويومك بالعقيق إذ الهوى ... منا جميع الشمل لم يتبدد)\n(لي ليلتان فليلة معسولة ... ألقى الحبيب بها بنجم الأسعد)\n(ومريحة همي علي كأنني ... حتى الصباح معلق بالفرقد)\nروضه من الكامل يقال يا للرجال ويا للرجال بالكسر والفتح وفي الحديث أن عمر رضي الله عنه صاح لما طعن يا لله يا للمسلمين وقوله في غد يريد فيما بعد وفي باقي الدهر قال الله سبحانه ( سيعلمون غدا من الكذاب الأشر\nالخبل والخبال النقصان من الشيء والمخبل أصله مأخوذ من النقص لأنه ناقص العقل والمعسولة الجلوة المشتهاة الشعر للأحوص والغناء في البيت الأول والثاني لمالك خفيف رمل بالبنصر عن الهشامي وحبش وفي الثالث والرابع لسليمان أخي بابويه ثقيل أول بالوسطى عن عمرو وفيهما وفي الخامس والسادس لحن لابن سريج ذكره يونس ولم يجنسه وذكر حماد بن إسحاق عن أبيه أن لمعبد في الأبيات كلها لحنا وأنه من صحيح غنائه ولم يجنسه أخبرني الحسين بن يحيى عن حماد عن أبيه عن أيوب بن عباية قال بلغني أن ابنا للأحوص بن محمد الشاعر دخل على امرأة شريفة وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني إبراهيم بن زيد عن عنبسة بن سعيد بن العاصي قال أخبرني أشعب بن جبير قال","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء — نسبة هذا البيت وما غني فيه من الشعر","partialRef":{"sid":"b38-20","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b38-22","bab":"الجزء 4","sec":"امرأة تستفسر ابنه عن شعر له","page":"ج4 ص257","text":"حضرت امرأة شريفة ودخل عليها ابن الأحوص بن محمد الشاعر فقالت له أتروي قول أبيك\n(لي ليلتان فليلة معسولة ... ألقى الحبيب بها بنجم الأسعد)\n(ومريحة همي علي كأنني ... حتى الصباح معلق بالفرقد)\nقال نعم قالت أتدري أي الليلتين التي يبيت فيها معلقا بالفرقد قال لا والله قالت هي ليلة أمك التي يبيت معها فيها قال إبراهيم في خبره فقلت لأشعب يا أبا العلاء فأي ليلتيه المعسولة فقال\n(ستبدي لك الأيام ما كنت جاهلا ... ويأتيك بالأخبار من لم تزود)\nي ليلة الإسراف ولا تسأل عما بعدها أخبرني عبد العزيز ابن بنت الماجشون قال أنشد ابن جندب قول الأحوص\n(لي ليلتان فليلة معسولة ... ألقى الحبيب بها بنجم الأسعد)\n(ومريحة همي علي كأنني ... حتى الصباح معلق بالفرقد)\nقال أما إن الله يعلم أن الليلة المريحة همي لألذ الليلتين عندي قال الحرمي ابن أبي العلاء وذلك لكلفه بالغزل والشوق والحنين وتمني اللقاء","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء — نسبة هذا البيت وما غني فيه من الشعر"},
{"id":"b38-23","bab":"الجزء 4","sec":"من هي عقيلة التي شغف بها الأحوص","page":"ج4 ص258","text":"وللأحوص مع عقيلة هذه أخبار قد ذكرت في مواضع أخر وعقيلة امرأة من ولد عقيل بن أبي طالب رضي الله عنه وقد ذكر الزبير عن ابن بنت الماجشون عن خاله أن عقيلة هذه هي سكينة بنت الحسين عليهما السلام كنى عنها بعقيلة أخبرني الحرمي قال حدثنا الزبير قال حدثني عمر بن أبي بكر المؤملي أن إنسانا أنشد عند إبراهيم بن هشام وهو والي المدينة قول الأحوص\n(إذ أنت فينا لمن ينهاك عاصية ... وإذ أجر إليكم سادرا رسني)\nوثب أبو عبيدة بن عمار بن ياسر قائما ثم أرخى رداءه ومضى يمشي على تلك\nالحال ويجره حتى بلغ العرض ثم رجع فقال له إبراهيم بن هشام حين جلس ما شأنك فقال أيها الأمير إني سمعت هذا البيت مرة فأعجبني فحلفت لا أسمعه إلا جررت رسني","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء — نسبة هذا البيت وما غني فيه من الشعر"},
{"id":"b38-24","bab":"الجزء 4","sec":"نسبة هذا البيت وما غني فيه من الشعر","page":"ج4 ص258","text":"صوت\n(سقيا لربعك من ربع بذي سلم ... وللزمان به إذ ذاك من زمن)\n(إذ أنت فينا لمن ينهاك عاصية ... وإذا أجر إليكم سادرا رسني)\nروضه من - البسيط - غنى ابن سريج في هذين البيتين لحنا من الثقيل الأول بالوسطى عن عمرو وذكر إسحاق فيه لحنا من الثقيل الأول بالسبابة في مجرى الوسطى ولم ينسبه إلى أحد وذكر حبش أنه للغريض","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":11,"spl":"نسبة ما في هذا الخبر من الغناء — نسبة هذا البيت وما غني فيه من الشعر"},
{"id":"b38-25","bab":"الجزء 4","sec":"حماد الراوية فضله على الشعراء في النسيب","page":"ج4 ص259","text":"أخبرني أبو خليفة عن محمد بن سلام عن سالم بن أبي السحماء وكان صاحب حماد الراوية أن حمادا كان يقدم الأحوص في النسيب أخبرني الحرمي قال حدثنا الزبير قال حدثنا عمر بن أبي سليمان عن يوسف ابن أبي سليمان بن عنيزة قال هجا الأحوص رجلا من الأنصار من بني حرام يقال له ابن بشير وكان كثير\nالمال فغضب من ذلك فخرج حتى قدم على الفرزدق بالبصرة وأهدى إليه وألطفه فقبل منه ثم جلسا يتحدثان فقال الفرزدق ممن أنت قال من الأنصار قال ما أقدمك قال جئت مستجيرا بالله عز و جل ثم وبك من رجل هجاني قال قد أجارك الله منه وكفاك مؤنته فأين أنت عن الأحوص قال هو الذي هجاني فأطرق ساعة ثم قال أليس هو الذي يقول\n(ألا قف برسم الدار فاستنطق الرسما ... فقد هاج أحزاني وذكرني نعما)\nال بلى قال فلا والله لا أهجو رجلا هذا شعره فخرج ابن بشير فاشترى أفضل من الشراء الأول من الهدايا فقدم بها على جرير فأخذها وقال له ما أقدمك قال جشت مستجيرا بالله بولك من رجل هجاني فقال قد أجارك الله عز و جل منه وكفاك أين أنت عن ابن عمك الأحوص بن محمد قال هو الذي هجاني قال فأطرق ساعة ثم قال أليس هو الذي يقول\n(تمشى بشتمي في أكاريس مالك ... تشيد به كالكلب إذ ينبح النجما)\n(فما أنا بالمخسوس في جذم مالك ... ولا بالمسمى ثم يلتزم الإسما)\n(ولكن بيتي إن سألت وجدته ... توسط منها العز والحسب الضخما)\nقال بلى والله قال فلا والله لا أهجو شاعرا هذا شعره قال فاشترى أفضل من تلك الهدايا وقدم على الأحوص فأهداها إليه وصالحه","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":12,"spl":"حماد الراوية فضله على الشعراء في النسيب — المهدي يسأل عن أنسب بيت قالته العرب"},
{"id":"b38-26","bab":"الجزء 4","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج4 ص260","text":"صوت\n(ألا قف برسم الدار فاستنطق الرسما ... فقد هاج أحزاني وذكرني نعما)\n(فبت كأني شارب من مدامة ... إذا أذهبت هما أتاحت له هما)\nناه إبراهيم الموصلي خفيف رمل بالوسطى عن الهشامي وذكر عبد الله ابن العباس الربيعي أنه له أخبرني الحرمي قال حدثني الزبير قال حدثني عبد الملك بن عبد العزيز قال قال لي أبو السائب المخزومي أنشدني للأحوص فأنشدته قوله\n(قالت وقلت تحرجي وصلي ... حبل امرئ بوصالكم صب)\n(واصل إذا بعلي فقلت لها ... الغدر شيء ليس من ضربي)\nوت\n(ثنتان لا أدنو لوصلهما ... عرس الخليل وجارة الجنب)\n(أما الخليل فلست فاجعه ... والجار أوصاني به ربي)\n(عوجوا كذا تذكر لغانية ... بعض الحديث مطيكم صحبي)\n(ونقل لها فيم الصدود ولم ... نذنب بل انت بدأت بالذنب)\n(إن تقبلي نقبل وننزلكم ... منا بدار السهل والرحب)\n(أو تدبري تكدر معيشتنا ... وتصدعي متلائم الشعب)\nنى في ثنتان لا أدنو والذي بعده ابن جامع ثقيلا أول بالوسطى وغنى في عوجوا كذا نذكر لغانية والأبيات التي بعده ابن محرز لحنا من\nالقدر الأوسط من الثقيل الأول مطلقا في مجرى البنصر قال فأقبل علي أبو السائب فقال يابن أخي هذا والله المحب عينا لا الذي يقول\n(وكنت إذا خليل رام صرمي ... وجدت وراي منفسحا عريضا)\nذهب فلا صحبك الله ولا وسع عليك يعني قائل هذا البيت","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":12,"spl":"حماد الراوية فضله على الشعراء في النسيب — المهدي يسأل عن أنسب بيت قالته العرب"},
{"id":"b38-27","bab":"الجزء 4","sec":"المهدي يسأل عن أنسب بيت قالته العرب","page":"ج4 ص262","text":"أخبرني الحرمي قال حدثني الزبير قال حدثنا خالد بن وضاح قال حدثني عبد الأعلى بن عبد الله بن محمد بن صفوان الجمحي قال حملت دينا بعسكر المهدي فركب المهدي بين أبي عبيد الله وعمر بن بزيع وأنا وراءه في موكبه على برذون قطوف فقال ما أنسب بيت قالته العرب فقال له أبو عبيد الله قول أمرئ القيس\n(وما ذرفت عيناك إلا لتضربي ... بسهميك في أعشار قلب مقتل)\nفقال هذا أعرابي قح فقال عمر بن بزيع قول كثير يا أمير المؤمنين\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nقال ما هذا بشيء وماله يريد أن ينسى ذكرها حتى تمثل له فقلت عندي حاجتك يا أمير المؤمنين جعلني الله فداك قال الحق بي قلت لا لحاق بي ليس ذلك في دابتي قال احملوه على دابة قلت هذا أول الفتح فحملت على دابة فلحقت فقال ما عندك فقلت قول الأحوص\n(إذا قلت إني مشتف بلقائها ... فحتم التلاقي بيننا زادني سقما)\nفقال أحسن والله اقضوا عنه دينه فقضي عني ديني","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":12,"spl":"حماد الراوية فضله على الشعراء في النسيب — المهدي يسأل عن أنسب بيت قالته العرب"},
{"id":"b38-28","bab":"الجزء 4","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج4 ص262","text":"منها الشعر الذي هو\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nصوت\n(ألا حييا ليلى أجد رحيلي ... وآذن أصحابي غدا بقفول)\n(ولم أر من ليلى نوالا أعده ... ألا ربما طالبت غير منيل)\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\n(وليس خليلي بالملول ولا الذي ... إذا غبت عنه باعني بخليل)\n(ولكن خليلي من يدوم وصاله ... ويحفظ سري عند كل دخيل)\nروضه من - الطويل - الشعر لكثير والغناء في ثلاثة الأبيات الأول لإبراهيم ولحنه من الثقيل الأول بإطلاق الوتر في مجرى البنصر ولابنه إسحاق في\n(وليس خليلي بالملول ولا الذي ... )\nثقيل آخر بالوسطى","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":13,"spl":"نسبة ما في هذا الخبر من الأغاني — شعره في مرض موته","partial":1},
{"id":"b38-29","bab":"الجزء 4","sec":"حديث البعض عن كثير وجميل","page":"ج4 ص263","text":"أخبرني أبو خليفة قال حدثنا محمد بن سلام وأخبرني الحرمي قال حدثنا الزبير عن محمد بن سلام قال كان لكثير في النسيب حظ وافر وجميل مقدم عليه وعلى أصحاب النسيب جميعا ولكثير من فنون الشعر ما ليس لجميل وكان كثير راوية جميل وكان جميل صادق الصبابة والعشق ولم يكن كثير بعاشق وكان يتقول قال وكان\nالناس يستحسنون بيت كثير في النسيب\n(أريد لأنسى ذكرها فكأنما ... تمثل لي ليلى بكل سبيل)\nال وقد رأيت من يفضل عليه بيت جميل\n(خليلي فيما عشتما هل رأيتما ... قتيلا بكى من حب قاتله قبلي)\nرأت في كتاب منسوب إلى أحمد بن يحيى البلاذري وذكر إسحاق بن إبراهيم الموصلي أن عبد الله بن معصب الزبيري كان يوما يذكر شعر كثير ويصف تفضيل أهل الحجاز إياه إلي أن انتهى إلى هذا البيت قال إسحاق فقلت له إن الناس يعيبون عليه هذا المعنى ويقولون ما له يريد أن ينساها فتبسم ابن مصعب ثم قال إنكم يأهل العراق لتقولون ذلك أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أبو يحيى الزهري قال حدثني الهزبري قال قيل لكثير ما أنسب بيت قلته قال الناس يقولون\n(أريد لأنسى ذكرها فكانما ... تمثل لي ليلى بكل سبيل)\nوأنسب عندي منه قولي\n(وقل أم عمر داؤه وشفاؤه ... لديها ورياها الشفاء من الخبل)\nقد قيل إن بعض هذه الأبيات للمتوكل الليثي أخبرني الحرمي قال حدثنا الزبير قال حدثني عثمان قال الحرمي أحسبه ابن عبد الرحمن المخزومي قال حدثنا إبراهيم بن أبي عبد الله قال\nقيل لمحرز بن جعفر أنت صاحب شعر ونراك تلزم الأنصار وليس هناك منه شي قال بلى والله إن هناك لشعر عين الشعر وكيف لا يكون للشعر هناك وصاحبهم الأحوص الذي يقول\n(يقولون لو ماتت لقد غاض حبه ... وذلك حين الفاجعات وحيني)\n(لعمرك إني إن تحم وفاتها ... بصحبة من يبقى لغير ضنين)\nوهو الذي يقول\n(وإني لمكرام لسادات مالك ... وإني لنوكى مالك لسبوب)\n(وإني على الحلم الذي من سجيتي ... لحمال أضغان لهن طلوب)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":13,"spl":"نسبة ما في هذا الخبر من الأغاني — شعره في مرض موته"},
{"id":"b38-30","bab":"الجزء 4","sec":"شعره في مرض موته","page":"ج4 ص265","text":"أخبرني الحرمي قال حدثني الزبير قال حدثني عمي مصعب قال حدثني يحيى بن الزبير بن عباد بن حمزة بن عبد الله بن الزبير قال الزبير وحدثني علي بن صالح عن عامر بن صالح أن الأحوص قال في مرضه الذي مات فيه وقال عامر بن صالح حين هرب من عبد الواحد النصري إلى البصرة\n(يا بشر يا رب محزون بمصرعنا ... وشامت جذل ما مسه الحزن)\n(وما شمات امرئ إن مات صاحبه ... وقد يرى أنه بالموت مرتهن)\n(يا بشر هبي فإن النوم أرقه ... نأي مشت وأرض غيرها الوطن)","topic":"ذكر الأحوص وأخباره ونسبه","topicNo":38,"sp":13,"spl":"نسبة ما في هذا الخبر من الأغاني — شعره في مرض موته"},
{"id":"b39-2","bab":"الجزء 4","sec":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره — بعض صفاته","page":"ج4 ص265 – ج4 ص266","text":"الدلال اسمه ناقد وكنيته أبو زيد وهو مدني مولى بني فهم وأخبرني علي بن عبد العزيز عن ابن خرداذبه قال قال إسحاق لم يكن في المخنثين أحسن وجها ولا أنظف ثوبا ولا أظرف من الدلال قال وهو أحد من خصاه ابن حزم فلما فعل ذلك به قال الآن تم الخنث وأخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبد الله مصعب الزبيري قال الدلال مولى عائشة بنت سعيد بن العاص\nوأخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن أبي عبد الله مصعب الزبيري قال كان الدلال من أهل المدينة ولم يكن أهلها يعدون في الظرفاء وأصحاب النوادر من المخنثين بها إلا ثلاثة طويس والدلال وهنب فكان هنب أقدمهم والدلال أصغرهم ولم يكن بعد طويس أظرف من الدلال ولا أكثر ملحا\nقال إسحاق وحدثني هشام بن المرية عن جرير وكانا نديمين مدنيين قال ما ذكرت الدلال قط إلا ضحكت لكثرة نوادره قال وكان نزر الحديث فإذا تكلم أضحك الثكلي وكان ضاحك السن وصنعته نزرة جيده ولم يكن يغني إلا غناء مضعفا يعني كثير العمل قال إسحاق وحدثني أيوب بن عباية قال شهدت أهل المدينة إذا ذكروا الدلال وأحاديثه طولوا رقابهم وفخروا به فعلمت أن ذلك لفضيلة كانت فيه قال وحدثني ابن جامع عن يونس قال كان الدلال مبتلى بالنساء والكون معهن وكان يطلب فلا يقدر عليه وكان بديع الغناء صحيحه حسن الجرم","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":0,"spl":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره — بعض صفاته — كيف كان يتوس"},
{"id":"b39-3","bab":"الجزء 4","sec":"كيف كان يتوسط بين الرجال والنساء","page":"ج4 ص266","text":"قال إسحاق وحدثني الزبيري قال إنما لقب بالدلال لشكله وحسن دله وظرفه وحلاوة منطقة وحسن وجهه وإشارته وكان مشغوفا بمخالطة النساء ووصفهن للرجال وكان من أراد خطبة امرأة سأله عنها وعن غيرها فلا يزال يصف له النساء واحدة فواحدة حتى ينتهي إلى وصف ما يعجبه ثم يتوسط بينه وبين من يعجبه منهن حتى يتزوجها فكان يشاغل كل من جالسه عن الغناء بتلك الأحاديث كراهة منه للغناء","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":0,"spl":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره — بعض صفاته — كيف كان يتوس"},
{"id":"b39-4","bab":"الجزء 4","sec":"السبب الذي من أجله خصي","page":"ج4 ص267","text":"قال إسحاق وحدثني مصعب الزبيري قال أنا أعلم خلق الله بالسبب الذي من أجله خصي الدلال وذلك أنه كان\nالقادم يقدم المدينة فيسأل عن المرأة يتزوجها فيدل على الدلال فإذا جاءه قال له صف لي من تعرف من النساء للتزويج فلا يزال يصف له واحدة بعد واحدة حتى ينتهي إلى ما يوافق هواه فيقول كيف لي بهذه فيقول مهرها كذا وكذا فإذا رضي بذلك أتاها الدلال فقال لها إني قد أصبت لك رجلا من حاله وقصته وهيئته ويساره ولا عهد له بالنساء وإنما قدم بلدنا آنفا فلا يزال بذلك يشوقها ويحركها حتى تطيعه فيأتي الرجل فيعلمه أنه قد أحكم له ما أراد فإذا سوي الأمر وتزوجته المرأة قال لها قد آن لهذا الرجل أن يدخل بك والليلة موعده وأنتم مغتلمة شبقة جامة فساعة يدخل عليك قد دفقت عليه مثل سيل العرم فيقذرك ولا يعاودك وتكونين من أشأم النساء على نفسك وغيرك فتقول فكيف أصنع فيقول أنت أعلم بدواء حرك ودائه وما يسكن غلمتك فتقول أنت أعرف فيقول ما أجدله شيئا أشفى من النيك فيقول لها إن لم تخافي الفضيحة فابعثي إلى بعض الزنوج حتى يقضي بعض وطرك ويكف عادية حرك فتقول له ويلك ولا كل هذا فلا تزال المحاورة بينهما حتى يقول لها فكما جاء علي أقوم فأخففك وأنا والله إلى التخفيف أحوج فتفرح المرأة فتقول هذا أمر مستور فينيكها حتى إذا قضى لذته منها قال لها أما أنت فقد استرحت وأمنت العيب وبقيت أنا ثم يجيء إلى الزوج فيقول له قد واعدتها أن تدخل عليك الليلة وأنت رجل عزب ونساء المدينة خاصة يردن المطاولة في الجماع وكأني بك كما تدخله عليها تفرغ وتقوم فتبغضك وتمقتك ولا تعاودك بعدها ولو أعطيتها الدنيا ولا تنظر في وجهك بعدها فلا يزال في مثل هذا القول حتى يعلم أنه قد هاجت شهوته فيقول له كيف أعمل قال تطلب زنجية فتنيكها مرتين أو\nثلاثا حتى تسكن غلمتك فإذا دخلت الليلة إلى أهلك لم تجد أمرك إلا جميلا فيقول له ذاك أعوذ بالله من هذه الحال أزنا وزنجية لا والله لا أفعل فإذا أكثر محاورته قال له فكما جاء علي قم فنكني أنا حتى تسكن غلمتك وشبقك فيفرح فينيكه مرة أو مرتين فيقول له قد استوى أمرك الآن وطابت نفسك وتدخل على زوجتك فتنيكها نيكا يملؤها سرورا ولذة فينيك المرأة قبل زوجها وينيكه الرجل قبل امرأته فكان ذلك دأبه إلى أن بلغ خبره سليمان بن عبد الملك وكان غيورا شديد الغيرة فكتب بأن يخصى هو وسائر المخنثين بالمدينة ومكة وقال إن هؤلاء يدخلون على نساء قريش ويفسدونهن فورد الكتاب على ابن حزم فخصاهم هذه رواية إسحاق عن الزبيري والسبب في هذا أيضا مختلف فيه وليس كل الرواة يروون ذلك كما رواه مصعب","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":1,"spl":"السبب الذي من أجله خصي"},
{"id":"b39-5","bab":"الجزء 4","sec":"رواية أخرى عن سبب خصيه","page":"ج4 ص269","text":"فمما روي من أمرهم ما أخبرني به أحمد بن عبد العزيز الجوهري وهذا الخبر أصح ما روي في ذلك إسنادا قال أخبرنا أبو زيد عمر بن شبة عن معن بن عيسى هكذا رواه الجوهري وأخبرنا به إسماعيل بن يونس قال حدثني عمر ابن شبة قال حدثني أبو غسان قال قال ابن جناح حدثني معن بن عيسى عن عبد الرحمن بن أبي الزناد عن أبيه وعن محمد بن معن الغفاري قالا كان سبب ما خصي له المخنثون بالمدينة أن سليمان بن عبد الملك كان في نادية له يسمر ليلة على ظهر سطح فتفرق عنه جلساؤه فدعا بوضوء فجاءت به جارية له فبينا هي تصب عليه إذا أومأ بيده وأشار بها مرتين أو ثلاثا فلم تصب\nعليه فأنكر ذلك فرفع رأسه فإذا هي مصغية بسمعها إلى ناحية العسكر وإذا وصوت رجل يغني فأنصت له حتى سمع جميع ما تغني به فلما أصبح أذن للناس ثم أجرى ذكر الغناء فلين فيه حتى ظن القوم أنه يشتهيه ويريده فأفاضوا فيه بالتسهيل وذكر من كان يسمعه فقال سليمان فهل بقي أحد يسمع منه الغناء فقال رجل من القوم عندي يا أمير المؤمنين رجلان من أهل أيلة مجيدان محكمان قال وأين منزلك فأومأ إلى الناحية التي كان الغناء منها قال فابعث إليهما ففعل فوجد الرسول أحدهما فأدخله على سليمان فقال ما اسمك قال سمير فسأله عن الغناء فاعترف به فقال متى عهدك به قال الليلة الماضية قال وأين كنت فأشار إلى الناحية التي سمع سليمان منها الغناء قال فما غنيت به فأخبره الشعر الذي سمعه سليمان فأقبل على القوم فقال هدر الجمل فضبعت الناقة ونب التيس فشكرت الشاة وهدر الحمام فزافت الحمامة وغنى الرجل فطربت المرأة ثم أمر به فخصي وسأل عن الغناء أين أصله فقيل بالمدينة في المخنثين وهم أئمته والحذاق فيه فكتب إلى أبي بكر بن محمد بن عمرو بن حزم الأنصاري وكان عامله عليها أن اخص من قبلك من المخنثين المغنين فزعم موسى بن جعفر بن أبي كثير قال أخبرني بعض الكتاب قال قرأت كتاب سليمان في الديوان فرأيت على الخاء نقطة كتمرة العجوة قال ومن لا يعلم يقول إنه صحف القارئ وكانت أحص قال فتتبعهم ابن حزم فخصى منهم تسعة فمنهم الدلال وطريف وحبيب نومة\nالضحى وقال بعضهم حين خصي سلم الخاتن والمختون وهذا كلام يقوله الصبي إذا ختن قال فزعم ابن أبي ثابت الأعرج قال أخبرني حماد بن نشيط الحسني قال أقبلنا من مكة ومعنا بدراقس وهو الذي ختنهم وكان غلامه قد أعانه على خصائهم فنزلنا على حبيب نومة الضحى فاحتفل لنا وأكرمنا فقال له ثابت من أنت قال يابن أخي أتجهلني وأنت وليت ختاني أو قال وأنت ختنتني قال واسوءتاه وأيهم أنت قال أنا حبيب قال ثابت فاجتنبت طعامه وخفت أن يسمني قال وجعلت لحية الدلال بعد سنة أو سنتين تتناثر وأما ابن الكلبي فإنه ذكر عن أبي مسكين ولقيط أن أيمن كتب بإحصاء من في المدينة من المخنثين ليعرفهم فيوفد عليه من يختاره للوفادة فظن الوالي أنه يريد الخصاء فخاصهم أخبرني وكيع قال حدثني أبو أيوب المديني قال حدثني محمد بن سلام قال حدثني ابن جعدبة ونسخت أنا من كتاب أحمد بن الحارث الخراز عن المديني عن ابن جعدبة واللفظ له أن الذي هاج سليمان بن عبد الملك على ما صنعه بمن كان بالمدينة من المخنثين أنه كان مستلقيا على فراشه في الليل وجارية له إلى جنبه وعليها غلالة ورداء معصفران وعليها وشاحان من ذهب وفي عنقها فصلان من لؤلؤ وزبرجد وياقوت وكان سليمان بها مشغوفا وفي عسكره رجل يقال له سمير الأيلي يغني فلم يفكر سليمان في غنائه شغلا بها وإقبالا عليها وهي لاهية عنه لا تجيبه مصغية إلى الرجل حتى طال ذلك عليه فحول وجهه عنها مغضبا ثم عاد إلى ما كان مشغولا عن فهمه بها فسمع سميرا يغني بأحسن صوت وأطيب نغمة\nصوت\n(محجوبة سمعت صوتي فأرقها ... من آخر الليل حتى شفها السهر)\n(تدني على جيدها ثنيي معصفرة ... والحلي منها على لباتها خصر)\n(في ليلة النصف ما يدري مضاجعها ... أوجهها عنده أبهى أم القمر)\nيروى\n(أوجهها ما يرى أم وجهها القمر ... )\n(لو خليت لمشت نحوي على قدم ... تكاد من رقة للمشي تنفطر)","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":2,"spl":"رواية أخرى عن سبب خصيه","partial":1},
{"id":"b39-6","bab":"الجزء 4","sec":"رواية أخرى عن سبب خصيه","page":"ج4 ص269","text":"لغناء لسمير الأيلي رمل مطلق بالبنصر عن حبش وأخبرني ذكاء وجه الرزة أنه سمع فيه لحنا للدلال من الثقيل الأول فلم يشكك سليمان أن الذي بها مما سمعت وأنها تهوى سميرا فوجه من وقته من أحضره وحبسه ودعا لها بسيف ونطع وقال والله لتصدقني أو لأضربن عنقك قالت سلني عما تريد قال أخبريني عما بينك وبين هذا الرجل قالت والله ما أعرفه ولا رأيته قط وأنا جارية منشأي الحجاز ومن هناك حملت إليك ووالله ما أعرف بهذه البلاد أحدا سواك فرق لها وأحضر الرجل فسأله وتلطف له في المسألة فلم يجد بينه وبينها سبيلا ولم تطب نفسه بتخليته سويا فخصاه وكتب في المخنثين بمثل ذلك هذه الرواية الصحيحة","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":3,"spl":"رواية أخرى عن سبب خصيه — نسبة هذا الصوت"},
{"id":"b39-7","bab":"الجزء 4","sec":"أسف ابن أبي عتيق والماجشون لخصائه","page":"ج4 ص272","text":"وقد أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار يقال حدثنا عمي قال\nقيل للوليد بن عبد الملك إن نساء قريش يدخل عليهن المخنثون بالمدينة وقد قال رسول الله ( لا يدخل عليكن هؤلاء\nفكتب إلى ابن حزم الأنصاري أن اخصهم فخصاهم فمر ابن أبي عتيق فقال أخصيتم الدلال أما والله لقد كان يحسن\n(لمن ربع بذات الجيش ... أمسى دارسا خلقا)\n(تأبد بعد ساكنه ... فأصبح أهله فرقا)\n(وقفت به أسائله ... ومرت عيسهم حزقا)\nم ذهب ثم رجع فقال إنما أعني خفيفة لست أعني ثقيله أخبرني الحسين بن يحيى عن حماد عن أبيه عن الواقدي عن ابن الماجشون أن خليفة صاحب الشرطة لما خصي المخنثون مر بأبيه الماجشون وهو في حلقته فصاح به تعال فجاءه فقال أخصيتم الدلال قال نعم قال أما إنه كان يجيد\n(لمن ربع بذات الجيش ... أمسى دارسا خلقا)\nم مضى غير بعيد فرده ثم قال أستغفر الله إنما أعني هزجه لا ثقيله","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":3,"spl":"رواية أخرى عن سبب خصيه — نسبة هذا الصوت"},
{"id":"b39-8","bab":"الجزء 4","sec":"أخبر له في المسجد","page":"ج4 ص273","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثني حمزة النوفلي قال صلى الدلال المخنث إلى جانبي في المسجد فضرط ضرطة هائلة سمعها\nمن في المسجد فرفعنا رؤوسنا وهو ساجد وهو يقول في سجوده رافعا بذلك صوته سبح لك أعلاي وأسفلي فلم يبق في المسجد أحد إلا فتن وقطع صلاته بالضحك أخبرني الحسين عن حماد عن أبيه عن المدائني عن أشياخه أن عبد الله بن جعفر قال لصديق له لو غنتك جاريتي فلانه\n(لمن ربع بذات الجيش ... أمسى دارسا خلقا)\nما أدركت دكانك فقال جعلت فداك قد وجبت جنوبها فكلوا منها وأطعموا البائس الفقير فقال عبد الله يا غلام مر فلانة أن تخرج فخرجت معها عودها فقال عبد الله إن هذا الشيخ يكره السماع فقالت ويحه لو كره الطعام والشراب كان أقرب له إلى الصواب فقال الشيخ فكيف ذاك وبهما الحياة فقالت إنهما ربما قتلا وهذا لا يقتل فقال عبد الله غني\n(لمن ربع بذات الجيش ... أمسى دارسا خلقا)\nغنت فجعل الشيخ يصفق ويرقص ويقول\n(هذا أوان الشد فاشتدي زيم ... )\nيحرك رأسه ويدور حتى وقع مغشيا عليه وعبد الله بن جعفر يضحك منه\nأخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة قال حدثني أبو غسان قال مر الغمر بن يزيد بن عبد الملك حاجا فغناه الدلال\n(بانت سعاد وأمسى حبلها انصرما ... واحتلت الغمر فالأجراع من إضما)\nفقال له الغمر أحسنت والله وغلبت فيه ابن سريج فقال له الدلال نعمة الله علي فيه أعظم من ذلك قال وما هي قال السمعة لا يسمعه أحد إلا علم أنه غناء مخنث حقا","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":3,"spl":"رواية أخرى عن سبب خصيه — نسبة هذا الصوت","partial":1},
{"id":"b39-9","bab":"الجزء 4","sec":"نسبة هذا الصوت","page":"ج4 ص275","text":"صوت بانت سعاد وأمسى حبلها انصرما ... واحتلت الغمر فالأجراع من إضما إحدى بلي وما هام الفؤاد بها ... إلا السفاه وإلا ذكرة حلما هلا سألت بني ذبيان ما حسبي ... إذا الدخان تغشى الأشمط البرما\nلشعر للنابغة الذبياني والغناء للدلال خفيف ثقيل أول بالوسطى عن\nالهشامي وفيه خفيف ثقيل بالبنصر لمعبد عن عمرو بن بانة وفيه لابن سريج ثقيل أول بالبنصر عن حبش وفيه لنشيط ثاني ثقيل بالبنصر عنه وذكر الهشامي أن لحن معبد ثقيل أول وذكر حماد أنه للغريض وفيه لجميلة ودحمان لحنان ويقال إنهما جميعا من الثقيل الأول أخبرني الحسين بن يحيى قال أخبرنا حماد بن إسحاق إجازة عن أبيه عن المدائني قال اختصم شيعي ومرجئ فجعلا بينهما أول من يطلع فطلع الدلال فقالا له أبا زيد أيهما خير الشيعي أم المرجئ فقال لا أردي إلا أن أعلاي شيعي وأسفلي مرجئ","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":3,"spl":"رواية أخرى عن سبب خصيه — نسبة هذا الصوت"},
{"id":"b39-10","bab":"الجزء 4","sec":"هروبه من المدينة إلى مكة","page":"ج4 ص276","text":"قال إسحاق قال المدائني وأخبرني أبو مسكين عن فليح بن سليمان قال كان الدلال ملازما لأم سعيد الأسلمية وبنت ليحيى بن الحكم بن أبي العاصي وكانتا من أمجن النساء كانتا تخرجان فتركبان الفرسين فتستبقان عليهما حتى تبدو خلاخيلهما فقال معاوية لمروان بن الحكم إكفني بنت أخيك فقال أفعل فاستزارها وأمر ببئر فحفرت في طريقها وغطيت بحصير فلما مشت عليه سقطت في البئر فكانت قبرها وطلب الدلال فهرب إلى مكة فقال له نساء أهل مكة قتلت نساء أهل المدينة وجئت لتقتلنا فقال والله ما قتلهن إلا\nالحكاك فقلن اعزب أخزاك الله ولا أدنى بك دارا ولا آذانا بك قال فمن لكن بعدي يدل على دائكن ويعلم موضع شفائكن والله ما زنيت قط ولا زني بي وإني لأشتهي ما تشتهي نساؤكم ورجالكم قال إسحاق وحدثني الواقدي عن ابن الماجشون قال كان أبي يعجبه الدلال ويستحسن غناءه ويدنيه ويقربه ولم أره أنا فسمعت أبي يقول غناني الدلال يوما بشعر مجنون بني عامر فلقد خفت الفتنة على نفسي فقلت يا أبت وأي شعر تغني قال قوله صوت\n(عسى الله أن يجري المودة بيننا ... ويوصل حبلا منكم بحباليا)\n(فكم من خليلي جفوة قد تقاطعا ... على الدهر لما أن أطالا التلاقيا)\n(وإني لفي كرب وأنت خلية ... لقد فارقت في الوصف حالك حاليا)\n(عتبت فما أعتبتني بمودة ... ورمت فما أسعفتني بسؤاليا)\nلغناء في هذا الشعر للغريض ثقيل أول بالوسطى ولا أعرف فيه لحنا غيره وذكر حماد في أخبار الدلال أنه للدلال ولم يجنسه قال إسحاق وحدثني الواقدي عن عثمان بن إبراهيم الحاطبي قال قدم مخنث من مكة يقال له مخة فجاء إلى الدلال فقال يا أبا زيد دلني على بعض مخنثي أهل المدينة أكايده وأمازحه ثم أجاذبه قال قد وجدته لك وكان خثيم بن عراك بن مالك صاحب شرطة زياد بن عبيد الله الحارثي جاره وقد\nخرج في ذلك الوقت ليصلي في المسجد فأومأ إلى خثيم فقال الحقه في المسجد فإنه يقوم فيه فيصلي ليرائي الناس فإنك ستظفر بما تريد منه فدخل المسجد وجلس إلى جنب ابن عراك فقال عجلي بصلاتك لا صلى الله عليك فقال خثيم سبحان الله فقال المخنث سبحت في جامعة قراصة انصرفي حتى أتحدث معك فانصرف خثيم من صلاته ودعا بالشرط والسياط فقال خذوه فأخذوه فضربه مائة وحبسه أخبرني الحسين عن حماد عن أبيه قال صلى الدلال يوما خلف الإمام بمكة فقرأ ( وما لي لا أعبد الذي فطرني وإليه ترجعون\nفقال الدلال لا أدري والله فضحك أكثر الناس وقطعوا الصلاة فلما قضى الوالي صلاته دعا به وقال له ويلك ألا تدع هذا المجون والسفه فقال له قد كان عندي أنك تعبد الله فلما سمعتك تستفهم ظننت أنك قد تشككت في ربك فثبتك فقال له أنا شككت في ربي وأنت ثبتني إذهب لعنك الله ولا تعاود فأبالغ والله في عقوبتك","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":4,"spl":"هروبه من المدينة إلى مكة — قصته مع رجل زوجه امرأة لم يدخل بها"},
{"id":"b39-11","bab":"الجزء 4","sec":"قصته مع رجل زوجه امرأة لم يدخل بها","page":"ج4 ص278","text":"قال إسحاق وحدثني الواقدي عن عثمان بن إبراهيم قال سأل رجل الدلال أن يزوجه امرأة فزوجه فلما أعطاها صداقها وجاء بها إليه فدخلت عليه قام إليها فواقعها فضرطت قبل أن يطأها فكسل عنها الرجل ومقتها وأمر بها فأخرجت وبعث إلى الدلال فعرفه ما جرى عليه فقال له الدلال فديتك هذا كله من عزة نفسها قال دعني منك فإني قد أبغضتها\nفاردد علي دراهمي فرد بعضها فقال له لم رددت بعضها وقد خرجت كما دخلت قال للروعة التي أدخلتها على استها فضحك وقال له اذهب فأنت أقضى الناس وأفقههم","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":4,"spl":"هروبه من المدينة إلى مكة — قصته مع رجل زوجه امرأة لم يدخل بها"},
{"id":"b39-12","bab":"الجزء 4","sec":"فتية من قريش يسقونه حتى يسكروه","page":"ج4 ص279","text":"أخبرني الحسن بن علي قال حدثنا أبو أيوب المديني قال حدثني محمد بن سلام عن أبيه قال وأخبرني به الحسين بن يحيى عن حماد عن أبيه عن محمد ابن سلام عن أبيه قال أن الدلال خرج يوما مع فتية من قريش في نزهة له وكان معهم غلام جميل الوجه فأعجبه وعلم القوم وعلم القوم بذلك فقالوا قد ظفرنا به بقية يومنا وكان لا يصبر في مجلس حتى ينقضي وينصرف عنه استثقالا لمحادثة الرجال ومحبة في محادثة النساء فغمزوا الغلام عليه وفطن لذلك فغضب وقام لينصرف فأقسم الغلام عليه والقوم جميعا فجلس وكان معهم شراب فشربوا وسقوه وحملوا عليه لئلا يبرح ثم سألوه أن يغنيهم فغناهم صوت\n(زبيرية بالعرج منها منازل ... وبالخيف من أدنى منازلها رسم)\n(أسائل عنها كل ركب لقيته ... ومالي بها من بعد مكتنا علم)\n(أيا صاحب الخيمات من بطن أرثد ... إلى النخل من ودان ما فعلت نعم)\n(فإن تك حرب بين قومي وقومها ... فإني لها في كل نائرة سلم)\nذكر يحيى المكي وعمرو بن بانة أن الغناء في هذا الشعر لمعبد ثاني ثقيل بالوسطى وذكر غيرهما أنه للدلال وفيه لمخارق رمل وذكر إسحاق هذا اللحن في طريقة الثقيل الثاني ولم ينسبه إلى أحد قال فاستطير القوم فرحا وسرورا وعلا نعيرهم فنذر بهم السلطان وتعادت الأشراط فأحسوا بالطلب فهربوا وبقي الغلام والدلال ما يطيقان براحا من السكر فأخذا فأتي بهما أمير المدينة فقال للدلال يا فاسق فقال له من فمك إلى السماء قال جؤوا فكه قال وعنقه أيضا قال يا عدو الله أما وسعك بيتك حتى خرجت بهذا الغلام إلى الصحراء تفسق به فقال لو علمت أنك تغار علينا وتشتهي أن نفسق سرا ما خرجت من بيتي قال جردوه واضربوه حدا قال وما ينفعك من ذلك وأنا والله أضرب في كل يوم حدودا قال ومن يتولى ذلك منك قال أيور المسلمين قال ابطحوه على وجهه واجلسوا على ظهره قال أحسب أن الأمير قد اشتهى أن يرى كيف أناك قال أقيموه لعنه الله واشهروه في المدينة مع الغلام فأخرجا يدار بهما في السكك فقيل له ما هذا يا دلال قال إشتهى الأمير أن يجمع بين الرأسين فجمع بيني وبين هذا الغلام ونادى علينا ولو قيل له الآن إنك قواد غضب فبلغ قوله الوالي فقال خلوا سبيلهما لعنة الله عليهما قال إسحاق في خبره خاصة ولم يذكره أبو أيوب فحدثني أبي عن ابن جامع عن سياط قال سمعت يونس يقول قال لي معبد ما ذكرت غناء الدلال في هذا الشعر\n(زبيرية بالعرج منها منازل ... )\nإلا جدد لي سرورا ولوددت أني كنت سبقته إليه لحسنه عندي قال يونس فقلت له ما بلغ من حسنه عندك قال يكفيك أني لم أسمع أحسن منه قط","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":5,"spl":"فتية من قريش يسقونه حتى يسكروه","partial":1},
{"id":"b39-13","bab":"الجزء 4","sec":"خبره هو وطويس والوليد مع عبد الرحمن بن حسان","page":"ج4 ص281","text":"أخبرني الحسين عن حماد عن أبيه عن الهيثم بن عدي عن صالح بن حسان قال كان بالمدينة عرس فاتفق فيه الدلال وطويس والوليد المخنث فدخل عبد الرحمن بن حسان فلما رآهم قال ما كنت لأجلس في مجلس فيه هؤلاء فقال له طويس قد علمت يا عبد الرحمن نكايتي فيك وأن جرحي إياك لم يندمل يعني خبره معه بحضرة عبد الله بن جعفر وذكره لعمته الفارعة فاربح نفسك وأقبل على شأنك فإنه لا قيام لك بمن يفهمك فهمي وقال له الدلال يا أخا الأنصار إن أبا عبد النعيم أعلم بك مني وسأعلمك بعض ما أعلم به ثم اندفع ونقر بالدف وكلهم ينقر بدفه معه فتغنى صوت\n(أتهجر يا إنسان من أنت عاشقه ... ومن أنت مشتاق إليه وشائقه)\n(وريم أحم المقلتين موشح ... زرابيه مبثوثة ونمارقه)\n(ترى الرقم والديباج في بيته معا ... كما زين الروض الأنيق حدائقه)\n(وسرب ظباء ترتعي جانب الحمى ... إلى الجو فالخبتين بيض عقائقه)\n(وما من حمى في الناس إلا لنا حمى ... إلا لنا غربيه ومشارقه)\nفاستضحك عبد الرحمن وقال اللهم غفرا وجلس\nلحن الدلال في هذه الأبيات هزج بالبنصر عن يحيى المكي وحماد أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبد الله الجمحي عن محمد بن عثمان عن عبدالرحمن بن الحارث بن هشام قال سمعت عمي عتبة يقول حدثني مولى للوليد بن عبد الملك قال كان الدلال ظريفا جميلا حسن البيان من أحضر الناس جوابا وأحجهم وكان سليمان بن عبد الملك قد رق له حين خصي غلطا فوجه إليه مولى له وقال له جئني به سرا وكانت تبلغه نوادره وطيبه وحذر رسوله أن يعلم بذلك أحد فنفذ المولى إليه وأعلمه ما أمره به وأمره بالكتمان وحذر أن يقف على مقصده أحد ففعل وخرج به إلى الشام فلما قدم أنزله المولى منزله وأعلم سليمان بمكانه فدعا به ليلا فقال ويلك ما خبرك فقال جببت من القبل مرة أخرى يا أمير المؤمنين فهل تريد أن تجبني المرة من الدبر فضحك وقال اعزب أخزاك الله ثم قال له غن فقال لا أحسن إلا بالدف فأمر فأتي له بدف فغنى في شعر العرجي\n(أفي رسم دار دمعك المتحدر ... سفاها وما استنطاق ما ليس يخبر)\n(تغير ذاك الربع من بعد جدة ... وكل جديد مرة متغير)\n(لأسماء إذ قلبي بأسماء مغرم ... وما ذكر أسماء الجميلة مهجر)\n(وممشى ثلاث بعد هدء كواعب ... كمثل الدمى بل هن من ذاك أنضر)\n(فسلمن تسليما خفيا وسقطت ... مصاعبة ظلع من السير حسر)\n(لها أرج من زاهر البقل والثرى ... وبرد إذا ما باشر الجلد يخصر)\n(فقالت لتربيها الغداة تبقيا ... بعين ولا تستبعدا حين أبصر)\n(ولا تظهرا برديكما وعليكما ... كساءان من خز بنقش وأخضر)\n(فعدي فما هذا العتاب بنافع ... هواي ولا مرجي الهوى حين يقصر)\nقال له سليمان حق لك يا دلال أن يقال لك الدلال أحسنت وأجملت فوالله ما أدري أي أمريك أعجب أسرعة جوابك وجودة فهمك أم حسن غنائك بل جميعا عجب وأمر له بصلة سنية فأقام عنده شهرا يشرب على غنائه ثم سرحه إلى الحجاز مكرما","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":6,"spl":"خبره هو وطويس والوليد مع عبد الرحمن بن حسان"},
{"id":"b39-14","bab":"الجزء 4","sec":"قصة الشامي الذي أراد أن يتزوج من المدينة","page":"ج4 ص283","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن الأصمعي قال حج هشام بن عبد الملك فلما قدم المدينة نزل رجل من أشراف أهل الشأم وقوادهم بجنب دار الدلال فكان الشامي يسمع غناء الدلال ويصغي إليه ويصعد فوق السطح ليقرب من الصوت ثم بعث إلى الدلال إما أن تزورنا وإما أن نزورك فبعث إليه الدلال بل تزورنا فتهيأ الشامي ومضى إليه وكان للشامي غلمان روقة فمضى معه بغلامين منهم كأنهما درتان فغناه الدلال\n(قد كنت آمل فيكم أملا ... والمرء ليس بمدرك أمله)\n(حتى بدا لي منكم خلف ... فزجرت قلبي عن هوى جهله)\n(ليس الفتى بمخلد أبدا ... حقا وليس بفائت أجله)\n(حي العمود ومن بعقوته ... وقفا العمود وإن جلا أهله)\nال فاستحسن الشامي غناءه وقال له زدني فقال أو ما يكفيك ما سمعت قال لا والله ما يكفيني قال فإن لي إليك حاجة قال وما هي قال تبيعني أحد هذين الغلامين أو كليهما قال اختر أيهما شئت فاختار أحدهما فقال الشامي هو لك فقبله الدلال ثم غناه\n(دعتني دواع من أريا فهيجت ... هوى كان قدما من فؤاد طروب)\n(لعل زمانا قد مضى أن يعود لي ... فتغفر أروى عند ذاك ذنوبي)\n(سبتني أريا يوم نعف محسر ... بوجه جميل للقلوب سلوب)\nقال له الشامي أحسنت ثم قال له أيها الرجل الجميل إن لي إليك حاجة قال وما هي قال أريد وصيفة ولدت في حجر صالح ونشأت في خير جميلة الوجه مجدولة وضيئة جعدة في بياض مشربة حمرة حسنة القامة سبطة أسيلة الخد عذبة اللسان لها شكل ودل تملأ العين والنفس فقال له الدلال قد أصبتها لك فما لي عليك إن دللتك قال غلامي هذا قال إذا رأيتها وقبلتها فالغلام لي قال نعم فأتى امرأة كنى عن اسمها فقال لها جعلت فداك إنه نزل بقربي رجل من أهل الشأم من قواد هشام له ظرف وسخاء وجاءني زائرا فأكرمته ورأيت معه غلامين كأنهما الشمس الطالعة والقمر المنير والكواكب الزاهرة ما وقعت عيني على مثلهما ولا ينطلق لساني بوصفهما فوهب\nلي أحدهما والآخر عنده وإن لم يصل إلي فنفسي خارجة قالت فتريد ماذا قال طلب مني وصيفة يشتريها على صفة لا أعلمها في أحد إلا في فلانة بنتك فهل لك أن تريها له قالت وكيف لك بأن يدفع الغلام إليك إذا رآها قال فإني قد شرطت عليه ذلك عند النظر لا عند البيع قالت فشأنك ولا يعلم أحد بذلك فمضى الدلال فجاء الشامي معه فلما صار إلي المرأة أدخلته فإذا هو بحجلة وفيها امرأة على سرير مشرف برزة جميلة فوضع له كرسي فجلس فقالت له أمن العرب أنت قال نعم قالت من أيهم قال من خزاعة قالت مرحبا بك وأهلا أي شيء طلبت فوصف الصفة فقالت أصبتها وأصغت إلى جارية لها فدخلت فمكثت هنيهة ثم خرجت فنظرت إليها المرأة فقالت لها أي حبيبتي أخرجي فخرجت وصيفة ما رأى الراؤون مثلها فقالت لها أقبلي فأقبلت ثم قالت لها أدبري فأدبرت تملأ العين والنفس فما بقي منها شيء إلا وضع يده عليه فقالت أتحب أن نؤزرها لك قال نعم قالت أي حبيبتي ائتزري فضمها الإزار وظهرت محاسنها الخفية وضرب بيده على عجيزتها وصدرها ثم قالت أتحب أن نجردها لك قال نعم قالت أي حبيبتي وضحي فألقت إزارها فإذا أحسن خلق الله كأنها سبيكة فقالت يا أخا أهل الشأم كيف رأيت قال منية المتمني قال بكم تقولين قالت ليس يوم النظر يوم البيع ولكن تعود غدا حتى نبايعك ولا تنصرف إلا على الرضا فانصرف من عندها فقال له الدلال أرضيت قال نعم ما كنت أحسب أن مثل هذه في الدنيا فإن الصفة لتقصر دونها ثم دفع إليه الغلام الثاني فلما كان من الغد قال له الشامي امض بنا فمضيا حتى قرعا الباب فأذن لهما فدخلا وسلما ورحبت المرأة بهما ثم قالت للشامي اعطنا ما تبذل قال ما لها عندي ثمن إلا وهي أكبر منه فقولي يا أمة الله قالت بل قل فإنا لم نوطئك أعقابنا ونحن نريد خلافك وأنت لها رضا قال ثلاثة آلاف دينار فقالت والله لقبلة من هذه خير من ثلاثة آلاف دينار قال","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":7,"spl":"قصة الشامي الذي أراد أن يتزوج من المدينة"},
{"id":"b39-15","bab":"الجزء 4","sec":"قصة الشامي الذي أراد أن يتزوج من المدينة","page":"ج4 ص283","text":"بأربعة آلاف دينار قالت غفر الله لك أعطنا أيها الرجل قال والله ما معي غيرها ولو كان لزدتك إلا رقيق ودواب وخرثي أحمله إليك قالت ما أراك إلا صادقا أتدري من هذه قال تخبريني قالت هذه ابنتي فلانة بنت فلان وأنا فلانة بنت فلان وقد كنت أردت أن أعرض عليك وصيفة عندي فأحببت إذا رأيت غدا غلظ أهل الشأم وجفاءهم ذكرت ابنتي فعلمت أنكم في غير شيء قم راشدا فقال للدلال خدعتني قال أولا ترضى أن ترى ما رأيت من مثلها وتهب مائة غلام مثل غلامك قال أما هذا فنعم وخرجا من عندها","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":8,"spl":"قصة الشامي الذي أراد أن يتزوج من المدينة — نسبة ما عرفت نسبته من الغناء المذكور في هذا الخ"},
{"id":"b39-16","bab":"الجزء 4","sec":"نسبة ما عرفت نسبته من الغناء المذكور في هذا الخبر","page":"ج4 ص286","text":"صوت\n(قد كنت آمل فيكم أملا ... والمرء ليس بمدرك أمله)\n(حتى بدا لي منكم خلف ... فزجرت قلبي عن هوى جهله)\nلشعر للمغيرة بن عمرو بن عثمان والغناء للدلال ولحنه من القدر الأوسط من الثقيل الأول بالبنصر في مجراها وجدته في بعض كتب إسحاق بخط يده هكذا وذكر علي بن يحيى المنجم أن هذا اللحن في هذه الطريقة لابن سريج وأن لحن الدلال خفيف ثقيل نشيد وذكر أحمد بن المكي أن لحن الدلال ثاني ثقيل بالوسطى ولحن ابن سريج ثقيل أول وفيه لمتيم وعريب لميتم خفيفا ثقيل المطلق المسجح منهما لعريب ومنها\nصوت\n(دعتني دواع من أريا فهيجت ... هوى كان قدما من فؤاد طروب)\n(سبتني أريا يوم نعف محسر ... بوجه صبيح للقلوب سلوب)\n(لعل زمانا قد مضى أن يعود لي ... وتغفر أروى عند ذاك ذنوبي)\nلغناء للدلال خفيف ثقيل أول بالوسطى في مجراها من رواية حماد عن أبيه وذكر يحيى المكي أنه لابن سريج أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي قبيصة قال جاء الدلال يوما إلى منزل نائلة بنت عمار الكلبي وكانت عند معاوية فطلقها فقرع الباب فلم يفتح له فغنى في شعر مجنون بني عامر ونقر بدفه\n(خليلي لا والله ما أملك البكا ... إذا علم من أرض ليلى بدا ليا)\n(خليلي إن بانوا بليلى فهيئا ... لي النعش والأكفان واستغفرا ليا)\nخرج حشمها فزجروه وقالوا تنح عن الباب وسمعت الجلبة فقالت ما هذه الضجة بالباب فقالوا الدلال فقالت ائذنوا له فلما دخل عليها شق ثيابه وطرح التراب على رأسه وصاح بويله وحربه فقالت له الويل ويلك ما دهاك وما أمرك قال ضربني حشمك قال ولم قال غنيت صوتا أريد أن أسمعك إياه لأدخل إليك فقالت أف لهم وتف نحن نبلغ لك ما تحب ونحسن تأديبهم يا جارية هاتي ثيابا مقطوعة فلما طرحت عليه جلس فقالت ما حاجتك قال لا أسألك حاجة حتى أغنيك قال فذاك إليك فاندفع يغني شعر جميل\n(ارحميني فقد بليت فحسبي ... بعض ذا الداء يا بثينة حسبي)\n(لامني فيك يا بثنية صحبي ... لا تلوموا قد أقرح الحب قلبي)\n(زعم الناس أن دائي طبي ... أنت والله يا بثنية طبي)\nثم جلس فقال هل من طعام قالت علي بالمائدة فأتي بها كأنها كانت مهيأة عليها أنواع الأطعمة فأكل ثم قال هل من شراب قالت أما نبيذ فلا ولكن غيره فأتي بأنواع الأشربة فشرب من جميعها ثم قال هل من فاكهة فأتي بأنواع الفواكه فتفكه ثم قال حاجتي خمسة آلاف درهم وخمس حلل من حلل معاوية وخمس حلل من حلل حبيب بن مسلمة وخمس حلل من حلل النعمان بن بشير فقالت وما أردت بهذا قال هو ذاك والله ما أرضى ببعض دون بعض فإما الحاجة وإما الرد فدعت له بما سأل فقبضه وقام فلما توسط الدار غنى ونقر بدفه\n(ليت شعري أجفوة أم دلال ... أم عدو أتى بثينة بعدي)\n(فمريني أطعك في كل أمر ... أنت والله أوجه الناس عندي)\nكانت نائلة عند معاوية فقال لفاختة بنت قرظة إذهبي فانظري إليها فذهبت فنظرت إليها فقالت له ما رأيت مثلها ولكني رأيت تحت سرتها خالا ليوضعن منه رأس زوجها في حجرها فطلقها معاوية فتزوجها بعده رجلان أحدهما حبيب بن مسلمة والآخر النعمان بن بشير فقتل أحدهما فوضع رأسه في حجرها","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":8,"spl":"قصة الشامي الذي أراد أن يتزوج من المدينة — نسبة ما عرفت نسبته من الغناء المذكور في هذا الخ"},
{"id":"b39-17","bab":"الجزء 4","sec":"نسبة ما في هذا الخبر من الأغاني","page":"ج4 ص289","text":"صوت\n(خليلي لا والله ما أملك البكا ... إذا علم من أرض ليلى بداليا)\n(خليلي إن بانوا بليلى فهيئا ... لي النعش والأكفان واستغفراليا)\n(أمضروبة ليلى على أن أزورها ... ومتخذ ذنبا لها أن ترانيا)\n(خليلي لا والله ما أملك الذي ... قضى الله في ليلى ولا ما قضى ليا)\n(قضاها لغيري وابتلاني بحبها ... فهلا بشيء غير ليلى ابتلانيا)\nلشعر للمجنون والغناء لابن محرز ثاني ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وذكر الهشامي أن فيه لحنا لمعبد ثقيل أول لا يشك فيه قال وقد قال قوم إنه منحول يحيى المكي وفيه لإبراهيم خفيف ثقيل عن الهشامي أيضا وفيه ليحيى المكي رمل من رواية ابنه أحمد وفيه خفيف رمل عن أحمد بن عبيد لا يعرف صانعه ومنها صوت\n(ليت شعري أجفوة أم دلال ... أم عدو أتى بثينة بعدي)\n(فمريني أطعك في كل أمر ... أنت والله أوجه الناس عندي)\nلشعر لجميل والغناء لابن محرز خفيف ثقيل بالسبابة في مجرى البنصر عن إسحاق وفيه لعلويه خفيف ثقيل آخر وذكر عمرو بن بانة أن فيه خفيف ثقيل بالوسطى لمعبد وذكر إسحاق أن فيه رملا بالبنصر في مجراها ولم ينسبه إلى أحد وذكر الهشامي أنه لمالك وفيه لمتيم خفيف رمل وفيه لعريب ثقيل أول بالبنصر وذكر حبش أن فيه للغريض ثقيلا أول بالبنصر ولمعبد فيه ثقيل أول بالوسطى وذكر ابن المكي أن فيه خفيف ثقيل لمالك وعلويه","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":9,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة ما في هذا الخبر من الغناء"},
{"id":"b39-18","bab":"الجزء 4","sec":"غناؤه في زفاف ابنة عبد الله بن جعفر","page":"ج4 ص290","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن المدائني عن عوانة بن الحكم قال لما أراد عبد الله بن جعفر إهداء بنته إلى الحجاج كان ابن أبي عتيق عنده فجاءه الدلال متعرضا فاستأذن فقال له ابن جعفر لقد جئتنا يا دلال في وقت حاجتنا إليك قال ذلك قصدت فقال له ابن أبي عتيق غننا فقال ابن جعفر ليس وقت ذلك نحن في شغل عن هذا فقال ابن أبي عتيق ورب الكعبة ليغنين فقال له ابن جعفر هات فغنى ونقر بالدف والهوادج والرواحل قد هيئت وصيرت بنت ابن جعفر فيها مع جواريها والمشيعين لها\n(يا صاح لو كنت عالما خبرا ... بما يلاقي المحب لم تلمه)\n(لا ذنب لي في مقرط حسن ... أعجبني دله ومبتسمه)\n(شيمته البخل والبعاد لنا ... يا حبذا هو وحبذا شيمه)\n(مضمخ بالعبير عارضه ... طوبى لمن شمه ومن لثمه)\nال ولابن محرز في هذا الشعر لحن أجود من لحن الدلال فطرب ابن جعفر وابن أبي عتيق وقال له ابن جعفر زدني وطرب فأعاد اللحن ثلاثا ثم غنى\n(بكر العواذل في الصباح ... يلمنني وألومهنه)\n(ويقلن شيب قد علاك ... وقد كبرت فقلت إنه)\nومضت بنت ابن جعفر فاتبعها يغنيها بهذا الشعر ولعبد آل الهذلي فيه لحن وهو أحسنها\n(إن الخليط أجد فاحتملا ... وأراد غيظك بالذي فعلا)\n(فوقفت أنظر بعض شأنهم ... والنفس مما تأمل الأملا)\n(وإذا البغال تشد صافنة ... وإذا الحداة قد ازمعوا الرحلا)\n(فهناك كاد الشوق يقتلني ... لو أن شوقا قبله قتلا)\nدمعت عينا عبد الله بن جعفر وقال للدلال حسبك فقد أوجعت قلبي وقال لهم امضوا في حفظ الله على خير طائر وأيمن نقيبة","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":9,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة ما في هذا الخبر من الغناء"},
{"id":"b39-19","bab":"الجزء 4","sec":"نسبة ما في هذا الخبر من الغناء","page":"ج4 ص291","text":"صوت\n(بكر العواذل في الصباح ... يلمنني وألومهنه)\n(ويقلن شيب قد علاك ... وقد كبرت فقلت إنه)\n(لا بد من شيب فدعن ... ولا تطلن ملامكنه)\n(يمشين كالبقر الثقال ... عمدن نحو مراحهنه)\n(يحفين في الممشى القريب ... إذا يردن صديقهنه)\nلشعر لابن قيس الرقيات والغناء لابن مسجح خفيف ثقيل أول بالسبابة\nفي مجرى البنصر عن إسحاق وفيه ثقيل أول للغريض عن الهشامي وفيه خفيف ثقيل آخر بالوسطى ليعقوب بن هبار عن الهشامي ودنانير وذكر حبش أنه ليعقوب ومنها صوت\n(إن الخليط أجد فاحتملا ... وأراد غيظك بالذي فعلا)\nالأبيات الأربعة الشعر لعمر بن أبي ربيعة والغناء للغريض ثقيل أول بالسبابة عن يحيى المكي وفيه ليحيى أيضا ثقيل أول بالوسطى من رواية أحمد ابنه وذكر حبش أن هذا اللحن لبسباسة بنت معبد","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":9,"spl":"نسبة ما في هذا الخبر من الأغاني — نسبة ما في هذا الخبر من الغناء"},
{"id":"b39-20","bab":"الجزء 4","sec":"غنى شعرا لعمر بن أبي ربيعة فأجازه","page":"ج4 ص292","text":"أخبرني الحسين عن حماد عن أبيه عن عثمان بن حفص الثقفي قال كان للدلال صوت يغني به ويجيده وكان عمر بن أبي ربيعة سأله الغناء فيه وأعطاه مائة دينار ففعل وهو قول عمر صوت\n(ألم تسأل الأطلال والمتربعا ... ببطن حليات دوارس بلقعا)\n(إلى السرح من وادي المغمس بدلت ... معالمه وبلا ونكباء زعزعا)\n(وقربن أسباب الهوى بمتيم ... يقيس ذراعا كلما قسن أصبعا)\n(فقلت لمطريهن في الحسن إنما ... ضررت فهل تسطيع نفعا فتنفعا)\nلشعر لعمر بن أبي ربيعة والغناء للغريض فيه لحنان أحدهما في الأول والثاني من الأبيات ثقيل أول بالبنصر عن عمرو والآخر في الثالث والرابع ثاني ثقيل بالبنصر وفي هذين البيتين الآخرين لابن سريج ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفي الأول والثاني للهذلي خفيف ثقيل أول بالوسطى عن عمرو وفيهما لابن جامع رمل بالوسطى عنه أيضا وقال يونس لمالك فيه لحنان ولمعبد لحن واحد أخبرني الحسين عن حماد عن أبيه قال حدثني هشام بن المرية قال كنا نعرف للدلال صوتين عجيبين وكان جرير يغني بهما فأعجب من حسنهما فأخذتهما عنه وأنا أغني بهما فأما أحدهما فإنه يفرح القلب والآخر يرقص كل من سمعه فأما الذي يفرح القلب فلابن سريج فيه أيضا لحن حسن وهو\n(ولقد جرى لك يوم سرحة مالك ... مما تعيف سانح وبريح)\nأحوى القوادم بالبياض ملمع ... قلق المواقع بالفراق يصيح الحب أبغضه إلي أقله ... صرح بذاك فراحتي التصريح بانت عويمة فالفؤاد قريح ... ودموع عينك في الرداء سفوح\nالآخر\n(كلما أبصرت وجها ... حسنا قلت خليلي)\n(فإذا ما لم يكنه ... صحت ويلي وعويل)\n(فصلي حبل محب ... لكم جد وصول)\n(وانظري لا تخذليه ... إنه غير خذول)","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":10,"spl":"غنى شعرا لعمر بن أبي ربيعة فأجازه — شرب الخمرة وسكر فخلع ثيابه"},
{"id":"b39-21","bab":"الجزء 4","sec":"نسبة هذين الصوتين","page":"ج4 ص293","text":"للدلال في الشعر الأول الذي أوله\n(ولقد جرى لك يوم سرحة مالك ... )\nفيف ثقيل بالوسطى وفيه لابن سريج ثقيل أول عن الهشامي وقال حبش إن للدلال فيه لحنين خفيف ثقيل أول وخفيف رمل وأول خفيف الرمل\n(بانت عويمة فالفؤاد قريح ... )\nكر أن لحن ابن سريج ثاني ثقيل وأن لابن مسجح فيه أيضا خفيف ثقيل والصوت الثاني الذي أوله\n(كلما أبصرت وجها ... حسنا قلت خليلي)\nلغناء فيه لعطرد خفيف ثقيل بالوسطى عن حبش ويقال إنه للدلال وفيه ليونس خفيف رمل وفيه لإبراهيم الموصلي خفيف ثقيل أول بالبنصر عن عمرو","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":10,"spl":"غنى شعرا لعمر بن أبي ربيعة فأجازه — شرب الخمرة وسكر فخلع ثيابه","partialRef":{"sid":"b39-20","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b39-22","bab":"الجزء 4","sec":"شرب الخمرة وسكر فخلع ثيابه","page":"ج4 ص294","text":"أخبرني الحسين عن حماد عن أبيه عن مصعب بن عبد الله الزبيري قال كان الدلال لا يشرب النبيذ فخرج مع قوم إلى متنزه لهم ومعهم نبيذ فشربوا ولم يشرب منه وسقوه عسلا مجدوحا وكان كلما تغافل صيروا في\nشرابه النبيذ فلا ينكره وكثر ذلك حتى سكر وطرب وقال اسقوني من شرابكم فسقوه حتى ثمل وغناهم في شعر الأحوص\n(طاف الخيال وطاف الهم فاعتكرا ... عند الفراش فبات الهم محتضرا)\n(أراقب النجم كالحيران مرتقبا ... وقلص النوم عن عيني فانشمرا)\n(من لوعة أورثت قرحا على كبدي ... يوما فأصبح منها القلب منفطرا)\n(ومن يبت مضمرا هما كما ضمنت ... مني الضلوع يبت مستبطنا غيرا)\nاسحتسنه القوم وطربوا وشربوا ثم غناهم\n(طربت وهاجك من تدكر ... ومن لست من حبه تعتذر)\n(فإن نلت منها الذي أرتجي ... فذاك لعمري الذي أنتظر)\n(وإلا صبرت فلا مفحشا ... عليها بسوء ولا مبتهر)\nحن الدلال في هذا الشعر خفيف ثقيل أول بالبنصر عن حبش قال وذكر قوم أنه للغريض قال وسكر حتى خلع ثيابه ونام عريانا فغطاه القوم بثيابهم وحملوه إلى منزله ليلا فنوموه وانصرفوا عنه فأصبح وقد تقيأ ولوث ثيابه بقيئه فأنكر نفسه وحلف ألا يغني أبدا ولا يعاشر من يشرب النبيذ فوفى بذلك إلى أن مات وكان يجالس المشيخة والأشراف فيفيض معهم في أخبار الناس وأيامهم حتى قضى نحبه انقضت أخبار الدلال","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":10,"spl":"غنى شعرا لعمر بن أبي ربيعة فأجازه — شرب الخمرة وسكر فخلع ثيابه"},
{"id":"b39-23","bab":"الجزء 4","sec":"ومما في شعر الأحوص من المائة المختارة صوت من المائة المختارة","page":"ج4 ص296","text":"(يا دين قلبك منها لست ذاكرها ... إلا ترقرق ماء العين أو دمعا)\n(أدعو إلى هجرها قلبي فيتبعني ... حتى إذا قلت هذا صادق نزعا)\n(لا أستطيع نزوعا عن محبتها ... أو يصنع الحب بي فوق الذي صنعا)\n(كم من دني لها قد صرت أتبعه ... ولو سلا القلب عنها صار لي تبعا)\n(وزادنى كلفا في الحب أن منعت ... وحب شيء إلى الإنسان ما منعا)\nلشعر للأحوص والغناء ليحيى بن واصل المكي وهو رجل قليل الصنعة غير مشهور ولا وجدت له خبرا فأذكره ولحنه المختار ثقيل أول بالوسطى في مجراها عن إسحاق وذكر يونس أن فيه لحنا لمعبد ولم يجنسه أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا مطرف بن عبد الله المدني قال حدثني أبي عن جدي قال بينا أطوف بالبيت ومعي أبي إذا بعجوز كبيرة يضرب أحد لحييها الآخر فقال لي أبي أتعرف هذه قلت لا ومن هي قال هذه التي يقول فيها الأحوص\n(يا سلم ليت لسانا تنطقين به ... قبل الذي نالني من حبكم قطعا)\n(يلومني فيك أقوام أجالسهم ... فما أبالي أطار اللوم أم وقعا)\n(أدعو إلى هجرها قلبي فيتبعني ... حتى إذا قلت هذا صادق نزعا)\nقال فقلت له يا أبت ما أرى أنه كان في هذه خير قط فضحك ثم قال يا بني هكذا يصنع الدهر بأهله حدثنا به وكيع قال حدثنا ابن أبي سعد قال حدثنا إبراهيم بن المنذر قال حدثنا أبو خويلد مطرف بن عبد الله المدني عن أبيه ولم يقل عن جده وذكر الخبر مثل الذي قبله صوت من المائة المختارة\n(كالبيض بالأدحي يلمع في الضحى ... فالحسن حسن والنعيم نعيم)\n(حلين من در البحور كأنه ... فوق النحور إذا يلوح نجوم)\nلأدحي المواضع التي يبيض فيها النعام واحدتها أدحية وذكر أبو عمرو الشيباني أن الأدحي البيض نفسه ويقال فيه أدحي وأداح أيضا الشعر لطريح بن إسماعيل الثقفي والغناء لأبي سعيد مولى فائد ولحنه المختار من الثقيل الأول بإطلاق الوتر في مجرى الوسطى عن إسحاق وفيه للهذلي خفيف ثقيل من رواية الهشامي وقد سمعنا من يغني فيه لحنا من خفيف الرمل ولست أعرف لمن هو","topic":"ذكر الدلال وقصته حين خصي ومن خصي معه والسبب في ذلك وسائر أخباره","topicNo":39,"sp":11,"spl":"ومما في شعر الأحوص من المائة المختارة صوت من المائة المختارة"},
{"id":"b40-1","bab":"الجزء 4","sec":"ذكر طريح وأخباره ونسبه","page":"ج4 ص297","text":"هو فيما أخبرني به محمد بن الحسن بن دريد عن عمه عن ابن الكلبي في كتاب النسب إجازة وأخبرنا يحيى بن علي بن يحيى عن أبي أيوب المديني عن ابن عائشة ومحمد بن سلام ومصعب الزبيري قال طريح بن إسماعيل بن عبيد بن أسيد بن علاج بن أبي سلمة بن عبد العزى بن عنزة بن عوف بن قسي وهو ثقيف بن منبه بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس ابن عيلان بن مضر","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":0,"spl":"ذكر طريح وأخباره ونسبه"},
{"id":"b40-2","bab":"الجزء 4","sec":"الخلاف في نسب ثقيف","page":"ج4 ص298","text":"قال ابن الكلبي ومن النسابين من يذكر أن ثقيفا هو قسي بن منبه بن النبيت ابن منصور بن يقدم بن أفصى بن دعمي بن إياد بن نزار ويقال إن ثقيفا كان عبدا لأبي رغال وكان أصله من قوم نجوا من ثمود فانتمى بعد ذلك إلى قيس وروي عن علي بن أبي طالب رضي الله تعالى عنه وكرم وجهه أنه مر بثقيف فتغامزوا به فرجع إليهم فقال لهم يا عبيد أبي رغال إنما كان أبوكم عبدا له فهرب منه فثقفه بعد ذلك ثم انتمى إلى قيس وقال الحجاج في خبطة خطبها بالكوفة بلغني أنكم تقولون إن ثقيفا من\nبقية ثمود ويلكم وهل نجا من ثمود إلا خيارهم ومن آمن بصالح فبقي معه عليه السلام ثم قال قال الله تعالى ( وثمود فما أبقى\nبلغ ذلك الحسن البصري فتضاحك ثم قال حكم لكع لنفسه إنما قال عز و جل ( فما أبقى\nأي لم يبقهم بل أهلكهم فرفع ذلك إلى الحجاج فطلبه فتوارى عنه حتى هلك الحجاج وهذا كان سبب تواريه منه ذكر ابن الكلبي أنه بلغه عن الحسن وكان حماد الراوية يذكر أن أبا رغال أبو ثقيف كلها وأنه من بقية ثمود وأنه كان ملكا بالطائف فكان يظلم رعيته فمر بامرأة ترضع صبيا يتيما بلبن عنز لها فأخذها منها وكانت سنة مجدبة فبقي الصبي بلا مرضعة فمات فرماه الله بقارعة فأهلكه فرجمت العرب قبره وهو بين مكة والطائف وقيل بل كان قائد الفيل ودليل الحبشة لما غزوا الكعبة فهلك فيمن هلك منهم فدفن بين مكة والطائف فمر النبي بقبره فأمر برجمه فرجم فكان ذلك سنة قال ابن الكلبي وأخبرني أبي عن أبي صالح عن ابن عباس قال كان ثقيف والنخع من إياد فثقيف قسي بن منبه بن النبيت بن يقدم بن أقصى بن دعمي بن إياد والنخع بن عمرو بن الطمنان بن عبد مناة بن يقدم بن\nأقصى فخرجا ومعهما عنز لهما لبون يشربان لبنها عرض لهما مصدق لملك اليمن فأراد أخذها فقالا له إنما نعيش بدرها فأبى أن يدعها فرماه أحدهما فقتله ثم قال لصاحبه إنه لا يحملني وإياك أرض فأما النخع فمضى إلى بيشة فأقام بها ونزل القسي موضعا قريبا من الطائف فرأى جارية ترعى غنما لعامر بن الظرب العدواني فطمع فيها وقال أقتل الجارية ثم أحوي الغنم فأنكرت الجارية منظره فقالت له إني أراك تريد قتلي وأخذ الغنم وهذا شيء إن فعلته قتلت وأخذت الغنم منك وأظنك غريبا جائعا فدلته على مولاها فأتاه واستجار به فزوجه بنته وأقام بالطائف فقيل لله دره من أثقفه حين ثقف عامرا فأجاره وكان قد مر بيهودية بوادي القرى حين قتل المصدق فأعطته قضبان كرم فغرسها بالطائف فأطعمته ونفعته قال ابن الكلبي في خبر طويل ذكره كان قسي مقيما باليمن فضاق عليه موضعه ونبا به فأتى الطائف وهو يومئذ منازل فهم وعدوان ابني عمرو بن قيس ابن عيلان فانتهى إلى الظرب العدواني وهو أبو عامر بن الظرب فوجده نائما تحت شجرة فأيقظه وقال من أنت قال أنا الظرب قال علي ألية إن لم أقتلك أو تحالفني وتزوجني ابنتك ففعل وانصرف الظرب وقسي معه فلقيه ابنه عامر بن الظرب فقال من هذا معك يا أبت فقص قصته قال عامر لله أبوه لقد ثقف أمره فسمي يومئذ ثقيفا قال وعير الظرب تزويجه قسيا وقيل\nزوجت عبدا فسار إلى الكهان يسألهم فانتهى إلى شق بن صعب البجلي وكان أقربهم منه فلما انتهى إليه قال إنا قد جئناك في أمر فما هو قال جئتم في قسي وقسي عبد إياد أبق ليلة الواد في وج ذات الأنداد فوالى سعدا ليفاد ثم لوى بغير معاد يعني سعد بن قيس بن عيلان بن مضر قال ثم توجه إلى سطيح الذئبي حي من غسان ويقال إنهم حي من قضاعة نزول في غسان فقال إنا جئناك في أمر فما هو قال جئتم في قسي وقسي من ولد ثمود القديم ولدته أمه بصحراء بريم فالتقطه إياد وهو عديم فاستعبده وهو مليم فرجع الظرب وهو لا يدري ما يصنع في أمره وقد وكد عليه في الحلف والتزويج وكانوا على كفرهم يوفون بالقول فلهذا يقول من قال إن ثقيفا من ثمود لأن إيادا من ثمود قال وقد قيل إن حربا كانت بين إياد وبين قيس وكان رئيسهم عامر بن الظرب فظفرت بهم قيس فنفتهم إلى ثمود وأنكروا أن يكونوا من نزار قال وقال عامر بن الظرب في ذلك\n(قالت إياد قد رأينا نسبا ... في ابني نزار ورأينا غلبا)\n(سيري إياد قد رأينا عجبا ... لا أصلكم منا فسامي الطلبا)\n(دار ثمود إذ رأيت السببا ... )\nال وقد روي عن الأعمش أن علي بن أبي طالب رضي الله تعالى عنه","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":1,"spl":"الخلاف في نسب ثقيف","partial":1},
{"id":"b40-3","bab":"الجزء 4","sec":"الخلاف في نسب ثقيف","page":"ج4 ص298","text":"قال على المنبر بالكوفة وذكر ثقيفا لقد هممت أن أضع على ثقيف الجزية لأن ثقيفا كان عبدا لصالح نبي الله وإنه سرحه إلى عامل له على الصدقة فبعث العامل معه بها فهرب واستوطن الحرم وإن أولى الناس بصالح محمد وإني أشهدكم أني قد رددتهم إلى الرق قال وبلغنا أن ابن عباس قال وذكر عنده ثقيف فقال هو قسي بن منبه وكان عبدا لامرأة صالح نبي الله وهي الهيجمانة بنت سعد فوهبته لصالح وإنه سرحه إلى عامل له على الصدقة ثم ذكر باقي خبره مثل ما قال علي ابن أبي طالب رضي الله عنه وقال فيه إنه مر برجل معه غنم ومعه ابن له صغير ماتت أمه فهو يرضع من شاة ليست في الغنم لبون غيرها فأخذ الشاة فناشده الله وأعطاه عشرا فأبى فأعطاه جميع الغنم فأبى فلما رأى ذلك تنحى ثم نثل كنانته فرماه ففلق قلبه فقيل له قتلت رسول الله صالح فأتى صالحا فقص عليه قصته فقال أبعده الله فقد كنت أنتظر هذا منه فرجم قبره فإلى اليوم والليلة يرجم وهو أبو رغال قال وبلغنا عن عبد الله بن عباس أن رسول الله حين انصرف من الطائف مر بقبر أبي رغال فقال ( هذا قبر أبي رغال وهو أبو ثقيف كان في الحرم فمنعه الله عز و جل فلما خرج منه رماه الله وفيه عمود من ذهب\nفابتدره المسلمون فأخرجوه قال وروى عمرو بن عبيد عن الحسن أنه سئل عن جرهم هل بقي منهم أحد قال ما أدري غير أنه لم يبق من ثمود إلا ثقيف في قيس عيلان وبنو لجإ في طيئ والطفاوة في بني أعصر قال عمرو بن عبيد وقال الحسن ذكرت القبائل عند النبي فقال\n(قبائل تنتمي إلى العرب وليسوا من العرب حمير من تبع وجرهم من عاد وثقيف من ثمود ... )\nال وروي عن قتادة أن رجلين جاءا إلى عمران بن حصين فقال لهما ممن أنتما قالا من ثقيف فقال لهما أتزعمان أن ثقيفا من إياد قالا نعم قال فإن إيادا من ثمود فشق ذلك عليهما فقال لهما أساء كما قولي قالا نعم والله قال فإن الله أنجى من ثمود صالحا والذين آمنوا معه فأنتم إن شاء الله من ذرية من آمن وإن كان أبو رغال قد أتى ما بلغكما قالا له فما اسم أبي رغال فإن الناس قد اختلفوا علينا في اسمه قال قسي بن مبنه قال وروى الزهري أن النبي قال ( من كان يؤمن بالله واليوم الأخر فلا يحب ثقيفا ومن كان يؤمن بالله واليوم الآخر فلا يبغض الأنصار\nال وبلغنا عنه أنه قال ( بنو هاشم والأنصار حلفان وبنو أمية وثقيف حلفان\nقال وفي ثقيف يقول حسان بن ثابت رضي الله تعالى عنه\n(إذا الثقفي فاخركم فقولوا ... هلم نعد شأن أبي رغال)\n(أبوكم أخبث الآباء قدما ... وأنتم مشبهوه على مثال)\n(عبيد الفزر أورثهم بنيه ... وولى عنهم أخرى الليالي)","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":2,"spl":"الخلاف في نسب ثقيف — نسب أم طريح","partial":1},
{"id":"b40-4","bab":"الجزء 4","sec":"نسب أم طريح","page":"ج4 ص303","text":"وأم طريح بنت عبد الله بن سباع بن عبد العزى بن نضلة بن غبشان من خزاعة وهم حلفاء بني زهرة بن كلاب بن مرة بن كعب بن لؤي وسباع بن عبد\nالعزى هو الذي قتله حمزة بن عبد المطلب يوم أحد ولما برز إليه سباع قال له حمزة هلم إلي يابن مقطعة البظور وكانت أمه تفعل ذلك وتقبل نساء قريش بمكة فحمي وحشي لقوله وغضب لسباع فرمى حمزة بحربته فقتله رحمة الله عليه وقد كتب ذلك في خبر غزاة أحد في بعض هذا الكتاب ويكنى طريح أبا الصلت كني بذلك لابن كان له اسمه صلت وله يقول\n(يا صلت إن أباك رهن منية ... مكتوبة لا بد أن يلقاها)\n(سلفت سوالفها بأنفس من مضى ... وكذاك يتبع باقيا أخراها)\n(والدهر يوشك أن يفرق ريبه ... بالموت أو رحل تشت نواها)\n(لا بد بينكما فتسمع دعوة ... أو تستجيب لدعوة تدعاها)\nوأخبرني يحيى بن علي بن يحيى إجازة قال أخبرني أبو الحسن الكاتب أن أم الصلت بن طريح ماتت وهو صغير فطرحه طريح إلى أخواله بعد موت أمه وفيه يقول\n(بات الخيال من الصليت مؤرقي ... يفري السراة مع الرباب الملثق)\n(ما راعني إلا بياض وجيهه ... تحت الدجنة كالسراج المشرق)","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":2,"spl":"الخلاف في نسب ثقيف — نسب أم طريح"},
{"id":"b40-5","bab":"الجزء 4","sec":"نشأة طريح","page":"ج4 ص304","text":"ونشأ طريح في دولة بني أمية واستفرغ شعره في الوليد بن يزيد وأدرك دولة بني العباس ومات في أيام المهدي وكان الوليد له مكرما مقدما لانقطاعه إليه ولخؤولته في ثقيف\nفأخبرني محمد بن خلف وكيع قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني أحمد بن حماد بن الجميل عن العتبي عن سهم بن عبد الحميد قال أخبرني طريح بن إسماعيل الثقفي قال خصصت بالوليد بن يزيد حتى صرت أخلو معه فقلت له ذات يوم وأنا معه في مشربة يا أمير المؤمنين خالك يحب أن تعلم شيئا من خلقه قال وما هو قلت لم أشرب شرابا قط ممزوجا إلا من لبن أو عسل قال قد عرفت ذاك ولم يباعدك من قلبي قال ودخلت يوما إليه وعنده الأمويون فقال لي إلي يا خالي وأقعدني إلى جانبه ثم أتي بشراب فشرب ثم ناولني القدح فقلت يا أمير المؤمنين قد أعلمتك رأيي في الشراب قال ليس لذلك أعطيتك إنما دفعته إليك لتناوله الغلام وغضب فرفع القوم أيديهم كأن صاعقة نزلت على الخوان فذهبت أقوم فقال أقعد فلما خلا البيت افترى علي ثم قال يا عاض كذا وكذا أردت أن تفضحني ولولا أنك خالي لضربتك ألف سوط ثم نهى الحاجب عن إدخالي وقطع عني أرزاقي فمكثت ما شاء الله ثم دخلت عليه يوما متنكرا فلم يشعر إلا وأنا بين يديه وأنا أقول\n(يابن الخلائف مالي بعد تقربة ... إليك أقصى وفي حاليك لي عجب)\n(مالي أذاد وأقصى حين أقصدكم ... كما توقي من ذي العرة الجرب)\n(كأنني لم يكن بيني وبينكم ... إل ولا خلة ترعى ولا نسب)\n(لو كان بالود يدنى منك أزلفني ... بقربك الود والإشفاق والحدب)\n(وكنت دون رجال قد جعلتهم ... دوني إذ ما رأوني مقبلا قطبوا)\n(إن يسمعوا الخير يخفوه وإن سمعوا ... شرا أذاعوا وإن لم يسمعوا كذبوا)\n(رأوا صدودك عني في اللقاء فقد ... تحدثوا أن حبلي منك منقضب)\n(فذوا الشماتة مسرور بهيضتنا ... وذوا النصيحة والإشفاق مكتئب)\nقال فتبسم وأمرني بالجلوس فجلست ورجع إلي وقال إياك أن تعاود وتمام هذه القصيدة\n(أين الذمامة والحق الذي نزلت ... بحفظه وبتعظيم له الكتب)\n(وحوكي الشعر أصفيه وأنظمه ... نظم القلائد فيها الدر والذهب)\n(وإن سخطك شيء لم أناج به ... نفسي ولم يك مما كنت أكتسب)\n(لكن أتاك بقول كاذب أثم ... قوم بغوني فنالوا في ما طلبوا)\n(وما عهدتك فيما زل تقطع ذا ... قربى ولا تدفع الحق الذي يجب)\n(ولا توجع من حق تحمله ... ولا تتبع بالتكدير ما تهب)\n(فقد تقربت جهدا من رضاك بما ... كانت تنال به من مثلك القرب)\n(فغير دفعك حقي وارتفاضك لي ... وطيك الكشح عني كنت أحتسب)\n(أمشمت بي أقواما صدورهم ... علي فيك إلى الأذقان تلتهب)\n(قد كنت أحسب أني قد لجأت إلى ... حرز وألا يضروني وإن ألبوا)\n(إن التي صنتها عن معشر طلبوا ... مني إلي الذي لم ينجح الطلب)\n(أخلصتها لك إخلاص امرئ علم الأقوام ... أن ليس إلا فيك يرتغب)\n(أصبحت تدفعها مني وأعطفها ... عليك وهي لمن يجبى بها رغب)\n(فإن وصلت فأهل العرف أنت وإن ... تدفع يدي فلي بقيا ومنقلب)\n(إني كريم كرام عشت في أدب ... نفى العيوب وملك الشيمة الأدب)\n(قد يعلمون بأن العسر منقطع ... يوما وأن الغنى لا بد منقلب)\n(فمالهم حبس في الحق مرتهن ... مثل الغنائم تحوى ثم تنتهب)\n(وما علي جارهم ألا يكون له ... إذا تكنفه أبياتهم نشب)\n(لا يفرحون إذا ما الدهر طاوعهم ... يوما بيسر ولا يشكون إن نكبوا)\n(فارقت قومي فلم أعتض بهم عوضا ... والدهر يحدث أحداثا لها نوب)","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":3,"spl":"نشأة طريح"},
{"id":"b40-6","bab":"الجزء 4","sec":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد","page":"ج4 ص307","text":"وأما المدائني فقال كان الوليد بن يزيد يكرم طريحا وكانت له منه منزلة قريبة ومكانه وكان يدني مجلسه وجعله أول داخل وآخر خارج ولم يكن يصدر إلا عن رأيه فاستفرغ مديحه كله وعامة شعره فيه فحسده ناس من أهل بيت الوليد وقدم حماد الرواية على التفئة الشأم فشكوا ذلك إليه وقالوا والله لقد ذهب طريح بالأمير فما نالنا منه ليل ولا نهار فقال حماد ابغوني من ينشد الأمير بيتين من شعر فأسقط منزلته فطلبوا إلى الخصي الذي كان يقوم على رأس الوليد وجعلوا له عشرة آلاف درهم على أن ينشدهما الأمير في خلوة فإذا سأله من قول من هذا قال من قول طريح فأجابهم الخصي إلى ذلك وعلموه البيتين فلما كان ذات يوم دخل طريح على الوليد وفتح الباب وأذن للناس فجلسوا طويلا ثم نهضوا وبقي طريح مع الوليد وهو ولي عهد ثم دعا بغدائه فتغديا جميعا ثم إن طريحا خرج وركب إلى منزله وترك الوليد في مجلسه ليس معه أحد فاستلقى على فراشه واغتنم الخصي خلوته فاندفع ينشد\n(سيري ركابي إلى من تسعدين به ... فقد أقمت بدار الهون ما صلحا)\n(سيري إلى سيد سمح خلائقه ... ضخم الدسيعة قرم يحمل المدحا)\nأصغى الوليد إلى الخصي بسمعه وأعاد الخصي غير مرة ثم قال الوليد ويحك يا غلام من قول من هذا قال من قول طريح فغضب الوليد حتى امتلأ غيظا ثم قال والهفا على أم لم تلدني قد جعلته أول داخل وآخر خارج ثم يزعم أن هشاما يحمل المدح ولا أحملها ثم قال علي بالحاجب فأتاه فقال لا أعلم ما أذنت لطريح ولا رأيته على وجه الأرض فإن حاولك فاخطفه بالسيف فلما كان العشي وصليت العصر جاء طريح للساعة التي كان يؤذن له فيها فدنا من الباب ليدخل فقال له الحاجب وراءك فقال مالك هل دخل على ولي العهد أحد بعدي قال لا ولكن ساعة وليت من عنده دعاني فأمرني ألا آذن لك وإن حاولتني في ذلك خطفتك بالسيف فقال لك عشرة آلاف درهم واذن لي في الدخول عليه فقال له الحاجب والله لو أعطيتني خراج العراق ما أذنت لك في ذلك وليس لك من خير في الدخول عليه فارجع قال ويحك هل تعلم من دهاني عنده قال الحاجب لا والله لقد دخلت عليه وما عنده أحد ولكن الله يحدث ما يشاء في الليل والنهار قال فرجع طريح وأقام بباب الوليد سنة لا يخلص إليه ولا يقدر على الدخول عليه وأراد الرجوع إلى بلده وقومه فقال والله إن هذا لعجز بي أن أرجع من غير أن ألقى ولي العهد فأعلم من دهاني عنده ورأى أناسا كانوا له أعداء قد فرحوا بما كان من أمره فكانوا يدخلون على الوليد ويحدثونه ويصدر عن رأيهم فلم يزل يلطف بالحاجب ويمنيه حتى قال له الحاجب أما إذا أطلت المقام فإني أكره أن تنصرف على حالك هذه ولكن الأمير إذا كان يوم كذا وكذا دخل الحمام\nثم أمر بسريره فأبرز وليس عليه يومئذ حجاب فإذا كان ذلك اليوم أعلمتك فتكون قد دخلت عليه وظفرت بحاجتك وأكون أنا على حال عذر فلما كان ذلك اليوم دخل الحمام وأمر بسريره فأبرز وجلس عليه وأذن للناس فدخلوا عليه والوليد ينظر إلى من أقبل وبعث الحاجب إلى طريح فأقبل وقد تتام الناس فلما نظر الوليد إليه من بعيد صرف عنه وجهه واستحيا أن يرده من بين الناس فدنا فسلم فلم يرد عليه السلام فقال طريح يستعطفه ويتضرع إليه\n(نام الخلي من الهموم وبات لي ... ليل أكابده وهم مضلع)\n(وسهرت لا أسري ولا في لذة ... أرقي وأغفل ما لقيت الهجع)\n(أبغي وجوه مخارجي من تهمة ... أزمت علي وسد منها المطلع)\n(جزعا لمعتبة الوليد ولم أكن ... من قبل ذاك من الحوادث أجزع)\n(يابن الخلائف إن سخطك لامرئ ... أمسيت عصمته بلاء مفظع)\n(فلانزعن عن الذي لم تهوه ... إن كان لي ورأيت ذلك منزع)\n(فاعطف فداك أبي علي توسعا ... وفضيلة فعلى الفضيلة تتبع)\n(فلقد كفاك وزاد ما قد نالني ... إن كنت لي ببلاء ضر تقنع)\n(سمة لذاك علي جسم شاحب ... باد تحسره ولون أسفع)\n(إن كنت في ذنب عتبت فإنني ... عما كرهت لنازع متضرع)\n(ويئست منك فكل عسر باسط ... كفا إلي وكل يسر أقطع)\n(من بعد أخذي من حبالك بالذي ... قد كنت أحسب أنه لا يقطع)\n(فاربب صنيعك بي فإن بأعين ... للكاشحين وسمعهم ما تصنع)\n(أدفعتني حتى انقطعت وسددت ... عني الوجوه ولم يكن لي مدفع)\n(ورجيت واتقيت يداي وقيل قد ... أمسي يضر إذا أحب وينفع)\n(ودخلت في حرم الذمام وحاطني ... خفر أخذت به وعهد مولع)","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":4,"spl":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد"},
{"id":"b40-7","bab":"الجزء 4","sec":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد","page":"ج4 ص307","text":"(أفهادم ما قد بنيت وخافض ... شرفي وأنت لغير ذلك أوسع)\n(أفلا خشيت شمات قوم فتهم ... سبقا وأنفسهم عليك تقطع)\n(وفضلت في الحسب الأشم عليهم ... وصنعت في الأقوام ما لم يصنعوا)\n(فكأن انفهم بكل صنيعة ... أسديتها وجميل فعل تجدع)\n(ودوا لو أنهم ينال أكفهم ... شلل وأنك عن صنيعك تنزع)\n(أو تستليم فيجعلونك أسوة ... وأبى الملام لك الندى والموضع)\nال فقربه وأدناه وضحك إليه وعاد له إلى ما كان عليه أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن شبيب قال حدثنا محمد بن عبد الله بن حمزة بن عتبة اللهبي عن أبيه أن طريحا دخل على أبي جعفر المنصور وهو في الشعراء فقال له لا حياك الله ولا بياك أما اتقيت الله ويلك حيث تقول للوليد بن يزيد\n(لو قلت للسيل دع طريقك والموج ... عليه كالهضب يعتلج)\n(لساخ وارتد أو لكان له ... في سائر الأرض عنك منعرج)\nقال له طريح قد علم الله عز و جل أني قلت ذاك ويدي ممدودة إليه عز و جل وإياه تبارك وتعالى عنيت فقال المنصور يا ربيع أما ترى هذا التخلص","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":5,"spl":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد — نسبة هذا الصوت"},
{"id":"b40-8","bab":"الجزء 4","sec":"مدح الوليد فأطربه","page":"ج4 ص310","text":"نسخت من كتاب أحمد بن الحارث مما أجاز لي أبو أحمد الجريري روايته عنه حدثنا المدائني أن الوليد جلس يوما في مجلس له عام ودخل إليه أهل بيته ومواليه والشعراء وأصحاب الحوائج فقضاها وكان أشرف يوم رئي له فقام بعض الشعراء فأنشد ثم وثب طريح وهو عن يسار الوليد وكان أهل بيته عن يمينه وأخواله عن شماله وهو فيهم فأنشده صوت\n(أنت ابن مسلنطح البطاح ولم ... تطرق عليك الحني والولج)\n(طوبى لفرعيك من هنا وهنا ... طوبى لأعراقك التي تشج)\n(لو قلت للسيل دع طريقك والموج ... عليه كالهضب يعتلج)\n(لساخ وارتد أو لكان له ... في سائر الأرض عنك منعرج)\nطرب الوليد بن يزيد حتى رئي الارتياح فيه وأمر له بخمسين ألف درهم وقال ما أرى أحدا منكم يجيئني اليوم بمثل ما قال خالي فلا ينشدني أحد بعده شيئا وأمر لسائر الشعراء بصلات وانصرفوا واحتبس طريحا عنده وأمر ابن عائشة فغنى هذا الشعر","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":5,"spl":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد — نسبة هذا الصوت"},
{"id":"b40-9","bab":"الجزء 4","sec":"نسبة هذا الصوت","page":"ج4 ص311","text":"(أنت ابن مسلنطح البطاح ولم ... تطرق عليك الحني والولج)\nلأبيات الأربعة عروضه من المنسرح غناه ابن عائشة ولحنه رمل مطلق في مجرى الوسطى عن إسحاق\nالمسلنطح من البطاح ما اتسع واستوى سطحه منها وتطرق عليك تطبق عليك وتغطيك وتضيق مكانك يقال طرقت الحادثة بكذا وكذا إذا أتت بأمر ضيق معضل والوشيج أصول النبت يقال أعرقك واشجة في الكرم أي نابتة فيه قال الشاعر\n(وهل ينبت الخطي إلا وشيجه ... وتنبت إلا في مغارسها النخل)\nعني أنه كريم الأبوين من قريش وثقيف وقد ردد طريح هذا المعنى في الوليد فقال في كلمة له\n(واعتام كهلك من ثقيف كفأه ... فتنازعاك فأنت جوهر جوهر)\n(فنمت فروع القريتين قصيها ... وقسيها بك في الأشم الأكبر)\nالحني ما انخفص من الأرض والواحدة حنا والجمع حني مثل عصا وعصي والولج كل متسع في الوادي الواحدة ولجة ويقال الولجات بين الجبال مثل الرحاب أي لم تكن بين الحني ولا الولج فيخفى مكانك أي لست في موضع خفي من الحسب وقال أبو عبيدة سمع عمر بن الخطاب رضي الله عنه رجلا يقول لآخر يفخر عليه أنا ابن مسلنطح البطاح وابن كذا وكذا فقال له عمر إن كان لك عقل فلك أصل وإن كان لك خلق فلك شرف وإن كان لك تقوى فلك كرم وإلا فذاك الحمار خير منك أحبكم إلينا قبل أن نراكم\nأحسنكم سمتا فإذا تكلمتم فأبينكم منطقا فإذا اختبرناكم فأحسنكم فعلا وقوله لو قلت للسيل دع طريقك يقول أنت ملك هذا الأبطح والمطاع فيه فكل من تأمره يطيعك فيه حتى لو أمرت السيل بالانصراف عنه لفعل لنفوذ أمرك وإنما ضرب هذا مثلا وجعله مبالغة لأنه لا شيء أشد تعذرا من هذا وشبهه فإذا صرفه كان على كل شيء سواه أقدر وقوله لساخ أي لغاض في الأرض وارتد أي عدل عن طريقه وإن لم يجد إلى ذلك سبيلا كان له منعرج عنك إلى سائر الأرض","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":5,"spl":"رواية أخرى عن خلاف طريح مع الوليد بن يزيد — نسبة هذا الصوت"},
{"id":"b40-10","bab":"الجزء 4","sec":"ابن عائشة استعرض الوليد بأن غنى له في شعر طريح","page":"ج4 ص313","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال إسحاق وحدثني به الواقدي عن أبي الزناد عن إبراهيم بن عطية\nأن الوليد بن يزيد لما ولي الخلافة بعث إلى المغنين بالمدينة ومكة فأشخصهم إليه وأمرهم أن يتفرقوا ولا يدخلوا نهارا لئلا يعرفوا وكان إذ ذاك تيستر في أمره ولا يظهره فسبقهم ابن عائشة فدخل نهارا وشهر أمره فحبسه الوليد وأمر به فقيد وأذن للمغنين وفيهم معبد فدخلوا عليه دخلات ثم إنه جمعهم ليلة فغنوا له حتى طرب وطابت نفسه\nفلما رأى ذلك منه معبد قال لهم أخوكم ابن عائشة فيما قد علمتم فاطلبوا فيه\nثم قال يا أمير المؤمنين كيف ترى مجلسنا هذا قال حسنا لذيذا\nقال فكيف لو رأيت ابن عائشة وسمعت ما عنده قال فعلي به\nفطلع ابن عائشة يرسف في قيده\nفلما نظر إليه الوليد اندفع ابن عائشة فغناه في شعر طريح والصنعة فيه له\n(أنت ابن مسلنطح البطاح ولم ... تطرق عليك الحني والولج)\nفصاح الوليد اكسروا قيده وفكوا عنه فلم يزل عنده أثيرا مكرما أخبرني الحسن بن علي قال حدثنا ابن أبي سعد عن الحزامي عن عثمان بن حفص عن إبراهيم بن عبد السلام بن أبي الحارث الذي يقول له عمر بن أبي ربيعة\n(يا أبا الحارث قلبي طائر ... فأتمر أمر رشيد مؤتمن)\nال والله إني لقاعد مع مسلمة بن محمد بن هشام إذ مر به ابن جوان بن عمر بن أبي ربيعة وكان يغني فقال له اجلس يابن أخي غننا فجلس فغنى\n(أنت ابن مسلنطح البطاح ولم ... تطرق عليك الحني والولج)\nقال له يابن أخي ما أنت وهذا حين تغناه ولا حظ لك فيه هذا قاله طريح فينا\n(إذ الناس ناس والزمان زمان ... )\nمما في المائة الصوت المختارة من الأغاني من أشعار طريح بن إسماعيل التي مدح بها الوليد بن يزيد","topic":"ذكر طريح وأخباره ونسبه","topicNo":40,"sp":6,"spl":"ابن عائشة استعرض الوليد بأن غنى له في شعر طريح","partial":1},
{"id":"b41-1","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص314","text":"(ويحي غدا إن غدا علي بما ... أحذر من لوعة الفراق غد)\n(وكيف صبري وقد تجاوب بالفرقة ... منها الغراب والصرد)\nالشعر لطريح بن إسماعيل والغناء لابن مشعب الطائفي ولحنه المختار من الرمل بالوسطى","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":0,"spl":"صوت من المائة المختارة — نسبة ما في هذه الأخبار من الأغاني"},
{"id":"b41-2","bab":"الجزء 4","sec":"ذكر ابن مشعب وأخباره","page":"ج4 ص315","text":"هو رجل من أهل الطائف مولى لثقيف وقيل إنه من أنفسهم وانتقل إلى مكة فكان بها وإياه يعني العرجي بقوله\n(بفناء بيتك وابن مشعب حاضر ... في سامر عطر وليل مقمر)\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nخبرني الحسين بن يحيى عن حماد عن أبيه قال ابن مشعب مغن من أهل الطائف وكان من أحسن الناس غناء وكان في زمن ابن سريج والأعرج وعامة الغناء الذي ينسب إلى أهل مكة له وقد تفرق غناؤه فنسب بعضه إلى ابن سريج وبعضه إلى الهذليين وبعضه إلى ابن محرز قال ومن غنائه الذي ينسب إلى ابن محرز\n(يا دار عاتكة التي بالأزهر ... )\nمنه أيضا\n(أقفر ممن يحله السند ... فالمنحني فالعقيق فالجمد)\nأخبرني الحسين قال قال حماد وحدثني أبي قال مرض رجل من أهل المدينة بالشأم فعاده جيرانه وقالوا له ما تشتهي قال أشتهي إنسانا يضع فمه على أذني ويغنيني في بيتي العرجي\n(بفناء بيتك وابن مشعب حاضر ... في سامر عطر وليل مقمر)\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":0,"spl":"صوت من المائة المختارة — نسبة ما في هذه الأخبار من الأغاني","partialRef":{"sid":"b6-8","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b41-3","bab":"الجزء 4","sec":"نسبة ما في هذه الأخبار من الأغاني","page":"ج4 ص316","text":"(يا دار عاتكة التي بالأزهر ... أو فوقه بقفا الكثيب الأحمر)\n(بفناء بيتك وابن مشعب حاضر ... في سامر عطر وليل مقمر)\n(فتلازما عند الفراق صبابة ... أخذ الغريم بفضل ثوب المعسر)\nالشعر للعرجي والغناء لابن محرز خفيف ثقيل أول بالبنصر وذكر إسحاق أنه لابن مشعب وذكر حبش وذكر حبش أن فيه لابن المكي هزجا خفيفا بالبنصر وأما الصوت الآخر الذي أوله\n(أقفر ممن يحله السند ... )\nإنه الصوت الذي ذكرناه الذي فيه اللحن المختار وهو أول قصيدة طريح التي منها\n(ويحي غدا إن غدا علي بما ... أكره من لوعة الفراق غد)\nليس يغني فيه في زماننا هذا وهذه القصيدة طويلة يمدح فيها طريح الوليد بن يزيد يقول فيها\n(لم يبق فيها من المعارف بعد ... الحي إلا الرماد والوتد)\n(وعرصة نكرت معالمها الريح ... بها مسجد ومنتضد)","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":0,"spl":"صوت من المائة المختارة — نسبة ما في هذه الأخبار من الأغاني","partialRef":{"sid":"b6-8","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b41-4","bab":"الجزء 4","sec":"المنصور يمدح قصيدة لطريح","page":"ج4 ص317","text":"أخبرني يحيى بن علي بن يحيى قال حدثني محمد بن خلف القارئ قال أخبرنا هارون بن محمد وأخبرنا به وكيع وأظنه هو الذي كنى عنه يحيى بن علي فقال محمد بن خلف القارئ قال حدثنا هارون بن محمد بن عبد الملك قال حدثني علي بن عبد الله اللهبي قال حدثنا أبي عن أبيه قال أنشد المنصور هذه القصيدة فقال للربيع أسمعت أحدا من الشعراء ذكر في باقي معالم الحي المسجد غير طريح وهذه القصيدة من جيد قصائد طريح يقول فيها\n(لم أنس سلمى ولا ليالينا ... بالحزن إذ عيشنا بها رغد)\n(إذ نحن في ميعة الشباب وإذ ... أيامنا تلك غضة جدد)\n(في عيشة كالفريد عازبة الشقوة ... خضراء غصنها خضد)\n(نحسد فيها على النعيم وما ... يولع إلا بالنعمة الحسد)\n(أيام سلمى غريرة أنف ... كأنها خوط بانة رؤد)\n(ويحي غدا إن غدا علي بما ... أكره من لوعة الفراق غد)\n(قد كنت أبكي من الفراق وحيانا ... جميع ودارنا صدد)\n(فيكف صبري وقد تجاوب بالفرقة ... منها الغراب والصرد)\n(دع عنك سلمى لغير مقلية ... وعد مدحا بيوته شرد)\n(للأفضل الأفضل الخليفة عبد ... الله من دون شأوه صعد)\n(في وجهه النور يستبان كما ... لاح سراج النهار إذ يقد)\n(يمضي على خير ما ي قول ولا ... يخلف ميعاده إذا يعد)\n(من معشر لا يشم من خذلوا ... عزا ولا يستذل من رفدوا)\n(بيض عظام الحلوم حدهم ... ماض حسام وخيرهم عتد)\n(أنت إيام الهدي الذي أصلح الله ... به الناس بعدما فسدوا)\n(لما أتى الناس أن ملكهم ... إليك قد صار أمره سجدوا)\n(واستبشروا بالرضا تباشرهم ... بالخلد لو قيل إنكم خلد)\n(وعج بالحمد أهل أرضك حتى ... كاد يهتز فرحة أحد)\n(واستقبل الناس عيشة أنفا ... إن تبق فيها لهم فقد سعدوا)\n(رزقت من ودهم وطاعتهم ... ما لم يجده لوالد ولد)\n(أثلجهم منك أنهم علموا ... أنك فيما وليت مجتهد)\n(وأن ما قد صنعت من حسن ... مصداق ما كنت مرة تعد)\n(ألفت أهواءهم فأصبحت الأضغان ... سلما وماتت الحقد)\n(كنت أرى أن ما وجدت من الفرحة ... لم يلق مثله أحد)\n(حتى رأيت العباد كلهم ... قد وجدوا من هواك ما أجد)\nصوت\n(قد طلب الناس ما بلغت فما ... نالوا ولا قاربوا وقد جهدوا)\n(يرفعك الله بالتكرم والتقوى ... فتعلو وأنت مقتصد)\n(حسب امرء من غنى تقربه ... منك وإن لم يكن له سبد)\n(فأنت أمن لمن يخاف وللمخذول ... أودى نصيره عضد)\nغنى في هذه الأبيات الأربعة إبراهيم خفيف ثقيل بالبنصر\n(كل امرئ ذي يد تعد عليه ... منك معلومة يد ويد)\n(فهم ملوك ما لم يروك فإن ... داناهم منك منزل خمدوا)\n(تعروهم رعدة لديك كما ... قفقف تحت الدجنة الصرد)\n(لا خوف ظلم ولا قلى خلق ... إلا جلالا كساكه الصمد)\n(وأنت عمر الندى إذا هبط الزوار ... أرضا تحلها حمدوا)\n(فهم رفاق فرفقة صدرت ... عنك بغنم ورفقة ترد)\n(إن حال دهر فإنك لا ... تنفك عن حالك التي عهدوا)\n(قد صدق الله مادحيك فما ... في قولهم فرية ولا فند)","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":1,"spl":"المنصور يمدح قصيدة لطريح — علم جعفر بن يحيى بالأشعار والألحان"},
{"id":"b41-5","bab":"الجزء 4","sec":"علم جعفر بن يحيى بالأشعار والألحان","page":"ج4 ص319","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى قال سمعت إسحاق بن إبراهيم الموصلي يحلف بالله الذي لا إله إلا هو إنه ما رأى أذكى من جعفر بن يحيى قط ولا أفطن ولا أعلم بكل شيء ولا أفصح\nلسانا ولا أبلغ في مكاتبة قال ولقد كنا يوما عند الرشيد فغنى أبي لحنا في شعر طريح بن إسماعيل وهو\n(قد طلب الناس ما بلغت فما ... نالوا ولا قاربوا وقد جهدوا)\nفاستحسن الرشيد اللحن والشعر واستعاده ووصل أبي عليه وكان اللحن في طريقة خفيف الثقيل الأول فقال جعفر بن يحيى قد والله يا سيدي أحسن ولكن اللحن مأخوذ من لحن الدلال الذي غناه في شعر أبي زبيد\n(من ير العير لابن أروى على ظهر ... المرورى حداتهن عجال)\nأما الشعر فنقله طريح من قول زهير\n(سعى بعدهم قوم لكي يدركوهم ... فلم يبلغوا ولم يلاموا ولم يألوا)\nال إسحاق فعجبت والله من علمه بالألحان والأشعار وإذا اللحن يشبه لحن الدلال قال وكذلك الشعر فاغتممت أني لم أكن فهمت اللحن وكان ذلك أشد علي من ذهاب أمر الشعر علي وأنا والله مع ذلك أغني الصوتين وأحفظ الشعرين قال الحسين ولحن الدلال في شعر أبي زبيد هذا من خفيف الثقيل أيضا","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":1,"spl":"المنصور يمدح قصيدة لطريح — علم جعفر بن يحيى بالأشعار والألحان"},
{"id":"b41-6","bab":"الجزء 4","sec":"طريح يذكر لأبي ورقاء قصته مع أعرابي عاشق","page":"ج4 ص320","text":"أخبرني يحيى بن علي بن يحيى إجازة قال حدثني أبو الحسن البلاذري أحمد ابن يحيى وأبو أيوب المديني قال البلاذري وحدثني الخرمازي وقال أبو أيوب وحدثونا عن الحرمازي قال حدثني أبو القعقاع سهل بن عبد الحميد عن أبي ورقاء الحنفي قال خرجت من الكوفة أريد بغداد فلما صرت إلى أول خان نزلته بسط غلماننا\nوهيأوا غداءهم ولم يجئ أحد بعد إذ رمانا الباب برجل فاره البرذون حسن الهيئة فصحت بالغلمان فأخذوا دابته فدفعها إليهم ودعوت بالغداء فبسط يديه غير محتشم وجعلت لا أكرمه بشيء إلا قبله ثم جاء غلمانه بعد ساعة في ثقل سري وهيئة حسنة فتناسبنا فإذا الرجل طريح بن إسماعيل الثقفي فلما ارتحلنا ارتحلنا في قافلة غناء لا يدرك طرفاها قال فقال لي ما حاجتنا إلى زحام الناس وليست بنا إليهم وحشة ولا علينا خوف نتقدمهم بيوم فيخلوا لنا الطريق ونصادف الخانات فارغة ونودع أنفسنا إلى أن يوافوا قلت ذلك إليك قال فأصبحنا الغد فنزلنا الخان فتغدينا وإلى جانبنا نهر ظليل فقال هل لك أن نستنقع فيه فقلت له شأنك فلما سرا ثيابه إذا ما بين عصعصه إلى عنقه ذاهب وفي جنبيه أمثال الجرذان فوقع في نفسي منه شيء فنظر إلي ففطن وتبسم ثم قال قد رأيت ذعرك مما رأيت وحديث هذا إذا سرنا العشية إن شاء الله تعالى أحدثك به قال فلما ركبنا قلت الحديث قال نعم قدمت من عند الوليد بن يزيد بالدنيا وكتبت إلى يوسف بن عمر مع فراش فملأ يدي أصحابي فخرجت أبادر الطائف فلما امتد لي الطريق وليس يصحبني فيه خلق عن لي أعرابي على بعير له فحدثني فإذا هو حسن الحديث وروى لي الشعر فإذا هو راوية وأنشدني لنفسه فإذا هو شاعر فقلت له من أين أقبلت قال لا أدري قلت فأين تريد فذكر قصة يخبر فيها أنه عاشق لمريئة قد أفسدت عليه عقله\nوسترها عنه أهلها وجفاه أهله فإنما يستريح إلى الطريق ينحدر مع منحدريه ويصعد مع مصعديه قلت فأين هي قال غدا ننزل بإزائها فلما نزلنا أراني ظربا على يسار الطريق فقال لي أترى ذلك الظرب قلت أراه قال فإنها في مسقطه قال فأدركني أريحية الشباب فقلت أنا والله آتيها برسالتك قال فخرجت وأتيت الظرب وإذا بيت حريد وإذا فيه امرأة جميلة ظريفة فذكرته لها فزفرت زفرة كادت أضلاعها تساقط ثم قالت أوحي هو قلت نعم تركته في رحلي وراء هذا الظرب ونحن بائتون ومصبحون فقالت يا أبي أرى لك وجها يدل على خير فهل لك في الأجر فقلت فقير والله إليه قالت فالبس ثيابي وكن مكاني ودعني حتى آتيه وذلك مغيربان الشمس قلت أفعل قالت إنك إذا أظلمت أتاك زوجي في هجمة من إبله فإذا بركت أتاك وقال يا فاجرة يا هنتاه فيوسعك شتما فأوسعه صمتا ثم يقول اقمعي سقاءك فضع القمع في هذا السقاء حتى يحقن فيه وإياك وهذا الآخر فإنه واهي الأسفل قال فجاء ففعلت ما أمرتني به ثم قال اقمعي سقاءك فحينني الله فتركت الصحيح وقمعت الواهي فما شعر إلا باللبن بين رجليه فعمد إلى رشاء من قد مربوع فثناه باثنين فصار على ثمان قوى ثم جعل لا يتقي مني\nرأسا ولا رجلا ولا جنبا فخشيت أن يبدو له وجهي فتكون الأخرى فألزمت وجهي الأرض فعمل بظهري ما ترى","topic":"ذكر ابن مشعب وأخباره","topicNo":41,"sp":2,"spl":"طريح يذكر لأبي ورقاء قصته مع أعرابي عاشق"},
{"id":"b42-1","bab":"الجزء 4","sec":"ذكر أخبار أبي سعيد مولى فائد ونسبه جمع الشعر إلى جانب الغناء","page":"ج4 ص324","text":"أبو سعيد مولى فائد وفائد مولى عمرو بن عثمان بن عفان رضي الله عنه وذكر ابن خرداذبة أن اسم أبي سعيد إبراهيم وهو يعرف في الشعراء بابن أبي سنة مولى بني أمية وفي المغنين بأبي سعيد مولى فائد وكان شاعرا مجيدا ومغنيا وناسكا بعد ذلك فاضلا مقبول الشهادة بالمدينة معدلا وعمر إلى خلافة الرشيد ولقيه إبراهيم بن المهدي وإسحاق الموصلي وذووهما وله قصائد جياد في مراثي بني أمية الذين قتلهم عبد الله وداود ابنا علي بن عبد الله بن العباس يذكر هاهنا في موضعه منها ما تسوق الأحاديث ذكره أخبرني علي بن عبد العزيز عن عبيد الله بن عبد الله عن إسحاق وأخبرني الحسين بن يحيى عن ابن أبي الأزهر عن حماد عن أبيه وأخبرنا به يحيى بن علي عن أخيه أحمد بن علي عن عافية بن شبيب عن أبي جعفر الأسدي عن إسحاق قال يحيى خاصة في خبره قال إسحاق حججت مع الرشيد فلما قربت من مكة استأذنته في التقدم فأذن لي فدخلت مكة فسألت عن أبي سعيد مولى فائد فقيل لي هو في المسجد الحرام فأتيت المسجد فسألت عنه فدللت عليه فإذا هو قائم يصلي\nفجئت فجلست قريبا منه فلما فرغ قال لي يا فتى ألك حاجة قلت نعم تغنيني لقد طفت سبعا هذه رواية يحيى بن علي وأما الباقون فإنهم ذكروا عن إسحاق أن المهدي قال هذا لأبي سعيد وأمره أن يغني له\n(لقد طفت سبعا قلت لما قضيتها ... ألا ليت هذا لا علي ولا ليا)\nورفق به وأدنى مجلسه وقد كان نسك فقال أو أغنيك يا أمير المؤمنين أحسن منه قال أنت وذاك فغني\n(إن هذا الطويل من آل حفص ... نشر المجد بعدما كان ماتا)\n(وبناه على أساس وثيق ... وعماد قد أثبتت إثباتا)\n(مثل ما قد بنى له أولوه ... وكذا يشبه البناة البناتا)\nلشعر والغناء لأبي سعيد مولى فائد فأحسن فقال له المهدي أحسنت يا أبا سعيد فغني لقد طفت سبعا قال أو أغنيك أحسن منه قال أنت وذاك فغناه\n(قدم الطويل فأشرقت واستبشرت ... أرض الحجاز وبان في الأشجار)\n(إن الطويل من آل حفص فاعلموا ... ساد الحضور وساد في الأسفار)\nأحسن فيه فقال غنني لقد طفت سبعا قال أو أغنيك أحسن منه قال فغنني فغناه\n(أيها السائل الذي يخبط الأرض ... دع الناس أجمعين وراكا)\n(وأت هذا الطويل من آل حفص ... إن تخوفت عيلة أو هلاكا)\nأحسن فيه فقال له غنني لقد طفت سبعا فقد أحسنت فيما غنيت ولكنا نحب أن تغني ما دعوناك إليه فقال لا سبيل إلى ذلك يا أمير المؤمنين لأني رأيت رسول الله منامي وفي يده شيء لا أدري ما هو وقد رفعه ليضربني به وهو يقول يا أبا سعيد لقد طفت سبعا لقد طفت سبعا سبعا طفت ما صنعت بأمتي في هذا الصوت فقلت له بأبي أنت وأمي اغفر لي فوالذي بعثك بالحق واصطفاك بالنبوة لا غنيت هذا الصوت أبدا فرد يده ثم قال عفا الله عنك إذا ثم انتبهت وما كنت لأعطي رسول الله شيئا في منامي فارجع عنه في يقظتي فبكى المهدي وقال أحسنت يا أبا سعيد أحسن الله إليك لا تعد في غنائه وحباه وكساه وأمر برده إلى الحجاز فقال له أبو سعيد ولكن اسمعه يا أمير المؤمنين من منة جارية البرامكة وأظن حكاية من حكى ذلك عن المهدي غلطا لأن منة جارية البرامكة لم تكن في أيام المهدي وإنما نشأت وعرفت في أيام الرشيد وقد حدثني أحمد بن جعفر جحظة قال حدثني هبة الله بن إبراهيم بن المهدي عن أبيه أنه هو الذي لقي أبا سعيد مولى فائد وجاراه هذه القصة وذكر ذلك أيضا حماد بن إسحاق عن إبراهيم بن المهدي وقد يجوز أن يكون إبراهيم بن المهدي وإسحاق سألاه عن هذا الصوت فأجابهما فيه بمثل ما أجاب المهدي وأما خبر إبراهيم بن المهدي خاصة فله معان غير هذه والصوت الذي سأله عنه غير هذا وسيذكر بعد انقضاء هذه الأخبار لئلا تنقطع","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":0,"spl":"ذكر أخبار أبي سعيد مولى فائد ونسبه جمع الشعر إلى جانب الغناء — رفض الشخوص إلى بغداد مع إبر"},
{"id":"b42-2","bab":"الجزء 4","sec":"رفض الشخوص إلى بغداد مع إبراهيم بن المهدي","page":"ج4 ص326","text":"وأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة أن إبراهيم بن المهدي لقي أبا سعيد مولى فائد وذكر الخبر بمثل الذي قبله وزاد فيه فقال له اشخص معي إلى بغداد فلم يفعل فقال ما كنت\nلآخذك بما لا تحب ولو كان غيرك لأكرهته على ما أحب ولكن دلني على من ينوب عنك فدل على ابن جامع وقال له عليك بغلام من بني سهم قد أخذ عني وعن نظرائي وتخرج وهو كما تحب فأخذه إبراهيم معه فأقدمه بغداد فهو الذي كان سبب وروده إياها","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":0,"spl":"ذكر أخبار أبي سعيد مولى فائد ونسبه جمع الشعر إلى جانب الغناء — رفض الشخوص إلى بغداد مع إبر"},
{"id":"b42-3","bab":"الجزء 4","sec":"نسبة ما في هذه الأخبار من الأغاني صوت من المائة المختارة","page":"ج4 ص327","text":"(لقد طفت سبعا قلت لما قضيتها ... ألا ليت هذا لا علي ولا ليا)\n(يسائلني صحبي فما أعقل الذي ... يقولون من ذكر لليلى اعترانيا)\nعروضه من الطويل ذكر يحيى بن علي أن الشعر والغناء لأبي سعيد مولى فائد وذكر غيره أن الشعر للمجنون ولحنه خفيف رمل بالبنصر وهو المختار وذكر حبش أن فيه لإبراهيم خفيف رمل آخر والذي ذكر يحيى بن علي من أن الشعر لأبي سعيد مولى فائد هو الصحيح أخبرني عمي عن الكراني عن عيسى بن إسماعيل عن القحذمي أنه أنشده لأبي سعيد مولى فائد قال عمي وأنشدني هذا الشعر أيضا أحمد بن أبي طاهر عن أبي دعامة لأبي سعيد وبعد هذين البيتين اللذين مضيا هذه الأبيات\n(إذا جئت باب الشعب شعب ابن عامر ... فأقرئ غزال الشعب مني سلاميا)\n(وقل لغزال الشعب هل أنت نازل ... بشعبك أم هل يصبح القلب ثاويا)\n(لقد زادني الحجاج شوقا إليكم ... وقد كنت قبل اليوم للحج قاليا)\n(وما نظرت عيني إلى وجه قادم ... من الحج إلا بل دمعي ردائيا)\nي البيت الأول من هذه الأبيات وهو\n(إذا جئت باب الشعب شعب ابن عامر ... )\nحن لابن جامع خفيف رمل عن الهشامي ومنها صوت\n(إن هذا الطويل من آل حفص ... نشر المجد بعدما كان ماتا)\n(وبناه على أساس وثيق ... وعماد قد أثبتت إثباتا)\n(مثل ما قد بنى له أولوه ... وكذا يشبه البناة البناتا)\nروضه من الخفيف الشعر والغناء لأبي سعيد مولى فائد ولحنه رمل مطلق في مجرى البنصر عن إسحاق ومنها صوت\n(قدم الطويل فأشرقت لقدومه ... أرض الحجاز وبان في الأشجار)\n(إن الطويل من آل حفص فاعلموا ... ساد الحضور وساد في الأسفار)\nلشعر والغناء لأبي سعيد ومنها صوت\n(أيها الطالب الذي يخبط الأرض ... دع الناس أجمعين وراكا)\n(وأن هذا الطويل من آل حفص ... إن تخوفت عيلة أو هلاكا)\nعروضه من الخفيف الشعر لأبي سعيد مولى فائد وقيل إنه للدارمي والغناء لأبي سعيد خفيف ثقيل وفيه للدارمي ثاني ثقيل الطويل من آل حفص الذي عناه الشعراء في هذه الأشعار هو عبد الله بن عبد الحميد بن حفص وقيل ابن أبي حفص بن المغيرة المخزومي وكان ممدحا","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":1,"spl":"نسبة ما في هذه الأخبار من الأغاني صوت من المائة المختارة — مدح عبد الله بن عبد الحميد","partial":1},
{"id":"b42-4","bab":"الجزء 4","sec":"مدح عبد الله بن عبد الحميد","page":"ج4 ص329","text":"فأخبرني يحيى بن علي بن يحيى إجازة عن أبي أيوب المديني قال حدثنا عبد الرحمن بن أخي الأصمعي عن عمه أن عبد الله بن عبد الحميد المخزومي كان يعطي الشعراء فيجزل وكان موسرا وكان سبب يساره ما صار إليه من أم سلمة المخزومية امرأة أبي العباس السفاح فإنه تزوجها بعده فصار إليه منها مال عظيم فكان يتسمح به ويتفتى ويتسع في العطايا وكانت أم سلمة مائلة إليه فأعطته ما لا يدري ما هو ثم إنها اتهمته بجارية لها فاحتجبت عنه فلم تعد إليه حتى مات وكان جميل الوجه طويلا وفيه يقول أبو سعيد مولى فائد\n(إن هذا الطويل من آل حفص ... نشر المجد بعد ما كان ماتا)\nفيه يقول الدارمي\n(أيها السائل الذي يخبط الأرض ... دع الناس أجمعين وراكا)\n(وأت هذا الطويل من آل حفص ... إن تخوفت عيلة أو هلاكا)\nوفيه يقول الدارمي أيضا صوت\n(إن الطويل إذا حللت به ... يوما كفاك مؤونة الثقل)\nيروى\n(ابن الطويل إذا حللت به ... )\n(وحللت في دعة وفي كنف ... رحب الفناء ومنزل سهل)\nناه ابن عباد الكاتب ولحنه من الثقيل الأول الذي بالبنصر عن ابن المكي فأما خبر إبراهيم بن المهدي مع أبي سعيد مولى فائد الذي قلنا إنه يذكر هاهنا فأخبرني به الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك الزيات قال حدثني القطراني المغني قال حدثني ابن جبر قال سمعت إبراهيم بن المهدي يقول كنت بمكة في المسجد الحرام فإذا شيخ قد طلع وقد قلب إحدى نعليه على الأخرى وقام يصلي فسألت عنه فقيل لي هذا أبو سعيد مولى فائد فقلت لبعض الغلمان احصبه فحصبه فأقبل عليه وقال ما يظن أحدكم إذا دخل المسجد إلا أنه له فقلت للغلام قل له يقول لك مولاي ابلغني فقال ذلك له فقال له أبو سعيد من مولاك حفظه الله قال مولاي إبراهيم بن المهدي فمن أنت قال أنا أبو سعيد مولى فائد وقام فجلس بين يدي وقال لا والله بأبي أنت وأمي ما عرفتك فقلت لا عليك أخبرني عن هذا الصوت\n(أفاض المدامع قتلى كدى ... وقتلى بكثوة لم ترمس)\nقال هو لي قلت ورب هذه البنية لا تبرح حتى تغنيه قال ورب هذه البنية لا تبرح حتى تسمعه قال ثم قلب إحدى نعليه وأخذ بعقب الأخرى وجعل يقرع بحرفها على الأخرى ويغنيه حتى أتى عليه فأخذته منه قال ابن جبر وأخذته أنا من إبراهيم بن المهدي","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":1,"spl":"نسبة ما في هذه الأخبار من الأغاني صوت من المائة المختارة — مدح عبد الله بن عبد الحميد","partial":1},
{"id":"b42-5","bab":"الجزء 4","sec":"محمد بن عمران يقبل شهادته بعد أن ردها","page":"ج4 ص331","text":"أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال حدثني دنية المدني صاحب العباسة بنت المهدي وكان آدب من قدم علينا من أهل الحجاز أن أبا سعيد مولى فائد حضر مجلس محمد بن عمران التيمي قاضي المدينة لأبي جعفر وكان مقدما لأبي سعيد فقال له ابن عمران التيمي يا أبا سعيد أنت القائل\n(لقد طفت سبعا قلت لما قضيتها ... ألا ليت هذا لا علي ولا ليا)\nقال أي لعمر أبيك وإني لأدمجه إدماجا من لؤلؤ فرد محمد بن عمران شهادته في ذلك المجلس وقام أبو سعيد من مجلسه مغضبا وحلف ألا يشهد عنده أبدا فأنكر أهل المدينة على ابن عمران رده شهادته وقالوا عرضت حقوقنا للتوى وأموالنا للتلف لأنا كنا نشهد هذا الرجل لعلمنا بما كنت عليه والقضاة قبلك من الثقة به وتقديمه وتعديله فندم ابن عمران بعد ذلك على رد شهادته ووجه إليه يسأله حضور مجلسه والشهادة عنده ليقضي بشهادته فامتنع وذكر أنه لا يقدر على حضور مجلسه ليمين لزمته إن حضره حنث قال فكان ابن عمران بعد ذلك إذا ادعى أحد عنده شهادة أبي سعيد صار إليه إلى منزله أو مكانه من المسجد حتى يسمع منه ويسأله عما يشهد به فيخبره وكان محمد بن عمران كثير اللحم\nعظيم البطن كبير العجيزة صغير القدمين دقيق الساقين يشتد عليه المشي فكان كثيرا ما يقول لقد أتعبني هذا الصوت لقد طفت سبعا وأضر بي ضررا طويلا شديدا وأنا رجل ثقال بترددي إلى أبي سعيد لأسمع شهادته أخبرني عمي قال حدثنا الكراني قال حدثنا النضر بن عمرو عن الهيثم بن عدي قال كان المطلب بن عبد الله بن حنطب قاضيا على مكة فشهد عنده أبو سعيد مولى فائد بشهادة فقال له المطلب ويحك ألست الذي يقول\n(لقد طفت سبعا قلت لما قضيتها ... ألا ليت هذا لا علي ولا ليا)\nا قبلت لك شهادة أبدا فقال أبو سعيد أنا والله الذي أقول\n(كأن وجوه الحنطبيين في الدجى ... قناديل تسقيها السليط الهياكل)\nقال الحنطبي إنك ما علمتك إلا دبابا حول البيت في الظلم مدمنا للطواف به في الليل والنهار وقبل شهادته","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":2,"spl":"محمد بن عمران يقبل شهادته بعد أن ردها — نسبة الصوت المذكور قبل هذا الذي في حديث إبراهيم بن"},
{"id":"b42-6","bab":"الجزء 4","sec":"نسبة الصوت المذكور قبل هذا الذي في حديث إبراهيم بن المهدي وخبره","page":"ج4 ص332","text":"صوت\n(أفاض المدامع قتلى كدى ... وقتلى بكثوة لم ترمس)\n(وقتلى بوج وباللابتين ... من يثرب خير ما أنفس)\n(وبالزابيين نفوس ثوت ... وأخرى بنهر أبي فطرس)\n(أولئك قومي أناخت بهم ... نوائب من زمن متعس)\n(إذا ركبوا زينوا الموكبين ... وإن جلسوا الزين في المجلس)\n(هم أضرعوني لريب الزمان ... وهم ألصقوا الرغم بالمعطس)\nروضه من المتقارب الشعر للعبلي واسمه عبد الله بن عمر ويكنى أبا عدي وله أخبار تذكر مفردة في موضعها إن شاء الله والغناء لأبي سعيد مولى فائد ولحنه من الثقيل الثاني بالسبابة في مجرى البنصر وقصيدة العبلي أولها\n(تقول أمامة لما رأت ... نشوزي عن المضجع الأنفس)","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":2,"spl":"محمد بن عمران يقبل شهادته بعد أن ردها — نسبة الصوت المذكور قبل هذا الذي في حديث إبراهيم بن"},
{"id":"b42-7","bab":"الجزء 4","sec":"الشاعر العبلي ينشد ابن حسن رثاء في قومه فيبكي","page":"ج4 ص333","text":"نسخت من كتاب الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار وأخبرني الأخفش عن المبرد عن المغيرة بن محمد المهلبي عن الزبير عن سليمان بن\nعياش السعدي قال جاء عبد الله بن عمر العبلي إلى سويقة وهو طريد بن العباس وذلك بعقب أيام بني أمية وابتداء خروج ملكهم إلى بني العباس فقصد عبد الله وحسنا ابني الحسن بن حسن بسويقة فاستنشده عبد الله بن حسن شيئا من شعره فأنشده فقال له أريد أن تنشدني شيئا مما رثيت به قومك فأنشده قوله\n(تقول أمامة لما رأت ... نشوزي عن المضجع الأنفس)\n(وقلة نومي على مضجعي ... لدي هجعة الأعين النعس)\n(أبي ما عراك فقلت الهموم ... عرون أباك فلا تبلسي)\n(عرون أباك فحبسنه ... من الذل في شر ما محبس)\n(لفقد الأحبة إذ نالها ... سهام من الحدث المبئس)\n(رمتها المنون بلا نكل ... ولا طائشات ولا نكس)\n(بأسهمها المتلفات النفوس ... متى ما تصب مهجة تخلس)\n(فصرعنهم في نواحي البلاد ... ملقى بأرض ولم يرسس)\n(تقي أصيب وأثوابه ... من العيب والعار لم تدنس)\n(وآخر قد دس في حفرة ... وآخر قد طار لم يحسس)\n(إذا عن ذكرهم لم ينم ... أبوك وأوحش في المجلس)\n(فذاك الذي غالني فاعلمي ... ولا تسألي بامرىء متعس)\n(أذلوا قناتي لمن رامها ... وقد ألصقوا الرغم بالمعطس)\nال فرأيت عبد الله بن حسن وإن دموعه لتجري على خده وقد أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني عن إبراهيم بن رباح قال عمر أبو سعيد بن أبي سنة مولى بني أمية وهو مولى فائد مولى عمرو بن عثمان إلى أيام الرشيد فلما حج أحضره فقال أنشدني قصيدتك\n(تقول أمامة لما رأت ... )\nاندفع فغناه قبل أن ينشده الشعر لحنه في أبيات منها أولها\n(أفاض المدامع قتلى كدى ... )\nكان الرشيد مغضبا فسكن غضبه وطرب فقال أنشدني القصيدة فقال يا أمير المؤمنين كان القوم موالي وأنعموا علي فرثيتهم ولم أهج أحدا فتركه أخبرني محمد بن يحيى قال حدثنا الحزنبل قال كنا عند ابن الأعرابي وحضر معنا أبو هفان فأنشدنا ابن الأعرابي عمن أنشده قال قال ابن أبي سبة العبلي\n(أفاض المدامع قتلى كذا ... وقتلى بكبوة لم ترمس)\nغمز أبو هفان رجلا وقال له قل له ما معنى كذا قال يريد كثرتهم فلما قمنا قال لي أبو هفان أسمعت إلى هذا المعجب الرقيع صحف اسم الرجل هو ابن أبي سنة فقال ابن أبي سبة وصحف في بيت واحد موضعين فقال قتلى كذا وهو كدى وقتلى بكبوة وهو بكثوة وأغلظ علي من هذا أنه يفسر تصحيفه\nبوجه وقاح وهذا الشعر الذي غناه أبو سعيد يقوله أبو عدي عبد الله بن عمر العبلي فيمن قتله عبد الله بن علي بنهر أبي فطرس وأبو العباس السفاح أمير المؤمنين بعدهم من بني أمية وخبرهم والوقائع التي كانت بينهم مشهورة يطول ذكرها جدا ونذكر هاهنا ما يستحسن منها","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":3,"spl":"الشاعر العبلي ينشد ابن حسن رثاء في قومه فيبكي — ذكر من قتل أبو العباس السفاح من بني أمية","partialRef":{"sid":"b42-4","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b42-8","bab":"الجزء 4","sec":"ذكر من قتل أبو العباس السفاح من بني أمية","page":"ج4 ص337","text":"أخبرني محمد بن يحيى قال حدثني مسبح بن حاتم العكلي قال حدثني الجهم بن السباق عن صالح بن ميمون مولى عبد الصمد بن علي قال لما استمرت الهزيمة بمروان أقام عبد الله بن علي بالرقة وأنفذ أخاه عبد الصمد في طلبه فصار إلى دمشق وأتبعه جيشا عليهم أبو إسماعيل عامر الطويل من قواد خراسان فلحقه وقد جاز مصر في قرية تدعى بوصير فقتله وذلك يوم الأحد لثلاث بقين من ذي الحجة ووجه برأسه إلى عبد الله بن علي فأنفذه عبد الله بن علي إلى أبي العباس فلما وضع بين يديه خر لله ساجدا ثم رفع رأسه وقال الحمد لله الذي أظهرني عليك وأظفرني بك ولم يبق ثأري قبلك وقبل رهطك أعداء الدين ثم تمثل قول ذي الإصبع العدواني\n(لو يشربون دمي لم يرو شاربهم ... ولا دماؤهم للغيظ ترويني)\nخبرني محمد بن خلف وكيع قال حدثني محمد بن يزيد قال\nنظر عبد الله بن علي إلى فتى عليه أبهة الشرف وهو يقاتل مستنتلا فناداه يا فتى لك الأمان ولو كنت مروان بن محمد فقال إلا أكنه فلست بدونه قال فلك الأمان من كنت فأطرق ثم قال\n(أذل الحياة وكره المممات ... وكلا أرى لك شرا وبيلا)\nيروى\n(وكلا أراه طعاما وبيلا ... )\n(فإن لم يكن غير إحداهما ... فسيرا إلى الموت سيرا جميلا)\nم قاتل حتى قتل قال فإذا هو ابن مسلمة بن عبد الملك بن مروان","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":3,"spl":"الشاعر العبلي ينشد ابن حسن رثاء في قومه فيبكي — ذكر من قتل أبو العباس السفاح من بني أمية","partial":1},
{"id":"b42-9","bab":"الجزء 4","sec":"مقتل جماعة من الأمويين في اجتماع عند السفاح","page":"ج4 ص338","text":"أخبرني عمي قال حدثني محمد بن سعد الكراني قال حدثني النضر بن عمرو عن المعيطي وأخبرنا محمد بن خلف وكيع قال قال أبو السائب سلم بن جنادة السوائي سمعت أبا نعيم الفضل بن دكين يقول دخل سديف وهو مولى لآل أبي لهب على أبي العباس بالحيرة هكذا قال وكيع وقال الكراني في خبره واللفظ له كان أبو العباس جالسا في مجلسه على سريره وبنو هاشم دونه على الكراسي وبنو أمية على الوسائد قد ثنيت لهم وكانوا في أيام دولتهم يجلسون هم والخلفاء منهم على السرير ويجلس بنو هاشم على الكراسي فدخل الحاجب فقال يا أمير المؤمنين بالباب رجل حجازي أسود راكب على نجيب متلثم يستأذن ولا يخبر باسمه ويحلف ألا يحسر اللثام عن وجهه حتى يراك قال هذا مولاي سديف يدخل فدخل فلما نظر إلى أبي\nالعباس وبنو أمية حوله حدر اللثام عن وجهه وأنشأ يقول\n(أصبح الملك ثابت الآساس ... بالبهاليل من بني العباس)\n(بالصدور المقدمين قديما ... والرؤوس القماقم الرؤاس)\n(يا أمير المطهرين من الذم ... ويا رأس منتهى كل راس)\n(أنت مهدي هاشم وهداها ... كم أناس رجوك بعد إياس)\n(لا تقيلن عبد شمس عثارا ... واقطعن كل رقلة وغراس)\n(أنزلوها بحيث أنزلها الله ... بدار الهوان والإتعاس)\n(خوفهم أظهر التودد منهم ... وبهم منكم كحز المواسي)\n(أقصهم أيها الخليفة واحسم ... عنك بالسيف شأفة الأرجاس)\n(واذكرن مصرع الحسين وزيد ... وقتيل بجانب المهراس)\n(والإمام الذي بحران أمسى ... رهن قبر في غربة وتناسي)\n(فلقد ساءني وساء سوائي ... قربهم من نمارق وكراسي)\n(نعم كلب الهراش مولاك لولا ... أود من حبائل الإفلاس)\nتغير لون أبي العباس وأخذه زمع ورعدة فالتفت بعض ولد سليمان بن عبد الملك إلى رجل منهم وكان إلى جنبه فقال قتلنا والله العبد ثم أقبل أبو العباس عليهم فقال يا بني الفواعل أرى قتلاكم من أهلي قد سلفوا وأنتم أحياء تتلذذون في الدنيا خذوهم فأخذتهم الخراسانية بالكافر كوبات فأهمدوا إلا ما كان من عبد العزيز بن عمر بن عبد العزيز فإنه استجار بداود بن علي وقال له إن أبي لم يكن كآبائهم وقد علمت صنيعته إليكم فأجاره واستوهبه من السفاح وقال له قد علمت يا أمير المؤمنين صنيع أبيه إلينا فوهبه له وقال له لا تريني وجهه وليكن بحيث تأمنه وكتب إلى عماله في النواحي بقتل بني أمية","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":4,"spl":"مقتل جماعة من الأمويين في اجتماع عند السفاح"},
{"id":"b42-10","bab":"الجزء 4","sec":"لماذا قتل السفاح بني أمية","page":"ج4 ص340","text":"أخبرني الحسن بن علي قال حدثني أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار عن عمه أن سبب قتل بني أمية أن السفاح أنشد قصيدة مدح بها فأقبل على بعضهم فقال أين هذا مما مدحتم به فقال هيهات لا يقول والله أحد فيكم مثل قول ابن قيس الرقيات فينا\n(ما نقموا من بني أمية إلا ... أنهم يحلمون إن غضبوا)\n(وأنهم معدن الملوك ولا ... تصلح إلا عليهم العرب)\nقال له يا ماص كذا من أمه أو إن الخلافة لفي نفسك بعد خذوهم فأخذوا فقتلوا أخبرني عمي عن الكراني عن النضر بن عمرو عن المعيطي أن أبا العباس دعا بالغداء حين قتلوا وأمر ببساط فبسط عليهم وجلس فوقه يأكل وهم يضطربون تحته فلما فرغ من الأكل قال ما أعلمني أكلت أكلة قط أهنأ ولا أطيب لنفسي منها فلما فرغ قال جروا بأرجلهم فألقوا في الطريق يلعنهم الناس أمواتا كما لعنوهم أحياء قال فرأيت الكلاب تجر بأرجلهم وعليهم سراويلات الوشي حتى أنتنوا ثم حفرت لهم بئر فألقوا فيها أخبرني عمر بن عبد الله بن جميل العتكي قال حدثنا عمر بن شبة قال حدثني محمد بن معن الغفاري عن أبيه قال لما أقبل داود بن علي من مكة أقبل معه بنو حسن جميعا وحسين بن علي بن حسين وعلي بن عمر بن علي بن حسين وجعفر بن محمد والأرقط محمد بن عبد الله وحسين بن زيد ومحمد بن عبد الله بن عمرو بن عثمان وعبد الله بن عنبسة بن سعيد بن العاصي وعروة وسعيد ابنا خالد بن سعيد بن عمرو بن عثمان فعمل لداود مجلس بالرويثة فجلس عليه هو والهاشميون وجلس الأمويون تحتهم فأنشده إبراهيم بن هرمة قصيدة يقول فيها\n(فلا عفا الله عن مروان مظلمة ... ولا أمية بئس المجلس النادي)\n(كانوا كعاد فأمسى الله أهلكهم ... بمثل ما أهلك الغاوين من عاد)\n(فلن يكذبني من هاشم من أحد ... فيما أقول ولو أكثرت تعدادي)\nقال فنبذ داود نحو ابن عنبسة ضحكة كالكشرة فلما قام قال عبد الله بن حسن لأخيه حسن أما رأيت ضحكته إلى ابن عنبسة الحمد لله الذي صرفها عن أخي يعني العثماني قال فما هو إلا أن قدم المدينة حتى قتل ابن عنبسة قال محمد بن معن حدثني محمد بن عبد الله بن عمرو بن عثمان قال استحلف أخي عبد الله بن حسن داود بن علي وقد حج معه سنة اثنتين وثلاثين ومائة بطلاق امرأته مليكة بنت دواد بن حسن ألا يقتل أخويه محمدا والقاسم ابني عبد الله قال فكنت أختلف إليه آمنا وهو يقول بني أمية وكان يكره أن يراني أهل خراسان ولا يستطيع إلي سبيلا ليمينه فاستدناني يوما فدنوت منه فقال ما أكثر الغفلة وأقل الحزمة فأخبرت بها عبد الله بن حسن فقال يابن أم تغيب عن الرجل فتغيبت عنه حتى مات","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":5,"spl":"لماذا قتل السفاح بني أمية — خبر آخر عن مقتل الأمويين عند السفاح"},
{"id":"b42-11","bab":"الجزء 4","sec":"خبر آخر عن مقتل الأمويين عند السفاح","page":"ج4 ص342","text":"أخبرني الحسن بن علي ومحمد بن يحيى قالا حدثنا الحارث بن أبي أسامة قال حدثني إسماعيل بن إبراهيم عن الهيثم بن بشر مولى محمد بن علي قال أنشد سديف أبا العباس وعنده رجال من بني أمية قوله\n(يابن عم النبي أنت ضياء ... استبنا بك اليقين الجليا)\nلما بلغ قوله\n(جرد السيف وارفع العفو حتى ... لا ترى فوق ظهرها أمويا)\n(لا يغرنك ما ترى من رجال ... إن تحت الضلوع داء دويا)\n(بطن البغض في القديم فأضحى ... ثاويا في قلوبهم مطويا)\nهي طويلة قال يا سديف خلق الإنسان من عجل ثم قال\n(أحيا الضغائن آباء لنا سلفوا ... فلن تبيد وللآباء أبناء)\nم أمر بمن عنده منهم فقتلوا أخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد بن سليمان النوفلي عن أبيه عن عمومته أنهم حضروا سليمان بن علي بالبصرة وقد حضره جماعة من بني أمية عليهم الثياب الموشية المرتفعة فكأني أنظر إلى أحدهم وقد أسود شيب في عارضيه من الغالية فأمر بهم فقتلوا وجروا بأرجلهم فألقوا على الطريق وإن عليهم لسراويلات الوشي والكلاب تجر بأرجلهم","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":5,"spl":"لماذا قتل السفاح بني أمية — خبر آخر عن مقتل الأمويين عند السفاح"},
{"id":"b42-12","bab":"الجزء 4","sec":"عمرو بن معاوية يأخذ الأمان من سليمان بن علي","page":"ج4 ص343","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثني محمد بن عبد الله بن عمرو قال أخبرني طارق بن المبارك عن أبيه قال جاءني رسول عمرو بن معاوية بن عمرو بن عتبة فقال لي يقول لك عمرو قد جاءت هذه الدولة وأنا حديث السر كثير العيال منتشر المال فما أكون في قبيلة إلا شهر أمري وعرفت وقد اعتزمت على أن أفدي حرمي بنفسي وأنا صائر إلى باب الأمير سليمان بن علي فصر إلي فوافيته فإذا عليه طيلسان مطبق أبيض\nوسراويل وشي مسدول فقلت يا سبحان الله ما تصنع الحداثة بأهلها أبهذا اللباس تلقى هؤلاء القوم لما تريد لقاءهم فيه فقال لا والله ولكنه ليس عندي ثوب إلا أشهر مما ترى فأعطيته طيلساني وأخذت طيلسانه ولويت سراويله إلى ركبتيه فدخل ثم خرج مسرورا فقلت له حدثني ما جرى بينك وبين الأمير قال دخلت عليه ولم نتراء قط فقلت أصلح الله الأمير لفظتني البلاد إليك ودلني فضلك عليك فإما قتلتني غانما وإما رددتني سالما فقال ومن أنت ما أعرفك فانتسبت له فقال مرحبا بك أقعد فتكلم آمنا غانما ثم أقبل علي فقال ما حاجتك يابن أخي فقلت إن الحرم اللواتي أنت أقرب الناس إليهن معنا وأولى الناس بهن بعدنا قد خفن لخوفنا ومن خاف خيف عليه فوالله ما أجابني إلا بدموعه على خديه ثم قال يابن أخي يحقن الله دمك ويحفظك في حرمك ويوفر عليك مالك ووالله لو أمكنني ذلك في جميع قومك لفعلت فكن متواريا كظاهر وآمنا كخائف ولتأتني رقاعك قال فكنت والله أكتب إليه كما يكتب الرجل إلى أبيه وعمه قال فلما فرغ من الحديث رددت عليه طيلسانه فقال مهلا فإن ثيابنا إذا فارقتنا لن ترجع إلينا","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":6,"spl":"عمرو بن معاوية يأخذ الأمان من سليمان بن علي — قول الشعراء في تحريض السفاح على بني أمية"},
{"id":"b42-13","bab":"الجزء 4","sec":"قول الشعراء في تحريض السفاح على بني أمية","page":"ج4 ص344","text":"أخبرني أحمد بن عبد الله قال حدثنا أحمد بن عبد العزيز قال حدثنا عمر ابن شبة قال قال سديف لأبي العباس يحضه على بني أمية ويذكر من قتل مروان وبنو أمية من قومه\n(كيف بالعفو عنهم وقديما ... قتلوكم وهتكوا الحرمات)\n(أين زيد وأين يحيى بن زيد ... يا لها من مصيبة وترات)\n(والإمام الذي أصيب بحران ... إمام الهدى ورأس الثقات)\n(قتلوا آل أحمد لا عفا الذنب ... لمروان غافر السيئات)\nخبرني علي بن سليمان الأخفش قال أنشدني محمد بن يزيد لرجل من شيعة بني العباس يحرضهم على بني أمية\n(إياكم أن تلينوا لاعتذارهم ... فليس ذلك إلا الخوف والطمع)\n(لو أنهم أمنوا أبدوا عداوتهم ... لكنهم قمعوا بالذل فانقمعوا)\n(أليس في ألف شهر قد مضت لهم ... سقوكم جرعا من بعدها جرع)\n(حتى إذا ما انقضت أيام مدتهم ... متوا إليكم بالأرحام التي قطعوا)\n(هيهات لا بد أن يسقوا بكأسهم ... ريا وأن يحصدوا الزرع الذي زرعوا)\n(إنا وإخواننا الأنصار شيعتكم ... إذا تفرقت الأهواء والشيع)\n(إياكم أن يقول الناس إنهم ... قد ملكوا ثم ما ضروا ولا نفعوا)\nذكر ابن المعتز أن جعفر بن إبراهيم حدثه عن إسحاق بن منصور عن أبي الخصيب في قصة سديف بمثل ما ذكره الكراني عن النضر بن عمرو عن المعيطي إلا أنه قال فيها فلما أنشده ذلك التفت إليه أبو الغمر سليمان بن هشام فقال يا ماص بظر أمه أتجبهنا بهذا ونحن سروات الناس فغضب أبو العباس وكان سليمان بن هشام صديقه قديما وحديثا يقضي حوائجه في أيامهم ويبره فلم يلتفت إلى ذلك\nوصاح بالخراسانية خذوهم فقتلوا جمعيا إلا سليمان بن هشام فأقبل عليه السفاح فقال يا أبا الغمر ما أرى لك في الحياة بعد هؤلاء خيرا قال لا والله فقال اقتلوه وكان إلى جنبه فقتل وصلبوا في بستانه حتى تأذى جلساؤه بروائحهم فكلموه في ذلك فقال والله لهذا ألذ عندي من شم المسك والعنبر غيظا عليهم وحنقا","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":6,"spl":"عمرو بن معاوية يأخذ الأمان من سليمان بن علي — قول الشعراء في تحريض السفاح على بني أمية"},
{"id":"b42-14","bab":"الجزء 4","sec":"نسبة ما في هذه الأخبار من الغناء","page":"ج4 ص346","text":"صوت\n(أصبح الدين ثابت الاساس ... بالبهاليل من بني العباس)\n(بالصدور المقدمين قديما ... والرؤوس القماقم الرؤاس)\nروضه من الخفيف الشعر لسديف والغناء لعطرد رمل بالبنصر عن حبش قال وفيه لحكم الوادي ثاني ثقيل وفيه ثقيل أول مجهول ومما قاله أبو سعيد مولى فائد في قتلى بني أمية وغنى فيه صوت\n(بكيت وماذا يرد البكاء ... وقل البكاء لقتلى كداء)\n(أصيبوا معا فتولوا معا ... كذلك كانوا معا في رخاء)\n(بكت لهم الأرض من بعدهم ... وناحت عليهم نجوم السماء)\n(وكانوا الضياء فلما انقضى الزمان بقومي تول الضياء ... )\nعروضه من المتقارب الشعر والغناء لأبي سعيد مولى فائد ولحنه من الثقيل الأول بالبنصر من رواية عمرو بن بانة وإسحاق وغيرهما\nومما قاله فيهم وغنى فيه على أنه قد نسب إلى غيره صوت\n(أثر الدهر في رجالي فقلوا ... بعد جمع فراح عظمي مهيضا)\n(ما تذكرتهم فتملك عيني ... فيض غرب وحق لي أن تفيضا)\nالشعر والغناء لأبي سعيد خفيف ثقيل بالوسطى عن ابن المكي والهشامي وروى الشيعي عن عمر بن شبة عن إسحاق أن الشعر لسديف والغناء للغريض ولعله وهم ومنها صوت\n(أولئك قومي بعد عز ومنعة ... تفانوا فإلا تذرف العين أكمد)\n(كأنهم لا ناس للموت غيرهم ... وإن كان فيهم منصفا غير معتدي)\nلشعر والغناء لأبي سعيد وفيه لحن لمتيم","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":7,"spl":"نسبة ما في هذه الأخبار من الغناء — خبر المأمون مع المغني علويه","partial":1},
{"id":"b42-15","bab":"الجزء 4","sec":"خبر المأمون مع المغني علويه","page":"ج4 ص347","text":"أخبرني عبد الله بن الربيع قال حدثنا أحمد بن إسماعيل بن إبراهيم قال حدثني عمي طياب بن إبراهيم قال ركب المأمون بدمشق يتصيد حتى بلغ جبل الثلج فوقف في بعض الطريق على بركة عظيمة في جوانبها أربع سروات لم ير أحسن منها ولا أعظم فنزل المأمون وجعل ينظر إلى آثار بني أمية ويعجب منها ويذكرهم ثم دعا بطبق عليه\nبزما ورد ورطل نبيذ فقام علويه فغنى\n(أولئك قومي بعد عز ومنعة ... تفانوا فإلا تذرف العين أكمد)\nال فغضب المأمون وأمر برفع الطبق وقال يابن الزانية ألم يكن لك وقت تبكي فيه على قومك إلا هذا الوقت قال نعم أبكي عليهم مولاكم زرياب يركب معهم في مائة غلام وأنا مولاهم معكم أموت جوعا فقام المأمون فركب وانصرف الناس وغضب على علويه عشرين يوما فكلمه فيه عباس أخو بحر فرضي عنه ووصله بعشرين ألف درهم","topic":"ذكر أخبار أبي سعيد مولى فائد ونسبه","topicNo":42,"sp":7,"spl":"نسبة ما في هذه الأخبار من الغناء — خبر المأمون مع المغني علويه"},
{"id":"b43-1","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص348","text":"(مهاة لو ان الذر تمشي ضعافه ... على متنها بضت مدارجه دما)\n(فقلن لها قومي فديناك فاركبي ... فأومت بلا لا غير أن تتكلما)\nروضه من الطويل بضت سالت يقول لو مشى الذر على جلدها لجرى منه الدم من رقته وروى الأصمعي\n(منعمة لو يصبح الذر ساريا ... على متنها بضت مدارجه دما)\nلشعر لحميد بن ثور الهلالي والغناء في اللحن المختار لفليح بن أبي\nالعوراء ولحنه من الثقيل الأول بالوسطى وذكر عمرو بن بانه أن لحن فليح من خفيف الثقيل الأول بالوسطى وأن الثقيل الأول للهذلي ومما يغني فيه من هذه القصيدة صوت\n(إذا شئت غنتني بأجزاع بيشة ... أو النخل من تثليث أو من يلملما)\n(مطوقة طوقا وليس بحلية ... ولا ضرب صواغ بكفيه درهما)\n(تبكي على فرخ لها ثم تغتدي ... مولهة تبغي له الدهر مطعما)\n(تؤمل منه مؤنسا لانفرادها ... وتبكي عليه إن زقا أو ترنما)\nناه محمد الرف خفيف رمل بالوسطى","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":0,"spl":"صوت من المائة المختارة — أخبار فليح بن أبي العوراء"},
{"id":"b43-2","bab":"الجزء 4","sec":"ذكر حميد بن ثور ونسبه وأخباره","page":"ج4 ص349","text":"هو حميد بن ثور بن عبد الله بن عامر بن أبي ربيعة بن نهيك بن هلال بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة ابن قيس بن عيلان بن مضر بن نزار وهو من شعراء الإسلام وقرنه ابن سلام بنهشل بن حري وأوس بن مغراء وقد أدرك حميد بن ثور عمر بن الخطاب رضي الله عنه وقال الشعر في أيامه وقد أدرك الجاهلية أيضا","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":0,"spl":"صوت من المائة المختارة — أخبار فليح بن أبي العوراء"},
{"id":"b43-3","bab":"الجزء 4","sec":"يخرج على نهي عمر ويشبب بالنساء","page":"ج4 ص350","text":"أخبرنا وكيع قال حدثنا عبد الله بن أبي سعد وعبد الله بن شبيب قالا حدثنا إبراهيم بن المنذر الحزامي قال حدثني محمد بن فضالة النحوي قال تقدم عمر بن الخطاب رضي الله عنه إلى الشعراء ألا يشبب أحدا بامرأة إلا جلده فقال حميد بن ثور\n(أبى الله إلا أن سرحة مالك ... على كل أفنان العضاة تروق)\n(فقد ذهبت عرضا وما فوق طولها ... من السرح إلا عشة وسحوق)\nلعشة القليلة الأغصان والورق والسحوق الطويلة المفرطة\n(فلا الظل من برد الضحى تستطيعه ... ولا الفيء من برد العشي تذوق)\n(فهل أنا إن عللت نفسي بسرحة ... من السرح موجود علي طريق)\nهي قصيدة طويلة أولها\n(نأت أم عمر فالفؤاد مشوق ... يحن إليها والها ويتوق)\nصوت وفيها ما يغني فيه\n(سقى السرحة المحلال والأبرق الذي ... به السرح غيث دائم وبروق)\n(وهل أنا إن عللت نفسي بسرحة ... من السرح موجود علي طريق)\nناه إسحاق ولحنه ثاني ثقيل بالوسطى أخبرنا الحرمي قال حدثنا الزبير عن عمه قال وفد حميد بن ثور على بعض خلفاء بني أمية فقال له ما جاء بك فقال\n(أتاك بي الله الذي فوق من ترى ... وخير ومعروف عليك دليل)\n(ومطوية الأقراب أما نهارها ... فنص وأما ليلها فذميل)\n(ويطوي علي الليل حضنيه إنني ... لذاك إذا هاب الرجال فعول)\nوصله وصرفه شاكرا","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":0,"spl":"صوت من المائة المختارة — أخبار فليح بن أبي العوراء"},
{"id":"b43-4","bab":"الجزء 4","sec":"أخبار فليح بن أبي العوراء","page":"ج4 ص352","text":"فليح رجل من أهل مكة مولى لبني مخزوم ولم يقع إلينا اسم أبيه وهو أحد مغني الدولة العباسية له محل كبير من صناعته وموضع جليل وكان إسحاق إذا عد من سمع من المحسنين ذكره فيهم وبدأ به وهو أحد الثلاثة الذين اختاروا المائة الصوت للرشيد","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":0,"spl":"صوت من المائة المختارة — أخبار فليح بن أبي العوراء"},
{"id":"b43-5","bab":"الجزء 4","sec":"إسحاق الموصلي يمدح غناءه","page":"ج4 ص353","text":"أخبرني أحمد بن جعفر جحظة قال حدثني ابن المكي عن أبيه عن إسحاق قال ما سمعت أحسن غناء من فليح بن أبي العوراء وابن جامع فقلت له فأبو إسحاق يعني أباه فقال كان هذان لا يحسنان غير الغناء وكان أبو إسحاق فيه مثلهما ويزيد عليهما فنونا من الأدب والرواية لا يداخلانه فيها أخبرني الحسن بن علي قال حدثنا يزيد بن محمد المهلبي قال قال لي إسحاق أحسن من سمعت غناء عطرد وفليح وكان فليح أحد الموصوفين بحسن الغناء المسموع في أيامه وهو أحد من كان يحكي الأوائل فيصيب ويحسن أخبرني الحسن بن علي قال حدثني هارون بن محمد بن عبد الملك الزيات\nقال حدثني محمد بن محمد العنبسي قال حدثني محمد بن الوليد الزبيري قال سمعت كثير بن المحول يقول كان مغنيان بالمدينة يقال لأحدهما فليح بن أبي العوراء والآخر سليمان بن سليم فخرج إليهما رسول الرشيد يقول لفليح غناؤك من حلق أبي صدقة أحسن منه من حلقك فعلمه إياه قال وكان يغني صوتا يجيده وهو\n(خير ما نشربها بالبكر ... )\nال فقال فليح للرسول قل له حسبك قال فسمعنا ضحكة من وراء الستارة","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":1,"spl":"إسحاق الموصلي يمدح غناءه — تفرده برؤية المهدي وهو يغني","partial":1},
{"id":"b43-6","bab":"الجزء 4","sec":"تفرده برؤية المهدي وهو يغني","page":"ج4 ص354","text":"أخبرني رضوان بن أحمد الصيدلاني قال حدثنا يوسف بن إبراهيم قال حدثني أبو إسحاق إبراهيم بن المهدي قال حدثنا الفضل بن الربيع أن المهدي كان يسمع المغنين جميعا ويحضرون مجلسه فيغنونه من وراء الستارة لا يرون له وجها إلا فليح بن أبي العوراء فإن عبد الله بن مصعب الزبيري كان يرويه شعره ويغني فيه في مدائحه للمهدي فدس في أضعافها بيتين يسأله فيهما أن ينادمه وسأل فليحا أن يغنيهما في أضعاف أغانيه وهما صوت\n(يا أمين الإله في الشرق والغرب ... على الخلق وابن عم الرسول)\n(مجلسا بالعشي عندك في الميدان ... أبغي والإذن لي في الوصول)\nغناه فليح إياهما فقال المهدي يا فضل أجب عبد الله إلى ما سأل وأحضره مجلسي إذا حضره أهلي وموالي وجلست لهم وزده على ذلك أن ترفع بيني وبين\nروايته فليح الستارة فكان فليح أول مغن عاين وجهه في مجلسهم أخبرني رضوان قال حدثني يوسف بن إبراهيم قال حدثني بعد قدومي فسطاط مصر زياد بن أبي الخطاب كاتب مسرور خادم الرشيد قال سمعت محبوب بن الهفتي يحدث أبي قال دعاني محمد بن سليمان بن علي فقال لي قد قدم فليح من الحجاز ونزل عند مسجد ابن رغبان فصر إليه فأعلمه أنه إن جاءني قبل أن يدخل إلى الرشيد خلعت عليه خلعة سرية من ثيابي ووهبت له خمسة آلاف درهم فمضيت إليه فخبرته بذلك فأجابني إليه إجابة مسرور به نشيط له وخرج معي فعدل إلى حمام كان بقربه فدعا القيم فأعطاه درهمين وسأله أن يجيئه بشيء يأكله ونبيذ يشربه فجاءه برأس كأنه رأس عجل ونبيذ دوشابي غليظ مسحوري رديء فقلت له لا تفعل وجهدت به ألا يأكل ولا يشرب إلا عند محمد بن سليمان فلم يلتفت إلي وأكل ذلك الرأس وشرب من ذلك النبيذ الغليظ حتى طابت نفسه وغنى وغنى القيم معه مليا ثم خاطب القيم بما أغضبه وتلاحيا وتواثبا فأخذ القيم شيئا فضربه به على رأسه فشجه حتى جرى دمه فلما رأى الدم على وجهه اضطرب وجزع وقام يغسل جرحه ودعا بصوفة محرقة وزيت وعصبه وتعمم وقام معي فلما دخلنا دار محمد بن سليمان ورأى الفرش والآلة وحضر الطعام فرأى سروه وطيبه وحضر النبيذ وآلته ومدت الستائر وغنى الجواري أقبل علي وقال يا مجنون سألتك بالله أيما أحق بالعربدة وأولى مجلس القيم أم مجلس الأمير فقلت وكأنه لا بد من عربدة قال لا والله مالي منها بد فأخرجتها من\nرأسي هناك فقلت أما على هذا الشرط فالذي فعلت أجود فسألني محمد عما كنا فيه فأخبرته فضحك ضحكا كثيرا وقال هذا الحديث والله أظرف وأطيب من كل غناء وخلع عليه وأعطاه خمسة آلاف درهم","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":1,"spl":"إسحاق الموصلي يمدح غناءه — تفرده برؤية المهدي وهو يغني"},
{"id":"b43-7","bab":"الجزء 4","sec":"اتفق مع حكم الوادي على ابن جامع","page":"ج4 ص356","text":"قال هارون بن محمد وحدثني حماد بن إسحاق قال حدثني أبو إسحاق القرمطي قال حدثنا مدركة بن يزيد قال قال فليح بن أبي العوراء بعث يحيى بن خالد إلي والى حكم الوادي وإلى ابن جامع فأتيناه فقلت لحكم إن قعد ابن جامع معنا فعاوني عليه لنكسره فلما صرنا إلى الغناء غنى حكم فصحت وقلت هكذا والله يكون الغناء ثم غنيت ففعل لي حكم مثل ذلك وغنى ابن جامع فما كنا معه في شيء فلما كان العشي أرسل إلى جاريته دنانير إن أصحابك عندنا فهل لك أن تخرجي إلينا فخرجت وخرج معها وصائف فأقبل عليها يقول لها من حيث يظن أنا لا نسمع ليس في القوم أنزه نفسا من فليح ثم أشار إلى غلام له أن ائت كل إنسان بألفي درهم فجاء بها فدفع إلى ابن جامع ألفي درهم فأخذها فطرحها في كمه وفعل بحكم الوادي مثل ذلك فطرحها في كمه ودفع إلي ألفين فقلت لدنانير قد بلغ مني النبيذ فاحبسيها لي عندك حتى تبعثي بها إلي فأخذت الدراهم مني وبعثت بها إلي من الغد وقد زادت عليها وأرسلت إلي قد بعثت إليك بوديعتك وبشيء أحببت أن تفرقه على أخواتي تعني جواري\nقال هارون بن محمد وحدثني حماد قال حدثني أبي قال كنا عند الفضل بن الربيع فقال هل لك في فليح بن أبي العوراء قلت نعم فأرسل إليه فجاء الرسول فقال هو عليل فعاد إليه فقال الرسول لا بد من أن تجيء فجاء به محمولا في محفة فحدثنا ساعة ثم غنى فكان فيما غنى\n(تقول عرسي إذ نبا المضجع ... ما بالك الليلة لا تهجع)\nاستحسناه منه واستعدناه منه مرارا ثم انصرف ومات في علته تلك وكان آخر العهد به ذلك المجلس","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":2,"spl":"اتفق مع حكم الوادي على ابن جامع — انتشار أغانيه بأصوات جواري إبراهيم بن المهدي"},
{"id":"b43-8","bab":"الجزء 4","sec":"غنى لفتى وعشيقته فعجلت في أمر خطبتها","page":"ج4 ص357","text":"أخبرني أحمد بن جعفر جحظة قال حدثني محمد بن أحمد بن يحيى المكي قال حدثني أبي عن فليح بن أبي العوراء قال كان بالمدينة فتى يعشق ابنة عم له فوعدته أن تزوره وشكا إلي أنها تأتيه ولا شيء عنده فأعطيته دينارا للنفقة فلما زارته قالت له من يلهينا قال صديق لي ووصفني لها ودعاني فأتيته فكان أول ما غنيته\n(من الخفرات لم تفضح أخاها ... ولم ترفع لوالدها شنارا)\nقامت إلى ثوبها فلبسته لتنصرف فعلق بها وجهد بها كل الجهد في أن تقيم فلم تقم وانصرفت فأقبل علي يلومني في أن غنيتها ذلك الصوت فقلت والله ما هو شيء اعتمدت به مساءتك ولكنه شيء اتفق قال فلم نبرح حتى عاد رسولها بعدها ومعه صرة فيها ألف دينار ودفعها إلى الفتى وقال له تقول لك ابنة عمك هذا مهري ادفعه إلى أبي واخطبني ففعل فتزوجها","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":2,"spl":"اتفق مع حكم الوادي على ابن جامع — انتشار أغانيه بأصوات جواري إبراهيم بن المهدي"},
{"id":"b43-9","bab":"الجزء 4","sec":"نسبة هذا الصوت","page":"ج4 ص357","text":"صوت\n(من الخفرات لم تفضح أخاها ... ولم ترفع لوالدها شنارا)\n(كأن مجامع الأرداف منها ... نقا درجت عليه الريح هارا)\n(يعاف وصال ذات البذل قلبي ... وأتبع الممنعة النوارا)\nلشعر لسليك بن السلكة السعدي والغناء لابن سريج رمل بالسبابة في مجرى الوسطى وفيه لابن الهربذ لحن من رواية بذل أوله\n(يعاف وصال ذات البذل قلبي ... )\nوبعده\n(غذاها قارص يغدو عليها ... ومحض حين تنتظر العشارا)","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":2,"spl":"اتفق مع حكم الوادي على ابن جامع — انتشار أغانيه بأصوات جواري إبراهيم بن المهدي","partial":1},
{"id":"b43-10","bab":"الجزء 4","sec":"انتشار أغانيه بأصوات جواري إبراهيم بن المهدي","page":"ج4 ص358","text":"أخبرني رضوان بن أحمد قال حدثنا يوسف بن إبراهيم قال حدثنا أبو إسحاق إبراهيم بن المهدي قال كتب إلي جعفر بن يحيى وأنا عامل للرشيد على جند دمشق قد قدم علينا فليح بن أبي العوراء فأفسد علينا بأهزاجه وخفيفه كل غناء سمعناه قبله وأنا محتال لك في تخليصه إليك لتستمتع به كما استمتعنا فلم ألبث أن ورد علي فليح بكتاب الرشيد يأمر له بثلاثة آلاف دينار فورد علي رجل أذكرني لقاؤه الناس\nوأخبرني أنه قد ناهز المائة فأقام عندي ثلاث سنين فأخذ عنه جواري كل ما كان معه من الغناء وانتشرت أغانيه بدمشق قال يوسف ثم قدم علينا شاب من المغنين مع علي بن زيد بن الفرج الحراني عند مقدم عنبسة بن إسحاق فسطاط مصر يقال له مونق فغناني من غناء فليح صوت\n(يا قرة العين اقبلي عذري ... ضاق بهجرانكم صدري)\n(لو هلك الهجر استراح الهوى ... ما لقى الوصل من الهجر)\nلحنه خفيف رمل فلم أر بين ما غناه وبين ما سمعته في دار أبي إسحاق فرقا فسألته من أين أخذه فقال أخذته بدمشق فعلمت أنه مما أخذه أهل دمشق عن فليح","topic":"ذكر حميد بن ثور ونسبه وأخباره","topicNo":43,"sp":2,"spl":"اتفق مع حكم الوادي على ابن جامع — انتشار أغانيه بأصوات جواري إبراهيم بن المهدي"},
{"id":"b44-1","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص359","text":"(أفاطم إن النأي يسلي ذوي الهوى ... ونأيك عني زاد قلبي بكم وجدا)\n(أرى حرجا ما نلت من ود غيركم ... ونافلة ما نلت من ودكم رشدا)\n(وما نلتقي من بعد نأي وفرقة ... وشحط نوى إلا وجدت له بردا)\n(على كبد قد كان يبدي بها الهوى ... ندوبا وبعض القوم يحسبني جلدا)\nروضه من الطويل النأي البعد ومثله الشحط والحرج الضيق قال الله تعالى ( يجعل صدره ضيقا حرجا\nوالندوب آثار الجراح واحدها ندب الشعر لإبراهيم بن هرمة والغناء في اللحن المختار على ما ذكره\nإسحاق ليونس الكاتب وهو من الثقيل الأول بإطلاق الوتر في مجرى الوسطى وذكر يحيى بن علي بن يحيى عن أبيه مثل ذلك وذكر حبش بن موسى أن الغناء لمرزوق الصراف أو ليحيى بن واصل وفي هذه الأبيات للهذلي لحن من خفيف الثقيل الأول بالوسطى على مذهب إسحاق من رواية عمرو بن بانة ومن الناس من ينسب اللحنين جميعا إليه","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":0,"spl":"صوت من المائة المختارة — ذكر ابن هرمة وأخباره ونسبه"},
{"id":"b44-2","bab":"الجزء 4","sec":"ذكر ابن هرمة وأخباره ونسبه","page":"ج4 ص361","text":"هو إبراهيم بن علي بن سلمة بن هرمة بن هذيل هكذا ذكر يعقوب بن السكيت وأخبرني الحرمي بن أبي العلاء عن الزبير بن بكار عن عمه مصعب وذكر ذلك العباس بن هشام الكلبي عن أبيه هشام بن محمد بن السائب قالوا جميعا هو إبراهيم بن علي بن سلمة بن عامر بن هرمة بن الهذيل بن ربيع بن عامر ابن صبيح بن كنانة بن عدي بن قيس بن الحارث بن فهر وفهر أصل قريش فمن لم يكن من ولده لم يعد من قريش وقد قيل ذلك في النضر بن كنانة وفهر ابن مالك بن النضر بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر قال من ذكرنا من النسابين قيس بن الحارث هو الخلج وكانوا في عدوان ثم انتقلوا إلى بني نصر بن معاوية بن بكر بن هوازن فلما استخلف عمر بن الخطاب رضي الله عنه أتوه ليفرض لهم فأنكر نسبهم فلما استخلف عثمان أتوه فأثبتهم في بني الحارث بن فهر وجعل لهم معهم ديوانا وسموا الخلج لأنهم اختلجوا ممن كانوا معه من عدوان ومن بني نصر بن معاوية وأهل المدينة يقولون إنما سموا الخلج لأنهم نزلوا بالمدينة على خلج وواحدها خليج فسموا بذلك ولهم\nبالمدينة عدد قال مصعب كان لإبراهيم بن هرمة عم يقال له هرمة الأعور فأرادت الخلج نفيه منهم فقال أمسيت الأم العرب دعي أدعياء ثم قال يهجوهم\n(رأيت بني فهر سباطا أكفهم ... فما بال أنبوني أكفكم قفدا)\n(ولم تدركوا ما أدرك القوم قبلكم ... من المجد إلا دعوة ألحقت كدا)\n(على ذي أيادي الدهر أفلح جدهم ... وخبتم فلم يصرع لكم جدكم جدا)\nقال يحيى بن علي حدثني أبو أيوب المديني عن المدائني عن أبي سلمة الغفاري قال نفى بنو الحارث بن فهر ابن هرمة فقال\n(أحاربن فهر كيف تطرحونني ... وجاء العدا من غيركم تبتغي نصري)\nال فصار من ولد فهر في ساعته قال يحيى بن علي وحدثني أحمد بن يحيى الكاتب قال حدثني العباس بن هشام الكلبي عن أبيه قال كان ابن هرمة يقول أنا الأم العرب دعي أدعياء هرمة دعي في الخلج والخلج أدعياء في قريش","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":0,"spl":"صوت من المائة المختارة — ذكر ابن هرمة وأخباره ونسبه"},
{"id":"b44-3","bab":"الجزء 4","sec":"خبره مع رجل من أسلم ضافه","page":"ج4 ص362","text":"حدثني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمر بن\nأبي بكر المؤملي قال حدثني عبد الله بن أبي عبيدة بن محمد بن عمار بن ياسر قال زرت عبد الله بن حسن بباديته وزاره ابن هرمة فجاءه رجل من أسلم فقال ابن هرمة لعبد الله بن حسن أصلحك الله سل الأسلمي أن يأذن لي أن أخبرك خبري وخبره فقال له عبد الله بن حسن ائذن له فأذن له الأسلمي فقال له إبراهيم بن هرمة إني خرجت أصلحك الله أبغي ذودا لي فأوحشت وضفت هذا الأسلمي فذبح لي شاة وخبز لي خبزا وأكرمني ثم غدوت من عنده فأقمت ما شاء الله ثم خرجت أيضا في بغاء ذود لي فأوحشت فضفته فقراني بلبن وتمر ثم غدوت من عنده فأقمت ما شاء الله ثم خرجت في بغاء ذود لي فأوحشت فقلت لو ضفت الأسلمي فاللبن والتمر خير من الطوى فضفته فجاءني بلبن حامض فقال قد أجبته أصلحك الله إلى ما سأل فسله أن يأذن لي أن أخبرك لم فعلت فقال له ائذن له فأذن له فقال الأسلمي ضافني فسألته من هو فقال رجل من قريش فذبحت له الشاة التي ذكر ووالله لو كان غيرها عندي لذبحته له حين ذكر أنه من قريش ثم غدا من عندي وغدا علي الحي فقالوا من كان ضيفك البارحة قلت رجل من قريش فقالوا لا والله ما هو من قريش ولكنه دعي فيها ثم ضافني الثانية على أنه دعي في قريش فجئته بلبن وتمر وقلت دعي قريش خير من غيره ثم غدا من عندي ثم غدا علي الحي فقالوا من كان ضيفك البارحة قلت الرجل الذي زعمتم أنه دعي في قريش فقالوا لا والله ما هو بدعي في قريش ولكنه دعي أدعياء قريش ثم\nجاءني الثالثة فقريته لبنا حامضا ووالله لو كان عندي شر منه لقريته إياه قال فانخذل ابن هرمة وضحك عبد الله وضحكنا معه","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":1,"spl":"خبره مع رجل من أسلم ضافه — طلب منه ابن ميادة أن يتهاجيا"},
{"id":"b44-4","bab":"الجزء 4","sec":"طلب منه ابن ميادة أن يتهاجيا","page":"ج4 ص364","text":"أخبرنا الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني نوفل بن ميمون قال لقي ابن ميادة ابن هرمة فقال ابن ميادة والله لقد كنت أحب أن ألقاك لا بد من أن نتهاجى وقد فعل الناس ذلك قبلنا فقال ابن هرمة بئس والله ما دعوت إليه وأحببته وهو يظنه جادا ثم قال له ابن هرمة أما والله إنني للذي أقول\n(إني لميمون جوارا وإنني ... إذا زجر الطير العدا لمشوم)\n(وإني لملآن العنان مناقل ... إذا ما ونى يوما ألف سؤوم)\n(فود رجال أن أمي تقنعت ... بشيب يغشي الرأس وهي عقيم)\nفقال ابن ميادة وهل عندك جراء ثكلتك أمك أنت ألأم من ذلك ما قلت إلا مازحا أخبرنا به وكيع قال حدثنا محمد بن إسماعيل قال قال عبد العزيز بن عمران\nاجتمع ابن هرمة وابن ميادة عند جميع بن عمر بن الوليد فقال ابن ميادة لابن هرمة قد كنت أحب أن ألقاك ثم ذكر نحوه وقال هارون بن محمد بن عبد الملك حدثنا علي بن محمد بن سليمان النوفلي قال حدثني أبو سلمة الغفاري عن أبيه قال وفدت على المهدي في جماعة من أهل المدينة وكان فيمن وفد يوسف بن موهب وكان في رجال بني هاشم من بني نوفل وكان معنا ابن هرمة فجلسنا يوما على دكان قد هيئ لمسجد ولم يسقف في عسكر المهدي وقد كنا نلقى الوزراء وكبراء السلطان وكانوا قد عرفونا وإذا حيال الدكان رجل بين يديه ناطف يبيعه في يوم شات شديد البرد فأقبل إذا ضربه بفأسه فتطاير جفوفا فأقبل ابن هرمة علينا فقال ليوسف يابن عم رسول الله أما معك درهم نأكل به من هذا الناطف فقال له متى عهدتني أحمل الدراهم قال فقلت له لكني أنا معي فأعطيته درهما خفيفا فاشترى به ناطفا على طبق للناطفي فجاء بشيء كثير فأقبل يتمضغه وحده ويحدثنا ويضحك فما راعنا إلا موكب أحد الوزيرين أبي عبيد الله أو يعقوب بن داود ثم أقبلت المطرقة فقلنا ما لك قاتلك الله يهجم علينا هذا وأصحابه فيرون الناطف بين أيدينا فيظنون أنا كنا نأكل معك قال فوالله ما أحد أولى بالستر على أصحابه وتقلد البلية منك يابن عم الرسول\nالله فضعه بين يديك قال أعزب قبحك الله قال فأنت يا بن أبي ذر فزبرته قال فقال قد علمت أنه لا يبتلى بهذا إلا دعي أدعياء عاض كذا من أمه ثم أخذ الطبق في يده فحمله وتلقى به الموكب فما مر به أحد له نباهة إلا مازحه حتى مضى القوم جميعا","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":1,"spl":"خبره مع رجل من أسلم ضافه — طلب منه ابن ميادة أن يتهاجيا"},
{"id":"b44-5","bab":"الجزء 4","sec":"إكرام عبد الله بن حسن على مدحه له","page":"ج4 ص366","text":"وقال هارون حدثني أبو حذافة السهمي قال حدثنا إسحاق بن نسطاس قال كان ابن هرمة مشتهرا بالنبيذ فأتى عبد الله بن حسن وهو بالسيالة فأنشده مديحا له فقام عبد الله إلى غنم كانت له فرمى بساجة عليها فافترقت فرقتين فقال اختر أيهما شئت قال فإما أن تكون زادت بواحدة أو نقصت بواحدة على الأخرى قال وكانت ثلاثمائة وكتب له إلى المدينة بدنانير فقال له يابن هرمة انقل عيالك إلينا يكونوا مع عيالنا فقال أفعل يابن رسول الله ثم قدم ابن هرمة المدينة وجهز عياله لينقلهم إلى عبد الله بن حسن واكترى من رجل من مزينة فبينا هو قد شد متاعه وحمله والكري ينتظره أن يتحمل إذ أتاه صديق له فقال أي أبا إسحاق عندي والله نبيذ يسقط لحم الوجه فقال ويحك أما ترانا على مثل هذه الحال أعليها يمكن الشراب فقال إنما هي ثلاثة لا تزد عليهن شيئا فمضى معه وهم وقوف ينظرون فلم يزل يشرب حتى مضى من الليل صدر صالح ثم أتي به وهو سكران فطرح في شق\nالمحمل وعادلته امرأته ومضوا فلما أسحروا رفع رأسه فقال أين أنا فأقبلت عليه امرأته تلومه وتعذله وقالت قد أفسد عليك هذا النبيذ دينك ودنياك فلو تعللت عنه بهذه الألبان فرفع رأسه إليها وقال\n(لا نبتغي لبن البعير وعندنا ... ماء الزبيب وناطف المعصار)\nخبرنا محمد بن خلف وكيع قال حدثنا زكريا بن يحيى بن خلاد قال كان الأصمعي يقول ختم الشعراء بابن هرمة والحكم الخضري وابن ميادة وطفيل الكناني ومكين العذري","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":2,"spl":"إكرام عبد الله بن حسن على مدحه له — ولعه بالنبيذ"},
{"id":"b44-6","bab":"الجزء 4","sec":"ولعه بالنبيذ","page":"ج4 ص367","text":"قال هارون بن محمد بن عبد الملك حدثني أبو حذافة السهمي أحمد بن إسماعيل قال كان ابن هرمة مدمنا للشراب مغرما به فأتى أبا عمرو بن أبي راشد مولى عدوان فأكرمه وسقاه أياما ثلاثة فدعا ابن هرمة بالنبيذ فقال له غلام لأبي عمرو بن أبي راشد قد نفد نبيذنا فنزع ابن هرمة رداءه عن ظهره فقال للغلام اذهب به إلى ابن حونك نباذ كان بالمدينة فارهنه عنده وأتنا بنبيذ ففعل وجاء ابن أبي راشد فجعل يشرب معه من ذلك النبيذ فقال له أين رداؤك يا أبا إسحاق فقال نصف في القدح ونصف في بطنك قال هارون حدثني محمد بن عمر بن إسماعيل بن عبد العزيز بن عمر بن عبد الرحمن بن عوف الزهري قال حدثني عمي عبد العزيز بن إسماعيل قال\nمدح ابن هرمة محمد بن عمران الطلحي وبعث إليه بالمديح مع ابن ربيح فاحتجب عنه فمدح محمد بن عبد العزيز وكان ابن هرمة مريضا فقال قصيدته التي يقول فيها\n(إني دعوتك إذ جفيت وشفني ... مرض تضاعفني شديد المشتكى)\n(وحبست عن طلب المعيشة وارتقت ... دوني الجوائج في وعور المرتقى)\n(فأجب أخاك فقد أناف بصوته ... يا ذا الإخاء ويا كريم المرتجى)\n(ولقد حفيت صبيب عكة بيتنا ... ذوبا ومزت بصفوه عنك القذى)\n(فخذ الغنيمة واغتنمني إنني ... غنم لمثلك والمكارم تشترى)\n(لا ترمين بحاجتي وقضائها ... ضرح الحجاب كما رمى بي من رمى)\nركب إلى جعفر بن سليمان نصف النهار فقال ما نزعك يا أبا عبد الله في هذا الوقت قال حاجة لم أر فيها أحدا أكفى مني قال وما هي قال قد مدحني ابن هرمة بهذه الأبيات فأردت من أرزاقي مائة دينار قال ومن عندي مثلها قال ومن الأمير أيضا قال فجاءت المائتا الدينار إلى ابن هرمة فما أنفق منها إلا دينارا واحدا حتى مات وورث الباقي أهله","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":2,"spl":"إكرام عبد الله بن حسن على مدحه له — ولعه بالنبيذ"},
{"id":"b44-7","bab":"الجزء 4","sec":"طلب من أبي جعفر أن يجيز له الشراب","page":"ج4 ص368","text":"وقال أحمد بن أبي خيثمة عن أبي الحسن المدائني قال امتدح ابن هرمة أبا جعفر فوصله بعشرة آلاف درهم فقال لا تقع مني هذه قال ويحك إنها كثيرة قال إن أردت أن تهنئني فأبح لي الشراب\nفإني مغرم به فقال ويحك هذا حد من حدود الله قال احتل لي يا أمير المؤمنين قال نعم فكتب إلى والي المدينة من أتاك بابن هرمة سكران فاضربه مائة واضرب ابن هرمة ثمانين قال فجعل الجلواز إذا مر بابن هرمة سكران قال من يشتري الثمانين بالمائة أخبرني أحمد بن عبد العزيز قال حدثني أبو زيد عمر بن شبة قال حدثنا أبو سلمة الغفاري قال أخبرنا ابن ربيح راوية ابن هرمة قال أصابت ابن هرمة أزمة فقال لي في يوم حار إذهب فتكار حمارين إلى ستة أميال ولم يسم موضعا فركب واحدا وركبت واحدا ثم سرنا حتى صرنا إلى قصور الحسن بن زيد ببطحاء ابن أزهر فدخلنا مسجده فلما مالت الشمس خرج علينا مشتملا على قميصه فقال لمولى له أذن فأذن ولم يكلمنا كلمة ثم قال له أقم فأقام فصلى بنا ثم أقبل على ابن هرمة فقال مرحبا بك يا أبا إسحاق حاجتك قال نعم بأبي أنت وأمي أبيات قلتها وقد كان عبد الله وحسن وإبراهيم بنو حسن بن حسن وعدوه شيئا فأخلفوه فقال هاتها فقال\n(أما بنو هاشم حولي فقد قرعوا ... نبل الضباب التي جمعت في قرن)\n(فما بيثرب منهم من أعاتبه ... إلا عوائد أرجوهن من حسن)\n(الله أعطاك فضلا من عطيته ... على هن وهن فيما مضى وهن)\nقال حاجتك قال لابن أبي مضرس علي خمسون ومائة دينار قال فقال لمولى له يا هيثم اركب هذه البغلة فأتني بابن أبي مضرس وذكر حقه قال فما صلينا العصر حتى جاء به فقال له مرحبا بك يابن أبي مضرس أمعك ذكر\nحقك على ابن هرمة قال نعم قال فامحه فمحاه ثم قال يا هيثم بع ابن أبي مضرس من تمر الخانقين بمائة وخمسين دينارا وزده كل دينار ربع دينار وكل ابن هرمة بخمسين ومائة دينار تمرا وكل ابن ربيح بثلاثين دينار تمرا قال فانصرفنا من عنده فلقيه محمد بن عبد الله بن حسن بالسيالة وقد بلغه الشعر فغضب لأبيه وعمومته فقال أي ماص يظر أمه أنت القائل\n(على هن وهن فيما مضى وهن ... )\nقال لا والله ولكني الذي أقول لك\n(لا والذي أنت منه نعمة سلفت ... نرجو عواقيها في آخر الزمن)\n(لقد أتيت بأمر ما عمدت له ... ولا تعمده قولي ولا سنني)\n(فكيف أمشي مع الأقوام معتدلا ... وقد رميت بريء العود بالأبن)\n(ما غيرت وجهه أم مهجنة ... إذا القتام تغشى أوجه الهجن)\nال وأم الحسن أم ولد قال هارون فحدثني حماد بن إسحاق عن أبيه عن أيوب بن عباية قال لما قال ابن هرمة هذا الشعر في حسن بن زيد قال عبد الله بن حسن والله ما أراد الفاسق غيري وغير أخوي حسن وإبراهيم وكان عبد الله يجري على ابن هرمة رزقا فقطعه عنه وغضب عليه فأتاه يعتذر فنحي وطرد فسأل رجالا أن يكلموه فردهم فيئس من رضاه واجتنبه وخافه فمكث ما شاء الله ثم مر عشية وعبد الله على زربيه في ممر المنبر ولم تكن تبسط لأحد غيره في ذلك المكان\nفلما رأى عبد الله تضاءل وتقنفذ وتصاغر وأسرع المشي فكأن عبد الله رق له فأمر به فرد عليه فقال يا فاسق يا شارب الخمر على هن وهن تفضل الحسن علي وعلى أخوي فقال بأبي أنت وأمي ورب هذا القبر ما عنيت إلا فرعون وهامان وقارون أفتغضب لهم فضحك وقال والله ما أحسبك إلا كاذبا قال والله ما كذبتك فأمر بأن ترد عليه جرايته","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":3,"spl":"طلب من أبي جعفر أن يجيز له الشراب","partial":1},
{"id":"b44-8","bab":"الجزء 4","sec":"قصيدتة الخالية من الحروف المعجمة","page":"ج4 ص371","text":"أخبرني يحيى بن علي إجازة قال أخبرني أبو أيوب المديني عن مصعب قال إنما اعتذر ابن هرمة بهذا إلى محمد بن عبد الله بن حسن قال يحيى وأخبرني أبو أيوب عن علي بن صالح قال أنشدني عامر بن صالح قصيدة لابن هرمة نحوا من أربعين بيتا ليس فيها حرف يعجم وذكر هذه الأبيات منها ولم أجد هذه القصيدة في شعر ابن هرمة ولا كنت أظن أن أحدا تقدم رزينا العروضي إلى هذا الباب وأولها\n(أرسم سودة أمسى دارس الطلل ... معطلا رده الأحوال كالحلل)\nكذا ذكر يحيى بن علي في خبره أن القصيدة نحو من أربعين بيتا ووجدتها في رواية الأصمعي ويعقوب بن السكيت اثنى عشر بيتا فنسختها هاهنا للحاجة\nإلى ذلك وليس فيها حرف يعجم إلا ما اصطلح عليه الكتاب من تصبيرهم مكان ألف ياء مثل أعلى فإنها في اللفظ بالألف وهي تكتب بالياء ومثل رأى ونحو هذا وهو في التحقيق في اللفظ بالألف وإنما اصطلح الكتاب على كتابته بالياء كما ذكرناه والقصيدة\n(أرسم سودة محل دارس الطلل ... معطل رده الأحوال كالحلل)\n(لما رأى أهلها سدوا مطالعها ... رام الصدود وعاد الود كالمهل)\n(وعاد ودك داء لا دواء له ... ولو دعاك طوال الدهر للرحل)\n(ما وصل سودة إلا وصل صارمة ... أحلها الدهر دارا مأكل الوعل)\n(وعاد أمواهها سدما وطار لها ... سهم دعا أهلها للصرم والعلل)\n(صدوا وصد وساء المرء صدهم ... وحام للورد ردها حومة العلل)\nومة الماء كثرته وغمرته والعلل الشرب الثاني والرده مستنقع الماء\n(وحلؤوه رداها ماؤها عسل ... ما ماء رده لعمر الله كالعسل)\n(دعا الحمام حماما سد مسمعه ... لما دعاه رآه طامح الأمل)\n(طموح سارحة حوم ملمعة ... وممرع السر سهل ماكد السهل)\n(وحاولوا رد أمر لا مرد له ... والصرم داء لأهل اللوعة الوصل)\n(أحلك الله أعلى كل مكرمة ... والله أعطاك أعلى صالح العمل)\n(سهل موارده سمح مواعده ... مسود لكرام سادة حمل)","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":4,"spl":"قصيدتة الخالية من الحروف المعجمة — شعره في المسور بن عبد الملك"},
{"id":"b44-9","bab":"الجزء 4","sec":"شعره في المسور بن عبد الملك","page":"ج4 ص373","text":"قال يحيى بن علي وحدثني أبو أيوب المديني عن أبي حذيفة قال كان المسور بن عبد الملك المخزومي يعيب شعر ابن هرمة وكان المسور هذا عالما بالشعر والنسب فقال ابن هرمة فيه\n(إياك لا ألزمن لحييك من لجمي ... نكلا ينكل قراصا من اللجم)\n(يدق لحييك أو تنقاد متبعا ... مشي المقيد ذي القردان والحلم)\n(إني إذا ما امرؤ خفت نعامته ... إلي واستحصدت منه قوى الوذم)\n(عقدت في ملتقى أوداج لبته ... طوق الحمامة لا يبلى على القدم)\n(إني امرؤ لا أصوغ الحلي تعمله ... كفاي لكن لساني صائغ الكلم)\n(إن الأديم الذي أمسيت تقرظه ... جهلا لذو نغل باد وذو حلم)\n(ولا يئط بأيدي الخالقين ولا ... أيدي الخوالق إلا جيد الأدم)\nال يحيى وحدثني أبو أيوب عن مصعب بن عبد الله عن أبيه قال لقيني ابن هرمة فقال لي يابن مصعب أتفضل علي ابن أذينة أما شكرت قولي\n(فما لك مختلا عليك خصاصة ... كأنك لم تنبت ببعض المنابت)\n(كأنك لم تصحب شعيب بن جعفر ... ولا مصعبا ذا المكرمات ابن ثابت)\nعني مصعب بن عبد الله قال فقلت يا أبا إسحاق أقلني وروني من شعرك ما شئت فإني لم أرو لك شيئا فرواني عباسياته تلك","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":4,"spl":"قصيدتة الخالية من الحروف المعجمة — شعره في المسور بن عبد الملك"},
{"id":"b44-10","bab":"الجزء 4","sec":"مدحه لإبراهيم بن عبد الله","page":"ج4 ص374","text":"قال يحيى وأخبرني أبو أيوب المديني عن مصعب بن عبد الله عن مصعب ابن عثمان قال قال ابن هرمة ما رأيت أحدا قط أسخى ولا أكرم من رجلين إبراهيم بن عبد الله بن مطيع وإبراهيم بن طلحة بن عمرو بن عبد الله بن معمر أما إبراهيم بن طلحة فأتيته فقال أحسنوا ضيافة أبي إسحاق فأتيت بكل شيء من الطعام فأردت أن أنشده فقال ليس هذا وقت الشعر ثم أخرج الغلام إلي رقعة فقال أئت بها الوكيل فأتيته بها فقال إن شئت أخذت لك جميع ما كتب به وإن شئت أعطيتك القيمة قلت وما أمر لي به فقال مائتا شاة برعائها وأربعة أجمال وغلام جمال ومظلة وما تحتاج إليه وقوتك وقوت عيالك سنة قلت فأعطني القيمة فأعطاني مائتي دينار وأما إبراهيم بن عبد الله فأتيته في منزله بمشاش على بئر ابن الوليد بن عثمان بن عفان فدخل إلى منزله ثم خرج إلي\nبرزمة من ثياب وصرة من دراهم ودنانير وحلي ثم قال لا والله ما بقينا في منزلنا ثوبا إلا ثوبا نواري به امرأة ولا حليا ولا دينارا ولا درهما وقال يمدح إبراهيم\n(أرقتني تلومني أم بكر ... بعد هدء واللوم قد يؤذيني)\n(حذرتني الزمان ثمت قالت ... ليس هذا الزمان بالمأمون)\n(قلت لما هبت تحذرني الدهر ... دعي اللوم عنك واستبقيني)\n(إن ذا الجود والمكارم إبراهيم ... يعنيه كل ما يعنيني)\n(قد خبرناه في القديم فألفينا ... مواعيده كعين اليقين)\n(قلت ما قلت للذي هو حق ... مستبين لا للذي يعطيني)\n(نضحت أرضنا سماؤك بعد الجدب ... منها وبعد سوء الظنون)\n(فرعينا آثار غيث هراقته ... يدا محكم القوى ميمون)\nقال هارون حدثنا حماد عن عبد الله بن إبراهيم الحجبي أن إبلا لمحمد بن عمران تحمل علفا مرت بمحمد بن عبد العزيز الزهري ومعه ابن هرمة فقال يا أبا إسحاق ألا تستعلف محمد بن عمران وهو يريد أن يعرضه لمنعه فيهجوه فأرسل ابن هرمة في أثر الحمولة رسولا حتى وقف على ابن عمران فأبلغه رسالته فرد إليه الإبل بما عليها وقال إن احتجت إلي غيرها زدناك فأقبل ابن هرمة على محمد بن عبد العزيز فقال له اغسلها عني فإنه إن علم أني استعلفته ولا دابة لي وقعت منه في سوءة قال بماذا قال تعطيني حمارك قال هو لك بسرجه ولجامه فقال ابن هرمة من حفر حفرة سوء وقع فيها","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":5,"spl":"مدحه لإبراهيم بن عبد الله"},
{"id":"b44-11","bab":"الجزء 4","sec":"وفادته على السري بن عبد الله باليمامة ومدحه","page":"ج4 ص376","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا أبو يحيى هارون بن عبد الله الزهري عن ابن زريق وكان منقطعا إلى أبي العباس بن محمد وكان من أروى الناس قال كنت مع السري بن عبد الله باليمامة وكان يتشوق إلى إبراهيم بن علي ابن هرمة ويحب أن يفد عليه فأقول ما يمنعك أن تكتب إليه فيقول أخاف أن يكلفني من المؤونة ما لا أطيق فكنت أكتب بذلك إلى ابن هرمة فكره أن يقدم عليه إلا بكتاب منه ثم غلب فشخص إليه فنزل علي ومعه راويته ابن ربيح فقلت له ما منعك من القدوم على الأمير وهو من الحرص على قدومك على ما كتبت به إليك قال الذي منعه من الكتاب إلي فدخلت على السري فأخبرته بقدومه فسر بذلك وجلس للناس مجلسا عاما ثم أذن لابن هرمة فدخل عليه ومعه راويته ابن ربيح وكان ابن هرمة قصيرا دميما أريمص وكان ابن ربيح طويلا جسيما نقي الثياب فسلم على السري ثم قال له أصلحك الله إني قد قلت شعرا أثنيت فيه عليك فقال إنشد فقال هذا ينشد فجلس فأنشده ابن ربيح قصيدته التي أولها\n(عوجا على ربع ليلى أم محمود ... كيما نسائله من دون عبود)\n(عن أم محمود إذ شط المزار بها ... لعل ذلك يشفي داء معمود)\n(فعرجا بعد تغوير وقد وقفت ... شمس النهار ولاذ الظل بالعود)\n(شيئا فما رجعت أطلال منزلة ... قفر جوابا لمحزون الجوى مودي)\nثم قال فيها يمدح السري\n(ذاك السري الذي لولا تدفقه ... بالعرف متنا حليف المجد والجود)\n(من يعتمدك ابن عبد الله مجتديا ... لسيب عرفك يعمد خير معمود)\n(يابن الأساة الشفاة المستغاث بهم ... والمطعمين ذرى الكوم المقاحيد)\n(والسابقين إلى الخيرات قومهم ... سبق الجياد إلى غاياتها القود)\n(أنت ابن مسلنطح البطحاء منبتكم ... بطحاء مكة لا روس القراديد)\n(لكم سقايتها قدما وندوتها ... قد حازها والد منكم لمولود)\n(لولا رجاؤك لم تعسف بنا قلص ... أجواز مهمهة قفر الصوى بيد)\n(لكن دعاني وميض لاح معترضا ... من نحو أرضك في دهم مناضيد)\nوأنشده أيضا قصيدة مدحه فيها أولها\n(أفي طلل قفر تحمل آهله ... وقفت وماء العين ينهل هامله)\n(تسائل عن سلمى سفاها وقد نأت ... بسلمى نوى شحط فكيف تسائله)\n(وترجو لم ينطق وليس بناطق ... جوابا محيل قد تحمل آهله)\n(ونؤي كخط النون ما إن تبينه ... عفته ذيول من شمال تذايله)\nم قال فيها يمدح السري\n(فقل للسري الواصل البر ذي الندي ... مديحا إذا ما بث صدق قائله)\n(جواد على العلات يهتز للندى ... كما اهتز غضب أخلصته صياقله)\n(نفى الظلم عن أهل اليمامة عدله ... فعاشوا وزاح الظلم عنهم وباطله)\n(وناموا بأمن بعد خوف وشدة ... بسيرة عدل ما تخاف غوائله)\n(وقد علم المعروف أنك خدنه ... ويعلم هذا الجوع أنك قاتله)\n(بك الله أحيا أرض حجر وغيرها ... من الأرض حتى عاش بالبقل آكله)\n(وأنت ترجى للذي أنت أهله ... وتنفع ذا القربى لديك وسائله)\nأنشده أيضا مما مدحه به قوله\n(عوجا نحي الطول بالكثب ... )\nيقول فيها يمدحه\n(دع عنك سلمى وقل محبرة ... لماجد الجد طيب النسب)\n(محض مصفى العروق يحمده ... في العسر واليسر كل مرتغب)\n(الواهب الخيل في أعنتها ... والوصفاء الحسان كالذهب)\n(مجدا وحمدا يفيده كرما ... والحمد في الناس خير مكتسب)\nال فلما فرغ ابن ربيح قال السري لابن هرمة مرحبا بك يا أبا إسحاق ما حاجتك قال جئتك عبدا مملوكا قال لا بل حرا كريما وابن عم فما ذاك قال ما تركت لي مالا إلا رهنته ولا صديقا إلا كلفته قال أبو يحيى يقول لي ابن زريق حتى كأن له ديانا وعليه مالا فقال له السري وما دينك قال سبعمائة دينار قال قد قضاها الله عز و جل عنك قال فأقام أياما ثم قال لي قد اشتقت فقلت له قل شعرا تشوق فيه فقال قصيدته التي يقول فيها\n(أألحمامة في نخل ابن هداج ... هاجت صبابة عاني القلب مهتاج)\n(أم المخبر أن الغيث قد وضعت ... منه العشار تماما غير إخداج)\n(شقت سوائفها بالفرش من ملل ... إلى الأعارف من حزن وأولاج)\n(حتى كأن وجوه الأرض ملبسة ... طرائفا من سدى عصب وديباج)\nهي طويلة مختارة من شعره يقول فيها يمدح السري\n(أما السري فإني سوف أمدحه ... ما المادح الذاكر الإحسان كالهاجي)\n(ذاك الذي هو بعد الله أنقذني ... فلست أنساه إنقاذي وإخراجي)\n(ليث بحجر إذا ما هاجه فزع ... هاج إليه بإلجام وإسراج)\n(لأحبونك مما أصطفي مدحا ... مصاحبات لعمار وحجاج)","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":6,"spl":"وفادته على السري بن عبد الله باليمامة ومدحه","partial":1},
{"id":"b44-12","bab":"الجزء 4","sec":"وفادته على السري بن عبد الله باليمامة ومدحه","page":"ج4 ص376","text":"(أسدى الصنعية من بر ومن لطف ... إلى قروع لباب الملك ولاج)\n(كم من يد لك في الأقوام قد سلفت ... عند امرئ ذي غنى أو عند محتاج)\nفأمر له بسبعمائة دينار في قضاء دينه ومائة دينار يتجهز بها ومائة دينار يعرض بها أهله ومائة دينار إذا قدم على أهله قوله يعرض بها أهله أي يهدي لهم بها هدية والعراضة الهدية قال الفرزدق يهجو هشام بن عبد الملك\n(كانت عراضتك التي عرضتنا ... يوم المدينة زكمة وسعالا)\nخبرني الحرمي قال حدثنا الزبير قال حدثني نوفل بن ميمون قال أخبرني أبو مالك محمد بن علي بن هرمة قال قال ابن هرمة\n(ومهما ألام على حبهم ... فإني أحب بني فاطمه)\n(بنى بنت من جاء بالمحكمات ... والدين والسنة القائمه)\nلقيه بعد ذلك رجل فسأله من قائلها فقال من عض بظر أمه فقال له ابنه يا أبت ألست قائلها قال بلى قال فلم شتمت نفسك قال أليس أن يعض المرء بظر أمه خيرا من أن يأخذه ابن قحطبة","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":7,"spl":"وفادته على السري بن عبد الله باليمامة ومدحه — خبره مع رجل وابنتيه"},
{"id":"b44-13","bab":"الجزء 4","sec":"خبره مع رجل وابنتيه","page":"ج4 ص381","text":"أخبرنا الحرمي قال حدثنا الزبير قال حدثنا جعفر بن مدرك الجعدي قال جاء ابن هرمة إلى رجل كان بسوق النبط معه زوجة له وابنتان كأنهما ظبيتان يقود عليهما بمال فدفعه إليه فكان يشتري لهم طعاما وشرابا فأقام ابن هرمة مع ابنتيه حتى خف ذلك المال وجاء قوم آخرون معهم مال فأخبرهم بمكان ابن هرمة فاستثقلوه وكرهوا أن يعلم بهم فأمر ابنتيه فقالتا له يا أبا إسحاق أما دريت ما الناس فيه قال وما هم فيه قالتا زلزل بالروضة فتغافلهما ثم جاء أبوهما متفازعا فقال أي أبا إسحاق ألا تفزع لما الناس فيه قال وما هم فيه قال زلزل بالروضة قال قد جاءكم الآن إنسان معه مال وقد نفضت ما جئتكم به وثقلت عليه فأردت إدخاله وإخراجي أيزلزل بروضة من رياض الجنة ويترك منزلك وأنت تجمع فيه الرجال على ابنتيك والله لا عدت إليه وخرج من عنده وروى هذا الخبر عن الزبير بن هارون بن محمد الزيات فزاد فيه قال ثم خرج من عندهم فأتى عبد الله بن حسن فقال إني قد مدحتك فاستمع مني قال لا حاجة لي بذلك أنا أعطيك ما تريد ولا أسمع قال إذا أسقط ويكسد\nسوقي فسمع منه وأمر له بمائتي دينار فأخذها وعاد إلى الرجل وقال قد جئتك بما تنفقه كيف شئت ولم يزل عنده حتى نفذت","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":7,"spl":"وفادته على السري بن عبد الله باليمامة ومدحه — خبره مع رجل وابنتيه"},
{"id":"b44-14","bab":"الجزء 4","sec":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران","page":"ج4 ص382","text":"قال الزبير وحدثني عبد الرحمن بن عبد الله بن عبد العزيز قال حدثني عمي عمران بن عبد العزيز بن عمر بن عبد الرحمن بن عوف قال وافينا الحج في عام من الأعوام الخالية فأصبحت بالسيالة فإذا إبراهيم ابن علي بن هرمة يأتينا فاستأذن على أخي محمد بن عبد العزيز فأذن له فدخل عليه فقال يا أبا عبد الله ألا أخبرك ببعض ما تستظرف قال بلى وربما فعلت يا أبا إسحاق قال فإنه أصبح عندنا هاهنا منذ أيام محمد بن عمران وإسماعيل بن عبد الله بن جبير وأصبح ابن عمران بجملين له ظالعين فإذا رسوله يأتيني أن أجب فخرجت حتى أتيته فأخبرني بظلع جمليه وقال لي أردت أن أبعث إلى ناضحين لي بعمق لعلي أوتى بهما إلى هاهنا لأمضي عليهما ويصير هذان الظالعان إلى مكانهما ففرغ لنا دارك واشتر لنا علفا واستلنه بجهدك فإنا مقيمون هاهنا حتى تأتينا جمالنا فقلت في الرحب والقرب والدار فارغة وزوجته طالق إن اشتريت عود علف عندي حاجتك منه فأنزلته ودخلت إلى السوق فما أبقيت فيه شيئا من رسل ولا جداء ولا طرفة ولا غير ذلك\nإلا ابتعت منه فاخره وبعثت به إليه مع دجاج كان عندنا قال فبينا أنا أدور في السوق إذ وقف علي عبد لإسماعيل بن عبد الله يساومني بحمل علف لي فلم أزل أنا وهو حتى أخذه مني بعشرة دراهم وذهب به فطرحه لظهره وخرجت عند الرواح أتقاضى العبد ثمن حملي فإذا هو لإسماعيل ابن عبد الله ولم أكن دريت فلما رآني مولاه حياني ورحب بي وقال هل من حاجة يا أبا إسحاق فأعلمه العبد أن العلف لي فأجلسني فتغديت عنده ثم أمر لي مكان كل درهم منها بدينار وكانت معه زوجته فاطمة بنت عباد فبعثت إلي بخمسة دنانير قال وراحوا وخرجت بالدنانير ففرقتها على غرمائي وقلت عند ابن عمران عوض منها قال فأقام عندي ثلاثا وأتاه جملاه فما فعل بي شيئا فبينا هو يترحل وفي نفسه مني ما لا أدري به إذ كلم غلاما له بشيء فلم يفهم فأقبل علي فقال ما أقدر على إفهامه مع قعودك عندي قد والله آذيتني ومنعتني ما أردت فقمت مغتما بالذي قال حتى إذا كنت على باب الدار لقيني إنسان فسألني هل فعل إليك شيئا فقلت أنا والله بخير إذ تلف مالي وربحت بدني قال وطلع علي وأنا أقولها فشتمني والله يا أبا عبد الله حتى ما أبقى لي وزعم أنه لولا إحرامه لضربني وراح وما أعطاني درهما فقلت\n(يا من يعين على ضيف ألم بنا ... ليس بذي كرم يرجى ولا دين)\n(أقام عندي ثلاثا سنة سلفت ... أغضيت منها على الأقذاء والهون)\n(مسافة البيت عشر غير مشكلة ... وأنت تأتيه في شهر وعشرين)\n(لست تبالي فوات الحج إن نصبت ... ذات الكلال وأسمنت ابن حرقين)\n(تحدث الناس عما فيك من كرم ... هيهات ذاك لضيفان المساكين)\n(أصبحت تخزن ما تحوي وتجمعه ... أبا سليمان من أشلاء قارون)\n(مثل ابن عمران آباء له سلفوا ... يجزون فعل ذوي الإحسان بالدون)\n(ألا تكون كإسماعيل إن له ... رأيا أصيلا وفعلا غير ممنون)\n(أو مثل زوجته فيما ألم بها ... هيهات من أمها ذات النطاقين)\nلما أنشدها قال له محمد بن عبد العزيز نحن نعينك يا أبا إسحاق لقوله يا من يعين قال قد رفعك الله عن العون الذي أريده ما أردت إلا رجلا مثل عبد الله بن خنزيرة وطلحة أطباء الكلبة يمسكونه لي وآخذ خوط سلم فأوجع به خواصره وجواعره قال ولما بغل في إنشاده إلى قوله\n(مثل ابن عمران آباء له سلفوا ... )\nقبل علي فقال عذرا إلى الله تعالى وإليكم إني لم أعن من آبائه طلحة بن عبيد الله قال ونزل إليه إسماعيل بن جعفر بن محمد وكان عندنا فلم يكلمه حتى ضرب أنفه وقال له فعنيت من آبائه أبا سلميان محمد بن طلحة يا دعي قال فدخلنا بينهما وجاء رسول محمد بن طلحة بن عبيد الله بن عبد الرحمن بن أبي بكر الصديق رضي الله عنه إلى ابن هرمة يدعوه فذهب إليه فقال له ما الذي بلغني من هجائك أبا سليمان والله لا أرضى حتى تحلف ألا تقول له أبدا إلا خيرا وحتى تلقاه فترضاه إذا رجع وتحتمل كل ما أزل إليك وتمدحه قال أفعل بالحب والكرامة قال وإسماعيل بن جعفر لا تعرض له إلا بخير قال نعم قال فأخذ عليه الأيمان فيهما وأعطاه ثلاثين دينارا وأعطاه محمد بن عبد العزيز مثلها قال واندفع ابن هرمة يمدح محمد بن عمران\n(ألم تر أن القول يخلص صدقه ... وتأبى فما تزكوا لباغ بواطله)\n(ذممت امرأ لم يطبع الذم عرضه ... قليلا لدى تحصيله من يشاكله)","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":8,"spl":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران","partial":1},
{"id":"b44-15","bab":"الجزء 4","sec":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران","page":"ج4 ص382","text":"(فما بالحجاز من فتى ذي إمارة ... ولا شرف إلا ابن عمران فاضله)\n(فتى لا يطور الذم ساحة بيته ... ونشقى به ليل التمام عواذله)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثنا أحمد بن عمر الزهري قال حدثنا أبو بكر بن عبد الله ابن جعفر المسوري قال مدح إبراهيم بن هرمة محمد بن عمران الطلحي فألفاه راويته وقد جاءته عير له تحمل غلة قد جاءته من الفرع أو خبير فقال له رجل كان عنده أعلم والله أن أبا ثابت بن عمران بن عبد العزيز أغراه بك وأنا حاضر عنده وأخبره بعيرك هذه فقال إنما أراد أبو ثابت أن يعرضني للسانه قودوا إليه القطار فقيد إليه","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":9,"spl":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران — خبر زواجه"},
{"id":"b44-16","bab":"الجزء 4","sec":"كان يعمل من التمر نبيذا","page":"ج4 ص385","text":"أخبرنا الحرمي قال حدثنا الزبير قال حدثني يحيى بن محمد عن عبد الله بن عمرو بن القاسم قال جاء أبي تمر من صدقة عمر فجاءه ابن هرمة فقال أمتع الله بك أعطني من هذا التمر قال يا أبا إسحاق لولا أني أخاف أن تعمل منه نبيذا لأعطيتك قال فإذا علمت أني أعمل منه نبيذا لا تعطيني قال فخافه فأعطاه فلقيه بعد ذلك فقال له ما في الدنيا أجود من نبيذ يجيء من صدقة عمر فأخجله أخبرنا الحرمي قال أخبرنا الزبير قال حدثني عبد الملك بن عبد العزيز\nقال قدم جرير المدينة فأتاه ابن هرمة وابن أذينة فأنشداه فقال جرير القرشي أشعرهما والعربي أفصحهما أخبرنا يحيى بن علي إجازة قال حدثني حماد بن إسحاق عن أبيه قال حدثني عبد الله بن محمد أن ابن هرمة قال يمدح أبا الحكم المطلب بن عبد الله\n(لما رأيت الحادثات كنفنني ... وأورثنني بؤسي ذكرت أبا الحكم)\n(سليل ملوك سبعة قد تتابعوا ... هم المصطفون والمصفون بالكرم)\nلاموه وقالوا أتمدح غلاما حديث السن بمثل هذا قال نعم وكانت له ابنة يلقبها عيينة وقال الزبير كان يلقبها عينة فقال\n(كانت عيينة فينا وهي عاطلة ... بين الجواري فحلاها أبو الحكم)\n(فمن لحانا على حسن المقال له ... كان المليم وكنا نحن لم نلم)\nال يحيى وحدثني حماد بن إسحاق عن أبيه عن الزبيري عن نوفل بن ميمون قال أرسل ابن هرمة إلى عبد العزيز بن المطلب بكتاب يشكو فيه بعض حاله فبعث إليه بخمسة عشر دينارا فمكث شهرا ثم بعث يطلب منه شيئا آخر بعد ذلك فقال إنا والله ما نقوى على ما كان يقوى عليه الحكم بن المطلب وكان عبد العزيز قد خطب إلى امرأة من ولد عمر فردته فخطب إلى امرأة من بني عامر ابن لؤي فزوجوه فقال ابن هرمة\n(خطبت إلى كعب فردوك صاغرا ... فحولت من كعب إلى جذم عامر)\n(وفي عامر عز قديم وإنما ... أجازك فيهم هزل أهل المقابر)\nقال فيه أيضا\n(أبالبخل نطلب ما قدمت ... عرانين جادت بأموالها)\n(فهيهات خالفت فعل الكرام ... خلاف الجمال بأبوالها)","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":9,"spl":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران — خبر زواجه"},
{"id":"b44-17","bab":"الجزء 4","sec":"خبر زواجه","page":"ج4 ص387","text":"وقال هارون بن محمد حدثني مغيرة بن محمد قال حدثني أبو محمد السهمي قال حدثني أبو كاسب قال تزوج ابن هرمة بامرأة فقالت له أعطني شيئا فقال والله ما معي إلا نعلاي فدفعهما إليها ومضى معها فتوركها مرارا فقالت له أجفيتني فقال لها الذي أجفى صاحبه منا يعض بظر أمه أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني المسيبي محمد بن إسحاق قال حدثني إبراهيم بن سكرة جار أبي ضمرة قال جلس ابن هرمة مع قوم على شراب فذكر الحكم بن المطلب فأطنب في مدحه فقالوا له إنك لتكثر ذكر رجل لو طرقته الساعة في شاة يقال لها غراء تسأله إياها لردك عنها فقال أهو يفعل هذا قالوا إي والله وكانوا قد عرفوا أن الحكم بها معجب وكانت في داره سبعون شاة تحلب فخرج وفي رأسه ما فيه فدق الباب فخرج إليه غلامه فقال له أعلم أبا مروان بمكاني وكان قد أمر ألا\nيحجب إبراهيم بن هرمة عنه فأعلمه به فخرج إليه متشحا فقال أفي مثل هذه الساعة يا أبا إسحاق فقال نعم جعلت فداك ولد لأخ لي مولود فلم تدر عليه أمه فطلبوا له شاة حلوبة فلم يجدوها فذكروا له شاة عندك يقال لها غراء فسألني أن أسألكها فقال أتجيء في هذه الساعة ثم تنصرف بشاة واحدة والله لا تبقى في الدار شاة إلا انصرفت بها سقهن معه يا غلام فساقهن فخرج بهن إلى القوم فقالوا ويحك أي شيء صنعت فقص عليهم القصة قال وكان فيهن والله ما ثمنه عشرة دنانير وأكثر من عشرة","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":9,"spl":"أخباره مع محمد بن عبد العزيز ومحمد بن عمران — خبر زواجه"}]);
window.__BOOK__['p02'].push([{"id":"b44-18","bab":"الجزء 4","sec":"مدح الوليد بعد أن قتل","page":"ج4 ص388","text":"قال هارون وحدثني حماد بن إسحاق قال ذكر أبي عن أيوب بن عباية عن عمر بن أيوب الليثي قال شرب ابن هرمة عندنا يوما فسكر فنام فلما حضرت الصلاة تحرك أو حركته فقال لي وهو يتوضأ ما كان حديثكم اليوم قلت يزعمون أن الوليد قتل فرفع رأسه إلي وقال\n(وكانت أمور الناس منبتة القوى ... فشد الوليد حين قام نظامها)\n(خليفة حق لا خليفة باطل ... رمى عن قناة الدين حتى أقامها)\nم قال لي إياك أن تذكر من هذا شيئا فإني لا أدري ما يكون أخبرني علي بن سليمان النحوي قال حدثنا أبو العباس الأحول عن ابن الأعرابي أنه كان يقول ختم الشعراء بأبن هرمة أخبرنا يحيى بن علي بن يحيى قال أخبرني أحمد بن يحيى البلاذري أن ابن هرمة كان مغرما بالنبيذ فمر على جيرانه وهو شديد السكر حتى دخل منزله فلما كان من الغد دخلوا عليه فعاتبوه على الحال التي رأوه عليها فقال\nلهم أنا في طلب مثلها منذ دهر أما سمعتم قولي\n(أسأل الله سكرة قبل موتي ... وصياح الصبيان يا سكران)\nال فنفضوا ثيابهم وخرجوا وقالوا ليس يفلح والله هذا أبدا","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":10,"spl":"مدح الوليد بعد أن قتل — ذكر أخبار يونس الكاتب"},
{"id":"b44-19","bab":"الجزء 4","sec":"موته ودفنه","page":"ج4 ص389","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أنشدني عمي لابن هرمة\n(ما أظن الزمان يا أم عمر ... تاركا إن هلكت من يبكيني)\nال فكان والله كذلك لقد مات فأخبرني من رأى جنازته ما يحملها إلا أربعة نفر حتى دفن بالبقيع قال يحيى بن علي أراه عن البلاذري ولد ابن هرمة سنة تسعين وأنشد أبا جعفر المنصور في سنة أربعين ومائة قصيدته التي يقول فيها\n(إن الغواني قد أعرضن مقلية ... لما رمى هدف الخمسين ميلادي)\nال ثم عمر بعدها مدة طويلة","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":10,"spl":"مدح الوليد بعد أن قتل — ذكر أخبار يونس الكاتب"},
{"id":"b44-20","bab":"الجزء 4","sec":"ذكر أخبار يونس الكاتب","page":"ج4 ص390","text":"هو يونس بن سليمان بن كرد بن شهريار من ولد هرمز وقيل إنه مولى لعمرو بن الزبير ومنشؤه ومنزله بالمدينة وكان أبوه فقيها فأسلمه في الديوان فكان من كتابه وأخذ الغناء عن معبد وابن سريج وابن محرز والغريض وكان أكثر روايته عن معبد ولم يكن في أصحاب معبد أحذق ولا أقوم بما أخذ عنه منه وله غناء حسن وصنعة كثيرة وشعر جيد وكتابه في الأغاني ونسبها إلى من غنى فيها هو الأصل الذي يعمل عليه ويرجع إليه وهو أول من دون الغناء أخبرنا محمد بن خلف وكيع قال حدثنا حماد بن إسحاق قال حدثني أبي قال أنشدني مسعود بن خالد المورياني لنفسه في يونس\n(يا يونس الكاتب يا يونس ... طاب لنا اليوم بك المجلس)\n(إن المغنين إذا ما هم ... جاروك أخنى بهم المقبس)\n(تنشر ديباجا وأشباهه ... وهم إذا ما نشروا كربسوا)\nخبرني الحسين بن يحيى عن حماد عن أبيه قال ذكر إبراهيم بن قدامة الجمحي قال اجتمع فتيان من فتيان أهل المدينة فيهم يونس الكاتب وجماعة ممن يغني\nفخرجوا إلى واد يقال له دومة من بطن العقيق في أصحاب لهم فتغنوا واجتمع إليهم نساء أهل الوادي قال بعض من كان معهم فرأيت حولنا مثل مراح الضأن وأقبل محمد بن عائشة ومعه صاحب له فلما رأى جماعة النساء عندهم حسدهم فالتفت إلى صاحبه فقال أما والله لأفرقن هذه الجماعة فأتى قصرا من قصور العقيق فعلا سطحه وألقى رداءه واتكأ عليه وتغنى صوت\n(هذا مقام مطرد ... هدمت منازله ودوره)\n(رقى عليه عداته ... ظلما فعاقبه أميره)\nلغناء لابن عائشة رمل بالوسطى والشعر لعبيد بن حنين مولى آل زيد بن الخطاب وقيل إنه لعبد الله بن أبي كثير مولى بني مخزوم قال فوالله ما قضى صوته حتى ما بقيت امرأة إلا جلست تحت القصر الذي هو عليه وتفرق عامة أصحابهم فقال يونس وأصحابه هذا عمل ابن عائشة وحسده","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":10,"spl":"مدح الوليد بعد أن قتل — ذكر أخبار يونس الكاتب"},
{"id":"b44-21","bab":"الجزء 4","sec":"ابن عائشة تغنى بشعر لعبد الله بن أبي كثير","page":"ج4 ص391","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا أبو غسان محمد بن يحيى عن أبيه قال تزوج عبد الله بن أبي كثير مولى بني مخزوم بالعراق في ولاية مصعب بن الزبير امرأة من بني عبد بن بغيض بن عامر بن لؤي ففرق مصعب بينهما فخرج حتى قدم على عبد الله بن الزبير بمكة فقال\n(هذا مقام مطرد ... هدمت منازله ودوره)\n(رقت عليه عداته ... كذابا فعاقبه أميره)\n(في أن شربت بجم ماء ... كان حلا لي غديره)\n(فلقد قطعت الخرق بعد ... الخرق معتسفا أسيره)\n(حتى أتيت خليفة الرحمن ... ممهودا سريره)\n(حييته بتحية ... في مجلس حضرت صقوره)\nكتب عبد الله إلى مصعب أن أردد عليه امرأته فإني لا أحرم ما أحل الله عز و جل فردها عليه هذه رواية عمر بن شبة وأخبرني الحسن بن علي عن حماد بن إسحاق عن أبيه عن المدائني عن سحيم بن حفص أن المتزوج بهذه المرأة عبيد بن حنين مولى آل زيد بن الخطاب وأن المفرق بينهما الحارث بن عبد الله بن أبي ربيعة الذي يقال له القباع وذكر باقي الخبر مثل الأول أخبرني عمي قال حدثني طلحة بن عبد الله الطلحي قال حدثني أحمد بن الهيثم قال خرج يونس الكاتب من المدينة إلى الشام في تجارة فبلغ الوليد بن يزيد مكانه فلم يشعر يونس إلا برسله قد دخلوا عليه الخان فقالوا له أجب الأمير والوليد إذا ذاك أمير قال فنهضت معهم حتى أدخلوني على الأمير لا أدري من هو إلا أنه من أحسن الناس وجها وأنبلهم فسلمت عليه فأمرني بالجلوس ثم","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":11,"spl":"ابن عائشة تغنى بشعر لعبد الله بن أبي كثير — دعا بالشراب والجواري فكنا يومنا وليلتنا في أمر"},
{"id":"b44-22","bab":"الجزء 4","sec":"دعا بالشراب والجواري فكنا يومنا وليلتنا في أمر عجيب","page":"ج4 ص392","text":"وغنيته فأعجب بغنائي إلى أن غنيته\n(إن يعش مصعب فنحن بخير ... قد أتانا من عيشنا ما نرجي)\nم تبنهت فقطعت الصوت فقال مالك فأخذت أعتذر من غنائي بشعر في مصعب فضحك وقال إن مصعبا قد مضى وانقطع أثره ولا عداوة بيني وبينه وإنما أريد الغناء فامض الصوت فعدت فيه فغنيته فلم يزل يستعيدنيه حتى أصبح فشرب مصطبحا وهو يستعيدني هذا الصوت ما يتجاوزه حتى مضت ثلاثة أيام ثم قلت له جعلني الله فداء الأمير أنا رجل تاجر خرجت مع تجار وأخاف أن يرتحلوا فيضيع مالي فقال لي أنت تغدوا غدا وشرب باقي ليلته وأمر لي بثلاثة آلاف دينار فحملت إلي وغدوت إلى أصحابي فلما خرجت من عنده سألت عنه فقيل لي هذا الأمير الوليد بن يزيد ولي عهد أمير المؤمنين هشام فلما استخلف بعث إلي فأتيته فلم أزل معه حتى قتل","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":11,"spl":"ابن عائشة تغنى بشعر لعبد الله بن أبي كثير — دعا بالشراب والجواري فكنا يومنا وليلتنا في أمر"},
{"id":"b44-23","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص393","text":"(أقصدت زينب قلبي بعدما ... ذهب الباطل عني والغزل)\n(وعلا المفرق شيب شامل ... واضح في الرأس مني واشتعل)\nلشعر لابن رهيمة المدني والغناء في اللحن المختار لعمر الوادي ثاني ثقيل بالبنصر في مجراها عن إسحاق وفيه ليونس الكاتب لحنان أحدهما خفيف ثقيل أول بالبنصر في مجرى الوسطى عن إسحاق والآخر رمل بالسبابة في مجرى البنصر عنه أيضا وفيه رملان بالوسطى والبنصر أحدها لابن المكي والآخر\nلحكم وقيل إنه لإسحاق من رواية الهشامي ولحن يونس في هذا الشعر من أصواته المعروفة بالزيانب والشعر فيها كله لابن رهيمة في زينب بنت عكرمة ابن عبد الرحمن بن الحارث بن هشام وهي سبعة أحدها قد مضى والآخر صوت\n(أقصدت زينب قلبي ... وسبت عقلي ولبي)\n(تركتني مستهاما ... أستغيث الله ربي)\n(ليس لي ذنب إليها ... فتجازيني بذنبي)\n(ولها عندي ذنوب ... في تنائيها وقربي)\n(غناه يونس رملا ... بالبنصر وفيه لحكم هزج)\nفيف بالسبابة في مجرى البنصر عن إسحاق ومنها صوت\n(وجد الفؤاد بزينبا ... وجدا شديدا متعبا)\n(أصبحت من وجدي بها ... أدعى سقيما مسهبا)\n(وجعلت زينب سترة ... وأتيت أمرا معجبا)\nناه يونس ثقيلا أول مطلقا في مجرى البنصر عن عمرو وإسحاق وهو مما يشك فيه من غناء يونس ولعلية بنت المهدي فيه ثقيل أول آخر لا يشك فيه أنه لها كنت فيه عن رشأ الخادم وذكر أحمد بن عبيد أن فيه من الغناء لحنين هما جميعا من الثقيل الأول ليونس ومن لا يعلم يزعم أن الشعر لها ومنها\nصوت\n(إنما زينب المنى ... وهي الهم والهوى)\n(ذات دل تضني الصحيح ... وتبري من الجوى)\n(لا يغرنك أن دعوت ... فؤادي فما التوى)\n(واحذري هجرة الحبيب ... إذا مل وانزوى)\nناه يونس رملا بالخنصر في مجرى البنصر عن إسحاق ومنها صوت\n(إنما زينب همي ... بأبي تلك وأمي)\n(بأبي زينب لا أكني ... ولكني أسمي)\n(بأبي زينب من قاض ... قضى عمدا بظلمي)\n(بأبي من ليس لي في ... قلبه قيراط رحم)\nناه يونس رملا بالبنصر عن عمرو وله فيه لحن آخر ومنها صوت\n(يا زينب الحسناء يا زينب ... يا أكرم الناس إذا تنسب)\n(تقيك نفسي حادثات الردى ... والأم تفديك معا والأب)\n(هل لك في ود امرىء صادق ... لا يمذق الود ولا يكذب)\n(لا يبتغي في وده محرما ... هيهات أنت العمل الأريب)\nناه يونس ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق ومنها صوت فليت الذي يلحى على زينب المنى ... تعلقه مما لقيت عشير فحسبي به بالعشر مما لقيته ... وذلك فيما قد تراه يسير\nغناه يونس ثاني ثقيل بالوسطى في مجراها عن الهشامي هذه سبعة أصوات قد مضت وهي المعروفة بالزيانب ومن الناس من يجعلها ثمانية ويزيد فيها لحن يونس في\n(تصابيت أم هاجت لك الشوق زينب ... )\nليس هذا منها وإن كان ليونس لحنه فإن شعره لحجية بن المضرب الكندي وقد كتب في موضع آخر وإنما الزيانب في شعر ابن رهيمة ومنهم من يعدها تسعة ويضيف إليها\n(قولا لزينب لو رأيت ... تشوقي لك واشترافي)\nهذا اللحن لحكم والشعر لمحمد بن أبي العباس السفاح في زينب بنت سليمان ابن علي وقد كتب في موضع آخر انقضت أخبار يونس الكاتب","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":12,"spl":"صوت من المائة المختارة","partial":1},
{"id":"b44-24","bab":"الجزء 4","sec":"أخبار ابن رهيمة تشبيبه بزينب بنت عكرمة وأمر هشام بضربه","page":"ج4 ص397","text":"خبرني محمد بن جعفر النحوي قال حدثنا أحمد بن القاسم قال حدثني أبو هفان عن إسحاق قال كان ابن رهيمة يشبب بزينب بنت عكرمة بن عبد الرحمن بن الحارث بن هشام ويغني يونس بشعره فافتضحت بذلك فاستعدى عليه أخوها هشام بن عبد الملك فأمر بضربه خمسمائة سوط وأن يباح دمه إن وجد قد عاد لذكرها وأن يفعل ذلك بكل من غنى في شيء من شعره فهرب هو ويونس فلم يقدر عليهما فلما ولي الوليد بن يزيد ظهرا وقال ابن رهيمة\n(لئن كنت اطردتني ظالما ... لقد كشف الله ما أرهب)\n(ولو نلت مني ما تشتهي ... لقل إذا رضيت زينب)\n(وما شئت فاصنعه بي بعد ذا ... فحبي لزينب لا يذهب)\nفي الأصوات المعروفة بالزيانب يقول أبان بن عبد الحميد اللاحقي\n(أحب من الغناء خفيفه ... إن فاتني الهزج)\n(وأشنأ ضوء برق مثل ... ما أشنأ عفا مزج)\n(وأبغض يوم تنأى والزيانب ... كلها سمج)\n(ويعجبني لإبراهيم ... والأوتار تختلج)\n(أدير مدامة صرفا ... كأن صبيبها ودج)\nغني أبان لحن إبراهيم والشعر لأبان أيضا وهو صوت\n(أدير مدامة صرفا ... كأن صبيبها ودج)\n(فظل تخاله ملكا ... يصرفها ويمتزج)\nلشعر لأبان والغناء لإبراهيم ثاني ثقيل بالخنصر في مجرى الوسطى عن إسحاق وفيه لابن جامع ثاني ثقيل بإطلاق الوتر في مجرى الوسطى عن إسحاق أيضا ومما في غناء يونس من المائة المختارة المذكورة في هذا الكتاب","topic":"ذكر ابن هرمة وأخباره ونسبه","topicNo":44,"sp":13,"spl":"أخبار ابن رهيمة تشبيبه بزينب بنت عكرمة وأمر هشام بضربه"},
{"id":"b45-1","bab":"الجزء 4","sec":"صوت من المائة المختارة","page":"ج4 ص398","text":"(ألا يا لقومي للرقاد المسهد ... وللماء ممنوعا من الحائم الصدي)\n(وللحال بعد الحال يركبها الفتى ... وللحب بعد السلوة المتمرد)\nالشعر لإسماعيل بن يسار النسائي من قصيدة مدح بها عبد الملك بن مروان وذكر يحيى بن علي عن أبيه عن إسحاق أنها للغول بن عبد الله بن صيفي الطائي والصحيح أنها لإسماعيل وأنا أذكر خبره مع عبد الملك بن مروان ومدحه إياه بها ليعلم صحة ذلك والغناء ليونس ولحنه المختار من القدر الأوسط من\nالثقيل الأول مطلق في مجرى البنصر وتمام هذه الأبيات\n(وللمرء لا عمن يحب بمرعو ... ولا لسبيل الرشد يوما بمهتدي)\n(وقد قال أقوام وهم يعذلونه ... لقد طال تعذيب الفؤاد المصيد)","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":0,"spl":"صوت من المائة المختارة — سخريته من رجل يكنى أبا قيس"},
{"id":"b45-2","bab":"الجزء 4","sec":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","page":"ج4 ص400","text":"حدثني عمي قال حدثني أحمد بن أبي خيثمة قال حدثنا مصعب بن عبد الله الزبيري قال كان إسماعيل بن يسار النسائي مولي بني تيم بن مرة تيم قريش وكان منقطعا إلى آل الزبير فلما أفضت الخلافة إلى عبد الملك بن مروان وفد إليه مع عروة بن الزبير ومدحه ومدح الخلفاء من ولده بعده وعاش عمرا طويلا إلى أن أدرك آخر سلطان بني أمية ولم يدرك الدولة العباسية وكان طيبا مليحا مندرا بطالا مليح الشعر وكان كالمنقطع إلى عروة بن الزبير وإنما سمي إسماعيل بن يسار النسائي لأن أباه كان يصنع طعام العرس ويبيعه فيشتريه منه من أراد التعريس من المتجملين وممن لم تبلغ حاله اصطناع ذلك وأخبرني الأسدي قال حدثنا أبو الحسن محمد بن صالح بن النطاح قال إنما سمي إسماعيل بن يسار النسائي لأنه كان يبيع النجد والفرش التي تتخذ للعرائس فقيل له إسماعيل بن يسار النسائي\nوأخبرني محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد عن ابن عائشة أن إسماعيل بن يسار النسائي إنما لقب بذلك لأن أباه كان يكون عنده طعام العرسات مصلحا أبدا فمن طرقه وجده عنده معدا أخبرني علي بن سليمان الأخفش قال حدثنا أحمد بن يحيى ثعلب قال حدثني الزبير بن بكار قال قال مصعب بن عثمان لما خرج عروة بن الزبير إلى الشام يريد الوليد بن عبد الملك أخرج معه إسماعيل بن يسار النسائي وكان منقطعا إلى آل الزبير فعادله فقال عروة ليلة من الليالي لبعض غلمانه انظر كيف ترى المحمل قال أراه معتدلا قال إسماعيل الله أكبر ما اعتدل الحق والباطل قبل الليلة قط فضحك عروة وكان يستخف إسماعيل ويستطيبه","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":0,"spl":"صوت من المائة المختارة — سخريته من رجل يكنى أبا قيس"},
{"id":"b45-3","bab":"الجزء 4","sec":"سخريته من رجل يكنى أبا قيس","page":"ج4 ص401","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن سعيد قال حدثنا الزبير قال حدثني عمي عن أيوب بن عباية المخزومي أن إسماعيل بن يسار كان ينزل في موضع يقال له حديلة وكان له جلساء يتحدثون عنده ففقدهم أياما وسأل عنهم فقيل هم عند رجل يتحدثون إليه طيب الحديث حلو ظريف قدم عليهم يسمى محمدا ويكنى أبا قيس فجاء إسماعيل فوقف عليهم فسمع الرجل القوم يقولون قد جاء صديقنا إسماعيل بن يسار فأقبل عليه فقال له أنت إسماعيل قال نعم قال رحم الله أبويك فإنهما سمياك باسم صادق الوعد وأنت أكذب الناس فقال له إسماعيل ما اسمك\nقال محمد قال أبو من قال أبو قيس قال لا ولكن لا رحم الله أبويك فإنهما سمياك باسم نبي وكنياك بكنية قرد فأفحم الرجل وضحك القوم ولم يعد إلى مجالستهم فعادوا إلى مجالسة إسماعيل أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني عن نمير العذري قال إستأذن إسماعيل بن يسار النسائي على الغمر بن يزيد بن عبد الملك يوما فحجبه ساعة ثم أذن له فدخل يبكي فقال له الغمر مالك يا أبا فائد تبكي قال وكيف لا أبكي وأنا على مروانيتي ومروانية أبي أحجب عنك فجعل الغمر يعتذر إليه وهو يبكي فما سكت حتى وصله الغمر بجملة لها قدر وخرج من عنده فلحقه رجل فقال له أخبرني ويلك يا إسماعيل أي مروانية كانت لك أو لأبيك قال بغضنا إياهم امرأته طالق إن لم يكن يلعن مروان وآله كل يوم مكان التسبيح وإن لم يكن أبوه حضره الموت فقيل له قل لا إله إلا الله فقال لعن الله مروان تقربا بذلك إلى الله تعالى وإبدالا له من التوحيد وإقامة له مقامه","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":0,"spl":"صوت من المائة المختارة — سخريته من رجل يكنى أبا قيس"},
{"id":"b45-4","bab":"الجزء 4","sec":"مفاخرته بالعجم على العرب","page":"ج4 ص402","text":"أخبرني عمي قال حدثني أبو أيوب المديني قال حدثني مصعب قال قال إسماعيل بن يسار النسائي قصيدته التي أولها\n(ما على رسم منزل بالجناب ... لو أبان الغداة رجع الجواب)\n(غيرته الصبا وكل ملث ... دائم الورق مكفهر السحاب)\n(دار هند وهل زماني بهند ... عائد بالهوى وصفو الجناب)\n(كالذي كان والصفاء مصون ... لم تشبه بهجرة واجتناب)\n(ذاك منها إذ أنت كالغصن غض ... وهي رؤد كدمية المحراب)\n(غادة تستبي العقول بعذب ... طيب الطعم بارد الأنياب)\n(وأثيث من فوق لون نقي ... كبياض اللجين في الزرياب)\n(فأقل الملام فيها وأقصر ... لج قلبي من لوعة واكتئاب)\n(صاح أبصرت أو سمعت براع ... رد في الضرع ما قرى في العلاب)\n(انقضت شرتي وأقصر جهلي ... واستراحت عواذلي من عتابي)\nقال فيها يفخر على العرب بالعجم\n(رب خال متوج لي وعم ... ماجد مجتدى كريم النصاب)\n(إنما سمي الفوارس بالفرس ... مضاهاة رفعة الأنساب)\n(فاتركي الفخر يا أمام علينا ... واتركي الجور وانطقي بالصواب)\n(وأسألي إن جهلت عنا وعنكم ... كيف كنا في سالف الأحقاب)\n(إذ تربي بناتنا وتدسون ... سفاها بناتكم في التراب)\nقال رجل من آل كثير بن الصلت إن حاجتنا إلى بناتنا غير حاجتكم فأفحمه يريد أن العجم يربون بناتهم لينكحوهن والعرب لا تفعل ذلك وفي هذه الأبيات غناء نسبته صوت\n(صاح أبصرت أو سمعت براع ... رد في الضرع ما قرى في العلاب)\n(إنقضت شرتي وأقصر جهلي ... واستراحت عواذلي من عتابي)\nلشعر لإسماعيل بن يسار النسائي والغناء لمالك خفيف ثقيل بإطلاق الوتر في مجرى الوسطى وذكر عمرو بن بانة في نسخته الأولى أن فيه للغريض خفيف ثقيل بالبنصر وذكر في نسخته الثانية أنه لابن سريج وذكر الهشامي أن لحن ابن سريج رمل بالوسطى وأن لحن الغريض ثقيل أول","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":1,"spl":"مفاخرته بالعجم على العرب — مدح الوليد بن يزيد فأكرمه"},
{"id":"b45-5","bab":"الجزء 4","sec":"شعوبيته","page":"ج4 ص404","text":"وحدثني بهذا الخبر عمي قال حدثنا أحمد بن أبي خيثمة عن مصعب قال إسماعيل بن يسار يكنى أبا فائد وكان أخواه محمد وإبراهيم شاعرين أيضا وهم من سبي فارس وكان إسماعيل شعوبيا شديد التعصب للعجم وله شعر كثير يفخر فيه بالأعاجم قال فأنشد يوما في مجلس فيه أشعب قوله\n(إذ نربي بناتنا وتدسون ... سفاها بناتكم في التراب)\nقال له أشعب صدقت والله يا أبا فائد أراد القوم بناتهم لغير ما أردتموهن له قال وما ذاك قال دفن القوم بناتهم خوفا من العار وربيتموهن لتنكحوهن قال فضحك القوم حتى استغربوا وخجل إسماعيل حتى لو قدر أن يسيخ في الأرض لفعل","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":1,"spl":"مفاخرته بالعجم على العرب — مدح الوليد بن يزيد فأكرمه"},
{"id":"b45-6","bab":"الجزء 4","sec":"مدح الوليد بن يزيد فأكرمه","page":"ج4 ص405","text":"أخبرني الجوهري قال حدثنا عمر بن شبة قال أخبرني أبو سلمة الغفاري قال أخبرنا أبو عاصم الأسلمي قال بينا ابن يسار النسائي مع الوليد بن يزيد جالس على بركة إذ أشار الوليد إلى مولى له يقال له عبد الصمد فدفع ابن يسار النسائي في البركة بثيابه فأمر به الوليد فأخرج فقال ابن يسار\n(قل لوالي العهد إن لاقيته ... وولي العهد أولى بالرشد)\n(إنه والله لولا أنت لم ... ينج مني سالما عبد الصمد)\n(إنه قد رام مني خطة ... لم يرمها قبله مني أحد)\n(فهو مما رام مني كالذي ... يقنص الدراج من خيس الأسد)\nفبعث إليه الوليد بخلعة سنية وصلة وترضاه وقد روي هذا الخبر لسعيد بن عبد الرحمن بن حسان بن ثابت في قصة أخرى وذكر هذا الشعر له فيه\nأخبرني الحسين بن يحيى قال قال حماد قرأت على أبي حدثني مصعب بن عبد الله قال سمعت إبراهيم بن أبي عبد الله يقول ركب فلان من ولد جعفر بن أبي طالب رحمه الله بإسماعيل بن يسار النسائي حتى أتى به قباء فاستخرج الأحوص فقال له أنشدني قولك\n(ما ضر جيراننا إذ انتجعوا ... لو أنهم قبل بينهم ربعوا)\nأنشده القصيدة فأعجب بها ثم انصرف فقال له إسماعيل بن يسار أما جئت إلا لما أرى قال لا قال فاسمع فأنشده قصيدته التي يقول فيها\n(ما ضر أهلك لو تطوف عاشق ... بفناء بيتك أو ألم فسلما)\nقال والله لو كنت سمعت هذه القصيدة أو علمت أنك قلتها لما أتيته وفي أبيات من هذا الشعر غناء نسبته صوت\n(يا هند ردي الوصل أن يتصرما ... وصلي امرأ كلفا بحبك مغرما)\n(لو تبذلين لنا دلالك مرة ... لم نبغ منك سوى دلالك محرما)\n(منع الزيارة أن أهلك كلهم ... أبدوا لزورك غلظة وتجهما)\n(ما ضر أهلك لو تطوف عاشق ... بفناء بيتك أو ألم فسلما)\nلشعر لإسماعيل بن يسار النسائي والغناء لابن مسجح خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه لإبراهيم الموصلي رمل بالبنصر عن حبش","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":1,"spl":"مفاخرته بالعجم على العرب — مدح الوليد بن يزيد فأكرمه"},
{"id":"b45-7","bab":"الجزء 4","sec":"زبان السواق يبكي بعد أن يسمع شعره","page":"ج4 ص407","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة قال أنشد رجل زبان السواق قول إسماعيل بن يسار\n(ما ضر أهلك لو تطوف عاشق ... بفناء بيتك أو ألم فسلما)\nبكى زبان ثم قال لا شيء والله إلا الضجر وسوء الخلق وضيق الصدر وجعل يبكي ويمسح عينيه أخبرني محمد بن جعفر الصيدلاني النحوي صهر المبرد قال حدثني طلحة ابن عبد الله بن إسحاق الطلحي قال حدثني الزبير بن بكار قال حدثني جعفر بن الحسين المهلبي قال أنشدت زبان السواق قول إسماعيل بن يسار النسائي صوت\n(إن جملا وإن تبينت منها ... نكبا عن مودتي وازورارا)\n(شردت بادكارها النوم عني ... وأطير العزاء مني فطارا)\n(ما على أهلها ولم تأت سوءا ... أن تحيا تحية أو تزارا)\n(يوم أبدوا لي التجهم فيها ... وحموها لجاجة وضرارا)\nقال زبان لا شيء وأبيهم إلا اللحز وقلة المعرفة وضيق العطن فصاح عليه\nأبو المعافى وقال فعلى من ذاك ويلك أعليك أو على أبيك أو أمك فقال له زبان إنما أتيت يا أبا المعافى من نفسك لو كنت تفعل هذا ما اختلفت أنت وابنك فوثب إليه أبو المعافى يرميه بالتراب ويقول له ويحك يا سفيه تحسن الدياثة وزبان يسعى هربا منه الغناء في هذه الأبيات لابن مسجح خفيف ثقيل بالوسطى عن ابن المكي وحماد وذكر الهشامي وحبش أنه لابن محرز وأن لحن ابن مسجح ثاني ثقيل","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":2,"spl":"زبان السواق يبكي بعد أن يسمع شعره — نسبة هذا الصوت"},
{"id":"b45-8","bab":"الجزء 4","sec":"حضر من الحجاز ليمدح الوليد","page":"ج4 ص408","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني إسحاق الموصلي قال غني الوليد بن يزيد في شعر لإسماعيل بن يسار وهو\n(حتى إذا الصبح بدا ضوؤه ... وغارت الجوزاء والمرزم)\n(خرجت والوطء خفي كما ... ينساب من مكمنه الأرقم)\nقال من يقول هذا قالوا رجل من أهل الحجاز يقال له إسماعيل بن يسار النسائي فكتب في إشخاصه إليه فلما دخل عليه استنشده القصيدة التي هذان البيتان منها فأنشده\n(كلثم أنت الهم يا كلثم ... وأنتم دائي الذي أكتم)\n(أكاتم الناس هوى شفني ... وبعض كتمان الهوى أحزم)\n(قد لمتني ظلما بلا ظنة ... وأنت فيما بيننا ألوم)\n(أبدي الذي تخفينه ظاهرا ... أرتد عنه فيك أو أقدم)\n(إما بيأس منك أو مطمع ... يسدى بحسن الود أو يلحم)\n(لا تتركيني هكذا ميتا ... لا أمنح الود ولا أصرم)\n(أوفي بما قلت ولا تندمي ... إن الوفي القول لا يندم)\n(آية ما جئت على رقبة ... بعد الكرى والحي قد نوموا)\n(أخافت المشي حذار العدا ... والليل داج حالك مظلم)\n(ودون ما حاولت إذ زرتكم ... أخوك والخال معا والعم)\n(وليس إلا الله لي صاحب ... إليكم والصارم اللهذم)\n(حتى دخلت البيت فاستذرفت ... من شفق عيناك لي تسجم)\n(ثم انجلى الحزن وروعاته ... وغيب الكاشح والمبرم)\n(فبت فيما شئت من نعمة ... يمنحنيها نحرها والفم)\n(حتى إذا الصبح بدا ضوؤه ... وغارت الجوزاء والمرزم)\n(خرجت والوطء خفي كما ... ينساب من مكمنه الأرقم)\nال فطرب الوليد حتى نزل عن فرشه وسريره وأمر المغنين فغنوه الصوت وشرب عليه أقداحا وأمر لإسماعيل بكسوة وجائزة سنية وسرحه إلى المدينة","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":2,"spl":"زبان السواق يبكي بعد أن يسمع شعره — نسبة هذا الصوت"},
{"id":"b45-9","bab":"الجزء 4","sec":"نسبة هذا الصوت","page":"ج4 ص408","text":"الشعر لإسماعيل بن يسار النسائي والغناء لابن سريج رمل","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":2,"spl":"زبان السواق يبكي بعد أن يسمع شعره — نسبة هذا الصوت"},
{"id":"b45-10","bab":"الجزء 4","sec":"شيخ يسمع شعره بصوت جارية فيلقي بنفسه في الفرات إعجابا به","page":"ج4 ص409","text":"حدثنا أحمد بن عبيد الله بن عمار قال حدثنا عمر بن شبة قال حدثنا إسحاق الموصلي قال حدثنا محمد بن كناسة قال\nاصطحب شيخ وشباب في سفينة من الكوفة فقال بعض الشباب للشيخ إن معنا قينة لنا ونحن نجلك ونحب أن نسمع غناءها قال الله المستعان فأنا أرقى على الأطلال وشأنكم فغنت\n(حتى إذا الصبح بدا ضوؤه ... وغارت الجوزاء والمرزم)\n(أقبلت والوطء خفي كما ... ينساب من مكمنه الأرقم)\nال فألقى الشيخ بنفسه في الفرات وجعل يخبط بيديه ويقول أنا الأرقم أنا الأرقم فأدركوه وقد كاد يغرق فقالوا ما صنعت بنفسك فقال إني والله أعلم من معاني الشعر ما لا تعلمون أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو مسلم المستملي عن المدائني قال مدح إسماعيل بن يسار النسائي رجلا من أهل المدينة يقال له عبد الله بن أنس وكان قد اتصل ببني مروان وأصاب منهم خيرا وكان إسماعيل صديقا له فرحل إلى دمشق إليه فأنشده مديحا له ومت إليه بالجوار والصداقة فلم يعطه شيئا فقال يهجوه\n(لعمرك ما إلى حسن رحلنا ... ولا زرنا حسينا يابن أنس)\nعني الحسن والحسين رضي الله عنهما\n(ولا عبدا لعبدهما فنحظى ... بحسن الحظ منهم غير بخس)\n(ولكن ضب جندلة أتينا ... مضبا في مكامنه يفسي)\n(فلما أن أتيناه وقلنا ... بحاجتنا تلون لون ورس)\n(وأعرض غير منبلج لعرف ... وظل مقرطبا ضرسا بضرس)\n(فقلت لأهله أبه كزاز ... وقلت لصاحبي أتراه يمسي)\n(فكان الغنم أن قمنا جميعا ... مخافة أن نزن بقتل نفس)","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":3,"spl":"شيخ يسمع شعره بصوت جارية فيلقي بنفسه في الفرات إعجابا به — رثاؤه لمحمد بن عروة"},
{"id":"b45-11","bab":"الجزء 4","sec":"رثاؤه لمحمد بن عروة","page":"ج4 ص411","text":"حدثني عمي قال حدثنا أحمد بن زهير قال حدثنا مصعب بن عبد الله قال وفد عروة بن الزبير إلى الوليد بن عبد الملك وأخرج معه إسماعيل بن يسار النسائي فمات في تلك الوفادة محمد بن عروة بن الزبير وكان مطلعا على دواب الوليد بن عبد الملك فسقط من فوق السطح بينها فجعلت ترمحه حتى قطعته كان جميل الوجه جوادا فقال إسماعيل بن يسار يرثيه\n(صلى الإله على فتى فارقته ... بالشام في جدث الطوي الملحد)\n(بوأته بيدي دار إقامة ... نائي المحلة عن مزار العود)\n(وغبرت أعوله وقد أسملته ... لصفا الأماعز والصفيح المسند)\n(متخشعا للدهر ألبس حلة ... في النائبات بحسرة وتجلد)\n(أعني ابن عروة إنه قد هدني ... فقد ابن عروة هدة لم تقصد)\n(فإذا ذهبت إلى العزاء أرومه ... ليرى المكاشح بالعزاء تجلدي)\n(منع التعزي أنني لفراقه ... لبس العدو علي جلد الأربد)\n(ونأى الصديق فلا صديق أعده ... لدفاع نائبة الزمان المفسد)\n(فلئن تركتك يا محمد ثاويا ... لبما تروح مع الكرام وتغتدي)\n(كان الذي يزع العدو بدفعه ... ويرد نخوة ذي المراح الأصيد)\n(فمضى لوجهته وكل معمر ... يوما سيدركه حمام الموعد)","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":3,"spl":"شيخ يسمع شعره بصوت جارية فيلقي بنفسه في الفرات إعجابا به — رثاؤه لمحمد بن عروة"},
{"id":"b45-12","bab":"الجزء 4","sec":"مدح عبد الملك بن مروان بعد مقتل ابن الزبير","page":"ج4 ص412","text":"حدثني عمي قال حدثني أحمد بن أبي خيثمة قال حدثنا مصعب بن عبد الله عن أبيه أن إسماعيل بن يسار دخل على عبد الملك بن مروان لما أفضى إليه الأمر بعد مقتل عبد الله بن الزبير فسلم ووقف موقف المنشد واستأذن في الإنشاد فقال له عبد الملك الآن يابن يسار إنما أنت امرؤ زبيري فبأي لسان تنشد فقال له يا أمير المؤمنين أنا أصغر شأنا من ذلك وقد صفحت عن أعظم جرما وأكثر غناء لأعدائك مني وإنما أنا شاعر مضحك فتبسم عبد الملك وأومأ إليه الوليد بأن ينشد فابتدأ فأنشد قوله\n(ألا يا لقومي للرقاد المسهد ... وللماء ممنوعا من الحائم الصدي)\n(وللحال بعد الحال يركبها الفتى ... وللحب بعد السلوة المتمرد)\n(وللمرء يلحى في التصابي وقبله ... صبا بالغواني كل قرم ممجد)\n(وكيف تناسي القلب سلمى وحبها ... كجمر غضى بين الشراسيف موقد)\nتى انتهى إلى قوله\n(إليك إمام الناس من بطن يثرب ... ونعم أخو ذي الحاجة المتعمد)\n(رحلنا لأن الجود منك خليقة ... وأنك لم يذمم جنابك مجتدي)\n(ملكت فزدت الناس ما لم يزدهم ... إمام من المعروف غير المصرد)\n(وقمت فلم تنقض قضاء خليفة ... ولكن بما ساروا من الفعل تقتدي)\n(ولما وليت الملك ضاربت دونه ... وأسندته لا تأتلي خير مسند)\n(جعلت هشاما والوليد ذخيرة ... وليين للعهد الوثيق المؤكد)\nقال فنظر إليهما عبد الملك متبسما والتفت إلى سلميان فقال أخرجك إسماعيل من هذا الأمر فقطب سليمان ونظر إلى إسماعيل نظر مغضب فقال إسماعيل يا أمير المؤمنين إنما وزن الشعر أخرجه من البيت الأول وقد قلت بعده\n(وأمضيت عزما في سليمان راشدا ... ومن يعتصم بالله مثلك يرشد)\nأمر له بألفي درهم صلة وزاد في عطائه وفرض له وقال لولده أعطوه فأعطوه ثلاثة آلاف درهم","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":4,"spl":"مدح عبد الملك بن مروان بعد مقتل ابن الزبير — هشام بن عبد الملك يلقي به في بركة ماء بعد أن "},
{"id":"b45-13","bab":"الجزء 4","sec":"هشام بن عبد الملك يلقي به في بركة ماء بعد أن أنشده قصيدته التي يفتخر","page":"ج4 ص413","text":"فيها بالعجم\nأخبرني عمي قال حدثنا أحمد بن أبي خيثمة قال ذكر ابن النطاح عن أبي اليقظان\nأن إسماعيل بن يسار دخل على هشام بن عبد الملك في خلافته وهو بالرصافة جالس على بركة له في قصره فاستنشده وهو يرى أنه ينشده مديحا له فأنشده قصيدته التي يفتخر فيها بالعجم\n(يا ربع رامة بالعلياء من ريم ... هل ترجعن إذا حييت تسليمي)\n(ما بال حي غدت بزل المطي بهم ... تخدي لغربتهم سيرا بتقحيم)\n(كأنني يوم ساروا شارب سلبت ... فؤاده قهوة من خمر داروم)\nتى انتهى إلى قوله\n(إني وجدك ما عودي بذي خور ... عند الحفاظ ولا حوضي بمهدوم)\n(أصلي كريم ومجدي لا يقاس به ... ولي لسان كحد السيف مسموم)\n(أحمي به مجد أقوام ذوي حسب ... من كل قرم بتاج الملك معموم)\n(جحاجح سادة بلج مرازبة ... جرد عتاق مساميح مطاعيم)\n(من مثل كسرى وسابور الجنود معا ... والهرمزان لفخر أو لتعظيم)\n(أسد الكتائب يوم الروع إن زحفوا ... وهم أذلوا ملوك الترك والروم)\n(يمشون في حلق المادي سابغة ... مشي الضراغمة الأسد اللهاميم)\n(هناك إن تسألي تنبي بأن لنا ... جرثومة قهرت عز الجراثيم)\nال فغضب هشام وقال له يا عاض بظر أمه أعلي تفخر وإياي تنشد قصيدة تمدح بها نفسك وأعلاج قومك غطوه في الماء فغطوه في البركة حتى كادت نفسه تخرج ثم أمر بإخراجه وهو بشر ونفاه من وقته فأخرج عن الرصافة منفيا إلى الحجاز قال وكان مبتلى بالعصبية للعجم والفخر بهم فكان لا يزال مضروبا محروما مطرودا","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":4,"spl":"مدح عبد الملك بن مروان بعد مقتل ابن الزبير — هشام بن عبد الملك يلقي به في بركة ماء بعد أن "},
{"id":"b45-14","bab":"الجزء 4","sec":"مدح ابني يزيد فأكرماه","page":"ج4 ص415","text":"أخبرني عمي قال حدثني أحمد بن أبي خيثمة قال قال ابن النطاح وحدثني أبو اليقظان أن إسماعيل بن يسار وفد إلى الوليد بن يزيد وقد أسن وضعف فتوسل إليه بأخيه الغمر ومدحه بقوله\n(نأتك سليمى فالهوى متشاجر ... وفي نأيها للقلب داء مخامر)\n(نأتك وهام القلب نأيا بذكرها ... ولج كما لج الخليع المقامر)\n(بواضحة الأقراب خفاقة الحشى ... برهرهة لا يجتويها المعاشر)\nيقول فيها يمدح الغمر بن يزيد\n(إذا عدد الناس المكارم والعلا ... فلا يفخرن يوما على الغمر فاخر)\n(فما مر من يوم على الدهر واحد ... على الغمر إلا وهو في الناس غامر)\n(تراهم خشوعا حين يبدو مهابة ... كما خشعت يوما لكسرى الأساور)\n(أغز بطاحي كأن جبينه ... إذا ما بدا بدر إذا لاح باهر)\n(وقى عرضه بالمال فالمال جنة ... له وأهات المال والعرض وافر)\n(وفى سيبه للمجتدين عمارة ... وفي سيفه للدين عز وناصر)\n(نماه إلى فرعي لؤي بن غالب ... أبوه أبو العاصي وحرب وعامر)\n(وخمسة آباء له قد تتابعوا ... خلائف عدل ملكهم متواتر)\n(بهاليل سباقون في كل غاية ... إذا استبقت في المكرمات المعاشر)\n(هم خير من بين الحجون إلى الصفا ... إلى حيث أفضت بالبطاح الحزاور)\n(وهم جمعوا هذه الأنام على الهدى ... وقد فرقت بين الأنام البصائر)\nال فأعطاه الغمر ثلاثة آلاف درهم وأخذ له من أخيه الوليد ثلاثة آلاف درهم أخبرني عمي قال حدثنا أحمد بن أبي حيثمة عن مصعب قال لما مات محمد بن يسار وكانت وفاته قبل أخيه دخل إسماعيل على هشام ابن عروة فجلس عنده وحدثه بمصيبته ووفاة أخيه ثم أنشده يرثيه\n(عيل العزاء وخانني صبري ... لما نعى الناعي أبا بكر)\n(ورأيت ريب الدهر أفردني ... منه وأسلم للعدا ظهري)\n(من طيب الأثواب مقتبل ... حلو الشمائل ماجد غمر)\n(فمضى لوجهته وأدركه ... قدر أتيح له من القدر)\n(وغبرت مالي من تذكره ... إلا الأسى وحرارة الصدر)\n(وخوى يعاودني وقل له ... مني الجوى ومحاسن الذكر)\n(لما هوت أيدي الرجال به ... في قعر ذات جوانب غبر)\n(وعلمت أني لن ألاقيه ... في الناس حتى ملتقى الحشر)\n(كادت لفرقته وما ظلمت ... نفسي تموت على شفا القبر)\n(ولعمر من حبس الهدي له ... بالأخشبين صبيحة النحر)\n(لو كان نيل الخلد يدركه ... بشر بطيب الخيم والنجر)\n(لغبرت لا تخشى المنون ولا ... أودى بنفسك حادث الدهر)\n(ولنعم مأوى المرملين إذا ... قحطوا وأخلف صائب القطر)\n(كم قلت آونة وقد ذرفت ... عيني فماء شؤونها يجري)\n(أني وأي فتى يكون لنا ... شرواك عند تفاقم الأمر)\n(لدفاع خصم ذي مشاغبة ... ولعائل ترب أخي فقر)\n(ولقد علمت وإن ضمنت جوى ... مما أجن كواهج الجمر)\n(ما لامرئ دون المنية من ... نفق فيحرزه ولا ستر)\nال وكان بحضرة هشام رجل من آل الزبير فقال له أحسنت وأسرفت في القول فلو قلت هذا في رجل من سادات قريش لكان كثيرا فزجره هشام وقال بئس والله ما واجهت به جليسك فكشره إسماعيل وجزاه خيرا فلما انصرف تناول هشام الرجل الزبيري وقال ما أردت إلى رجل شاعر ملك قوله فصرف أحسنه إلى أخيه ما زدت على أن أغريته بعرضك وأعراضنا لولا أني تلافيته وكان محمد بن يسار أخو إسماعيل هذا الذي رثاه شاعرا من طبقة أخيه وله أشعار كثيرة ولم أجد له خبرا فأذكره ولكن له أشعار كثيرة يغنى فيها منها قوله في قصيدة طويلة صوت\n(غشيت الدار بالسند ... دوين الشعب من أحد)\n(عفت بعدي وغيرها ... تقادم سالف الأبد)\nلغناء لحكم الوادي خفيف ثقيل عن الهشامي ولإسماعيل بن يسار ابن يقال له إبراهيم شاعر أيضا وهو القائل\n(مضى الجهل عنك إلى طيته ... وآبك حلمك من غيبته)\n(وأصبحت تعجب مما رأيت ... من نقض دهر ومن مرته)\nوهي طويلة يفتخر فيها بالعجم كرهت الإطال بذكرها انقضت أخباره\n(كليب لعمري كان أكثر ناصرا ... وأيسر جرما منك ضرج بالدم)\n(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المنمنم)\nروضه من الطويل الشعر للنابغة الجعدي والغناء للهذلي في اللحن المختار وطريقته من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق ونذكر هاهنا سائر ما يغنى به في هذه الأبيات وغيرها من هذه القصيدة وننسبه إلى صانعه ثم نأتي بعده بما يتبعه من أخباره فمنها على الولاء سوى لحن الهذلي\n(كليب لعمري كان أكثر ناصرا ... وأيسر جرما منك ضرج بالدم)","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":5,"spl":"مدح ابني يزيد فأكرماه"},
{"id":"b45-15","bab":"الجزء 4","sec":"مدح ابني يزيد فأكرماه","page":"ج4 ص415","text":"(رمى ضرع ناب فاستمر بطعنة ... كحاشية البرد اليماني المسهم)\n(أيا دار سلمى بالحرورية اسلمي ... إلى جانب الصمان فالمتثلم)\n(أقامت به البردين ثم تذكرت ... منازلها بين الدخول فجرثم)\n(ومسكنها بين الغروب إلى اللوى ... إلى شعب ترعى بهن فعيهم)\n(ليالي تصطاد الرجال بفاحم ... وأبيض كالإغريض لم يتثلم)\nفي البيت الأول والثاني لابن سريج ثقيل أول آخر بإطلاق الوتر في مجرى الوسطى عن إسحاق ويونس وفيهما لمالك خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق وللغريض في الثالث والرابع والأول والثاني ثقيل أول بالسبابة في مجرى الوسطى ولإسحاق في الثالث والأول ثقيل أول بالوسطى ذكر ذلك أبو العبيس والهشامي وللغريض في الرابع ثم الأول خفيف ثقيل بالوسطى في رواية عمرو ابن بانة ولمعبد فيهما وفي الخامس والسادس خفيف ثقيل من رواية أحمد بن المكي ولابن سريج في الخامس والسادس ثقيل أول بالبنصر من رواية علي بن يحيى المنجم وذكر غيره أنه للغريض ولإبراهيم ثقيل أول بالوسطى عن الهشامي وذكر حبش أنه لمعبد ولابن محرز في الأول والثاني والثالث والرابع هزج ذكر ذلك أبو العبيس وذكر قمري أنه لأبي عيسى بن المتوكل لا يشك فيه وللدلال في الخامس والسادس ثاني ثقيل عن الهشامي وذكر أبو العبيس أنه للهذلي ولعبيد الله بن عبد الله بن طاهر في الرابع خفيف رمل ولإسحاق في الثالث والرابع أيضا ماخوري ولمعبد خفيف ثقيل أول بالوسطى فيهما وقيل إنه لحنه الذي ذكرنا متقدما وإنه ليس في هذا الشعر غيره وذكر حبش أن في هذه الأبيات التي أولها كليب لعمري خفيف رمل بالوسطى وللهذلي خفيف ثقيل بالبنصر وللدلال رمل فذلك ثمانية عشر صوتا وأخبرني محمد بن إبراهيم قريص أن له فيهما أعني الأول والثاني خفيفا بالوسطى\nحذف 5\nبسم الله الرحمن الرحيم","topic":"أخبار إسماعيل بن يسار ونسبه ولاؤه وسبب تلقيبه بالنسائي","topicNo":45,"sp":6,"spl":"مدح ابني يزيد فأكرماه"}]);